--- 获取某页总星数
function GetPageStars(page)
    local startIdx = (page - 1) * STAGE_PAGE_SIZE + 1
    local endIdx = math.min(page * STAGE_PAGE_SIZE, #STAGES)
    local total = 0
    for i = startIdx, endIdx do
        total = total + (stageStars[tostring(i)] or 0)
    end
    return total
end

