-- 聊天屏蔽词过滤
local CHAT_BANNED_WORDS = {
    "傻逼", "操你", "妈的", "他妈", "草泥马", "狗日", "王八蛋",
    "滚蛋", "去死", "废物", "垃圾", "白痴", "弱智", "脑残",
    "智障", "猪头", "蠢货", "混蛋", "畜生", "贱人", "婊子",
    "尼玛", "卧槽", "艹", "TMD", "tmd", "NMSL", "nmsl",
    "CNM", "cnm", "SB", "sb", "MB", "mb",
}
local function FilterBannedWords(text)
    if not text or #text == 0 then return text end
    local result = text
    for _, word in ipairs(CHAT_BANNED_WORDS) do
        local stars = string.rep("*", utf8.len(word) or #word)
        result = string.gsub(result, word, stars)
    end
    return result
end

