-- ============================================================================
-- 兵甲界面 - 正式UI系统 (EquipUI)
-- ============================================================================
-- EquipUI 表在 EquipUI.lua 模块中定义

-- 计算装备总加成 (百分比, 含品质加成)
function GetEquipmentBonus()
    local bonus = {
        atkPct = 0, defPct = 0, hpPct = 0,
        -- 额外词条 (来自套装效果)
        critRate = 0, dmgReduction = 0, speedPct = 0,
        atkSpeedPct = 0, counterRate = 0, breakDmgPct = 0,
        deathExplosionPct = 0,
    }
    local setCounts = {}
    for slotIdx = 1, 7 do
        local eq = GetEquippedItem(slotIdx)
        if eq then
            local piece = EQUIPMENT_SETS[eq.setIdx].pieces[slotIdx]
            local tierMul = EQUIP_TIERS[eq.tier or 1].multiplier
            -- 强化等级加成: 每级+5%
            local enhMul = 1.0 + (eq.enhanceLv or 0) * ENHANCE_PERCENT_PER_LEVEL / 100
            -- 品质加成: quality(0~100) → 0%~1% 额外加到基础属性上
            local qBonus = GetQualityBonus(eq.quality)
            -- 装备等级加成: 每级+0.3%基础属性
            local lvBonus = GetLevelBonus(eq.level)
            bonus.atkPct = bonus.atkPct + (piece.atkPct + qBonus + lvBonus) * tierMul * enhMul
            bonus.defPct = bonus.defPct + (piece.defPct + qBonus + lvBonus) * tierMul * enhMul
            bonus.hpPct  = bonus.hpPct  + (piece.hpPct + qBonus + lvBonus) * tierMul * enhMul
            setCounts[eq.setIdx] = (setCounts[eq.setIdx] or 0) + 1
        end
    end
    -- 额外词条key列表
    local extraKeys = { "critRate", "dmgReduction", "speedPct", "atkSpeedPct", "counterRate", "breakDmgPct", "deathExplosionPct" }
    -- 多阶套装奖励 (3件/4件/7件 逐级叠加最高档)
    -- ★ 套装属性按参与件中最差等阶的 multiplier 来折算比例
    --   比例 = minTierMultiplier / maxTierMultiplier(帝品3.2)
    --   全帝品才给 100%, 混搭凡品则只给 1.0/3.2 ≈ 31%
    local maxTierMul = EQUIP_TIERS[#EQUIP_TIERS].multiplier  -- 帝品 3.2
    for setIdx, count in pairs(setCounts) do
        local setData = EQUIPMENT_SETS[setIdx]
        local sb = nil
        if count >= 7 and setData.setBonus then
            sb = setData.setBonus
        elseif count >= 4 and setData.setBonus4 then
            sb = setData.setBonus4
        elseif count >= 3 and setData.setBonus3 then
            sb = setData.setBonus3
        end
        if sb then
            -- 找出该套装中所有已装备件的最差等阶
            local minMul = maxTierMul
            for slotIdx2 = 1, 7 do
                local eq2 = GetEquippedItem(slotIdx2)
                if eq2 and eq2.setIdx == setIdx then
                    local tierMul2 = EQUIP_TIERS[eq2.tier or 1].multiplier
                    if tierMul2 < minMul then minMul = tierMul2 end
                end
            end
            local setRatio = minMul / maxTierMul  -- 0.31 ~ 1.0
            bonus.atkPct = bonus.atkPct + sb.atkPct * setRatio
            bonus.defPct = bonus.defPct + sb.defPct * setRatio
            bonus.hpPct  = bonus.hpPct  + sb.hpPct * setRatio
            -- 累加额外词条 (同样按比例)
            for _, ek in ipairs(extraKeys) do
                if sb[ek] then
                    bonus[ek] = bonus[ek] + sb[ek] * setRatio
                end
            end
        end
    end
    return bonus
end

-- ============================================================================
-- 评分系统 + 红点检测
-- ============================================================================

-- 装备评分: 基础属性和 × 品阶倍率 (含品质加成)
function GetEquipScore(setIdx, slotIdx, tier, enhanceLv, quality)
    local piece = EQUIPMENT_SETS[setIdx].pieces[slotIdx]
    local mul = EQUIP_TIERS[tier].multiplier
    local enhMul = 1.0 + (enhanceLv or 0) * ENHANCE_PERCENT_PER_LEVEL / 100
    local qBonus = GetQualityBonus(quality)
    return math.ceil((piece.atkPct + piece.defPct + piece.hpPct + qBonus * 3) * mul * enhMul)
end

-- 武技评分: 基于阶级战斗伤害值 × 层数加成 (每层+20%)
function GetSkillScore(skillIdx)
    local tech = SKILL_TECHNIQUES[skillIdx]
    if not tech then return 0 end
    local baseDmg = TIER_BATTLE_STATS[tech.tier].damage
    local layer = skillLayers[skillIdx] or 1
    return math.floor(baseDmg * (1 + (layer - 1) * 0.2))
end

-- 获取某装备槽当前已装备的评分（含强化等级和品质）
function GetEquippedSlotScore(slotIdx)
    local eq = GetEquippedItem(slotIdx)
    if not eq then return 0 end
    return GetEquipScore(eq.setIdx, slotIdx, eq.tier, eq.enhanceLv, eq.quality)
end

-- 获取某装备槽拥有的最佳评分
function GetBestOwnedScoreForSlot(slotIdx)
    local best = 0
    for _, item in ipairs(playerEquipment.owned) do
        if item.slotIdx == slotIdx then
            local score = GetEquipScore(item.setIdx, slotIdx, item.tier, item.enhanceLv, item.quality)
            if score > best then best = score end
        end
    end
    return best
end

-- 玩家总评分 (已装备兵甲 + 已装备武技)
function GetPlayerTotalScore()
    local score = 0
    for slotIdx = 1, 7 do
        score = score + GetEquippedSlotScore(slotIdx)
    end
    for _, skillIdx in ipairs(playerEquippedSkills) do
        score = score + GetSkillScore(skillIdx)
    end
    return score
end

-- ============================================================================
-- 战力评分系统 (纯局外统一公式)
-- ============================================================================
-- 战力 = 装备评分 + 最高4武灵评分 + 武技分
-- 所有分数只看局外持久化数据，不涉及战斗状态

--- 武灵评分: 基础属性综合 × 命格 × 等级成长
--- 公式: (atk*2 + def + hp*0.1) × levelMult
function CalcHeroPowerScore(card)
    local lm = 1 + ((card.level or 1) - 1) * GameConfig.LEVEL_GROWTH_RATE
    local cStats = ApplyConstellationStats(card)
    local atk, def, hp = cStats.atk, cStats.def, cStats.hp
    -- 兵符加成
    if card.cardIdx then
        local sb = GetSealTotalBonus(card.cardIdx)
        atk = math.floor(atk * (1 + sb.atkPct / 100))
        def = math.floor(def * (1 + sb.defPct / 100))
        hp  = math.floor(hp  * (1 + sb.hpPct  / 100))
    end
    local power = (atk * 2 + def + hp * 0.1) * lm
    return math.floor(power)
end

--- 境界显示名: "新生三级" 格式
function GetRankDisplayName(rankIdx)
    rankIdx = rankIdx or playerInfo.rankIdx or 1
    local layers = GameConfig.REALM_LAYERS or 10
    local realmIdx = math.ceil(rankIdx / layers)
    local layerIdx = ((rankIdx - 1) % layers) + 1
    local realmName = GameConfig.PLAYER_REALMS[realmIdx] or "大将军"
    local layerName = GameConfig.CHINESE_NUMS[layerIdx] or tostring(layerIdx)
    return realmName .. layerName .. "级"
end

--- 境界评分: 每级递增, 高境界增幅更大 (50级)
RANK_POWER_TABLE = {
    -- 新生 一~十层
    0,   5,  12,  20,  30,  42,  56,  72,  90, 115,
    -- 侍僧 一~十层
    140, 170, 200, 235, 275, 320, 370, 425, 485, 550,
    -- 偏将 一~十层
    620, 700, 785, 875, 970, 1070, 1175, 1285, 1400, 1520,
    -- 领主 一~十层
    1650, 1790, 1940, 2100, 2270, 2450, 2640, 2840, 3050, 3270,
    -- 大将军 一~十层
    3500, 3740, 3990, 4250, 4520, 4800, 5090, 5390, 5700, 6020,
}

function CalcRankPowerScore()
    local idx = playerInfo.rankIdx or 1
    return RANK_POWER_TABLE[idx] or 0
end

--- 武技战力: 复用 GetSkillScore
function CalcSkillPowerScore()
    local power = 0
    for _, skillIdx in ipairs(playerEquippedSkills) do
        power = power + GetSkillScore(skillIdx)
    end
    return power
end

--- 装备总评分: 7个槽位已装备评分之和
function CalcEquipPowerScore()
    local power = 0
    for slotIdx = 1, 7 do
        power = power + GetEquippedSlotScore(slotIdx)
    end
    return power
end

--- 敌方单卡评分 (与玩家同口径, 无等级/命格/装备, 加 enemyScale)
function CalcEnemyPowerScore(card, enemyScale)
    enemyScale = enemyScale or 1.0
    local power = (card.atk * 2 + card.def + card.hp * 0.1) * enemyScale
    return math.floor(power)
end

--- 估算某个 enemyScale 下的推荐总战力 (纯敌方武灵战力, 不含玩家自身分)
function CalcStageRequiredPower(enemyScale)
    -- 敌方武灵战力 (实际战斗中部署 3-4 个敌人, 用平均值 * 3.5 估算)
    local totalAtk, totalDef, totalHp = 0, 0, 0
    for _, ec in ipairs(ENEMY_CARDS) do
        totalAtk = totalAtk + ec.atk
        totalDef = totalDef + ec.def
        totalHp  = totalHp  + ec.hp
    end
    local n = #ENEMY_CARDS
    local unitPow = (totalAtk / n * 2 + totalDef / n + totalHp / n * 0.1) * enemyScale
    local enemyHeroPower = unitPow * 3.5
    local totalPower = enemyHeroPower
    local minRequired = math.floor(totalPower * 0.7)
    local recommended = math.floor(totalPower * 1.0)
    return math.floor(totalPower), minRequired, recommended
end

--- 计算敌方阵容总战力 (纯武灵战力)
function CalcEnemyTotalPower(slots, enemyScale)
    local heroPower = 0
    for _, slot in ipairs(slots) do
        if slot.filled and slot.card then
            heroPower = heroPower + CalcEnemyPowerScore(slot.card, enemyScale)
        end
    end
    return heroPower
end

--- 计算战力比 (玩家/敌方, 同口径)
function CalcPowerRatio(playerSlots, enemySlots, enemyScale)
    local pp = CalcPlayerTotalPower()
    local ep = CalcEnemyTotalPower(enemySlots, enemyScale)
    if ep == 0 then return 99.0 end
    return pp / ep
end

--- 格式化战力数值 (带颜色)
function FormatPower(power)
    if power >= 10000 then
        return string.format("%.1fw", power / 10000)
    elseif power >= 1000 then
        return string.format("%.1fk", power / 1000)
    end
    return tostring(math.floor(power))
end

--- 格式化虎符数量 (超1000用k, 超100万用m, 超10亿用b)
function FormatJade(amount)
    if amount >= 1000000000 then
        return string.format("%.1fb", amount / 1000000000)
    elseif amount >= 1000000 then
        return string.format("%.1fm", amount / 1000000)
    elseif amount >= 1000 then
        return string.format("%.1fk", amount / 1000)
    end
    return tostring(math.floor(amount))
end

--- 获取战力等级评价
function GetPowerGrade(ratio)
    if ratio >= 2.0 then return "碾压", {80, 255, 80}
    elseif ratio >= 1.5 then return "优势", {120, 220, 160}
    elseif ratio >= 1.1 then return "均势", {220, 220, 120}
    elseif ratio >= 0.8 then return "劣势", {255, 180, 80}
    else return "危险", {255, 80, 80}
    end
end

-- ============================================================================
-- 红点系统 - 已读指纹 + 树状穿透
-- ============================================================================
-- 原理: 用评分指纹跟踪"上次确认时的状态"。
--   当获得新装备/武技导致 bestOwned 升高, 指纹不再匹配 >> 红点亮起。
--   点击进入对应页面 >> 调用 Dismiss >> 指纹更新 >> 红点关闭。
--   树状穿透: 父节点红点 = OR(所有子节点红点)。

redDotState = {
    equipAck = {},      -- equipAck[slotIdx] = 已确认的该槽位最佳拥有评分
    skillAckBest = 0,   -- 已确认的最佳未装备武技评分
    skillAckSlots = 2,  -- 已确认时的已装备槽位数
}

-- 获取当前最佳未装备武技评分
function GetBestUnequippedSkillScore()
    local equippedSet = {}
    for _, si in ipairs(playerEquippedSkills) do equippedSet[si] = true end
    local best = 0
    for i = 1, #SKILL_TECHNIQUES do
        if not equippedSet[i] and SKILL_DEFS[i] and SKILL_DEFS[i].unlocked then
            local sc = GetSkillScore(i)
            if sc > best then best = sc end
        end
    end
    return best
end

-- 单槽位红点: 有更好的装备 且 该优势未被确认
function HasEquipSlotRedDot(slotIdx)
    local bestOwned = GetBestOwnedScoreForSlot(slotIdx)
    local equipped = GetEquippedSlotScore(slotIdx)
    if bestOwned <= equipped then return false end
    return bestOwned > (redDotState.equipAck[slotIdx] or 0)
end

-- 兵甲按钮红点 (树状: 任一子槽位亮 >> 父节点亮)
function HasEquipRedDot()
    for slotIdx = 1, 7 do
        if HasEquipSlotRedDot(slotIdx) then return true end
    end
    return false
end

-- 武技按钮红点
function HasSkillRedDot()
    -- 情况1: 有空闲槽位 且 有已解锁的武技可装备 → 持续红点提醒
    if #playerEquippedSkills < 2 then
        local equippedSet = {}
        for _, si in ipairs(playerEquippedSkills) do equippedSet[si] = true end
        for i = 1, #SKILL_TECHNIQUES do
            if not equippedSet[i] and SKILL_DEFS[i] and SKILL_DEFS[i].unlocked then
                return true  -- 有空槽 + 有可装备的武技 → 红点
            end
        end
    end
    -- 情况2: 有更好的未装备武技, 且该优势未被确认
    local minEquipped = math.huge
    for _, si in ipairs(playerEquippedSkills) do
        local sc = GetSkillScore(si)
        if sc < minEquipped then minEquipped = sc end
    end
    if #playerEquippedSkills == 0 then minEquipped = 0 end
    local bestUnequipped = GetBestUnequippedSkillScore()
    if bestUnequipped <= minEquipped then return false end
    return bestUnequipped > (redDotState.skillAckBest or 0)
end

-- 确认兵甲红点 (进入兵甲页面时调用)
function DismissEquipRedDots()
    for slotIdx = 1, 7 do
        redDotState.equipAck[slotIdx] = GetBestOwnedScoreForSlot(slotIdx)
    end
end

-- 确认武技红点 (进入武技页面时调用)
function DismissSkillRedDots()
    redDotState.skillAckBest = GetBestUnequippedSkillScore()
    redDotState.skillAckSlots = #playerEquippedSkills
end

-- 绘制红点 (带白描边的小红圆)
function DrawRedDot(rx, ry, rr)
    rr = rr or 6
    nvgBeginPath(vg)
    nvgCircle(vg, rx, ry, rr)
    nvgFillColor(vg, nvgRGBA(255, 45, 45, 235))
    nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(255, 255, 255, 200))
    nvgStrokeWidth(vg, 1.5)
    nvgStroke(vg)
end

-- 每日任务红点: 有可领取但未领取的任务
function HasDailyTaskRedDot()
    for _, task in ipairs(DAILY_TASKS) do
        if not dailyTaskState.claimed[task.id] then
            local prog = dailyTaskState.progress[task.id] or 0
            if prog >= task.target then return true end
        end
    end
    return false
end

-- 周任务红点: 有可领取但未领取的周任务
function HasWeeklyTaskRedDot()
    for _, task in ipairs(WEEKLY_TASKS) do
        if not weeklyTaskState.claimed[task.id] then
            local prog = weeklyTaskState.progress[task.id] or 0
            if prog >= task.target then return true end
        end
    end
    return false
end

-- 成就红点: 有可领取但未领取的成就
function HasAchievementRedDot()
    for _, ach in ipairs(ACHIEVEMENTS) do
        if not achievementClaimed[ach.id] then
            local val = GetAchievementStatValue(ach.stat)
            if val >= ach.target then return true end
        end
    end
    return false
end

-- 修行日录按钮红点 (树状: 任一子页签亮 >> 父节点亮)
function HasProgressRedDot()
    return HasDailyTaskRedDot() or HasWeeklyTaskRedDot() or HasAchievementRedDot()
end

-- 赠送随机装备（个体化: 每件兵甲独立，有品质）
function GrantRandomEquipment(maxTier)
    maxTier = maxTier or 1
    -- 根据概率决定阶级: 高阶概率极低
    local tier = 1
    local roll = math.random(1, 1000)
    local isTower = gameState and gameState.towerFloor
    if maxTier >= 6 and roll <= 5 then tier = 6                        -- 0.5%
    elseif maxTier >= 5 and roll <= (isTower and 5 or 25) then tier = 5 -- 爬塔0.5% / 普通2%
    elseif maxTier >= 4 and roll <= 75 then tier = 4                   -- 5%
    elseif maxTier >= 3 and roll <= 225 then tier = 3                  -- 15%
    elseif maxTier >= 2 and roll <= 475 then tier = 2                  -- 25%
    else tier = 1                                                       -- 52.5%
    end
    -- 随机选一个套装和部位
    local si = math.random(1, #EQUIPMENT_SETS)
    local pi = math.random(1, 7)
    local item = CreateEquipItem(si, pi, tier) -- 品质随机生成
    playerInfo.totalEquips = playerInfo.totalEquips + 1
    return { setIdx = si, slotIdx = pi, tier = tier, uid = item.uid, quality = item.quality }
end


