-- 通用奖励发放
function GrantRewardTable(reward)
    if not reward then return end
    if reward.jade and reward.jade > 0 then
        playerInfo.jade = playerInfo.jade + reward.jade
        AddFloatText(DESIGN_W / 2, DESIGN_H * 0.35, "+" .. reward.jade .. " 虎符", 1.5, { 210, 180, 255 }, 16)
    end
    if reward.frag and reward.frag > 0 then
        -- 随机分配残片
        for _ = 1, reward.frag do
            local idx = math.random(1, #SKILL_TECHNIQUES)
            skillFragments[idx] = (skillFragments[idx] or 0) + 1
        end
        AddFloatText(DESIGN_W / 2, DESIGN_H * 0.40, "+" .. reward.frag .. " 武技残片", 1.5, { 180, 160, 255 }, 14)
    end
    if reward.ticket and reward.ticket > 0 then
        -- 讨伐票已废弃，转换为虎符 (1票=10虎符)
        local bonusJade = reward.ticket * 10
        playerInfo.jade = playerInfo.jade + bonusJade
        AddFloatText(DESIGN_W / 2, DESIGN_H * 0.45, "+" .. bonusJade .. " 虎符", 1.5, { 200, 140, 255 }, 14)
    end
    -- 装备掉落 (讨伐主要产出路径)
    if reward.equipDrop and reward.equipDrop > 0 then
        for _ = 1, reward.equipDrop do
            local si = math.random(1, #EQUIPMENT_SETS)
            local pi = math.random(1, 7)
            -- 讨伐掉落阶级偏高: 50% T2, 30% T3, 15% T4, 5% T5
            local roll = math.random(1, 100)
            local tier
            if roll <= 5 then tier = 5
            elseif roll <= 20 then tier = 4
            elseif roll <= 50 then tier = 3
            elseif roll <= 100 then tier = 2
            end
            CreateEquipItem(si, pi, tier, math.random(30, 90))
            playerInfo.totalEquips = (playerInfo.totalEquips or 0) + 1
        end
        AddFloatText(DESIGN_W / 2, DESIGN_H * 0.50, "+" .. reward.equipDrop .. " 件装备!", 1.5, { 255, 200, 100 }, 16)
    end
end

-- ============================================================================
-- 英雄升级
-- ============================================================================
function GetHeroExpForLevel(level)
    if level < 1 then return 0 end
    if level > HERO_MAX_LEVEL then return HERO_LEVEL_EXP[HERO_MAX_LEVEL] + (level - HERO_MAX_LEVEL) * 500 end
    return HERO_LEVEL_EXP[level] or 0
end

function TryLevelUpHero(cardIdx)
    local hero = playerHeroes[cardIdx]
    if not hero or not hero.owned then return false end
    local curLv = hero.level or 1
    local needed = GetHeroExpForLevel(curLv + 1) - GetHeroExpForLevel(curLv)
    if needed <= 0 then needed = 50 end
    if playerInfo.exp < needed then return false end
    playerInfo.exp = playerInfo.exp - needed
    hero.level = curLv + 1
    AddFloatText(DESIGN_W / 2, DESIGN_H * 0.3,
        HERO_CARDS[cardIdx].name .. " 升级! Lv" .. hero.level, 2.0, { 255, 230, 80 }, 18)
    SaveGameProgress()
    return true
end

-- ============================================================================
-- 玩家升级检查 (经验累积制: 达到阈值自动升级)
-- ============================================================================
function CheckPlayerLevelUp()
    local maxRank = #GameConfig.RANK_EXP_TABLE
    while playerInfo.rankIdx < maxRank do
        local nextExp = GameConfig.RANK_EXP_TABLE[playerInfo.rankIdx + 1]
        if not nextExp then break end
        if playerInfo.exp >= nextExp then
            playerInfo.rankIdx = playerInfo.rankIdx + 1
            playerInfo.level = playerInfo.rankIdx
            local rankName = GetRankDisplayName(playerInfo.rankIdx)
            AddFloatText(DESIGN_W / 2, DESIGN_H * 0.25,
                "突破! " .. rankName, 3.0, { 255, 230, 80 }, 22)
            PlaySFX(AUDIO.sfx_win)
            SaveGameProgress()
            ReportRealmScore()
        else
            break
        end
    end
end

-- ============================================================================
-- 装备分解 & 强化
-- ============================================================================
--- 计算分解可获得军资（含强化返还50%）
function CalcDecomposeGain(tier, enhanceLv)
    local base = DECOMPOSE_LINGSHI[tier] or 5
    local enhLv = enhanceLv or 0
    if enhLv <= 0 then return base, 0 end
    -- 强化投入总军资
    local totalEnhCost = 0
    for i = 1, enhLv do
        totalEnhCost = totalEnhCost + (ENHANCE_COST[i] or 0)
    end
    -- 返还强化投入的50%（向上取整）
    local enhRefund = math.ceil(totalEnhCost * 0.5)
    return base + enhRefund, enhRefund
end

function DecomposeEquipment(uid)
    local item, idx = FindOwnedByUid(uid)
    if not item then return false end
    -- 已装备的不能分解
    local equippedUid = playerEquipment.equipped[item.slotIdx]
    if equippedUid == uid then return false end
    -- 分解获取军资（含强化返还）
    local gain, enhRefund = CalcDecomposeGain(item.tier, item.enhanceLv)
    RemoveOwnedByUid(uid)
    playerInfo.lingshi = playerInfo.lingshi + gain
    playerInfo.totalDecompose = playerInfo.totalDecompose + 1
    TrackDailyTask("enhance1", 0) -- 分解不算强化
    local msg = "分解 +" .. gain .. " 军资"
    if enhRefund > 0 then
        msg = msg .. " (含强化返还" .. enhRefund .. ")"
    end
    AddFloatText(DESIGN_W / 2, DESIGN_H * 0.3, msg, 1.5, { 180, 220, 255 }, 16)
    SaveGameProgress()
    return true
end

--- 计算筛选分解统计 (不执行分解)
function CalcBatchDecomposeStats(maxTier)
    maxTier = maxTier or 6
    local count = 0
    local gain = 0
    for _, item in ipairs(playerEquipment.owned) do
        if playerEquipment.equipped[item.slotIdx] ~= item.uid and item.tier <= maxTier then
            count = count + 1
            gain = gain + CalcDecomposeGain(item.tier, item.enhanceLv)
        end
    end
    return count, gain
end

--- 一键分解: 分解未装备兵甲(可筛选品质), 返回(总数, 总军资)
function BatchDecomposeAll(maxTier, filterTiers, maxEnhLv)
    maxTier = maxTier or 6
    local toRemove = {}
    local totalGain = 0
    local count = 0
    for _, item in ipairs(playerEquipment.owned) do
        local equippedUid = playerEquipment.equipped[item.slotIdx]
        if equippedUid ~= item.uid then
            local tierOk = false
            if filterTiers then
                tierOk = filterTiers[item.tier] == true
            else
                tierOk = item.tier <= maxTier
            end
            local lvOk = true
            if maxEnhLv then
                lvOk = (item.enhanceLv or 0) <= maxEnhLv
            end
            if tierOk and lvOk then
                local gain = CalcDecomposeGain(item.tier, item.enhanceLv)
                totalGain = totalGain + gain
                count = count + 1
                table.insert(toRemove, item.uid)
            end
        end
    end
    if count == 0 then return 0, 0 end
    -- 从后往前删除 (避免索引偏移)
    for i = #toRemove, 1, -1 do
        RemoveOwnedByUid(toRemove[i])
    end
    playerInfo.lingshi = playerInfo.lingshi + totalGain
    playerInfo.totalDecompose = playerInfo.totalDecompose + count
    AddFloatText(DESIGN_W / 2, DESIGN_H * 0.3,
        "批量分解 " .. count .. " 件 +" .. totalGain .. " 军资", 2.5, { 255, 200, 100 }, 18)
    SaveGameProgress()
    return count, totalGain
end

--- 计算选中分解统计 (不执行分解)
function CalcSelectDecomposeStats(uids)
    local count = 0
    local gain = 0
    for uid, _ in pairs(uids) do
        local item = FindOwnedByUid(uid)
        if item and playerEquipment.equipped[item.slotIdx] ~= item.uid then
            count = count + 1
            gain = gain + CalcDecomposeGain(item.tier, item.enhanceLv)
        end
    end
    return count, gain
end

--- 选中分解: 分解指定uid列表, 返回(总数, 总军资)
function SelectDecomposeAll(uids)
    local toRemove = {}
    local totalGain = 0
    local count = 0
    for uid, _ in pairs(uids) do
        local item = FindOwnedByUid(uid)
        if item and playerEquipment.equipped[item.slotIdx] ~= item.uid then
            local gain = CalcDecomposeGain(item.tier, item.enhanceLv)
            totalGain = totalGain + gain
            count = count + 1
            table.insert(toRemove, uid)
        end
    end
    if count == 0 then return 0, 0 end
    for i = #toRemove, 1, -1 do
        RemoveOwnedByUid(toRemove[i])
    end
    playerInfo.lingshi = playerInfo.lingshi + totalGain
    playerInfo.totalDecompose = playerInfo.totalDecompose + count
    AddFloatText(DESIGN_W / 2, DESIGN_H * 0.3,
        "选中分解 " .. count .. " 件 +" .. totalGain .. " 军资", 2.5, { 255, 200, 100 }, 18)
    SaveGameProgress()
    return count, totalGain
end

function EnhanceEquipment(slotIdx)
    local eq = GetEquippedItem(slotIdx)
    if not eq then return false end
    local curLv = eq.enhanceLv or 0
    if curLv >= ENHANCE_MAX_LEVEL then
        AddFloatText(DESIGN_W / 2, DESIGN_H * 0.3, "已达强化上限 +20!", 1.0, { 255, 200, 100 }, 14)
        return false
    end
    local cost = ENHANCE_COST[curLv + 1] or 999
    if playerInfo.lingshi < cost then
        AddFloatText(DESIGN_W / 2, DESIGN_H * 0.3, "军资不足 (需要" .. cost .. ")", 1.0, { 255, 100, 100 }, 14)
        return false
    end
    playerInfo.lingshi = playerInfo.lingshi - cost
    eq.enhanceLv = curLv + 1
    playerInfo.totalEnhance = playerInfo.totalEnhance + 1
    TrackDailyTask("enhance1", 1)
    TrackWeeklyTask("wenhance3", 1)
    TrackBattlePassTask("bp_enhance1", 1)
    TrackBattlePassTask("bp_senhance20", 1)
    local bonusPct = eq.enhanceLv * ENHANCE_PERCENT_PER_LEVEL
    AddFloatText(DESIGN_W / 2, DESIGN_H * 0.3,
        "强化成功! +" .. eq.enhanceLv .. " (全属性+" .. bonusPct .. "%)", 2.0, { 255, 220, 80 }, 18)
    SaveGameProgress()
    return true
end

-- ============================================================================
-- 成就统计获取
-- ============================================================================
function GetAchievementStatValue(statName)
    if statName == "totalWins" then return playerInfo.totalWins
    elseif statName == "totalBattles" then return playerInfo.totalBattles
    elseif statName == "totalGachas" then return playerInfo.totalGachas
    elseif statName == "totalEquips" then return playerInfo.totalEquips
    elseif statName == "totalDecompose" then return playerInfo.totalDecompose
    elseif statName == "totalEnhance" then return playerInfo.totalEnhance
    elseif statName == "totalFriends" then return playerInfo.totalFriends or 0
    elseif statName == "totalFriendReqs" then return playerInfo.totalFriendReqs or 0
    elseif statName == "totalFactionChat" then return playerInfo.totalFactionChat or 0
    elseif statName == "factionJoined" then return playerInfo.factionJoined or 0
    elseif statName == "totalFactionCreated" then return playerInfo.totalFactionCreated or 0
    elseif statName == "totalRankedBattles" then return playerInfo.totalRankedBattles or 0
    elseif statName == "totalRankedWins" then return playerInfo.totalRankedWins or 0
    elseif statName == "totalExplores" then return playerInfo.totalExplores or 0
    elseif statName == "stagesCleared" then
        local c = 0
        for k, v in pairs(stageStars) do if v and v > 0 then c = c + 1 end end
        return c
    elseif statName == "abyssCleared" then
        local c = 0
        for k, v in pairs(abyssCleared) do if v then c = c + 1 end end
        return c
    end
    return 0
end

function ClaimAchievement(achIdx)
    local ach = ACHIEVEMENTS[achIdx]
    if not ach then return false end
    if achievementClaimed[ach.id] then return false end
    local val = GetAchievementStatValue(ach.stat)
    if val < ach.target then return false end
    achievementClaimed[ach.id] = true
    GrantRewardTable(ach.reward)
    SaveGameProgress()
    return true
end

-- ============================================================================
-- 战斗结算: 胜利/结束 统一入口
-- ============================================================================

--- 战斗胜利时调用 (统计、首通、讨伐通关、解锁下一关)
function OnBattleVictory()
    -- 0) 探索模式: 返回探索界面
    if gameState.explorationMode then
        playerInfo.totalWins = playerInfo.totalWins + 1
        playerInfo.totalBattles = playerInfo.totalBattles + 1
        TrackDailyTask("battle3", 1)
        TrackDailyTask("win2", 1)
        TrackWeeklyTask("wbattle15", 1)
        TrackWeeklyTask("wwin10", 1)
        TrackBattlePassTask("bp_battle3", 1)
        TrackBattlePassTask("bp_win2", 1)
        TrackBattlePassTask("bp_wbattle20", 1)
        TrackBattlePassTask("bp_wwin12", 1)
        TrackBattlePassTask("bp_sbattle100", 1)
        TrackBattlePassTask("bp_swin50", 1)
        Exploration.OnBattleReturn(true)
        gameState.explorationMode = false
        gameState.phase = "EXPLORATION"
        print("[探索] 战斗胜利, 返回探索地图")
        return
    end

    -- 1) 统计
    playerInfo.totalWins = playerInfo.totalWins + 1
    playerInfo.totalBattles = playerInfo.totalBattles + 1
    TrackDailyTask("battle3", 1)
    TrackDailyTask("win2", 1)
    TrackWeeklyTask("wbattle15", 1)
    TrackWeeklyTask("wwin10", 1)
    TrackBattlePassTask("bp_battle3", 1)
    TrackBattlePassTask("bp_win2", 1)
    TrackBattlePassTask("bp_wbattle20", 1)
    TrackBattlePassTask("bp_wwin12", 1)
    TrackBattlePassTask("bp_sbattle100", 1)
    TrackBattlePassTask("bp_swin50", 1)

    -- 2) 关卡星级奖励 (非讨伐/爬塔)
    if not gameState.abyssFloor and not gameState.towerFloor and not gameState.isRanked then
        local stageIdx = stageState.currentStage
        local key = tostring(stageIdx)
        -- 计算星级: 基于基地剩余HP百分比
        local hpPct = (gameState.playerBaseHP or 0) / (BASE_HP_MAX or 1)
        local earnedStars = 1
        if hpPct > 0.8 then earnedStars = 3
        elseif hpPct > 0.5 then earnedStars = 2 end
        -- 更新最高星级
        local prevStars = stageStars[key] or 0
        if earnedStars > prevStars then
            stageStars[key] = earnedStars
            -- 发放新达到星级的虎符奖励
            local totalJadeReward = 0
            for s = prevStars + 1, earnedStars do
                local claimKey = key .. "_" .. s
                if not stageStarClaimed[claimKey] then
                    stageStarClaimed[claimKey] = true
                    totalJadeReward = totalJadeReward + (STAGE_STAR_JADE[s] or 0)
                end
            end
            if totalJadeReward > 0 then
                playerInfo.jade = playerInfo.jade + totalJadeReward
                gameState.firstClearReward = { jade = totalJadeReward }
                AddFloatText(DESIGN_W / 2, DESIGN_H * 0.35, "★" .. earnedStars .. " 星级奖励: +" .. totalJadeReward .. " 虎符", 2.0, {255, 220, 80}, 20)
            end
        end
        gameState.lastEarnedStars = earnedStars  -- 保存用于结算展示
        -- 自动解锁下一关
        if stageIdx >= stageState.maxUnlocked and stageIdx < #STAGES then
            stageState.maxUnlocked = stageIdx + 1
        end
    end

    -- 3) 讨伐通关奖励
    if gameState.abyssFloor then
        local floorIdx = gameState.abyssFloor
        local floorKey = tostring(floorIdx)
        TrackDailyTask("abyss1", 1)
        TrackWeeklyTask("wabyss3", 1)
        TrackBattlePassTask("bp_wabyss3", 1)
        TrackBattlePassTask("bp_sabyss10", 1)
        if not abyssCleared[floorKey] then
            abyssCleared[floorKey] = true
        end
        local abReward = ABYSS_REWARDS[floorIdx]
        if abReward then
            GrantRewardTable(abReward)
            gameState.abyssReward = abReward  -- 保存用于弹窗展示
        end
    end

    -- 3.5) 爬塔通关奖励
    if gameState.towerFloor then
        local fl = gameState.towerFloor
        -- 递增奖励 (适度降低)
        local towerJade = 20 + fl * 7
        local towerFrag = math.min(12, math.floor(fl / 4) + 1)
        local towerReward = { jade = towerJade, frag = towerFrag }
        GrantRewardTable(towerReward)
        gameState.towerReward = towerReward  -- 保存用于弹窗展示
        -- 推进层数 (上限999层)
        towerState.currentFloor = math.min(fl + 1, 1000)  -- 1000表示已通关999层，不可再挑战
        if fl > towerState.highestFloor then
            towerState.highestFloor = fl
            ReportTowerFloor()  -- 上报云端排行榜
        end
    end

    -- 3.8) 排位胜利
    if gameState.isRanked then
        playerInfo.totalRankedBattles = (playerInfo.totalRankedBattles or 0) + 1
        playerInfo.totalRankedWins = (playerInfo.totalRankedWins or 0) + 1
        rankedState.wins = rankedState.wins + 1
        if rankedState.streak < 0 then rankedState.streak = 0 end
        rankedState.streak = rankedState.streak + 1
        local delta = CalcRankedScoreChange(true, rankedState.streak)
        rankedState.score = math.max(0, rankedState.score + delta)
        if rankedState.score > rankedState.highestScore then
            rankedState.highestScore = rankedState.score
        end
        gameState.rankedDelta = delta  -- 保存用于弹窗展示
        ReportRankedScore()
    end

    -- 4) 保存
    SaveGameProgress()
end

--- 战斗结束时调用 (失败/平局)
function OnBattleEnd()
    -- 探索模式: 战败返回探索地图 (敌人不清除)
    if gameState.explorationMode then
        playerInfo.totalBattles = playerInfo.totalBattles + 1
        TrackDailyTask("battle3", 1)
        TrackWeeklyTask("wbattle15", 1)
        TrackBattlePassTask("bp_battle3", 1)
        TrackBattlePassTask("bp_wbattle20", 1)
        TrackBattlePassTask("bp_sbattle100", 1)
        Exploration.OnBattleReturn(false)
        gameState.explorationMode = false
        gameState.phase = "EXPLORATION"
        print("[探索] 战斗失败, 返回探索地图")
        return
    end

    playerInfo.totalBattles = playerInfo.totalBattles + 1
    TrackDailyTask("battle3", 1)
    TrackWeeklyTask("wbattle15", 1)
    TrackBattlePassTask("bp_battle3", 1)
    TrackBattlePassTask("bp_wbattle20", 1)
    TrackBattlePassTask("bp_sbattle100", 1)
    -- 讨伐失败也计入讨伐任务
    if gameState.abyssFloor then
        TrackDailyTask("abyss1", 1)
        TrackWeeklyTask("wabyss3", 1)
        TrackBattlePassTask("bp_wabyss3", 1)
        TrackBattlePassTask("bp_sabyss10", 1)
    end
    -- 排位失败
    if gameState.isRanked then
        playerInfo.totalRankedBattles = (playerInfo.totalRankedBattles or 0) + 1
        rankedState.losses = rankedState.losses + 1
        if rankedState.streak > 0 then rankedState.streak = 0 end
        rankedState.streak = rankedState.streak - 1
        local delta = CalcRankedScoreChange(false, rankedState.streak)
        rankedState.score = math.max(0, rankedState.score + delta)
        gameState.rankedDelta = delta  -- 保存用于弹窗展示
        ReportRankedScore()
    end
    SaveGameProgress()
end

--- 获取当前主字体 ID (统一使用 MiSans)
function GetMainFont()
    local style = gameSettings.fontStyle or "misans"
    if style == "kuaile" and fontGame >= 0 then return fontGame end
    if style == "wenkai" and fontFZ >= 0 then return fontFZ end
    if style == "xingshu" and fontArt >= 0 then return fontArt end
    return fontId  -- misans 默认
end

