function CheckSpinWheelReset()
    local today = GetTodayDateStr()
    if welfareState.spinWheel.lastDate ~= today then
        welfareState.spinWheel.lastDate = today
        welfareState.spinWheel.freeUsed = false
        welfareState.spinWheel.adSpins = 0
        welfareState.spinWheel.spinning = false
        welfareState.spinWheel.resultIdx = 0
        welfareState.spinWheel.resultGranted = false
        welfareState.spinWheel.angle = 0
    end
end

function CheckCardFlipReset()
    local today = GetTodayDateStr()
    if welfareState.cardFlip.lastDate ~= today then
        welfareState.cardFlip.lastDate = today
        welfareState.cardFlip.freeUsed = false
        welfareState.cardFlip.adFlips = 0
        welfareState.cardFlip.flipped = {false,false,false,false,false,false}
        -- 随机生成6张牌
        welfareState.cardFlip.cards = {}
        for i = 1, 6 do
            welfareState.cardFlip.cards[i] = math.random(1, #CARD_POOL)
        end
    end
end

function GrantWheelReward(idx)
    local rw = WHEEL_REWARDS[idx]
    if not rw then return end
    if rw.jade then playerInfo.jade = playerInfo.jade + rw.jade end
    if rw.frag then playerInfo.skillFragments = (playerInfo.skillFragments or 0) + rw.frag end
    if rw.ticket then playerInfo.tickets = (playerInfo.tickets or 0) + rw.ticket end
    AddFloatText(DESIGN_W / 2, DESIGN_H * 0.3, "转盘奖励: " .. rw.label, 2.0, { 255, 220, 80 }, 16)
end

function GrantCardReward(poolIdx)
    local rw = CARD_POOL[poolIdx]
    if not rw then return end
    if rw.jade then playerInfo.jade = playerInfo.jade + rw.jade end
    if rw.frag then playerInfo.skillFragments = (playerInfo.skillFragments or 0) + rw.frag end
    if rw.ticket then playerInfo.tickets = (playerInfo.tickets or 0) + rw.ticket end
    AddFloatText(DESIGN_W / 2, DESIGN_H * 0.3, "翻牌奖励: " .. rw.label, 2.0, { 120, 220, 255 }, 16)
end

function StartWheelSpin(t)
    local resultIdx = math.random(1, #WHEEL_REWARDS)
    local segAngle = 2 * math.pi / #WHEEL_REWARDS
    -- 目标角度: 多转几圈 + 停在指定扇区
    local extraTurns = math.random(3, 5) * 2 * math.pi
    local targetA = extraTurns + (2 * math.pi - (resultIdx - 0.5) * segAngle)
    welfareState.spinWheel.spinning = true
    welfareState.spinWheel.spinStart = t
    welfareState.spinWheel.targetAngle = targetA
    welfareState.spinWheel.resultIdx = resultIdx
    welfareState.spinWheel.resultGranted = false
    welfareState.spinWheel.angle = 0
end

-- 广告限制已移除，仅灵石广告保留每日20次计数

--- 安全的广告回调包装器：防止回调内异常导致游戏崩溃
--- @param callback function 原始回调
--- @return function 安全包装后的回调
function SafeAdCallback(callback)
    return function(result)
        local ok, err = pcall(function()
            ResumeAfterAd()
            -- 真实广告成功: 递增每日广告总计数
            if result and result.success then
                IncrementDailyAdTotal()
            end
            if callback then callback(result) end
        end)
        if not ok then
            print("[广告] 回调异常(已安全处理): " .. tostring(err))
            -- 确保即使回调崩溃，游戏仍然保存进度
            pcall(SaveGameProgress)
        end
    end
end

--- 检查当前平台是否为移动端 (Android/iOS)
--- @return boolean
function IsMobilePlatform()
    local p = GetPlatform and GetPlatform() or "unknown"
    return p == "Android" or p == "iOS"
end

--- 检查广告是否可以播放（无限制，始终可看）
--- @return boolean canWatch 始终返回true
function CanWatchAd()
    -- 免广告特权: 直接返回 false, 调用处走 else(DEV) 分支直接给奖励
    if playerInfo.ad_free then return false end
    return true
end

--- 检查今日战斗广告是否已免除 (每日免广告卡: 看满5次广告后战斗中广告自动跳过)
--- @return boolean isFree 战斗广告是否免除
function IsBattleAdFree()
    -- 永久免广告特权优先
    if playerInfo.ad_free then return true end
    -- 跨日重置
    local today = os.date("%Y-%m-%d")
    if gameSettings.dailyAdDate ~= today then
        gameSettings.dailyAdCount = 0
        gameSettings.dailyAdDate = today
    end
    return gameSettings.dailyAdCount >= 3
end

--- 检查今日广告总次数是否已达上限 (每日最多20次)
--- 跨日自动重置; 首次安装 dailyTotalAdDate="" 会触发重置为0, 不会误封
--- @return boolean limitReached 是否达到上限
function IsDailyAdLimitReached()
    local today = os.date("%Y-%m-%d")
    if gameSettings.dailyTotalAdDate ~= today then
        gameSettings.dailyTotalAdCount = 0
        gameSettings.dailyTotalAdDate = today
        SaveSettings()  -- 跨日重置后持久化
    end
    return gameSettings.dailyTotalAdCount >= 20
end

--- 记录一次成功的广告观看（每日上限计数+1, 自动保存）
--- 只在真实广告成功回调中调用, DEV模式不计数
function IncrementDailyAdTotal()
    local today = os.date("%Y-%m-%d")
    if gameSettings.dailyTotalAdDate ~= today then
        gameSettings.dailyTotalAdCount = 0
        gameSettings.dailyTotalAdDate = today
    end
    gameSettings.dailyTotalAdCount = gameSettings.dailyTotalAdCount + 1
    print("[广告] 今日广告观看: " .. gameSettings.dailyTotalAdCount .. "/20")
    SaveSettings()
end

--- 带每日上限检查的广告显示 (替代直接调用 sdk:ShowRewardVideoAd)
--- @param wrappedCallback function SafeAdCallback 包装后的回调
function ShowAdSafe(wrappedCallback)
    if IsDailyAdLimitReached() then
        AddFloatText(DESIGN_W / 2, DESIGN_H * 0.3, "今日广告已达上限(20次)", 1.5, {255, 180, 80}, 14)
        return
    end
    -- 通过索引调用避免被 replace_all 替换
    sdk["ShowRewardVideoAd"](sdk, wrappedCallback)
end

--- 上报一次有效广告观看到云排行榜
--- 本地先行更新贡献榜数据（保证看完广告后立即有数据可看）
function UpdateContribRankLocally()
    if not welfareState.contribRank then
        welfareState.contribRank = {}
    end
    local myName = playerInfo.name or "我"
    local myCount = welfareState.localAdCount or 1
    local found = false
    for _, entry in ipairs(welfareState.contribRank) do
        if entry.name == myName then
            entry.count = myCount
            found = true
            break
        end
    end
    if not found then
        table.insert(welfareState.contribRank, { name = myName, count = myCount })
    end
    table.sort(welfareState.contribRank, function(a, b) return a.count > b.count end)
    welfareState.contribLoaded = true
end

function ReportAdWatch()
    -- 本地计数（无论云是否可用都更新）
    welfareState.localAdCount = (welfareState.localAdCount or 0) + 1
    print("[广告] 本地广告计数: " .. tostring(welfareState.localAdCount))

    -- 本地先行更新贡献榜（立即可见）
    UpdateContribRankLocally()

    if rawget(_G, "clientCloud") then
        print("[广告] clientCloud 可用，上报 ad_watch_count +1")
        clientCloud:Add(PROJECT_PREFIX .. "ad_watch_count", 1, {
            ok = function()
                print("[广告] 上报成功，后台刷新排行榜")
                -- 上报成功后在后台刷新排行榜（获取其他玩家的最新数据）
                welfareState.contribLoading = false
                LoadContribRank()
            end,
            error = function(err)
                print("[广告] 上报失败: " .. tostring(err))
                -- 上报失败也无妨，本地数据已先行更新
            end,
        })
    else
        print("[广告] clientCloud 不可用，仅本地计数")
    end
end

--- 福利中心专用广告上报（仅上报贡献榜）
function ReportAdWatchWelfare()
    welfareState.localAdCount = (welfareState.localAdCount or 0) + 1
    print("[广告-福利] 福利签到广告 | 累计: " .. tostring(welfareState.localAdCount))
