end

--- 加载贡献榜数据（广告观看排行）
LoadContribRank = function()
    if not rawget(_G, "clientCloud") then return end
    if welfareState.contribLoading then return end
    welfareState.contribLoading = true
    print("[贡献榜] 开始加载排行榜...")
    clientCloud:GetRankList(PROJECT_PREFIX .. "ad_watch_count", 0, 100, {
        ok = function(rankList)
            print("[贡献榜] GetRankList 返回 " .. tostring(#rankList) .. " 条")
            -- 过滤封禁玩家并截取前50
            local filtered = {}
            for _, item in ipairs(rankList) do
                if not CloudManager.IsPlayerRankHidden(item.player) then
                    filtered[#filtered + 1] = item
                    if #filtered >= 50 then break end
                end
            end
            rankList = filtered
            -- 收集 userId 列表
            local userIds = {}
            for _, item in ipairs(rankList) do
                table.insert(userIds, item.player)
            end
            if #userIds == 0 then
                welfareState.contribRank = {}
                welfareState.contribLoading = false
                welfareState.contribLoaded = true
                print("[贡献榜] 排行榜为空")
                return
            end

            --- 从排行榜数据生成结果（不依赖昵称）
            local function buildResultWithoutNicknames()
                local result = {}
                for _, item in ipairs(rankList) do
                    local count = item.iscore and item.iscore[PROJECT_PREFIX .. "ad_watch_count"] or 0
                    table.insert(result, { name = "玩家" .. tostring(item.player), count = count, userId = item.player })
                end
                return result
            end

            -- 安全查询昵称（pcall 保护，防止 lobby 不可用等异常导致卡住）
            local nickOk, nickErr = pcall(function()
                GetUserNickname({
                    userIds = userIds,
                    onSuccess = function(nicknames)
                        local nameMap = {}
                        for _, info in ipairs(nicknames) do
                            nameMap[info.userId] = info.nickname
                        end
                        local result = {}
                        for _, item in ipairs(rankList) do
                            local count = item.iscore and item.iscore[PROJECT_PREFIX .. "ad_watch_count"] or 0
                            local name = nameMap[item.player] or ("玩家" .. tostring(item.player))
                            table.insert(result, { name = name, count = count, userId = item.player })
                        end
                        welfareState.contribRank = result
                        welfareState.contribLoading = false
                        welfareState.contribLoaded = true
                        print("[贡献榜] 昵称查询成功，共 " .. #result .. " 条")
                    end,
                    onError = function()
                        -- 昵称查询失败也展示，用 userId 代替
                        welfareState.contribRank = buildResultWithoutNicknames()
                        welfareState.contribLoading = false
                        welfareState.contribLoaded = true
                        print("[贡献榜] 昵称查询失败，使用ID代替")
                    end,
                })
            end)
            if not nickOk then
                -- GetUserNickname 调用本身异常（lobby不可用等）
                print("[贡献榜] GetUserNickname异常: " .. tostring(nickErr))
                welfareState.contribRank = buildResultWithoutNicknames()
                welfareState.contribLoading = false
                welfareState.contribLoaded = true
            end
        end,
        error = function(err)
            print("[贡献榜] GetRankList 失败: " .. tostring(err))
            welfareState.contribLoading = false
            welfareState.contribLoaded = true
            welfareState.contribRank = {}
        end,
    })
end

---- 上报战力到云排行榜（使用 SetInt 设置绝对值）
function ReportPowerScore()
    local power = CalcPlayerTotalPower()
    if power <= 0 then return end

    -- 统计技能数和武灵数，附带上报
    local skillCount = 0
    for i, sk in pairs(SKILL_DEFS) do
        if sk.unlocked then skillCount = skillCount + 1 end
    end
    local heroCount = #GetAllOwnedHeroes()

    if rawget(_G, "clientCloud") then
        clientCloud:SetInt(PROJECT_PREFIX .. "combat_power", power, {
            ok = function()
                print("[战力] 上报成功: " .. tostring(power))
                -- 附带上报技能数和武灵数
                clientCloud:SetInt(PROJECT_PREFIX .. "skill_count", skillCount, {})
                clientCloud:SetInt(PROJECT_PREFIX .. "hero_count", heroCount, {})
                -- 上报成功后刷新战力排行榜
                welfareState.powerLoaded = false
                welfareState.powerLoading = false
                LoadPowerRank()
            end,
            error = function(err)
                print("[战力] 上报失败: " .. tostring(err))
            end,
        })
    else
        print("[战力] clientCloud 不可用，仅本地模拟")
        -- 开发模式下本地模拟
        if not welfareState.powerRank then
            welfareState.powerRank = {}
        end
        local myName = playerInfo.name or "我"
        local found = false
        for _, entry in ipairs(welfareState.powerRank) do
            if entry.name == myName then
                entry.power = power
                found = true
                break
            end
        end
        if not found then
            table.insert(welfareState.powerRank, 1, { name = myName, power = power, userId = 0 })
        end
        table.sort(welfareState.powerRank, function(a, b) return a.power > b.power end)
        welfareState.powerLoaded = true
    end
end

