-- 桩逼王排行榜 (打桩伤害排行 - 上报 & 加载)
-- ============================================================================
function ReportDummyScore(damage)
    if damage <= 0 then return end
    local intDmg = math.floor(damage)
    if rawget(_G, "clientCloud") then
        clientCloud:SetInt(PROJECT_PREFIX .. "dummy_damage", intDmg, {
            ok = function()
                print("[桩逼王] 上报成功: " .. tostring(intDmg))
                welfareState.dummyLoaded = false
                welfareState.dummyLoading = false
            end,
            error = function(err)
                print("[桩逼王] 上报失败: " .. tostring(err))
            end,
        })
    end
end

function LoadDummyRank()
    if not rawget(_G, "clientCloud") then return end
    if welfareState.dummyLoading then return end
    welfareState.dummyLoading = true
    clientCloud:GetRankList(PROJECT_PREFIX .. "dummy_damage", 0, 100, {
        ok = function(rankList)
            -- 过滤封禁玩家并截取前50
            local filtered = {}
            for _, item in ipairs(rankList) do
                if not CloudManager.IsPlayerRankHidden(item.player) then
                    filtered[#filtered + 1] = item
                    if #filtered >= 50 then break end
                end
            end
            rankList = filtered
            local userIds = {}
            for _, item in ipairs(rankList) do
                table.insert(userIds, item.player)
            end
            if #userIds == 0 then
                welfareState.dummyRank = {}
                welfareState.dummyLoading = false
                welfareState.dummyLoaded = true
                return
            end
            GetUserNickname({
                userIds = userIds,
                onSuccess = function(nicknames)
                    local nameMap = {}
                    for _, info in ipairs(nicknames) do
                        nameMap[info.userId] = info.nickname
                    end
                    local result = {}
                    for _, item in ipairs(rankList) do
                        local sc = item.iscore or {}
                        local dmg = sc[PROJECT_PREFIX .. "dummy_damage"] or 0
                        local name = nameMap[item.player] or ("玩家" .. tostring(item.player))
                        table.insert(result, {
                            name = name, damage = dmg, userId = item.player,
                            power = sc[PROJECT_PREFIX .. "combat_power"] or 0,
                        })
                    end
                    welfareState.dummyRank = result
                    welfareState.dummyLoading = false
                    welfareState.dummyLoaded = true
                end,
                onError = function()
                    local result = {}
                    for _, item in ipairs(rankList) do
                        local sc = item.iscore or {}
                        local dmg = sc[PROJECT_PREFIX .. "dummy_damage"] or 0
                        table.insert(result, {
                            name = "玩家" .. tostring(item.player), damage = dmg, userId = item.player,
                            power = sc[PROJECT_PREFIX .. "combat_power"] or 0,
                        })
                    end
                    welfareState.dummyRank = result
                    welfareState.dummyLoading = false
                    welfareState.dummyLoaded = true
                end,
            })
        end,
        error = function()
            welfareState.dummyLoading = false
            welfareState.dummyLoaded = true
            welfareState.dummyRank = {}
        end,
    })
end

-- ============================================================================
-- 安全剪贴板工具 (兼容 Web/WASM 平台 copyToClipboard 不存在的情况)
-- ============================================================================
local _internalClipboard = ""  -- 游戏内部剪贴板备份

local function _isWebPlatform()
    local p = GetPlatform and GetPlatform() or "unknown"
    return p == "Web" or p == "web" or p == "Emscripten"
end

--- 安全写入剪贴板 (优先系统剪贴板，Web平台仅用内部剪贴板)
function SafeSetClipboard(text)
    _internalClipboard = text or ""
    -- Web/WASM平台: 系统剪贴板API会导致JS崩溃，直接跳过
    if _isWebPlatform() then
        pcall(function()
            ui.useSystemClipboard = false
            ui:SetClipboardText(text)
        end)
        return false
    end
    -- 原生平台: 尝试系统剪贴板
    local ok = pcall(function()
        ui.useSystemClipboard = true
        ui:SetClipboardText(text)
    end)
    if not ok then
        pcall(function()
            ui.useSystemClipboard = false
            ui:SetClipboardText(text)
        end)
    end
    return ok
end

--- 安全读取剪贴板 (优先系统剪贴板，Web平台仅用内部剪贴板)
function SafeGetClipboard()
    -- Web/WASM平台: 不调用系统剪贴板
    if not _isWebPlatform() then
        local ok, text = pcall(function()
            ui.useSystemClipboard = true
            return ui:GetClipboardText()
        end)
        if ok and text and type(text) == "string" and #text > 0 then
            return text
        end
    end
    -- 内部剪贴板
    local ok2, text2 = pcall(function()
        ui.useSystemClipboard = false
        return ui:GetClipboardText()
    end)
    if ok2 and text2 and type(text2) == "string" and #text2 > 0 then
        return text2
    end
    if #_internalClipboard > 0 then return _internalClipboard end
    return nil
end

