-- ============================================================================
-- 武技系统: 广告解锁 + 技能施放 + 伤害逻辑
-- ============================================================================

--- 解锁或升层武技（统一入口）
--- 返回 layer (新层数) 或 nil (失败)
function UnlockOrUpgradeSkill(skillIdx)
    local skill = SKILL_DEFS[skillIdx]
    if not skill then return nil end
    if not skill.unlocked then
        -- 首次解锁
        skill.unlocked = true
        skillLayers[skillIdx] = 1
        return 1
    else
        -- 已解锁，升层
        local cur = skillLayers[skillIdx] or 1
        if cur >= SKILL_MAX_LAYER then
            return nil  -- 已满层
        end
        skillLayers[skillIdx] = cur + 1
        return cur + 1
    end
end

-- (已移除看广告升层武技功能，武技只能通过召唤或残片合成升层)

--- 初始化AI对手技能系统 (排位/讨伐模式)
function InitAISkills()
    aiSkillState.enabled = false
    aiSkillState.availableSkills = {}
    aiSkillState.cooldowns = {}
    aiSkillState.castTimer = 0
    aiSkillState.nextCastTime = 4.0 + math.random() * 3.0  -- 首次释放4~7秒

    -- 仅排位或讨伐模式启用
    if not gameState.isRanked and not gameState.abyssFloor then return end

    -- 筛选有特效的可用武技 (排除 notAvailable 和治疗技能)
    local allAvailable = {}
    for i, skill in ipairs(SKILL_DEFS) do
        if not skill.notAvailable and skill.skillType ~= "heal" then
            table.insert(allAvailable, i)
        end
    end

    -- 从所有可用技能中随机选2个，整局只用这2个
    if #allAvailable >= 2 then
        -- Fisher-Yates 洗牌取前2
        for i = #allAvailable, 2, -1 do
            local j = math.random(1, i)
            allAvailable[i], allAvailable[j] = allAvailable[j], allAvailable[i]
        end
        aiSkillState.availableSkills = { allAvailable[1], allAvailable[2] }
    elseif #allAvailable == 1 then
        aiSkillState.availableSkills = { allAvailable[1] }
    end

    for _, idx in ipairs(aiSkillState.availableSkills) do
        aiSkillState.cooldowns[idx] = 0
    end

    if #aiSkillState.availableSkills > 0 then
        aiSkillState.enabled = true
        -- 讨伐模式高层加快释放频率
        local floor = gameState.abyssFloor or 0
        if floor >= 5 then
            aiSkillState.castInterval = 4.0
        elseif floor >= 3 then
            aiSkillState.castInterval = 5.0
        else
            aiSkillState.castInterval = 6.0
        end
        local names = {}
        for _, idx in ipairs(aiSkillState.availableSkills) do
            table.insert(names, SKILL_DEFS[idx].name)
        end
        print("=== AI技能系统启用: 本局随机选定 " .. table.concat(names, ", ") .. " ===")
    end
end

--- AI对手释放技能 (每帧在UpdateBattle中调用)
function UpdateAISkills(dt)
    if not aiSkillState.enabled then return end
    if #enemyUnits == 0 then return end  -- 没有敌方单位不释放

    -- 冷却递减
    for idx, cd in pairs(aiSkillState.cooldowns) do
        if cd > 0 then
            aiSkillState.cooldowns[idx] = cd - dt
            if aiSkillState.cooldowns[idx] < 0 then aiSkillState.cooldowns[idx] = 0 end
        end
    end

    -- 释放计时
    aiSkillState.castTimer = aiSkillState.castTimer + dt
    if aiSkillState.castTimer < aiSkillState.nextCastTime then return end

    -- 时间到了，尝试释放一个技能
    aiSkillState.castTimer = 0
    aiSkillState.nextCastTime = aiSkillState.castInterval + (math.random() - 0.5) * 2.0  -- 随机浮动

    -- 筛选当前可用(不在CD中)的技能
    local readySkills = {}
    for _, idx in ipairs(aiSkillState.availableSkills) do
        if aiSkillState.cooldowns[idx] <= 0 then
            table.insert(readySkills, idx)
        end
    end
    if #readySkills == 0 then return end

    -- 随机选一个技能
    local chosenIdx = readySkills[math.random(1, #readySkills)]
    local skill = SKILL_DEFS[chosenIdx]
    if not skill then return end

    -- 设置冷却 (AI冷却比玩家稍长)
    aiSkillState.cooldowns[chosenIdx] = skill.maxCooldown * 1.5

    -- 计算目标位置
    local targetX, targetY
    if skill.skillType == "line" then
        -- 线型技能: 随机选一个车道
        local laneIdx = math.random(1, NUM_LANES)
        targetX = GetLaneCenterX(laneIdx)
        targetY = BATTLE_ZONE.centerY
    else
        -- AOE/矩形/区域技能: 优先瞄准玩家单位密集区域
        if #playerUnits > 0 then
            -- 随机选一个玩家单位作为目标中心
            local target = playerUnits[math.random(1, #playerUnits)]
            if target and target.alive then
                targetX = target.x + (math.random() - 0.5) * 40
                targetY = target.y + (math.random() - 0.5) * 30
            end
        end
        -- 如果没有合适目标，随机选战场中下部区域
        if not targetX then
            targetX = BATTLE_ZONE.left + math.random() * (BATTLE_ZONE.right - BATTLE_ZONE.left)
            targetY = BATTLE_ZONE.centerY + math.random() * (BATTLE_ZONE.playerLine - BATTLE_ZONE.centerY) * 0.6
        end
    end

    -- 释放音效
    if skill.skillType == "line" then
        PlaySFX(AUDIO.sfx_slash)
    else
        PlaySFX(AUDIO.sfx_cast)
    end

    -- 创建技能特效 (标记 isEnemySkill = true)
    if skill.skillType == "line" then
        local laneIdx = math.floor((targetX - BATTLE_ZONE.left) / LANE_WIDTH) + 1
        laneIdx = math.max(1, math.min(NUM_LANES, laneIdx))
        local laneCX = GetLaneCenterX(laneIdx)
        -- AI线型技能: 从敌方线出发向玩家线飞行 (方向反转)
        local startY = BATTLE_ZONE.enemyLine + 20
        local endY   = BATTLE_ZONE.playerLine + 30
        local dist   = endY - startY  -- 飞行总距离
        local fxData = SKILL_FX_SHEETS[skill.iconIdx]
        local frames = fxData and fxData.frames or 8
        local fps    = fxData and fxData.fps or 12
        local dur    = frames / fps
        local speed  = dist / dur
        table.insert(activeSkillEffects, {
            x = laneCX,
            y = startY,
            startY = startY,
            endY = endY,
            skillIdx = chosenIdx,
            timer = 0,
            frameIdx = 0,
            damaged = false,
            duration = dur,
            lineSpeed = speed,
            isLine = true,
            laneIdx = laneIdx,
            hitUnits = {},
            isEnemySkill = true,  -- 标记为AI技能
        })
    else
        table.insert(activeSkillEffects, {
            x = targetX,
            y = targetY,
            skillIdx = chosenIdx,
            timer = 0,
            frameIdx = 0,
            damaged = false,
            duration = skill.animDuration,
            isEnemySkill = true,  -- 标记为AI技能
        })
    end

    AddFloatText(targetX, targetY - 60, "敌方: " .. skill.name .. "!", 1.2,
        { math.min(255, skill.color[1] + 40), math.max(0, skill.color[2] - 30), math.max(0, skill.color[3] - 30) }, 20)
    print("=== AI释放武技: " .. skill.name .. " at (" .. math.floor(targetX) .. "," .. math.floor(targetY) .. ") ===")
end

--- 在目标位置释放技能
function CastSkill(skillIdx, targetX, targetY)
    local skill = SKILL_DEFS[skillIdx]
    if not skill or not skill.unlocked then return end
    if skill.cooldown > 0 then return end

    -- 设置冷却
    skill.cooldown = skill.maxCooldown

    -- 释放音效
    if skill.skillType == "line" then
        PlaySFX(AUDIO.sfx_slash)
    else
        PlaySFX(AUDIO.sfx_cast)
    end

    -- 创建技能特效
    if skill.skillType == "line" then
        -- 线型技能: 吸附到最近车道中心, 从玩家线出发向敌方飞行
        local laneIdx = math.floor((targetX - BATTLE_ZONE.left) / LANE_WIDTH) + 1
        laneIdx = math.max(1, math.min(NUM_LANES, laneIdx))
        local laneCX = GetLaneCenterX(laneIdx)
        local startY = BATTLE_ZONE.playerLine - 20
        local endY   = BATTLE_ZONE.enemyLine - 30
        local dist   = startY - endY  -- 飞行总距离 (像素)
        -- 动画恰好播完一次 = 飞行全程, 速度自动计算
        local fxData = SKILL_FX_SHEETS[skill.iconIdx]
        local frames = fxData and fxData.frames or 8
        local fps    = fxData and fxData.fps or 12
        local dur    = frames / fps              -- 动画总时长(秒)
        local speed  = dist / dur                -- 自动算出飞行速度
        table.insert(activeSkillEffects, {
            x = laneCX,
            y = startY,
            startY = startY,
            endY = endY,
            skillIdx = skillIdx,
            timer = 0,
            frameIdx = 0,
            damaged = false,
            duration = dur,
            lineSpeed = speed,
            isLine = true,
            laneIdx = laneIdx,
            hitUnits = {},
        })
    else
        -- AOE技能: 固定位置爆发
        table.insert(activeSkillEffects, {
            x = targetX,
            y = targetY,
            skillIdx = skillIdx,
            timer = 0,
            frameIdx = 0,
            damaged = false,
            duration = skill.animDuration,
        })
    end

    AddFloatText(targetX, targetY - 60, skill.name .. "!", 1.2, { skill.color[1], skill.color[2], skill.color[3] }, 20)
    print("=== 释放武技: " .. skill.name .. " at (" .. math.floor(targetX) .. "," .. math.floor(targetY) .. ") ===")
end

--- 更新技能特效 (在 UpdateBattle 中调用)
function UpdateSkillEffects(dt)
    -- 冷却递减
    for _, skill in ipairs(SKILL_DEFS) do
        if skill.cooldown > 0 then
            skill.cooldown = skill.cooldown - dt
            if skill.cooldown < 0 then skill.cooldown = 0 end
        end
    end

    -- 更新活跃特效
    for i = #activeSkillEffects, 1, -1 do
        local eff = activeSkillEffects[i]
        eff.timer = eff.timer + dt

        local skill = SKILL_DEFS[eff.skillIdx]
        if not skill then
            table.remove(activeSkillEffects, i)
            goto continue_fx
        end

        local fxData = SKILL_FX_SHEETS[skill.iconIdx]
        local frameCount = fxData and fxData.frames or SKILL_FRAME_COUNT

        if eff.isLine then
            -- ======== 线型技能: 向目标基地飞行, 持续命中 ========
            if eff.isEnemySkill then
                eff.y = eff.y + eff.lineSpeed * dt  -- AI技能: 向下飞行(Y增大=向玩家)
            else
                eff.y = eff.y - eff.lineSpeed * dt  -- 玩家技能: 向上飞行(Y减小=向敌方)
            end
            -- 帧动画只播一次 (clamp到最后一帧)
            local fps = fxData and fxData.fps or 12
            eff.frameIdx = math.min(math.floor(eff.timer * fps), frameCount - 1)

            -- 飞行过程中持续检测命中 (横向宽度内的单位)
            local halfW = (skill.lineWidth or 50) / 2
            local lineLayerMul = 1 + ((skillLayers[eff.skillIdx] or 1) - 1) * 0.2
            local targetUnits = eff.isEnemySkill and playerUnits or enemyUnits
            for _, u in ipairs(targetUnits) do
                if u.alive and not eff.hitUnits[u] then
                    if math.abs(u.x - eff.x) <= halfW and math.abs(u.y - eff.y) <= 25 then
                        eff.hitUnits[u] = true
                        PlaySFX(AUDIO.sfx_hit)
                        local dmg = math.ceil(skill.damage * lineLayerMul)
                        u.hp = u.hp - dmg
                        u.flashTimer = 0.3
                        local isCrit = math.random() < 0.2
                        if isCrit then
                            dmg = math.ceil(dmg * 1.8)
                            u.hp = u.hp - math.ceil(skill.damage * lineLayerMul * 0.8)
                        end
                        AddFloatText(u.x, u.y - 12, math.floor(dmg) .. (isCrit and "!" or ""),
                            0.8, isCrit and { 255, 220, 50 } or { skill.color[1], skill.color[2], skill.color[3] },
                            isCrit and 28 or 22)
                        for _ = 1, 3 do
                            AddParticle(u.x, u.y, {
                                vx = (math.random() - 0.5) * 60,
                                vy = -(math.random() * 30 + 10),
                                life = 0.3, size = 2,
                                color = { skill.color[1], skill.color[2], skill.color[3] },
                            })
                        end
                        if u.hp <= 0 then
                            u.alive = false
                            if not eff.isEnemySkill then
                                gameState.totalKills = gameState.totalKills + 1
                            end
                            for _ = 1, 8 do
                                AddParticle(u.x, u.y, {
                                    vx = (math.random() - 0.5) * 120,
                                    vy = -(math.random() * 60 + 15),
                                    life = 0.5, size = 3,
                                    color = { skill.color[1], math.random(100, 200), 40 },
                                })
                            end
                        end
                    end
                end
            end

            -- 尾迹粒子
            if math.random() < 0.6 then
                local sc = skill.color
                local trailOffY = eff.isEnemySkill and -20 or 20
                AddParticle(eff.x + (math.random() - 0.5) * 30, eff.y + trailOffY, {
                    vx = (math.random() - 0.5) * 20,
                    vy = eff.isEnemySkill and -(math.random() * 15 + 5) or (math.random() * 15 + 5),
                    life = 0.3 + math.random() * 0.2,
                    size = 1.5 + math.random() * 2,
                    color = { sc[1], sc[2], sc[3] },
                })
            end

            -- 动画播完 / 到达终点 >> 移除
            local reachedEnd
            if eff.isEnemySkill then
                reachedEnd = eff.y >= (eff.endY or BATTLE_ZONE.playerLine + 30)
            else
                reachedEnd = eff.y <= (eff.endY or BATTLE_ZONE.enemyLine - 30)
            end
            if eff.timer >= eff.duration or reachedEnd then
                table.remove(activeSkillEffects, i)
            end
        elseif skill.skillType == "heal" then
            -- ======== 治疗技能: 中间帧延长停留 + 持续回血 ========
            -- 帧播放策略: 前8帧正常播 >> 中间帧(7-9)停留holdTime >> 后6帧正常播
            local fps = 12
            local holdStart = 7    -- 停留起始帧 (0-indexed)
            local holdEnd   = 9    -- 停留结束帧
            local holdTime  = 3.0  -- 中间帧停留总时长(秒)
            local introTime = (holdStart + 1) / fps   -- 前段: 帧0~7 = 8帧
            local outroFrames = frameCount - holdEnd - 1  -- 后段帧数
            local outroTime = outroFrames / fps
            local totalDur = introTime + holdTime + outroTime

            if eff.timer < introTime then
                -- 前段: 正常播放 0~holdStart
                eff.frameIdx = math.min(holdStart, math.floor(eff.timer * fps))
            elseif eff.timer < introTime + holdTime then
                -- 中间段: 在 holdStart~holdEnd 之间缓慢循环
                local holdProgress = (eff.timer - introTime) / holdTime
                local holdRange = holdEnd - holdStart + 1
                eff.frameIdx = holdStart + math.floor(holdProgress * holdRange * 3) % holdRange
            else
                -- 后段: 从 holdEnd+1 播放到结束
                local outroElapsed = eff.timer - introTime - holdTime
                eff.frameIdx = math.min(frameCount - 1, holdEnd + 1 + math.floor(outroElapsed * fps))
            end

            -- 持续治疗己方单位 (每 healInterval 秒一次)
            if not eff.lastHealTime then eff.lastHealTime = 0 end
            if eff.timer - eff.lastHealTime >= skill.healInterval then
                eff.lastHealTime = eff.timer
                local healAmt = skill.healPerTick
                local sc = skill.color
                for _, u in ipairs(playerUnits) do
                    if u.alive then
                        local ddx = u.x - eff.x
                        local ddy = u.y - eff.y
                        if math.sqrt(ddx * ddx + ddy * ddy) <= skill.radius then
                            u.hp = math.min(u.maxHp or u.hp + healAmt, u.hp + healAmt)
                            -- 绿色回血浮字
                            AddFloatText(u.x, u.y - 12, "+" .. healAmt, 0.6, { 80, 230, 80 }, 16)
                        end
                    end
                end
            end

            -- 治疗粒子 (绿色上升)
            if math.random() < 0.35 then
                local sc = skill.color
                local angle = math.random() * 6.28
                local dist = skill.radius * 0.5 * math.random()
                AddParticle(eff.x + math.cos(angle) * dist, eff.y + math.sin(angle) * dist, {
                    vx = (math.random() - 0.5) * 20,
                    vy = -(math.random() * 25 + 15),
                    life = 0.5 + math.random() * 0.4,
                    size = 1.5 + math.random() * 2,
                    color = { sc[1], sc[2], sc[3] },
                })
            end

            -- 动画结束 >> 移除
            if eff.timer >= totalDur then
                table.remove(activeSkillEffects, i)
            end
        elseif skill.skillType == "zone" then
            -- ======== 区域技能(冰狱封疆): 中间帧延长 + 持续伤害 + 减速 ========
            local fps = 12
            local holdStart = 7
            local holdEnd   = 9
            local holdTime  = 3.0
            local introTime = (holdStart + 1) / fps
            local outroFrames = frameCount - holdEnd - 1
            local outroTime = outroFrames / fps
            local totalDurZ = introTime + holdTime + outroTime

            if eff.timer < introTime then
                eff.frameIdx = math.min(holdStart, math.floor(eff.timer * fps))
            elseif eff.timer < introTime + holdTime then
                local holdProgress = (eff.timer - introTime) / holdTime
                local holdRange = holdEnd - holdStart + 1
                eff.frameIdx = holdStart + math.floor(holdProgress * holdRange * 3) % holdRange
            else
                local outroElapsed = eff.timer - introTime - holdTime
                eff.frameIdx = math.min(frameCount - 1, holdEnd + 1 + math.floor(outroElapsed * fps))
            end

            -- 持续伤害 + 减速 (每 tickInterval 秒一次)
            if not eff.lastZoneTick then eff.lastZoneTick = 0 end
            if eff.timer - eff.lastZoneTick >= skill.tickInterval then
                eff.lastZoneTick = eff.timer
                local zoneLayerMul = 1 + ((skillLayers[eff.skillIdx] or 1) - 1) * 0.2
                local dmg = math.ceil(skill.dmgPerTick * zoneLayerMul)
                local sc = skill.color
                local zoneTargets = eff.isEnemySkill and playerUnits or enemyUnits
                for _, u in ipairs(zoneTargets) do
                    if u.alive then
                        local ddx = u.x - eff.x
                        local ddy = u.y - eff.y
                        if math.sqrt(ddx * ddx + ddy * ddy) <= skill.radius then
                            u.hp = u.hp - dmg
                            AddFloatText(u.x, u.y - 12, "-" .. dmg, 0.6, { 100, 180, 255 }, 14)
                            -- 标记减速 (每帧会被重置,只在zone存活期间生效)
                            u.zoneSlowUntil = gameState.gameTime + skill.tickInterval + 0.1
                            u.zoneSlowFactor = skill.slowFactor
                            if u.hp <= 0 then
                                u.hp = 0
                                u.alive = false
                            end
                        end
                    end
                end
            end

            -- 冰霜粒子 (蓝/青色)
            if math.random() < 0.4 then
                local angle = math.random() * 6.28
                local dist = skill.radius * 0.5 * math.random()
                AddParticle(eff.x + math.cos(angle) * dist, eff.y + math.sin(angle) * dist, {
                    vx = (math.random() - 0.5) * 15,
                    vy = -(math.random() * 20 + 10),
                    life = 0.5 + math.random() * 0.4,
                    size = 1.5 + math.random() * 2,
                    color = { 100 + math.random(80), 180 + math.random(60), 255 },
                })
            end

            -- 动画结束 >> 移除
            if eff.timer >= totalDurZ then
                table.remove(activeSkillEffects, i)
            end
        else
            -- ======== AOE/矩形技能: 固定位置爆发 ========
            local frameTime = eff.duration / frameCount
            eff.frameIdx = math.min(frameCount - 1, math.floor(eff.timer / frameTime))

            -- 在伤害帧触发范围伤害 (只触发一次)
            if not eff.damaged and eff.frameIdx >= skill.damageFrame then
                eff.damaged = true
                PlaySFX(AUDIO.sfx_hit)
                ApplySkillDamage(eff.x, eff.y, skill, eff.skillIdx, eff.isEnemySkill)
            end

            -- 矩形持续伤害 (夜影蚀径等: dmgPerTick + tickInterval)
            if skill.dmgPerTick and skill.tickInterval then
                if not eff.lastRectTick then eff.lastRectTick = 0 end
                if eff.timer - eff.lastRectTick >= skill.tickInterval then
                    eff.lastRectTick = eff.timer
                    local halfW = skill.rectW and (skill.rectW / 2) or skill.radius
                    local halfH = skill.rectH and (skill.rectH / 2) or skill.radius
                    local rectTargets = eff.isEnemySkill and playerUnits or enemyUnits
                    for _, u in ipairs(rectTargets) do
                        if u.alive then
                            local ddx = math.abs(u.x - eff.x)
                            local ddy = math.abs(u.y - eff.y)
                            if ddx <= halfW and ddy <= halfH then
                                local rectLayerMul = 1 + ((skillLayers[eff.skillIdx] or 1) - 1) * 0.2
                                local rectDmg = math.ceil(skill.dmgPerTick * rectLayerMul)
                                u.hp = u.hp - rectDmg
                                AddFloatText(u.x, u.y - 12, "-" .. rectDmg, 0.6, { 160, 80, 220 }, 14)
                                if u.hp <= 0 then u.hp = 0; u.alive = false end
                            end
                        end
                    end
                end
            end

            -- 每帧产生粒子 (矩形用矩形分布, AOE用圆形分布)
            if math.random() < 0.4 then
                local sc = skill.color
                local px, py
                if skill.skillType == "rect" then
                    px = eff.x + (math.random() - 0.5) * skill.rectW * 0.4
                    py = eff.y + (math.random() - 0.5) * skill.rectH * 0.4
                else
                    local angle = math.random() * 6.28
                    local dist = skill.radius * 0.4 * math.random()
                    px = eff.x + math.cos(angle) * dist
                    py = eff.y + math.sin(angle) * dist
                end
                AddParticle(px, py, {
                    vx = (math.random() - 0.5) * 40,
                    vy = -(math.random() * 30 + 10),
                    life = 0.3 + math.random() * 0.3,
                    size = 1.5 + math.random() * 2,
                    color = { sc[1], sc[2], sc[3] },
                })
            end

            -- 动画结束 >> 移除
            if eff.timer >= eff.duration then
                table.remove(activeSkillEffects, i)
            end
        end
        ::continue_fx::
    end
end

--- 对目标区域内的单位造成伤害 (isEnemy=true时伤害玩家单位)
function ApplySkillDamage(cx, cy, skill, skillIdx, isEnemySkill)
    local radius = skill.radius
    local layerMul = 1.0
    if skillIdx then
        local layer = skillLayers[skillIdx] or 1
        layerMul = 1 + (layer - 1) * 0.2  -- 每层+20%伤害
    end
    local baseDmg = math.ceil(skill.damage * layerMul)
    local hitCount = 0
    local isRect = skill.skillType == "rect"
    local halfW = isRect and (skill.rectW / 2) or 0
    local halfH = isRect and (skill.rectH / 2) or 0

    local dmgTargets = isEnemySkill and playerUnits or enemyUnits
    for _, u in ipairs(dmgTargets) do
        if u.alive then
            local ddx = u.x - cx
            local ddy = u.y - cy
            local inRange
            if isRect then
                inRange = math.abs(ddx) <= halfW and math.abs(ddy) <= halfH
            else
                inRange = math.sqrt(ddx * ddx + ddy * ddy) <= radius
            end
            if inRange then
                local dist = math.sqrt(ddx * ddx + ddy * ddy)
                local maxDist = isRect and math.sqrt(halfW * halfW + halfH * halfH) or radius
                -- 距离衰减: 中心全额, 边缘50%
                local falloff = 1.0 - (dist / maxDist) * 0.5
                local dmg = math.ceil(baseDmg * falloff)
                u.hp = u.hp - dmg
                u.flashTimer = 0.3

                -- 击飞微位移
                if dist > 1 then
                    u.x = u.x + (ddx / dist) * 8
                    u.y = u.y + (ddy / dist) * 8
                end

                local isCrit = math.random() < 0.15
                if isCrit then
                    dmg = math.ceil(dmg * 1.8)
                    u.hp = u.hp - math.ceil(baseDmg * falloff * 0.8)  -- 暴击额外伤害
                end

                AddFloatText(u.x, u.y - 12, math.floor(dmg) .. (isCrit and "!" or ""),
                    0.8, isCrit and { 255, 220, 50 } or { 255, 160, 60 },
                    isCrit and 28 or 22)

                -- 命中粒子
                for _ = 1, 4 do
                    AddParticle(u.x, u.y, {
                        vx = (math.random() - 0.5) * 80,
                        vy = -(math.random() * 40 + 10),
                        life = 0.4 + math.random() * 0.3,
                        size = 2 + math.random() * 2,
                        color = { 255, math.random(80, 160), 30 },
                    })
                end

                if u.hp <= 0 then
                    u.alive = false
                    if not isEnemySkill then
                        gameState.totalKills = gameState.totalKills + 1
                    end
                    -- 击杀爆炸粒子
                    for _ = 1, 10 do
                        AddParticle(u.x, u.y, {
                            vx = (math.random() - 0.5) * 140,
                            vy = -(math.random() * 70 + 15),
                            life = 0.6 + math.random() * 0.5,
                            size = 2.5 + math.random() * 3,
                            color = { 255, math.random(100, 200), 40 },
                        })
                    end
                end
                hitCount = hitCount + 1
            end
        end
    end

    if hitCount > 0 then
        AddFloatText(cx, cy - 80, "命中 " .. hitCount .. " 个目标!", 1.5, { 255, 200, 80 }, 18)
    else
        AddFloatText(cx, cy - 50, "未命中", 1.0, { 180, 160, 140 }, 14)
    end
end

--- 绘制技能序列帧的单帧 (设计坐标)
function DrawSkillFrame(cx, cy, renderW, frameIdx, alpha, techIdx)
    -- 根据技能的 iconIdx 查找对应的 FX 精灵图
    local skill = techIdx and SKILL_DEFS[techIdx]
    local iconIdx = skill and skill.iconIdx or 20
    local fxData = SKILL_FX_SHEETS[iconIdx]

    -- 有专属精灵图 >> 用 crop-aware 渲染
    if fxData and fxData.handle > 0 then
        local cols = fxData.cols
        local rows = fxData.rows
        local totalFrames = fxData.frames
        local fi = math.min(frameIdx % totalFrames, totalFrames - 1)
        local fcol = fi % cols
        local frow = math.floor(fi / cols)
        local crop = fxData.crop

        local imgW, imgH = nvgImageSize(vg, fxData.handle)
        local cellW = imgW / cols
        local cellH = imgH / rows

        -- crop 值基于原始图片尺寸, 需按实际尺寸缩放
        local cropScale = fxData.origW and (imgW / fxData.origW) or 1
        local srcX = fcol * cellW + crop.x * cropScale
        local srcY = frow * cellH + crop.y * cropScale
        local srcW = crop.w * cropScale
        local srcH = crop.h * cropScale

        -- 按宽度缩放, 确保可见宽度 == renderW (匹配瞄准圈直径)
        local contentScale = renderW / srcW
        local scaledW = renderW
        local scaledH = srcH * contentScale
        local centeredX = cx - scaledW / 2
        local centeredY = cy - scaledH / 2

        -- 逐帧视觉中心校正 (消除序列帧抖动)
        local offsets = fxData.frameOffsets
        if offsets then
            local fo = offsets[fi + 1]  -- Lua 1-based
            if fo then
                centeredX = centeredX + fo[1] * contentScale
                centeredY = centeredY + fo[2] * contentScale
            end
        end

        local patX = centeredX - srcX * contentScale
        local patY = centeredY - srcY * contentScale

        local pat = nvgImagePattern(vg, patX, patY, imgW * contentScale, imgH * contentScale, 0, fxData.handle, alpha)
        nvgBeginPath(vg)
        nvgRect(vg, centeredX, centeredY, scaledW, scaledH)
        nvgFillPaint(vg, pat)
        nvgFill(vg)
        return
    end

    -- 无专属精灵图 >> 通用粒子爆发效果 (基于技能颜色)
    local sc = skill and skill.color or { 255, 160, 60 }
    local progress = frameIdx / 15  -- 0~1
    local burstR = renderW * 0.4 * (0.3 + progress * 0.7)
    local burstAlpha = math.floor(255 * alpha * (1.0 - progress * 0.6))
    -- 外圈光晕
    local glow = nvgRadialGradient(vg, cx, cy, burstR * 0.2, burstR,
        nvgRGBA(sc[1], sc[2], sc[3], math.floor(burstAlpha * 0.6)),
        nvgRGBA(sc[1], sc[2], sc[3], 0))
    nvgBeginPath(vg); nvgCircle(vg, cx, cy, burstR)
    nvgFillPaint(vg, glow); nvgFill(vg)
    -- 内核
    local coreR = burstR * 0.3
    local coreGlow = nvgRadialGradient(vg, cx, cy, 0, coreR,
        nvgRGBA(255, 255, 255, math.floor(burstAlpha * 0.8)),
        nvgRGBA(sc[1], sc[2], sc[3], math.floor(burstAlpha * 0.3)))
    nvgBeginPath(vg); nvgCircle(vg, cx, cy, coreR)
    nvgFillPaint(vg, coreGlow); nvgFill(vg)
end

--- 绘制底层技能特效 (renderBehind=true, 在 DrawBattleUnits 之前调用)
function DrawGroundSkillEffects()
    for _, eff in ipairs(activeSkillEffects) do
        local skill = SKILL_DEFS[eff.skillIdx]
        if not skill or not skill.renderBehind then goto continue end

        local progress = eff.timer / eff.duration
        -- alpha: 渐入渐出
        local alpha = 1.0
        if progress < 0.15 then
            alpha = progress / 0.15
        elseif progress > 0.75 then
            alpha = (1.0 - progress) / 0.25
        end
        alpha = math.max(0, math.min(1, alpha))

        local sc = skill.color
        -- ======== 底层渲染: 柔和光圈 + 序列帧 ========
        local glowPulse = 0.4 + 0.3 * math.sin(eff.timer * 4)  -- 缓慢呼吸
        local isRectBehind = skill.skillType == "rect" and skill.rectW

        if isRectBehind then
            -- 矩形技能底层: 矩形光圈
            local rw = skill.rectW * (0.7 + progress * 0.3)
            local rh = skill.rectH * (0.7 + progress * 0.3)
            local rx, ry = eff.x - rw / 2, eff.y - rh / 2
            local groundGlow = nvgBoxGradient(vg, rx, ry, rw, rh, 10, rw * 0.3,
                nvgRGBA(sc[1], sc[2], sc[3], math.floor(35 * alpha * glowPulse)),
                nvgRGBA(sc[1], sc[2], sc[3], 0))
            nvgBeginPath(vg); nvgRoundedRect(vg, rx - rw * 0.15, ry - rh * 0.15, rw * 1.3, rh * 1.3, 10)
            nvgFillPaint(vg, groundGlow); nvgFill(vg)
            -- 序列帧
            DrawSkillFrame(eff.x, eff.y, rw, eff.frameIdx, alpha * 0.85, eff.skillIdx)
        else
            -- 圆形技能底层: 圆形光圈 (治疗/区域)
            local glowR = skill.radius * (0.7 + progress * 0.3)

            -- 底层柔光圈 (更大范围, 低透明度)
            local groundGlow = nvgRadialGradient(vg, eff.x, eff.y, glowR * 0.1, glowR * 1.2,
                nvgRGBA(sc[1], sc[2], sc[3], math.floor(35 * alpha * glowPulse)),
                nvgRGBA(sc[1], sc[2], sc[3], 0))
            nvgBeginPath(vg); nvgCircle(vg, eff.x, eff.y, glowR * 1.2)
            nvgFillPaint(vg, groundGlow); nvgFill(vg)

            -- 内层光圈 (较亮)
            local innerGlow = nvgRadialGradient(vg, eff.x, eff.y, glowR * 0.05, glowR * 0.7,
                nvgRGBA(sc[1], sc[2], sc[3], math.floor(50 * alpha * glowPulse)),
                nvgRGBA(sc[1], sc[2], sc[3], 0))
            nvgBeginPath(vg); nvgCircle(vg, eff.x, eff.y, glowR * 0.7)
            nvgFillPaint(vg, innerGlow); nvgFill(vg)

            -- 序列帧动画
            local effectDiameter = skill.radius * 2
            DrawSkillFrame(eff.x, eff.y, effectDiameter * (0.7 + progress * 0.3), eff.frameIdx, alpha * 0.85, eff.skillIdx)
        end

        ::continue::
    end
end

--- 绘制所有活跃的技能特效 (设计坐标, 在 DrawBattleUnits 之后调用)
function DrawSkillEffects()
    for _, eff in ipairs(activeSkillEffects) do
        local skill = SKILL_DEFS[eff.skillIdx]
        if not skill then goto continue end
        -- renderBehind 效果已在 DrawGroundSkillEffects 中绘制
        if skill.renderBehind then goto continue end
        local progress = eff.timer / eff.duration
        -- alpha: 渐入渐出
        local alpha = 1.0
        if progress < 0.15 then
            alpha = progress / 0.15
        elseif progress > 0.75 then
            alpha = (1.0 - progress) / 0.25
        end
        alpha = math.max(0, math.min(1, alpha))

        local sc = skill.color

        if eff.isLine then
            -- ======== 线型技能渲染: 竖向光带尾迹 ========
            local halfW = (skill.lineWidth or 50) / 2
            local trailLen = 80  -- 尾迹长度

            -- 光带主体 (从当前位置向后拖尾, AI技能反向)
            local headY = eff.y
            local tailY
            if eff.isEnemySkill then
                tailY = math.max(headY - trailLen, BATTLE_ZONE.enemyLine)
            else
                tailY = math.min(headY + trailLen, BATTLE_ZONE.playerLine)
            end
            local glowPulse = 0.7 + 0.3 * math.sin(eff.timer * 10)
            local bodyAlpha = math.floor(50 * alpha * glowPulse)

            -- 光带渐变 (头部亮, 尾部暗)
            local gradY1 = math.min(headY, tailY)
            local gradY2 = math.max(headY, tailY)
            local grad
            if eff.isEnemySkill then
                grad = nvgLinearGradient(vg, eff.x, headY, eff.x, tailY,
                    nvgRGBA(sc[1], sc[2], sc[3], math.floor(bodyAlpha * 1.2)),
                    nvgRGBA(sc[1], sc[2], sc[3], 0))
            else
                grad = nvgLinearGradient(vg, eff.x, headY, eff.x, tailY,
                    nvgRGBA(sc[1], sc[2], sc[3], math.floor(bodyAlpha * 1.2)),
                    nvgRGBA(sc[1], sc[2], sc[3], 0))
            end
            nvgBeginPath(vg)
            nvgRect(vg, eff.x - halfW, gradY1, halfW * 2, gradY2 - gradY1)
            nvgFillPaint(vg, grad); nvgFill(vg)

            -- 头部高亮光晕
            local headGlow = nvgRadialGradient(vg, eff.x, headY, 5, halfW * 1.5,
                nvgRGBA(sc[1], sc[2], sc[3], math.floor(100 * alpha * glowPulse)),
                nvgRGBA(sc[1], sc[2], sc[3], 0))
            nvgBeginPath(vg); nvgCircle(vg, eff.x, headY, halfW * 1.5)
            nvgFillPaint(vg, headGlow); nvgFill(vg)

            -- 序列帧动画 (在弹头位置绘制)
            local frameSize = skill.renderSize * (0.8 + 0.2 * glowPulse)
            DrawSkillFrame(eff.x, eff.y, frameSize, eff.frameIdx, alpha, eff.skillIdx)
        elseif skill.skillType == "rect" then
            -- ======== 矩形技能渲染: 矩形光框 + 序列帧 ========
            local rw, rh = skill.rectW, skill.rectH
            local glowPulse = 0.5 + 0.5 * math.sin(eff.timer * 8)
            local rectScale = 0.6 + progress * 0.4
            local gw, gh = rw * rectScale, rh * rectScale

            -- 矩形范围光晕
            local rx, ry = eff.x - gw / 2, eff.y - gh / 2
            local grad = nvgLinearGradient(vg, rx, ry, rx, ry + gh,
                nvgRGBA(sc[1], sc[2], sc[3], math.floor(50 * alpha * glowPulse)),
                nvgRGBA(sc[1], sc[2], sc[3], math.floor(15 * alpha * glowPulse)))
            nvgBeginPath(vg); nvgRect(vg, rx, ry, gw, gh)
            nvgFillPaint(vg, grad); nvgFill(vg)

            -- 矩形边框
            nvgBeginPath(vg); nvgRect(vg, rx, ry, gw, gh)
            nvgStrokeColor(vg, nvgRGBA(sc[1], sc[2], sc[3], math.floor(40 * alpha * glowPulse)))
            nvgStrokeWidth(vg, 1.0); nvgStroke(vg)

            -- 序列帧动画 (用矩形宽度匹配)
            local fxScale = 0.7 + progress * 0.3
            DrawSkillFrame(eff.x, eff.y, rw * fxScale, eff.frameIdx, alpha, eff.skillIdx)
        else
            -- ======== AOE技能渲染: 圆形光圈 + 序列帧 ========
            -- 底部光圈(范围指示, 使用技能颜色)
            local glowPulse = 0.5 + 0.5 * math.sin(eff.timer * 8)
            local glowR = skill.radius * (0.6 + progress * 0.4)
            local glow = nvgRadialGradient(vg, eff.x, eff.y, glowR * 0.2, glowR,
                nvgRGBA(sc[1], sc[2], sc[3], math.floor(60 * alpha * glowPulse)),
                nvgRGBA(sc[1], sc[2], sc[3], 0))
            nvgBeginPath(vg); nvgCircle(vg, eff.x, eff.y, glowR)
            nvgFillPaint(vg, glow); nvgFill(vg)

            -- 序列帧动画 (用 radius*2 匹配瞄准圈直径)
            local effectDiameter = skill.radius * 2
            DrawSkillFrame(eff.x, eff.y, effectDiameter * (0.7 + progress * 0.3), eff.frameIdx, alpha, eff.skillIdx)
        end
        ::continue::
    end
end

--- 绘制技能瞄准指示器 (设计坐标, 拖拽中调用)
function DrawSkillTargetingDesign()
    if not skillTargeting.active then return end
    local skill = SKILL_DEFS[skillTargeting.skillIdx]
    if not skill then return end

    local tx, ty = skillTargeting.dx, skillTargeting.dy
    local bz = BATTLE_ZONE
    local t = gameState.gameTime

    -- 检查是否在战场范围内
    local inZone = tx >= bz.left and tx <= bz.right
        and ty >= bz.enemyLine and ty <= bz.playerLine

    local baseAlpha = inZone and 180 or 80
    local pulseAlpha = math.floor(baseAlpha * (0.6 + 0.4 * math.sin(t * 5)))

    if skill.skillType == "line" then
        -- ======== 线型技能瞄准: 高亮整条车道 ========
        local laneIdx = math.floor((tx - bz.left) / LANE_WIDTH) + 1
        laneIdx = math.max(1, math.min(NUM_LANES, laneIdx))
        local laneCX = GetLaneCenterX(laneIdx)
        local laneLeft = bz.left + (laneIdx - 1) * LANE_WIDTH
        local laneTop = bz.enemyLine
        local laneBot = bz.playerLine
        local laneH = laneBot - laneTop
        local pulse = 0.6 + 0.4 * math.sin(t * 5)

        if inZone then
            -- 车道背景高亮
            local grad = nvgLinearGradient(vg, laneCX, laneTop, laneCX, laneBot,
                nvgRGBA(255, 120, 40, math.floor(55 * pulse)),
                nvgRGBA(255, 80, 20, math.floor(20 * pulse)))
            nvgBeginPath(vg)
            nvgRect(vg, laneLeft, laneTop, LANE_WIDTH, laneH)
            nvgFillPaint(vg, grad); nvgFill(vg)

            -- 车道边框
            nvgBeginPath(vg)
            nvgRect(vg, laneLeft, laneTop, LANE_WIDTH, laneH)
            nvgStrokeColor(vg, nvgRGBA(255, 140, 60, math.floor(pulseAlpha * 0.8)))
            nvgStrokeWidth(vg, 1.5); nvgStroke(vg)

            -- 箭头指示 (从下向上的方向箭头)
            local arrowX = laneCX
            for ay = laneBot - 40, laneTop + 20, -80 do
                local aAlpha = math.floor(120 * pulse * (1.0 - (laneBot - ay) / laneH))
                nvgBeginPath(vg)
                nvgMoveTo(vg, arrowX - 8, ay + 8)
                nvgLineTo(vg, arrowX, ay - 4)
                nvgLineTo(vg, arrowX + 8, ay + 8)
                nvgStrokeColor(vg, nvgRGBA(255, 200, 100, math.max(30, aAlpha)))
                nvgStrokeWidth(vg, 1.5); nvgStroke(vg)
            end
        else
            -- 超出范围: 淡色提示
            nvgBeginPath(vg)
            nvgRect(vg, laneLeft, laneTop, LANE_WIDTH, laneH)
            nvgFillColor(vg, nvgRGBA(150, 130, 110, math.floor(15 * pulse)))
            nvgFill(vg)
        end

        -- 技能名 (显示在车道顶部)
        if fontId >= 0 then
            nvgFontFaceId(vg, GetMainFont())
            nvgFontSize(vg, 15)
            nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_BOTTOM)
            nvgFillColor(vg, nvgRGBA(255, 200, 100, pulseAlpha))
            nvgText(vg, laneCX, laneTop - 6, skill.name, nil)
        end
    elseif skill.skillType == "rect" then
        -- ======== 矩形技能瞄准: 矩形范围框 ========
        local rw, rh = skill.rectW, skill.rectH
        local rx, ry = tx - rw / 2, ty - rh / 2
        local pulse = 0.6 + 0.4 * math.sin(t * 5)

        nvgBeginPath(vg); nvgRect(vg, rx, ry, rw, rh)
        nvgStrokeWidth(vg, 1.5)
        if inZone then
            nvgStrokeColor(vg, nvgRGBA(255, 120, 40, pulseAlpha))
            -- 填充淡色渐变
            local fill = nvgLinearGradient(vg, rx, ry, rx, ry + rh,
                nvgRGBA(255, 100, 30, math.floor(50 * pulse)),
                nvgRGBA(255, 60, 10, math.floor(15 * pulse)))
            nvgFillPaint(vg, fill); nvgFill(vg)
        else
            nvgStrokeColor(vg, nvgRGBA(180, 150, 130, math.floor(pulseAlpha * 0.5)))
        end
        nvgStroke(vg)

        -- 十字准星
        local crossSize = 10
        nvgBeginPath(vg)
        nvgMoveTo(vg, tx - crossSize, ty); nvgLineTo(vg, tx + crossSize, ty)
        nvgMoveTo(vg, tx, ty - crossSize); nvgLineTo(vg, tx, ty + crossSize)
        nvgStrokeColor(vg, nvgRGBA(255, 220, 100, pulseAlpha))
        nvgStrokeWidth(vg, 1.0); nvgStroke(vg)

        -- 技能名
        if fontId >= 0 then
            nvgFontFaceId(vg, GetMainFont())
            nvgFontSize(vg, 15)
            nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_BOTTOM)
            nvgFillColor(vg, nvgRGBA(255, 200, 100, pulseAlpha))
            nvgText(vg, tx, ry - 6, skill.name, nil)
        end
    else
        -- ======== AOE技能瞄准: 范围圈 ========
        -- 范围圈
        nvgBeginPath(vg); nvgCircle(vg, tx, ty, skill.radius)
        nvgStrokeWidth(vg, 1.5)
        if inZone then
            nvgStrokeColor(vg, nvgRGBA(255, 120, 40, pulseAlpha))
            -- 填充淡色
            local fill = nvgRadialGradient(vg, tx, ty, 5, skill.radius,
                nvgRGBA(255, 100, 30, math.floor(40 * (0.6 + 0.4 * math.sin(t * 5)))),
                nvgRGBA(255, 60, 10, 0))
            nvgFillPaint(vg, fill); nvgFill(vg)
        else
            nvgStrokeColor(vg, nvgRGBA(180, 150, 130, math.floor(pulseAlpha * 0.5)))
        end
        nvgStroke(vg)

        -- 十字准星
        local crossSize = 10
        nvgBeginPath(vg)
        nvgMoveTo(vg, tx - crossSize, ty); nvgLineTo(vg, tx + crossSize, ty)
        nvgMoveTo(vg, tx, ty - crossSize); nvgLineTo(vg, tx, ty + crossSize)
        nvgStrokeColor(vg, nvgRGBA(255, 220, 100, pulseAlpha))
        nvgStrokeWidth(vg, 1.0); nvgStroke(vg)

        -- 技能名
        if fontId >= 0 then
            nvgFontFaceId(vg, GetMainFont())
            nvgFontSize(vg, 15)
            nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_BOTTOM)
            nvgFillColor(vg, nvgRGBA(255, 200, 100, pulseAlpha))
            nvgText(vg, tx, ty - skill.radius - 6, skill.name, nil)
        end
    end
end

-- ============================================================================
-- 抽卡系统 (广告驱动)
-- ============================================================================

--- 按权重随机选一张卡的 cardIdx
function RandomDrawCard()
    -- 1. 按品质概率表决定本次抽到哪个品质
    local weights = GameConfig.DRAW_QUALITY_WEIGHTS
    local totalW = 0
    for q = 1, 4 do totalW = totalW + (weights[q] or 0) end

    local r = math.random() * totalW
    local cumW = 0
    local targetQuality = 1
    for q = 1, 4 do
        cumW = cumW + (weights[q] or 0)
        if r <= cumW then
            targetQuality = q
            break
        end
    end

    -- 2. 从该品质的武灵中随机选一个
    -- 教程期间排除初始武灵 (确保抽到新角色)
    local excludeSet = nil
    if tutorialState.active then
        excludeSet = {}
        for _, id in ipairs(GameConfig.INITIAL_HEROES) do
            excludeSet[id] = true
        end
    end

    local pool = {}
    for idx, card in ipairs(HERO_CARDS) do
        if card.quality == targetQuality then
            if not excludeSet or not excludeSet[idx] then
                table.insert(pool, idx)
            end
        end
    end

    -- 安全回退: 若该品质无武灵，从全池中选(排除初始武灵和限定SSR)
    if #pool == 0 then
        for idx, card in ipairs(HERO_CARDS) do
            if card.quality ~= QUALITY.LIMITED then
                if not excludeSet or not excludeSet[idx] then
                    table.insert(pool, idx)
                end
            end
        end
    end

    if #pool == 0 then
        -- 极端回退: 从非限定池中随机
        local safePool = {}
        for idx, card in ipairs(HERO_CARDS) do
            if card.quality ~= QUALITY.LIMITED then table.insert(safePool, idx) end
        end
        if #safePool > 0 then return safePool[math.random(1, #safePool)] end
        return math.random(1, #HERO_CARDS)
    end

    return pool[math.random(1, #pool)]
end

--- 执行抽卡 (count 次, 消耗虎符, 残片/整卡混合产出)
--- 大概率出残片(1~5个), 极小概率出整卡
--- @param count number 抽卡次数 (1 或 10)
--- @param forceCardIdx number|nil 强制指定出整卡(新手引导用)
function ExecuteGachaPull(count, forceCardIdx)
    local cost
    if count >= 10 then
        cost = math.floor(GameConfig.GACHA_COST_SINGLE * count * 0.9)  -- 10连及以上享9折
    else
        cost = GameConfig.GACHA_COST_SINGLE * count
    end
    if playerInfo.jade < cost then
        AddFloatText(DESIGN_W / 2, DESIGN_H * 0.45, "虎符不足!", 1.2, { 255, 100, 100 }, 14)
        return false
    end

    playerInfo.jade = playerInfo.jade - cost
    gachaState.results = {}

    local totalJadeRefund = 0

    for pullI = 1, count do
        gachaState.pityCounter = gachaState.pityCounter + 1

        -- 决定本次抽取的武灵
        local cardIdx
        local isPityTriggered = false  -- 75抽保底是否触发
        local isFullCardForced = false -- 保底强制整卡标记
        if forceCardIdx and pullI == 1 then
            -- 新手引导强制指定
            cardIdx = forceCardIdx
            isFullCardForced = true
        elseif gachaState.pityCounter >= GameConfig.PITY_SSR_COUNT then
            -- ★ 75抽保底: 必出整卡, 普通:SSR = 7:3 (排除限定SSR)
            isPityTriggered = true
            local roll = math.random(1, 10)
            if roll <= 3 then
                -- 30% SSR整卡 (仅普通SSR, 排除限定)
                local ssrCards = {}
                for ci, c in ipairs(HERO_CARDS) do
                    if c.quality == QUALITY.LEGENDARY then table.insert(ssrCards, ci) end
                end
                cardIdx = ssrCards[math.random(1, #ssrCards)]
            else
                -- 70% 普通整卡(非SSR, 排除限定SSR)
                local normalCards = {}
                for ci, c in ipairs(HERO_CARDS) do
                    if c.quality ~= QUALITY.LEGENDARY and c.quality ~= QUALITY.LIMITED then
                        table.insert(normalCards, ci)
                    end
                end
                cardIdx = normalCards[math.random(1, #normalCards)]
            end
            isFullCardForced = true
            gachaState.pityCounter = 0  -- 保底触发立即重置
            print("[抽卡] 75抽保底触发! 强制出整卡(普通:SSR=7:3, roll=" .. roll .. ")")
        else
            cardIdx = RandomDrawCard()
        end

        local card = HERO_CARDS[cardIdx]

        -- 判断是出整卡还是残片
        local isFullCard = false
        if isFullCardForced then
            -- 保底/新手引导: 强制整卡
            isFullCard = true
        else
            -- 正常抽取: HERO_FULL_CARD_RATE% 概率整卡
            isFullCard = (math.random(1, 100) <= HERO_FULL_CARD_RATE)
        end

        if isFullCard then
            -- ★ 整卡产出
            local hero = playerHeroes[cardIdx]
            local result = {
                cardIdx = cardIdx, isFullCard = true, fragCount = 0,
                isNew = false, oldConst = 0, constellation = 0, jadeRefund = 0,
            }
            if hero and hero.owned then
                result.oldConst = hero.constellation
                if hero.constellation >= GameConfig.MAX_CONSTELLATION then
                    local refund = GameConfig.DUPLICATE_JADE_REWARD[card.quality] or 1
                    result.jadeRefund = refund
                    totalJadeRefund = totalJadeRefund + refund
                    result.constellation = hero.constellation
                else
                    hero.constellation = hero.constellation + 1
                    result.constellation = hero.constellation
                end
            else
                playerHeroes[cardIdx] = { owned = true, constellation = 0 }
                result.isNew = true
                result.constellation = 0
            end
            table.insert(gachaState.results, result)

            -- 保底重置已在触发时处理; 非保底情况下不额外重置
        else
            -- ★ 残片产出: 1~5个残片
            local fragCount = math.random(1, 5)
            heroFragments[cardIdx] = (heroFragments[cardIdx] or 0) + fragCount
            local result = {
                cardIdx = cardIdx, isFullCard = false, fragCount = fragCount,
                totalFrags = heroFragments[cardIdx],
                isNew = false, oldConst = 0, constellation = 0, jadeRefund = 0,
            }
            table.insert(gachaState.results, result)
        end
    end

    -- 返还满命格重复角色的虎符
    if totalJadeRefund > 0 then
        playerInfo.jade = playerInfo.jade + totalJadeRefund
        AddFloatText(DESIGN_W / 2, DESIGN_H * 0.38, "满命格返还 " .. totalJadeRefund .. " 虎符!", 1.5, { 255, 215, 0 }, 16)
    end

    -- 启动召唤动画
    gachaState.pulling = true
    gachaState.pullTimer = 0
    gachaState.pullCount = count
    gachaState.showResults = false

    -- 任务追踪
    playerInfo.totalGachas = playerInfo.totalGachas + count
    TrackDailyTask("gacha1", count)
    TrackWeeklyTask("wgacha5", count)
    TrackBattlePassTask("bp_gacha1", count)
    TrackBattlePassTask("bp_wgacha5", count)
    TrackBattlePassTask("bp_sgacha30", count)

    print("[抽卡] 消耗 " .. cost .. " 虎符, 抽取 " .. count .. " 次")
    return true
end

-- ============================================================================
-- 限定池抽取 (只出碎片, 无整卡, 限定SSR碎片唯一来源)
-- ============================================================================

--- 限定池随机抽取: 按 LIMITED_DRAW_WEIGHTS 决定品质, 然后随机该品质武灵
function RandomDrawLimitedCard()
    local weights = LIMITED_DRAW_WEIGHTS
    local totalW = 0
    for q = 1, 5 do totalW = totalW + (weights[q] or 0) end

    local r = math.random() * totalW
    local cumW = 0
    local targetQuality = 2  -- 默认R
    for q = 1, 5 do
        cumW = cumW + (weights[q] or 0)
        if r <= cumW then
            targetQuality = q
            break
        end
    end

    local pool = {}
    for idx, card in ipairs(HERO_CARDS) do
        if card.quality == targetQuality then
            table.insert(pool, idx)
        end
    end

    -- 安全回退
    if #pool == 0 then
        for idx, card in ipairs(HERO_CARDS) do
            if card.quality >= QUALITY.RARE then
                table.insert(pool, idx)
            end
        end
    end
    if #pool == 0 then return math.random(1, #HERO_CARDS) end
    return pool[math.random(1, #pool)]
end

--- 执行限定池抽取 (全碎片产出, 30抽保底限定碎片)
--- @param count number 抽取次数 (1 或 10)
function ExecuteLimitedGachaPull(count)
    local cost
    if count >= 10 then
        cost = math.floor(LIMITED_GACHA_COST * count * 0.9)  -- 10连及以上享9折
    else
        cost = LIMITED_GACHA_COST * count
    end
    if playerInfo.jade < cost then
        AddFloatText(DESIGN_W / 2, DESIGN_H * 0.45, "虎符不足!", 1.2, { 255, 100, 100 }, 14)
        return false
    end

    playerInfo.jade = playerInfo.jade - cost
    gachaState.limitedResults = {}

    local totalJadeRefund = 0

    for pullI = 1, count do
        gachaState.limitedPityCounter = gachaState.limitedPityCounter + 1

        local cardIdx
        local isPityTriggered = false

        -- 30抽保底: 必出限定SSR碎片
        if gachaState.limitedPityCounter >= LIMITED_PITY_FRAG_COUNT then
            isPityTriggered = true
            -- 从限定SSR池中随机
            local limitedPool = {}
            for idx, card in ipairs(HERO_CARDS) do
                if card.quality == QUALITY.LIMITED then
                    table.insert(limitedPool, idx)
                end
            end
            cardIdx = #limitedPool > 0 and limitedPool[math.random(1, #limitedPool)] or RandomDrawLimitedCard()
            print("[限定池] 保底触发! 必出限定SSR碎片")
        else
            cardIdx = RandomDrawLimitedCard()
        end

        local card = HERO_CARDS[cardIdx]

        -- 限定池只出碎片, 无整卡
        local fragCount
        if isPityTriggered then
            fragCount = math.random(LIMITED_FRAG_GUARANTEE_MIN, LIMITED_FRAG_GUARANTEE_MAX)  -- 保底给6~8碎片
        elseif card.quality == QUALITY.LIMITED then
            fragCount = math.random(3, 6)  -- 限定SSR碎片多给
        elseif card.quality == QUALITY.LEGENDARY then
            fragCount = math.random(2, 5)  -- SSR碎片
        else
            fragCount = math.random(1, 4)  -- 普通碎片
        end

        heroFragments[cardIdx] = (heroFragments[cardIdx] or 0) + fragCount

        local result = {
            cardIdx = cardIdx, isFullCard = false, fragCount = fragCount,
            totalFrags = heroFragments[cardIdx],
            isNew = false, oldConst = 0, constellation = 0, jadeRefund = 0,
            isPity = isPityTriggered,
        }
        table.insert(gachaState.limitedResults, result)

        -- 保底重置
        if isPityTriggered or card.quality == QUALITY.LIMITED then
            gachaState.limitedPityCounter = 0
        end
    end

    -- 启动召唤动画 (复用武灵池动画)
    gachaState.pulling = true
    gachaState.pullTimer = 0
    gachaState.pullCount = count
    gachaState.showResults = false

    -- 任务追踪
    playerInfo.totalGachas = playerInfo.totalGachas + count
    TrackDailyTask("gacha1", count)
    TrackWeeklyTask("wgacha5", count)
    TrackBattlePassTask("bp_gacha1", count)
    TrackBattlePassTask("bp_wgacha5", count)
    TrackBattlePassTask("bp_sgacha30", count)

    print("[限定池] 消耗 " .. cost .. " 虎符, 抽取 " .. count .. " 次")
    return true
end

-- ============================================================================
-- 武技残片抽取
-- ============================================================================

--- 武技残片品质权重 (tier → 权重, 与 SKILL_TIERS 7阶对齐)
--- 凡品52.5% 良品25% 优品15% 将品5% 侯品2% 王品0.4% 帝品0.1%
SKILL_FRAG_WEIGHTS = {
    [1] = 525,  -- 凡品   52.5%
    [2] = 250,  -- 良品   25%
    [3] = 150,  -- 优品   15%
    [4] = 50,   -- 将品   5%
    [5] = 20,   -- 侯品   2%
    [6] = 4,    -- 王品   0.4%
    [7] = 1,    -- 帝品   0.1%
}
SKILL_FRAG_EXCHANGE = 49  -- 49残片兑换一个完整武技
SKILL_FRAG_PER_PULL = 5   -- 单抽出5个残片

--- 战斗胜利掉落武技残片 (按关卡maxTier影响掉落品质)
--- @param maxTier number 关卡最高掉落阶级(1-6)
--- @return table[] fragDrops 掉落列表 { {skillIdx, skillName, tierName, tierColor} ... }
function GenerateBattleSkillFragDrop(maxTier)
    local fragDrops = {}
    -- 掉落数量: 1-3个残片, 高关卡倾向更多
    local dropCount = 1
    local roll = math.random(1, 100)
    if maxTier >= 4 then
        dropCount = roll <= 40 and 3 or (roll <= 75 and 2 or 1)
    elseif maxTier >= 2 then
        dropCount = roll <= 30 and 2 or 1
    end
    for _ = 1, dropCount do
        -- 构建受maxTier影响的权重池: 关卡越高, 高阶残片权重略增
        local pool = {}
        local totalW = 0
        for idx, tech in ipairs(SKILL_TECHNIQUES) do
            local baseW = SKILL_FRAG_WEIGHTS[tech.tier] or 10
            -- maxTier以下的阶级保持原权重, 以上的轻微提升
            if tech.tier <= maxTier then
                baseW = baseW + math.floor(maxTier * 0.5)
            end
            totalW = totalW + baseW
            table.insert(pool, { idx = idx, weight = baseW, cumWeight = totalW })
        end
        local r = math.random() * totalW
        local chosen = pool[1].idx
        for _, p in ipairs(pool) do
            if r <= p.cumWeight then chosen = p.idx; break end
        end
        skillFragments[chosen] = (skillFragments[chosen] or 0) + 1
        local tech = SKILL_TECHNIQUES[chosen]
        local tier = SKILL_TIERS[tech.tier]
        table.insert(fragDrops, {
            skillIdx = chosen,
            skillName = tech.name,
            tierName = tier.name,
            tierColor = tier.color,
        })
    end
    return fragDrops
end

--- 按权重随机选一个武技
function RandomDrawSkillFragment()
    -- 构建权重池
    local pool = {}
    local totalWeight = 0
    for idx, tech in ipairs(SKILL_TECHNIQUES) do
        local w = SKILL_FRAG_WEIGHTS[tech.tier] or 10
        totalWeight = totalWeight + w
        table.insert(pool, { idx = idx, weight = w, cumWeight = totalWeight })
    end
    local roll = math.random() * totalWeight
    for _, entry in ipairs(pool) do
        if roll <= entry.cumWeight then
            return entry.idx
        end
    end
    return 1
end

--- 执行武技残片抽取 (count=1单抽出5个残片, count=10十连出50个残片)
function ExecuteSkillGachaPull(count)
    local cost
    if count >= 10 then
        cost = math.floor(GameConfig.GACHA_COST_SINGLE * count * 0.9)  -- 10连及以上享9折
    else
        cost = GameConfig.GACHA_COST_SINGLE * count
    end
    if playerInfo.jade < cost then
        AddFloatText(DESIGN_W / 2, DESIGN_H * 0.45, "虎符不足!", 1.2, { 255, 100, 100 }, 14)
        return false
    end

    playerInfo.jade = playerInfo.jade - cost
    gachaState.skillResults = {}

    local totalFrags = SKILL_FRAG_PER_PULL * count  -- 单抽5个, 十连50个
    -- 随机抽出所有残片, 合并同类 (无保底, 纯概率)
    local fragMap = {}
    for _ = 1, totalFrags do
        local skillIdx = RandomDrawSkillFragment()
        fragMap[skillIdx] = (fragMap[skillIdx] or 0) + 1
    end

    -- 转为结果列表
    for skillIdx, fragCount in pairs(fragMap) do
        -- 累加到玩家残片库
        skillFragments[skillIdx] = (skillFragments[skillIdx] or 0) + fragCount
        table.insert(gachaState.skillResults, {
            skillIdx = skillIdx,
            fragCount = fragCount,
            totalFrags = skillFragments[skillIdx],
            isPity = false,
        })
    end
    -- 按tier从高到低排序（稀有的在前面）
    table.sort(gachaState.skillResults, function(a, b)
        local ta = SKILL_TECHNIQUES[a.skillIdx].tier
        local tb = SKILL_TECHNIQUES[b.skillIdx].tier
        if ta ~= tb then return ta > tb end
        return a.skillIdx < b.skillIdx
    end)

    -- 启动召唤动画
    gachaState.pulling = true
    gachaState.pullTimer = 0
    gachaState.pullCount = count
    gachaState.showResults = false

    -- 任务追踪
    playerInfo.totalGachas = playerInfo.totalGachas + count
    TrackDailyTask("gacha1", count)
    TrackWeeklyTask("wgacha5", count)
    TrackBattlePassTask("bp_gacha1", count)
    TrackBattlePassTask("bp_wgacha5", count)
    TrackBattlePassTask("bp_sgacha30", count)

    print("[武技抽取] 消耗 " .. cost .. " 虎符, 获得 " .. totalFrags .. " 个残片")
    return true
end

-- ============================================================================
-- 合成系统
-- ============================================================================

--- 在背包中查找可合成的配对 (同角色同命格, 且命格 < MAX)
function FindMergeableIndex(targetInvIdx)
    local item = inventory[targetInvIdx]
    if not item then return nil end
    if item.constellation >= GameConfig.MAX_CONSTELLATION then return nil end
    for i, other in ipairs(inventory) do
        if i ~= targetInvIdx and
           other.cardIdx == item.cardIdx and
           other.constellation == item.constellation then
            return i
        end
    end
    return nil
end

--- 检测某张背包卡是否可合成
function IsMergeable(invIdx)
    return FindMergeableIndex(invIdx) ~= nil
end

--- 执行合成: 两张同角色同命格 >> 一张更高命格
function TryMergeCard(invIdx)
    local pairIdx = FindMergeableIndex(invIdx)
    if not pairIdx then
        AddFloatText(DESIGN_W / 2, DESIGN_H * 0.85, "无法合成", 1.0, { 255, 120, 80 }, 13)
        return false
    end
    local item = inventory[invIdx]
    local newConst = item.constellation + 1
    local cardName = HERO_CARDS[item.cardIdx].name

    -- 移除配对 (先移除较大索引, 避免索引偏移)
    local removeFirst = math.max(invIdx, pairIdx)
    local removeSecond = math.min(invIdx, pairIdx)
    table.remove(inventory, removeFirst)
    table.remove(inventory, removeSecond)

    -- 添加新卡
    table.insert(inventory, { cardIdx = item.cardIdx, constellation = newConst })

    AddFloatText(DESIGN_W / 2, DESIGN_H * 0.85,
        cardName .. " >> C" .. newConst .. " !", 1.5, { 200, 160, 255 }, 15)
    print("[合成] " .. cardName .. " C" .. (newConst - 1) .. " >> C" .. newConst)
    return true
end

-- ============================================================================
-- 战斗单位
-- ============================================================================

function GetUnitClassForCard(card, isPlayer)
    if isPlayer then return UNIT_CLASS[card.unitClass] or UNIT_CLASS.SWORD
    elseif gameState.isRanked then return UNIT_CLASS[card.unitClass] or UNIT_CLASS.SWORD
    else return UNIT_CLASS[card.unitClass] or UNIT_CLASS.DEMON_WARRIOR end
end

function SpawnPlayerUnit()
    if #playerUnits >= GetPlayerUnitCap() then return end
    local filledSlots = {}
    for si, slot in ipairs(PLAYER_SLOTS) do
        if slot.filled and slot.card then table.insert(filledSlots, { slot = slot, idx = si }) end
    end

    local uc, atk, def, hp, breakDmgAdd
    breakDmgAdd = 0
    if #filledSlots > 0 then
        -- ★ 站位加成：放对位置的武灵出兵概率更高（加权随机）
        -- 前排(1-3)适合近战，后排(4-8)适合远程/治疗，夜影刺客任意
        local weights = {}
        local totalW = 0
        for i, entry in ipairs(filledSlots) do
            local isFront = (entry.idx <= 3)
            local ucN = (entry.slot.card.unitClass or "SWORD")
            local w = 1.0  -- 默认权重
            if ucN == "SHIELD" or ucN == "CAVALRY" or ucN == "LANCER" or ucN == "BEAST" or ucN == "SWORD" then
                w = isFront and 1.5 or 0.8   -- 近战放前排概率+50%，放后排概率-20%
            elseif ucN == "ARCHER" or ucN == "MAGE" or ucN == "ICE_MAGE" then
                w = isFront and 0.8 or 1.5   -- 远程放后排概率+50%，放前排概率-20%
            elseif ucN == "HEALER" or ucN == "PUPPETEER" then
                w = isFront and 0.7 or 1.6   -- 军医道士/驯兽使放后排概率+60%
            elseif ucN == "ASSASSIN" then
                w = 1.2                       -- 夜影刺客任意位置略高
            elseif ucN == "TALISMAN" or ucN == "SWARM" then
                w = isFront and 1.4 or 0.9   -- 火牛突袭/蜂巢蝗群偏前排（冲锋/近战虫群）
            end
            weights[i] = w
            totalW = totalW + w
        end
        -- 加权随机选择
        local roll = math.random() * totalW
        local pickIdx = 1
        local acc = 0
        for i, w in ipairs(weights) do
            acc = acc + w
            if roll <= acc then pickIdx = i; break end
        end

        local pick = filledSlots[pickIdx]
        local slot = pick.slot
        local card = slot.card
        local lm = 1 + ((card.level or 1) - 1) * GameConfig.LEVEL_GROWTH_RATE
        uc = GetUnitClassForCard(card, true)
        -- 应用命格加成
        local cStats = ApplyConstellationStats(card)
        -- 应用装备百分比增幅
        local eqB = GetEquipmentBonus()
        cachedEqBonus = eqB  -- 缓存供单位属性注入
        local ss = SOLDIER_STAT_SCALE
        atk = cStats.atk * (1 + eqB.atkPct / 100) * lm * ss
        def = cStats.def * (1 + eqB.defPct / 100) * lm * ss * 0.5
        hp  = cStats.hp  * (1 + eqB.hpPct / 100)  * lm * ss * 0.6
        breakDmgAdd = cStats.breakDmgAdd or 0
    else
        uc = UNIT_CLASS.SWORD; atk = 56; def = 14; hp = 180
    end

    local bz = BATTLE_ZONE
    local unit = {
        x = bz.left + 20 + math.random() * (bz.right - bz.left - 40),
        y = bz.bottom - 10 - math.random() * 20,
        hp = hp, maxHp = hp, atk = atk, def = def,
        speed = uc.speed + math.random() * 6,
        atkTimer = math.random() * 0.5, atkCooldown = uc.atkCd,
        atkRange = uc.atkRange,
        alive = true, isPlayer = true,
        isRanged = uc.isRanged, unitClass = uc,
        animTimer = math.random() * 6.28, flashTimer = 0,
        isHealer = (uc == UNIT_CLASS.HEALER),
        cloudSeed = math.random() * 100,
        breakDmgAdd = breakDmgAdd,
    }
    -- 装备套装额外词条注入 (与兵符属性同名, 战斗中叠加生效)
    if cachedEqBonus then
        local eb = cachedEqBonus
        if eb.speedPct > 0 then
            unit.speed = unit.speed * (1 + eb.speedPct / 100)
        end
        if eb.atkSpeedPct > 0 then
            unit.atkCooldown = unit.atkCooldown / (1 + eb.atkSpeedPct / 100)
        end
        unit.equipCritRate = eb.critRate or 0
        unit.equipDmgReduction = eb.dmgReduction or 0
        unit.equipCounterRate = eb.counterRate or 0
        unit.equipBreakDmgPct = eb.breakDmgPct or 0
        unit.equipDeathExplosionPct = eb.deathExplosionPct or 0
    end
    table.insert(playerUnits, unit)
end

function SpawnEnemyUnit()
    if #enemyUnits >= MAX_ENEMY_UNITS then return end
    local filledSlots = {}
    for _, slot in ipairs(ENEMY_SLOTS) do
        if slot.filled and slot.card then table.insert(filledSlots, slot) end
    end

    local uc, atk, def, hp
    if #filledSlots > 0 then
        local slot = filledSlots[math.random(1, #filledSlots)]
        local card = slot.card
        uc = GetUnitClassForCard(card, false)
        local ss = SOLDIER_STAT_SCALE
        atk = card.atk * ss; def = card.def * ss * 0.5; hp = card.hp * ss * 0.6
    else
        uc = UNIT_CLASS.DEMON_WARRIOR
        atk = 52; def = 12; hp = 160
    end

    local bz = BATTLE_ZONE
    table.insert(enemyUnits, {
        x = bz.left + 20 + math.random() * (bz.right - bz.left - 40),
        y = bz.top + 10 + math.random() * 20,
        hp = hp, maxHp = hp, atk = atk, def = def,
        speed = uc.speed + math.random() * 5,
        atkTimer = math.random() * 0.5, atkCooldown = uc.atkCd,
        atkRange = uc.atkRange,
        alive = true, isPlayer = false,
        isRanged = uc.isRanged, unitClass = uc,
        animTimer = math.random() * 6.28, flashTimer = 0,
        isHealer = false,
        cloudSeed = math.random() * 100,
    })
end

-- ============================================================================
-- 更新逻辑
-- ============================================================================

---@param eventType string
---@param eventData UpdateEventData
function HandleUpdate(eventType, eventData)
    local dt = eventData["TimeStep"]:GetFloat()
    gameState.gameTime = gameState.gameTime + dt

    -- DWP 回调设置的字体重建标志：在主线程执行字体重建
    if fontRebuildNeeded then
        fontRebuildNeeded = false
        if fontId < 0 then
            fontId = nvgCreateFont(vg, "sans", "Fonts/MiSans-Regular.ttf")
            print("[MainThread] 重建主字体 fontId=" .. tostring(fontId))
        end
    end

    -- 自动存档（每60秒保存一次，防止意外退出丢失进度）
    -- 仅在完成资料设置且进入主菜单后才自动存档，避免在加载/选资料阶段覆盖正确数据
    autoSaveTimer = (autoSaveTimer or 0) + dt
    if autoSaveTimer >= 60 then
        autoSaveTimer = 0
        if playerInfo.profileSet and gameState.phase ~= "LOADING" and gameState.phase ~= "PROFILE" then
            SaveGameProgress()
        end
    end

    -- 虎符≥20万一次性解锁连抽增强 (10/50/100连抽)
    if not playerInfo.jadeUnlockedBigPull and playerInfo.jade >= 200000 then
        playerInfo.jadeUnlockedBigPull = true
        AddFloatText(DESIGN_W / 2, DESIGN_H * 0.3, "连抽增强已解锁! 10/50/100连抽", 2.5, { 255, 220, 80 }, 20)
        print("[连抽增强] 虎符≥20万, 永久解锁10/50/100连抽!")
    end

    -- 云存档重试 (委托给 CloudManager)
    if rawget(_G, 'CloudManager') then CloudManager.Update(dt) end

    -- 交易行定时扫描
    TradeManager.Tick(dt)

    -- 广告限制已移除

    -- 战斗规则弹窗滚动惯性
    if battleRulesState.show and not battleRulesState.isDragging and math.abs(battleRulesState.vel) > 1 then
        battleRulesState.scrollY = battleRulesState.scrollY + battleRulesState.vel * dt
        battleRulesState.vel = battleRulesState.vel * 0.92
        local maxScroll = math.max(0, battleRulesState.contentH - battleRulesState.viewH)
        battleRulesState.scrollY = math.max(0, math.min(battleRulesState.scrollY, maxScroll))
    elseif battleRulesState.show and not battleRulesState.isDragging then
        battleRulesState.vel = 0
    end

    -- 新手指引弹窗滚动惯性
    if newbieGuidePopup.show and not newbieGuidePopup.isDragging and math.abs(newbieGuidePopup.vel or 0) > 1 then
        newbieGuidePopup.scrollY = (newbieGuidePopup.scrollY or 0) + (newbieGuidePopup.vel or 0) * dt
        newbieGuidePopup.vel = (newbieGuidePopup.vel or 0) * 0.92
        local maxScroll = math.max(0, (newbieGuidePopup.contentH or 0) - (newbieGuidePopup.viewH or 0))
        newbieGuidePopup.scrollY = math.max(0, math.min(newbieGuidePopup.scrollY, maxScroll))
    elseif newbieGuidePopup.show and not newbieGuidePopup.isDragging then
        newbieGuidePopup.vel = 0
    end

    -- 统一规则弹窗滚动惯性
    if phaseRulePopup.show and not phaseRulePopup.isDragging and math.abs(phaseRulePopup.vel or 0) > 1 then
        phaseRulePopup.scrollY = (phaseRulePopup.scrollY or 0) + (phaseRulePopup.vel or 0) * dt
        phaseRulePopup.vel = (phaseRulePopup.vel or 0) * 0.92
        local maxScroll = math.max(0, (phaseRulePopup.contentH or 0) - (phaseRulePopup.viewH or 0))
        phaseRulePopup.scrollY = math.max(0, math.min(phaseRulePopup.scrollY, maxScroll))
    elseif phaseRulePopup.show and not phaseRulePopup.isDragging then
        phaseRulePopup.vel = 0
    end

    -- 兵符替换弹窗滚动惯性
    if sealReplaceState.show then
        local scrl = sealReplaceState.scroll
        if not scrl.isDragging and math.abs(scrl.vel or 0) > 1 then
            scrl.y = (scrl.y or 0) + (scrl.vel or 0) * dt
            scrl.vel = (scrl.vel or 0) * 0.92
            local maxScroll = math.max(0, (scrl.contentH or 0) - (scrl.viewH or 0))
            scrl.y = math.max(0, math.min(scrl.y, maxScroll))
        elseif not scrl.isDragging then
            scrl.vel = 0
        end
    end

    -- 策略选项条: 每帧检测长按（不依赖手指移动）
    if strategyWheelState.pressing and not strategyWheelState.show then
        local elapsed = gameState.gameTime - strategyWheelState.startTime
        if elapsed >= STRATEGY_LONG_PRESS then
            strategyWheelState.show = true
        end
    end

    -- (已移除武技长按弹窗, 改为按下即拖拽瞄准)

    -- 探索模式帧更新
    if gameState.phase == "EXPLORATION" then
        Exploration.Update(dt)
    end

    -- 累计在线时间（全局，不仅限于福利页）
    welfareState.onlineTime = welfareState.onlineTime + dt

    -- BGM 场景切换
    UpdateBGM()

    -- 天命赐福滚动惯性
    if gameState.phase == "WELFARE" then
        local ws = welfareState.scroll
        if not ws.isDragging and math.abs(ws.vel) > 0.5 then
            ws.offset = ws.offset + ws.vel * dt
            ws.vel = ws.vel * 0.92
        elseif not ws.isDragging then
            ws.vel = 0
        end
        -- 贡献榜独立滚动惯性
        local cs = welfareState.contribScroll
        if not cs.isDragging and math.abs(cs.vel) > 0.5 then
            cs.offset = cs.offset + cs.vel * dt
            cs.vel = cs.vel * 0.92
        elseif not cs.isDragging then
            cs.vel = 0
        end
        -- 战力排行榜独立滚动惯性
        local ps2 = welfareState.powerScroll
        if not ps2.isDragging and math.abs(ps2.vel) > 0.5 then
            ps2.offset = ps2.offset + ps2.vel * dt
            ps2.vel = ps2.vel * 0.92
        elseif not ps2.isDragging then
            ps2.vel = 0
        end
        -- 桩逼王排行榜滚动惯性
        local ds = welfareState.dummyScroll
        if not ds.isDragging and math.abs(ds.vel) > 0.5 then
            ds.offset = ds.offset + ds.vel * dt
            ds.vel = ds.vel * 0.92
        elseif not ds.isDragging then
            ds.vel = 0
        end
    end

    -- 阵营成员列表滚动惯性
    if gameState.phase == "FACTION" then
        local fs = factionUI.scroll
        if not fs.isDragging and math.abs(fs.vel) > 0.5 then
            fs.offset = fs.offset + fs.vel * dt
            fs.vel = fs.vel * 0.92
            if fs.offset < 0 then fs.offset = 0; fs.vel = 0 end
        elseif not fs.isDragging then
            fs.vel = 0
        end
    end

    -- 交易行滚动惯性
    if gameState.phase == "TRADE" then
        local ts = tradeState.scroll
        if not ts.isDragging and math.abs(ts.vel) > 0.5 then
            ts.offset = ts.offset + ts.vel * dt
            ts.vel = ts.vel * 0.92
            if ts.offset < 0 then ts.offset = 0; ts.vel = 0 end
        elseif not ts.isDragging then
            ts.vel = 0
        end
        -- toast 计时
        if tradeState.toastTimer > 0 then
            tradeState.toastTimer = tradeState.toastTimer - dt
        end
    end

    -- 编队界面滚动惯性
    if gameState.phase == "FORMATION" and formationUI then
        menuAnimTimer = menuAnimTimer + dt
        if not formationUI.isDragging and math.abs(formationUI.scrollVel or 0) > 0.5 then
            formationUI.scrollY = (formationUI.scrollY or 0) + formationUI.scrollVel * dt
            formationUI.scrollVel = formationUI.scrollVel * 0.92
        elseif not formationUI.isDragging then
            formationUI.scrollVel = 0
        end
    end

    -- 邮件列表滚动惯性
    if gameState.phase == "MAIL_BOX" then
        local ms = welfareState.mail.scroll
        if ms and not ms.isDragging and math.abs(ms.vel) > 0.5 then
            ms.offset = ms.offset + ms.vel * dt
            ms.vel = ms.vel * 0.92
            if ms.offset < 0 then ms.offset = 0; ms.vel = 0 end
        elseif ms and not ms.isDragging then
            ms.vel = 0
        end
    end

    -- 战令通行证任务列表滚动惯性
    if gameState.phase == "BATTLE_PASS" and battlePassUIState.tab ~= 1 then
        local bs = battlePassUIState
        if not bs.isDragging then
            if math.abs(bs.scrollVel or 0) > 0.3 then
                bs.scrollY = bs.scrollY + bs.scrollVel * dt
                bs.scrollVel = bs.scrollVel * math.pow(0.12, dt)
            else
                bs.scrollVel = 0
            end
            -- 边界回弹
            local maxY = 0
            local minY = -math.max(0, (bs.contentHeight or 0))
            if bs.scrollY > maxY then
                bs.scrollY = bs.scrollY + (maxY - bs.scrollY) * math.min(1, 12 * dt)
                bs.scrollVel = (bs.scrollVel or 0) * 0.5
                if math.abs(bs.scrollY - maxY) < 0.5 then bs.scrollY = maxY end
            elseif bs.scrollY < minY then
                bs.scrollY = bs.scrollY + (minY - bs.scrollY) * math.min(1, 12 * dt)
                bs.scrollVel = (bs.scrollVel or 0) * 0.5
                if math.abs(bs.scrollY - minY) < 0.5 then bs.scrollY = minY end
            end
        end
    end

    -- 每日任务/成就滚动惯性 (带边界回弹)
    if gameState.phase == "PROGRESS" then
        local ps = progressUIState
        if not ps.isDragging then
            -- 惯性衰减（更平滑的指数衰减）
            if math.abs(ps.scrollVel) > 0.3 then
                ps.scrollY = ps.scrollY + ps.scrollVel * dt
                ps.scrollVel = ps.scrollVel * math.pow(0.12, dt) -- 时间无关衰减
            else
                ps.scrollVel = 0
            end
            -- 边界回弹
            local maxScroll = ps.contentHeight or 0
            local minY = -math.max(0, maxScroll)
            local maxY = 0
            if ps.scrollY > maxY then
                -- 顶部超出，弹回
                ps.scrollY = ps.scrollY + (maxY - ps.scrollY) * math.min(1, 12 * dt)
                ps.scrollVel = ps.scrollVel * 0.5
                if math.abs(ps.scrollY - maxY) < 0.5 then ps.scrollY = maxY end
            elseif ps.scrollY < minY then
                -- 底部超出，弹回
                ps.scrollY = ps.scrollY + (minY - ps.scrollY) * math.min(1, 12 * dt)
                ps.scrollVel = ps.scrollVel * 0.5
                if math.abs(ps.scrollY - minY) < 0.5 then ps.scrollY = minY end
            end
        else
            -- 拖拽中的橡皮筋效果（超出边界时阻力变大）
            local maxScroll = ps.contentHeight or 0
            local minY = -math.max(0, maxScroll)
            if ps.scrollY > 0 then
                ps.scrollY = ps.scrollY * 0.6  -- 顶部橡皮筋阻力
            elseif ps.scrollY < minY then
                local over = minY - ps.scrollY
                ps.scrollY = minY - over * 0.6  -- 底部橡皮筋阻力
            end
        end
    end

    -- 编辑器滚动惯性 (带边界回弹)
    if gameState.phase == "DEV_EDITOR" then
        local es = editorState
        if not es.isDragging then
            if math.abs(es.scrollVel) > 0.3 then
                es.scrollY = es.scrollY + es.scrollVel * dt
                es.scrollVel = es.scrollVel * math.pow(0.12, dt)
            else
                es.scrollVel = 0
            end
            local maxScroll = es.contentHeight or 0
            local minY = -math.max(0, maxScroll)
            local maxY = 0
            if es.scrollY > maxY then
                es.scrollY = es.scrollY + (maxY - es.scrollY) * math.min(1, 12 * dt)
                es.scrollVel = es.scrollVel * 0.5
                if math.abs(es.scrollY - maxY) < 0.5 then es.scrollY = maxY end
            elseif es.scrollY < minY then
                es.scrollY = es.scrollY + (minY - es.scrollY) * math.min(1, 12 * dt)
                es.scrollVel = es.scrollVel * 0.5
                if math.abs(es.scrollY - minY) < 0.5 then es.scrollY = minY end
            end
        else
            local maxScroll = es.contentHeight or 0
            local minY = -math.max(0, maxScroll)
            if es.scrollY > 0 then
                es.scrollY = es.scrollY * 0.6
            elseif es.scrollY < minY then
                local over = minY - es.scrollY
                es.scrollY = minY - over * 0.6
            end
        end
    end

    -- 相位切换防穿透冷却递减
    if phaseChangeCooldown > 0 then
        phaseChangeCooldown = phaseChangeCooldown - dt
    end

    -- CDK 结果提示倒计时
    if cdkState.resultTimer > 0 then
        cdkState.resultTimer = cdkState.resultTimer - dt
    end

    -- Toast 计时器递减
    if toastState.timer > 0 then
        toastState.timer = toastState.timer - dt
    end

    -- (长按不再触发弹窗, 改为单击触发 infoPopupState)

    -- LOADING 阶段：阻塞资源下载完成后自动跳转
    if gameState.phase == "LOADING" then
        menuAnimTimer = menuAnimTimer + dt
        if blockingLoadState.ready then
            if playerInfo.profileSet then
                -- 已设置过资料，跳过头像选择直接进入主菜单
                gameState.phase = "MENU"
                print("=== 阻塞加载完成，profileSet=true，直接进入 MENU ===")
            else
                gameState.phase = "PROFILE"
                print("=== 阻塞加载完成，进入 PROFILE（首次设置资料）===")
            end
        end
        -- 点击提示倒计时
        if loadingClickTipTimer and loadingClickTipTimer > 0 then
            loadingClickTipTimer = loadingClickTipTimer - dt
        end
        return
    end

    if gameState.phase == "PROFILE" then
        menuAnimTimer = menuAnimTimer + dt
    elseif gameState.phase == "MENU" then
        menuAnimTimer = menuAnimTimer + dt
        -- 教程 step 2-5 在 MENU phase 下运行
        if tutorialState.active then UpdateTutorial(dt) end
        -- 左侧栏滚动惯性
        if not leftSidebarScroll.isDragging and math.abs(leftSidebarScroll.vel) > 0.5 then
            leftSidebarScroll.y = leftSidebarScroll.y + leftSidebarScroll.vel * dt
            leftSidebarScroll.vel = leftSidebarScroll.vel * 0.92
            local maxScroll = math.max(0, leftSidebarScroll.contentH - leftSidebarScroll.viewH)
            leftSidebarScroll.y = math.max(0, math.min(leftSidebarScroll.y, maxScroll))
        elseif not leftSidebarScroll.isDragging then
            leftSidebarScroll.vel = 0
        end
    elseif gameState.phase == "GACHA" then
        if tutorialState.active then
            -- 教程 step 6: 由 UpdateTutorial 管理 gacha 动画
            UpdateTutorial(dt)
        else
            gachaState.animTimer = gachaState.animTimer + dt
            if gachaState.pulling then
                gachaState.pullTimer = gachaState.pullTimer + dt
                if gachaState.pullTimer >= 1.2 then
                    gachaState.pulling = false
                    gachaState.showResults = true
                end
            end
            if sealGachaState.pulling then
                sealGachaState.pullTimer = sealGachaState.pullTimer + dt
                if sealGachaState.pullTimer >= 1.2 then
                    sealGachaState.pulling = false
                    sealGachaState.showResults = true
                end
            end
        end
        -- 残片仓库惯性滚动
        if gachaState.showFragShop and not fragShopScroll.isDragging and math.abs(fragShopScroll.vel) > 0.5 then
            fragShopScroll.offset = fragShopScroll.offset + fragShopScroll.vel * dt
            fragShopScroll.vel = fragShopScroll.vel * 0.92
        elseif gachaState.showFragShop then
            fragShopScroll.vel = 0
        end
    elseif gameState.phase == "CODEX" then
        menuAnimTimer = menuAnimTimer + dt
        -- 滚动惯性
        if not codexScroll.isDragging and math.abs(codexScroll.vel) > 0.5 then
            codexScroll.y = codexScroll.y + codexScroll.vel * dt
            codexScroll.vel = codexScroll.vel * 0.92  -- 摩擦力衰减
        else
            codexScroll.vel = 0
        end
    elseif gameState.phase == "HERO_DETAIL" then
        menuAnimTimer = menuAnimTimer + dt
    elseif gameState.phase == "PLAYER_DETAIL" then
        menuAnimTimer = menuAnimTimer + dt
    elseif gameState.phase == "SKILL_CODEX" then
        menuAnimTimer = menuAnimTimer + dt
        -- 滚动惯性
        if not skillCodexState.isDragging and math.abs(skillCodexState.scrollVel) > 0.5 then
            skillCodexState.scrollY = skillCodexState.scrollY + skillCodexState.scrollVel * dt
            skillCodexState.scrollVel = skillCodexState.scrollVel * 0.92
        else
            skillCodexState.scrollVel = 0
        end
        -- 滚动范围限制
        local maxScroll = math.max(0, (skillCodexState.contentH or 0) - (DESIGN_H - 68))
        skillCodexState.scrollY = math.max(0, math.min(maxScroll, skillCodexState.scrollY))
    elseif gameState.phase == "EQUIP" then
        menuAnimTimer = menuAnimTimer + dt
        -- 新版EquipUI更新（滚动惯性、长按计时等）
        if EquipUI.isVisible then
            EquipUI.Update(dt)
        else
            -- 旧版滚动惯性
            if not equipScreenState.isDragging and math.abs(equipScreenState.scrollVel) > 0.5 then
                equipScreenState.scrollY = equipScreenState.scrollY + equipScreenState.scrollVel * dt
                equipScreenState.scrollVel = equipScreenState.scrollVel * 0.92
            elseif not equipScreenState.isDragging then
                equipScreenState.scrollVel = 0
            end
        end
    elseif gameState.phase == "EQUIP_CODEX" then
        menuAnimTimer = menuAnimTimer + dt
        -- 兵甲图录滚动惯性
        if not equipCodexState.isDragging and math.abs(equipCodexState.scrollVel) > 0.5 then
            equipCodexState.scrollY = equipCodexState.scrollY + equipCodexState.scrollVel * dt
            equipCodexState.scrollVel = equipCodexState.scrollVel * 0.92
        elseif not equipCodexState.isDragging then
            equipCodexState.scrollVel = 0
        end
    elseif gameState.phase == "SEAL_MGR" then
        menuAnimTimer = menuAnimTimer + dt
        -- 兵符管理滚动惯性（选中分解列表）
        if not sealMgrScroll.isDragging and math.abs(sealMgrScroll.vel) > 0.5 then
            sealMgrScroll.y = (sealMgrScroll.y or 0) + sealMgrScroll.vel * dt
            sealMgrScroll.vel = sealMgrScroll.vel * 0.92
            -- 边界限制
            local maxS = math.max(0, (sealMgrScroll.contentH or 0) - (sealMgrScroll.viewH or 0))
            sealMgrScroll.y = math.max(0, math.min(sealMgrScroll.y, maxS))
        elseif not sealMgrScroll.isDragging then
            sealMgrScroll.vel = 0
        end
        -- 英雄选择弹窗滚动惯性
        if sealMgrState.showHeroPicker and not heroPickerScroll.isDragging and math.abs(heroPickerScroll.vel) > 0.5 then
            heroPickerScroll.y = (heroPickerScroll.y or 0) + heroPickerScroll.vel * dt
            local maxScroll = math.max(0, (heroPickerScroll.contentH or 0) - (heroPickerScroll.viewH or 0))
            heroPickerScroll.y = math.max(0, math.min(heroPickerScroll.y, maxScroll))
            heroPickerScroll.vel = heroPickerScroll.vel * 0.92
        elseif sealMgrState.showHeroPicker and not heroPickerScroll.isDragging then
            heroPickerScroll.vel = 0
        end
    elseif gameState.phase == "WELFARE" then
        menuAnimTimer = menuAnimTimer + dt
    elseif gameState.phase == "MAIL_BOX" then
        menuAnimTimer = menuAnimTimer + dt
    elseif gameState.phase == "POWER_RANK" then
        menuAnimTimer = menuAnimTimer + dt
        -- 战力/境界排行榜滚动惯性（根据当前页签）
        local ps2 = welfareState.powerScroll
        if not ps2.isDragging and math.abs(ps2.vel) > 0.5 then
            ps2.offset = ps2.offset + ps2.vel * dt
            ps2.vel = ps2.vel * 0.92
        elseif not ps2.isDragging then
            ps2.vel = 0
        end
        local rs2 = welfareState.realmScroll
        if not rs2.isDragging and math.abs(rs2.vel) > 0.5 then
            rs2.offset = rs2.offset + rs2.vel * dt
            rs2.vel = rs2.vel * 0.92
        elseif not rs2.isDragging then
            rs2.vel = 0
        end
    elseif gameState.phase == "CONTRIB_RANK" then
        menuAnimTimer = menuAnimTimer + dt
        -- 贡献榜详情页滚动惯性
        local cs2 = welfareState.contribDetailScroll
        if not cs2.isDragging and math.abs(cs2.vel) > 0.5 then
            cs2.offset = cs2.offset + cs2.vel * dt
            cs2.vel = cs2.vel * 0.92
        elseif not cs2.isDragging then
            cs2.vel = 0
        end
    elseif gameState.phase == "RANKED_SELECT" then
        menuAnimTimer = menuAnimTimer + dt
        -- 排位匹配动画 (1.5秒假匹配后进入战斗)
        if rankedState.isMatching then
            rankedState.matchAnim = rankedState.matchAnim + dt
            if rankedState.matchAnim >= 1.5 then
                rankedState.isMatching = false
                rankedState.matchAnim = 0
                -- 进入战斗
                gameState.isRanked = true
                gameState.phase = "BATTLE"
                gameState.battlePhase = "SHOP"
                gameState.playerBaseHP = BASE_HP_MAX
                gameState.enemyBaseHP = BASE_HP_MAX
                gameState.gold = GameConfig.INITIAL_GOLD
                gameState.totalKills = 0
                gameState.gameTime = 0
                gameState.battleTime = 0
                gameState.drawCount = 0
                gameState.goldTimer = 0
                gameState.resultTimer = 0
                gameState.autoMarch = false
                -- 阶级: 根据段位递增
                local tierIdx = GetRankedTier(rankedState.score).index
                stageMaxTier = math.min(6, math.max(1, tierIdx))
                for _, sk in ipairs(SKILL_DEFS) do sk.cooldown = 0 end
                activeSkillEffects = {}
                skillTargeting.active = false
                for _, s in ipairs(PLAYER_SLOTS) do s.filled = false; s.card = nil end
                for _, s in ipairs(ENEMY_SLOTS) do s.filled = false; s.card = nil end
                playerUnits = {}
                enemyUnits = {}
                inventory = {}
                RefreshShop()
                -- 部署AI对手的武灵到敌方槽位 (stats已bake, eScale=1.0)
                local oppCards = rankedState.opponentCards
                for i = 1, math.min(#oppCards, #ENEMY_SLOTS) do
                    local card = DeepCopy(oppCards[i])
                    ENEMY_SLOTS[i].filled = true
                    ENEMY_SLOTS[i].card = card
                end
                -- 使用随机战场背景
                local bgIdx = math.random(1, 8)
                ApplyBattleLayout(bgIdx)
                InitAISkills()  -- 排位模式启用AI技能
                PlaySFX(AUDIO.sfx_click)
                print("=== 排位匹配完成，进入战斗 vs " .. rankedState.opponentName .. " ===")
            end
        end
        -- 排行榜滚动惯性
        if rankedState.showLeaderboard and not rankedState.rankScroll.isDragging then
            if math.abs(rankedState.rankScroll.vel) > 0.5 then
                rankedState.rankScroll.offset = rankedState.rankScroll.offset + rankedState.rankScroll.vel * dt
                rankedState.rankScroll.vel = rankedState.rankScroll.vel * 0.92
            else
                rankedState.rankScroll.vel = 0
            end
            rankedState.rankScroll.offset = math.max(0, rankedState.rankScroll.offset)
        end
    elseif gameState.phase == "DUMMY_SELECT" then
        menuAnimTimer = menuAnimTimer + dt
        -- 打桩选将滚动惯性
        if not dummyState.isDragging and math.abs(dummyState.scrollVel) > 0.5 then
            dummyState.scrollY = dummyState.scrollY + dummyState.scrollVel * dt
            dummyState.scrollVel = dummyState.scrollVel * 0.92
        elseif not dummyState.isDragging then
            dummyState.scrollVel = 0
        end
        local maxScroll = math.max(0, dummyState.contentH - dummyState.gridH)
        dummyState.scrollY = math.max(0, math.min(maxScroll, dummyState.scrollY))
    elseif gameState.phase == "DUMMY_RESULT" then
        menuAnimTimer = menuAnimTimer + dt
    elseif gameState.phase == "SKILL_DETAIL" then
        menuAnimTimer = menuAnimTimer + dt
        -- skillFxTimer 复用 menuAnimTimer
    elseif gameState.phase == "TUTORIAL" then
        UpdateTutorial(dt)
    elseif gameState.phase == "BATTLE" then
        if tutorialState.active then
            -- 教程战斗: UpdateTutorial 内部已调用 UpdateBattle
            UpdateTutorial(dt)
        else
            -- 战斗倍速: 乘以倍率
            local battleDt = dt * (gameState.battleSpeed or 1)
            UpdateAutoBattle(dt)  -- 自动战斗用原始dt节流
            UpdateBattle(battleDt)
        end
    elseif gameState.phase == "WIN" or gameState.phase == "LOSE" then
        gameState.resultTimer = gameState.resultTimer + dt
        if gameState.showRewardPopup then
            gameState.rewardPopupTimer = (gameState.rewardPopupTimer or 0) + dt
        end
    end

    -- 飘字
    for i = #floatTexts, 1, -1 do
        floatTexts[i].timer = floatTexts[i].timer + dt
        if floatTexts[i].timer >= floatTexts[i].duration then table.remove(floatTexts, i) end
    end

    -- 粒子
    for i = #particles, 1, -1 do
        local p = particles[i]
        p.timer = p.timer + dt
        p.x = p.x + p.vx * dt
        p.y = p.y + p.vy * dt
        p.vy = p.vy + 50 * dt  -- 重力
        if p.timer >= p.life then table.remove(particles, i) end
    end
end

--- 根据自动行军策略选择车道
function PickLaneByStrategy(strategy)
    if strategy == "mid_focus" then
        -- 全歼中路: 全部兵力集中第3道
        return 3
    elseif strategy == "side_spread" then
        -- 分散侧翼: 全部兵力只走第1和第5道
        if math.random(2) == 1 then return 1 else return 5 end
    else
        -- 五路并进(默认): 随机全车道
        return math.random(1, NUM_LANES)
    end
end

--- 自动释放玩家技能 (autoMarch开启时, 手动操作优先)
function UpdateAutoSkills(dt)
    if not gameState.autoMarch then return end
    if skillTargeting.active then return end  -- 玩家正在手动瞄准，跳过
    if #playerEquippedSkills == 0 then return end
    if #playerUnits == 0 then return end  -- 没有己方单位不释放

    autoSkillState.timer = autoSkillState.timer + dt
    if autoSkillState.timer < autoSkillState.nextTime then return end

    autoSkillState.timer = 0
    autoSkillState.nextTime = autoSkillState.interval + (math.random() - 0.5) * 2.0

    -- 筛选可用(不在CD)的已装备技能
    local readySkills = {}
    for _, techIdx in ipairs(playerEquippedSkills) do
        local skill = SKILL_DEFS[techIdx]
        if skill and skill.unlocked and skill.cooldown <= 0 then
            table.insert(readySkills, techIdx)
        end
    end
    if #readySkills == 0 then return end

    -- 随机选一个技能
    local chosenIdx = readySkills[math.random(1, #readySkills)]
    local skill = SKILL_DEFS[chosenIdx]
    if not skill then return end

    -- 计算目标: 优先瞄准敌方单位
    local targetX, targetY
    if skill.skillType == "line" then
        local laneIdx = PickLaneByStrategy(gameState.autoMarchStrategy)
        targetX = GetLaneCenterX(laneIdx)
        targetY = BATTLE_ZONE.centerY
    else
        if #enemyUnits > 0 then
            local target = enemyUnits[math.random(1, #enemyUnits)]
            if target and target.alive then
                targetX = target.x + (math.random() - 0.5) * 30
                targetY = target.y + (math.random() - 0.5) * 20
            end
        end
        if not targetX then
            targetX = BATTLE_ZONE.left + math.random() * (BATTLE_ZONE.right - BATTLE_ZONE.left)
            targetY = BATTLE_ZONE.centerY - math.random() * (BATTLE_ZONE.centerY - BATTLE_ZONE.enemyLine) * 0.5
        end
    end

    -- 释放技能 (复用 CastSkill)
    CastSkill(chosenIdx, targetX, targetY)
    AddFloatText(targetX, targetY - 50, "自动: " .. skill.name, 1.0, { skill.color[1], skill.color[2], skill.color[3] }, 14)
end

-- ============================================================================
-- 全自动战斗 AI (简单逻辑: 自动买卡上阵、开战、行军、刷新)
-- ============================================================================

--- 自动从商店购买卡牌并放入空槽位
--- @return boolean 是否成功购买了至少一张
function AutoBuyAndPlace()
    local bought = false

    -- 优先级策略:
    -- 1. 优先购买能与已上阵武灵合并升级的卡牌 (同名)
    -- 2. 其次按费用降序购买高品质卡牌
    -- 3. 有空槽才放新卡

    -- 收集已上阵武灵名称 (用于合并升级判断)
    local onBoardNames = {}
    for _, slot in ipairs(PLAYER_SLOTS) do
        if slot.filled and slot.card then
            onBoardNames[slot.card.name] = true
        end
    end

    -- 按费用降序排列索引
    local sortedIndices = {}
    for i = 1, #shopCards do sortedIndices[i] = i end

    -- 排序: 可合并的优先, 同优先级按费用降序
    table.sort(sortedIndices, function(a, b)
        local sa, sb = shopCards[a], shopCards[b]
        local heroA = HERO_CARDS[sa.cardIdx]
        local heroB = HERO_CARDS[sb.cardIdx]
        local mergeA = (heroA and onBoardNames[heroA.name]) and 1 or 0
        local mergeB = (heroB and onBoardNames[heroB.name]) and 1 or 0
        if mergeA ~= mergeB then return mergeA > mergeB end
        return sa.cost > sb.cost
    end)

    for _, i in ipairs(sortedIndices) do
        local shopItem = shopCards[i]
        if not shopItem.sold and gameState.gold >= shopItem.cost then
            -- 先检查能否合并到已有同名槽位
            local heroData = HERO_CARDS[shopItem.cardIdx]
            local mergeSlot = nil
            if heroData then
                for _, slot in ipairs(PLAYER_SLOTS) do
                    if slot.filled and slot.card and slot.card.name == heroData.name then
                        mergeSlot = slot
                        break
                    end
                end
            end

            if mergeSlot then
                -- 合并升级: 购买后升级已有卡牌
                gameState.gold = gameState.gold - shopItem.cost
                shopItem.sold = true
                -- 升级: 等级+1, 属性提升
                local mc = mergeSlot.card
                mc.level = (mc.level or 1) + 1
                mc.constellation = (mc.constellation or 0) + (shopItem.constellation or 0)
                bought = true
                AddFloatText(DESIGN_W / 2, DESIGN_H * 0.5,
                    mc.name .. " 升级 Lv" .. mc.level, 1.0, { 255, 220, 80 }, 14)
            else
                -- 找一个空槽位放新卡
                local emptySlot = nil
                for _, slot in ipairs(PLAYER_SLOTS) do
                    if not slot.filled then
                        emptySlot = slot
                        break
                    end
                end
                if not emptySlot then break end -- 没有空槽位了
                -- 购买并放置
                gameState.gold = gameState.gold - shopItem.cost
                shopItem.sold = true
                local cardData = DeepCopy(HERO_CARDS[shopItem.cardIdx])
                cardData.cardIdx = shopItem.cardIdx
                cardData.constellation = shopItem.constellation or 0
                cardData.level = 1
                SetupSlotHero(emptySlot, cardData)
                bought = true
            end
        end
    end
    if bought then RefreshBaseStats() end
    return bought
end

--- 自动战斗主更新 (用原始dt节流, 不受倍速影响)
function UpdateAutoBattle(dt)
    if not gameState.autoBattle then return end
    if tutorialState.active then return end -- 教程中不自动
    if gameState.noFullAuto then gameState.autoBattle = false; return end -- 副本禁用全自动

    autoBattleTimer = (autoBattleTimer or 0) + dt

    if gameState.battlePhase == "SHOP" then
        -- SHOP阶段: 每0.3s执行一次, 买卡上阵然后开战
        if autoBattleTimer < 0.3 then return end
        autoBattleTimer = 0

        -- 自动购买并上阵
        local bought = AutoBuyAndPlace()

        -- 如果买不到更多卡 (钱不够或槽位满), 自动开战
        if not bought and GetPlayerFilledSlotCount() > 0 then
            gameState.battlePhase = "FIGHT"
            AggregateBaseStats()
            gameState.autoMarch = true
            gameState.battleTime = 0
            AddFloatText(DESIGN_W / 2, DESIGN_H * 0.4, "自动开战!", 1.5, { 120, 255, 180 }, 18)
            PlaySFX(AUDIO.sfx_march)
        end

    elseif gameState.battlePhase == "FIGHT" then
        -- FIGHT阶段: 每1s执行一次
        if autoBattleTimer < 1.0 then return end
        autoBattleTimer = 0

        -- 确保自动行军开启
        if not gameState.autoMarch then
            gameState.autoMarch = true
        end

        -- 商店售罄且有军资时自动刷新
        if GetUnsoldShopCardCount() == 0 and gameState.gold >= GameConfig.REFRESH_COST then
            gameState.gold = gameState.gold - GameConfig.REFRESH_COST
            RefreshShop()
        end

        -- 自动购买新卡并放入空槽位
        AutoBuyAndPlace()
    end
end

function UpdateBattle(dt)
    -- ============================
    -- SHOP: 布阵购卡阶段 - 不出兵, 等玩家点击开战
    -- ============================
    if gameState.battlePhase == "SHOP" then
        return
    end

    -- ============================
    -- FIGHT: 连续出兵+战斗 (无回合, 直到一方基地血量归零)
    -- ============================

    -- === 打桩模式: 30s倒计时 + 伤害追踪 ===
    if gameState.isDummy then
        -- 准备阶段不计时
        if dummyState.prepPhase then return end

        local prevHP = gameState.enemyBaseHP
        -- 继续正常战斗更新（下方逻辑会减少enemyBaseHP）
        -- 但先处理计时
        dummyState.timer = dummyState.timer - dt
        if dummyState.timer <= 0 then
            -- 计算本帧最后伤害
            local frameDmg = prevHP - gameState.enemyBaseHP
            if frameDmg > 0 then
                dummyState.totalDamage = dummyState.totalDamage + frameDmg
            end
            -- 时间到，进入结果页
            gameState.phase = "DUMMY_RESULT"
            gameState.isDummy = false
            gameState.abyssFloor = nil
            gameState.towerFloor = nil
            gameState.isRanked = false
            dummyState.prepPhase = false
            AddFloatText(DESIGN_W / 2, DESIGN_H * 0.4, "时间到!", 2.0, { 255, 200, 60 }, 36)
            PlaySFX(AUDIO.sfx_click)
            print(string.format("=== 30s打桩结束 | 总伤害: %d | DPS: %.0f ===",
                math.floor(dummyState.totalDamage), dummyState.totalDamage / 30))
            -- 记录最高打桩伤害 & 上报到桩逼王排行榜
            if dummyState.totalDamage > (playerInfo.bestDummyDamage or 0) then
                playerInfo.bestDummyDamage = dummyState.totalDamage
            end
            ReportDummyScore(dummyState.totalDamage)
            return
        end
    end

    gameState.battleTime = gameState.battleTime + dt

    -- 军资自动增长 (每30s +1)
    gameState.goldTimer = gameState.goldTimer + dt
    if gameState.goldTimer >= GameConfig.GOLD_INTERVAL then
        gameState.goldTimer = gameState.goldTimer - GameConfig.GOLD_INTERVAL
        gameState.gold = gameState.gold + GameConfig.GOLD_PER_TICK
        AddFloatText(DESIGN_W * 0.15, DESIGN_H * 0.35, "+1 军资", 1.2, { 100, 220, 255 }, 22)
    end

    -- === 玩家部署冷却倒计时 (手动拖拽部署, 不再自动出兵) ===
    for _, slot in ipairs(PLAYER_SLOTS) do
        if slot.filled and slot.deployCD and slot.deployCD > 0 then
            slot.deployCD = slot.deployCD - dt
            if slot.deployCD < 0 then slot.deployCD = 0 end
        end
    end

    -- === 自动行军: 已上阵且不在CD期的武灵立即派兵(按策略选车道) ===
    if gameState.autoMarch then
        for _, slot in ipairs(PLAYER_SLOTS) do
            if slot.filled and slot.card then
                local cd = slot.deployCD or 0
                local unitCap = GetPlayerUnitCap()
                if cd <= 0 and #playerUnits < unitCap then
                    local laneIdx = PickLaneByStrategy(gameState.autoMarchStrategy)
                    local batchSize = GetBatchSizeForSlot(slot)
                    local spawned = 0
                    for _ = 1, batchSize do
                        if #playerUnits < unitCap then
                            SpawnUnitFromSlot(slot, true, laneIdx)
                            spawned = spawned + 1
                        end
                    end
                    slot.deployCD = DEPLOY_CD
                    slot.spawnFlash = 0.5
                    slot.spawnCount = (slot.spawnCount or 0) + spawned
                end
            end
        end
    end

    -- === 敌方出兵: 共享计时器,每次CD到随机选一个槽位派1兵 ===
    -- (旧方案: 每槽独立1.2sCD → 3-4槽=0.3s一个兵, 严重过快)
    if not gameState.isDummy then
        enemySpawnTimer = enemySpawnTimer + dt
        if enemySpawnTimer >= ENEMY_SPAWN_CD and #enemyUnits < MAX_ENEMY_UNITS then
            enemySpawnTimer = enemySpawnTimer - ENEMY_SPAWN_CD
            local filledSlots = {}
            for _, slot in ipairs(ENEMY_SLOTS) do
                if slot.filled and slot.card then table.insert(filledSlots, slot) end
            end
            if #filledSlots > 0 then
                local slot = filledSlots[math.random(1, #filledSlots)]
                slot.spawnCount = (slot.spawnCount or 0) + 1
                SpawnUnitFromSlot(slot, false)
            end
        end
    end

    -- === 出兵闪光衰减 (原在 UpdateHeroSkills 中) ===
    for _, slot in ipairs(PLAYER_SLOTS) do
        if slot.spawnFlash and slot.spawnFlash > 0 then slot.spawnFlash = slot.spawnFlash - dt end
    end
    for _, slot in ipairs(ENEMY_SLOTS) do
        if slot.spawnFlash and slot.spawnFlash > 0 then slot.spawnFlash = slot.spawnFlash - dt end
    end

    -- 更新武技技能特效
    UpdateSkillEffects(dt)

    -- AI对手释放武技技能 (排位/讨伐模式)
    UpdateAISkills(dt)

    -- 玩家自动释放技能 (自动行军开启时, 手动优先)
    UpdateAutoSkills(dt)

    -- 更新兵力战斗
    UpdateUnits(dt, playerUnits, enemyUnits, true)
    UpdateUnits(dt, enemyUnits, playerUnits, false)

    -- === 玩家兵突破敌方临界线 >> 直接攻击敌方大本营 ===
    -- 皇室战争设计: 突破=大伤害, 一个兵过线就很痛
    for i = #playerUnits, 1, -1 do
        local u = playerUnits[i]
        if u.alive and u.y <= BATTLE_ZONE.enemyLine + 8 then
            -- 突破伤害 = 兵ATK全额 + 兵种额外突破 + 剩余HP占比加成
            local classBreak = (u.unitClass and u.unitClass.breakDmg or 1) * 15
            local hpRatio = u.hp / math.max(1, u.maxHp)
            local rawDmg = math.ceil(u.atk * 1.0 + classBreak + u.atk * hpRatio * 0.5)
            -- 突破伤害加成: 兵符 + 装备词条
            local totalBreakPct = (u.sealBreakDmgPct or 0) + (u.equipBreakDmgPct or 0)
            if totalBreakPct > 0 then
                rawDmg = math.ceil(rawDmg * (1 + totalBreakPct / 100))
            end
            local breakDmg = math.max(5, rawDmg)
            gameState.enemyBaseHP = gameState.enemyBaseHP - breakDmg
            AddFloatText(u.x, BATTLE_ZONE.enemyLine + 5, "-" .. breakDmg, 1.0, { 100, 255, 150 }, 26)
            -- 突破爆炸特效 (更大更亮)
            for _ = 1, 8 do
                AddParticle(u.x, BATTLE_ZONE.enemyLine, {
                    vx = (math.random() - 0.5) * 100, vy = -(math.random() * 50 + 15),
                    life = 0.6, size = 3, color = { 100, 255, 180 },
                })
            end
            u.alive = false
        end
        if not u.alive then table.remove(playerUnits, i) end
    end

    -- === 敌方兵突破玩家临界线 >> 直接攻击玩家大本营 ===
    for i = #enemyUnits, 1, -1 do
        local u = enemyUnits[i]
        -- 打桩老虎不移动(speed=0)，不会突破临界线，但以防万一也跳过
        if u.alive and u.y >= BATTLE_ZONE.playerLine - 8 then
            if not u.isDummyTiger then
                local classBreak = (u.unitClass and u.unitClass.breakDmg or 1) * 15
                local hpRatio = u.hp / math.max(1, u.maxHp)
                local rawDmg = math.ceil(u.atk * 1.0 + classBreak + u.atk * hpRatio * 0.5)
                local breakDmg = math.max(5, rawDmg)
                gameState.playerBaseHP = gameState.playerBaseHP - breakDmg
                AddFloatText(u.x, BATTLE_ZONE.playerLine - 5, "-" .. breakDmg, 1.0, { 255, 100, 80 }, 26)
                for _ = 1, 8 do
                    AddParticle(u.x, BATTLE_ZONE.playerLine, {
                        vx = (math.random() - 0.5) * 100, vy = (math.random() * 50 + 15),
                        life = 0.6, size = 3, color = { 255, 80, 60 },
                    })
                end
                u.alive = false
            end
        end
        -- 打桩老虎死亡后不移除，留给下面的复活逻辑处理
        if not u.alive and not u.isDummyTiger then table.remove(enemyUnits, i) end
    end

    -- === 打桩模式: 每帧伤害累计 + 老虎无限轮回 ===
    if gameState.isDummy then
        -- 记录本帧造成的伤害 (enemyBaseHP在上方被减少了)
        local curHP = gameState.enemyBaseHP
        local expectedHP = 999999
        local frameDmg = expectedHP - curHP
        if frameDmg > 0 then
            dummyState.totalDamage = dummyState.totalDamage + frameDmg
            gameState.enemyBaseHP = expectedHP
        end
        -- 统计被击杀老虎的伤害并复活
        local bz = BATTLE_ZONE
        local tigerUC = UNIT_CLASS.DEMON_WARRIOR
        for i = #enemyUnits, 1, -1 do
            local u = enemyUnits[i]
            if u.isDummyTiger and not u.alive then
                -- 累计击杀伤害
                dummyState.totalDamage = dummyState.totalDamage + (u.maxHp or 8000)
                -- 原地复活：在同一车道中间区域随机位置重生
                local lane = u.laneIdx or math.random(1, NUM_LANES)
                local laneCX = GetLaneCenterX(lane)
                u.x = laneCX + (math.random() - 0.5) * LANE_WIDTH * 0.6
                u.y = bz.centerY + (math.random() - 0.5) * (bz.bottom - bz.top) * 0.5
                u.hp = u.maxHp
                u.alive = true
                u.flashTimer = 0
                u.animTimer = math.random() * 6.28
            end
        end
        -- 打桩模式也不让玩家基地被打死
        gameState.playerBaseHP = math.max(gameState.playerBaseHP, gameState.playerBaseMax)
        return  -- 打桩模式不走正常超时/胜负判定
    end

    -- 超时判定 (3分钟时限，按剩余HP比例决定胜负)
    if gameState.battleTime >= BATTLE_TIME_LIMIT then
        local pRatio = gameState.playerBaseHP / math.max(1, gameState.playerBaseMax)
        local eRatio = gameState.enemyBaseHP / math.max(1, gameState.enemyBaseMax)
        if pRatio > eRatio then
            -- 玩家HP比例更高 >> 胜利
            gameState.enemyBaseHP = 0
            gameState.phase = "WIN"
            gameState.resultTimer = 0
            -- 探索模式: 奖励由探索系统管理, 不在此直接发放
            if gameState.explorationMode then
                OnBattleVictory()
                AddFloatText(DESIGN_W / 2, BATTLE_ZONE.centerY, "时间到-大捷!", 3.0, { 255, 230, 80 }, 48)
                PlaySFX(AUDIO.sfx_win)
            else
                gameState.winJade = math.random(GameConfig.JADE_PER_WIN_MIN, GameConfig.JADE_PER_WIN_MAX)
                gameState.winExp = GameConfig.EXP_PER_WIN
                playerInfo.jade = playerInfo.jade + gameState.winJade
                playerInfo.exp = playerInfo.exp + GameConfig.EXP_PER_WIN
                CheckPlayerLevelUp()
                local reward = GrantRandomEquipment(stageMaxTier or 2)
                gameState.winEquip = reward
                gameState.winFragDrops = GenerateBattleSkillFragDrop(stageMaxTier or 2)
                OnBattleVictory()
                AddFloatText(DESIGN_W / 2, BATTLE_ZONE.centerY, "时间到-大捷!", 3.0, { 255, 230, 80 }, 48)
                PlaySFX(AUDIO.sfx_win)
            end
        elseif eRatio > pRatio then
            -- 敌方HP比例更高 >> 失败
            gameState.playerBaseHP = 0
            gameState.phase = "LOSE"
            gameState.resultTimer = 0
            if not gameState.explorationMode then
                playerInfo.jade = playerInfo.jade + GameConfig.JADE_PER_LOSE
                playerInfo.exp = playerInfo.exp + GameConfig.EXP_PER_LOSE
                CheckPlayerLevelUp()
            end
            OnBattleEnd()
            AddFloatText(DESIGN_W / 2, BATTLE_ZONE.centerY, "时间到-败北...", 3.0, { 255, 80, 80 }, 48)
            PlaySFX(AUDIO.sfx_lose)
        else
            -- 完全平局 >> 判定为失败
            gameState.playerBaseHP = 0
            gameState.phase = "LOSE"
            gameState.resultTimer = 0
            if not gameState.explorationMode then
                playerInfo.jade = playerInfo.jade + GameConfig.JADE_PER_LOSE
                playerInfo.exp = playerInfo.exp + GameConfig.EXP_PER_LOSE
                CheckPlayerLevelUp()
            end
            OnBattleEnd()
            AddFloatText(DESIGN_W / 2, BATTLE_ZONE.centerY, "时间到-平局", 3.0, { 200, 180, 120 }, 48)
            PlaySFX(AUDIO.sfx_lose)
        end
        return
    end

    -- 胜负判定
    if gameState.enemyBaseHP <= 0 then
        gameState.enemyBaseHP = 0
        -- 教程战斗: 进入胜利过渡 step 14
        if tutorialState.active and tutorialState.step >= 8 and tutorialState.step <= 13 then
            tutorialState.step = 14
            tutorialState.fadeTimer = 0
            AddFloatText(DESIGN_W / 2, BATTLE_ZONE.centerY, "大捷!", 2.0, { 255, 230, 80 }, 48)
            PlaySFX(AUDIO.sfx_win)
            print("=== 教程: 战斗胜利, 进入过渡 ===")
            return
        end
        gameState.phase = "WIN"
        gameState.resultTimer = 0
        -- 探索模式: 奖励由探索系统管理 (tempLoot), 不在此直接发放
        if gameState.explorationMode then
            OnBattleVictory()
            AddFloatText(DESIGN_W / 2, BATTLE_ZONE.centerY, "大捷!", 3.0, { 255, 230, 80 }, 48)
            PlaySFX(AUDIO.sfx_win)
            return
        end
        -- 保存奖励信息用于结算界面展示
        gameState.winJade = math.random(GameConfig.JADE_PER_WIN_MIN, GameConfig.JADE_PER_WIN_MAX)
        gameState.winExp = GameConfig.EXP_PER_WIN
        playerInfo.jade = playerInfo.jade + gameState.winJade
        playerInfo.exp = playerInfo.exp + GameConfig.EXP_PER_WIN
        CheckPlayerLevelUp()
        -- 战斗胜利奖励随机兵甲
        local reward = GrantRandomEquipment(stageMaxTier or 2)
        gameState.winEquip = reward  -- 保存装备掉落用于展示
        gameState.winFragDrops = GenerateBattleSkillFragDrop(stageMaxTier or 2)
        OnBattleVictory()
        AddFloatText(DESIGN_W / 2, BATTLE_ZONE.centerY, "大捷!", 3.0, { 255, 230, 80 }, 48)
        PlaySFX(AUDIO.sfx_win)
        return
    elseif gameState.playerBaseHP <= 0 then
        gameState.playerBaseHP = 0
        gameState.phase = "LOSE"
        gameState.resultTimer = 0
        -- 探索模式: 不直接发放败局奖励, 由探索系统统一管理
        if not gameState.explorationMode then
            playerInfo.jade = playerInfo.jade + GameConfig.JADE_PER_LOSE
            playerInfo.exp = playerInfo.exp + GameConfig.EXP_PER_LOSE
            CheckPlayerLevelUp()
        end
        OnBattleEnd()
        AddFloatText(DESIGN_W / 2, BATTLE_ZONE.centerY, "败北...", 3.0, { 255, 80, 80 }, 48)
        PlaySFX(AUDIO.sfx_lose)
        return
    end
end

--- 获取兵种实际出兵数 (大型兵种数量更少)
--- 返回 baseBatch, sealExtra (兵符额外兵力不受spawnMax限制)
function GetBatchSizeForSlot(slot)
    local quality = slot.card and slot.card.quality or 1
    local baseBatch = DEPLOY_BATCH_SIZE[quality] or 4
    -- 贪欲兵符: 额外出兵数 (无视spawnMax, 作为独立增援)
    local sealExtra = 0
    local sb = slot.cachedSealBonus
    if sb and sb.extraTroops > 0 then
        sealExtra = math.floor(sb.extraTroops)
    end
    local uc = GetUnitClassForCard(slot.card, true)
    if uc.spawnMax then
        baseBatch = math.min(baseBatch, uc.spawnMax)
    end
    return baseBatch + sealExtra
end

--- 从指定槽位生成一个战斗单位 (overrideLaneIdx: 手动部署时指定车道)
function SpawnUnitFromSlot(slot, isPlayer, overrideLaneIdx)
    local card = slot.card
    local uc = GetUnitClassForCard(card, isPlayer)
    local lm = 1 + ((card.level or 1) - 1) * GameConfig.LEVEL_GROWTH_RATE
    local cStats = ApplyConstellationStats(card)
    local bz = BATTLE_ZONE

    -- 车道分配
    local laneIdx
    if overrideLaneIdx then
        laneIdx = overrideLaneIdx
    elseif not isPlayer then
        laneIdx = EnemyPickLane()
    else
        laneIdx = slot.laneIdx or math.random(1, NUM_LANES)
    end
    local laneCX = GetLaneCenterX(laneIdx)
    local spawnX = laneCX + (math.random() - 0.5) * LANE_WIDTH * 0.6

    local ss = SOLDIER_STAT_SCALE
    -- 大型兵种属性加成（数量少但单体更强）
    local hpM = uc.hpMult or 1.0
    local atkM = uc.atkMult or 1.0
    local unitHp = cStats.hp * lm * ss * 0.6 * hpM
    local unit = {
        x = spawnX,
        y = isPlayer and (bz.bottom - 10 - math.random() * 20) or (bz.top + 10 + math.random() * 20),
        hp = unitHp, maxHp = unitHp,
        atk = cStats.atk * lm * ss * atkM, def = cStats.def * lm * ss * 0.5,
        speed = uc.speed + math.random() * 5,
        atkTimer = math.random() * 0.5, atkCooldown = uc.atkCd,
        atkRange = uc.atkRange,
        alive = true, isPlayer = isPlayer,
        isRanged = uc.isRanged, unitClass = uc,
        animTimer = math.random() * 6.28, flashTimer = 0,
        isHealer = (uc == UNIT_CLASS.HEALER),
        cloudSeed = math.random() * 100,
        breakDmgAdd = cStats.breakDmgAdd or 0,
        laneIdx = laneIdx,  -- 所属车道
        summonTimer = 0,    -- 傀儡操师召唤计时
        summonCount = 0,    -- 傀儡操师已召唤数
    }

    -- 六欲兵符战斗属性注入
    local sb = isPlayer and slot.cachedSealBonus or nil
    if sb then
        -- 慢欲: 移速加成
        if sb.speedPct > 0 then
            unit.speed = unit.speed * (1 + sb.speedPct / 100)
        end
        -- 慢欲: 攻速加成 (降低攻击冷却)
        if sb.atkSpeedPct > 0 then
            unit.atkCooldown = unit.atkCooldown / (1 + sb.atkSpeedPct / 100)
        end
        -- 嗔欲: 暴击率
        unit.sealCritRate = sb.critRate or 0
        -- 痴欲: 减伤
        unit.sealDmgReduction = sb.dmgReduction or 0
        -- 疑欲: 反击率
        unit.sealCounterRate = sb.counterRate or 0
        -- 邪欲: 突破伤害加成%
        unit.sealBreakDmgPct = sb.breakDmgPct or 0
        -- 邪欲: 死亡爆炸ATK%
        unit.sealDeathExplosionPct = sb.deathExplosionPct or 0
    end

    -- 装备基础属性百分比加成 (玩家方: atkPct/defPct/hpPct)
    if isPlayer then
        local eqB = GetEquipmentBonus()
        if eqB.atkPct > 0 then unit.atk = unit.atk * (1 + eqB.atkPct / 100) end
        if eqB.defPct > 0 then unit.def = unit.def * (1 + eqB.defPct / 100) end
        if eqB.hpPct > 0 then
            unit.hp = unit.hp * (1 + eqB.hpPct / 100)
            unit.maxHp = unit.hp
        end
    end

    -- 装备套装额外词条注入 (玩家方, 与兵符叠加)
    if isPlayer then
        local eb = GetEquipmentBonus()
        if eb.speedPct > 0 then
            unit.speed = unit.speed * (1 + eb.speedPct / 100)
        end
        if eb.atkSpeedPct > 0 then
            unit.atkCooldown = unit.atkCooldown / (1 + eb.atkSpeedPct / 100)
        end
        unit.equipCritRate = eb.critRate or 0
        unit.equipDmgReduction = eb.dmgReduction or 0
        unit.equipCounterRate = eb.counterRate or 0
        unit.equipBreakDmgPct = eb.breakDmgPct or 0
        unit.equipDeathExplosionPct = eb.deathExplosionPct or 0
    end

    -- 腐蝇虫群: 一次生成多个小单位
    if uc.swarmCount and uc.swarmCount > 1 then
        for si = 1, uc.swarmCount do
            local swarmUnit = {}
            for k, v in pairs(unit) do swarmUnit[k] = v end
            swarmUnit.x = spawnX + (si - 3.5) * 8
            swarmUnit.y = unit.y + (math.random() - 0.5) * 12
            swarmUnit.cloudSeed = math.random() * 100
            swarmUnit.animTimer = math.random() * 6.28
            swarmUnit.isSwarmling = true
            if isPlayer then table.insert(playerUnits, swarmUnit)
            else table.insert(enemyUnits, swarmUnit) end
        end
        return  -- 虫群不再插入主单位
    end

    if isPlayer then
        table.insert(playerUnits, unit)
    else
        table.insert(enemyUnits, unit)
    end
end

--- 傀儡操师召唤小傀儡 (战斗中调用)
function SpawnPuppet(master, units, isPlayerSide)
    local bz = BATTLE_ZONE
    local puppet = {
        x = master.x + (math.random() - 0.5) * 20,
        y = master.y + (isPlayerSide and -20 or 20),
        hp = master.maxHp * 0.2, maxHp = master.maxHp * 0.2,
        atk = master.atk * 0.5, def = master.def * 0.3,
        speed = 28 + math.random() * 5,
        atkTimer = math.random() * 0.5, atkCooldown = 0.8,
        atkRange = 35,
        alive = true, isPlayer = isPlayerSide,
        isRanged = false, unitClass = UNIT_CLASS.PUPPETEER,
        animTimer = math.random() * 6.28, flashTimer = 0,
        cloudSeed = math.random() * 100,
        breakDmgAdd = 0,
        laneIdx = master.laneIdx,
        isPuppet = true,  -- 标记为傀儡小兵
        summonTimer = 0, summonCount = 0,
    }
    table.insert(units, puppet)
end

--- 敌方AI选择车道：优先选玩家兵最多的车道进行拦截
function EnemyPickLane()
    local laneCounts = { 0, 0, 0, 0, 0 }
    for _, u in ipairs(playerUnits) do
        if u.alive and u.laneIdx then
            laneCounts[u.laneIdx] = laneCounts[u.laneIdx] + 1
        end
    end
    -- 找最多的车道，加一点随机性
    local maxCount = 0
    local candidates = {}
    for i = 1, NUM_LANES do
        if laneCounts[i] > maxCount then
            maxCount = laneCounts[i]
            candidates = { i }
        elseif laneCounts[i] == maxCount then
            table.insert(candidates, i)
        end
    end
    if maxCount == 0 then
        return math.random(1, NUM_LANES)
    end
    return candidates[math.random(1, #candidates)]
end

function UpdateUnits(dt, units, targets, isPlayerSide)
    for _, u in ipairs(units) do
        if u.alive then
            -- 区域减速: 临时降低速度, 帧末恢复
            local origSpeed = u.speed
            if u.zoneSlowUntil and gameState.gameTime < u.zoneSlowUntil then
                u.speed = u.speed * (1.0 - (u.zoneSlowFactor or 0))
                u.isZoneSlowed = true
            else
                u.isZoneSlowed = false
                u.zoneSlowUntil = nil
                u.zoneSlowFactor = nil
            end

            u.animTimer = u.animTimer + dt * 3
            if u.flashTimer > 0 then u.flashTimer = u.flashTimer - dt end
            if u.atkAnimTimer and u.atkAnimTimer > 0 then u.atkAnimTimer = u.atkAnimTimer - dt end

            local ucId = u.unitClass and u.unitClass.id or 1

            if u.isHealer then
                -- 腐灵祭司: 跟随部队前进 + 沿途治疗 + 攻速光环
                u.atkTimer = u.atkTimer + dt
                if u.atkTimer >= u.atkCooldown then
                    local ally = FindLowestHPAlly(u, units)
                    if ally and ally.hp < ally.maxHp then
                        u.atkTimer = 0; u.atkAnimTimer = 0.4
                        local heal = u.atk * 0.8
                        ally.hp = math.min(ally.maxHp, ally.hp + heal)
                        AddFloatText(ally.x, ally.y - 15, "+" .. math.floor(heal), 0.7, { 80, 255, 120 }, 20)
                    end
                end
                -- ★ 腐灵祭司攻速光环: 周围80px内友军攻速提升20%
                local auraRange = 80
                for _, ally in ipairs(units) do
                    if ally.alive and ally ~= u and not ally.isHealer then
                        local adx, ady = ally.x - u.x, ally.y - u.y
                        local ad = math.sqrt(adx * adx + ady * ady)
                        if ad <= auraRange then
                            ally.healerAura = true
                            ally.atkCooldown = (ally.unitClass and ally.unitClass.atkCd or 1.0) * 0.8
                        end
                    end
                end
                -- 跟随前线友军推进（保持在友军后方一定距离）
                local frontAlly = FindFrontAlly(u, units, isPlayerSide)
                if frontAlly then
                    local followY = isPlayerSide and (frontAlly.y + 40) or (frontAlly.y - 40)
                    local ddy = followY - u.y
                    if math.abs(ddy) > 5 then
                        u.y = u.y + (ddy > 0 and 1 or -1) * u.speed * dt
                    end
                    local ddx = frontAlly.x - u.x
                    if math.abs(ddx) > 10 then
                        u.x = u.x + (ddx > 0 and 1 or -1) * u.speed * 0.4 * dt
                    end
                else
                    -- 没有友军时缓慢前进
                    MoveTowardEnemyBase(u, dt, isPlayerSide)
                end

            elseif ucId == 9 then
                -- 噩梦骑兵: 快速冲锋，沿途对碰到的敌人造成撞击伤害，不停下来打
                local targetY = isPlayerSide and BATTLE_ZONE.enemyLine or BATTLE_ZONE.playerLine
                local ddy = targetY - u.y
                if math.abs(ddy) > 1 then
                    local dirY = ddy > 0 and 1 or -1
                    u.y = u.y + dirY * u.speed * dt
                    -- 冲锋沿途撞击：对路径上的敌人造成伤害
                    for _, t in ipairs(targets) do
                        if t.alive then
                            local tdx, tdy = t.x - u.x, t.y - u.y
                            local td = math.sqrt(tdx * tdx + tdy * tdy)
                            if td < 30 then
                                u.atkTimer = u.atkTimer + dt
                                if u.atkTimer >= u.atkCooldown then
                                    u.atkTimer = 0; u.atkAnimTimer = 0.4
                                    local raw = u.atk * 1.2
                                    t.hp = t.hp - raw
                                    t.flashTimer = 0.15
                                    AddFloatText(t.x, t.y - 10, math.floor(raw), 0.5, { 255, 200, 80 }, 14)
                                end
                            end
                        end
                    end
                    -- 车道修正
                    local laneCX = GetLaneCenterX(u.laneIdx or 3)
                    local ldx = laneCX - u.x
                    if math.abs(ldx) > 5 then
                        u.x = u.x + (ldx > 0 and 1 or -1) * u.speed * 0.3 * dt
                    end
                end

            elseif ucId == 10 then
                -- 讨伐巨兽: 行进优先+范围攻击，边走边打挡路敌人
                local blockT, blockD = FindBlockingEnemy(u, targets, u.atkRange, isPlayerSide)
                if blockT then
                    -- 挡路敌人在攻击范围内 → 范围攻击，但不停下来
                    u.atkTimer = u.atkTimer + dt
                    if u.atkTimer >= u.atkCooldown then
                        u.atkTimer = 0; u.atkAnimTimer = 0.4
                        local hitCount = 0
                        for _, t in ipairs(targets) do
                            if t.alive then
                                local tdx, tdy = t.x - u.x, t.y - u.y
                                local td = math.sqrt(tdx * tdx + tdy * tdy)
                                if td <= u.atkRange then
                                    local raw = u.atk * 0.8
                                    t.hp = t.hp - raw
                                    t.flashTimer = 0.15
                                    hitCount = hitCount + 1
                                end
                            end
                        end
                        if hitCount > 0 then
                            AddFloatText(u.x, u.y - 15, "震" .. hitCount .. "人", 0.6, { 255, 160, 50 }, 16)
                        end
                    end
                end
                -- 始终向基地推进
                MoveTowardEnemyBase(u, dt, isPlayerSide)

            elseif ucId == 13 then
                -- 自爆亡魂: 全速冲向基地，碰到敌人也引爆
                local exploded = false
                -- 检查是否碰到敌人
                for _, t in ipairs(targets) do
                    if t.alive then
                        local tdx, tdy = t.x - u.x, t.y - u.y
                        local td = math.sqrt(tdx * tdx + tdy * tdy)
                        if td <= 25 then
                            exploded = true; break
                        end
                    end
                end
                if exploded then
                    -- 自爆! 范围伤害
                    local eRadius = u.unitClass.explosionRadius or 60
                    local eMult = u.unitClass.explosionMult or 2.5
                    local hitCount = 0
                    for _, t in ipairs(targets) do
                        if t.alive then
                            local tdx, tdy = t.x - u.x, t.y - u.y
                            local td = math.sqrt(tdx * tdx + tdy * tdy)
                            if td <= eRadius then
                                local raw = u.atk * eMult
                                t.hp = t.hp - raw
                                t.flashTimer = 0.2
                                hitCount = hitCount + 1
                                if t.hp <= 0 then t.alive = false end
                            end
                        end
                    end
                    AddFloatText(u.x, u.y - 15, "符爆!" .. hitCount .. "人", 0.8, { 255, 200, 50 }, 18)
                    -- 爆炸粒子特效
                    for _ = 1, 8 do
                        AddParticle(u.x, u.y, {
                            vx = (math.random() - 0.5) * 80,
                            vy = (math.random() - 0.5) * 80,
                            life = 0.5 + math.random() * 0.3,
                            size = 3 + math.random() * 4,
                            color = { 255, 180, 50 },
                        })
                    end
                    u.alive = false  -- 自毁
                else
                    -- 全速冲向基地
                    MoveTowardEnemyBase(u, dt, isPlayerSide)
                end

            elseif ucId == 14 and not u.isPuppet then
                -- 傀儡操师(召唤): 缓慢前进，定期召唤小傀儡
                u.summonTimer = (u.summonTimer or 0) + dt
                local sCd = u.unitClass.summonCd or 4.0
                local sMax = u.unitClass.summonMax or 4
                if u.summonTimer >= sCd and (u.summonCount or 0) < sMax then
                    u.summonTimer = 0
                    u.summonCount = (u.summonCount or 0) + 1
                    SpawnPuppet(u, isPlayerSide and playerUnits or enemyUnits, isPlayerSide)
                    AddFloatText(u.x, u.y - 15, "召唤傀儡", 0.6, { 180, 100, 255 }, 14)
                end
                -- 远程攻击范围内敌人
                local bestT, bestD = nil, u.atkRange + 1
                for _, t in ipairs(targets) do
                    if t.alive then
                        local tdx, tdy = t.x - u.x, t.y - u.y
                        local td = math.sqrt(tdx * tdx + tdy * tdy)
                        if td < bestD then bestD = td; bestT = t end
                    end
                end
                if bestT and bestD <= u.atkRange then
                    AttackTarget(u, bestT, dt, isPlayerSide)
                end
                MoveTowardEnemyBase(u, dt, isPlayerSide)

            elseif ucId == 15 then
                -- 霜骨冰巫(减速): 远程攻击附带减速效果，有目标时停下射击
                local bestT, bestD = nil, u.atkRange + 1
                for _, t in ipairs(targets) do
                    if t.alive then
                        local tdx, tdy = t.x - u.x, t.y - u.y
                        local td = math.sqrt(tdx * tdx + tdy * tdy)
                        if td < bestD then bestD = td; bestT = t end
                    end
                end
                if bestT and bestD <= u.atkRange then
                    -- 有目标：停下来射击
                    u.rangedTarget = bestT
                    u.atkTimer = u.atkTimer + dt
                    if u.atkTimer >= u.atkCooldown then
                        u.atkTimer = 0; u.atkAnimTimer = 0.4
                        local atkDefMod = u.atk / (u.atk + bestT.def)
                        local raw = math.max(1, u.atk * atkDefMod * 0.7)  -- 伤害略低
                        bestT.hp = bestT.hp - raw
                        bestT.flashTimer = 0.15
                        -- 施加减速
                        local sf = u.unitClass.slowFactor or 0.4
                        local sd = u.unitClass.slowDuration or 2.0
                        bestT.zoneSlowUntil = gameState.gameTime + sd
                        bestT.zoneSlowFactor = sf
                        AddFloatText(bestT.x, bestT.y - 10, math.floor(raw) .. " 冻", 0.5, { 100, 200, 255 }, 13)
                        if bestT.hp <= 0 then bestT.alive = false end
                        -- 冰蓝弹道特效
                        AddProjectile(u.x, u.y, bestT.x, bestT.y, {100, 200, 255}, isPlayerSide)
                        -- 冰晶粒子
                        for _ = 1, 3 do
                            AddParticle(bestT.x, bestT.y, {
                                vx = (math.random() - 0.5) * 30,
                                vy = -(math.random() * 20),
                                life = 0.4, size = 2 + math.random() * 2,
                                color = { 120, 210, 255 },
                            })
                        end
                    end
                else
                    -- 无目标才推进
                    u.rangedTarget = nil
                    MoveTowardEnemyBase(u, dt, isPlayerSide)
                end

            elseif ucId == 16 or u.isSwarmling then
                -- 腐蝇虫群: 极快攻速，近距离群攻，血薄
                local blockT, blockD = FindBlockingEnemy(u, targets, u.atkRange, isPlayerSide)
                if not blockT then
                    -- 虫群也搜索附近任意敌人（小范围）
                    for _, t in ipairs(targets) do
                        if t.alive then
                            local tdx, tdy = t.x - u.x, t.y - u.y
                            local td = math.sqrt(tdx * tdx + tdy * tdy)
                            if td <= u.atkRange + 15 then
                                blockT = t; blockD = td; break
                            end
                        end
                    end
                end
                if blockT then
                    u.atkTimer = u.atkTimer + dt
                    if u.atkTimer >= u.atkCooldown then
                        u.atkTimer = 0; u.atkAnimTimer = 0.4
                        local raw = math.max(1, u.atk * 0.8)
                        blockT.hp = blockT.hp - raw
                        blockT.flashTimer = 0.1
                        if blockT.hp <= 0 then blockT.alive = false end
                    end
                end
                MoveTowardEnemyBase(u, dt, isPlayerSide)

            elseif ucId == 3 then
                -- 墓碑守卫: 防御型AI，不主动进攻，在自家半场站岗防御
                if not u.guardPostY then
                    -- 分配站岗位置: 在自家半场均匀分布
                    local shieldCount = 0
                    local shieldIdx = 0
                    for _, su in ipairs(units) do
                        if su.alive and su.unitClass and su.unitClass.id == 3 then
                            shieldCount = shieldCount + 1
                            if su == u then shieldIdx = shieldCount end
                        end
                    end
                    if isPlayerSide then
                        -- 玩家半场: centerY(430) ~ playerLine(665) 之间站岗
                        local zoneTop = BATTLE_ZONE.centerY - 20
                        local zoneBot = BATTLE_ZONE.playerLine - 30
                        u.guardPostY = zoneTop + (zoneBot - zoneTop) * shieldIdx / (shieldCount + 1)
                    else
                        -- 敌方半场: enemyLine(195) ~ centerY(430) 之间站岗
                        local zoneTop = BATTLE_ZONE.enemyLine + 30
                        local zoneBot = BATTLE_ZONE.centerY + 20
                        u.guardPostY = zoneTop + (zoneBot - zoneTop) * shieldIdx / (shieldCount + 1)
                    end
                end
                -- 移动到站岗位置
                local laneCX = GetLaneCenterX(u.laneIdx or 3)
                local gdx = laneCX - u.x
                local gdy = u.guardPostY - u.y
                if math.abs(gdy) > 3 then
                    u.y = u.y + (gdy > 0 and 1 or -1) * u.speed * dt
                end
                if math.abs(gdx) > 5 then
                    u.x = u.x + (gdx > 0 and 1 or -1) * u.speed * 0.3 * dt
                end
                -- 攻击范围内的敌人（站岗时也攻击）
                local blockT, blockD = FindBlockingEnemy(u, targets, u.atkRange, isPlayerSide)
                if not blockT then
                    -- 也查找从后方经过的敌人（防御不只看前方）
                    for _, t in ipairs(targets) do
                        if t.alive then
                            local tdx, tdy = t.x - u.x, t.y - u.y
                            local td = math.sqrt(tdx * tdx + tdy * tdy)
                            if td <= u.atkRange then
                                blockT = t; blockD = td
                                break
                            end
                        end
                    end
                end
                if blockT then
                    AttackTarget(u, blockT, dt, isPlayerSide)
                    -- 墓碑守卫嘲讽: 被攻击的敌人会优先攻击墓碑守卫（标记嘲讽源）
                    blockT.tauntedBy = u
                    blockT.tauntTimer = 3.0  -- 嘲讽持续3秒
                end

            elseif ucId == 2 or ucId == 4 or ucId == 7 then
                -- 亡魂弩手/冥火术士/邪骨射手: 远程攻击AI，有目标时停下射击+弹道特效
                local bestT, bestD = nil, u.atkRange + 1
                for _, t in ipairs(targets) do
                    if t.alive then
                        local tdx, tdy = t.x - u.x, t.y - u.y
                        local td = math.sqrt(tdx * tdx + tdy * tdy)
                        if td < bestD then bestD = td; bestT = t end
                    end
                end
                if bestT and bestD <= u.atkRange then
                    -- 有目标：停下来射击
                    local prevTimer = u.atkTimer
                    AttackTarget(u, bestT, dt, isPlayerSide)
                    if u.atkTimer < prevTimer then
                        -- 攻击命中瞬间生成弹道特效
                        local projColor
                        if ucId == 4 then projColor = {180, 130, 255}      -- 冥火术士: 紫色
                        elseif ucId == 7 then projColor = {255, 80, 60}    -- 邪骨射手: 暗红
                        else projColor = {200, 230, 255} end               -- 亡魂弩手: 淡蓝
                        AddProjectile(u.x, u.y, bestT.x, bestT.y, projColor, isPlayerSide)
                    end
                    u.rangedTarget = bestT
                else
                    -- 无目标才向基地推进
                    u.rangedTarget = nil
                    MoveTowardEnemyBase(u, dt, isPlayerSide)
                end

            elseif ucId == 11 then
                -- 夜影刺客: 跨越路线绕后暗杀，对后排目标造成高伤害
                local prioTarget = FindBacklineEnemy(u, targets)
                if prioTarget then
                    local ddx, ddy = prioTarget.x - u.x, prioTarget.y - u.y
                    local dist = math.sqrt(ddx * ddx + ddy * ddy)
                    if dist <= u.atkRange then
                        -- 后排目标在范围内 → 暗杀攻击（绕后加成1.5x）
                        u.stealthing = false
                        u.atkTimer = u.atkTimer + dt
                        if u.atkTimer >= u.atkCooldown then
                            u.atkTimer = 0; u.atkAnimTimer = 0.4
                            local atkDefMod = u.atk / (u.atk + prioTarget.def)
                            local raw = math.max(1, u.atk * atkDefMod)
                            -- 绕后加成: 夜影刺客从后方攻击伤害x1.5
                            local behindBonus = 1.0
                            local isBehind = (isPlayerSide and u.y > prioTarget.y) or (not isPlayerSide and u.y < prioTarget.y)
                            if isBehind then behindBonus = 1.5 end
                            raw = raw * behindBonus
                            local isCrit = math.random() < 0.15  -- 夜影刺客暴击率更高
                            if isCrit then raw = raw * 2.0 end
                            prioTarget.hp = prioTarget.hp - raw
                            prioTarget.flashTimer = 0.15
                            local dmgColor = isBehind and { 255, 80, 200 } or { 255, 200, 80 }
                            local dmgText = isCrit and "暴击!" .. math.floor(raw) or math.floor(raw)
                            AddFloatText(prioTarget.x, prioTarget.y - 10, dmgText, 0.6, dmgColor, isCrit and 18 or 14)
                            if prioTarget.hp <= 0 then prioTarget.alive = false end
                        end
                    else
                        u.stealthing = true
                    end
                    -- 夜影刺客绕后路线: 先横向迂回到目标侧翼，再纵向包抄
                    local targetY = isPlayerSide and BATTLE_ZONE.enemyLine or BATTLE_ZONE.playerLine
                    local baseDir = targetY - u.y
                    if math.abs(baseDir) > 1 then
                        local dirY = baseDir > 0 and 1 or -1
                        u.y = u.y + dirY * u.speed * dt
                    end
                    -- 横向跨越车道靠近后排目标
                    local ldx = prioTarget.x - u.x
                    if math.abs(ldx) > 5 then
                        u.x = u.x + (ldx > 0 and 1 or -1) * u.speed * 0.6 * dt
                    end
                else
                    u.stealthing = false
                    -- 没有后排目标 → 边打挡路敌人边向基地推进
                    local blockT, blockD = FindBlockingEnemy(u, targets, u.atkRange, isPlayerSide)
                    if blockT then
                        AttackTarget(u, blockT, dt, isPlayerSide)
                    end
                    MoveTowardEnemyBase(u, dt, isPlayerSide)
                end

            elseif ucId == 12 then
                -- 骨矛枪兵: 行进优先+贯穿攻击，边走边打挡路敌人
                local blockT, blockD = FindBlockingEnemy(u, targets, u.atkRange, isPlayerSide)
                if blockT then
                    u.atkTimer = u.atkTimer + dt
                    if u.atkTimer >= u.atkCooldown then
                        u.atkTimer = 0; u.atkAnimTimer = 0.4
                        -- 找最近的2个敌人同时攻击
                        local sorted = {}
                        for _, t in ipairs(targets) do
                            if t.alive then
                                local tdx, tdy = t.x - u.x, t.y - u.y
                                local td = math.sqrt(tdx * tdx + tdy * tdy)
                                if td <= u.atkRange + 15 then
                                    table.insert(sorted, { target = t, dist = td })
                                end
                            end
                        end
                        table.sort(sorted, function(a, b) return a.dist < b.dist end)
                        for i = 1, math.min(2, #sorted) do
                            local t = sorted[i].target
                            local atkDefMod = u.atk / (u.atk + t.def)
                            local raw = math.max(1, u.atk * atkDefMod)
                            t.hp = t.hp - raw
                            t.flashTimer = 0.15
                            AddFloatText(t.x, t.y - 10, math.floor(raw), 0.5, { 200, 220, 255 }, 13)
                        end
                    end
                end
                -- 始终向基地推进
                MoveTowardEnemyBase(u, dt, isPlayerSide)

            else
                -- 骷髅剑兵/炼狱战鬼/铁棺重卫: 近战行进优先AI
                -- 嘲讽响应: 如果被墓碑守卫嘲讽，优先攻击墓碑守卫
                if u.tauntedBy and u.tauntedBy.alive and u.tauntTimer and u.tauntTimer > 0 then
                    u.tauntTimer = u.tauntTimer - dt
                    local tdx, tdy = u.tauntedBy.x - u.x, u.tauntedBy.y - u.y
                    local td = math.sqrt(tdx * tdx + tdy * tdy)
                    if td <= u.atkRange + 20 then
                        AttackTarget(u, u.tauntedBy, dt, isPlayerSide)
                    else
                        -- 向嘲讽源移动
                        u.x = u.x + (tdx > 0 and 1 or -1) * u.speed * 0.5 * dt
                        u.y = u.y + (tdy > 0 and 1 or -1) * u.speed * 0.5 * dt
                    end
                else
                    u.tauntedBy = nil
                    -- 只攻击挡路的敌人（同车道+前方+攻击范围内），不追击不偏离路线
                    local blockT, blockD = FindBlockingEnemy(u, targets, u.atkRange, isPlayerSide)
                    if blockT then
                        AttackTarget(u, blockT, dt, isPlayerSide)
                    end
                    -- 始终向基地推进（即使在攻击也继续行进）
                    MoveTowardEnemyBase(u, dt, isPlayerSide)
                end

                -- ★ 敌军差异化 (仅限炼狱战鬼ucId==6)
                if ucId == 6 then
                    -- 炼狱战鬼死亡爆炸: 在 hp<=0 时触发范围伤害
                    if u.hp <= 0 and not u.deathExploded then
                        u.deathExploded = true
                        local explR = 45
                        local explDmg = u.atk * 1.2
                        for _, t in ipairs(targets) do
                            if t.alive then
                                local edx, edy = t.x - u.x, t.y - u.y
                                local ed = math.sqrt(edx * edx + edy * edy)
                                if ed <= explR then
                                    t.hp = t.hp - explDmg
                                    t.flashTimer = 0.2
                                    AddFloatText(t.x, t.y - 10, math.floor(explDmg), 0.5, { 200, 50, 50 }, 14)
                                end
                            end
                        end
                        -- 爆炸粒子
                        for a = 1, 8 do
                            local angle = (a / 8) * math.pi * 2
                            table.insert(particles, {
                                x = u.x, y = u.y,
                                vx = math.cos(angle) * 40, vy = math.sin(angle) * 40,
                                size = 4, life = 0.5, timer = 0,
                                color = { 180, 50, 50 }, isDesign = true,
                            })
                        end
                    end
                end

                -- ★ 铁棺重卫差异化 (ucId==8): 护盾抗性，受到伤害降低15%
                if ucId == 8 then
                    -- 通过在受伤时降低伤害实现（在此标记，AttackTarget检测）
                    u.damageReduction = 0.15
                end
            end

            -- 恢复原始速度 (区域减速只在本帧生效)
            u.speed = origSpeed
        end
    end
end

--- 向敌方基地推进 (提取公用)
function MoveTowardEnemyBase(u, dt, isPlayerSide)
    local targetY = isPlayerSide and BATTLE_ZONE.enemyLine or BATTLE_ZONE.playerLine
    local laneCX = GetLaneCenterX(u.laneIdx or 3)
    local ddx = laneCX - u.x
    local ddy = targetY - u.y
    if math.abs(ddy) > 1 then
        local dirY = ddy > 0 and 1 or -1
        local xCorrect = 0
        if math.abs(ddx) > 5 then
            xCorrect = (ddx > 0 and 1 or -1) * u.speed * 0.3 * dt
        end
        u.y = u.y + dirY * u.speed * dt
        u.x = u.x + xCorrect
    end
end

--- 查找前线友军 (腐灵祭司跟随用)
function FindFrontAlly(healer, units, isPlayerSide)
    local best, bestY = nil, nil
    for _, u in ipairs(units) do
        if u.alive and u ~= healer and not u.isHealer then
            if bestY == nil then
                best = u; bestY = u.y
            else
                if isPlayerSide then
                    if u.y < bestY then best = u; bestY = u.y end  -- 玩家方: Y越小越前
                else
                    if u.y > bestY then best = u; bestY = u.y end  -- 敌方: Y越大越前
                end
            end
        end
    end
    return best
end

--- 查找后排高优先目标 (夜影刺客专用: 远程/腐灵祭司优先)
function FindBacklineEnemy(assassin, targets)
    local best, bestD = nil, 99999
    for _, t in ipairs(targets) do
        if t.alive and (t.isRanged or t.isHealer) then
            local ddx, ddy = t.x - assassin.x, t.y - assassin.y
            local d = math.sqrt(ddx * ddx + ddy * ddy)
            if d < bestD then bestD = d; best = t end
        end
    end
    return best
end

--- 查找附近敌人 (只在interceptRange范围内)
function FindNearbyEnemy(unit, targets, interceptRange)
    local best, bestD = nil, interceptRange + 1
    for _, t in ipairs(targets) do
        if t.alive then
            local ddx, ddy = t.x - unit.x, t.y - unit.y
            local d = math.sqrt(ddx * ddx + ddy * ddy)
            if d < bestD then bestD = d; best = t end
        end
    end
    if best and bestD <= interceptRange then
        return best, bestD
    end
    return nil, 99999
end

--- 查找挡路敌人 (行进优先模式: 只找同车道+在前方的敌人)
--- 所有普通兵种使用此函数，确保行军到基地为首要目标
function FindBlockingEnemy(unit, targets, atkRange, isPlayerSide)
    local laneTolerance = LANE_WIDTH * 0.7  -- 同车道横向容差
    local best, bestD = nil, atkRange + 1
    for _, t in ipairs(targets) do
        if t.alive then
            local ddx = t.x - unit.x
            local ddy = t.y - unit.y
            -- 检查: 必须在前方 (玩家方向上推进 = Y 减小方向)
            local isAhead = (isPlayerSide and ddy < 0) or (not isPlayerSide and ddy > 0)
            -- 检查: 大致同车道 (横向距离 < 容差)
            local sameishLane = math.abs(ddx) < laneTolerance
            if isAhead and sameishLane then
                local d = math.sqrt(ddx * ddx + ddy * ddy)
                if d < bestD then bestD = d; best = t end
            end
        end
    end
    if best and bestD <= atkRange then
        return best, bestD
    end
    return nil, 99999
end

--- 攻击目标 (从原UpdateUnits提取)
function AttackTarget(u, t, dt, isPlayerSide)
    u.atkTimer = u.atkTimer + dt
    if u.atkTimer >= u.atkCooldown then
        u.atkTimer = 0; u.atkAnimTimer = 0.4
        local atkDefMod = u.atk / (u.atk + t.def)
        local raw = math.max(1, u.atk * atkDefMod)
        -- 暴击率: 基础10% + 兵符加成 + 装备词条加成
        local critChance = 0.1 + (u.sealCritRate or 0) / 100 + (u.equipCritRate or 0) / 100
        local isCrit = math.random() < critChance
        if isCrit then raw = raw * 2.0 end
        -- 铁棺重卫护盾抗性: 减少受到的伤害
        if t.damageReduction and t.damageReduction > 0 then
            raw = raw * (1 - t.damageReduction)
        end
        -- 减伤: 兵符 + 装备词条
        local totalDmgReduction = (t.sealDmgReduction or 0) + (t.equipDmgReduction or 0)
        if totalDmgReduction > 0 then
            raw = raw * (1 - totalDmgReduction / 100)
        end
        t.hp = t.hp - raw
        -- 反击: 兵符 + 装备词条 (受击方概率反弹50%自身ATK伤害)
        local totalCounterRate = (t.sealCounterRate or 0) + (t.equipCounterRate or 0)
        if totalCounterRate > 0 and t.alive and math.random() * 100 < totalCounterRate then
            local counterDmg = math.max(1, t.atk * 0.5)
            u.hp = u.hp - counterDmg
            u.flashTimer = 0.1
            -- 反击特效 (紫色闪光)
            AddParticle(u.x, u.y, {
                vx = (math.random() - 0.5) * 40,
                vy = -(math.random() * 20 + 5),
                life = 0.25, size = 2,
                color = { 180, 160, 220 },
            })
            if u.hp <= 0 then u.alive = false end
        end
        t.flashTimer = 0.15
        for _ = 1, 3 do
            AddParticle(t.x, t.y, {
                vx = (math.random() - 0.5) * 50,
                vy = -(math.random() * 30 + 5),
                life = 0.3 + math.random() * 0.3,
                size = 1 + math.random() * 2,
                color = isPlayerSide and { 200, 230, 255 } or { 255, 100, 80 },
            })
        end
        if t.hp <= 0 then
            t.alive = false
            if isPlayerSide then
                gameState.totalKills = gameState.totalKills + 1
            end
            -- 死亡爆炸: 兵符 + 装备词条 (被击杀单位如果有死亡爆炸属性，对周围敌人造成AOE伤害)
            local totalDeathExplPct = (t.sealDeathExplosionPct or 0) + (t.equipDeathExplosionPct or 0)
            if totalDeathExplPct > 0 then
                local explDmg = t.atk * totalDeathExplPct / 100
                local explRadius = 60
                local enemies = isPlayerSide and playerUnits or enemyUnits  -- 被杀方的敌人
                for _, e in ipairs(enemies) do
                    if e.alive and e ~= u then
                        local edx = e.x - t.x
                        local edy = e.y - t.y
                        local ed = math.sqrt(edx * edx + edy * edy)
                        if ed <= explRadius then
                            e.hp = e.hp - explDmg
                            e.flashTimer = 0.15
                            if e.hp <= 0 then e.alive = false end
                        end
                    end
                end
                -- 死亡爆炸特效 (紫红色扩散)
                for _ = 1, 12 do
                    AddParticle(t.x, t.y, {
                        vx = (math.random() - 0.5) * 150,
                        vy = (math.random() - 0.5) * 150,
                        life = 0.4 + math.random() * 0.3,
                        size = 3 + math.random() * 3,
                        color = { 200, 50, 200 },
                    })
                end
                AddFloatText(t.x, t.y - 20, "邪爆!", 0.6, { 200, 50, 200 }, 18)
            end
            for _ = 1, 8 do
                AddParticle(t.x, t.y, {
                    vx = (math.random() - 0.5) * 120,
                    vy = -(math.random() * 60 + 10),
                    life = 0.5 + math.random() * 0.4,
                    size = 2 + math.random() * 2.5,
                    color = isPlayerSide and { 255, 160, 60 } or { 120, 200, 255 },
                })
            end
        end
        AddFloatText(t.x, t.y - 15, math.floor(raw) .. (isCrit and "!" or ""),
            0.7, isCrit and { 255, 220, 50 } or (isPlayerSide and { 255, 255, 255 } or { 255, 100, 100 }),
            isCrit and 26 or 20)
    end
end

function FindNearest(unit, targets)
    local best, bestD = nil, 99999
    for _, t in ipairs(targets) do
        if t.alive then
            local ddx, ddy = t.x - unit.x, t.y - unit.y
            local d = math.sqrt(ddx * ddx + ddy * ddy)
            if d < bestD then bestD = d; best = t end
        end
    end
    return best, bestD
end

function FindLowestHPAlly(unit, allies)
    local best, bestRatio = nil, 1.0
    for _, a in ipairs(allies) do
        if a.alive and a ~= unit then
            local r = a.hp / a.maxHp
            if r < bestRatio then bestRatio = r; best = a end
        end
    end
    return best
end

function AddFloatText(x, y, text, duration, color, fontSize)
    if #floatTexts >= 50 then return end
    table.insert(floatTexts, {
        x = x, y = y, text = text,
        timer = 0, duration = duration or 1.0,
        color = color or { 255, 255, 255 },
        fontSize = fontSize or 12,
    })
end

-- ============================================================================
-- 坐标转换 (含华为/HarmonyOS 触摸坐标系自动检测)
-- ============================================================================

--- 获取触摸坐标的有效DPR（自动检测设备是返回物理像素还是逻辑像素）
--- @return number effectiveDPR 1.0表示触摸坐标已是逻辑像素，>1表示物理像素需要除DPR
function GetTouchDPR()
    if touchCoordDPR then return touchCoordDPR end
    return GetGraphics():GetDPR()
end

--- 自动检测触摸坐标系统（在前N次触摸时调用）
--- 原理：如果触摸坐标超过了逻辑像素范围(physW/dpr)，则一定是物理像素
--- 如果N次采样都未超出，且DPR>1，则很可能设备返回的已经是逻辑像素
function DetectTouchCoordSystem(sx, sy)
    if touchCoordDPR then return end  -- 已检测完毕
    if screenW <= 0 or screenH <= 0 then return end  -- 渲染尚未初始化

    _touchDetectSamples = _touchDetectSamples + 1
    local g = GetGraphics()
    local dpr = g:GetDPR()

    -- 如果DPR≈1，无需检测，物理和逻辑像素相同
    if dpr < 1.05 then
        touchCoordDPR = 1.0
        print(string.format("[TouchDetect] DPR≈1 (%.2f), 无需坐标转换", dpr))
        return
    end

    -- 检查触摸坐标是否超出逻辑像素范围（加少量容差避免边缘误判）
    local margin = 2
    if sx > screenW + margin or sy > screenH + margin then
        _touchExceedsLogical = true
    end

    if _touchExceedsLogical then
        -- 有坐标超出逻辑范围 → 确认是物理像素
        touchCoordDPR = dpr
        print(string.format("[TouchDetect] 物理像素坐标确认 (DPR=%.2f, sample=%d, sx=%.0f>logW=%.0f)",
            dpr, _touchDetectSamples, sx, screenW))
        return
    end

    if _touchDetectSamples >= _touchDetectMax then
        -- 采样完毕，所有坐标都在逻辑像素范围内
        -- 再做一个额外验证：如果最大触摸坐标非常小（远小于物理像素范围），
        -- 那大概率是逻辑像素
        touchCoordDPR = 1.0
        print(string.format("[TouchDetect] 逻辑像素坐标推断 (DPR=%.2f, %d次采样均未超出logW=%.0f×logH=%.0f)",
            dpr, _touchDetectSamples, screenW, screenH))
    end
end

function ScreenToDesign(sx, sy)
    local dpr = GetTouchDPR()
    local lx, ly = sx / dpr, sy / dpr
    return (lx - offsetX) / scale, (ly - offsetY) / scale
end

function ScreenToLogical(sx, sy)
    local dpr = GetTouchDPR()
    return sx / dpr, sy / dpr
end

function DesignToLogical(dx, dy)
    return dx * scale + offsetX, dy * scale + offsetY
end

function LogicalToDesign(lx, ly)
    return (lx - offsetX) / scale, (ly - offsetY) / scale
end

-- ============================================================================
-- 输入: 碰撞检测
-- ============================================================================

function HitSlotCard(dx, dy)
    local halfW = SLOT_CARD_W / 2 + 4
    local halfH = SLOT_CARD_H / 2 + 4
    for i, slot in ipairs(PLAYER_SLOTS) do
        if slot.filled and slot.card then
            if dx >= slot.cx - halfW and dx <= slot.cx + halfW and
               dy >= slot.cy - halfH and dy <= slot.cy + halfH then
                return slot.card, i, false
            end
        end
    end
    for i, slot in ipairs(ENEMY_SLOTS) do
        if slot.filled and slot.card then
            if dx >= slot.cx - halfW and dx <= slot.cx + halfW and
               dy >= slot.cy - halfH and dy <= slot.cy + halfH then
                return slot.card, i, true
            end
        end
    end
    return nil, 0, false
end

function HitInventoryCard(lx, ly)
    local sl = shopLayout
    if ly < sl.y or ly > sl.y + sl.h then return nil, 0 end
    local visCount = GameConfig.INVENTORY_VISIBLE
    for vi = 1, visCount do
        local invIdx = invScrollOffset + vi
        if invIdx <= #inventory and inventory[invIdx] then
            local cx = sl.startX + (vi - 1) * (sl.cardW + sl.gap)
            local cy = sl.y + 20
            if lx >= cx and lx <= cx + sl.cardW and ly >= cy and ly <= cy + sl.cardH then
                return inventory[invIdx], invIdx
            end
        end
    end
    return nil, 0
end

function HitArrowLeft(lx, ly)
    local sl = shopLayout
    if ly < sl.y or ly > sl.y + sl.h then return false end
    return lx >= sl.arrowLeftX and lx <= sl.arrowLeftX + sl.arrowLeftW
end

function HitArrowRight(lx, ly)
    local sl = shopLayout
    if ly < sl.y or ly > sl.y + sl.h then return false end
    return lx >= sl.arrowRightX and lx <= sl.arrowRightX + sl.arrowRightW
end

function HitDrawButton(lx, ly)
    local sl = shopLayout
    return lx >= sl.drawBtnX and lx <= sl.drawBtnX + sl.drawBtnW and
           ly >= sl.drawBtnY and ly <= sl.drawBtnY + sl.drawBtnH
end

--- 检测点击商店卡牌 (逻辑坐标)
function HitShopCard(lx, ly)
    for i, item in ipairs(shopCards) do
        if item._rect and not item.sold then
            local r = item._rect
            if lx >= r.x and lx <= r.x + r.w and ly >= r.y and ly <= r.y + r.h then
                return i, item
            end
        end
    end
    return 0, nil
end

--- 检测点击开战按钮 (设计坐标)
function HitFightButton(dx, dy)
    if not shopFightBtnRect then return false end
    local r = shopFightBtnRect
    return dx >= r.x and dx <= r.x + r.w and dy >= r.y and dy <= r.y + r.h
end

-- ============================================================================
-- 输入事件
-- ============================================================================

function HandleMouseDown(eventType, eventData)
    if eventData["Button"]:GetInt() ~= MOUSEB_LEFT then return end
    BeginPress(eventData["X"]:GetInt(), eventData["Y"]:GetInt(), -1)
end

function HandleMouseMove(eventType, eventData)
    HandleMoveLogic(eventData["X"]:GetInt(), eventData["Y"]:GetInt(), -1)
end

function HandleMouseUp(eventType, eventData)
    if eventData["Button"]:GetInt() ~= MOUSEB_LEFT then return end
    EndPress(eventData["X"]:GetInt(), eventData["Y"]:GetInt(), -1)
end

function HandleTouchBegin(eventType, eventData)
    local tx, ty = eventData["X"]:GetInt(), eventData["Y"]:GetInt()
    DetectTouchCoordSystem(tx, ty)
    -- 前3次触摸打印诊断日志
    if _touchDetectSamples <= 3 then
        print(string.format("[TouchDiag] raw=(%d,%d) logScreen=(%.0f,%.0f) physScreen=(%d,%d) dpr=%.2f touchDPR=%s",
            tx, ty, screenW, screenH,
            GetGraphics():GetWidth(), GetGraphics():GetHeight(),
            GetGraphics():GetDPR(),
            touchCoordDPR and string.format("%.2f", touchCoordDPR) or "detecting"))
    end
    BeginPress(tx, ty, eventData["TouchID"]:GetInt())
end

function HandleTouchMove(eventType, eventData)
    local tx, ty = eventData["X"]:GetInt(), eventData["Y"]:GetInt()
    DetectTouchCoordSystem(tx, ty)
    HandleMoveLogic(tx, ty, eventData["TouchID"]:GetInt())
end

function HandleTouchEnd(eventType, eventData)
    EndPress(eventData["X"]:GetInt(), eventData["Y"]:GetInt(), eventData["TouchID"]:GetInt())
end

-- === 文本输入事件（自定义名字） ===
function HandleTextInput(eventType, eventData)
    local ch = eventData:GetString("Text")
    if not ch or #ch == 0 then return end

    -- CDK 输入拦截 (优先)
    if cdkState.inputOpen then
        local upper = string.upper(ch)
        -- 接受 A-Z, 0-9, - (CDK码字符)
        if upper:match("^[A-Z0-9%-]$") then
            if #cdkState.inputText < 20 then
                cdkState.inputText = cdkState.inputText .. upper
            end
        end
        return
    end

    -- 阵营创建输入
    if gameState.phase == "FACTION" and factionUI.inputTarget then
        if factionUI.inputTarget == "name" then
            local nameLen = utf8.len(factionUI.createName) or 0
            if nameLen < 8 then factionUI.createName = factionUI.createName .. ch end
        elseif factionUI.inputTarget == "desc" then
            local descLen = utf8.len(factionUI.createDesc) or 0
            if descLen < 30 then factionUI.createDesc = factionUI.createDesc .. ch end
        elseif factionUI.inputTarget == "chat" then
            if not factionUI.chatInput then factionUI.chatInput = "" end
            local chatLen = utf8.len(factionUI.chatInput) or 0
            if chatLen < 50 then factionUI.chatInput = factionUI.chatInput .. ch end
        elseif factionUI.inputTarget == "rename" then
            if not factionUI.renameInput then factionUI.renameInput = "" end
            local renameLen = utf8.len(factionUI.renameInput) or 0
            if renameLen < 8 then factionUI.renameInput = factionUI.renameInput .. ch end
        elseif factionUI.inputTarget == "announce" then
            if not factionUI.announceInput then factionUI.announceInput = "" end
            local annLen = utf8.len(factionUI.announceInput) or 0
            if annLen < 200 then factionUI.announceInput = factionUI.announceInput .. ch end
        end
        return
    end

    -- 好友搜索输入
    if gameState.phase == "FRIENDS" and friendsUI.inputActive then
        -- 只接受数字
        if ch:match("^[0-9]$") then
            if #friendsUI.searchId < 15 then
                friendsUI.searchId = friendsUI.searchId .. ch
            end
        end
        return
    end

    -- 世界聊天输入
    if worldChatUI.expanded and worldChatUI.inputActive then
        if not worldChatUI.chatInput then worldChatUI.chatInput = "" end
        local chatLen = utf8.len(worldChatUI.chatInput) or 0
        if chatLen < 60 then worldChatUI.chatInput = worldChatUI.chatInput .. ch end
        return
    end

    -- 邮件写信输入
    if gameState.phase == "MAIL_BOX" and welfareState.mail.composing and welfareState.mail.composeData then
        local cd = welfareState.mail.composeData
        if cd.inputFocus == "uid" then
            -- UID只接受数字
            if ch:match("^[0-9]$") then
                if #cd.targetUid < 15 then cd.targetUid = cd.targetUid .. ch end
            end
        elseif cd.inputFocus == "subject" then
            local subLen = utf8.len(cd.subject) or 0
            if subLen < 20 then cd.subject = cd.subject .. ch end
        elseif cd.inputFocus == "body" then
            local bodyLen = utf8.len(cd.body) or 0
            if bodyLen < 100 then cd.body = cd.body .. ch end
        elseif cd.inputFocus == "jade" then
            if ch:match("^[0-9]$") then
                local s = cd.jadeInputText or "0"
                if #s < 8 then cd.jadeInputText = s .. ch end
                cd.rewardJade = tonumber(cd.jadeInputText) or 0
            end
        end
        return
    end

    -- 个人资料名字输入
    if not profileState.isInputActive then return end
    if gameState.phase ~= "PROFILE" then return end
    -- 限制最大5个UTF-8字符
    local nameLen = utf8.len(profileState.customName) or 0
    if nameLen < 5 then
        profileState.customName = profileState.customName .. ch
    end
end

function HandleKeyDown(eventType, eventData)
    local key = eventData:GetInt("Key")

    -- 云数据加载中拦截键盘操作
    if CloudManager.IsCloudLoading() then return end

    -- CDK 输入拦截 (优先)
    if cdkState.inputOpen then
        if key == KEY_BACKSPACE then
            local s = cdkState.inputText
            if #s > 0 then cdkState.inputText = s:sub(1, -2) end
        elseif key == KEY_RETURN or key == KEY_KP_ENTER then
            TryRedeemCDK()
        elseif key == KEY_ESCAPE then
            cdkState.inputOpen = false
            cdkState.inputText = ""
            input:SetScreenKeyboardVisible(false)
        end
        return
    end

    -- 阵营创建输入 KeyDown
    if gameState.phase == "FACTION" and factionUI.inputTarget then
        if key == KEY_BACKSPACE then
            if factionUI.inputTarget == "name" then
                local s = factionUI.createName
                if #s > 0 then
                    local bytes = { string.byte(s, 1, #s) }
                    local i = #bytes
                    while i > 0 and bytes[i] >= 0x80 and bytes[i] < 0xC0 do i = i - 1 end
                    if i > 0 then i = i - 1 end
                    factionUI.createName = string.sub(s, 1, i)
                end
            elseif factionUI.inputTarget == "desc" then
                local s = factionUI.createDesc
                if #s > 0 then
                    local bytes = { string.byte(s, 1, #s) }
                    local i = #bytes
                    while i > 0 and bytes[i] >= 0x80 and bytes[i] < 0xC0 do i = i - 1 end
                    if i > 0 then i = i - 1 end
                    factionUI.createDesc = string.sub(s, 1, i)
                end
            elseif factionUI.inputTarget == "chat" then
                local s = factionUI.chatInput or ""
                if #s > 0 then
                    local bytes = { string.byte(s, 1, #s) }
                    local i = #bytes
                    while i > 0 and bytes[i] >= 0x80 and bytes[i] < 0xC0 do i = i - 1 end
                    if i > 0 then i = i - 1 end
                    factionUI.chatInput = string.sub(s, 1, i)
                end
            elseif factionUI.inputTarget == "rename" then
                local s = factionUI.renameInput or ""
                if #s > 0 then
                    local bytes = { string.byte(s, 1, #s) }
                    local i = #bytes
                    while i > 0 and bytes[i] >= 0x80 and bytes[i] < 0xC0 do i = i - 1 end
                    if i > 0 then i = i - 1 end
                    factionUI.renameInput = string.sub(s, 1, i)
                end
            elseif factionUI.inputTarget == "announce" then
                local s = factionUI.announceInput or ""
                if #s > 0 then
                    local bytes = { string.byte(s, 1, #s) }
                    local i = #bytes
                    while i > 0 and bytes[i] >= 0x80 and bytes[i] < 0xC0 do i = i - 1 end
                    if i > 0 then i = i - 1 end
                    factionUI.announceInput = string.sub(s, 1, i)
                end
            end
        elseif key == KEY_RETURN or key == KEY_KP_ENTER then
            -- 改名输入回车直接提交
            if factionUI.inputTarget == "rename" and factionUI.renamePopup then
                local newName = factionUI.renameInput or ""
                if #newName > 0 then
                    if (playerInfo.jade or 0) < 1000 then
                        ShowToast("虎符不足，改名需要1000虎符")
                    else
                        playerInfo.jade = playerInfo.jade - 1000
                        CloudManager.RenameFaction(newName, function(ok, reason)
                            if ok then
                                ShowToast("阵营已更名为「" .. newName .. "」(-1000虎符)")
                                factionUI.loaded = false; factionUI.loading = false
                                if SaveGameProgress then SaveGameProgress() end
                            else
                                playerInfo.jade = playerInfo.jade + 1000
                                ShowToast("改名失败: " .. tostring(reason))
                            end
                        end)
                    end
                end
                factionUI.renamePopup = false; factionUI.renameInput = ""
                factionUI.inputTarget = nil; input:SetScreenKeyboardVisible(false)
                return
            end
            -- 聊天输入回车直接发送 (云端同步)
            if factionUI.inputTarget == "chat" and factionUI.chatInput and #factionUI.chatInput > 0 then
                local filteredText = FilterBannedWords(factionUI.chatInput)
                local senderName = CloudManager._myTapNickname or factionUI.myNickname or playerInfo.name or "我"
                CloudManager.SendFactionChat(filteredText, senderName)
                playerInfo.totalFactionChat = (playerInfo.totalFactionChat or 0) + 1
                factionUI.chatInput = ""
            end
            factionUI.inputTarget = nil; input:SetScreenKeyboardVisible(false)
        elseif key == KEY_ESCAPE then
            if factionUI.renamePopup then
                factionUI.renamePopup = false; factionUI.renameInput = ""
            end
            factionUI.inputTarget = nil; input:SetScreenKeyboardVisible(false)
        end
        return
    end

    -- 好友搜索输入 KeyDown
    if gameState.phase == "FRIENDS" and friendsUI.inputActive then
        if key == KEY_BACKSPACE then
            local s = friendsUI.searchId
            if #s > 0 then friendsUI.searchId = s:sub(1, -2) end
        elseif key == KEY_RETURN or key == KEY_KP_ENTER then
            friendsUI.inputActive = false; input:SetScreenKeyboardVisible(false)
            -- 自动触发搜索
            if #friendsUI.searchId > 0 then
                friendsUI.searchResult = nil; friendsUI.searchNotFound = false
                local searchUid = tonumber(friendsUI.searchId)
                if searchUid then
                    CloudManager.SearchPlayer(searchUid, function(player)
                        if player then friendsUI.searchResult = player; friendsUI.searchNotFound = false
                        else friendsUI.searchNotFound = true end
                    end)
                end
            end
        elseif key == KEY_ESCAPE then
            friendsUI.inputActive = false; input:SetScreenKeyboardVisible(false)
        end
        return
    end

    -- 世界聊天 KeyDown
    if worldChatUI.expanded and worldChatUI.inputActive then
        if key == KEY_BACKSPACE then
            local s = worldChatUI.chatInput or ""
            if #s > 0 then
                local bytes = { string.byte(s, 1, #s) }
                local i = #bytes
                while i > 0 and bytes[i] >= 0x80 and bytes[i] < 0xC0 do i = i - 1 end
                if i > 0 then i = i - 1 end
                worldChatUI.chatInput = string.sub(s, 1, i)
            end
        elseif key == KEY_RETURN or key == KEY_KP_ENTER then
            if worldChatUI.chatInput and #worldChatUI.chatInput > 0 then
                local filteredText = FilterBannedWords(worldChatUI.chatInput)
                local senderName = CloudManager._myTapNickname or factionUI.myNickname or playerInfo.name or "无名"
                CloudManager.SendWorldChat(filteredText, senderName)
                worldChatUI.chatInput = ""
            end
            worldChatUI.inputActive = false; input:SetScreenKeyboardVisible(false)
        elseif key == KEY_ESCAPE then
            worldChatUI.expanded = false; worldChatUI.inputActive = false
            worldChatUI.chatInput = ""; input:SetScreenKeyboardVisible(false)
        end
        return
    end

    -- 邮件写信 KeyDown
    if gameState.phase == "MAIL_BOX" and welfareState.mail.composing and welfareState.mail.composeData then
        local cd = welfareState.mail.composeData
        if key == KEY_BACKSPACE then
            local field = cd.inputFocus
            if field == "uid" then
                if #cd.targetUid > 0 then cd.targetUid = cd.targetUid:sub(1, -2) end
            elseif field == "subject" then
                local s = cd.subject
                if #s > 0 then
                    local bytes = { string.byte(s, 1, #s) }
                    local i = #bytes
                    while i > 0 and bytes[i] >= 0x80 and bytes[i] < 0xC0 do i = i - 1 end
                    if i > 0 then i = i - 1 end
                    cd.subject = string.sub(s, 1, i)
                end
            elseif field == "body" then
                local s = cd.body
                if #s > 0 then
                    local bytes = { string.byte(s, 1, #s) }
                    local i = #bytes
                    while i > 0 and bytes[i] >= 0x80 and bytes[i] < 0xC0 do i = i - 1 end
                    if i > 0 then i = i - 1 end
                    cd.body = string.sub(s, 1, i)
                end
            elseif field == "jade" then
                local s = cd.jadeInputText or "0"
                if #s > 1 then
                    cd.jadeInputText = s:sub(1, -2)
                else
                    cd.jadeInputText = "0"
                end
                cd.rewardJade = tonumber(cd.jadeInputText) or 0
            end
        elseif key == KEY_TAB then
            -- Tab键切换输入焦点
            if cd.isManage then
                cd.inputFocus = "uid"
            else
                if cd.inputFocus == "uid" then cd.inputFocus = "subject"
                elseif cd.inputFocus == "subject" then cd.inputFocus = "body"
                elseif cd.inputFocus == "body" then cd.inputFocus = cd.isAdmin and "jade" or "uid"
                else cd.inputFocus = "uid" end
            end
        elseif key == KEY_ESCAPE then
            welfareState.mail.composing = false
            welfareState.mail.composeData = nil
            input:SetScreenKeyboardVisible(false)
        end
        return
    end

    if not profileState.isInputActive then return end
    if gameState.phase ~= "PROFILE" then return end
    if key == KEY_BACKSPACE then
        local s = profileState.customName
        if #s > 0 then
            -- 删除最后一个UTF-8字符
            local bytes = { string.byte(s, 1, #s) }
            local i = #bytes
            while i > 0 and bytes[i] >= 0x80 and bytes[i] < 0xC0 do
                i = i - 1
            end
            if i > 0 then i = i - 1 end
            profileState.customName = string.sub(s, 1, i)
        end
    elseif key == KEY_RETURN or key == KEY_KP_ENTER then
        profileState.isInputActive = false
        input:SetScreenKeyboardVisible(false)
    end
end

_lastPressFrame = -1  -- 全局防抖: 防止同一帧 Touch+Mouse 双重触发
function BeginPress(sx, sy, touchId)
    local curFrame = time:GetFrameNumber()
    if curFrame == _lastPressFrame then return end
    _lastPressFrame = curFrame

    -- === 教程点击拦截 ===
    if tutorialState.active then
        if HandleTutorialClick(sx, sy) then
            return  -- 教程已处理, 不传递给正常逻辑
        end
    end

    -- === LOADING 阶段点击提示 ===
    if gameState.phase == "LOADING" then
        loadingClickTipTimer = 2.5
        return
    end

    -- === 个人资料界面输入 ===
    if gameState.phase == "PROFILE" then
        local dx, dy = ScreenToDesign(sx, sy)
        local function HitRect(r)
            return r and dx >= r.x and dx <= r.x + r.w and dy >= r.y and dy <= r.y + r.h
        end
        -- 头像选择
        for i, rect in ipairs(profileAvatarRects) do
            if HitRect(rect) then
                profileState.selectedAvatar = i
                return
            end
        end
        -- 名字选择 (含自定义选项)
        for i, rect in ipairs(profileNameRects) do
            if HitRect(rect) then
                profileState.selectedName = i
                if i == CUSTOM_NAME_IDX then
                    -- 点击自定义: 启动文本输入
                    profileState.isInputActive = true
                    input:SetScreenKeyboardVisible(true)
                else
                    profileState.isInputActive = false
                    input:SetScreenKeyboardVisible(false)
                end
                return
            end
        end
        -- 确认按钮
        if HitRect(profileConfirmBtnRect) then
            -- (教程资源检查已移除，无需等待下载)
            playerInfo.avatarIdx = AVATAR_OPTIONS[profileState.selectedAvatar] or 1
            if profileState.selectedName == CUSTOM_NAME_IDX and #profileState.customName > 0 then
                playerInfo.name = profileState.customName
            else
                playerInfo.name = PRESET_NAMES[profileState.selectedName] or "无名武灵"
            end
            playerInfo.profileSet = true
            profileState.isInputActive = false
            input:SetScreenKeyboardVisible(false)
            -- 立即保存，确保 profileSet 状态持久化
            SaveGameProgress()
            -- 模块下载已在阻塞加载完成后自动启动（InitModuleDownloads）
            if profileState.editMode then
                -- 编辑模式：直接返回，不触发新手引导
                profileState.editMode = false
                PopPhase()
                print("=== 资料编辑完成: " .. playerInfo.name .. " ===")
            elseif not gameSettings.tutorialCompleted then
                -- 首次创建资料：启动新手引导
                tutorialState.active = true
                tutorialState.step = 2
                tutorialState.fadeTimer = 0
                tutorialState.hintTimer = 0
                tutorialState.stepTimer = 0
                SaveSettings()
                gameState.phase = "MENU"
                phaseChangeCooldown = 0.3
                print("=== 资料设置完成, 启动新手引导 ===")
            else
                gameState.phase = "MENU"
                print("=== 资料设置完成: " .. playerInfo.name .. " ===")
            end
        end
        return
    end

    -- ======== 统一规则弹窗交互 (全局最高优先级) ========
    if phaseRulePopup.show then
        local dx, dy = ScreenToDesign(sx, sy)
        local function HitRectG(r)
            return r and dx >= r.x and dx <= r.x + r.w and dy >= r.y and dy <= r.y + r.h
        end
        local cr = phaseRulePopup.closeBtnRect
        if cr and HitRectG(cr) then
            phaseRulePopup.show = false
            phaseRulePopup.isDragging = false
            PlaySFX(AUDIO.sfx_click)
            return
        end
        local pr = phaseRulePopup.panelRect
        if pr and HitRectG(pr) then
            phaseRulePopup.isDragging = true
            phaseRulePopup.lastTouchY = dy
            phaseRulePopup.vel = 0
        else
            phaseRulePopup.show = false
            phaseRulePopup.isDragging = false
        end
        return
    end

    -- ======== 统一 "?" 按钮点击检测 (全局) ========
    if phaseRulePopup.helpBtnRect and gameState.phase ~= "BATTLE" then
        local dx, dy = ScreenToDesign(sx, sy)
        local _hbr = phaseRulePopup.helpBtnRect
        if _hbr and dx >= _hbr.x and dx <= _hbr.x + _hbr.w
            and dy >= _hbr.y and dy <= _hbr.y + _hbr.h then
            phaseRulePopup.show = true
            phaseRulePopup.phase = gameState.phase
            phaseRulePopup.scrollY = 0
            phaseRulePopup.vel = 0
            phaseRulePopup.isDragging = false
            PlaySFX(AUDIO.sfx_click)
            return
        end
    end

    -- 首页按钮点击检测
    if gameState.phase == "MENU" then
        -- 防穿透：刚从其他界面返回时忽略点击
        if phaseChangeCooldown > 0 then return end
        local dx, dy = ScreenToDesign(sx, sy)
        -- 辅助: 检测点是否在矩形内
        local function HitRect(r)
            return r and dx >= r.x and dx <= r.x + r.w and dy >= r.y and dy <= r.y + r.h
        end
        -- ======== 按钮位置调整模式交互 (最高优先级，必须在所有其他检测之前) ========
        if settingsPage.btnAdjustMode then
            -- 组切换标签点击
            if settingsPage.adjGroupBtnRects then
                for _, gr in ipairs(settingsPage.adjGroupBtnRects) do
                    if HitRect(gr) then
                        settingsPage.adjActiveGroup = gr.key
                        PlaySFX(AUDIO.sfx_click)
                        return
                    end
                end
            end
            -- 保存按钮 (保存所有组)
            if HitRect(settingsPage.adjSaveBtnRect) then
                gameSettings.btnOffsetX = settingsPage.adjOffsetX
                gameSettings.btnOffsetY = settingsPage.adjOffsetY
                gameSettings.btnScale = settingsPage.adjScale
                gameSettings.rightBtnOffsetX = settingsPage.adjRightBtnOffsetX
                gameSettings.rightBtnOffsetY = settingsPage.adjRightBtnOffsetY
                gameSettings.infoPanelOffsetX = settingsPage.adjInfoPanelOffsetX
                gameSettings.infoPanelOffsetY = settingsPage.adjInfoPanelOffsetY
                gameSettings.hudOffsetX = settingsPage.adjHudOffsetX
                gameSettings.hudOffsetY = settingsPage.adjHudOffsetY
                SaveSettings()
                settingsPage.btnAdjustMode = false
                PlaySFX(AUDIO.sfx_click)
                return
            end
            -- 重置按钮 (重置当前选中组)
            if HitRect(settingsPage.adjResetBtnRect) then
                local ag = settingsPage.adjActiveGroup or "skill"
                if ag == "skill" then
                    settingsPage.adjOffsetX = 0
                    settingsPage.adjOffsetY = 0
                    settingsPage.adjScale = 1.0
                elseif ag == "rightBtn" then
                    settingsPage.adjRightBtnOffsetX = 0
                    settingsPage.adjRightBtnOffsetY = 0
                elseif ag == "infoPanel" then
                    settingsPage.adjInfoPanelOffsetX = 0
                    settingsPage.adjInfoPanelOffsetY = 0
                elseif ag == "hud" then
                    settingsPage.adjHudOffsetX = 0
                    settingsPage.adjHudOffsetY = 0
                end
                PlaySFX(AUDIO.sfx_click)
                return
            end
            -- 返回按钮
            if HitRect(settingsPage.adjBackBtnRect) then
                settingsPage.btnAdjustMode = false
                PlaySFX(AUDIO.sfx_click)
                return
            end
            -- 缩放滑条拖拽开始 (仅技能组)
            if settingsPage.adjScaleSliderRect and HitRect(settingsPage.adjScaleSliderRect) then
                settingsPage.adjDraggingScale = true
                local r = settingsPage.adjScaleSliderRect
                local ratio = math.max(0, math.min(1, (dx - r.x) / r.w))
                settingsPage.adjScale = 0.5 + ratio * 1.5  -- 0.5~2.0
                return
            end
            -- 拖拽当前选中组（点击战斗区域内任意位置开始拖拽）
            settingsPage.adjDragging = true
            settingsPage.adjDragStartX = dx
            settingsPage.adjDragStartY = dy
            return
        end

        -- 玩家面板点击 >> 进入玩家详情
        if HitRect(playerDetailBtnRect) then
            PushPhase("PLAYER_DETAIL")
            print("=== 进入玩家详情 ===")
            return
        end
        -- 广告获取虎符
        if HitRect(adRects.jade) then
            WatchAdForJade()
            return
        end

        -- ======== CDK 弹窗交互 (最高优先级) ========
        if cdkState.inputOpen then
            if HitRect(cdkState.redeemBtnRect) then
                TryRedeemCDK()
                PlaySFX(AUDIO.sfx_click)
                return
            end
            if HitRect(cdkState.clearBtnRect) then
                cdkState.inputText = ""
                PlaySFX(AUDIO.sfx_click)
                return
            end
            if HitRect(cdkState.closeBtnRect) then
                cdkState.inputOpen = false
                cdkState.inputText = ""
                input:SetScreenKeyboardVisible(false)
                PlaySFX(AUDIO.sfx_click)
                return
            end
            -- 粘贴按钮
            if cdkState.pasteBtnRect and HitRect(cdkState.pasteBtnRect) then
                local clipText = SafeGetClipboard()
                print("=== CDK粘贴: clipText=[" .. tostring(clipText) .. "] ===")
                if clipText and #clipText > 0 then
                    local cleaned = clipText:upper():gsub("[^A-Z0-9%-]", "")
                    if #cleaned > 20 then cleaned = cleaned:sub(1, 20) end
                    cdkState.inputText = cleaned
                    print("=== 粘贴兑换码: " .. cleaned .. " ===")
                else
                    input:SetScreenKeyboardVisible(true)
                    cdkState.resultText = "请在键盘中长按输入框粘贴"
                    cdkState.resultTimer = 3.0
                    cdkState.resultOk = false
                end
                PlaySFX(AUDIO.sfx_click)
                return
            end
            -- 点击弹窗区域内消费事件(原生键盘处理输入)
            return
        end

        -- ======== 新手指引弹窗交互 (最高优先级) ========
        if newbieGuidePopup.show then
            local cr = newbieGuidePopup.closeBtnRect
            if cr and HitRect(cr) then
                newbieGuidePopup.show = false
                newbieGuidePopup.isDragging = false
                PlaySFX(AUDIO.sfx_click)
                return
            end
            local pr = newbieGuidePopup.panelRect
            if pr and HitRect(pr) then
                newbieGuidePopup.isDragging = true
                newbieGuidePopup.lastTouchY = dy
                newbieGuidePopup.vel = 0
            else
                newbieGuidePopup.show = false
                newbieGuidePopup.isDragging = false
            end
            return
        end

        -- ======== 战力说明弹窗交互 ========
        if powerExplainPopup.show then
            local cr = powerExplainPopup.closeBtnRect
            if cr and HitRect(cr) then
                powerExplainPopup.show = false
                PlaySFX(AUDIO.sfx_click)
                return
            end
            -- 点击弹窗外关闭
            local pr = powerExplainPopup.panelRect
            if not (pr and HitRect(pr)) then
                powerExplainPopup.show = false
            end
            return
        end

        -- ======== 设置界面交互 (优先拦截) ========
        if settingsPage.isOpen then
            -- 保存按钮
            if HitRect(settingsPage.saveBtnRect) then
                SaveSettings()
                settingsPage.isOpen = false
                PlaySFX(AUDIO.sfx_click)
                return
            end
            -- 关闭按钮
            if HitRect(settingsPage.closeBtnRect) then
                settingsPage.isOpen = false
                settingsPage.draggingMusic = false
                settingsPage.draggingSfx = false
                PlaySFX(AUDIO.sfx_click)
                return
            end
            -- 自动行军开关
            if HitRect(settingsPage.autoMarchToggleRect) then
                gameSettings.defaultAutoMarch = not gameSettings.defaultAutoMarch
                PlaySFX(AUDIO.sfx_click)
                return
            end
            -- 字体切换: 4种字体
            for _, fkey in ipairs({"misans", "kuaile", "wenkai", "xingshu"}) do
                local rect = settingsPage["font_" .. fkey .. "_rect"]
                if rect and HitRect(rect) then
                    gameSettings.fontStyle = fkey
                    SaveGameProgress()
                    PlaySFX(AUDIO.sfx_click)
                    return
                end
            end
            -- 默认战场切换
            if settingsPage.battlefieldBtnRect and HitRect(settingsPage.battlefieldBtnRect) then
                local cur = gameSettings.defaultBattlefield or 1
                gameSettings.defaultBattlefield = (cur % 8) + 1
                PlaySFX(AUDIO.sfx_click)
                return
            end
            -- 调整位置按钮 >> 进入战斗场景调整模式
            if HitRect(settingsPage.adjustPosBtnRect) then
                settingsPage.isOpen = false
                settingsPage.btnAdjustMode = true
                settingsPage.adjActiveGroup = "skill"
                settingsPage.adjOffsetX = gameSettings.btnOffsetX
                settingsPage.adjOffsetY = gameSettings.btnOffsetY
                settingsPage.adjScale = gameSettings.btnScale or 1.0
                settingsPage.adjRightBtnOffsetX = gameSettings.rightBtnOffsetX or 0
                settingsPage.adjRightBtnOffsetY = gameSettings.rightBtnOffsetY or 0
                settingsPage.adjInfoPanelOffsetX = gameSettings.infoPanelOffsetX or 0
                settingsPage.adjInfoPanelOffsetY = gameSettings.infoPanelOffsetY or 0
                settingsPage.adjHudOffsetX = gameSettings.hudOffsetX or 0
                settingsPage.adjHudOffsetY = gameSettings.hudOffsetY or 0
                PlaySFX(AUDIO.sfx_click)
                return
            end

            -- UID 复制按钮
            if settingsPage.uidCopyBtnRect and HitRect(settingsPage.uidCopyBtnRect) then
                local uidStr = settingsPage.uidValue or ""
                if uidStr ~= "" and uidStr ~= "---" then
                    local sysOk = SafeSetClipboard(uidStr)
                    settingsPage.uidCopyTimer = 2.5
                    if sysOk then
                        AddFloatText(DESIGN_W / 2, DESIGN_H * 0.35, "UID已复制: " .. uidStr, 1.5, { 100, 220, 160 }, 16)
                    else
                        -- 系统剪贴板不可用，已存入游戏内剪贴板，同时提示截图
                        AddFloatText(DESIGN_W / 2, DESIGN_H * 0.30, "UID已复制(游戏内)", 2.5, { 100, 220, 160 }, 16)
                        AddFloatText(DESIGN_W / 2, DESIGN_H * 0.36, uidStr, 3.0, { 255, 220, 80 }, 22)
                        AddFloatText(DESIGN_W / 2, DESIGN_H * 0.42, "发邮件可直接粘贴 / 截图保存", 2.5, { 180, 180, 180 }, 14)
                    end
                end
                PlaySFX(AUDIO.sfx_click)
                return
            end

            -- 免广告卡 - 看广告按钮
            if settingsPage.adCardBtnRect and HitRect(settingsPage.adCardBtnRect) then
                PlaySFX(AUDIO.sfx_click)
                if not IsMobilePlatform() then
                    AddFloatText(DESIGN_W / 2, DESIGN_H * 0.35, "仅移动端可观看广告", 1.5, { 200, 150, 100 }, 14)
                    return
                end
                -- 看广告并计入免广告卡
                local function onAdCardSuccess()
                    local today = os.date("%Y-%m-%d")
                    if gameSettings.dailyAdDate ~= today then
                        gameSettings.dailyAdCount = 0
                        gameSettings.dailyAdDate = today
                    end
                    gameSettings.dailyAdCount = gameSettings.dailyAdCount + 1
                    print("[免广告卡] 看广告计入: " .. gameSettings.dailyAdCount .. "/3")
                    if gameSettings.dailyAdCount >= 3 then
                        AddFloatText(DESIGN_W / 2, DESIGN_H * 0.25,
                            "今日免广告卡已激活!", 2.0, { 100, 255, 200 }, 18)
                    else
                        AddFloatText(DESIGN_W / 2, DESIGN_H * 0.35,
                            "广告观看成功 (" .. gameSettings.dailyAdCount .. "/3)", 1.5, { 200, 200, 100 }, 14)
                    end
                    SaveSettings()
                end
                if sdk then
                    ShowAdSafe(SafeAdCallback(function(result)
                        if result.success then
                            onAdCardSuccess()
                        end
                    end))
                else
                    onAdCardSuccess()
                end
                return
            end

            -- CDK 兑换按钮
            if HitRect(settingsPage.cdkBtnRect) then
                cdkState.inputOpen = true
                cdkState.inputText = ""
                cdkState.resultTimer = 0
                input:SetScreenKeyboardVisible(true)
                PlaySFX(AUDIO.sfx_click)
                return
            end
            -- 音乐滑条拖拽开始
            if HitRect(settingsPage.musicSliderRect) then
                settingsPage.draggingMusic = true
                local r = settingsPage.musicSliderRect
                local ratio = math.max(0, math.min(1, (dx - r.x) / r.w))
                gameSettings.musicVolume = ratio
                if audioState.bgmSource then audioState.bgmSource.gain = ratio end
                return
            end
            -- 音效滑条拖拽开始
            if HitRect(settingsPage.sfxSliderRect) then
                settingsPage.draggingSfx = true
                local r = settingsPage.sfxSliderRect
                local ratio = math.max(0, math.min(1, (dx - r.x) / r.w))
                gameSettings.sfxVolume = ratio
                return
            end
            -- 点击遮罩区域 >> 消费事件不穿透
            return
        end

        if HitRect(settingsPage.btnRect) then
            settingsPage.isOpen = true
            PlaySFX(AUDIO.sfx_click)
            return
        end
        -- 新手指引按钮
        if menuBtnRects.newbieGuide and HitRect(menuBtnRects.newbieGuide) then
            newbieGuidePopup.show = true
            newbieGuidePopup.scrollY = 0
            newbieGuidePopup.vel = 0
            PlaySFX(AUDIO.sfx_click)
            return
        end
        -- 战力说明"?"按钮 (在玩家面板点击之前拦截)
        if menuBtnRects.powerHelp and HitRect(menuBtnRects.powerHelp) then
            powerExplainPopup.show = true
            PlaySFX(AUDIO.sfx_click)
            return
        end
        -- 下载面板交互
        if downloadUI.panelOpen and downloadUI.panelRect and HitRect(downloadUI.panelRect) then
            -- 点击面板内部 >> 消费事件不穿透
            return
        end
        if downloadUI.btnRect and HitRect(downloadUI.btnRect) then
            downloadUI.panelOpen = not downloadUI.panelOpen
            PlaySFX(AUDIO.sfx_click)
            return
        end
        -- 点击其他区域时收起面板
        if downloadUI.panelOpen then
            downloadUI.panelOpen = false
        end

        -- ======== 左侧栏拖拽/点击处理 ========
        if leftSidebarScroll.areaRect then
            local ar = leftSidebarScroll.areaRect
            if dx >= ar.x and dx <= ar.x + ar.w and dy >= ar.y and dy <= ar.y + ar.h then
                local maxScroll = math.max(0, leftSidebarScroll.contentH - leftSidebarScroll.viewH)
                if maxScroll > 0 then
                    -- 有滚动需求 → 记录拖拽起点，EndPress 判断是点击还是拖拽
                    leftSidebarScroll.isDragging = true
                    leftSidebarScroll.dragStartY = dy
                    leftSidebarScroll.dragLastY = dy
                    leftSidebarScroll.vel = 0
                    return  -- 阻止穿透到下方按钮点击
                else
                    -- 无滚动 → 直接处理按钮点击
                    HandleSidebarButtonClick(dx, dy)
                    return
                end
            end
        end

        -- ======== 世界聊天点击处理 ========
        if worldChatUI.expanded then
            -- 展开模式: 优先拦截所有点击
            if menuBtnRects.worldChatClose and HitRect(menuBtnRects.worldChatClose) then
                worldChatUI.expanded = false
                worldChatUI.inputActive = false
                worldChatUI.chatInput = ""
                input:SetScreenKeyboardVisible(false)
                PlaySFX(AUDIO.sfx_click); return
            end
            -- 添加好友弹出按钮
            if menuBtnRects.worldChatAddFriend and HitRect(menuBtnRects.worldChatAddFriend) then
                local targetUid = menuBtnRects.worldChatAddFriend.uid
                local targetName = menuBtnRects.worldChatAddFriend.name or "?"
                local myUid = rawget(_G, "clientCloud") and clientCloud.userId or 0
                if targetUid == myUid then
                    ShowToast("不能添加自己为好友")
                else
                    CloudManager.SendFriendRequest(targetUid, "")
                    playerInfo.totalFriendReqs = (playerInfo.totalFriendReqs or 0) + 1
                    ShowToast("已向「" .. targetName .. "」发送好友请求")
                end
                worldChatUI.namePopup = nil
                PlaySFX(AUDIO.sfx_click); return
            end
            if menuBtnRects.worldChatSend and HitRect(menuBtnRects.worldChatSend) then
                if worldChatUI.chatInput and #worldChatUI.chatInput > 0 then
                    local filteredText = FilterBannedWords(worldChatUI.chatInput)
                    local senderName = CloudManager._myTapNickname or factionUI.myNickname or playerInfo.name or "无名"
                    CloudManager.SendWorldChat(filteredText, senderName)
                    worldChatUI.chatInput = ""
                    worldChatUI.inputActive = false
                    input:SetScreenKeyboardVisible(false)
                end
                worldChatUI.namePopup = nil
                PlaySFX(AUDIO.sfx_click); return
            end
            if menuBtnRects.worldChatInput and HitRect(menuBtnRects.worldChatInput) then
                worldChatUI.inputActive = true
                worldChatUI.namePopup = nil
                input:SetScreenKeyboardVisible(true)
                PlaySFX(AUDIO.sfx_click); return
            end
            -- 点击弹窗区域内不关闭
            if menuBtnRects.worldChatPopupArea and HitRect(menuBtnRects.worldChatPopupArea) then
                PlaySFX(AUDIO.sfx_click); return
            end
            -- 点击头像弹出玩家信息
            if worldChatUI._avatarRects then
                for _, nr in ipairs(worldChatUI._avatarRects) do
                    if HitRect(nr) then
                        if worldChatUI.namePopup and worldChatUI.namePopup.uid == nr.uid then
                            worldChatUI.namePopup = nil  -- 再次点击同一头像关闭
                        else
                            worldChatUI.namePopup = { uid = nr.uid, name = nr.name, x = nr.x, y = nr.y, av = nr.av }
                        end
                        PlaySFX(AUDIO.sfx_click); return
                    end
                end
            end
            -- 点击窗口外部关闭
            worldChatUI.expanded = false
            worldChatUI.inputActive = false
            worldChatUI.chatInput = ""
            worldChatUI.namePopup = nil
            input:SetScreenKeyboardVisible(false)
            PlaySFX(AUDIO.sfx_click); return
        end
        if menuBtnRects.worldChatMini and HitRect(menuBtnRects.worldChatMini) then
            worldChatUI.expanded = true
            worldChatUI.lastMsgCount = 0  -- 触发自动滚到底
            CloudManager.PollWorldChat()  -- 立即拉取
            PlaySFX(AUDIO.sfx_click); return
        end

        if HitRect(menuBtnRects.battle) then
            -- 乱世征途 >> 关卡选择（需要战斗模块）
            if not moduleState.battle.ready then
                local pct = math.floor(moduleState.battle.progress * 100)
                ShowToast("战斗资源下载中(" .. pct .. "%)，请稍候")
                PlaySFX(AUDIO.sfx_click)
                return
            end
            PlaySFX(AUDIO.sfx_click)
            PushPhase("STAGE_SELECT")
            print("=== 进入关卡选择 ===")
        elseif HitRect(menuBtnRects.gacha) then
            -- 召唤武灵（需要武灵模块）
            if not moduleState.heroes.ready then
                local pct = math.floor(moduleState.heroes.progress * 100)
                ShowToast("武灵资源下载中(" .. pct .. "%)，请稍候")
                PlaySFX(AUDIO.sfx_click)
                return
            end
            PushPhase("GACHA")
            gachaState.showResults = false
            gachaState.pulling = false
            gachaState.animTimer = 0
            gachaState.results = {}
            print("=== 进入召唤武灵 ===")
        elseif HitRect(menuBtnRects.codex) then
            -- 武灵录（需要武灵模块）
            if not moduleState.heroes.ready then
                local pct = math.floor(moduleState.heroes.progress * 100)
                ShowToast("武灵资源下载中(" .. pct .. "%)，请稍候")
                PlaySFX(AUDIO.sfx_click)
                return
            end
            PushPhase("CODEX")
            codexScroll.y = 0
            codexScroll.vel = 0
            phaseChangeCooldown = 0.3
            print("=== 进入武灵录 ===")
        elseif HitRect(menuBtnRects.equip) then
            -- 兵甲（需要兵甲模块）
            if not moduleState.equipment.ready then
                local pct = math.floor(moduleState.equipment.progress * 100)
                ShowToast("兵甲资源下载中(" .. pct .. "%)，请稍候")
                PlaySFX(AUDIO.sfx_click)
                return
            end
            PushPhase("EQUIP")
            -- 自动选中有红点的槽位（帮助玩家找到新装备）
            local autoSlot = 1
            for si = 1, 7 do
                if HasEquipSlotRedDot(si) then autoSlot = si; break end
            end
            equipScreenState.selectedSlot = autoSlot
            equipScreenState.scrollY = 0
            -- 传递 NanoVG 上下文和精灵图句柄给覆盖层
            EquipUI._vg = vg
            EquipUI._equipSheet = IMG.equipmentSheet
            EquipUI._sheetCols = EQUIP_SHEET_COLS
            EquipUI._sheetRows = EQUIP_SHEET_ROWS
            -- 显示NanoVG网格仓库
            EquipUI.Show()
            -- 不再立即消除所有红点，改为点击槽位时逐个消除
            print("=== 进入兵甲 ===")
        elseif HitRect(menuBtnRects.equipCodex) then
            -- 兵甲图录（需要兵甲模块）
            if not moduleState.equipment.ready then
                local pct = math.floor(moduleState.equipment.progress * 100)
                ShowToast("兵甲资源下载中(" .. pct .. "%)，请稍候")
                PlaySFX(AUDIO.sfx_click)
                return
            end
            PushPhase("EQUIP_CODEX")
            print("=== 进入兵甲图录 ===")
        elseif HitRect(menuBtnRects.skillCodex) then
            -- 武技（需要武技模块）
            if not moduleState.skills.ready then
                local pct = math.floor(moduleState.skills.progress * 100)
