            CloudManager.PollInbox()
            PlaySFX(AUDIO.sfx_click)
            print("=== 进入邮件 ===")
        elseif menuBtnRects.faction and HitRect(menuBtnRects.faction) then
            -- 阵营系统
            PushPhase("FACTION")
            phaseChangeCooldown = 0.3
            PlaySFX(AUDIO.sfx_click)
            print("=== 进入阵营 ===")
        elseif menuBtnRects.friends and HitRect(menuBtnRects.friends) then
