--- 左侧栏按钮点击处理（提取为独立函数，供 BeginPress 和 EndPress 共用）
--- @param dx number 设计坐标 X
--- @param dy number 设计坐标 Y
--- @return boolean handled
function HandleSidebarButtonClick(dx, dy)
    local function HitR(r)
        return r and dx >= r.x and dx <= r.x + r.w and dy >= r.y and dy <= r.y + r.h
    end

    if HitR(menuBtnRects.codex) then
        if not moduleState.heroes.ready then
            ShowToast("武灵资源下载中(" .. math.floor(moduleState.heroes.progress * 100) .. "%)，请稍候")
            PlaySFX(AUDIO.sfx_click); return true
        end
        PushPhase("CODEX"); codexScroll.y = 0; codexScroll.vel = 0
        phaseChangeCooldown = 0.3; return true
    elseif HitR(menuBtnRects.equip) then
        if not moduleState.equipment.ready then
            ShowToast("兵甲资源下载中(" .. math.floor(moduleState.equipment.progress * 100) .. "%)，请稍候")
            PlaySFX(AUDIO.sfx_click); return true
        end
        PushPhase("EQUIP")
        local autoSlot = 1
        for si = 1, 7 do
            if HasEquipSlotRedDot(si) then autoSlot = si; break end
        end
        equipScreenState.selectedSlot = autoSlot; equipScreenState.scrollY = 0
        EquipUI._vg = vg; EquipUI._equipSheet = IMG.equipmentSheet
        EquipUI._sheetCols = EQUIP_SHEET_COLS; EquipUI._sheetRows = EQUIP_SHEET_ROWS
        EquipUI.Show(); return true
    elseif HitR(menuBtnRects.equipCodex) then
        if not moduleState.equipment.ready then
            ShowToast("兵甲资源下载中(" .. math.floor(moduleState.equipment.progress * 100) .. "%)，请稍候")
            PlaySFX(AUDIO.sfx_click); return true
        end
        PushPhase("EQUIP_CODEX"); return true
    elseif HitR(menuBtnRects.skillCodex) then
        if not moduleState.skills.ready then
            ShowToast("武技资源下载中(" .. math.floor(moduleState.skills.progress * 100) .. "%)，请稍候")
            PlaySFX(AUDIO.sfx_click); return true
        end
        PushPhase("SKILL_CODEX"); skillCodexState.scrollY = 0; skillCodexState.scrollVel = 0
        phaseChangeCooldown = 0.3; DismissSkillRedDots(); return true
    elseif HitR(menuBtnRects.welfare) then
        PushPhase("WELFARE"); phaseChangeCooldown = 0.3
        welfareState.contribLoaded = false; welfareState.contribLoading = false
        welfareState.powerLoaded = false; welfareState.powerLoading = false
        welfareState.contribScroll = { offset = 0, vel = 0, dragStartY = nil, dragLastY = nil, isDragging = false }
        welfareState.powerScroll = { offset = 0, vel = 0, dragStartY = nil, dragLastY = nil, isDragging = false }
        welfareState.scroll = { offset = 0, vel = 0, dragStartY = nil, dragLastY = nil, isDragging = false }
        LoadContribRank(); ReportPowerScore(); LoadPowerRank(); return true
    elseif menuBtnRects.progress and HitR(menuBtnRects.progress) then
        CheckDailyReset(); CheckWeeklyReset()
        progressUIState.tab = 1; progressUIState.scrollY = 0
        PushPhase("PROGRESS"); phaseChangeCooldown = 0.3; PlaySFX(AUDIO.sfx_click); return true
    elseif menuBtnRects.mailBox and HitR(menuBtnRects.mailBox) then
        PushPhase("MAIL_BOX"); phaseChangeCooldown = 0.3
        welfareState.mail.scroll = { offset = 0, vel = 0, dragStartY = nil, dragLastY = nil, isDragging = false }
        welfareState.mail.btnRects = {}; welfareState.mail.cloudBtnRects = {}
        welfareState.mail.confirmPopup = nil
        welfareState.mail.composing = false; welfareState.mail.composeData = nil
        welfareState.mail.adminPanel = false
        CloudManager.PollInbox()
        PlaySFX(AUDIO.sfx_click); return true
    elseif menuBtnRects.faction and HitR(menuBtnRects.faction) then
        -- 重置阵营UI状态
        local info = CloudManager.GetFactionInfo()
        local hasFaction = info and info.id and info.id > 0
        factionUI.tab = hasFaction and "info" or "list"
        factionUI.loaded = false; factionUI.loading = false
        factionUI.applyLoaded = false; factionUI.applyLoading = false
        factionUI.leaderNickLoaded = false; factionUI.leaderNickname = nil
        factionUI.memberValidated = false  -- 重新验证成员
        factionUI.chatPolled = false  -- 下次进聊天tab重新拉取
        factionUI.members = {}; factionUI.applications = {}; factionUI.factions = {}
        factionUI.scroll = { offset = 0, vel = 0, isDragging = false, dragStartY = nil, dragLastY = nil }
        factionUI.inputTarget = nil; factionUI.confirmPopup = nil
        factionUI.createName = ""; factionUI.createDesc = ""
        PushPhase("FACTION"); phaseChangeCooldown = 0.3; PlaySFX(AUDIO.sfx_click); return true
    elseif menuBtnRects.friends and HitR(menuBtnRects.friends) then
        -- 重置好友UI状态
        friendsUI.tab = "list"
        friendsUI.loaded = false; friendsUI.loading = false
        friendsUI.reqLoaded = false; friendsUI.reqLoading = false
        friendsUI.recLoaded = false; friendsUI.recLoading = false
        friendsUI.friends = {}; friendsUI.requests = {}; friendsUI.recommended = {}
        friendsUI.scroll = { offset = 0, vel = 0, isDragging = false, dragStartY = nil, dragLastY = nil }
        friendsUI.confirmPopup = nil; friendsUI.inputActive = false
        friendsUI.searchId = ""; friendsUI.searchResult = nil; friendsUI.searchNotFound = false
        PushPhase("FRIENDS"); phaseChangeCooldown = 0.3; PlaySFX(AUDIO.sfx_click); return true
    elseif menuBtnRects.formation and HitR(menuBtnRects.formation) then
        -- 编队: 进入时先自动编队
        ValidateFormation()
        local ownedCount = AutoFillFormation()
        formationUI = formationUI or {}
        formationUI.scrollY = 0; formationUI.scrollVel = 0
        formationUI.isDragging = false; formationUI.dragStartY = nil; formationUI.dragLastY = nil
        formationUI.tab = 0  -- 0=全部
        formationUI.cardRects = {}; formationUI.slotRects = {}
        formationUI.confirmPopup = nil
        formationUI.ownedCount = ownedCount
        if ownedCount < 10 then
            AddFloatText(DESIGN_W / 2, DESIGN_H * 0.35, "武灵不足10人, 已全部自动上阵", 2.0, { 255, 220, 100 }, 14)
        else
            AddFloatText(DESIGN_W / 2, DESIGN_H * 0.35, "已自动编队, 可手动调整上阵武灵", 2.0, { 120, 220, 100 }, 14)
        end
        PushPhase("FORMATION"); phaseChangeCooldown = 0.3; PlaySFX(AUDIO.sfx_click); return true
    elseif menuBtnRects.trade and HitR(menuBtnRects.trade) then
        -- 交易行
        PushPhase("TRADE"); phaseChangeCooldown = 0.3
        tradeState.tab = "market"
        tradeState.scroll = { offset = 0, vel = 0, isDragging = false, dragStartY = nil, dragLastY = nil }
        tradeState.selectedItem = nil; tradeState.confirmPopup = nil; tradeState.btnRects = {}
        TradeManager.Init(); TradeManager.ResetCheckSalesCD(); TradeManager.RefreshMarket()
        PlaySFX(AUDIO.sfx_click); return true
    end
    return false
end

--- 各页面滚动/拖拽释放逻辑（从 EndPress 中提取以避免 200 upvalue 限制）
--- @return boolean handled 是否已处理（调用方应 return）
function HandleEndPressDragRelease(sx, sy, touchId)
    -- 左侧栏拖拽释放
    if leftSidebarScroll.isDragging then
        leftSidebarScroll.isDragging = false
        local _, dy = ScreenToDesign(sx, sy)
        local dragDist = math.abs(dy - (leftSidebarScroll.dragStartY or dy))
        if dragDist >= 10 then
            -- 拖拽距离足够 → 是滚动操作，不触发按钮点击
            leftSidebarScroll.dragStartY = nil
            leftSidebarScroll.dragLastY = nil
            return true
        end
        -- 拖拽距离不足 → 当作点击
        leftSidebarScroll.vel = 0
        leftSidebarScroll.dragStartY = nil
        leftSidebarScroll.dragLastY = nil
        local dx2, dy2 = ScreenToDesign(sx, sy)
        HandleSidebarButtonClick(dx2, dy2)
        return true
    end

    -- 英雄选择弹窗滚动释放
    if sealMgrState.showHeroPicker and heroPickerScroll.isDragging then
        heroPickerScroll.isDragging = false
        local dx, dy = ScreenToDesign(sx, sy)
        local dragDist = math.abs(dy - (heroPickerScroll.dragStartY or dy))
        if dragDist < 10 then
            heroPickerScroll.vel = 0
            -- 短按 = 点击，选中英雄卡牌
            for cardIdx, rect in pairs(sealMgrHeroRects) do
                if dx >= rect.x and dx <= rect.x + rect.w and dy >= rect.y and dy <= rect.y + rect.h then
                    sealMgrState.selectedHero = cardIdx
                    sealMgrState.selectedSlot = nil
                    sealMgrState.showLevelUp = false
                    sealMgrState.showHeroPicker = false
                    heroPickerScroll = { y = 0, vel = 0, dragStartY = nil, dragLastY = nil, isDragging = false, contentH = 0, viewH = 0 }
                    PlaySFX(AUDIO.sfx_click)
                    break
                end
            end
        end
        return true
    end

    -- 兵符替换弹窗滚动释放
    if sealReplaceState.show and sealReplaceState.scroll.isDragging then
        sealReplaceState.scroll.isDragging = false
        return true
    end

    -- 统一规则弹窗滚动释放
    if phaseRulePopup.isDragging then
        phaseRulePopup.isDragging = false
        return true
    end

    -- 战斗规则弹窗滚动释放
    if battleRulesState.isDragging then
        battleRulesState.isDragging = false
        return true
    end

    -- 新手指引弹窗滚动释放
    if newbieGuidePopup.isDragging then
        newbieGuidePopup.isDragging = false
        return true
    end

    -- ======== 按钮位置调整模式拖拽释放 ========
    if settingsPage.btnAdjustMode then
        settingsPage.adjDragging = false
        settingsPage.adjDraggingScale = false
        return true
    end

    -- ======== 设置界面拖拽释放 ========
    if settingsPage.isOpen and gameState.phase == "MENU" then
        settingsPage.draggingMusic = false
        settingsPage.draggingSfx = false
        return true
    end

    -- 策略选项条释放
    if strategyWheelState.pressing and touchId == strategyWheelState.touchId then
        strategyWheelState.pressing = false
        if strategyWheelState.show then
            if strategyWheelState.selected > 0 and strategyWheelState.selected <= #MARCH_STRATEGIES then
                -- 拖拽选中了，直接应用
                local st = MARCH_STRATEGIES[strategyWheelState.selected]
                gameState.autoMarchStrategy = st.id
                gameState.autoMarch = true
                AddFloatText(DESIGN_W / 2, DESIGN_H * 0.45, "策略: " .. st.name, 1.2, st.color, 16)
                PlaySFX(AUDIO.sfx_march)
                strategyWheelState.show = false
                strategyWheelState.selected = 0
            end
            -- 未选中则保持面板显示，等待点击选择
            return true
        else
            -- 短按: toggle自动行军
            gameState.autoMarch = not gameState.autoMarch
            if gameState.autoMarch then PlaySFX(AUDIO.sfx_march) end
            local txt = gameState.autoMarch and "自动行军 开启" or "自动行军 关闭"
            local clr = gameState.autoMarch and { 120, 255, 160 } or { 200, 180, 160 }
            AddFloatText(DESIGN_W / 2, DESIGN_H * 0.45, txt, 1.0, clr, 16)
            return true
        end
    end

    -- (已移除武技长按释放逻辑, 按下即拖拽瞄准)

    -- 武技技能瞄准释放
    if skillTargeting.active and touchId == skillTargeting.touchId then
        skillTargeting.active = false
        local tdx, tdy = ScreenToDesign(sx, sy)
        tdx = math.max(BATTLE_ZONE.left, math.min(BATTLE_ZONE.right, tdx))
        tdy = math.max(BATTLE_ZONE.top, math.min(BATTLE_ZONE.bottom, tdy))
        if tdy >= BATTLE_ZONE.top - 10 and tdy <= BATTLE_ZONE.bottom + 10
           and tdx >= BATTLE_ZONE.left - 10 and tdx <= BATTLE_ZONE.right + 10 then
            CastSkill(skillTargeting.skillIdx, tdx, tdy)
        else
            AddFloatText(DESIGN_W / 2, DESIGN_H * 0.45, "释放取消", 0.8, { 180, 180, 180 }, 12)
        end
        return true
    end

    -- 武技滚动结束
    if gameState.phase == "SKILL_CODEX" and skillCodexState.isDragging then
        HandleSkillCodexEndPress(sx, sy)
        return true
    end

    -- 打桩选将滚动结束
    if gameState.phase == "DUMMY_SELECT" and dummyState.isDragging then
        dummyState.isDragging = false
        local dx, dy = ScreenToDesign(sx, sy)
        local dragDist = math.abs(dy - (dummyState.dragStartY or dy))
        if dragDist < 10 then
            -- 视为点击，检查卡牌选择
            for ci, rect in pairs(dummyState.cardRects) do
                if dx >= rect.x and dx <= rect.x + rect.w and
                   dy >= rect.y and dy <= rect.y + rect.h then
                    local foundIdx = nil
                    for si, sel in ipairs(dummyState.selected) do
                        if sel == ci then foundIdx = si; break end
                    end
                    if foundIdx then
                        table.remove(dummyState.selected, foundIdx)
                        PlaySFX(AUDIO.sfx_click)
                    else
                        if #dummyState.selected < 4 then
                            table.insert(dummyState.selected, ci)
                            PlaySFX(AUDIO.sfx_click)
                        else
                            AddFloatText(DESIGN_W / 2, DESIGN_H * 0.4, "最多选择4名武灵", 1.0, { 255, 200, 80 }, 16)
                        end
                    end
                    break
                end
            end
        end
        dummyState.dragStartY = nil
        dummyState.dragLastY = nil
        return true
    end

    -- 天命赐福贡献榜滚动释放
    if gameState.phase == "WELFARE" and welfareState.contribScroll.isDragging then
        welfareState.contribScroll.isDragging = false
        welfareState.contribScroll.dragStartY = nil
        welfareState.contribScroll.dragLastY = nil
        return true
    end

    -- 战令通行证横向拖拽释放
    if gameState.phase == "BATTLE_PASS" and battlePassUIState.isDraggingReward then
        battlePassUIState.isDraggingReward = false
        return true
    end

    -- 战令通行证纵向拖拽释放
    if gameState.phase == "BATTLE_PASS" and battlePassUIState.isDragging then
        battlePassUIState.isDragging = false
        battlePassUIState.dragStartY = nil
        battlePassUIState.dragLastY = nil
        return true
    end

    -- 编队界面滚动释放 + 卡牌点击
    if gameState.phase == "FORMATION" and formationUI and formationUI.isDragging then
        formationUI.isDragging = false
        local _, dy = ScreenToDesign(sx, sy)
        local dragDist = math.abs(dy - (formationUI.dragStartY or dy))
        formationUI.dragStartY = nil; formationUI.dragLastY = nil
        if dragDist < 10 then
            -- 拖拽距离不足 → 当作点击 (添加/移除卡牌)
            formationUI.scrollVel = 0
            local dx2, dy2 = ScreenToDesign(sx, sy)
            local FORMATION_MAX = 10
            local ownedCount = formationUI.ownedCount or GetOwnedHeroCount()
            local canManualEdit = ownedCount >= 10
            local targetCount = math.min(FORMATION_MAX, ownedCount)
            if formationUI.cardRects then
                for _, cr in ipairs(formationUI.cardRects) do
                    if cr and dx2 >= cr.x and dx2 <= cr.x + cr.w and dy2 >= cr.y and dy2 <= cr.y + cr.h then
                        -- 不满10人时禁止手动调整
                        if not canManualEdit then
                            AddFloatText(DESIGN_W / 2, DESIGN_H * 0.35, "武灵不足10人, 无法调整编队", 1.5, { 255, 180, 80 }, 14)
                            PlaySFX(AUDIO.sfx_click)
                            break
                        end
                        local cardIdx = cr.cardIdx
                        -- 检查是否已在编队
                        local alreadyIn = false
                        for _, idx in ipairs(gameSettings.formation) do
                            if idx == cardIdx then alreadyIn = true; break end
                        end
                        if alreadyIn then
                            -- 已在编队 → 移除
                            for fi = #gameSettings.formation, 1, -1 do
                                if gameSettings.formation[fi] == cardIdx then
                                    table.remove(gameSettings.formation, fi); break
                                end
                            end
                            SaveSettings()
                            PlaySFX(AUDIO.sfx_click)
                        elseif #gameSettings.formation < targetCount then
                            -- 未满 → 添加
                            table.insert(gameSettings.formation, cardIdx)
                            SaveSettings()
                            PlaySFX(AUDIO.sfx_click)
                        else
                            AddFloatText(DESIGN_W / 2, DESIGN_H * 0.35, "编队已满(" .. targetCount .. "人)", 1.5, { 220, 160, 80 }, 14)
                        end
                        break
                    end
                end
            end
        end
        return true
    end

    -- 阵营成员列表滚动释放
    if gameState.phase == "FACTION" and factionUI.scroll.isDragging then
        factionUI.scroll.isDragging = false
        factionUI.scroll.dragStartY = nil
        factionUI.scroll.dragLastY = nil
        return true
    end

    -- 交易行滚动释放
    if gameState.phase == "TRADE" and tradeState.scroll.isDragging then
        tradeState.scroll.isDragging = false
        tradeState.scroll.dragStartY = nil
        tradeState.scroll.dragLastY = nil
        return true
    end

    -- 邮件列表滚动释放
    if gameState.phase == "MAIL_BOX" and welfareState.mail.scroll and welfareState.mail.scroll.isDragging then
        welfareState.mail.scroll.isDragging = false
        welfareState.mail.scroll.dragStartY = nil
        welfareState.mail.scroll.dragLastY = nil
        return true
    end

    -- 天命赐福下方内容滚动释放
    if gameState.phase == "WELFARE" and welfareState.scroll.isDragging then
        welfareState.scroll.isDragging = false
        welfareState.scroll.dragStartY = nil
        welfareState.scroll.dragLastY = nil
        return true
    end

    -- 每日任务/成就滚动释放
    if gameState.phase == "PROGRESS" and progressUIState.isDragging then
        progressUIState.isDragging = false
        progressUIState.dragStartY = nil
        progressUIState.dragLastY = nil
        return true
    end

    -- 编辑器石台释放
    if gameState.phase == "DEV_EDITOR" and editorState.slotPressKey then
        local key = editorState.slotPressKey
        if not editorState.slotDragging then
            if editorState.slotWasSelected then
                editorState.selectedSlots[key] = nil
            end
        end
        editorState.slotDragging = false
        editorState.slotPressKey = nil
        editorState.slotWasSelected = false
        editorState.slotPressStartX = nil
        editorState.slotPressStartY = nil
        editorState.dragStartBgX = nil
        editorState.dragStartBgY = nil
        editorState.dragOrigPositions = nil
        return true
    end

    -- 编辑器滚动释放
    if gameState.phase == "DEV_EDITOR" and editorState.isDragging then
        editorState.isDragging = false
        editorState.dragStartY = nil
        editorState.dragLastY = nil
        return true
    end

    -- 残片仓库松手
    if gameState.phase == "GACHA" and gachaState.showFragShop and fragShopScroll.isDragging then
        HandleFragShopEndPress(sx, sy)
        return true
    end

    -- 战力排行榜滚动释放
    if gameState.phase == "POWER_RANK" then
        local curScroll
        if welfareState.rankTab == "realm" then curScroll = welfareState.realmScroll
        elseif welfareState.rankTab == "dummy" then curScroll = welfareState.dummyScroll
        else curScroll = welfareState.powerScroll end
        if curScroll.isDragging then
            curScroll.isDragging = false
            curScroll.dragStartY = nil
            curScroll.dragLastY = nil
            return true
        end
    end

    -- 贡献榜详情页滚动释放
    if gameState.phase == "CONTRIB_RANK" and welfareState.contribDetailScroll.isDragging then
        welfareState.contribDetailScroll.isDragging = false
        welfareState.contribDetailScroll.dragStartY = nil
        welfareState.contribDetailScroll.dragLastY = nil
        return true
    end

    -- 新版EquipUI触摸结束委托
    if gameState.phase == "EQUIP" and EquipUI.isVisible then
        local dx, dy = ScreenToDesign(sx, sy)
        EquipUI.HandleTouchEnd(dx, dy)
        return true
    end

    -- 兵甲列表滚动释放（旧版，只响应按钮点击，不响应整行）
    if gameState.phase == "EQUIP" and equipScreenState.isDragging then
        equipScreenState.isDragging = false
        local dx, dy = ScreenToDesign(sx, sy)
        local dragDist = math.abs(dy - (equipScreenState.dragStartY or dy))
        if dragDist < 10 then
            equipScreenState.scrollVel = 0
            -- 短距离松手 = 点击，只检测按钮区域
            local function HitBtn(r)
                return r and dx >= r.x and dx <= r.x + r.w and dy >= r.y and dy <= r.y + r.h
            end
            local slotIdx = equipScreenState.selectedSlot
            -- 选中模式: 点击列表项切换勾选
            if equipScreenState.selectMode then
                for _, rect in pairs(equipPieceRects) do
                    local info = rect.info
                    if not info then goto skipSel end
                    if HitBtn(rect) then
                        -- 已装备的不可选
                        local equippedUid = playerEquipment.equipped[info.slotIdx]
                        if equippedUid ~= info.uid then
                            if equipScreenState.selectedUids[info.uid] then
                                equipScreenState.selectedUids[info.uid] = nil
                            else
                                equipScreenState.selectedUids[info.uid] = true
                            end
                            PlaySFX(AUDIO.sfx_click)
                        end
                        break
                    end
                    ::skipSel::
                end
            else
            for _, rect in pairs(equipPieceRects) do
                local info = rect.info
                if not info then goto skipRect end
                -- 分解按钮
                if HitBtn(rect.decompRect) then
                    local itemObj = FindOwnedByUid(info.uid)
                    if itemObj then
                        local gain, enhRefund = CalcDecomposeGain(itemObj.tier, itemObj.enhanceLv)
                        equipScreenState.decompConfirm = {
                            uid = itemObj.uid,
                            setIdx = itemObj.setIdx, slotIdx = itemObj.slotIdx,
                            tier = itemObj.tier, gain = gain, enhRefund = enhRefund, enhLv = itemObj.enhanceLv,
                        }
                    end
                    PlaySFX(AUDIO.sfx_click)
                    break
                end
                -- 装备按钮
                if HitBtn(rect.equipBtnRect) then
                    local itemObj = FindOwnedByUid(info.uid)
                    if itemObj then
                        playerEquipment.equipped[slotIdx] = itemObj.uid
                        local pieceName = EQUIPMENT_SETS[itemObj.setIdx].pieces[slotIdx].name
                        local tierName = EQUIP_TIERS[itemObj.tier or 1].name
                        local qLabel = GetQualityLabel(itemObj.quality)
                        print("=== 装备: 槽位" .. slotIdx .. " " .. tierName .. " " .. pieceName .. " " .. qLabel .. " ===")
                        AddFloatText(DESIGN_W / 2, DESIGN_H * 0.5, "装备 " .. tierName .. " " .. pieceName, 1.0, { 100, 255, 180 }, 18)
                        playerInfo.totalEquips = playerInfo.totalEquips + 1
                        TrackDailyTask("equip1", 1)
                        SaveGameProgress()
                    end
                    break
                end
                -- 卸下按钮
                if HitBtn(rect.unequipRect) then
                    playerEquipment.equipped[slotIdx] = nil
                    print("=== 卸下装备: 槽位" .. slotIdx .. " ===")
                    AddFloatText(DESIGN_W / 2, DESIGN_H * 0.5, "已卸下装备", 1.0, { 200, 200, 200 }, 18)
                    SaveGameProgress()
                    break
                end
                ::skipRect::
            end
            end -- end selectMode else
        end
        equipScreenState.dragStartY = nil
        equipScreenState.dragLastY = nil
        return true
    end

    -- 装备图鉴滚动释放
    if gameState.phase == "EQUIP_CODEX" and equipCodexState.isDragging then
        HandleEquipCodexEndPress(sx, sy)
        return true
    end

    -- 兵符管理滚动释放（选中分解列表）
    if gameState.phase == "SEAL_MGR" and sealMgrScroll.isDragging then
        sealMgrScroll.isDragging = false
        local dx, dy = ScreenToDesign(sx, sy)
        local dragDist = math.abs(dy - (sealMgrScroll.dragStartY or dy))
        if dragDist < 10 then
            sealMgrScroll.vel = 0
            -- 短按 = 点击，切换列表项选中
            if sealInvFilterState.selectMode and sealInvFilterBtnRects.selectItems then
                for _, rect in pairs(sealInvFilterBtnRects.selectItems) do
                    if dx >= rect.x and dx <= rect.x + rect.w and dy >= rect.y and dy <= rect.y + rect.h then
                        if sealInvFilterState.selectedIds[rect.invIndex] then
                            sealInvFilterState.selectedIds[rect.invIndex] = nil
                        else
                            sealInvFilterState.selectedIds[rect.invIndex] = true
                        end
                        PlaySFX(AUDIO.sfx_click)
                        break
                    end
                end
            end
        end
        return true
    end

    -- 武灵录滚动释放
    if gameState.phase == "CODEX" and codexScroll.isDragging then
        HandleCodexEndPress(sx, sy)
        return true
    end

    return false
end

_lastEndFrame = -1
function EndPress(sx, sy, touchId)
    if gameState.isBanned then return end  -- 封禁玩家拦截一切操作
    if CloudManager.IsCloudLoading() then return end  -- 云数据加载中拦截操作
    local curFrame = time:GetFrameNumber()
    if curFrame == _lastEndFrame then return end
    _lastEndFrame = curFrame

    if HandleEndPressDragRelease(sx, sy, touchId) then return end

    if longPressState.active then
        longPressState.active = false
        longPressState.pressing = false
        longPressState.card = nil
        return
    end

    if longPressState.pressing then
        if longPressState.card then
            infoPopupState.show = true
            infoPopupState.card = longPressState.card
            infoPopupState.slotIdx = longPressState.slotIdx
            infoPopupState.isSlot = longPressState.isSlot
            infoPopupState.isEnemy = longPressState.isEnemy
            laneButtonRects = {}
        end
        longPressState.pressing = false
        longPressState.card = nil
    end

    if dragState.active and (touchId == dragState.touchId) then
        dragState.lx, dragState.ly = ScreenToLogical(sx, sy)
        TryDrop()
    end
end

function TryDrop()
    if not dragState.active then return end
    dragState.active = false
    if not dragState.card then return end

    -- 把拖拽逻辑坐标转设计坐标检查放置
    local dx, dy = LogicalToDesign(dragState.lx, dragState.ly)

    local halfW = SLOT_CARD_W / 2 + 12
    local halfH = SLOT_CARD_H / 2 + 12
    local placed = false

    for si, slot in ipairs(PLAYER_SLOTS) do
        if dx >= slot.cx - halfW and dx <= slot.cx + halfW and
           dy >= slot.cy - halfH and dy <= slot.cy + halfH then

            -- === 从石台拖拽: 交换/移位 ===
            if dragState.fromSlot then
                local srcIdx = dragState.fromSlotIdx
                local srcSlot = PLAYER_SLOTS[srcIdx]
                if si == srcIdx then
                    -- 放回原位
                    srcSlot.filled = true
                    srcSlot.card = dragState.card
                    AddFloatText(slot.cx, slot.cy - 25, "放回", 0.8, { 180, 200, 255 }, 12)
                elseif slot.filled and slot.card then
                    -- 目标有卡牌 >> 交换
                    local targetCard = slot.card
                    -- 把拖拽卡牌放到目标位
                    SetupSlotHero(slot, dragState.card)
                    -- 把目标卡牌放到源位
                    SetupSlotHero(srcSlot, targetCard)
                    SpawnPlaceEffect(slot.cx, slot.cy, dragState.card.quality)
                    SpawnPlaceEffect(srcSlot.cx, srcSlot.cy, targetCard.quality)
                    AddFloatText(slot.cx, slot.cy - 25, "换位!", 1.0, { 255, 220, 120 }, 12)
                else
                    -- 目标为空 >> 直接移入
                    SetupSlotHero(slot, dragState.card)
                    SpawnPlaceEffect(slot.cx, slot.cy, dragState.card.quality)
                    AddFloatText(slot.cx, slot.cy - 25, dragState.card.name .. " 移位!", 1.0, { 200, 255, 200 }, 12)
                end
                dragState.card = nil
                placed = true
                RefreshBaseStats()
                return
            end

            -- === 从背包/商店来源 ===
            -- 从背包移除卡牌 (仅背包来源)
            if dragState.fromInventory and dragState.invIdx > 0 then
                if dragState.invIdx <= #inventory then
                    table.remove(inventory, dragState.invIdx)
                    local maxOff = math.max(0, #inventory - GameConfig.INVENTORY_VISIBLE)
                    if invScrollOffset > maxOff then invScrollOffset = maxOff end
                end
            end

            local oldCard = slot.card

            if dragState.fromShop then
                -- 商店卡牌: 使用 SetupSlotHero 初始化槽位
                SetupSlotHero(slot, dragState.card)
            else
                slot.filled = true
                slot.card = dragState.card
            end

            -- 放置特效
            SpawnPlaceEffect(slot.cx, slot.cy, dragState.card.quality)

            if oldCard and oldCard.name == dragState.card.name then
                slot.card.level = (oldCard.level or 1) + 1
                slot.card.atk = slot.card.atk * 1.15
                slot.card.def = slot.card.def * 1.1
                slot.card.hp = slot.card.hp * 1.2
                AddFloatText(slot.cx, slot.cy - 40, "合成! Lv" .. slot.card.level, 1.5, { 255, 220, 60 }, 14)
            elseif oldCard then
                -- 被替换的卡牌回到背包
                table.insert(inventory, {
                    cardIdx = oldCard.cardIdx or 1,
                    constellation = oldCard.constellation or 0,
                })
                AddFloatText(slot.cx, slot.cy - 25, "替换!", 1.0, { 255, 180, 80 }, 12)
            end
            AddFloatText(slot.cx, slot.cy - 25, slot.card.name .. " 上阵!", 1.2, { 200, 255, 200 }, 12)
            dragState.card = nil
            placed = true
            RefreshBaseStats()
            return
        end
    end

    -- === 未放到槽位上 ===
    if not placed then
        if dragState.fromSlot then
            if gameState.battlePhase == "SHOP" then
                -- SHOP阶段: 从石台拖出 >> 兑换军资
                local card = dragState.card
                local refund = GameConfig.CARD_COST[card.quality] or 3
                gameState.gold = gameState.gold + refund
                AddFloatText(DESIGN_W / 2, DESIGN_H * 0.5,
                    card.name .. " >> +" .. refund .. "军资", 1.2, { 255, 220, 80 }, 14)
                RefreshBaseStats()
            else
                -- FIGHT阶段: 检查是否拖到战场区域进行部署
                local ddx, ddy = LogicalToDesign(dragState.lx, dragState.ly)
                local srcIdx = dragState.fromSlotIdx
                local srcSlot = srcIdx and PLAYER_SLOTS[srcIdx]
                local bz = BATTLE_ZONE

                -- 判定区域比显示区域大(上下各扩60), 方便手机操作
                local hitMargin = 60
                if srcSlot and ddx >= bz.left and ddx <= bz.right
                   and ddy >= bz.enemyLine - hitMargin and ddy <= bz.playerLine + hitMargin then
                    -- 在战场区域: 检测车道并部署
                    if srcSlot.deployCD and srcSlot.deployCD > 0 then
                        -- 冷却中, 放回原位
                        srcSlot.filled = true
                        srcSlot.card = dragState.card
                        local cdLeft = string.format("%.1f", srcSlot.deployCD)
                        AddFloatText(DESIGN_W / 2, DESIGN_H * 0.5,
                            "冷却中(" .. cdLeft .. "s)", 0.8, { 255, 150, 100 }, 14)
                    else
                        -- 检测车道
                        local laneIdx = math.floor((ddx - bz.left) / LANE_WIDTH) + 1
                        laneIdx = math.max(1, math.min(NUM_LANES, laneIdx))

                        -- 先恢复卡牌 (拖拽中slot.card被清空, SpawnUnitFromSlot需要读slot.card)
                        srcSlot.filled = true
                        srcSlot.card = dragState.card

                        -- 批量部署士兵
                        local batchSize = GetBatchSizeForSlot(srcSlot)
                        local spawned = 0
                        local unitCap = GetPlayerUnitCap()
                        for _ = 1, batchSize do
                            if #playerUnits < unitCap then
                                SpawnUnitFromSlot(srcSlot, true, laneIdx)
                                spawned = spawned + 1
                            end
                        end

                        -- 设置冷却
                        srcSlot.deployCD = DEPLOY_CD
                        srcSlot.spawnFlash = 0.5
                        srcSlot.spawnCount = (srcSlot.spawnCount or 0) + spawned

                        AddFloatText(GetLaneCenterX(laneIdx), bz.centerY,
                            "部署 ×" .. spawned .. "!", 1.2, { 200, 255, 200 }, 16)
                    end
                else
                    -- 拖出战场区域: 检查是否拖到底部卡牌区/商店区
                    -- 只有拖到商店区域(屏幕底部)才下阵换军资, 其余放回原位
                    local shopTopY = screenH - SHOP_RESERVED_H
                    if srcSlot and dragState.ly >= shopTopY then
                        -- 拖到底部卡牌区: 下阵换军资
                        local card = dragState.card
                        local refund = GameConfig.CARD_COST[card.quality] or 3
                        gameState.gold = gameState.gold + refund
                        AddFloatText(DESIGN_W / 2, DESIGN_H * 0.5,
                            card.name .. " 下阵 >> +" .. refund .. "军资", 1.2, { 255, 220, 80 }, 14)
                        RefreshBaseStats()
                    elseif srcSlot then
                        -- 其他区域: 放回原位 (取消操作)
                        srcSlot.filled = true
                        srcSlot.card = dragState.card
                    end
                end
            end
        elseif dragState.fromShop then
            local shopItem = shopCards[dragState.shopIdx]
            if shopItem then
                shopItem.sold = false
                gameState.gold = gameState.gold + shopItem.cost
                AddFloatText(DESIGN_W / 2, DESIGN_H * 0.6, "已退还军资", 1.0, { 180, 220, 255 }, 12)
            end
        end
    end
    dragState.card = nil
end

-- ============================================================================
-- 渲染主流程
-- ============================================================================

function HandleNanoVGRender(eventType, eventData)
    if not vg then return end

    local g = GetGraphics()
    local physW = g:GetWidth()
    local physH = g:GetHeight()
    local dpr = g:GetDPR()

    -- DPR 安全校验：部分华为/鸿蒙设备可能返回异常值
    if dpr ~= dpr or dpr <= 0 then dpr = 1.0 end  -- NaN/负值/零 → 回退1.0
    if dpr > 4.0 then dpr = 3.0 end                -- 目前无 DPR>4 的手机

    screenW = physW / dpr
    screenH = physH / dpr

    -- 首帧设备诊断日志（帮助定位华为等设备的兼容性问题）
    if not _deviceInfoLogged then
        _deviceInfoLogged = true
        local rawDpr = g:GetDPR()
        print(string.format("[DeviceInfo] physW=%d physH=%d rawDPR=%.3f usedDPR=%.3f logW=%.1f logH=%.1f",
            physW, physH, rawDpr, dpr, screenW, screenH))
        local platform = GetPlatform and GetPlatform() or "unknown"
        print(string.format("[DeviceInfo] platform=%s designW=%d designH=%d", platform, DESIGN_W, DESIGN_H))
    end

    -- 战斗界面预留底部商店区域，其他界面全屏
    local isBattle = (gameState.phase == "BATTLE" or gameState.phase == "WIN" or gameState.phase == "LOSE" or gameState.phase == "SHOP")
    local reservedH = isBattle and SHOP_RESERVED_H or 0
    local availH = screenH - reservedH
    local scaleX = screenW / DESIGN_W
    local scaleY = availH / DESIGN_H
    scale = math.min(scaleX, scaleY)
    offsetX = (screenW - DESIGN_W * scale) / 2
    offsetY = (availH - DESIGN_H * scale) / 2

    -- 布局安全限制：防止部分设备因分辨率报告异常导致面板过度下移
    -- 正常手机 offsetY 一般不超过 screenH 的 15%
    local maxOffsetY = screenH * 0.18
    if offsetY > maxOffsetY then
        if not _layoutWarnLogged then
            _layoutWarnLogged = true
            print(string.format("[LayoutWarn] offsetY=%.1f > max=%.1f, clamped. physW=%d physH=%d dpr=%.3f scaleX=%.4f scaleY=%.4f scale=%.4f",
                offsetY, maxOffsetY, physW, physH, dpr, scaleX, scaleY, scale))
        end
        offsetY = maxOffsetY
    end
    if offsetX > screenW * 0.18 then
        offsetX = screenW * 0.18
    end

    -- 刘海屏安全区: 物理像素 >> 逻辑像素 >> 设计坐标
    local safeRect = GetSafeAreaInsets(false)
    if safeRect then
        safeInsets.top    = (safeRect.min.y / dpr) / scale
        safeInsets.bottom = (safeRect.max.y / dpr) / scale
        safeInsets.left   = (safeRect.min.x / dpr) / scale
        safeInsets.right  = (safeRect.max.x / dpr) / scale
    end

    CalcShopLayout()

    -- 将屏幕尺寸传递给 EquipUI overlay（避免全局事件中 graphics 返回错误值）
    if EquipUI then
        EquipUI._physW = physW
        EquipUI._physH = physH
        EquipUI._dpr = dpr
        EquipUI._logW = screenW
        EquipUI._logH = screenH
    end

    nvgBeginFrame(vg, physW, physH, dpr)
    nvgSave(vg)

    -- 黑色底色
    nvgBeginPath(vg); nvgRect(vg, 0, 0, screenW, screenH)
    nvgFillColor(vg, nvgRGBA(28, 24, 38, 255)); nvgFill(vg)

    -- 字体预热：用透明色渲染常用字符，避免后续首次显示时卡顿（尤其高DPI华为设备）
    if not fontsWarmed and fontId >= 0 then
        nvgSave(vg)
        nvgFillColor(vg, nvgRGBA(0, 0, 0, 0))  -- 完全透明，不可见
        nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_TOP)
        local warmStr = "三国武灵录正在加载请稍候0123456789%讨伐将启"
            .. "确定取消返回开始继续退出设置保存装备背包技能商店"
            .. "排位讨伐挑战关卡胜利失败战斗等级经验金币钻石体力"
            .. "攻击防御生命暴击闪避速度选择头像道号蚀骨幽火白骨"
            .. "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        local warmFonts = { fontId, fontArt, fontGame, fontKai, fontFZ }
        local warmedCount = 0
        for _, fid in ipairs(warmFonts) do
            if fid and fid >= 0 then
                nvgFontFaceId(vg, fid)
                nvgFontSize(vg, 24)
                nvgText(vg, -9999, -9999, warmStr, nil)  -- 屏幕外渲染
                warmedCount = warmedCount + 1
            end
        end
        -- 只有至少主字体预热成功才标记完成
        if warmedCount > 0 then
            fontsWarmed = true
        end
        nvgRestore(vg)
    end

    -- === LOADING 界面 (屏幕逻辑坐标，不用设计坐标) ===
    if gameState.phase == "LOADING" then
        local cx = screenW / 2
        local cy = screenH / 2
        local t = menuAnimTimer

        -- 游戏标题 (行书字体)
        nvgFontFaceId(vg, GetMainFont())
        nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)

        -- 标题投影
        nvgFontSize(vg, 30)
        nvgFillColor(vg, nvgRGBA(0, 0, 0, 180))
        nvgText(vg, cx + 2, cy - 35 + 2, "三国武灵录", nil)
        -- 标题主层
        DrawWhiteInkText(cx, cy - 35, "三国武灵录")

        -- 进度条
        local barW = screenW * 0.6
        local barH = 8
        local barX = cx - barW / 2
        local barY = cy + 10
        local pct = blockingLoadState.progress or 0

        -- 进度条背景
        nvgBeginPath(vg)
        nvgRoundedRect(vg, barX, barY, barW, barH, 4)
        nvgFillColor(vg, nvgRGBA(40, 40, 55, 200)); nvgFill(vg)

        -- 进度填充
        local fillW = barW * pct
        if fillW > 1 then
            local grad = nvgLinearGradient(vg, barX, barY, barX + fillW, barY,
                nvgRGBA(180, 150, 90, 220), nvgRGBA(220, 190, 120, 220))
            nvgBeginPath(vg)
            nvgRoundedRect(vg, barX, barY, fillW, barH, 4)
            nvgFillPaint(vg, grad); nvgFill(vg)
        end

        -- 进度文字
        nvgFontSize(vg, 16)
        nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_TOP)
        nvgFillColor(vg, nvgRGBA(215, 190, 120, 220))
        local loadText = string.format("正在加载 %d%%", math.floor(pct * 100))
        nvgText(vg, cx, barY + barH + 8, loadText, nil)

        -- 底部提示 (呼吸)
        local tipAlpha = math.floor(100 + 60 * math.sin(t * 2.0))
        nvgFontSize(vg, 14)
        nvgFillColor(vg, nvgRGBA(140, 130, 110, tipAlpha))
        nvgText(vg, cx, barY + barH + 32, "讨伐将启，请稍候...", nil)

        -- 具体进度数字
        nvgFontSize(vg, 13)
        nvgFillColor(vg, nvgRGBA(120, 115, 100, 160))
        local detailText = string.format("(%d/%d)", blockingLoadState.completedCount or 0, blockingLoadState.totalCount or 0)
        nvgText(vg, cx, barY + barH + 50, detailText, nil)

        -- 点击提示（玩家点击屏幕时显示）
        if loadingClickTipTimer and loadingClickTipTimer > 0 then
            local tipA = math.min(1, loadingClickTipTimer / 0.3)
            nvgFontSize(vg, 20)
            nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
            nvgFillColor(vg, nvgRGBA(255, 220, 120, math.floor(220 * tipA)))
            nvgText(vg, cx, cy + 80, "资源加载中，请耐心等待~", nil)
        end

        nvgRestore(vg)
        nvgEndFrame(vg)
        return  -- LOADING 阶段不渲染其他内容
    end

    -- === 游戏区域 (设计坐标) ===
    nvgSave(vg)
    nvgTranslate(vg, offsetX, offsetY)
    nvgScale(vg, scale, scale)

    if gameState.phase == "PROFILE" then
        DrawProfileScreen()
        DrawFloatTexts()
    elseif gameState.phase == "MENU" then
        if settingsPage.btnAdjustMode then
            DrawBtnAdjustMode()
        else
            DrawMenuScreen()
            DrawFloatTexts()
            if settingsPage.isOpen then DrawSettingsScreen() end
            if cdkState.inputOpen then DrawCDKPopup() end
            DrawNewbieGuidePopup()   -- 新手指引弹窗 (覆盖在菜单上层)
            DrawPowerExplainPopup()  -- 战力说明弹窗
        end
    elseif gameState.phase == "GACHA" then
        DrawGachaScreen()
        DrawFloatTexts()
    elseif gameState.phase == "CODEX" then
        DrawCodexScreen()
        DrawFloatTexts()
    elseif gameState.phase == "HERO_DETAIL" then
        DrawHeroDetailScreen()
        DrawFloatTexts()
    elseif gameState.phase == "PLAYER_DETAIL" then
        DrawPlayerDetailScreen()
        DrawFloatTexts()
        DrawPowerExplainPopup()  -- 战力说明弹窗 (覆盖在详情上层)
    elseif gameState.phase == "SKILL_CODEX" then
        DrawSkillCodexScreen()
        DrawFloatTexts()
    elseif gameState.phase == "SKILL_DETAIL" then
        DrawSkillDetailScreen()
        DrawFloatTexts()
    elseif gameState.phase == "WELFARE" then
        DrawWelfareScreen()
        DrawFloatTexts()
    elseif gameState.phase == "PROGRESS" then
        DrawDailyTasksAndAchievements()
        DrawFloatTexts()
    elseif gameState.phase == "EQUIP" then
        DrawEquipScreen()
    elseif gameState.phase == "EQUIP_CODEX" then
        DrawEquipCodexScreen()
    elseif gameState.phase == "SEAL_MGR" then
        DrawSealMgrScreen()
        DrawFloatTexts()
    elseif gameState.phase == "MAIL_BOX" then
        DrawMailBoxScreen()
        DrawFloatTexts()
    elseif gameState.phase == "POWER_RANK" then
        DrawPowerRankScreen()
        DrawFloatTexts()
    elseif gameState.phase == "TRADE" then
        DrawTradeScreen()
        DrawFloatTexts()
    elseif gameState.phase == "FACTION" then
        DrawFactionScreen()
        DrawFloatTexts()
    elseif gameState.phase == "FRIENDS" then
        DrawFriendsScreen()
        DrawFloatTexts()
    elseif gameState.phase == "FORMATION" then
        DrawFormationScreen()
        DrawFloatTexts()
    elseif gameState.phase == "CONTRIB_RANK" then
        DrawContribRankScreen()
        DrawFloatTexts()
    elseif gameState.phase == "STAGE_SELECT" then
        DrawStageSelectScreen()
        DrawFloatTexts()
    elseif gameState.phase == "DAILY_DUNGEON" then
        DrawDailyDungeonScreen()
        DrawFloatTexts()
    elseif gameState.phase == "RESOURCE_DUNGEON" then
        DrawResourceDungeonScreen()
        DrawFloatTexts()
    elseif gameState.phase == "BATTLE_PASS" then
        DrawBattlePassScreen()
        DrawFloatTexts()
    elseif gameState.phase == "ABYSS_SELECT" then
        DrawAbyssSelectScreen()
        DrawFloatTexts()
    elseif gameState.phase == "EXPLORATION" then
        Exploration.Draw(DESIGN_W, DESIGN_H, gameState.gameTime)
        DrawFloatTexts()
    elseif gameState.phase == "TOWER_SELECT" then
        DrawTowerSelectScreen()
        DrawFloatTexts()
    elseif gameState.phase == "RANKED_SELECT" then
        DrawRankedSelectScreen()
        DrawFloatTexts()
    elseif gameState.phase == "DUMMY_SELECT" then
        DrawDummySelectScreen()
        DrawFloatTexts()
    elseif gameState.phase == "DUMMY_RESULT" then
        DrawDummyResultScreen()
        DrawFloatTexts()
    elseif gameState.phase == "DEV_EDITOR" then
        DrawDevEditorScreen()
        DrawFloatTexts()
        DrawFloatTexts()
    else
        DrawBackground()
        DrawCriticalLines()
        DrawLaneDividers()
        DrawBaseHPBars()
        DrawGroundSkillEffects() -- 底层技能特效 (在单位之下, 如治疗法阵)
        DrawBattleUnits()
        DrawSkillEffects()       -- 武技技能特效 (在单位之上)
        DrawSkillTargetingDesign()  -- 技能瞄准指示器
        DrawParticles()
        UpdateAndDrawProjectiles(time:GetTimeStep())
        DrawCardSlots()
        DrawSlotHighlights()  -- 拖拽时的槽位高亮
        DrawHUD()
        DrawBattleButtons()  -- 右侧按钮在设计坐标空间绘制
        DrawBottomActionBar()  -- 右下角操作栏(自动行军+技能预留)
        DrawStrategyWheel()   -- 策略轮盘(长按自动行军弹出)
        DrawFloatTexts()
        DrawGameResultOverlay()
        DrawRewardPopup()
        DrawExploreExitConfirmPopup()  -- 探索退出/死亡确认弹窗
        DrawBattleRulesPopup()  -- 战斗规则弹窗
        -- DrawSkillInfoPopup()    -- 已移除武技详情弹窗 (改为按下即拖拽)
    end

    -- === 统一规则弹窗 (叠加在所有界面之上) ===
    DrawPhaseRulePopup()

    -- === 教程 overlay (设计坐标空间, 叠加在所有 phase 之上) ===
    if tutorialState.active and tutorialState.step >= 2 and tutorialState.step <= 13 then
        DrawTutorialGuideOverlay()
        DrawTutorialExitConfirmPopup()
    end
    if tutorialState.active and tutorialState.step == 14 then
        DrawTutorialVictoryTransition()
    end
    if tutorialState.active and tutorialState.step == 15 then
        DrawTutorialRewardPopup()
    end

    nvgRestore(vg)

    -- === 以下全部在屏幕逻辑坐标 ===
    if gameState.phase == "BATTLE" or gameState.phase == "WIN" or gameState.phase == "LOSE" then
        DrawShop()
        DrawDragCardScreen()   -- ★ 拖拽卡牌在屏幕坐标渲染
        DrawInfoPanel()
        DrawLongPressTip()     -- (已废弃, 空函数)
        DrawInfoPopup()        -- ★ 单击信息弹窗 (含车道选择)
    end

    -- 全局 Toast 提示（覆盖在最上层）
    DrawToast(DESIGN_W, DESIGN_H)

    -- 云数据加载中遮罩（半透明，显示加载提示）
    if CloudManager.IsCloudLoading() then
        local cW, cH = DESIGN_W, DESIGN_H
        nvgBeginPath(vg); nvgRect(vg, 0, 0, cW, cH)
        nvgFillColor(vg, nvgRGBA(0, 0, 0, 160)); nvgFill(vg)
        -- 加载提示框
        local boxW, boxH = 260, 80
        local boxX, boxY = (cW - boxW) / 2, (cH - boxH) / 2
        nvgBeginPath(vg); nvgRoundedRect(vg, boxX, boxY, boxW, boxH, 12)
        nvgFillColor(vg, nvgRGBA(30, 30, 40, 230)); nvgFill(vg)
        -- 旋转加载点动画
        local dotPhase = (os.clock() * 3) % 3
        nvgFontFace(vg, "sans"); nvgFontSize(vg, 18)
        nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        nvgFillColor(vg, nvgRGBA(220, 220, 220, 255))
        local dots = dotPhase < 1 and "." or (dotPhase < 2 and ".." or "...")
        nvgText(vg, cW / 2, cH / 2, "正在同步云端数据" .. dots)
    end

    -- 封禁全屏遮罩（最高层级，阻止一切操作）
    if gameState.isBanned then
        local bW, bH = DESIGN_W, DESIGN_H
        nvgBeginPath(vg); nvgRect(vg, 0, 0, bW, bH)
        nvgFillColor(vg, nvgRGBA(0, 0, 0, 220)); nvgFill(vg)

        local bcx, bcy = bW / 2, bH / 2
        -- 红色警告框
        local boxW, boxH = 380, 160
        local boxX, boxY = bcx - boxW / 2, bcy - boxH / 2
        nvgBeginPath(vg); nvgRoundedRect(vg, boxX, boxY, boxW, boxH, 14)
        nvgFillColor(vg, nvgRGBA(40, 10, 10, 240)); nvgFill(vg)
        nvgStrokeColor(vg, nvgRGBA(200, 60, 60, 200)); nvgStrokeWidth(vg, 2); nvgStroke(vg)

        nvgFontSize(vg, 20); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        nvgFillColor(vg, nvgRGBA(255, 100, 100, 255))
        nvgText(vg, bcx, boxY + 40, "账号已封禁", nil)

        nvgFontSize(vg, 14); nvgFillColor(vg, nvgRGBA(220, 200, 200, 220))
        nvgText(vg, bcx, boxY + 75, "您的账户经检测数据异常，已暂时被封禁", nil)
        nvgText(vg, bcx, boxY + 100, "请联系版主处理", nil)

        nvgFontSize(vg, 12); nvgFillColor(vg, nvgRGBA(150, 150, 160, 160))
        nvgText(vg, bcx, boxY + 130, "如有疑问请通过社区反馈", nil)
    end

    nvgRestore(vg)
    nvgEndFrame(vg)
end

function CalcShopLayout()
    local sl = shopLayout
    sl.h = SHOP_RESERVED_H
    sl.y = screenH - sl.h

    sl.cardH = sl.h - 32
    sl.cardW = sl.cardH * CARD_RATIO
    sl.gap = 6

    -- 可见卡牌数
    local visCount = GameConfig.INVENTORY_VISIBLE
    -- 翻页箭头宽度
    local arrowW = 22
    -- 抽卡按钮宽度
    local drawBtnW = 60

    local totalCardsW = visCount * sl.cardW + (visCount - 1) * sl.gap
    local totalW = arrowW + 6 + totalCardsW + 6 + arrowW + 10 + drawBtnW
    sl.startX = (screenW - totalW) / 2 + arrowW + 6

    -- 左箭头区域
    sl.arrowLeftX = sl.startX - 6 - arrowW
    sl.arrowLeftW = arrowW
    -- 右箭头区域
    sl.arrowRightX = sl.startX + totalCardsW + 6
    sl.arrowRightW = arrowW

    -- 抽卡按钮
    sl.drawBtnW = drawBtnW
    sl.drawBtnH = 36
    sl.drawBtnX = sl.arrowRightX + arrowW + 10
    sl.drawBtnY = sl.y + sl.h / 2 - sl.drawBtnH / 2 - 2
end

-- ============================================================================
-- 墨字辅助: 黑色毛笔字 + 轻微白色描边
-- ============================================================================
--- 绘制墨字风格文本 (使用前需已设好 nvgFontSize/nvgTextAlign/nvgFontFaceId)
function DrawInkText(x, y, text)
    -- 轻微白色描边 (4方向偏移1px) — 使用原始函数避免双重描边
    nvgFillColor(vg, nvgRGBA(255, 255, 255, 130))
    _nvgTextOrig(vg, x - 1, y, text, nil)
    _nvgTextOrig(vg, x + 1, y, text, nil)
    _nvgTextOrig(vg, x, y - 1, text, nil)
    _nvgTextOrig(vg, x, y + 1, text, nil)
    -- 黑色墨字主体
    nvgFillColor(vg, nvgRGBA(30, 25, 20, 240))
    _nvgTextOrig(vg, x, y, text, nil)
end

function DrawWhiteInkText(x, y, text)
    -- 黑色描边 (8方向偏移1.5px，更粗更清晰) — 使用原始函数避免双重描边
    nvgFillColor(vg, nvgRGBA(0, 0, 0, 210))
    for _, off in ipairs({{-1.5,0},{1.5,0},{0,-1.5},{0,1.5},{-1,-1},{1,-1},{-1,1},{1,1}}) do
        _nvgTextOrig(vg, x + off[1], y + off[2], text, nil)
    end
    -- 白色主体
    nvgFillColor(vg, nvgRGBA(255, 255, 255, 255))
    _nvgTextOrig(vg, x, y, text, nil)
end

-- ============================================================================
-- 背景
-- ============================================================================

function DrawBackground()
    -- 统一走 BATTLE_LAYOUTS 背景 (InitBattle 中已设置 currentLayoutIdx)
    local bgHandle = nil
    if currentLayoutIdx and BATTLE_LAYOUTS[currentLayoutIdx] then
        bgHandle = BATTLE_LAYOUTS[currentLayoutIdx].bgHandle
    end

    if not bgHandle or not IsImageReady(bgHandle) then
        -- 无背景图(默认战场)或图片未就绪: 绘制纯色深色背景
        nvgBeginPath(vg); nvgRect(vg, 0, 0, DESIGN_W, DESIGN_H)
        nvgFillColor(vg, nvgRGBA(22, 18, 30, 255)); nvgFill(vg)
        -- 如果有图但还在加载中，显示加载动画
        if bgHandle and not IsImageReady(bgHandle) then
            DrawSpinner(DESIGN_W / 2, DESIGN_H / 2, 20)
            return
        end
    else
        -- 有背景图: 所有战斗背景图均为 714×1280 (BG_W×BG_H)，直接拉伸到设计分辨率
        local p = nvgImagePattern(vg, 0, 0, DESIGN_W, DESIGN_H, 0, bgHandle, 1.0)
        nvgBeginPath(vg); nvgRect(vg, 0, 0, DESIGN_W, DESIGN_H)
        nvgFillPaint(vg, p); nvgFill(vg)
    end

    -- ★ 卡牌放置区域遮罩: 上下添加暗色渐变, 确保卡牌清晰可见
    -- 顶部敌方卡牌区 (Y 0~210): 从上往下渐变, 暗→透明
    local topZoneH = 210
    local topGrad = nvgLinearGradient(vg, 0, 0, 0, topZoneH,
        nvgRGBA(18, 12, 28, 120), nvgRGBA(0, 0, 0, 0))
    nvgBeginPath(vg); nvgRect(vg, 0, 0, DESIGN_W, topZoneH)
    nvgFillPaint(vg, topGrad); nvgFill(vg)

    -- 底部玩家卡牌区 (Y 820~1024): 从下往上渐变, 暗→透明
    local botStart = 820
    local botGrad = nvgLinearGradient(vg, 0, DESIGN_H, 0, botStart,
        nvgRGBA(18, 12, 28, 140), nvgRGBA(0, 0, 0, 0))
    nvgBeginPath(vg); nvgRect(vg, 0, botStart, DESIGN_W, DESIGN_H - botStart)
    nvgFillPaint(vg, botGrad); nvgFill(vg)
end

-- ============================================================================
-- 临界线 (突破扣血线)
-- ============================================================================

function DrawCriticalLines()
    local t = gameState.gameTime
    local bz = BATTLE_ZONE

    -- 敌方临界线 (上方, 绿色 — 玩家兵到达此处扣敌方血)
    local ePulse = 0.4 + 0.3 * math.sin(t * 3)
    local eLineY = bz.enemyLine
    -- 渐变发光带
    local eGlow = nvgLinearGradient(vg, 0, eLineY - 6, 0, eLineY + 6,
        nvgRGBA(80, 255, 150, 0),
        nvgRGBA(80, 255, 150, math.floor(25 * ePulse)))
    nvgBeginPath(vg); nvgRect(vg, bz.left, eLineY - 6, bz.right - bz.left, 12)
    nvgFillPaint(vg, eGlow); nvgFill(vg)
    -- 主线
    nvgBeginPath(vg)
    nvgMoveTo(vg, bz.left + 10, eLineY); nvgLineTo(vg, bz.right - 10, eLineY)
    nvgStrokeColor(vg, nvgRGBA(80, 255, 150, math.floor(50 + 40 * ePulse)))
    nvgStrokeWidth(vg, 0.8); nvgStroke(vg)

    -- 玩家临界线 (下方, 红色 — 敌方兵到达此处扣玩家血)
    local pPulse = 0.4 + 0.3 * math.sin(t * 3 + 1.5)
    local pLineY = bz.playerLine
    -- 渐变发光带
    local pGlow = nvgLinearGradient(vg, 0, pLineY - 6, 0, pLineY + 6,
        nvgRGBA(255, 80, 60, math.floor(25 * pPulse)),
        nvgRGBA(255, 80, 60, 0))
    nvgBeginPath(vg); nvgRect(vg, bz.left, pLineY - 6, bz.right - bz.left, 12)
    nvgFillPaint(vg, pGlow); nvgFill(vg)
    -- 主线
    nvgBeginPath(vg)
    nvgMoveTo(vg, bz.left + 10, pLineY); nvgLineTo(vg, bz.right - 10, pLineY)
    nvgStrokeColor(vg, nvgRGBA(255, 80, 60, math.floor(50 + 40 * pPulse)))
    nvgStrokeWidth(vg, 0.8); nvgStroke(vg)
end

-- ============================================================================
-- 车道分割线 (战斗中显示, 设计坐标)
-- ============================================================================

function DrawLaneDividers()
    if gameState.battlePhase ~= "FIGHT" then return end

    local bz = BATTLE_ZONE
    local t = gameState.gameTime

    -- 检测拖拽悬停车道 (从石台拖拽卡牌到战场时高亮)
    local highlightLane = 0
    local isDraggingSlot = dragState.active and dragState.fromSlot and dragState.card
    if isDraggingSlot then
        local ddx, ddy = LogicalToDesign(dragState.lx, dragState.ly)
        local hitMarginLane = 60
        if ddx >= bz.left and ddx <= bz.right
           and ddy >= bz.enemyLine - hitMarginLane and ddy <= bz.playerLine + hitMarginLane then
            highlightLane = math.floor((ddx - bz.left) / LANE_WIDTH) + 1
            highlightLane = math.max(1, math.min(NUM_LANES, highlightLane))
        end
    end

    -- 拖拽时显示所有车道背景 + 高亮悬停车道
    if isDraggingSlot then
        for i = 1, NUM_LANES do
            local laneX = bz.left + (i - 1) * LANE_WIDTH
            local laneH = bz.playerLine - bz.enemyLine
            nvgBeginPath(vg)
            nvgRect(vg, laneX, bz.enemyLine, LANE_WIDTH, laneH)
            if i == highlightLane then
                -- 高亮车道: 明亮蓝色
                local pulse = 0.6 + 0.4 * math.sin(t * 4)
                nvgFillColor(vg, nvgRGBA(80, 180, 255, math.floor(45 * pulse)))
            else
                -- 其他车道: 淡色
                nvgFillColor(vg, nvgRGBA(100, 140, 180, 12))
            end
            nvgFill(vg)
        end
    end

    -- 绘制4条车道分割线 (5条车道有4条分割线)
    for i = 1, NUM_LANES - 1 do
        local lx = bz.left + i * LANE_WIDTH
        local isNearHighlight = (highlightLane > 0) and (i == highlightLane or i == highlightLane - 1)
        local alpha = isNearHighlight
            and math.floor(80 + 40 * math.sin(t * 3))
            or math.floor(18 + 8 * math.sin(t * 1.5 + i * 0.8))
        local lineW = isNearHighlight and 1.2 or 0.6

        -- 虚线效果
        local dashLen = 8
        local gapLen = 6
        local y = bz.enemyLine + 4
        while y < bz.playerLine - 4 do
            local segEnd = math.min(y + dashLen, bz.playerLine - 4)
            nvgBeginPath(vg)
            nvgMoveTo(vg, lx, y)
            nvgLineTo(vg, lx, segEnd)
            if isNearHighlight then
                nvgStrokeColor(vg, nvgRGBA(100, 200, 255, alpha))
            else
                nvgStrokeColor(vg, nvgRGBA(140, 180, 220, alpha))
            end
            nvgStrokeWidth(vg, lineW)
            nvgStroke(vg)
            y = segEnd + gapLen
        end
    end

    -- 车道编号 (拖拽时更明显)
    if fontId >= 0 then
        nvgFontFaceId(vg, GetMainFont())
        local lblSize = isDraggingSlot and 18 or 12
        nvgFontSize(vg, lblSize)
        nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        local laneNames = { "一", "二", "三", "四", "五" }
        for i = 1, NUM_LANES do
            local cx = GetLaneCenterX(i)
            if isDraggingSlot then
                local isHL = (i == highlightLane)
                local a = isHL and 220 or 90
                nvgFillColor(vg, nvgRGBA(isHL and 120 or 160, isHL and 220 or 180, 255, a))
                nvgText(vg, cx, bz.enemyLine - 12, laneNames[i], nil)
            else
                nvgFillColor(vg, nvgRGBA(160, 180, 210, 40))
                nvgText(vg, cx, bz.enemyLine - 6, tostring(i), nil)
            end
        end
    end
end

-- ============================================================================
-- 石台卡牌 (透明角色 + 品质底光)
-- ============================================================================

-- 根据卡牌返回对应的精灵图句柄 (所有武灵均为独立图)
function GetHeroSheet(card)
    if card.singleImg then return IMG[card.singleImg] or -1 end
    return -1
end

--- 获取无背景版精灵图 (石台上渲染用，武灵独立图复用原图)
function GetHeroSheetNoBg(card)
    if card.singleImg then return IMG[card.singleImg] or -1 end
    return -1
end

-- 返回精灵图句柄及其网格列数/行数 (所有武灵均为1×1独立图)
function GetHeroSheetInfo(card)
    return GetHeroSheet(card), 1, 1
end

--- 绘制所有石台底座图片 (在卡牌下方)
-- 阵营石台配色表
PLATFORM_COLORS = {
    shu = { -- 蜀·翠玉石台
        topLight  = { 70, 130, 90 },   -- 顶面亮色
        topDark   = { 35, 75, 50 },    -- 顶面暗色
        side      = { 25, 55, 38 },    -- 侧面
        shadow    = { 10, 30, 18 },    -- 阴影
        rim       = { 100, 210, 130 }, -- 边缘光
        glow      = { 80, 200, 120 },  -- 底部辉光
    },
    wu = { -- 吴·赤焰石台
        topLight  = { 140, 65, 55 },
        topDark   = { 85, 35, 30 },
        side      = { 60, 25, 22 },
        shadow    = { 35, 12, 10 },
        rim       = { 220, 100, 80 },
        glow      = { 200, 80, 60 },
    },
    wei = { -- 魏·玄铁石台
        topLight  = { 75, 90, 130 },
        topDark   = { 40, 50, 80 },
        side      = { 30, 38, 60 },
        shadow    = { 12, 16, 30 },
        rim       = { 100, 140, 220 },
        glow      = { 80, 120, 200 },
    },
}

--- 绘制单个程序化石台
function DrawSinglePlatform(cx, cy, w, h, colors, t)
    local r = 6      -- 圆角
    local sideH = 8  -- 侧面厚度
    local shadowOff = 4

    -- 1) 阴影 (模糊椭圆)
    local sc = colors.shadow
    nvgBeginPath(vg)
    nvgEllipse(vg, cx, cy + sideH + shadowOff, w * 0.48, h * 0.22)
    nvgFillColor(vg, nvgRGBA(sc[1], sc[2], sc[3], 100))
    nvgFill(vg)

    -- 2) 侧面 (深色矩形, 表示石台厚度)
    local sd = colors.side
    nvgBeginPath(vg)
    nvgRoundedRect(vg, cx - w / 2, cy - h / 2 + sideH, w, h, r)
    nvgFillColor(vg, nvgRGBA(sd[1], sd[2], sd[3], 220))
    nvgFill(vg)
    -- 侧面底部高光线
    nvgBeginPath(vg)
    nvgMoveTo(vg, cx - w / 2 + r, cy + h / 2 + sideH - 1)
    nvgLineTo(vg, cx + w / 2 - r, cy + h / 2 + sideH - 1)
    nvgStrokeColor(vg, nvgRGBA(sd[1] + 30, sd[2] + 30, sd[3] + 30, 80))
    nvgStrokeWidth(vg, 0.8)
    nvgStroke(vg)

    -- 3) 顶面 (渐变矩形, 从亮到暗)
    local tl = colors.topLight
    local td = colors.topDark
    local topGrad = nvgLinearGradient(vg,
        cx, cy - h / 2, cx, cy + h / 2,
        nvgRGBA(tl[1], tl[2], tl[3], 200),
        nvgRGBA(td[1], td[2], td[3], 210))
    nvgBeginPath(vg)
    nvgRoundedRect(vg, cx - w / 2, cy - h / 2, w, h, r)
    nvgFillPaint(vg, topGrad)
    nvgFill(vg)

    -- 4) 顶面内部纹理线 (模拟石纹)
    nvgSave(vg)
    nvgScissor(vg, cx - w / 2, cy - h / 2, w, h)
    for li = 1, 3 do
        local offX = math.sin(li * 2.7 + cx * 0.1) * (w * 0.3)
        local offY = -h * 0.3 + li * (h * 0.25)
        nvgBeginPath(vg)
        nvgMoveTo(vg, cx - w / 2 + 4 + offX, cy - h / 2 + offY)
        nvgQuadTo(vg, cx + offX * 0.3, cy - h / 2 + offY + 6,
                      cx + w / 2 - 4 + offX * 0.5, cy - h / 2 + offY - 2)
        nvgStrokeColor(vg, nvgRGBA(tl[1] + 15, tl[2] + 15, tl[3] + 15, 25))
        nvgStrokeWidth(vg, 0.6)
        nvgStroke(vg)
    end
    nvgRestore(vg)

    -- 5) 阵营色边缘光 (顶面外描边 + 微弱脉动)
    local rm = colors.rim
    local pulse = 0.5 + 0.3 * math.sin((t or 0) * 2.0 + cx * 0.05)
    nvgBeginPath(vg)
    nvgRoundedRect(vg, cx - w / 2, cy - h / 2, w, h, r)
    nvgStrokeColor(vg, nvgRGBA(rm[1], rm[2], rm[3], math.floor(50 * pulse)))
    nvgStrokeWidth(vg, 1.2)
    nvgStroke(vg)

    -- 6) 顶面高光 (左上角微弱高光点)
    local hlGrad = nvgRadialGradient(vg,
        cx - w * 0.25, cy - h * 0.25, 2, w * 0.4,
        nvgRGBA(255, 255, 255, 30), nvgRGBA(255, 255, 255, 0))
    nvgBeginPath(vg)
    nvgRoundedRect(vg, cx - w / 2, cy - h / 2, w, h, r)
    nvgFillPaint(vg, hlGrad)
    nvgFill(vg)
end

function DrawSlotPlatforms()
    local layout = BATTLE_LAYOUTS[currentLayoutIdx] or BATTLE_LAYOUTS[1]
    local faction = layout.platformFaction or "shu"
    local colors = PLATFORM_COLORS[faction] or PLATFORM_COLORS.shu
    local platW = SLOT_CARD_W + 14
    local platH = SLOT_CARD_H + 12
    local t = gameState and gameState.gameTime or 0
    for _, slot in ipairs(ENEMY_SLOTS) do
        DrawSinglePlatform(slot.cx, slot.cy, platW, platH, colors, t)
    end
    for _, slot in ipairs(PLAYER_SLOTS) do
        DrawSinglePlatform(slot.cx, slot.cy, platW, platH, colors, t)
    end
end

function DrawCardSlots()
    -- DrawSlotPlatforms()  -- 石台已融入背景图
    for _, slot in ipairs(ENEMY_SLOTS) do DrawSlotCard(slot, false) end
    for _, slot in ipairs(PLAYER_SLOTS) do DrawSlotCard(slot, true) end
end

function DrawSlotCard(slot, isPlayer)
    local cx, cy = slot.cx, slot.cy
    local w, h = SLOT_CARD_W, SLOT_CARD_H

    if slot.filled and slot.card then
        local card = slot.card
        local t = gameState.gameTime
        local qg = QUALITY_GLOW[card.quality]
        local qc = QUALITY_COLORS[card.quality]

        -- 角色图 (使用原始带背景卡牌图)
        local useSheet, useRow, useCol, useCols, useRows
        -- 所有卡牌统一使用武灵独立图
        local _sh, _sc, _sr = GetHeroSheetInfo(card)
        useSheet = _sh; useRow = card.row; useCol = card.col
        useCols = _sc; useRows = _sr
        if useSheet and useSheet > 0 then
            DrawCardImage(cx - w / 2, cy - h / 2, w, h, useSheet, useRow, useCol, useCols, useRows)
        end

        -- 等阶标签 (N/R/SR/SSR, 左下角)
        if fontId >= 0 then
            local qTag = QUALITY_TAGS[card.quality] or "N"
            local qc2 = QUALITY_COLORS[card.quality] or { 200, 195, 180 }
            local tagW = #qTag > 2 and 24 or (#qTag > 1 and 18 or 12)
            local tagH = 11
            local tagX = cx - w / 2 + 1
            local tagY = cy + h / 2 - tagH - 1
            nvgBeginPath(vg); nvgRoundedRect(vg, tagX, tagY, tagW, tagH, 2)
            nvgFillColor(vg, nvgRGBA(qc2[1], qc2[2], qc2[3], 180)); nvgFill(vg)
            nvgFontFaceId(vg, GetMainFont()); nvgFontSize(vg, 13)
            nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
            DrawWhiteInkText(tagX + tagW / 2, tagY + tagH / 2, qTag)
        end

        -- 等级标记 (Lv2+ 古铜标记)
        if fontId >= 0 and card.level and card.level > 1 then
            local lvW = 22
            local lvH = 10
            local lvX = cx - lvW / 2
            local lvY = cy - h / 2 - lvH - 1
            nvgBeginPath(vg); nvgRoundedRect(vg, lvX, lvY, lvW, lvH, 2)
            nvgFillColor(vg, nvgRGBA(20, 15, 5, 180)); nvgFill(vg)
            nvgStrokeColor(vg, nvgRGBA(255, 210, 70, 60))
            nvgStrokeWidth(vg, 0.4); nvgStroke(vg)
            nvgFontFaceId(vg, GetMainFont()); nvgFontSize(vg, 14)
            nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
            DrawWhiteInkText(cx, lvY + lvH / 2, "Lv" .. card.level)
        end

        -- 命格徽标 (C0不显示, C1+显示)
        local cons = card.constellation or 0
        if fontId >= 0 and cons > 0 then
            local cc = GameConfig.CONSTELLATION_COLORS[cons] or { 180, 175, 165 }
            local badgeR = 6
            local badgeX = cx + w / 2 - 2
            local badgeY = cy - h / 2 - 2
            nvgBeginPath(vg); nvgCircle(vg, badgeX, badgeY, badgeR)
            nvgFillColor(vg, nvgRGBA(cc[1], cc[2], cc[3], 220)); nvgFill(vg)
            nvgStrokeColor(vg, nvgRGBA(255, 255, 255, 150))
            nvgStrokeWidth(vg, 0.8); nvgStroke(vg)
            nvgFontFaceId(vg, GetMainFont()); nvgFontSize(vg, 14)
            nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
            DrawWhiteInkText(badgeX, badgeY, "C" .. cons)
        end

        -- 出兵计数 (战斗中显示)
        if slot.filled and card and fontId >= 0 and gameState.battlePhase == "FIGHT" then
            -- 出兵计数 (卡牌左上角醒目显示)
            local sc = slot.spawnCount or 0
            if sc > 0 then
                local isFlashing = slot.spawnFlash and slot.spawnFlash > 0
                local flashP = isFlashing and math.min(1, slot.spawnFlash / 0.3) or 0

                -- 出兵数字背景圆 (放在卡牌上方, 避免被精灵遮挡)
                local badgeX = cx - w / 2 + 6
                local badgeY = cy - h / 2 - 14
                local badgeR = 9 + (isFlashing and (4 * flashP) or 0)
                -- 闪光时放大+高亮
                nvgBeginPath(vg); nvgCircle(vg, badgeX, badgeY, badgeR)
                if isFlashing then
                    nvgFillColor(vg, nvgRGBA(80, 255, 120, math.floor(180 + 75 * flashP)))
                else
                    nvgFillColor(vg, nvgRGBA(40, 160, 80, 200))
                end
                nvgFill(vg)
                nvgStrokeColor(vg, nvgRGBA(200, 255, 200, 180))
                nvgStrokeWidth(vg, 1.2); nvgStroke(vg)

                -- 数字
                nvgFontFaceId(vg, GetMainFont())
                nvgFontSize(vg, isFlashing and 17 or 14)
                nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
                DrawWhiteInkText(badgeX, badgeY, tostring(sc))

                -- 出兵闪光: 向上飘动的 "兵" 字动画
                if isFlashing then
                    local floatY = cy - h / 2 - 18 - (1 - flashP) * 20
                    local floatA = math.floor(220 * flashP)
                    nvgFontSize(vg, 16)
                    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
                    nvgFillColor(vg, nvgRGBA(120, 255, 160, floatA))
                    nvgText(vg, cx, floatY, "+1", nil)
                end
            end

            -- 部署冷却覆盖层 (己方卡牌, 冷却中暗化并显示倒计时)
            if isPlayer and slot.deployCD and slot.deployCD > 0 then
                -- 暗色遮罩
                nvgBeginPath(vg); nvgRoundedRect(vg, cx - w / 2, cy - h / 2, w, h, 3)
                nvgFillColor(vg, nvgRGBA(5, 5, 12, 110)); nvgFill(vg)

                -- 冷却进度环 (圆弧)
                local cdRatio = slot.deployCD / DEPLOY_CD
                local arcR = math.min(w, h) / 2 - 4
                nvgBeginPath(vg)
                nvgArc(vg, cx, cy, arcR, -math.pi / 2, -math.pi / 2 + cdRatio * math.pi * 2, 1)
                nvgStrokeColor(vg, nvgRGBA(255, 200, 100, 160))
                nvgStrokeWidth(vg, 2.5); nvgStroke(vg)

                -- CD倒计时数字
                if fontId >= 0 then
                    nvgFontFaceId(vg, GetMainFont()); nvgFontSize(vg, 20)
                    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
                    DrawWhiteInkText(cx, cy, string.format("%.1f", slot.deployCD))
                end
            end
        end
    end
end

-- 拖拽时的槽位高亮 (设计坐标, 用圆形匹配石台视觉)
function DrawSlotHighlights()
    if not dragState.active then return end
    local t = gameState.gameTime
    for _, slot in ipairs(PLAYER_SLOTS) do
        local pulse = 0.5 + 0.5 * math.sin(t * 5)
        -- 石台是近似圆形, 用圆形高亮匹配
        local r = SLOT_CARD_W / 2 + 3
        nvgBeginPath(vg); nvgCircle(vg, slot.cx, slot.cy, r)
        nvgStrokeColor(vg, nvgRGBA(255, 230, 100, math.floor(50 + 80 * pulse)))
        nvgStrokeWidth(vg, 1.8); nvgStroke(vg)
        -- 内圈微光
        local innerGrad = nvgRadialGradient(vg, slot.cx, slot.cy, r * 0.3, r,
            nvgRGBA(255, 230, 100, math.floor(15 * pulse)),
            nvgRGBA(255, 230, 100, 0))
        nvgBeginPath(vg); nvgCircle(vg, slot.cx, slot.cy, r)
        nvgFillPaint(vg, innerGrad); nvgFill(vg)
    end
end

-- 转圈 loading 动画（资源下载中占位）
function DrawSpinner(cx, cy, radius)
    local t = gameState.gameTime or 0
    local arcLen = math.pi * 0.8
    local startAngle = t * 4.0
    nvgSave(vg)
    nvgBeginPath(vg)
    nvgArc(vg, cx, cy, radius, startAngle, startAngle + arcLen, NVG_CW)
    nvgStrokeWidth(vg, math.max(2, radius * 0.2))
    nvgStrokeColor(vg, nvgRGBA(200, 170, 100, 180))
    nvgStroke(vg)
    nvgRestore(vg)
end

-- 判断 NanoVG 图片是否已就绪（DWP 占位图尺寸极小）
function IsImageReady(handle)
    if not handle or handle < 0 then return false end
    local iw, ih = nvgImageSize(vg, handle)
    return iw > 4 and ih > 4
end

-- 绘制全屏背景图（带 DWP 占位 spinner）
function DrawBgImage(handle, W, H, imgW, imgH, offsetY)
    if not IsImageReady(handle) then
        DrawSpinner(W / 2, H / 2, 20)
        return
    end
    local bgScale = math.max(W / imgW, H / imgH)
    local drawW = imgW * bgScale
    local drawH = imgH * bgScale
    local oy = (offsetY or 0)
    local pat = nvgImagePattern(vg, (W - drawW) / 2, (H - drawH) / 2 + oy, drawW, drawH, 0, handle, 1.0)
    nvgBeginPath(vg); nvgRect(vg, 0, 0, W, H)
    nvgFillPaint(vg, pat); nvgFill(vg)
end

-- 统一菜单背景（与首页相同：背景图 + 遮罩 + 渐变）
function DrawMenuBg(W, H)
    DrawBgImage(IMG.menuBg, W, H, 768, 1376, -60)
    -- 轻微暗色覆盖 (国风二次元，保持明亮)
    nvgBeginPath(vg); nvgRect(vg, 0, 0, W, H)
    nvgFillColor(vg, nvgRGBA(8, 6, 15, 20)); nvgFill(vg)
    -- 底部轻微渐暗 (不遮挡底栏)
    local botGrad = nvgLinearGradient(vg, 0, H * 0.75, 0, H,
        nvgRGBA(0, 0, 0, 0), nvgRGBA(10, 8, 18, 50))
    nvgBeginPath(vg); nvgRect(vg, 0, H * 0.75, W, H * 0.25)
    nvgFillPaint(vg, botGrad); nvgFill(vg)
    -- 顶部轻微渐暗 (让标题可读)
    local topGrad = nvgLinearGradient(vg, 0, 0, 0, H * 0.10,
        nvgRGBA(10, 8, 18, 30), nvgRGBA(0, 0, 0, 0))
    nvgBeginPath(vg); nvgRect(vg, 0, 0, W, H * 0.10)
    nvgFillPaint(vg, topGrad); nvgFill(vg)
end

-- Toast 提示系统
function ShowToast(text, dur)
    toastState.text = text
    toastState.timer = dur or 2.0
    toastState.duration = dur or 2.0
end

function DrawToast(W, H)
    if toastState.timer <= 0 then return end
    local alpha = math.min(1.0, toastState.timer * 3.0) -- 淡出
    local a = math.floor(alpha * 220)
    local msg = toastState.text
    nvgSave(vg)
    nvgFontFaceId(vg, GetMainFont())
    nvgFontSize(vg, 18)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    local tw = nvgTextBounds(vg, 0, 0, msg, nil) + 30
    local th = 36
    local tx = W / 2 - tw / 2
    local ty = H * 0.38
    -- 背景
    nvgBeginPath(vg)
    nvgRoundedRect(vg, tx, ty, tw, th, 8)
    nvgFillColor(vg, nvgRGBA(20, 15, 30, a)); nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(180, 140, 80, math.floor(alpha * 150)))
    nvgStrokeWidth(vg, 1); nvgStroke(vg)
    -- 文字
    nvgFillColor(vg, nvgRGBA(255, 220, 150, a))
    nvgText(vg, W / 2, ty + th / 2, msg, nil)
    nvgRestore(vg)
end

--- 纯代码绘制等阶边框（向外延伸，不遮挡图标区域）
--- @param x number 图标区域左上角X（与DrawCardImage一致）
--- @param y number 图标区域左上角Y（与DrawCardImage一致）
--- @param iconW number 图标宽度
--- @param iconH number 图标高度
--- @param tier number 等阶1-6
--- @param radius number 圆角半径
function DrawEquipTierBg(x, y, iconW, iconH, tier, radius)
    if not tier or tier < 1 or tier > 6 then return end
    local rd = radius or 4
    local tc = EQUIP_TIERS[tier].color
    local ix = math.floor(x)
    local iy = math.floor(y)
    local cx = ix + iconW / 2
    local cy = iy + iconH / 2
    local bw = 2.0 + tier * 0.5  -- 边框宽度随品阶递增

    -- ① 外层辉光 (径向渐变, 高阶更浓烈)
    if tier >= 2 then
        local gp = bw + 2 + tier
        local glowInner = math.min(30 + tier * 12, 100)
        local gr = nvgRadialGradient(vg, cx, cy,
            math.min(iconW, iconH) * 0.3,
            math.max(iconW, iconH) * 0.5 + gp,
            nvgRGBA(tc[1], tc[2], tc[3], glowInner),
            nvgRGBA(tc[1], tc[2], tc[3], 0))
        nvgBeginPath(vg)
        nvgRoundedRect(vg, ix - gp, iy - gp, iconW + gp * 2, iconH + gp * 2, rd + 4)
        nvgFillPaint(vg, gr); nvgFill(vg)
    end

    -- ② 外边框 — 双层描边: 暗底 + 品阶色渐变
    local outerW = bw + 1.5
    -- 暗底层
    nvgBeginPath(vg)
    nvgRoundedRect(vg, ix - outerW, iy - outerW, iconW + outerW * 2, iconH + outerW * 2, rd + 2)
    nvgFillColor(vg, nvgRGBA(8, 6, 14, 240))
    nvgFill(vg)
    -- 品阶色渐变层 (上亮下暗)
    local r2 = math.min(tc[1] + 40, 255)
    local g2 = math.min(tc[2] + 40, 255)
    local b2 = math.min(tc[3] + 40, 255)
    local borderGrad = nvgLinearGradient(vg, ix, iy - bw, ix, iy + iconH + bw,
        nvgRGBA(r2, g2, b2, 240),
        nvgRGBA(math.floor(tc[1] * 0.5), math.floor(tc[2] * 0.5), math.floor(tc[3] * 0.5), 240))
    nvgBeginPath(vg)
    nvgRoundedRect(vg, ix - bw, iy - bw, iconW + bw * 2, iconH + bw * 2, rd + 1)
    nvgFillPaint(vg, borderGrad); nvgFill(vg)

    -- ③ 内底 (图标背景)
    nvgBeginPath(vg)
    nvgRoundedRect(vg, ix, iy, iconW, iconH, rd)
    nvgFillColor(vg, nvgRGBA(12, 14, 24, 235))
    nvgFill(vg)

    -- ④ 内侧高光描边 (上边+左边亮, 下边+右边暗 — 立体)
    nvgBeginPath(vg)
    nvgRoundedRect(vg, ix + 0.5, iy + 0.5, iconW - 1, iconH - 1, rd)
    local innerGrad = nvgLinearGradient(vg, ix, iy, ix, iy + iconH,
        nvgRGBA(255, 255, 255, 30 + tier * 12),
        nvgRGBA(0, 0, 0, 20 + tier * 5))
    nvgStrokeWidth(vg, 1.0)
    nvgStrokePaint(vg, innerGrad); nvgStroke(vg)

    -- ⑤ 四角菱形装饰 (将品以上)
    if tier >= 4 then
        local ds = 2.2 + (tier - 4) * 0.6  -- 菱形大小
        local cornerInset = rd + 1
        local cAlpha = 120 + (tier - 4) * 50
        local corners = {
            { ix + cornerInset,          iy + cornerInset },
            { ix + iconW - cornerInset,  iy + cornerInset },
            { ix + cornerInset,          iy + iconH - cornerInset },
            { ix + iconW - cornerInset,  iy + iconH - cornerInset },
        }
        for _, c in ipairs(corners) do
            nvgBeginPath(vg)
            nvgMoveTo(vg, c[1], c[2] - ds)
            nvgLineTo(vg, c[1] + ds, c[2])
            nvgLineTo(vg, c[1], c[2] + ds)
            nvgLineTo(vg, c[1] - ds, c[2])
            nvgClosePath(vg)
            nvgFillColor(vg, nvgRGBA(tc[1], tc[2], tc[3], cAlpha))
            nvgFill(vg)
        end
    end

    -- ⑥ 顶部高光条纹 (模拟金属反光)
    if tier >= 3 then
        nvgSave(vg)
        nvgScissor(vg, ix, iy, iconW, iconH * 0.35)
        local shineA = 15 + tier * 8
        local shineGrad = nvgLinearGradient(vg, ix, iy, ix, iy + iconH * 0.35,
            nvgRGBA(255, 255, 255, shineA), nvgRGBA(255, 255, 255, 0))
        nvgBeginPath(vg)
        nvgRoundedRect(vg, ix, iy, iconW, iconH * 0.35, rd)
        nvgFillPaint(vg, shineGrad); nvgFill(vg)
        nvgRestore(vg)
    end
end

function DrawCardImage(x, y, w, h, sheet, row, col, gridCols, gridRows)
    -- 图片未就绪时显示转圈
    if not sheet or sheet < 0 then
        nvgBeginPath(vg); nvgRoundedRect(vg, x, y, w, h, 3)
        nvgFillColor(vg, nvgRGBA(30, 25, 20, 120)); nvgFill(vg)
        DrawSpinner(x + w / 2, y + h / 2, math.min(w, h) * 0.2)
        return
    end
    -- DWP 占位检测：图片存在但尚未下载完成（尺寸为占位图 4x4）
    local imgW, imgH = nvgImageSize(vg, sheet)
    if imgW <= 4 or imgH <= 4 then
        nvgBeginPath(vg); nvgRoundedRect(vg, x, y, w, h, 3)
        nvgFillColor(vg, nvgRGBA(30, 25, 20, 120)); nvgFill(vg)
        DrawSpinner(x + w / 2, y + h / 2, math.min(w, h) * 0.2)
        return
    end
    local cols = gridCols or SHEET_COLS
    local rows = gridRows or SHEET_ROWS
    -- 根据实际图片尺寸计算每格宽高比, 避免拉伸
    local cellW = imgW / cols
    local cellH = imgH / rows
    local cellAspect = cellW / cellH   -- 图片格子的宽高比
    local drawAspect = w / h           -- 绘制区域的宽高比
    local fitW, fitH
    if cellAspect > drawAspect then
        -- 图片格子更宽: 以宽度为基准, 高度按比例缩放
        fitW = w
        fitH = w / cellAspect
    else
        -- 图片格子更高或相同: 以高度为基准
        fitH = h
        fitW = h * cellAspect
    end
    local fitX = x + (w - fitW) / 2
    local fitY = y + (h - fitH) / 2
    local totalW = fitW * cols
    local totalH = fitH * rows
    local ox = fitX - col * fitW
    local oy = fitY - row * fitH
    nvgSave(vg)
    nvgIntersectScissor(vg, x, y, w, h)
    local p = nvgImagePattern(vg, ox, oy, totalW, totalH, 0, sheet, 1.0)
    nvgBeginPath(vg); nvgRoundedRect(vg, x, y, w, h, 3)
    nvgFillPaint(vg, p); nvgFill(vg)
    nvgRestore(vg)
end

-- ============================================================================
-- 战斗单位渲染
-- ============================================================================

function DrawBattleUnits()
    -- 战区分割线 (淡墨)
    nvgBeginPath(vg)
    local lineGrad = nvgLinearGradient(vg, BATTLE_ZONE.left + 30, BATTLE_ZONE.centerY,
        BATTLE_ZONE.right - 30, BATTLE_ZONE.centerY,
        nvgRGBA(200, 160, 80, 0), nvgRGBA(200, 160, 80, 30))
    nvgMoveTo(vg, BATTLE_ZONE.left + 30, BATTLE_ZONE.centerY)
    nvgLineTo(vg, BATTLE_ZONE.right - 30, BATTLE_ZONE.centerY)
    nvgStrokePaint(vg, lineGrad)
    nvgStrokeWidth(vg, 1); nvgStroke(vg)

    -- 云 (底层)
    for _, u in ipairs(playerUnits) do if u.alive then DrawUnitCloud(u) end end
    for _, u in ipairs(enemyUnits) do if u.alive then DrawUnitCloud(u) end end
    -- 角色 (上层)
    for _, u in ipairs(playerUnits) do if u.alive then DrawUnitSprite(u) end end
    for _, u in ipairs(enemyUnits) do if u.alive then DrawUnitSprite(u) end end
end

function DrawUnitCloud(u)
    local t = gameState.gameTime + u.cloudSeed
    local bob = math.sin(u.animTimer) * 2.0
    local px, py = u.x, u.y + bob
    local cImg = (math.floor(u.cloudSeed * 10) % 2 == 0) and IMG.cloudA or IMG.cloudB
    if not cImg or cImg <= 0 then return end

    local cloudW = 46 + math.sin(t * 1.5) * 5
    local cloudH = cloudW * 0.5
    local cloudX = px - cloudW / 2 + math.sin(t * 0.8) * 2
    local cloudY = py + 5 - math.sin(t * 1.2) * 1
    local alpha = 0.5 + 0.2 * math.sin(t * 2)

    nvgSave(vg); nvgGlobalAlpha(vg, alpha)
    local imgPat = nvgImagePattern(vg, cloudX, cloudY, cloudW, cloudH, 0, cImg, 1.0)
    nvgBeginPath(vg)
    nvgEllipse(vg, cloudX + cloudW / 2, cloudY + cloudH / 2, cloudW / 2, cloudH / 2)
    nvgFillPaint(vg, imgPat); nvgFill(vg)
    nvgRestore(vg)
end

function DrawUnitSprite(u)
    local uc = u.unitClass
    local spriteImg = IMG.unitSprites[uc and uc.sprite or "sword"]
    local uScale = uc and uc.unitScale or 1.0
    local sz = 38 * uScale
    local bob = math.sin(u.animTimer) * 2.5
    local px, py = u.x, u.y + bob

    -- === 序列帧动画：行走摇摆 + 攻击放大 + 受伤抖动 ===
    local animAngle = 0       -- 旋转角度(弧度)
    local animScaleX = 1.0    -- X缩放
    local animScaleY = 1.0    -- Y缩放
    local shakeX, shakeY = 0, 0  -- 抖动偏移

    -- 行走摇摆动画：左右轻微倾斜模拟跑步
    local walkCycle = math.sin(u.animTimer * 4)
    animAngle = walkCycle * 0.12  -- ±7度摇摆
    -- 模拟脚步弹跳
    local stepBounce = math.abs(math.sin(u.animTimer * 4))
    animScaleY = 1.0 + stepBounce * 0.06  -- 轻微纵向拉伸
    animScaleX = 1.0 - stepBounce * 0.03  -- 对应横向压缩

    -- 攻击动画：攻击瞬间短暂放大+前倾
    if u.atkAnimTimer and u.atkAnimTimer > 0 then
        local atkT = u.atkAnimTimer
        local atkPulse = math.sin(atkT * 12) * math.max(0, 1 - atkT * 3)
        animScaleX = animScaleX + atkPulse * 0.2
        animScaleY = animScaleY + atkPulse * 0.15
        -- 攻击前倾
        local leanDir = u.isPlayer and -1 or 1
        animAngle = animAngle + leanDir * math.max(0, 0.3 - atkT) * 0.5
    end

    -- 受伤抖动
    if u.flashTimer > 0 then
        shakeX = math.sin(u.flashTimer * 60) * 2
        shakeY = math.cos(u.flashTimer * 45) * 1
    end

    local drawX = px + shakeX
    local drawY = py + shakeY

    if spriteImg and spriteImg > 0 then
        local alpha = 1.0
        if u.flashTimer > 0 then alpha = 0.4 + 0.6 * math.sin(u.flashTimer * 40) end
        if u.stealthing then alpha = alpha * 0.45 end
        nvgSave(vg); nvgGlobalAlpha(vg, alpha)
        -- 应用旋转和缩放变换
        nvgTranslate(vg, drawX, drawY)
        nvgRotate(vg, animAngle)
        nvgScale(vg, animScaleX, animScaleY)
        local halfSz = sz / 2
        local imgPat = nvgImagePattern(vg, -halfSz, -halfSz, sz, sz, 0, spriteImg, 1.0)
        nvgBeginPath(vg); nvgRect(vg, -halfSz, -halfSz, sz, sz)
        nvgFillPaint(vg, imgPat); nvgFill(vg)
        nvgRestore(vg)
    else
        -- 无精灵图时用彩色圆圈 + 兵种标记
        local ucId = uc and uc.id or 1
        local r = sz * 0.4
        local alpha = u.stealthing and 120 or 200
        nvgSave(vg)
        nvgTranslate(vg, drawX, drawY)
        nvgRotate(vg, animAngle)
        nvgScale(vg, animScaleX, animScaleY)
        nvgBeginPath(vg); nvgCircle(vg, 0, 0, r)
        if ucId == 9 then
            nvgFillColor(vg, u.isPlayer and nvgRGBA(255, 160, 50, alpha) or nvgRGBA(200, 60, 60, alpha))
        elseif ucId == 10 then
            nvgFillColor(vg, u.isPlayer and nvgRGBA(180, 100, 255, alpha) or nvgRGBA(200, 60, 60, alpha))
        elseif ucId == 11 then
            nvgFillColor(vg, u.isPlayer and nvgRGBA(160, 60, 120, alpha) or nvgRGBA(200, 60, 60, alpha))
        elseif ucId == 12 then
            nvgFillColor(vg, u.isPlayer and nvgRGBA(60, 200, 180, alpha) or nvgRGBA(200, 60, 60, alpha))
        elseif ucId == 13 then
            nvgFillColor(vg, u.isPlayer and nvgRGBA(255, 200, 50, alpha) or nvgRGBA(200, 60, 60, alpha))
        elseif ucId == 14 then
            nvgFillColor(vg, u.isPlayer and nvgRGBA(160, 80, 200, alpha) or nvgRGBA(200, 60, 60, alpha))
        elseif ucId == 15 then
            nvgFillColor(vg, u.isPlayer and nvgRGBA(80, 200, 255, alpha) or nvgRGBA(200, 60, 60, alpha))
        elseif ucId == 16 then
            nvgFillColor(vg, u.isPlayer and nvgRGBA(240, 180, 40, alpha) or nvgRGBA(200, 60, 60, alpha))
        else
            nvgFillColor(vg, u.isPlayer and nvgRGBA(100, 180, 255, alpha) or nvgRGBA(200, 60, 60, alpha))
        end
        nvgFill(vg)
        -- 兵种首字标记
        if uc and uc.name then
            nvgFontSize(vg, sz * 0.45)
            nvgFontFace(vg, "sans")
            nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
            DrawWhiteInkText(0, 0, string.sub(uc.name, 1, 3))
        end
        nvgRestore(vg)
    end

    -- 噩梦骑兵冲锋拖尾特效
    if uc and uc.id == 9 then
        local trailAlpha = math.floor(80 + 40 * math.sin(u.animTimer * 2))
        nvgBeginPath(vg)
        nvgMoveTo(vg, px - sz * 0.3, py + sz * 0.5)
        nvgLineTo(vg, px, py + sz * 0.9)
        nvgLineTo(vg, px + sz * 0.3, py + sz * 0.5)
        nvgFillColor(vg, u.isPlayer and nvgRGBA(255, 200, 80, trailAlpha) or nvgRGBA(200, 80, 80, trailAlpha))
        nvgFill(vg)
    end

    -- 讨伐巨兽光环特效
    if uc and uc.id == 10 then
        nvgBeginPath(vg); nvgCircle(vg, px, py, sz * 0.55)
        nvgStrokeColor(vg, u.isPlayer and nvgRGBA(180, 100, 255, 60) or nvgRGBA(200, 60, 60, 60))
        nvgStrokeWidth(vg, 2); nvgStroke(vg)
    end

    -- 腐灵祭司攻速光环标记（绿色小箭头）
    if u.healerAura then
        nvgBeginPath(vg)
        nvgMoveTo(vg, px - 4, py - sz * 0.5 - 2)
        nvgLineTo(vg, px, py - sz * 0.5 - 7)
        nvgLineTo(vg, px + 4, py - sz * 0.5 - 2)
        nvgFillColor(vg, nvgRGBA(80, 255, 120, 160)); nvgFill(vg)
        u.healerAura = false  -- 每帧重置
    end

    -- 自爆亡魂脉冲特效
    if uc and uc.id == 13 then
        local pulse = 0.5 + 0.5 * math.sin(u.animTimer * 6)
        local pulseA = math.floor(40 + 60 * pulse)
        nvgBeginPath(vg); nvgCircle(vg, px, py, sz * (0.45 + 0.15 * pulse))
        nvgFillColor(vg, nvgRGBA(255, 200, 50, pulseA)); nvgFill(vg)
    end

    -- 傀儡操师操控丝线特效
    if uc and uc.id == 14 and not u.isPuppet then
        nvgStrokeColor(vg, nvgRGBA(180, 100, 255, 80))
        nvgStrokeWidth(vg, 1)
        nvgBeginPath(vg)
        nvgMoveTo(vg, px - sz * 0.3, py - sz * 0.4)
        nvgLineTo(vg, px - sz * 0.5, py - sz * 0.9)
        nvgMoveTo(vg, px + sz * 0.3, py - sz * 0.4)
        nvgLineTo(vg, px + sz * 0.5, py - sz * 0.9)
        nvgStroke(vg)
    end

    -- 霜骨冰巫霜冻光环
    if uc and uc.id == 15 then
        nvgBeginPath(vg); nvgCircle(vg, px, py, sz * 0.6)
        nvgStrokeColor(vg, nvgRGBA(100, 220, 255, 60 + math.floor(30 * math.sin(u.animTimer * 3))))
        nvgStrokeWidth(vg, 2); nvgStroke(vg)
    end

    -- 腐蝇虫群震动偏移（小型抖动）
    if uc and (uc.id == 16 or u.isSwarmling) then
        -- 额外小蜂翅膀闪烁
        local wingA = math.floor(80 + 60 * math.sin(u.animTimer * 12))
        nvgBeginPath(vg)
        nvgEllipse(vg, px - sz * 0.25, py - sz * 0.15, sz * 0.12, sz * 0.08)
        nvgEllipse(vg, px + sz * 0.25, py - sz * 0.15, sz * 0.12, sz * 0.08)
        nvgFillColor(vg, nvgRGBA(255, 240, 200, wingA)); nvgFill(vg)
    end

    -- 区域减速冰冻标记
    if u.isZoneSlowed then
        nvgBeginPath(vg); nvgCircle(vg, px, py, sz * 0.55)
        nvgFillColor(vg, nvgRGBA(100, 200, 255, 50)); nvgFill(vg)
        nvgStrokeColor(vg, nvgRGBA(120, 210, 255, 120))
        nvgStrokeWidth(vg, 1.5); nvgStroke(vg)
    end

    DrawHP(px, py - sz / 2 - 5, sz * 0.8, 3.0 * uScale, u.hp / u.maxHp, u.isPlayer)
end

function DrawHP(cx, cy, w, h, ratio, isP)
    local x = cx - w / 2
    nvgBeginPath(vg); nvgRoundedRect(vg, x, cy, w, h, 1)
    nvgFillColor(vg, nvgRGBA(5, 5, 12, 120)); nvgFill(vg)
    local fw = w * math.max(0, math.min(1, ratio))
    if fw > 0 then
        nvgBeginPath(vg); nvgRoundedRect(vg, x, cy, fw, h, 1)
        nvgFillColor(vg, isP and nvgRGBA(60, 210, 100, 230) or nvgRGBA(210, 50, 50, 230))
        nvgFill(vg)
    end
end

-- ============================================================================
-- 粒子渲染 (设计坐标)
-- ============================================================================

function DrawParticles()
    for _, p in ipairs(particles) do
        if p.isDesign then
            local alpha = math.floor(255 * (1 - p.timer / p.life))
            local sz = p.size * (1 - p.timer / p.life * 0.5)
            nvgBeginPath(vg); nvgCircle(vg, p.x, p.y, sz)
            nvgFillColor(vg, nvgRGBA(p.color[1], p.color[2], p.color[3], alpha))
            nvgFill(vg)
        end
    end
end

--- 更新并绘制远程弹道特效
function UpdateAndDrawProjectiles(dt)
    local i = 1
    while i <= #projectiles do
        local p = projectiles[i]
        p.timer = p.timer + dt
        if p.timer >= p.maxTime then
            table.remove(projectiles, i)
        else
            -- 线性插值当前位置
            local t = p.timer / p.maxTime
            local cx = p.sx + (p.tx - p.sx) * t
            local cy = p.sy + (p.ty - p.sy) * t
            local c = p.color
            -- 弹道头部光点
            nvgBeginPath(vg); nvgCircle(vg, cx, cy, 3)
            nvgFillColor(vg, nvgRGBA(c[1], c[2], c[3], 240)); nvgFill(vg)
            -- 弹道尾迹线
            local tailT = math.max(0, t - 0.4)
            local tailX = p.sx + (p.tx - p.sx) * tailT
            local tailY = p.sy + (p.ty - p.sy) * tailT
            nvgBeginPath(vg)
            nvgMoveTo(vg, tailX, tailY)
            nvgLineTo(vg, cx, cy)
            nvgStrokeColor(vg, nvgRGBA(c[1], c[2], c[3], math.floor(160 * (1 - t))))
            nvgStrokeWidth(vg, 2); nvgStroke(vg)
            -- 外发光
            nvgBeginPath(vg); nvgCircle(vg, cx, cy, 6)
            nvgFillColor(vg, nvgRGBA(c[1], c[2], c[3], 40)); nvgFill(vg)
            i = i + 1
        end
    end
end

-- ============================================================================
-- HUD (暗黑地牢风)
-- ============================================================================

function DrawHUD()
    if fontId < 0 then return end

    -- 应用HUD偏移量
    local hOfsX = gameSettings.hudOffsetX or 0
    local hOfsY = gameSettings.hudOffsetY or 0

    -- ======== 精简顶部信息条 (军资/击杀/兵力) ========
    local hudH = 22
    local hudBg = nvgLinearGradient(vg, 0, 2 + hOfsY, 0, hudH + 2 + hOfsY,
        nvgRGBA(30, 25, 16, 190), nvgRGBA(20, 16, 10, 200))
    nvgBeginPath(vg); nvgRoundedRect(vg, 4 + hOfsX, 2 + hOfsY, DESIGN_W - 8, hudH, 4)
    nvgFillPaint(vg, hudBg); nvgFill(vg)

    -- 装饰线
    local topLine = nvgLinearGradient(vg, 60 + hOfsX, 3 + hOfsY, DESIGN_W - 60 + hOfsX, 3 + hOfsY,
        nvgRGBA(200, 165, 80, 0), nvgRGBA(200, 165, 80, 50))
    nvgBeginPath(vg)
    nvgMoveTo(vg, 60 + hOfsX, 3 + hOfsY); nvgLineTo(vg, DESIGN_W - 60 + hOfsX, 3 + hOfsY)
    nvgStrokePaint(vg, topLine); nvgStrokeWidth(vg, 0.6); nvgStroke(vg)

    nvgFontFaceId(vg, GetMainFont())
    local midY = 13 + hOfsY

    -- 军资
    nvgFontSize(vg, 20)
    nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(16 + hOfsX, midY, "军资")
    nvgFontSize(vg, 22)
    DrawWhiteInkText(50 + hOfsX, midY, tostring(gameState.gold))

    -- 击杀
    nvgFontSize(vg, 20)
    DrawWhiteInkText(120 + hOfsX, midY, "斩")
    nvgFontSize(vg, 22)
    DrawWhiteInkText(140 + hOfsX, midY, tostring(gameState.totalKills))

    -- 兵力 (右侧)
    nvgFontSize(vg, 16)
    nvgTextAlign(vg, NVG_ALIGN_RIGHT + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(DESIGN_W - 12 + hOfsX, midY, "我:" .. #playerUnits .. " 敌:" .. #enemyUnits)

    -- ======== FIGHT 阶段倒计时 (正上方居中) ========
    if gameState.battlePhase == "FIGHT" then
        local t = gameState.gameTime
        local remainSec
        local isDummyBattle = gameState.isDummy
        if isDummyBattle then
            remainSec = math.max(0, math.ceil(dummyState.timer))
        else
            remainSec = math.max(0, math.ceil(BATTLE_TIME_LIMIT - gameState.battleTime))
        end

        local timerStr
        if isDummyBattle and dummyState.prepPhase then
            timerStr = "准备中"
        elseif isDummyBattle then
            timerStr = string.format("%ds", remainSec)
        else
            timerStr = string.format("%d:%02d", math.floor(remainSec / 60), remainSec % 60)
        end

        -- 倒计时背景胶囊
        local timerW = 72
        local timerH = 20
        local timerX = DESIGN_W / 2 - timerW / 2 + hOfsX
        local timerY = hudH + 4 + hOfsY
        nvgBeginPath(vg); nvgRoundedRect(vg, timerX, timerY, timerW, timerH, 10)
        if (isDummyBattle and not dummyState.prepPhase) or remainSec <= 30 then
            local urgPulse = 0.6 + 0.4 * math.sin(t * 6)
            nvgFillColor(vg, nvgRGBA(40, 8, 8, math.floor(180 * urgPulse))); nvgFill(vg)
            nvgStrokeColor(vg, nvgRGBA(255, 80, 60, math.floor(160 * urgPulse))); nvgStrokeWidth(vg, 0.8); nvgStroke(vg)
        else
            nvgFillColor(vg, nvgRGBA(12, 10, 6, 180)); nvgFill(vg)
            nvgStrokeColor(vg, nvgRGBA(90, 45, 55, 80)); nvgStrokeWidth(vg, 0.5); nvgStroke(vg)
        end

        nvgFontSize(vg, 16)
        nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        DrawWhiteInkText(DESIGN_W / 2 + hOfsX, timerY + timerH / 2, timerStr)
    end
end

-- ============================================================================
-- 基地血条 (贴在临界线旁边, 战场内显示)
-- ============================================================================

function DrawBaseHPBars()
    if fontId < 0 then return end

    local bz = BATTLE_ZONE
    local barW = 200
    local barH = 7
    local centerX = DESIGN_W / 2

    nvgFontFaceId(vg, GetMainFont())

    -- ======== 敌方基地血条 (临界线下方) ========
    local eBarY = bz.enemyLine + 16
    local eBarX = centerX - barW / 2

    -- 半透明底板
    nvgBeginPath(vg); nvgRoundedRect(vg, eBarX - 28, eBarY - 8, barW + 56, 16, 4)
    nvgFillColor(vg, nvgRGBA(15, 8, 5, 160)); nvgFill(vg)

    -- 标签
    nvgFontSize(vg, 20)
    nvgTextAlign(vg, NVG_ALIGN_RIGHT + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(eBarX - 6, eBarY, "敌")

    -- 血量条背景
    nvgBeginPath(vg); nvgRoundedRect(vg, eBarX, eBarY - barH / 2, barW, barH, 3)
    nvgFillColor(vg, nvgRGBA(40, 15, 10, 200)); nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(160, 80, 60, 50))
    nvgStrokeWidth(vg, 0.4); nvgStroke(vg)

    -- 血量条填充
    local eMax = gameState.enemyBaseMax or BASE_HP_MAX
    local eRatio = math.max(0, gameState.enemyBaseHP / eMax)
    if eRatio > 0 then
        local fillW = barW * eRatio
        local eGrad = nvgLinearGradient(vg, eBarX, eBarY, eBarX + fillW, eBarY,
            nvgRGBA(180, 40, 25, 220), nvgRGBA(255, 90, 50, 240))
        nvgBeginPath(vg); nvgRoundedRect(vg, eBarX, eBarY - barH / 2, fillW, barH, 3)
        nvgFillPaint(vg, eGrad); nvgFill(vg)
        -- 高光
        nvgBeginPath(vg); nvgRoundedRect(vg, eBarX, eBarY - barH / 2, fillW, barH * 0.35, 2)
        nvgFillColor(vg, nvgRGBA(255, 200, 180, 30)); nvgFill(vg)
    end

    -- 血量数字
    nvgFontSize(vg, 16)
    nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(eBarX + barW + 6, eBarY, gameState.enemyBaseHP .. "/" .. eMax)

    -- ======== 玩家基地血条 (临界线下方) ========
    local pBarY = bz.playerLine + 16
    local pBarX = centerX - barW / 2

    -- 半透明底板
    nvgBeginPath(vg); nvgRoundedRect(vg, pBarX - 28, pBarY - 8, barW + 56, 16, 4)
    nvgFillColor(vg, nvgRGBA(5, 10, 15, 160)); nvgFill(vg)

    -- 标签
    nvgFontSize(vg, 20)
    nvgTextAlign(vg, NVG_ALIGN_RIGHT + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(pBarX - 6, pBarY, "我")

    -- 血量条背景
    nvgBeginPath(vg); nvgRoundedRect(vg, pBarX, pBarY - barH / 2, barW, barH, 3)
    nvgFillColor(vg, nvgRGBA(10, 20, 35, 200)); nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(60, 130, 170, 50))
    nvgStrokeWidth(vg, 0.4); nvgStroke(vg)

    -- 血量条填充
    local pMax = gameState.playerBaseMax or BASE_HP_MAX
    local pRatio = math.max(0, gameState.playerBaseHP / pMax)
    if pRatio > 0 then
        local fillW = barW * pRatio
        local pGrad = nvgLinearGradient(vg, pBarX, pBarY, pBarX + fillW, pBarY,
            nvgRGBA(35, 150, 190, 220), nvgRGBA(70, 220, 180, 240))
        nvgBeginPath(vg); nvgRoundedRect(vg, pBarX, pBarY - barH / 2, fillW, barH, 3)
        nvgFillPaint(vg, pGrad); nvgFill(vg)
        -- 高光
        nvgBeginPath(vg); nvgRoundedRect(vg, pBarX, pBarY - barH / 2, fillW, barH * 0.35, 2)
        nvgFillColor(vg, nvgRGBA(200, 255, 255, 30)); nvgFill(vg)
    end

    -- 血量数字
    nvgFontSize(vg, 16)
    nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(pBarX + barW + 6, pBarY, gameState.playerBaseHP .. "/" .. pMax)

    -- ======== 血量低警告 ========
    local warningThreshold = math.floor((gameState.playerBaseMax or BASE_HP_MAX) * 0.15)
    if gameState.playerBaseHP <= warningThreshold and gameState.phase == "BATTLE" then
        local pulse = 0.5 + 0.5 * math.sin(gameState.gameTime * 6)
        -- 玩家血条闪红边框
        nvgBeginPath(vg); nvgRoundedRect(vg, pBarX - 1, pBarY - barH / 2 - 1, barW + 2, barH + 2, 4)
        nvgStrokeColor(vg, nvgRGBA(255, 60, 40, math.floor(80 + 120 * pulse)))
        nvgStrokeWidth(vg, 1.2); nvgStroke(vg)
    end
end

-- ============================================================================
-- 战斗按钮 (右侧垂直排列, 设计坐标)
-- ============================================================================

function DrawBattleButtons()
    if fontId < 0 then return end

    local isSHOP = (gameState.battlePhase == "SHOP")
    local t = gameState.gameTime

    nvgFontFaceId(vg, GetMainFont())

    -- 右侧按钮参数 (放大以适配手机操作)
    local btnW = 72
    local btnH = 30
    local btnGap = 6
    local rightMargin = 4  -- 距离设计区右边缘

    -- 应用右上角按钮组偏移量
    local rbOfsX = gameSettings.rightBtnOffsetX or 0
    local rbOfsY = gameSettings.rightBtnOffsetY or 0

    -- 所有按钮从上到下排列，基准Y=136避免被TapTap右上角按钮遮挡
    local startY = 136 + rbOfsY
    local bx = DESIGN_W - btnW - rightMargin + rbOfsX
    local curY = startY

    -- 半透明背景条（仅在有按钮时绘制）
    local btnList = {}

    if isSHOP then
        -- SHOP阶段按钮
        -- 1. 开战按钮
        nvgBeginPath(vg); nvgRoundedRect(vg, bx, curY, btnW, btnH, 4)
        nvgFillColor(vg, nvgRGBA(25, 22, 18, 200)); nvgFill(vg)
        nvgBeginPath(vg); nvgRoundedRect(vg, bx, curY, btnW, btnH, 4)
        nvgStrokeWidth(vg, 1.0)
        nvgStrokeColor(vg, nvgRGBA(120, 110, 100, 130)); nvgStroke(vg)
        nvgFontSize(vg, 17)
        nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        local fightLabel = (gameState.isDummy and dummyState.prepPhase) and "开始挑战" or "开战"
        DrawWhiteInkText(bx + btnW / 2, curY + btnH / 2, fightLabel)
        shopFightBtnRect = { x = bx, y = curY, w = btnW, h = btnH, isDesign = true }
        curY = curY + btnH + btnGap

        -- 换战场按钮 (打桩准备阶段 或 非讨伐普通战斗SHOP阶段)
        if gameState.isDummy and dummyState.prepPhase then
            nvgBeginPath(vg); nvgRoundedRect(vg, bx, curY, btnW, btnH, 3)
            nvgFillColor(vg, nvgRGBA(25, 22, 18, 190)); nvgFill(vg)
            nvgStrokeColor(vg, nvgRGBA(120, 110, 100, 120)); nvgStrokeWidth(vg, 0.8); nvgStroke(vg)
            nvgFontSize(vg, 15)
            nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
            DrawWhiteInkText(bx + btnW / 2, curY + btnH / 2, "换战场")
            dummyState.changeBgBtnRect = { x = bx, y = curY, w = btnW, h = btnH, isDesign = true }
            curY = curY + btnH + btnGap

            -- 战场编号提示
            nvgFontSize(vg, 11)
            nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_TOP)
            DrawWhiteInkText(bx + btnW / 2, curY - btnGap + 2, gameState.abyssFloor .. "/7")
            battleChangeBgBtnRect = nil
        elseif not gameState.abyssFloor and not gameState.towerFloor and not gameState.isRanked and not gameState.isDummy then
            -- 普通战斗换战场按钮
            nvgBeginPath(vg); nvgRoundedRect(vg, bx, curY, btnW, btnH, 3)
            nvgFillColor(vg, nvgRGBA(25, 22, 18, 190)); nvgFill(vg)
            nvgStrokeColor(vg, nvgRGBA(120, 110, 100, 120)); nvgStrokeWidth(vg, 0.8); nvgStroke(vg)
            nvgFontSize(vg, 15)
            nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
            DrawWhiteInkText(bx + btnW / 2, curY + btnH / 2, "换战场")
            battleChangeBgBtnRect = { x = bx, y = curY, w = btnW, h = btnH, isDesign = true }
            curY = curY + btnH + btnGap

            -- 战场名称提示
            nvgFontSize(vg, 11)
            nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_TOP)
            local layoutName = BATTLE_LAYOUTS[currentLayoutIdx] and BATTLE_LAYOUTS[currentLayoutIdx].name or "默认"
            DrawWhiteInkText(bx + btnW / 2, curY - btnGap + 2, layoutName)
            dummyState.changeBgBtnRect = nil
        else
            dummyState.changeBgBtnRect = nil
            battleChangeBgBtnRect = nil
        end

        -- 1.5 战力对比条 (SHOP阶段)
        do
            local myPow = CalcPlayerTotalPower()
            local enPow = CalcEnemyTotalPower(ENEMY_SLOTS, 1.0)  -- 敌方属性已在InitBattle中缩放
            local ratio = (enPow > 0) and (myPow / enPow) or 99.0
            local gTxt, gClr = GetPowerGrade(ratio)
            nvgBeginPath(vg); nvgRoundedRect(vg, bx, curY, btnW, btnH, 3)
            nvgFillColor(vg, nvgRGBA(25, 22, 18, 190)); nvgFill(vg)
            nvgStrokeColor(vg, nvgRGBA(120, 110, 100, 120)); nvgStrokeWidth(vg, 0.8); nvgStroke(vg)
            nvgFontSize(vg, 12); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_TOP)
            DrawWhiteInkText(bx + btnW / 2, curY + 2, gTxt)
            nvgFontSize(vg, 11)
            DrawWhiteInkText(bx + btnW / 2, curY + 14, FormatPower(myPow) .. "/" .. FormatPower(enPow))
            curY = curY + btnH + btnGap
        end

        -- 2. 军资显示 (打桩准备阶段隐藏商店)
        nvgBeginPath(vg); nvgRoundedRect(vg, bx, curY, btnW, btnH, 3)
        nvgFillColor(vg, nvgRGBA(12, 10, 6, 180)); nvgFill(vg)
        nvgStrokeColor(vg, nvgRGBA(100, 180, 220, 80)); nvgStrokeWidth(vg, 0.6); nvgStroke(vg)
        nvgFontSize(vg, 12)
        nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_TOP)
        DrawWhiteInkText(bx + btnW / 2, curY + 2, "军资")
        nvgFontSize(vg, 15)
        DrawWhiteInkText(bx + btnW / 2, curY + 11, tostring(gameState.gold))
        curY = curY + btnH + btnGap

        -- 3. 刷新按钮
        local canRefresh = gameState.gold >= GameConfig.REFRESH_COST
        local rAlpha = canRefresh and 200 or 80
        nvgBeginPath(vg); nvgRoundedRect(vg, bx, curY, btnW, btnH, 3)
        nvgFillColor(vg, nvgRGBA(20, 35, 50, rAlpha)); nvgFill(vg)
        nvgStrokeColor(vg, nvgRGBA(100, 180, 220, rAlpha)); nvgStrokeWidth(vg, 0.6); nvgStroke(vg)
        nvgFontSize(vg, 13)
        nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        DrawWhiteInkText(bx + btnW / 2, curY + btnH / 2, "刷新")
        shopRefreshBtnRect = { x = bx, y = curY, w = btnW, h = btnH, isDesign = true }
        curY = curY + btnH + btnGap

        -- 4. 自动战斗按钮 (SHOP阶段也可切换, 教程中隐藏)
        if not tutorialState.active then
            local isAuto = gameState.autoBattle
            local blocked = gameState.noFullAuto  -- 副本模式禁用全自动
            local autoPulse = isAuto and (0.7 + 0.3 * math.sin(t * 4)) or 1.0
            nvgBeginPath(vg); nvgRoundedRect(vg, bx, curY, btnW, btnH, 3)
            if blocked then
                nvgFillColor(vg, nvgRGBA(40, 35, 35, 160)); nvgFill(vg)
                nvgStrokeColor(vg, nvgRGBA(80, 70, 60, 100))
            elseif isAuto then
                nvgFillColor(vg, nvgRGBA(15, 50, 30, math.floor(220 * autoPulse))); nvgFill(vg)
                nvgStrokeColor(vg, nvgRGBA(80, 255, 140, math.floor(180 * autoPulse)))
            else
                nvgFillColor(vg, nvgRGBA(25, 22, 18, 190)); nvgFill(vg)
                nvgStrokeColor(vg, nvgRGBA(120, 110, 100, 120))
            end
            nvgStrokeWidth(vg, 0.8); nvgStroke(vg)
            nvgFontSize(vg, 12)
            nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
            local autoLabel = blocked and "禁用" or (isAuto and "自动 ON" or "自动 OFF")
            DrawWhiteInkText(bx + btnW / 2, curY + btnH / 2, autoLabel)
            autoBattleBtnRect = { x = bx, y = curY, w = btnW, h = btnH, isDesign = true }
            curY = curY + btnH + btnGap
        end

        -- 7. 退出按钮 (教程战斗阶段step>=8也显示)
        if not tutorialState.active or tutorialState.step >= 8 then
            nvgBeginPath(vg); nvgRoundedRect(vg, bx, curY, btnW, btnH, 3)
            nvgFillColor(vg, nvgRGBA(60, 20, 20, 160)); nvgFill(vg)
            nvgStrokeColor(vg, nvgRGBA(180, 100, 80, 120)); nvgStrokeWidth(vg, 0.6); nvgStroke(vg)
            nvgFontSize(vg, 13)
            nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
            DrawWhiteInkText(bx + btnW / 2, curY + btnH / 2, "退出")
            battleBackBtnRect = { x = bx, y = curY, w = btnW, h = btnH, isDesign = true }
        else
            battleBackBtnRect = nil
        end
        battleSpeedBtnRect = nil  -- SHOP阶段无倍速按钮
        autoMarchBtnRect = nil  -- SHOP阶段无自动行军按钮

        -- 新手提示: 点击卡牌可查看武灵详情 (前3场战斗显示)
        if (gameSettings.battleCount or 0) < 3 and not tutorialState.active then
            local hintAlpha = math.floor(140 + 60 * math.sin(t * 3.0))
            nvgFontSize(vg, 11)
            nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_TOP)
            nvgFillColor(vg, nvgRGBA(200, 180, 120, hintAlpha))
            nvgText(vg, bx + btnW / 2, curY + btnH + 8, "提示:点击卡牌", nil)
            nvgText(vg, bx + btnW / 2, curY + btnH + 21, "可查看武灵详情", nil)
        end
    else
        -- FIGHT阶段：精简显示

        -- 换战场按钮 (教程战斗时保留，防止按钮位移导致点击错位)
        if tutorialState.active and not gameState.abyssFloor and not gameState.towerFloor and not gameState.isRanked and not gameState.isDummy then
            nvgBeginPath(vg); nvgRoundedRect(vg, bx, curY, btnW, btnH, 3)
            nvgFillColor(vg, nvgRGBA(25, 22, 18, 190)); nvgFill(vg)
            nvgStrokeColor(vg, nvgRGBA(120, 110, 100, 120)); nvgStrokeWidth(vg, 0.8); nvgStroke(vg)
            nvgFontSize(vg, 15)
            nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
            DrawWhiteInkText(bx + btnW / 2, curY + btnH / 2, "换战场")
            battleChangeBgBtnRect = { x = bx, y = curY, w = btnW, h = btnH, isDesign = true }
            curY = curY + btnH + btnGap

            -- 战场名称提示
            nvgFontSize(vg, 11)
            nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_TOP)
            local layoutName = BATTLE_LAYOUTS[currentLayoutIdx] and BATTLE_LAYOUTS[currentLayoutIdx].name or "默认"
            DrawWhiteInkText(bx + btnW / 2, curY - btnGap + 2, layoutName)
        else
            battleChangeBgBtnRect = nil
        end

        -- 1. 军资+倒计时
        nvgBeginPath(vg); nvgRoundedRect(vg, bx, curY, btnW, btnH, 3)
        nvgFillColor(vg, nvgRGBA(12, 10, 6, 180)); nvgFill(vg)
        nvgStrokeColor(vg, nvgRGBA(100, 180, 220, 80)); nvgStrokeWidth(vg, 0.6); nvgStroke(vg)
        nvgFontSize(vg, 12)
        nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_TOP)
        DrawWhiteInkText(bx + btnW / 2, curY + 2, "军资")
        nvgFontSize(vg, 15)
        DrawWhiteInkText(bx + btnW / 2, curY + 11, tostring(gameState.gold))
        curY = curY + btnH + btnGap

        -- 2. 刷新按钮 (战斗中也可刷新商店换阵)
        local canRefreshF = gameState.gold >= GameConfig.REFRESH_COST
        local rAlphaF = canRefreshF and 200 or 80
        nvgBeginPath(vg); nvgRoundedRect(vg, bx, curY, btnW, btnH, 3)
        nvgFillColor(vg, nvgRGBA(20, 35, 50, rAlphaF)); nvgFill(vg)
        nvgStrokeColor(vg, nvgRGBA(100, 180, 220, rAlphaF)); nvgStrokeWidth(vg, 0.6); nvgStroke(vg)
        nvgFontSize(vg, 13)
        nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        DrawWhiteInkText(bx + btnW / 2, curY + btnH / 2, "刷新")
        shopRefreshBtnRect = { x = bx, y = curY, w = btnW, h = btnH, isDesign = true }
        curY = curY + btnH + btnGap

        -- 4. 倍速按钮
        do
            local spd = gameState.battleSpeed or 1
            local spdLabel = "×" .. tostring(spd)
            local spdOn = spd > 1
            local spdPulse = spdOn and (0.7 + 0.3 * math.sin(t * 5)) or 1.0
            nvgBeginPath(vg); nvgRoundedRect(vg, bx, curY, btnW, btnH, 3)
            if spdOn then
                nvgFillColor(vg, nvgRGBA(60, 40, 10, math.floor(200 * spdPulse))); nvgFill(vg)
                nvgStrokeColor(vg, nvgRGBA(255, 200, 60, math.floor(180 * spdPulse)))
            else
                nvgFillColor(vg, nvgRGBA(25, 22, 18, 190)); nvgFill(vg)
                nvgStrokeColor(vg, nvgRGBA(120, 110, 100, 120))
            end
            nvgStrokeWidth(vg, 0.8); nvgStroke(vg)
            nvgFontSize(vg, 13)
            nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
            DrawWhiteInkText(bx + btnW / 2, curY + btnH / 2, "倍速" .. spdLabel)
            battleSpeedBtnRect = { x = bx, y = curY, w = btnW, h = btnH, isDesign = true }
            curY = curY + btnH + btnGap
        end

        -- 7. 自动战斗按钮 (教程中隐藏)
        if not tutorialState.active then
            local isAuto = gameState.autoBattle
            local blocked = gameState.noFullAuto  -- 副本模式禁用全自动
            local autoPulse = isAuto and (0.7 + 0.3 * math.sin(t * 4)) or 1.0
            nvgBeginPath(vg); nvgRoundedRect(vg, bx, curY, btnW, btnH, 3)
            if blocked then
                nvgFillColor(vg, nvgRGBA(40, 35, 35, 160)); nvgFill(vg)
                nvgStrokeColor(vg, nvgRGBA(80, 70, 60, 100))
            elseif isAuto then
                nvgFillColor(vg, nvgRGBA(15, 50, 30, math.floor(220 * autoPulse))); nvgFill(vg)
                nvgStrokeColor(vg, nvgRGBA(80, 255, 140, math.floor(180 * autoPulse)))
            else
                nvgFillColor(vg, nvgRGBA(25, 22, 18, 190)); nvgFill(vg)
                nvgStrokeColor(vg, nvgRGBA(120, 110, 100, 120))
            end
            nvgStrokeWidth(vg, 0.8); nvgStroke(vg)
            nvgFontSize(vg, 12)
            nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
            local autoLabel = blocked and "禁用" or (isAuto and "自动 ON" or "自动 OFF")
            DrawWhiteInkText(bx + btnW / 2, curY + btnH / 2, autoLabel)
            autoBattleBtnRect = { x = bx, y = curY, w = btnW, h = btnH, isDesign = true }
            curY = curY + btnH + btnGap
        end

        -- 8. 规则按钮
        nvgBeginPath(vg); nvgRoundedRect(vg, bx, curY, btnW, btnH, 3)
        nvgFillColor(vg, nvgRGBA(30, 30, 50, 180)); nvgFill(vg)
        nvgStrokeColor(vg, nvgRGBA(140, 140, 180, 120)); nvgStrokeWidth(vg, 0.6); nvgStroke(vg)
        nvgFontSize(vg, 13)
        nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        DrawWhiteInkText(bx + btnW / 2, curY + btnH / 2, "规则")
        battleRuleBtnRect = { x = bx, y = curY, w = btnW, h = btnH, isDesign = true }
        curY = curY + btnH + btnGap

        -- 9. 退出按钮 (教程战斗阶段step>=8也显示)
        if not tutorialState.active or tutorialState.step >= 8 then
            nvgBeginPath(vg); nvgRoundedRect(vg, bx, curY, btnW, btnH, 3)
            nvgFillColor(vg, nvgRGBA(60, 20, 20, 160)); nvgFill(vg)
            nvgStrokeColor(vg, nvgRGBA(180, 100, 80, 120)); nvgStrokeWidth(vg, 0.6); nvgStroke(vg)
            nvgFontSize(vg, 14)
            nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
            DrawWhiteInkText(bx + btnW / 2, curY + btnH / 2, "退出")
            battleBackBtnRect = { x = bx, y = curY, w = btnW, h = btnH, isDesign = true }
        else
            battleBackBtnRect = nil
        end

        shopFightBtnRect = nil
        autoMarchBtnRect = nil  -- 自动行军按钮在 DrawBottomActionBar 中绘制
    end
end

-- ============================================================================
-- 右下角操作栏: 自动行军 + 预留技能按钮区域 (设计坐标)
-- ============================================================================
function DrawBottomActionBar()
    if fontId < 0 then return end
    if gameState.phase ~= "BATTLE" and gameState.phase ~= "WIN" and gameState.phase ~= "LOSE" then
        autoMarchBtnRect = nil
        skillBtnRects = {}
        return
    end
    if gameState.battlePhase ~= "FIGHT" then
        autoMarchBtnRect = nil
        skillBtnRects = {}
        return
    end

    local t = gameState.gameTime
    nvgFontFaceId(vg, GetMainFont())

    -- ======== 右下角三角排布圆形按钮 ========
    -- 布局: 底部两个武技圈并排, 上方一个自动行军圈
    --          [自动]
    --        [武技1][武技2]
    local btnSc = gameSettings.btnScale or 1.0
    local R = math.floor(26 * btnSc)        -- 圆形按钮半径 (受缩放)
    local gap = math.floor(6 * btnSc)       -- 圈之间间距
    local marginR = 8 + safeInsets.right   -- 右边距(含安全区)
    local marginB = 12 + safeInsets.bottom -- 底部边距(含安全区)

    -- 底部两圈的中心Y (下移一个身位, 贴近战场底部)
    -- 应用设置中自定义的按钮位置偏移
    local btnOfsX = gameSettings.btnOffsetX or 0
    local btnOfsY = gameSettings.btnOffsetY or 0
    local bottomCY = BATTLE_ZONE.bottom - marginB - R + R * 2 + btnOfsY
    -- 底部两圈: 右圈和左圈
    local rightCX = DESIGN_W - marginR - R + btnOfsX
    local leftCX  = rightCX - R * 2 - gap
    -- 上方自动行军圈: 在两圈正上方居中
    local topCX = (leftCX + rightCX) / 2
    local topCY = bottomCY - R * 2 - gap

    skillBtnRects = {}

    -- ---- 绘制辅助函数: 圆形按钮 ----
    local function drawCircleBtn(cx, cy, r, bgR, bgG, bgB, bgA, borderR, borderG, borderB, borderA)
        nvgBeginPath(vg); nvgCircle(vg, cx, cy, r)
        nvgFillColor(vg, nvgRGBA(bgR, bgG, bgB, bgA)); nvgFill(vg)
        nvgBeginPath(vg); nvgCircle(vg, cx, cy, r)
        nvgStrokeColor(vg, nvgRGBA(borderR, borderG, borderB, borderA))
        nvgStrokeWidth(vg, 1.5); nvgStroke(vg)
    end

    -- ---- 1. 自动行军圈 (顶部) ----
    local isAuto = gameState.autoMarch
    local amPulse = isAuto and (0.7 + 0.3 * math.sin(t * 3)) or 1.0
    if isAuto then
        drawCircleBtn(topCX, topCY, R,
            15, 70, 35, math.floor(220 * amPulse),
            80, 255, 140, math.floor(200 * amPulse))
    else
        drawCircleBtn(topCX, topCY, R,
            30, 25, 35, 200,
            120, 110, 130, 100)
    end
    -- 文字
    nvgFontSize(vg, math.floor(12 * btnSc))
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    if isAuto then
        DrawWhiteInkText(topCX, topCY - 4 * btnSc, "自动")
        nvgFontSize(vg, math.floor(10 * btnSc))
        DrawWhiteInkText(topCX, topCY + 9 * btnSc, "ON")
        -- 当前策略小标签
        local stName = "五路"
        local stClr = { 120, 220, 160 }
        for _, st in ipairs(MARCH_STRATEGIES) do
            if st.id == gameState.autoMarchStrategy then stName = st.name; stClr = st.color; break end
        end
        nvgFontSize(vg, math.floor(8 * btnSc))
        nvgFillColor(vg, nvgRGBA(stClr[1], stClr[2], stClr[3], 200))
        nvgText(vg, topCX, topCY + R + 7 * btnSc, stName, nil)
    else
        DrawWhiteInkText(topCX, topCY - 4 * btnSc, "行军")
        nvgFontSize(vg, math.floor(10 * btnSc))
        DrawWhiteInkText(topCX, topCY + 9 * btnSc, "OFF")
    end
    -- 新手提示: 长按切换策略
    if not gameSettings.shownMarchHint then
        nvgFontSize(vg, math.floor(9 * btnSc))
        local hintAlpha = math.floor(140 + 80 * math.sin((gameState.gameTime or 0) * 2.5))
        nvgFillColor(vg, nvgRGBA(255, 220, 100, hintAlpha))
        nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_TOP)
        nvgText(vg, topCX, topCY + R + 14 * btnSc, "长按切换策略", nil)
    end
    -- 圆形碰撞检测用矩形近似
    autoMarchBtnRect = { cx = topCX, cy = topCY, r = R, isCircle = true, isDesign = true }

    -- ---- 2. 武技技能圈 (底部两个) ----
    local slotPositions = {
        { cx = leftCX,  cy = bottomCY },  -- slot 1 左
        { cx = rightCX, cy = bottomCY },  -- slot 2 右
    }

    for slot = 1, 2 do
        local pos = slotPositions[slot]
        local techIdx = playerEquippedSkills[slot]
        local sk = techIdx and SKILL_DEFS[techIdx]

        if sk then
            local sc = sk.color
            local skPulse = 0.6 + 0.4 * math.sin(t * 2.5 + slot * 1.2)

            if sk.cooldown > 0 then
                -- ---- 冷却中: 暗色底 + 扇形冷却覆盖 ----
                local cdRatio = sk.cooldown / sk.maxCooldown
                -- 暗底
                nvgBeginPath(vg); nvgCircle(vg, pos.cx, pos.cy, R)
                nvgFillColor(vg, nvgRGBA(20, 15, 12, 220)); nvgFill(vg)

                -- 冷却扇形 (从顶部顺时针擦除)
                local angle = (1 - cdRatio) * math.pi * 2  -- 已冷却的角度
                if angle > 0.01 then
                    nvgBeginPath(vg)
                    nvgMoveTo(vg, pos.cx, pos.cy)
                    nvgArc(vg, pos.cx, pos.cy, R, -math.pi / 2, -math.pi / 2 + angle, 1)  -- NVG_CW = 1
                    nvgClosePath(vg)
                    nvgFillColor(vg, nvgRGBA(sc[1], sc[2], sc[3], 50)); nvgFill(vg)
                end

                -- 边框
                nvgBeginPath(vg); nvgCircle(vg, pos.cx, pos.cy, R)
                nvgStrokeColor(vg, nvgRGBA(sc[1], sc[2], sc[3], 80))
                nvgStrokeWidth(vg, 1.2); nvgStroke(vg)

                -- 图标 (半透明)
                nvgGlobalAlpha(vg, 0.4)
                drawSkillIcon(sk.iconIdx, pos.cx - R + 5, pos.cy - R + 5, (R - 5) * 2, R)
                nvgGlobalAlpha(vg, 1.0)

                -- 冷却秒数
                nvgFontSize(vg, math.floor(16 * btnSc))
                nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
                DrawWhiteInkText(pos.cx, pos.cy + 2, string.format("%.0f", math.ceil(sk.cooldown)))
            else
                -- ---- 可用: 发光底 + 图标 ----
                local glow = nvgRadialGradient(vg, pos.cx, pos.cy, R * 0.3, R,
                    nvgRGBA(sc[1], sc[2], sc[3], math.floor(80 * skPulse)),
                    nvgRGBA(sc[1], sc[2], sc[3], math.floor(20 * skPulse)))
                nvgBeginPath(vg); nvgCircle(vg, pos.cx, pos.cy, R)
                nvgFillPaint(vg, glow); nvgFill(vg)

                -- 边框脉冲
                nvgBeginPath(vg); nvgCircle(vg, pos.cx, pos.cy, R)
                nvgStrokeColor(vg, nvgRGBA(sc[1], sc[2], sc[3], math.floor(220 * skPulse)))
                nvgStrokeWidth(vg, 1.5); nvgStroke(vg)

                -- 图标
                drawSkillIcon(sk.iconIdx, pos.cx - R + 5, pos.cy - R + 5, (R - 5) * 2, R)
            end

            skillBtnRects[slot] = { cx = pos.cx, cy = pos.cy, r = R, isCircle = true, isDesign = true, techIdx = techIdx }
        else
            -- 空槽位: 虚线圆
            nvgBeginPath(vg); nvgCircle(vg, pos.cx, pos.cy, R)
            nvgStrokeColor(vg, nvgRGBA(100, 90, 80, 60))
            nvgStrokeWidth(vg, 1.0); nvgStroke(vg)
            nvgFontSize(vg, math.floor(9 * btnSc))
            nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
            DrawWhiteInkText(pos.cx, pos.cy, "空")
        end
    end

    -- 新手策略提示 (前3场战斗FIGHT阶段显示)
    if (gameSettings.battleCount or 0) < 3 and not tutorialState.active then
        local hintAlpha = math.floor(120 + 60 * math.sin(t * 2.5))
        nvgFontSize(vg, math.floor(9 * btnSc))
        nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_TOP)
        if not isAuto then
            -- 行军OFF时提示开启
            nvgFillColor(vg, nvgRGBA(180, 220, 140, hintAlpha))
            nvgText(vg, topCX, topCY - R - 14 * btnSc, "点击开启自动行军", nil)
        else
            -- 行军ON时提示长按换策略
            nvgFillColor(vg, nvgRGBA(200, 180, 120, hintAlpha))
            nvgText(vg, topCX, topCY - R - 14 * btnSc, "长按切换策略", nil)
        end
    end
end

-- ============================================================================
-- 策略选项条 (长按自动行军 → 向左弹出选项)
-- ============================================================================
function DrawStrategyWheel()
    if not strategyWheelState.show then return end
    if not autoMarchBtnRect then return end

    local ab = autoMarchBtnRect
    local t = gameState.gameTime or 0

    -- 布局参数（与 BeginPress 碰撞检测保持一致）
    local cardW = 115
    local cardH = 64
    local gap = 8
    local startX = ab.cx - ab.r - 12   -- 卡片右边缘起点
    local cardCY = ab.cy - ab.r - cardH / 2 - 16  -- 按钮上方
    local cornerR = 10

    -- 暗黑配色
    local cardColors = {
        { bg = { 40, 65, 45 }, hi = { 120, 220, 160 } },
        { bg = { 70, 50, 22 }, hi = { 255, 200, 80  } },
        { bg = { 28, 48, 72 }, hi = { 100, 180, 255 } },
    }

    nvgSave(vg)
    nvgFontFaceId(vg, GetMainFont())

    -- 连接线（从按钮顶部斜向卡片右端）
    local lineX0 = ab.cx - 4
    local lineY0 = ab.cy - ab.r
    local lineX1 = startX
    local lineY1 = cardCY + cardH / 2 - 2
    nvgBeginPath(vg)
    nvgMoveTo(vg, lineX0, lineY0)
    nvgLineTo(vg, lineX1, lineY1)
    nvgStrokeColor(vg, nvgRGBA(140, 120, 70, 120))
    nvgStrokeWidth(vg, 1)
    nvgStroke(vg)

    -- 绘制3张策略卡片
    for i = 1, #MARCH_STRATEGIES do
        local st = MARCH_STRATEGIES[i]
        local cc = cardColors[i]
        local sel = (strategyWheelState.selected == i)

        local cRight = startX - (i - 1) * (cardW + gap)
        local cLeft = cRight - cardW
        local cTop = cardCY - cardH / 2
        local cBot = cardCY + cardH / 2

        -- 卡片背景
        nvgBeginPath(vg)
        nvgRoundedRect(vg, cLeft, cTop, cardW, cardH, cornerR)
        if sel then
            local pulse = 0.8 + 0.2 * math.sin(t * 5)
            local a = math.floor(220 * pulse)
            local grad = nvgLinearGradient(vg, cLeft, cTop, cLeft, cBot,
                nvgRGBA(cc.hi[1], cc.hi[2], cc.hi[3], math.floor(a * 0.6)),
                nvgRGBA(cc.bg[1], cc.bg[2], cc.bg[3], a))
            nvgFillPaint(vg, grad); nvgFill(vg)
        else
            nvgFillColor(vg, nvgRGBA(cc.bg[1], cc.bg[2], cc.bg[3], 180))
            nvgFill(vg)
        end

        -- 卡片边框
        nvgBeginPath(vg)
        nvgRoundedRect(vg, cLeft, cTop, cardW, cardH, cornerR)
        if sel then
            nvgStrokeColor(vg, nvgRGBA(cc.hi[1], cc.hi[2], cc.hi[3], 220))
            nvgStrokeWidth(vg, 1.5)
        else
            nvgStrokeColor(vg, nvgRGBA(140, 120, 80, 80))
            nvgStrokeWidth(vg, 0.8)
        end
        nvgStroke(vg)

        -- 策略名
        local tx = cLeft + cardW / 2
        local ty = cardCY - 6
        nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        nvgFontSize(vg, 18)
        DrawWhiteInkText(tx, ty, st.name)

        -- 简短描述（始终显示）
        nvgFontSize(vg, 11)
        nvgFillColor(vg, nvgRGBA(cc.hi[1], cc.hi[2], cc.hi[3], 180))
        nvgText(vg, tx, ty + 18, st.desc, nil)
    end

    -- 提示文字
    nvgFontSize(vg, 10)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    local hintAlpha = math.floor(100 + 60 * math.sin(t * 2.5))
    nvgFillColor(vg, nvgRGBA(180, 165, 130, hintAlpha))
    nvgText(vg, startX - (#MARCH_STRATEGIES * (cardW + gap)) / 2, cardCY + cardH / 2 + 10, "点击选择策略", nil)

    nvgRestore(vg)
end

-- ============================================================================
-- 战斗规则弹窗
-- ============================================================================
function DrawBattleRulesPopup()
    if not battleRulesState.show then return end

    nvgSave(vg)
    -- 全屏半透明遮罩
    nvgBeginPath(vg); nvgRect(vg, 0, 0, DESIGN_W, DESIGN_H)
    nvgFillColor(vg, nvgRGBA(0, 0, 0, 180)); nvgFill(vg)

    -- 规则数据
    local rules = {
        { "★ 新手必读", "核心流程: 商店购买武灵→拖到石台上阵→点击「开战」→拖拽已上阵武灵到车道派兵。\n手动派兵: 将上阵武灵拖到指定车道精准出击。\n自动行军: 右下角行军按钮开启后自动派兵；长按按钮可切换策略(五路并进/全歼中路/分散侧翼)。\n查看详情: 点击商店卡牌可查看武灵属性。\n武技技能: 战斗中长按右下角武技图标可查看技能详情，短按后拖拽释放。" },
        { "基本玩法", "从商店购买武灵放置到石台上阵，拖拽武灵到战场选择车道派兵。" },
        { "军资经济", "每" .. tostring(math.floor(GameConfig.GOLD_INTERVAL)) .. "秒自动获得1军资，合理分配军资购买和刷新。" },
        { "阵容布置", "最多上阵" .. #PLAYER_SLOTS .. "位武灵，品质越高费用越高但属性更强。" },
        { "自动行军", "开启后武灵CD就绪即自动派兵。长按可选择策略：五路并进、全歼中路、分散侧翼。" },
        { "武技技能", "装备武技后战斗中可拖拽释放，造成范围伤害。自动行军时也会自动释放。" },
        { "突破机制", "己方兵突破敌方临界线可直接攻击敌方大本营。" },
        { "胜负判定", "率先摧毁对方大本营获胜。" },
        { "武灵升级", "出卡阶段将同名武灵拖放到已上阵武灵身上即可升级。每次升级属性提升：攻击×1.15  防御×1.10  生命×1.20。可多次叠加，等级越高越强。" },
        { "兵种特性", "虎贲刀兵：近战推进  连弩射手/火攻术士：远程射击  铁盾重卫：驻守半场嘲讽敌人  夜行刺客：绕后暗杀1.5倍  铁骑先锋：冲锋撞击  长枪兵：贯穿2人  战象巨兽：范围震击  军医道士：治疗+攻速光环" },
        { "特殊兵种", "火牛突袭：全速冲锋引爆(250%范围伤害)  驯兽使：每4秒召唤走兽(上限4只)  寒冰术士：远程攻击附带40%减速  蜂巢蝗群：一次6只攻速极快" },
        { "敌军差异", "黄巾力士死亡时自爆(120%范围伤害)  铁甲悍将受到伤害降低15%  山贼弓手远程射击" },
    }

    local titleFontSize = 24
    local ruleTitleSize = 16
    local ruleBodySize = 14
    local pw = 380
    local wrapW = pw - 48
    local titleAreaH = 20 + 32 + 12  -- padding + 标题 + 分隔线

    -- 第一遍：计算内容总高度
    nvgFontFaceId(vg, GetMainFont())
    local contentH = 0
    for _, rule in ipairs(rules) do
        contentH = contentH + 22  -- 规则标题行
        nvgFontSize(vg, ruleBodySize)
        local bounds = nvgTextBoxBounds(vg, 0, 0, wrapW, rule[2], nil)
        local textH = bounds and (bounds[4] - bounds[2]) or 18
        contentH = contentH + textH + 10
    end
    contentH = contentH + 10  -- 底部padding

    -- 面板尺寸
    local closeBtnAreaH = 48
    local maxH = DESIGN_H - 40
    local ph = math.min(titleAreaH + contentH + closeBtnAreaH, maxH)
    local viewH = ph - titleAreaH - closeBtnAreaH
    local px = (DESIGN_W - pw) / 2
    local py = (DESIGN_H - ph) / 2

    -- 保存到状态供滚动使用
    battleRulesState.contentH = contentH
    battleRulesState.viewH = viewH
    battleRulesState.panelRect = { x = px, y = py, w = pw, h = ph }

    -- 背景
    nvgBeginPath(vg); nvgRoundedRect(vg, px, py, pw, ph, 10)
    nvgFillColor(vg, nvgRGBA(25, 22, 18, 245)); nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(180, 160, 120, 150)); nvgStrokeWidth(vg, 1.5); nvgStroke(vg)

    -- 标题（固定不滚动）
    local titleY = py + 20
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_TOP)
    nvgFontSize(vg, titleFontSize)
    nvgFillColor(vg, nvgRGBA(255, 220, 120, 255))
    nvgText(vg, DESIGN_W / 2, titleY, "战斗规则", nil)

    -- 分隔线
    local sepY = titleY + 32
    nvgBeginPath(vg)
    nvgMoveTo(vg, px + 20, sepY); nvgLineTo(vg, px + pw - 20, sepY)
    nvgStrokeColor(vg, nvgRGBA(180, 160, 120, 100)); nvgStrokeWidth(vg, 0.8); nvgStroke(vg)

    -- 裁剪滚动区域
    local scrollTop = py + titleAreaH
    local scrollBot = scrollTop + viewH
    nvgScissor(vg, px, scrollTop, pw, viewH)

    -- 规则内容（随滚动偏移）
    local scrollY = battleRulesState.scrollY or 0
    local ty = scrollTop - scrollY + 6
    local lx = px + 20
    nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_TOP)

    for _, rule in ipairs(rules) do
        -- 规则标题
        nvgFillColor(vg, nvgRGBA(255, 200, 100, 240))
        nvgFontSize(vg, ruleTitleSize)
        nvgText(vg, lx, ty, "· " .. rule[1], nil)
        ty = ty + 22
        -- 规则正文
        nvgFillColor(vg, nvgRGBA(220, 210, 190, 210))
        nvgFontSize(vg, ruleBodySize)
        local bounds = nvgTextBoxBounds(vg, lx + 10, ty, wrapW, rule[2], nil)
        nvgTextBox(vg, lx + 10, ty, wrapW, rule[2], nil)
        local textH = bounds and (bounds[4] - bounds[2]) or 18
        ty = ty + textH + 10
    end

    nvgResetScissor(vg)

    -- 滚动条指示器（内容超出时显示）
    if contentH > viewH then
        local maxScroll = contentH - viewH
        local barH = math.max(20, viewH * (viewH / contentH))
        local barY = scrollTop + (scrollY / maxScroll) * (viewH - barH)
        nvgBeginPath(vg)
        nvgRoundedRect(vg, px + pw - 8, barY, 4, barH, 2)
        nvgFillColor(vg, nvgRGBA(180, 160, 120, 80))
        nvgFill(vg)
    end

    -- 关闭按钮（固定在底部）
    local closeBtnW, closeBtnH = 100, 32
    local closeBtnX = (DESIGN_W - closeBtnW) / 2
    local closeBtnY = py + ph - 42
    nvgBeginPath(vg); nvgRoundedRect(vg, closeBtnX, closeBtnY, closeBtnW, closeBtnH, 6)
    nvgFillColor(vg, nvgRGBA(60, 50, 35, 220)); nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(200, 180, 120, 180)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
    nvgFontSize(vg, 16)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    nvgFillColor(vg, nvgRGBA(255, 240, 200, 240))
    nvgText(vg, DESIGN_W / 2, closeBtnY + closeBtnH / 2, "知道了", nil)

    battleRulesState.closeBtnRect = { x = closeBtnX, y = closeBtnY, w = closeBtnW, h = closeBtnH }

    nvgRestore(vg)
end

