        { "       + 兵甲分 + 武技分", nvgRGBA(210, 200, 190, 220) },
        { "", nvgRGBA(0, 0, 0, 0) },
        { "· 武灵战力: 取拥有的最强4只武灵评分", nvgRGBA(200, 190, 180, 200) },
        { "· 兵甲分: 已装备兵甲的属性总和", nvgRGBA(200, 190, 180, 200) },
        { "· 武技分: 已解锁武技的阶级评分", nvgRGBA(200, 190, 180, 200) },
    }
    for _, ln in ipairs(lines) do
        nvgFillColor(vg, ln[2])
        nvgText(vg, lx2, ly, ln[1], nil)
        ly = ly + 18
    end

    -- 关闭按钮
    local cbW, cbH = 80, 28
    local cbX = (DESIGN_W - cbW) / 2
    local cbY = py + ph - 38
    nvgBeginPath(vg); nvgRoundedRect(vg, cbX, cbY, cbW, cbH, 6)
    nvgFillColor(vg, nvgRGBA(50, 40, 30, 220)); nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(180, 140, 70, 180)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
    nvgFontSize(vg, 15)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    nvgFillColor(vg, nvgRGBA(255, 240, 200, 240))
    nvgText(vg, DESIGN_W / 2, cbY + cbH / 2, "关闭", nil)
    powerExplainPopup.closeBtnRect = { x = cbX, y = cbY, w = cbW, h = cbH }

    nvgRestore(vg)
end

-- ============================================================================
-- 武技技能详情弹窗 (战斗中长按查看)
-- ============================================================================
function DrawSkillInfoPopup()
    if not skillLongPressState.showPopup then return end

    local skIdx = skillLongPressState.popupSkillIdx
    local tech = SKILL_TECHNIQUES[skIdx]
    local sk = SKILL_DEFS[skIdx]
    if not tech or not sk then
        skillLongPressState.showPopup = false
        return
    end
    local tier = SKILL_TIERS[tech.tier]

    nvgSave(vg)
    -- 半透明遮罩
    nvgBeginPath(vg); nvgRect(vg, 0, 0, DESIGN_W, DESIGN_H)
    nvgFillColor(vg, nvgRGBA(0, 0, 0, 140)); nvgFill(vg)

    local pw = 320
    local ph = 200
    local px = (DESIGN_W - pw) / 2
    local py = (DESIGN_H - ph) / 2

    nvgBeginPath(vg); nvgRoundedRect(vg, px, py, pw, ph, 10)
    nvgFillColor(vg, nvgRGBA(20, 15, 25, 245)); nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(tier.color[1], tier.color[2], tier.color[3], 180))
    nvgStrokeWidth(vg, 1.5); nvgStroke(vg)

    skillLongPressState.popupRect = { x = px, y = py, w = pw, h = ph }

    nvgFontFaceId(vg, GetMainFont())

    -- 技能名 + 阶级
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_TOP)
    nvgFontSize(vg, 22)
    nvgFillColor(vg, nvgRGBA(tier.color[1], tier.color[2], tier.color[3], 255))
    nvgText(vg, DESIGN_W / 2, py + 16, tech.name .. " [" .. tier.name .. "]", nil)

    -- 分隔线
    nvgBeginPath(vg)
    nvgMoveTo(vg, px + 20, py + 42); nvgLineTo(vg, px + pw - 20, py + 42)
    nvgStrokeColor(vg, nvgRGBA(tier.color[1], tier.color[2], tier.color[3], 80))
    nvgStrokeWidth(vg, 0.8); nvgStroke(vg)

    -- 描述
    nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_TOP)
    nvgFontSize(vg, 14)
    nvgFillColor(vg, nvgRGBA(210, 200, 190, 220))
    nvgTextBox(vg, px + 20, py + 50, pw - 40, tech.desc, nil)

    -- CD信息
    nvgFontSize(vg, 13)
    nvgFillColor(vg, nvgRGBA(180, 180, 200, 200))
    nvgText(vg, px + 20, py + 130, string.format("冷却: %.0f秒  伤害: %d  类型: %s",
        sk.maxCooldown, sk.damage, sk.skillType == "line" and "直线" or (sk.skillType == "rect" and "矩形" or "圆形")), nil)

    -- 当前状态
    nvgFontSize(vg, 13)
    if sk.cooldown > 0 then
        nvgFillColor(vg, nvgRGBA(255, 120, 80, 200))
        nvgText(vg, px + 20, py + 148, string.format("冷却中: %.1f秒", sk.cooldown), nil)
    else
        nvgFillColor(vg, nvgRGBA(100, 255, 120, 200))
        nvgText(vg, px + 20, py + 148, "可释放", nil)
    end

    -- 关闭提示
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    nvgFontSize(vg, 13)
    nvgFillColor(vg, nvgRGBA(160, 150, 140, 160))
    nvgText(vg, DESIGN_W / 2, py + ph - 16, "点击任意处关闭", nil)

    nvgRestore(vg)
end

-- ============================================================================
-- 信息面板 (左上角, 屏幕逻辑坐标)
-- ============================================================================

function DrawInfoPanel()
    if fontId < 0 then return end
    if longPressState.active or dragState.active or infoPopupState.show then return end  -- 操作中隐藏

    local panelW = 110
    local panelH = 88
    local ipOfsX = (gameSettings.infoPanelOffsetX or 0) * scale
    local ipOfsY = (gameSettings.infoPanelOffsetY or 0) * scale
    local px = 4 + ipOfsX
    local py = 26 * scale + offsetY + ipOfsY  -- HUD下方

    nvgSave(vg)

    -- 半透明古卷背景
    nvgBeginPath(vg); nvgRoundedRect(vg, px, py, panelW, panelH, 4)
    nvgFillColor(vg, nvgRGBA(10, 8, 5, 140)); nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(160, 130, 70, 40))
    nvgStrokeWidth(vg, 0.5); nvgStroke(vg)

    nvgFontFaceId(vg, GetMainFont())
    local ly = py + 10

    -- 阵容加成
    local filledCount = 0
    local totalAtk = 0
    local totalDef = 0
    for _, slot in ipairs(PLAYER_SLOTS) do
        if slot.filled and slot.card then
            filledCount = filledCount + 1
            local lm = 1 + ((slot.card.level or 1) - 1) * GameConfig.LEVEL_GROWTH_RATE
            totalAtk = totalAtk + math.floor(slot.card.atk * lm)
            totalDef = totalDef + math.floor(slot.card.def * lm)
        end
    end

    nvgFontSize(vg, 13.5)
    nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_TOP)

    DrawWhiteInkText(px + 6, ly, "阵容 " .. filledCount .. "/" .. #PLAYER_SLOTS)
    ly = ly + 13

    DrawWhiteInkText(px + 6, ly, "总攻: " .. totalAtk)
    ly = ly + 12

    DrawWhiteInkText(px + 6, ly, "总防: " .. totalDef)
    ly = ly + 16

    -- 操作提示
    nvgFontSize(vg, 11.2)
    DrawWhiteInkText(px + 6, ly, "点击查看 - 拖拽换位")
    ly = ly + 10
    DrawWhiteInkText(px + 6, ly, "拖拽卡牌至石台放置")

    nvgRestore(vg)
end

-- ============================================================================
-- 底部商店 (暗黑水墨风)
-- ============================================================================

function DrawShop()
    local sl = shopLayout
    if sl.h <= 0 then return end

    if fontId < 0 then return end
    nvgFontFaceId(vg, GetMainFont())

    local isSHOP = (gameState.battlePhase == "SHOP")

    -- ========== 底栏: 只放卡牌 ==========
    local shopGrad = nvgLinearGradient(vg, 0, sl.y, 0, sl.y + sl.h,
        nvgRGBA(42, 35, 22, 240), nvgRGBA(28, 22, 14, 248))
    nvgBeginPath(vg); nvgRect(vg, 0, sl.y, screenW, sl.h)
    nvgFillPaint(vg, shopGrad); nvgFill(vg)

    -- 顶部金线
    local topLine1 = nvgLinearGradient(vg, 0, sl.y, screenW, sl.y,
        nvgRGBA(180, 150, 80, 0), nvgRGBA(180, 150, 80, 100))
    nvgBeginPath(vg)
    nvgMoveTo(vg, 0, sl.y + 0.5); nvgLineTo(vg, screenW, sl.y + 0.5)
    nvgStrokePaint(vg, topLine1)
    nvgStrokeWidth(vg, 1.2); nvgStroke(vg)

    -- 卡牌布局 (底栏居中)
    local cardCount = GameConfig.SHOP_SIZE
    local cardH = sl.h - 22
    local cardW = cardH * CARD_RATIO
    local gap = 8
    local totalCardsW = cardCount * cardW + (cardCount - 1) * gap
    local startX = (screenW - totalCardsW) / 2
    local cardY = sl.y + 8

    -- 提示文字
    nvgFontSize(vg, 13)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_BOTTOM)
    if gameState.isDummy and dummyState.prepPhase then
        DrawWhiteInkText(screenW / 2, sl.y + sl.h / 2, "武灵已就位，点击「开始挑战」出战")
    else
        DrawWhiteInkText(screenW / 2, sl.y + sl.h - 2, "点击查看 - 拖拽放置")
        -- 新手提示: 前3场战斗提示可点击查看详情
        if gameSettings.battleCount < 3 then
            nvgFontSize(vg, 12)
            nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_TOP)
            nvgFillColor(vg, nvgRGBA(255, 220, 120, math.floor(160 + 60 * math.sin((gameState.gameTime or 0) * 3))))
            nvgText(vg, screenW / 2, sl.y + 2, "提示: 点击卡牌可查看武灵详情", nil)
        end
    end

    -- 商店卡牌 (打桩准备阶段不显示)
    if not (gameState.isDummy and dummyState.prepPhase) then
    for i = 1, cardCount do
        local cx = startX + (i - 1) * (cardW + gap)
        local shopItem = shopCards[i]
        if shopItem and not shopItem.sold then
            local card = HERO_CARDS[shopItem.cardIdx]
            if card then
                DrawInventoryCard(cx, cardY, cardW, cardH, card, shopItem.constellation or 0, false)
                -- 费用标签
                local costStr = tostring(shopItem.cost)
                local canAfford = gameState.gold >= shopItem.cost
                local costBgColor = canAfford and nvgRGBA(30, 60, 40, 200) or nvgRGBA(60, 30, 30, 200)
                local costTxtColor = canAfford and nvgRGBA(100, 255, 180, 240) or nvgRGBA(255, 120, 100, 200)
                local costW = 28
                local costH = 13
                local costX = cx + cardW / 2 - costW / 2
                local costY = cardY + cardH + 1
                nvgBeginPath(vg); nvgRoundedRect(vg, costX, costY, costW, costH, 2)
                nvgFillColor(vg, costBgColor); nvgFill(vg)
                nvgFontSize(vg, 13.5)
                nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
                nvgFillColor(vg, costTxtColor)
                nvgText(vg, costX + costW / 2, costY + costH / 2, costStr, nil)
            end
        elseif shopItem and shopItem.sold then
            -- 已购槽位：暗底 + "已购"文字，不显示"空"
            nvgBeginPath(vg); nvgRoundedRect(vg, cx, cardY, cardW, cardH, 3)
            nvgFillColor(vg, nvgRGBA(20, 16, 10, 100)); nvgFill(vg)
            nvgStrokeColor(vg, nvgRGBA(80, 65, 40, 40))
            nvgStrokeWidth(vg, 0.5); nvgStroke(vg)
            nvgFontSize(vg, 13.5)
            nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
            nvgFillColor(vg, nvgRGBA(120, 110, 90, 160))
            nvgText(vg, cx + cardW / 2, cardY + cardH / 2, "已购", nil)
        else
            DrawEmptyInvSlot(cx, cardY, cardW, cardH)
        end
        if not shopItem then shopItem = {} end
        shopItem._rect = { x = cx, y = cardY, w = cardW, h = cardH }
        if i <= #shopCards then shopCards[i]._rect = shopItem._rect end
    end
    end -- if not dummy prep
end

function DrawInventoryArrow(sl, isLeft)
    local ax = isLeft and sl.arrowLeftX or sl.arrowRightX
    local aw = isLeft and sl.arrowLeftW or sl.arrowRightW
    local ay = sl.y + 20
    local ah = sl.cardH
    local t = gameState.gameTime

    -- 是否可点击
    local canClick
    if isLeft then
        canClick = invScrollOffset > 0
    else
        canClick = invScrollOffset < math.max(0, #inventory - GameConfig.INVENTORY_VISIBLE)
    end

    local alpha = canClick and 180 or 50
    local pulse = canClick and (0.7 + 0.3 * math.sin(t * 3)) or 1.0

    -- 背景
    nvgBeginPath(vg); nvgRoundedRect(vg, ax, ay, aw, ah, 3)
    nvgFillColor(vg, nvgRGBA(25, 20, 12, math.floor(120 * pulse))); nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(160, 130, 70, math.floor(alpha * pulse * 0.4)))
    nvgStrokeWidth(vg, 0.5); nvgStroke(vg)

    -- 箭头符号
    if fontId >= 0 then
        nvgFontFaceId(vg, GetMainFont()); nvgFontSize(vg, 23)
        nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        nvgFillColor(vg, nvgRGBA(200, 180, 130, math.floor(alpha * pulse)))
        nvgText(vg, ax + aw / 2, ay + ah / 2, isLeft and "<" or ">", nil)
    end
end

function DrawEmptyInvSlot(x, y, w, h)
    nvgBeginPath(vg); nvgRoundedRect(vg, x, y, w, h, 3)
    nvgFillColor(vg, nvgRGBA(20, 16, 10, 100)); nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(80, 65, 40, 40))
    nvgStrokeWidth(vg, 0.5); nvgStroke(vg)
    if fontId >= 0 then
        nvgFontFaceId(vg, GetMainFont()); nvgFontSize(vg, 14)
        nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        DrawWhiteInkText(x + w / 2, y + h / 2, "空")
    end
end

-- 背包卡牌 (水墨风 + 命格标记)
function DrawInventoryCard(x, y, w, h, card, constellation, mergeable, hideName)
    local qc = QUALITY_COLORS[card.quality]
    local qg = QUALITY_GLOW[card.quality]
    local t = gameState.gameTime

    -- 外层品质光晕
    if qg and qg[4] > 0 then
        local pulse = 0.55 + 0.45 * math.sin(t * 2.2)
        local glowR = math.max(w, h) * 0.75
        local grad = nvgRadialGradient(vg, x + w / 2, y + h * 0.42, 2, glowR,
            nvgRGBA(qg[1], qg[2], qg[3], math.floor(qg[4] * pulse * 0.35)),
            nvgRGBA(qg[1], qg[2], qg[3], 0))
        nvgBeginPath(vg); nvgRoundedRect(vg, x - 4, y - 4, w + 8, h + 8, 6)
        nvgFillPaint(vg, grad); nvgFill(vg)
    end

    -- 可合成闪烁边框
    if mergeable then
        local mPulse = 0.5 + 0.5 * math.sin(t * 4)
        nvgBeginPath(vg); nvgRoundedRect(vg, x - 2, y - 2, w + 4, h + 4, 5)
        nvgStrokeColor(vg, nvgRGBA(200, 160, 255, math.floor(100 + 120 * mPulse)))
        nvgStrokeWidth(vg, 1.5); nvgStroke(vg)
    end

    -- 底板
    local paperGrad = nvgLinearGradient(vg, x, y, x, y + h,
        nvgRGBA(48, 40, 26, 248), nvgRGBA(32, 26, 14, 252))
    nvgBeginPath(vg); nvgRoundedRect(vg, x, y, w, h, 4)
    nvgFillPaint(vg, paperGrad); nvgFill(vg)

    -- 四角装饰
    local cs = 2
    for _, cp in ipairs({
        { x + 3, y + 3 }, { x + w - 3 - cs, y + 3 },
        { x + 3, y + h - 3 - cs }, { x + w - 3 - cs, y + h - 3 - cs },
    }) do
        nvgBeginPath(vg); nvgRect(vg, cp[1], cp[2], cs, cs)
        nvgFillColor(vg, nvgRGBA(200, 165, 90, 60)); nvgFill(vg)
    end

    -- 角色图
    local imgY = y + 3
    local imgH = h - 20
    if GetHeroSheet(card) > 0 then
        local _sh, _sc, _sr = GetHeroSheetInfo(card)
        DrawCardImage(x + 3, imgY, w - 6, imgH, _sh, card.row, card.col, _sc, _sr)
        local fadeGrad = nvgLinearGradient(vg, x, imgY + imgH - 10, x, imgY + imgH,
            nvgRGBA(32, 26, 14, 0), nvgRGBA(32, 26, 14, 200))
        nvgBeginPath(vg); nvgRect(vg, x + 3, imgY + imgH - 10, w - 6, 10)
        nvgFillPaint(vg, fadeGrad); nvgFill(vg)
    end

    -- 外边框 (品质描金)
    nvgBeginPath(vg); nvgRoundedRect(vg, x, y, w, h, 4)
    nvgStrokeColor(vg, nvgRGBA(qc[1], qc[2], qc[3], 170))
    nvgStrokeWidth(vg, 1.3); nvgStroke(vg)
    nvgBeginPath(vg); nvgRoundedRect(vg, x + 2, y + 2, w - 4, h - 4, 3)
    nvgStrokeColor(vg, nvgRGBA(200, 170, 100, 25))
    nvgStrokeWidth(vg, 0.5); nvgStroke(vg)

    if fontId < 0 then return end
    nvgFontFaceId(vg, GetMainFont())

    -- 左上类型印章
    local tc = TYPE_COLORS[card.type]
    nvgBeginPath(vg); nvgRoundedRect(vg, x + 3, y + 3, 13, 13, 1.5)
    nvgFillColor(vg, nvgRGBA(tc[1], tc[2], tc[3], 200)); nvgFill(vg)
    nvgBeginPath(vg); nvgRoundedRect(vg, x + 3, y + 3, 13, 13, 1.5)
    nvgStrokeColor(vg, nvgRGBA(255, 255, 255, 30))
    nvgStrokeWidth(vg, 0.5); nvgStroke(vg)
    nvgFontSize(vg, 12.8)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(x + 9.5, y + 9.5, TYPE_NAMES[card.type])

    -- 右上命格标记 (替代费用)
    local cc = GameConfig.CONSTELLATION_COLORS[constellation] or { 180, 175, 165 }
    local constX = x + w - 9
    local constY = y + 9
    nvgBeginPath(vg); nvgCircle(vg, constX, constY, 7.5)
    nvgFillColor(vg, nvgRGBA(38, 32, 16, 230)); nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(cc[1], cc[2], cc[3], 200))
    nvgStrokeWidth(vg, 1.3); nvgStroke(vg)
    -- 星标
    nvgFontSize(vg, 10.5); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    nvgFillColor(vg, nvgRGBA(cc[1], cc[2], cc[3], 255))
    nvgText(vg, constX, constY, "C" .. constellation, nil)

    if not hideName then
        -- 底部名条
        local nameBarH = 17
        local nameBarY = y + h - nameBarH
        local nameGrad = nvgLinearGradient(vg, x, nameBarY, x, y + h,
            nvgRGBA(30, 25, 14, 225), nvgRGBA(22, 18, 10, 240))
        nvgBeginPath(vg); nvgRoundedRect(vg, x + 1, nameBarY, w - 2, nameBarH, 0)
        nvgFillPaint(vg, nameGrad); nvgFill(vg)
        nvgBeginPath(vg)
        nvgMoveTo(vg, x + 5, nameBarY + 0.5); nvgLineTo(vg, x + w - 5, nameBarY + 0.5)
        nvgStrokeColor(vg, nvgRGBA(190, 160, 90, 55))
        nvgStrokeWidth(vg, 0.5); nvgStroke(vg)

        -- 品质菱形
        local qnx = x + w / 2
        local qny = nameBarY + 0.5
        nvgBeginPath(vg)
        nvgMoveTo(vg, qnx, qny - 2); nvgLineTo(vg, qnx + 3, qny)
        nvgLineTo(vg, qnx, qny + 2); nvgLineTo(vg, qnx - 3, qny)
        nvgClosePath(vg)
        nvgFillColor(vg, nvgRGBA(qc[1], qc[2], qc[3], 180)); nvgFill(vg)

        -- 等阶标签 (N/R/SR/SSR/限定SSR, 左对齐向右延展)
        local qTag = QUALITY_TAGS[card.quality] or "N"
        local tagH2 = 12
        local tagX2 = x + 2
        local tagY2 = nameBarY - tagH2 - 1
        -- 测量文字实际宽度，自适应标签宽
        nvgFontSize(vg, 13)
        nvgFontFaceId(vg, GetMainFont())
        local measuredW = nvgTextBounds(vg, 0, 0, qTag, nil)
        local tagW2 = math.max(14, measuredW + 8)
        nvgBeginPath(vg); nvgRoundedRect(vg, tagX2, tagY2, tagW2, tagH2, 2)
        nvgFillColor(vg, nvgRGBA(qc[1], qc[2], qc[3], 190)); nvgFill(vg)
        nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        DrawWhiteInkText(tagX2 + tagW2 / 2, tagY2 + tagH2 / 2, qTag)

        -- 名称 (左对齐，裁剪防超框)
        nvgSave(vg)
        nvgIntersectScissor(vg, x, nameBarY, w, nameBarH)
        nvgFontSize(vg, 14)
        nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)
        DrawWhiteInkText(x + 3, nameBarY + nameBarH / 2 + 1, card.name)
        nvgRestore(vg)
    end
end

function DrawDrawButton(sl)
    local bx, by = sl.drawBtnX, sl.drawBtnY
    local bw, bh = sl.drawBtnW, sl.drawBtnH
    local t = gameState.gameTime

    -- 按钮背景 (带脉冲光)
    local pulse = 0.7 + 0.3 * math.sin(t * 2.5)
    local btnGrad = nvgLinearGradient(vg, bx, by, bx, by + bh,
        nvgRGBA(40, 25, 55, 230), nvgRGBA(25, 15, 35, 245))
    nvgBeginPath(vg); nvgRoundedRect(vg, bx, by, bw, bh, 5)
    nvgFillPaint(vg, btnGrad); nvgFill(vg)

    -- 外发光
    local glowR = 8 * pulse
    local glow = nvgBoxGradient(vg, bx - glowR / 2, by - glowR / 2,
        bw + glowR, bh + glowR, 8, glowR,
        nvgRGBA(180, 120, 255, math.floor(25 * pulse)),
        nvgRGBA(180, 120, 255, 0))
    nvgBeginPath(vg)
    nvgRoundedRect(vg, bx - glowR, by - glowR, bw + glowR * 2, bh + glowR * 2, 10)
    nvgFillPaint(vg, glow); nvgFill(vg)

    -- 边框
    local borderAlpha = math.floor(100 + 60 * math.sin(t * 3))
    nvgBeginPath(vg); nvgRoundedRect(vg, bx, by, bw, bh, 5)
    nvgStrokeColor(vg, nvgRGBA(180, 130, 255, borderAlpha))
    nvgStrokeWidth(vg, 1.2); nvgStroke(vg)

    if fontId >= 0 then
        nvgFontFaceId(vg, GetMainFont())
        -- 主文字
        nvgFontSize(vg, 16.5)
        nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        nvgFillColor(vg, nvgRGBA(210, 180, 255, math.floor(220 + 35 * pulse)))
        nvgText(vg, bx + bw / 2, by + bh / 2 - 3, "武灵召唤", nil)
        -- 副文字
        nvgFontSize(vg, 10.5)
        DrawWhiteInkText(bx + bw / 2, by + bh / 2 + 10, "看广告抽卡")
    end
end

-- ============================================================================
-- 拖拽卡牌渲染 (★ 屏幕逻辑坐标, 不在游戏区域变换中)
-- ============================================================================

function DrawDragCardScreen()
    if not dragState.active or not dragState.card then return end
    local card = dragState.card
    local sl = shopLayout

    -- 卡牌尺寸 (与商店卡牌同大)
    local w = sl.cardW + 4
    local h = sl.cardH + 4
    local lx, ly = dragState.lx, dragState.ly
    local x, y = lx - w / 2, ly - h / 2

    nvgSave(vg)
    nvgGlobalAlpha(vg, 0.88)

    -- 底板
    nvgBeginPath(vg); nvgRoundedRect(vg, x, y, w, h, 4)
    nvgFillColor(vg, nvgRGBA(30, 25, 15, 230)); nvgFill(vg)

    -- 卡牌图片
    if GetHeroSheet(card) > 0 then
        local _sh2, _sc2, _sr2 = GetHeroSheetInfo(card)
        DrawCardImage(x + 2, y + 2, w - 4, h - 16, _sh2, card.row, card.col, _sc2, _sr2)
    end

    -- 品质边框
    local qc = QUALITY_COLORS[card.quality]
    nvgBeginPath(vg); nvgRoundedRect(vg, x, y, w, h, 4)
    nvgStrokeColor(vg, nvgRGBA(qc[1], qc[2], qc[3], 255))
    nvgStrokeWidth(vg, 2); nvgStroke(vg)

    if fontId >= 0 then
        nvgFontFaceId(vg, GetMainFont())

        -- 费用徽标 (左上角)
        local cardCost = GameConfig.CARD_COST[card.quality] or 5
        nvgBeginPath(vg); nvgRoundedRect(vg, x + 2, y + 2, 18, 13, 3)
        nvgFillColor(vg, nvgRGBA(20, 15, 8, 200)); nvgFill(vg)
        nvgFontSize(vg, 13.5); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        nvgFillColor(vg, nvgRGBA(120, 220, 255, 255))
        nvgText(vg, x + 11, y + 9, tostring(cardCost), nil)

        -- 命格徽标 (右上角)
        local cons = card.constellation or 0
        if cons > 0 then
            local cc = GameConfig.CONSTELLATION_COLORS[cons] or { 180, 175, 165 }
            local cBadgeX = x + w - 8
            local cBadgeY = y + 8
            nvgBeginPath(vg); nvgCircle(vg, cBadgeX, cBadgeY, 7)
            nvgFillColor(vg, nvgRGBA(cc[1], cc[2], cc[3], 200)); nvgFill(vg)
            nvgStrokeColor(vg, nvgRGBA(255, 255, 255, 120))
            nvgStrokeWidth(vg, 1); nvgStroke(vg)
            nvgFontSize(vg, 13.5); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
            DrawWhiteInkText(cBadgeX, cBadgeY, "C" .. cons)
        end

        -- 等阶标签 (N/R/SR/SSR, 左下角名条上方)
        local dqTag = QUALITY_TAGS[card.quality] or "N"
        local dqc = QUALITY_COLORS[card.quality] or { 200, 195, 180 }
        local dTagW = #dqTag > 2 and 22 or (#dqTag > 1 and 16 or 12)
        local dTagH = 11
        local dTagX = x + 2
        local dTagY = y + h - 14 - dTagH - 1
        nvgBeginPath(vg); nvgRoundedRect(vg, dTagX, dTagY, dTagW, dTagH, 2)
        nvgFillColor(vg, nvgRGBA(dqc[1], dqc[2], dqc[3], 190)); nvgFill(vg)
        nvgFontSize(vg, 12)
        nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        DrawWhiteInkText(dTagX + dTagW / 2, dTagY + dTagH / 2, dqTag)

        -- 名条
        nvgBeginPath(vg); nvgRect(vg, x, y + h - 14, w, 14)
        nvgFillColor(vg, nvgRGBA(28, 24, 14, 200)); nvgFill(vg)
        nvgFontSize(vg, 14)
        nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        DrawWhiteInkText(x + w / 2, y + h - 6, card.name)
    end

    nvgRestore(vg)
end

-- ============================================================================
-- 长按Tips浮层 (水墨卷轴)
-- ============================================================================

function DrawLongPressTip()
    -- 旧长按弹窗已废弃, 现在使用 DrawInfoPopup (单击触发)
end

function DrawInfoPopup()
    if not infoPopupState.show or not infoPopupState.card then return end
    if fontId < 0 then return end

    local card = infoPopupState.card
    local uc = UNIT_CLASS[card.unitClass]
    local qc = QUALITY_COLORS[card.quality]

    local tipW = math.min(240, screenW - 20)
    local pad = 12
    local lx = pad
    local innerW = tipW - pad * 2

    -- ===== 预计算内容高度 =====
    nvgFontFaceId(vg, GetMainFont())
    local contentH = 0
    contentH = contentH + 16 + 26 + 2   -- 顶部间距 + 名称
    contentH = contentH + 18 + 6         -- 标签行 + 分割线间距

    -- 属性面板 (3行: 属性值 + 兵符加成 + 等级/命格/费用)
    contentH = contentH + 18             -- 基础属性行
    -- 兵符加成
    local cardIdx = card.cardIdx
    local sb = cardIdx and GetSealTotalBonus(cardIdx) or nil
    local hasSealBonus = sb and (sb.atkPct > 0 or sb.defPct > 0 or sb.hpPct > 0)
    if hasSealBonus then
        contentH = contentH + 15         -- 基础值行(小字) + 已在18中含最终值
    end
    contentH = contentH + 19 + 6         -- 等级/命格/费用 + 分割线间距

    -- 技能描述高度
    local descH = 0
    if card.skill and card.skillData then
        contentH = contentH + 18         -- 技能标题
        nvgFontSize(vg, 13)
        local descText = card.skillData.desc or ""
        local bounds = nvgTextBoxBounds(vg, 0, 0, innerW, descText, nil)
        descH = bounds and (bounds[4] - bounds[2]) or 14
        contentH = contentH + descH + 6  -- 技能描述
    end

    -- 站位建议
    contentH = contentH + 6 + 16         -- 分割线 + 建议文字

    -- 兵符加成详情区块
    local sealLines = {}
    if cardIdx and sb then
        local sd = sealData[cardIdx]
        if sd and sd.slots then
            for i = 1, SEAL_MAX_SLOTS do
                local sealSlot = sd.slots[i]
                if sealSlot then
                    local effect = SEAL_SLOT_EFFECTS[i]
                    if effect then
                        local tierData = effect[sealSlot.sealQ] or effect[1]
                        local lv = sealSlot.level or 1
                        local mainVal = (tierData.main or 0) * lv
                        local subVal = (tierData.sub or 0) * lv
                        local line = {
                            slotIdx = i,
                            theme = effect.theme,
                            mainName = effect.mainName, mainVal = mainVal, mainUnit = (effect.mainKey == "extraTroops") and "" or "%",
                            subName = effect.subName, subVal = subVal,
                            level = lv,
                        }
                        sealLines[#sealLines + 1] = line
                    end
                end
            end
        end
    end
    local hasSealDetails = #sealLines > 0
    if hasSealDetails then
        contentH = contentH + 8 + 16     -- 分割线 + "兵符加成"标题
        contentH = contentH + #sealLines * 14 -- 每行兵符效果
    end

    contentH = contentH + 20             -- 底部"点击关闭"

    local tipH = contentH + 8
    if tipH > screenH - 16 then tipH = screenH - 16 end
    local tipX = (screenW - tipW) / 2
    local tipY = (screenH - tipH) / 2

    -- 遮罩
    nvgBeginPath(vg); nvgRect(vg, 0, 0, screenW, screenH)
    nvgFillColor(vg, nvgRGBA(5, 5, 12, 100)); nvgFill(vg)

    -- 卷轴底板
    nvgBeginPath(vg); nvgRoundedRect(vg, tipX, tipY, tipW, tipH, 8)
    local panelGrad = nvgLinearGradient(vg, tipX, tipY, tipX, tipY + tipH,
        nvgRGBA(42, 35, 22, 248), nvgRGBA(28, 22, 12, 252))
    nvgFillPaint(vg, panelGrad); nvgFill(vg)

    -- 品质色边框
    nvgBeginPath(vg); nvgRoundedRect(vg, tipX, tipY, tipW, tipH, 8)
    nvgStrokeColor(vg, nvgRGBA(qc[1], qc[2], qc[3], 160))
    nvgStrokeWidth(vg, 1.5); nvgStroke(vg)

    -- 顶部品质装饰线
    nvgBeginPath(vg); nvgRoundedRect(vg, tipX + 10, tipY + 6, tipW - 20, 2.5, 1)
    local decoGrad = nvgLinearGradient(vg, tipX + 10, tipY + 6, tipX + tipW - 10, tipY + 6,
        nvgRGBA(qc[1], qc[2], qc[3], 0), nvgRGBA(qc[1], qc[2], qc[3], 120))
    nvgFillPaint(vg, decoGrad); nvgFill(vg)

    local axLx = tipX + pad
    local cxTip = tipX + tipW / 2
    local ly = tipY + 16

    -- ① 名称
    nvgFontSize(vg, 24)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_TOP)
    DrawWhiteInkText(cxTip, ly, card.name)
    ly = ly + 26

    -- ② 品质 | 类型 | 兵种
    local pqTag = QUALITY_TAGS[card.quality] or "N"
    local typeName = TYPE_NAMES[card.type or 1]
    local ucName = uc and uc.name or "未知"
    local rangeTag = uc and (uc.isRanged and "远程" or "近战") or ""
    local tagLine = pqTag .. "·" .. QUALITY_NAMES[card.quality] .. "品  " .. typeName .. "  " .. ucName .. "(" .. rangeTag .. ")"
    nvgFontSize(vg, 14)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_TOP)
    nvgFillColor(vg, nvgRGBA(qc[1], qc[2], qc[3], 200))
    nvgText(vg, cxTip, ly, tagLine, nil)
    ly = ly + 18

    -- 分割线
    nvgBeginPath(vg)
    nvgMoveTo(vg, axLx, ly); nvgLineTo(vg, tipX + tipW - pad, ly)
    nvgStrokeColor(vg, nvgRGBA(160, 130, 80, 60)); nvgStrokeWidth(vg, 0.5); nvgStroke(vg)
    ly = ly + 6

    -- ③ 属性面板 (基础 or 基础+兵符)
    local lm = 1 + ((card.level or 1) - 1) * GameConfig.LEVEL_GROWTH_RATE
    local cBonus = GetConstellationBonus(card.constellation or 0)
    local rawAtk = math.floor(card.atk * cBonus.atkMult * lm)
    local rawDef = math.floor(card.def * cBonus.defMult * lm)
    local rawHp  = math.floor(card.hp  * cBonus.hpMult  * lm)

    local col3 = innerW / 3  -- 三列等分宽度
    nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_TOP)
    if hasSealBonus then
        -- 基础值行 (小字灰色)
        nvgFontSize(vg, 12)
        nvgFillColor(vg, nvgRGBA(180, 170, 155, 170))
        nvgText(vg, axLx, ly, "攻:" .. rawAtk, nil)
        nvgText(vg, axLx + col3, ly, "防:" .. rawDef, nil)
        nvgText(vg, axLx + col3 * 2, ly, "血:" .. rawHp, nil)
        ly = ly + 15

        -- 加成后最终值行
        local fAtk = math.floor(rawAtk * (1 + sb.atkPct / 100))
        local fDef = math.floor(rawDef * (1 + sb.defPct / 100))
        local fHp  = math.floor(rawHp  * (1 + sb.hpPct  / 100))
        nvgFontSize(vg, 15)
        nvgFillColor(vg, nvgRGBA(255, 120, 100, 240))
        local atkStr = "攻:" .. fAtk
        if sb.atkPct > 0 then atkStr = atkStr .. "↑" end
        nvgText(vg, axLx, ly, atkStr, nil)
        nvgFillColor(vg, nvgRGBA(100, 150, 255, 240))
        local defStr = "防:" .. fDef
        if sb.defPct > 0 then defStr = defStr .. "↑" end
        nvgText(vg, axLx + col3, ly, defStr, nil)
        nvgFillColor(vg, nvgRGBA(100, 230, 130, 240))
        local hpStr = "血:" .. fHp
        if sb.hpPct > 0 then hpStr = hpStr .. "↑" end
        nvgText(vg, axLx + col3 * 2, ly, hpStr, nil)
    else
        -- 无兵符，直接显示属性值
        nvgFontSize(vg, 15)
        nvgFillColor(vg, nvgRGBA(255, 120, 100, 240))
        nvgText(vg, axLx, ly, "攻:" .. rawAtk, nil)
        nvgFillColor(vg, nvgRGBA(100, 150, 255, 240))
        nvgText(vg, axLx + col3, ly, "防:" .. rawDef, nil)
        nvgFillColor(vg, nvgRGBA(100, 230, 130, 240))
        nvgText(vg, axLx + col3 * 2, ly, "血:" .. rawHp, nil)
    end
    ly = ly + 18

    -- ④ 等级 / 命格 / 费用
    local cons = card.constellation or 0
    local cc = GameConfig.CONSTELLATION_COLORS[cons] or { 180, 175, 165 }
    local cardCost = GameConfig.CARD_COST[card.quality] or 5
    nvgFontSize(vg, 15)
    nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_TOP)
    DrawWhiteInkText(axLx, ly, "Lv" .. (card.level or 1))
    nvgFillColor(vg, nvgRGBA(cc[1], cc[2], cc[3], 230))
    nvgText(vg, axLx + 45, ly, "C" .. cons, nil)
    nvgFillColor(vg, nvgRGBA(120, 220, 255, 230))
    nvgText(vg, axLx + 90, ly, "费用:" .. cardCost, nil)
    ly = ly + 19

    -- 分割线
    nvgBeginPath(vg)
    nvgMoveTo(vg, axLx, ly); nvgLineTo(vg, tipX + tipW - pad, ly)
    nvgStrokeColor(vg, nvgRGBA(160, 130, 80, 60)); nvgStrokeWidth(vg, 0.5); nvgStroke(vg)
    ly = ly + 6

    -- ⑤ 技能信息
    if card.skill and card.skillData then
        nvgFontSize(vg, 15)
        nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_TOP)
        nvgFillColor(vg, nvgRGBA(255, 200, 80, 240))
        nvgText(vg, axLx, ly, "技能: " .. card.skill, nil)
        nvgFillColor(vg, nvgRGBA(180, 170, 150, 180))
        nvgText(vg, tipX + tipW - pad - 50, ly, "CD:" .. (card.skillData.cd or "?") .. "s", nil)
        ly = ly + 18
        -- 技能描述 (自动换行)
        nvgFontSize(vg, 13)
        nvgFillColor(vg, nvgRGBA(200, 195, 180, 200))
        local descText2 = card.skillData.desc or ""
        nvgTextBox(vg, axLx, ly, innerW, descText2, nil)
        ly = ly + descH + 6
    end

    -- ⑥ 站位建议
    nvgBeginPath(vg)
    nvgMoveTo(vg, axLx, ly); nvgLineTo(vg, tipX + tipW - pad, ly)
    nvgStrokeColor(vg, nvgRGBA(160, 130, 80, 60)); nvgStrokeWidth(vg, 0.5); nvgStroke(vg)
    ly = ly + 6
    nvgFontSize(vg, 13)
    nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_TOP)
    local posAdvice = ""
    local posColor = { 180, 220, 255 }
    if card.unitClass == "SHIELD" or card.unitClass == "CAVALRY" or card.unitClass == "LANCER" then
        posAdvice = "前排★ 出兵概率+50%"
        posColor = { 100, 180, 255 }
    elseif card.unitClass == "ARCHER" or card.unitClass == "MAGE" then
        posAdvice = "后排★ 出兵概率+50%"
        posColor = { 255, 180, 80 }
    elseif card.unitClass == "HEALER" then
        posAdvice = "后排★ 出兵概率+60%"
        posColor = { 100, 230, 130 }
    elseif card.unitClass == "ASSASSIN" then
        posAdvice = "任意★ 出兵概率+20%"
        posColor = { 220, 140, 255 }
    elseif card.unitClass == "BEAST" then
        posAdvice = "前排★ 出兵概率+50%"
        posColor = { 255, 140, 100 }
    else
        posAdvice = "前排★ 出兵概率+50%"
        posColor = { 240, 220, 180 }
    end
    nvgFillColor(vg, nvgRGBA(posColor[1], posColor[2], posColor[3], 220))
    nvgText(vg, axLx, ly, posAdvice, nil)
    ly = ly + 16

    -- ⑦ 兵符加成详情
    if hasSealDetails then
        -- 分割线
        nvgBeginPath(vg)
        nvgMoveTo(vg, axLx, ly); nvgLineTo(vg, tipX + tipW - pad, ly)
        nvgStrokeColor(vg, nvgRGBA(160, 130, 80, 60)); nvgStrokeWidth(vg, 0.5); nvgStroke(vg)
        ly = ly + 5
        -- 标题
        nvgFontSize(vg, 14)
        nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_TOP)
        nvgFillColor(vg, nvgRGBA(255, 215, 80, 230))
        nvgText(vg, axLx, ly, "兵符加成", nil)
        ly = ly + 16
        -- 每条兵符效果
        nvgFontSize(vg, 11)
        for _, sl in ipairs(sealLines) do
            local tc2 = SEAL_SLOT_THEME_COLORS[sl.slotIdx] or { 200, 200, 200 }
            nvgFillColor(vg, nvgRGBA(tc2[1], tc2[2], tc2[3], 210))
            local txt = SEAL_SLOT_NAMES[sl.slotIdx] .. " "
            if sl.mainName then
                txt = txt .. sl.mainName .. "+" .. string.format("%.0f", sl.mainVal) .. sl.mainUnit
            end
            if sl.subName and sl.subVal > 0 then
                txt = txt .. " " .. sl.subName .. "+" .. string.format("%.0f", sl.subVal) .. "%"
            end
            txt = txt .. " L" .. sl.level
            nvgText(vg, axLx, ly, txt, nil)
            ly = ly + 14
        end
    end

    -- 关闭提示
    nvgFontSize(vg, 12)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_BOTTOM)
    nvgFillColor(vg, nvgRGBA(150, 140, 130, 120))
    nvgText(vg, cxTip, tipY + tipH - 4, "点击任意处关闭", nil)
end

-- ============================================================================
-- 飘字 & 波次过渡 (设计坐标)
-- ============================================================================

function DrawFloatTexts()
    if fontId < 0 then return end
    nvgFontFaceId(vg, GetMainFont())
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    for _, ft in ipairs(floatTexts) do
        local p = ft.timer / ft.duration
        local a = math.floor(255 * (1 - p))
        local py = ft.y - p * 60
        nvgFontSize(vg, ft.fontSize)
        nvgFillColor(vg, nvgRGBA(ft.color[1], ft.color[2], ft.color[3], a))
        nvgText(vg, ft.x, py, ft.text, nil)
    end
end

-- ============================================================================
-- 首页菜单 (暗铜NanoVG风格 + 模块下载/讨伐)
-- ============================================================================

function DrawMenuScreen()
    if gameState.phase ~= "MENU" then return end

    local W = DESIGN_W
    local H = DESIGN_H
    local cx = W / 2
    local t = menuAnimTimer

    -- 1. 统一菜单背景
    DrawMenuBg(W, H)

    nvgFontFaceId(vg, GetMainFont())

    -- ===========================
    -- 通用: 侧栏按钮绘制函数
    -- ===========================
    local function DrawSideBtn(bx, by, bw, bh, label, colors, bPulse, showGlow, iconImg)
        -- 纯图标+文字，无任何背景
        if iconImg and IsImageReady(iconImg) then
            local iconSize = math.floor(math.min(bw * 0.70, bh * 0.60))
            local iconX = bx + (bw - iconSize) / 2
            local iconY = by + 3
            local pat = nvgImagePattern(vg, iconX, iconY, iconSize, iconSize, 0, iconImg, 1.0)
            nvgBeginPath(vg); nvgRect(vg, iconX, iconY, iconSize, iconSize)
            nvgFillPaint(vg, pat); nvgFill(vg)
            -- 文字
            nvgFontFaceId(vg, GetMainFont())
            nvgFontSize(vg, 20)
            nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_BOTTOM)
            DrawWhiteInkText(bx + bw / 2, by + bh - 1, label)
        else
            nvgFontFaceId(vg, GetMainFont())
            nvgFontSize(vg, 25)
            nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
            DrawWhiteInkText(bx + bw / 2, by + bh / 2, label)
        end
    end

    -- ===========================
    -- 2. 标题卷轴 (中央上部)
    -- ===========================
    local titleW = 440
    local titleH = 440 * 343 / 512
    local titleY = H * 0.09
    local titleX = cx - titleW / 2

    if IsImageReady(IMG.titleScroll) then
        local pat = nvgImagePattern(vg, titleX, titleY, titleW, titleH, 0, IMG.titleScroll, 1.0)
        nvgBeginPath(vg); nvgRect(vg, titleX, titleY, titleW, titleH)
        nvgFillPaint(vg, pat); nvgFill(vg)
    end

    -- 标题文字
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    nvgFontFaceId(vg, GetMainFont())
    local mainTitleY = titleY + titleH * 0.48
    nvgFontSize(vg, 52)
    nvgFillColor(vg, nvgRGBA(0, 0, 0, 220))
    for _, off in ipairs({{-2,0},{2,0},{0,-2},{0,2},{-1.4,-1.4},{1.4,-1.4},{-1.4,1.4},{1.4,1.4}}) do
        _nvgTextOrig(vg, cx + off[1], mainTitleY + off[2], "三国武灵录", nil)
    end
    nvgFillColor(vg, nvgRGBA(255, 255, 255, 255))
    _nvgTextOrig(vg, cx, mainTitleY, "三国武灵录", nil)

    local subTitleY = mainTitleY + 36
    nvgFontSize(vg, 26)
    nvgFillColor(vg, nvgRGBA(0, 0, 0, 200))
    for _, off in ipairs({{-1,0},{1,0},{0,-1},{0,1}}) do
        _nvgTextOrig(vg, cx + off[1], subTitleY + off[2], "乱世征途", nil)
    end
    nvgFillColor(vg, nvgRGBA(255, 250, 240, 240))
    _nvgTextOrig(vg, cx, subTitleY, "乱世征途", nil)

    -- ===========================
    -- 3. 中央角色展示区 (标题下方到底栏之间)
    -- ===========================
    local centerAreaTop = titleY + titleH + 10
    local bottomBarH = 96
    local bottomBarY = H - bottomBarH - 8
    local centerAreaBottom = bottomBarY - 10



    -- ===========================
    -- 4. 左侧栏 (竖排功能按钮, 支持滚动)
    -- ===========================
    local sideBtnW = 100
    local sideBtnH = 78
    local sideGap = 7
    local sideX = 6
    local leftEndY = bottomBarY - 6       -- 底部留出间距，不与底栏重叠
    local leftStartY = leftEndY - 8 * sideBtnH - 7 * sideGap - 6  -- 上移: 确保至少8个按钮可见
    local leftViewH = leftEndY - leftStartY

    -- 左侧按钮配置 (带图标)
    local leftButtons = {
        { label = "阵营",   key = "faction",  colors = {70, 55, 30},  mod = nil,                   icon = IMG.menuIcons and IMG.menuIcons[8] },
        { label = "好友",   key = "friends",  colors = {40, 65, 70},  mod = nil,                   icon = IMG.menuIcons and IMG.menuIcons[9] },
        { label = "交易行", key = "trade",    colors = {75, 55, 35},  mod = nil,                   icon = IMG.menuIcons and IMG.menuIcons[14] },
        { label = "编队",   key = "formation", colors = {65, 50, 55},  mod = nil,                   icon = IMG.menuIcons and IMG.menuIcons[15] },
        { label = "邮件",   key = "mailBox",  colors = {45, 45, 70},  mod = nil,                   icon = IMG.menuIcons and IMG.menuIcons[10] },
        { label = "武灵录", key = "codex",     colors = {60, 45, 80},  mod = moduleState.heroes,    icon = IMG.menuIcons and IMG.menuIcons[1] },
        { label = "兵甲",   key = "equip",     colors = {50, 60, 80},  mod = moduleState.equipment, icon = IMG.menuIcons and IMG.menuIcons[2] },
        { label = "兵甲图录", key = "equipCodex", colors = {45, 55, 75}, mod = moduleState.equipment, icon = IMG.menuIcons and IMG.menuIcons[3] },
        { label = "武技",   key = "skillCodex", colors = {55, 40, 75},  mod = moduleState.skills,    icon = IMG.menuIcons and IMG.menuIcons[4] },
        { label = "天命赐福", key = "welfare",  colors = {80, 50, 40},  mod = nil,                   icon = IMG.menuIcons and IMG.menuIcons[5] },
        { label = "每日任务", key = "progress", colors = {50, 65, 50},  mod = nil,                   icon = IMG.menuIcons and IMG.menuIcons[6] },
    }

    -- 计算内容总高度
    local leftContentH = #leftButtons * sideBtnH + (#leftButtons - 1) * sideGap
    local leftMaxScroll = math.max(0, leftContentH - leftViewH)

    -- 更新滚动状态的元信息 (供拖拽交互使用)
    leftSidebarScroll.contentH = leftContentH
    leftSidebarScroll.viewH = leftViewH
    leftSidebarScroll.areaRect = { x = 0, y = leftStartY, w = sideBtnW + sideX * 2, h = leftViewH }

    -- 限制滚动范围
    leftSidebarScroll.y = math.max(0, math.min(leftSidebarScroll.y, leftMaxScroll))
    local scrollOff = leftSidebarScroll.y

    -- 开启裁剪区域
    nvgSave(vg)
    nvgScissor(vg, 0, leftStartY, sideBtnW + sideX * 2 + 4, leftViewH)

    local leftRects = {}
    for i, lb in ipairs(leftButtons) do
        local by = leftStartY + (i - 1) * (sideBtnH + sideGap) - scrollOff
        -- 仅渲染可见范围内的按钮
        if by + sideBtnH > leftStartY - 10 and by < leftEndY + 10 then
            local bPulse = 0.85 + 0.15 * math.sin(t * 2.0 + i)
            DrawSideBtn(sideX, by, sideBtnW, sideBtnH, lb.label, lb.colors, bPulse, false, lb.icon)

            -- 模块未就绪遮罩
            if lb.mod and not lb.mod.ready then
                nvgBeginPath(vg); nvgRoundedRect(vg, sideX, by, sideBtnW, sideBtnH, 8)
                nvgFillColor(vg, nvgRGBA(10, 12, 20, 140)); nvgFill(vg)
                nvgFontFaceId(vg, GetMainFont()); nvgFontSize(vg, 19)
                nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
                DrawWhiteInkText(sideX + sideBtnW / 2, by + sideBtnH / 2, math.floor(lb.mod.progress * 100) .. "%")
            end
        end
        leftRects[i] = { x = sideX, y = by, w = sideBtnW, h = sideBtnH }
        menuBtnRects[lb.key] = leftRects[i]
    end

    -- 左侧红点 (按 key 查找，在裁剪区域内绘制)
    local function DrawKeyRedDot(key)
        local r = menuBtnRects[key]
        if r then DrawRedDot(r.x + r.w - 6, r.y + 6, 6) end
    end
    if HasEquipRedDot() then DrawKeyRedDot("equip") end
    if HasSkillRedDot() then DrawKeyRedDot("skillCodex") end
    if HasProgressRedDot() then DrawKeyRedDot("progress") end
    -- 邮件红点
    local hasUnreadMail = false
    for _, md in ipairs(welfareState.mailDefs) do
        if not welfareState.mail.claimed[md.id] then hasUnreadMail = true; break end
    end
    if not hasUnreadMail then
        for _, cm in ipairs(CloudManager._mailInbox or {}) do
            if not CloudManager.IsMailClaimed(cm.id) and #(cm.rewards or {}) > 0 then
                hasUnreadMail = true; break
            end
        end
    end
    if hasUnreadMail then DrawKeyRedDot("mailBox") end
    -- 好友请求红点 (定时轮询, 首次5秒后检查, 之后每30秒)
    local now = os.time()
    local friendCheckInterval = friendsUI.pendingReqChecked and 30 or 5  -- 首次5秒, 之后30秒
    if now - friendsUI.lastReqCheckTime >= friendCheckInterval
       and rawget(_G, "CloudManager")
       and CloudManager.CheckIncomingRequests then
        friendsUI.lastReqCheckTime = now
        CloudManager.CheckIncomingRequests(function(reqs)
            friendsUI.pendingReqCount = reqs and #reqs or 0
            friendsUI.pendingReqChecked = true
        end)
    end
    if friendsUI.pendingReqCount > 0 then DrawKeyRedDot("friends") end
    -- 阵营申请红点 (仅盟主/副盟主, 定时轮询, 首次5秒后检查)
    do
        local fInfo = rawget(_G, "CloudManager") and CloudManager.GetFactionInfo and CloudManager.GetFactionInfo()
        if fInfo and (fInfo.role == "leader" or fInfo.role == "vice_leader") then
            local now2 = os.time()
            local factionCheckInterval = factionUI.pendingAppChecked and 30 or 5
            if now2 - factionUI.lastAppCheckTime >= factionCheckInterval
               and CloudManager.CheckFactionApplications then
                factionUI.lastAppCheckTime = now2
                CloudManager.CheckFactionApplications(function(apps)
                    factionUI.pendingAppCount = apps and #apps or 0
                    factionUI.pendingAppChecked = true
                end)
            end
            if factionUI.pendingAppCount > 0 then DrawKeyRedDot("faction") end
        end
    end

    -- 结束裁剪
    nvgRestore(vg)

    -- 滚动箭头提示 (当内容超出可见区域时，在侧栏外侧显示动态箭头)
    if leftMaxScroll > 0 then
        local arrowX = sideX + sideBtnW / 2
        local arrowBob = math.sin(t * 3.0) * 4  -- 上下浮动动画
        -- 上箭头 (可向上滚动时显示)
        if scrollOff > 2 then
            local upY = leftStartY - 14 + arrowBob
            local arrowA = math.min(200, math.floor(scrollOff / leftMaxScroll * 200 + 60))
            nvgFontFaceId(vg, GetMainFont()); nvgFontSize(vg, 18)
            nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
            nvgFillColor(vg, nvgRGBA(255, 200, 100, arrowA))
            nvgText(vg, arrowX, upY, "▲", nil)
        end
        -- 下箭头 (可向下滚动时显示)
        if scrollOff < leftMaxScroll - 2 then
            local downY = leftEndY + 4 - arrowBob
            local arrowA = math.min(200, math.floor((1 - scrollOff / leftMaxScroll) * 200 + 60))
            nvgFontFaceId(vg, GetMainFont()); nvgFontSize(vg, 18)
            nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
            nvgFillColor(vg, nvgRGBA(255, 200, 100, arrowA))
            nvgText(vg, arrowX, downY, "▼", nil)
        end
    end

    -- ===========================
    -- 5. 右侧栏 (挑战模式按钮)
    -- ===========================
    local rightX = W - sideBtnW - 6
    local rightStartY = centerAreaTop + 12
    local rTier = GetRankedTier(rankedState.score)
    local rightButtons = {
        { label = "排位", colors = {rTier.color[1], rTier.color[2], rTier.color[3]}, stateRef = rankedState, icon = IMG.menuIcons and IMG.menuIcons[7] },  -- 排位专用图标
        { label = "爬塔", colors = {40, 80, 140}, stateRef = towerState, icon = IMG.sealItem2 },
        { label = "讨伐", colors = {90, 50, 140}, stateRef = abyssState, icon = IMG.taofaIcon },
        { label = "副本", colors = {40, 120, 90}, stateRef = dailyDungeonState, icon = IMG.sealItem3 },
        { label = "探索", colors = {60, 160, 130}, stateRef = resourceDungeonState, icon = IMG.sealItem1 },
    }

    for i, rb in ipairs(rightButtons) do
        local by = rightStartY + (i - 1) * (sideBtnH + sideGap)
        local bPulse = 0.85 + 0.15 * math.sin(t * 2.2 + i * 0.8)
        DrawSideBtn(rightX, by, sideBtnW, sideBtnH, rb.label, rb.colors, bPulse, false, rb.icon)
        rb.stateRef.btnRect = { x = rightX, y = by, w = sideBtnW, h = sideBtnH }
        -- 战斗模块未就绪遮罩
        if not moduleState.battle.ready then
            nvgBeginPath(vg); nvgRoundedRect(vg, rightX, by, sideBtnW, sideBtnH, 8)
            nvgFillColor(vg, nvgRGBA(10, 12, 20, 140)); nvgFill(vg)
            nvgFontFaceId(vg, GetMainFont()); nvgFontSize(vg, 19)
            nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
            DrawWhiteInkText(rightX + sideBtnW / 2, by + sideBtnH / 2, math.floor(moduleState.battle.progress * 100) .. "%")
        end
    end

    -- 30s 打桩按钮 (右侧栏底部)
    local dummyBtnW = sideBtnW
    local dummyBtnH = 38
    local dummyBtnX = rightX
    local dummyBtnY = rightStartY + #rightButtons * (sideBtnH + sideGap) + 4
    local dummyPulse = 0.85 + 0.15 * math.sin(t * 3.5)
    nvgBeginPath(vg); nvgRoundedRect(vg, dummyBtnX + 2, dummyBtnY + 2, dummyBtnW, dummyBtnH, 6)
    nvgFillColor(vg, nvgRGBA(0, 0, 0, 50)); nvgFill(vg)
    nvgBeginPath(vg); nvgRoundedRect(vg, dummyBtnX, dummyBtnY, dummyBtnW, dummyBtnH, 6)
    local dummyGrad = nvgLinearGradient(vg, dummyBtnX, dummyBtnY, dummyBtnX, dummyBtnY + dummyBtnH,
        nvgRGBA(180, 55, 30, math.floor(220 * dummyPulse)),
        nvgRGBA(140, 30, 15, math.floor(235 * dummyPulse)))
    nvgFillPaint(vg, dummyGrad); nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(20, 15, 10, math.floor(200 * dummyPulse))); nvgStrokeWidth(vg, 2.0); nvgStroke(vg)
    nvgFontFaceId(vg, GetMainFont()); nvgFontSize(vg, 24)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(dummyBtnX + dummyBtnW / 2, dummyBtnY + dummyBtnH / 2, "30s")
    dummyState.btnRect = { x = dummyBtnX, y = dummyBtnY, w = dummyBtnW, h = dummyBtnH }
    -- 30s打桩 战斗模块未就绪遮罩
    if not moduleState.battle.ready then
        nvgBeginPath(vg); nvgRoundedRect(vg, dummyBtnX, dummyBtnY, dummyBtnW, dummyBtnH, 6)
        nvgFillColor(vg, nvgRGBA(10, 12, 20, 160)); nvgFill(vg)
    end

    -- ===========================
    -- 6. 底部操作栏 (横排5按钮, 仿参考图)
    -- ===========================
    -- 底栏背景 (国风暗底横条)
    local barBgGrad = nvgLinearGradient(vg, 0, bottomBarY - 8, 0, bottomBarY + bottomBarH,
        nvgRGBA(15, 10, 25, 0), nvgRGBA(15, 10, 25, 200))
    nvgBeginPath(vg); nvgRect(vg, 0, bottomBarY - 8, W, bottomBarH + 16)
    nvgFillPaint(vg, barBgGrad); nvgFill(vg)
    -- 顶部金色分隔线
    local sepGradL = nvgLinearGradient(vg, 0, bottomBarY - 2, W, bottomBarY - 2,
        nvgRGBA(255, 200, 80, 0), nvgRGBA(255, 200, 80, 150))
    nvgBeginPath(vg); nvgMoveTo(vg, 0, bottomBarY - 2); nvgLineTo(vg, cx, bottomBarY - 2)
    nvgStrokeWidth(vg, 1.5); nvgStrokePaint(vg, sepGradL); nvgStroke(vg)
    local sepGradR = nvgLinearGradient(vg, cx, bottomBarY - 2, W, bottomBarY - 2,
        nvgRGBA(255, 200, 80, 150), nvgRGBA(255, 200, 80, 0))
    nvgBeginPath(vg); nvgMoveTo(vg, cx, bottomBarY - 2); nvgLineTo(vg, W, bottomBarY - 2)
    nvgStrokeWidth(vg, 1.5); nvgStrokePaint(vg, sepGradR); nvgStroke(vg)

    -- 底栏按钮配置 (5个, 带图标)
    local botBtnCount = 5
    local botPad = 10
    local botTotalW = W - botPad * 2
    local botBtnW = (botTotalW - (botBtnCount - 1) * 6) / botBtnCount
    local botBtnH = 82
    local botBtnY = bottomBarY + (bottomBarH - botBtnH) / 2

    local bottomButtons = {
        { label = "设置",     key = "settings", colors = {40, 35, 55},  primary = false, mod = nil, icon = IMG.menuIcons and IMG.menuIcons[13] },
        { label = "战令",     key = "battlepass",colors = {120, 70, 30}, primary = false, mod = nil, icon = IMG.dragonPortal },
        { label = "战力榜",   key = "powerRank",colors = {35, 40, 65},  primary = false, mod = nil, icon = IMG.menuIcons and IMG.menuIcons[12] },
        { label = "召唤武灵", key = "gacha",    colors = {130, 30, 60}, primary = false, mod = moduleState.heroes, icon = IMG.menuIcons and IMG.menuIcons[11] },
        { label = "乱世征途", key = "battle",   colors = {180, 45, 25}, primary = true,  mod = moduleState.battle, icon = IMG.abyssTicket },
    }

    local pulse = 0.7 + 0.3 * math.sin(t * 2.5)
    for i, bb in ipairs(bottomButtons) do
        local bx = botPad + (i - 1) * (botBtnW + 6)
        local by = botBtnY
        local isPrimary = bb.primary
        local bPulse = isPrimary and pulse or (0.85 + 0.15 * math.sin(t * 2.0 + i))

        -- 纯图标+文字，无任何背景
        local hasIcon = bb.icon and IsImageReady(bb.icon)
        if hasIcon then
            local iconSize
            if isPrimary then
                iconSize = math.floor(math.min(botBtnW * 0.80, botBtnH * 0.80))
            else
                iconSize = math.floor(math.min(botBtnW * 0.62, botBtnH * 0.62))
            end
            local iconX = bx + (botBtnW - iconSize) / 2
            local iconY = isPrimary and (by - 4) or (by + 2)
            local pat = nvgImagePattern(vg, iconX, iconY, iconSize, iconSize, 0, bb.icon, 1.0)
            nvgBeginPath(vg); nvgRect(vg, iconX, iconY, iconSize, iconSize)
            nvgFillPaint(vg, pat); nvgFill(vg)
            -- 文字
            nvgFontFaceId(vg, GetMainFont())
            nvgFontSize(vg, isPrimary and 20 or 19)
            nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_BOTTOM)
            DrawWhiteInkText(bx + botBtnW / 2, by + botBtnH - 1, bb.label)
        else
            nvgFontFaceId(vg, GetMainFont())
            local fontSize = isPrimary and 28 or 25
            nvgFontSize(vg, fontSize)
            nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
            DrawWhiteInkText(bx + botBtnW / 2, by + botBtnH / 2, bb.label)
        end

        -- 存储点击区域
        local rect = { x = bx, y = by, w = botBtnW, h = botBtnH }
        -- 模块未就绪遮罩 (通用)
        if bb.mod and not bb.mod.ready then
            nvgBeginPath(vg); nvgRoundedRect(vg, bx, by, botBtnW, botBtnH, 8)
            nvgFillColor(vg, nvgRGBA(10, 12, 20, 140)); nvgFill(vg)
            nvgFontFaceId(vg, GetMainFont()); nvgFontSize(vg, 19)
            nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
            DrawWhiteInkText(bx + botBtnW/2, by + botBtnH/2, math.floor(bb.mod.progress * 100) .. "%")
        end
        if bb.key == "battle" then
            menuBtnRects.battle = rect
        elseif bb.key == "gacha" then
            menuBtnRects.gacha = rect
            -- 召唤红点
            local hasComposable = false
            for cardIdx2, cnt in pairs(heroFragments) do
                local card2 = HERO_CARDS[cardIdx2]
                if card2 then
                    local need = HERO_FRAG_EXCHANGE[card2.quality] or 80
                    if cnt >= need then hasComposable = true; break end
                end
            end
            if not hasComposable then
                for _, cnt in pairs(skillFragments) do
                    if cnt >= SKILL_FRAG_EXCHANGE then hasComposable = true; break end
                end
            end
            if hasComposable then DrawRedDot(bx + botBtnW - 6, by + 6, 6) end
        elseif bb.key == "battlepass" then
            menuBtnRects.battlepass = rect
            -- 战令红点
            if HasBattlePassRedDot() then DrawRedDot(bx + botBtnW - 6, by + 6, 6) end
        elseif bb.key == "powerRank" then
            menuBtnRects.powerRank = rect
        elseif bb.key == "settings" then
            settingsPage.btnRect = rect
        end
    end

    menuBtnRects.editor = nil

    -- ===========================
    -- 6.5 世界聊天 (底栏上方, 正中)
    -- ===========================
    do
        local msgs = CloudManager.GetWorldChatMessages()
        worldChatUI.miniAnim = (worldChatUI.miniAnim or 0) + (1.0 / 60.0)

        if not worldChatUI.expanded then
            -- ── 小窗模式: 显示最新一条消息 ──
            local miniW = math.min(W * 0.6, 340)
            local miniH = 32
            local miniX = (W - miniW) / 2
            local miniY = bottomBarY - miniH - 6
            -- 半透明背景
            nvgBeginPath(vg); nvgRoundedRect(vg, miniX, miniY, miniW, miniH, 6)
            nvgFillColor(vg, nvgRGBA(10, 10, 20, 160)); nvgFill(vg)
            nvgStrokeColor(vg, nvgRGBA(120, 100, 80, 100)); nvgStrokeWidth(vg, 0.8); nvgStroke(vg)
            -- 频道标签
            nvgFontFaceId(vg, GetMainFont()); nvgFontSize(vg, 13)
            nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)
            nvgFillColor(vg, nvgRGBA(255, 200, 80, 220))
            nvgText(vg, miniX + 8, miniY + miniH / 2, "【世界】", nil)
            -- 最新消息内容
            if #msgs > 0 then
                local last = msgs[#msgs]
                local displayText = (last.name or "?") .. ": " .. (last.text or "")
                if utf8.len(displayText) > 20 then
                    displayText = string.sub(displayText, 1, utf8.offset(displayText, 21) - 1) .. "..."
                end
                nvgFontSize(vg, 14); nvgFillColor(vg, nvgRGBA(220, 220, 220, 200))
                nvgText(vg, miniX + 58, miniY + miniH / 2, displayText, nil)
            else
                nvgFontSize(vg, 13); nvgFillColor(vg, nvgRGBA(150, 150, 150, 150))
                nvgText(vg, miniX + 58, miniY + miniH / 2, "点击打开世界聊天...", nil)
            end
            menuBtnRects.worldChatMini = { x = miniX, y = miniY, w = miniW, h = miniH }
        else
            -- ── 展开模式: 大聊天窗口 ──
            local chatW = math.min(W * 0.88, 460)
            local chatH = math.min(H * 0.55, 420)
            local chatX = (W - chatW) / 2
            local chatY = (H - chatH) / 2

            -- 遮罩
            nvgBeginPath(vg); nvgRect(vg, 0, 0, W, H)
            nvgFillColor(vg, nvgRGBA(0, 0, 0, 120)); nvgFill(vg)

            -- 窗口背景
            nvgBeginPath(vg); nvgRoundedRect(vg, chatX, chatY, chatW, chatH, 12)
            nvgFillColor(vg, nvgRGBA(18, 15, 28, 240)); nvgFill(vg)
            nvgStrokeColor(vg, nvgRGBA(160, 130, 80, 150)); nvgStrokeWidth(vg, 1.5); nvgStroke(vg)

            -- 标题栏
            local titleH2 = 36
            nvgBeginPath(vg); nvgRoundedRect(vg, chatX, chatY, chatW, titleH2, 12)
            nvgFillColor(vg, nvgRGBA(40, 30, 50, 200)); nvgFill(vg)
            nvgFontFaceId(vg, GetMainFont()); nvgFontSize(vg, 20)
            nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
            nvgFillColor(vg, nvgRGBA(255, 220, 120, 240))
            nvgText(vg, chatX + chatW / 2, chatY + titleH2 / 2, "世界聊天", nil)
            -- 关闭按钮
            local closeBtnS = 28
            local closeBtnX = chatX + chatW - closeBtnS - 4
            local closeBtnY2 = chatY + (titleH2 - closeBtnS) / 2
            nvgFontSize(vg, 22); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
            nvgFillColor(vg, nvgRGBA(200, 160, 160, 200))
            nvgText(vg, closeBtnX + closeBtnS / 2, closeBtnY2 + closeBtnS / 2, "X", nil)
            menuBtnRects.worldChatClose = { x = closeBtnX, y = closeBtnY2, w = closeBtnS, h = closeBtnS }

            -- 消息区域
            local msgAreaY = chatY + titleH2 + 4
            local inputH = 40
            local msgAreaH = chatH - titleH2 - inputH - 12
            nvgSave(vg)
            nvgScissor(vg, chatX + 4, msgAreaY, chatW - 8, msgAreaH)

            local avS = 24  -- 头像尺寸
            local lineH = avS + 6  -- 每条消息行高
            local maxVisible = math.floor(msgAreaH / lineH)
            -- 自动滚到底
            if #msgs ~= worldChatUI.lastMsgCount then
                worldChatUI.lastMsgCount = #msgs
                worldChatUI.scrollOffset = math.max(0, #msgs - maxVisible)
            end
            local startIdx = math.max(1, #msgs - maxVisible - worldChatUI.scrollOffset + 1)
            local endIdx = math.min(#msgs, startIdx + maxVisible - 1)

            worldChatUI._avatarRects = {}
            for i = startIdx, endIdx do
                local m = msgs[i]
                local row = i - startIdx
                local my2 = msgAreaY + row * lineH + 3
                -- 头像 (可点击)
                local avX = chatX + 8
                local avY = my2
                local avIdx = m.av or 1
                if IMG.avatarSheet >= 0 then
                    local avData = AVATAR_DATA[avIdx] or AVATAR_DATA[1]
                    local imgW2, imgH2 = 512, 768
                    local cellW2 = imgW2 / AVATAR_COLS
                    local cellH2 = imgH2 / AVATAR_ROWS
                    local sx2 = avData.col * cellW2
                    local sy2 = avData.row * cellH2
                    -- 头像底框
                    nvgBeginPath(vg); nvgRoundedRect(vg, avX - 1, avY - 1, avS + 2, avS + 2, 4)
                    nvgFillColor(vg, nvgRGBA(30, 25, 40, 200)); nvgFill(vg)
                    nvgStrokeColor(vg, nvgRGBA(120, 100, 70, 150)); nvgStrokeWidth(vg, 0.8); nvgStroke(vg)
                    local pat2 = nvgImagePattern(vg, avX - sx2 * (avS / cellW2),
                        avY - sy2 * (avS / cellH2),
                        imgW2 * (avS / cellW2), imgH2 * (avS / cellH2), 0, IMG.avatarSheet, 1.0)
                    nvgBeginPath(vg); nvgRoundedRect(vg, avX, avY, avS, avS, 3)
                    nvgFillPaint(vg, pat2); nvgFill(vg)
                else
                    -- 无头像图时画默认色块
                    nvgBeginPath(vg); nvgRoundedRect(vg, avX, avY, avS, avS, 3)
                    nvgFillColor(vg, nvgRGBA(60, 50, 70, 200)); nvgFill(vg)
                end
                -- 记录头像点击区域
                if m.uid and m.uid > 0 then
                    worldChatUI._avatarRects[#worldChatUI._avatarRects + 1] = {
                        x = avX, y = avY, w = avS, h = avS,
                        uid = m.uid, name = m.name or "???", av = avIdx,
                    }
                end
                -- 名字
                local textX = avX + avS + 6
                nvgFontFaceId(vg, GetMainFont()); nvgFontSize(vg, 13)
                nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_TOP)
                nvgFillColor(vg, nvgRGBA(255, 200, 80, 220))
                local nameOnlyStr = m.name or "???"
                nvgText(vg, textX, my2, nameOnlyStr, nil)
                -- 内容 (第二行)
                nvgFontSize(vg, 14)
                nvgFillColor(vg, nvgRGBA(230, 230, 230, 220))
                nvgText(vg, textX, my2 + 14, m.text or "", nil)
            end
            nvgRestore(vg)

            -- 玩家信息弹窗（点击头像弹出：头像 + 名字 + 添加好友按钮）
            if worldChatUI.namePopup then
                local pp = worldChatUI.namePopup
                local ppW, ppH = 160, 60
                local ppX = math.min(pp.x + avS + 4, chatX + chatW - ppW - 8)
                local ppY = pp.y - 4
                if ppY + ppH > chatY + chatH - 50 then ppY = pp.y - ppH - 4 end
                if ppY < chatY + titleH2 then ppY = chatY + titleH2 + 4 end
                -- 弹窗背景
                nvgBeginPath(vg); nvgRoundedRect(vg, ppX, ppY, ppW, ppH, 8)
                nvgFillColor(vg, nvgRGBA(40, 35, 55, 245)); nvgFill(vg)
                nvgStrokeColor(vg, nvgRGBA(180, 160, 100, 200)); nvgStrokeWidth(vg, 1.2); nvgStroke(vg)
                -- 弹窗内头像
                local ppAvS = 32
                local ppAvX = ppX + 8
                local ppAvY = ppY + (ppH - ppAvS) / 2
                local ppAvIdx = pp.av or 1
                if IMG.avatarSheet >= 0 then
                    local avData = AVATAR_DATA[ppAvIdx] or AVATAR_DATA[1]
                    local imgW2, imgH2 = 512, 768
                    local cellW2 = imgW2 / AVATAR_COLS
                    local cellH2 = imgH2 / AVATAR_ROWS
                    local sx2 = avData.col * cellW2
                    local sy2 = avData.row * cellH2
                    nvgBeginPath(vg); nvgRoundedRect(vg, ppAvX - 1, ppAvY - 1, ppAvS + 2, ppAvS + 2, 4)
                    nvgFillColor(vg, nvgRGBA(20, 15, 30, 200)); nvgFill(vg)
                    nvgStrokeColor(vg, nvgRGBA(140, 120, 80, 160)); nvgStrokeWidth(vg, 0.8); nvgStroke(vg)
                    local pat3 = nvgImagePattern(vg, ppAvX - sx2 * (ppAvS / cellW2),
                        ppAvY - sy2 * (ppAvS / cellH2),
                        imgW2 * (ppAvS / cellW2), imgH2 * (ppAvS / cellH2), 0, IMG.avatarSheet, 1.0)
                    nvgBeginPath(vg); nvgRoundedRect(vg, ppAvX, ppAvY, ppAvS, ppAvS, 3)
                    nvgFillPaint(vg, pat3); nvgFill(vg)
                end
                -- 名字
                local ppTxtX = ppAvX + ppAvS + 8
                nvgFontFaceId(vg, GetMainFont()); nvgFontSize(vg, 15)
                nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)
                nvgFillColor(vg, nvgRGBA(255, 220, 120, 240))
                nvgText(vg, ppTxtX, ppY + ppH / 2 - 8, pp.name or "???", nil)
                -- 添加好友按钮
                local addBtnW, addBtnH = 70, 22
                local addBtnX = ppTxtX
                local addBtnY = ppY + ppH / 2 + 6
                local isFriend = CloudManager.IsFriend(pp.uid)
                local isMe = (rawget(_G, "clientCloud") and pp.uid == clientCloud.userId)
                if isMe then
                    nvgFontSize(vg, 12); nvgFillColor(vg, nvgRGBA(120, 120, 120, 180))
                    nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)
                    nvgText(vg, addBtnX, addBtnY + addBtnH / 2, "（自己）", nil)
                elseif isFriend then
                    nvgFontSize(vg, 12); nvgFillColor(vg, nvgRGBA(100, 200, 140, 200))
                    nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)
                    nvgText(vg, addBtnX, addBtnY + addBtnH / 2, "已是好友", nil)
                else
                    nvgBeginPath(vg); nvgRoundedRect(vg, addBtnX, addBtnY, addBtnW, addBtnH, 4)
                    nvgFillColor(vg, nvgRGBA(40, 100, 60, 220)); nvgFill(vg)
                    nvgStrokeColor(vg, nvgRGBA(100, 220, 140, 180)); nvgStrokeWidth(vg, 0.8); nvgStroke(vg)
                    nvgFontSize(vg, 13); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
                    nvgFillColor(vg, nvgRGBA(100, 240, 140, 255))
                    nvgText(vg, addBtnX + addBtnW / 2, addBtnY + addBtnH / 2, "+ 加好友", nil)
                    menuBtnRects.worldChatAddFriend = { x = addBtnX, y = addBtnY, w = addBtnW, h = addBtnH, uid = pp.uid, name = pp.name }
                end
                -- 整个弹窗区域（点击外部关闭用）
                menuBtnRects.worldChatPopupArea = { x = ppX, y = ppY, w = ppW, h = ppH }
                if not menuBtnRects.worldChatAddFriend or isMe or isFriend then
                    menuBtnRects.worldChatAddFriend = nil
                end
            else
                menuBtnRects.worldChatAddFriend = nil
                menuBtnRects.worldChatPopupArea = nil
            end

            -- 输入区域
            local inputY = chatY + chatH - inputH - 4
            local sendBtnW = 56
            local inputW = chatW - sendBtnW - 20
            -- 输入框背景
            nvgBeginPath(vg); nvgRoundedRect(vg, chatX + 8, inputY, inputW, inputH - 4, 6)
            nvgFillColor(vg, nvgRGBA(35, 30, 45, 220)); nvgFill(vg)
            nvgStrokeColor(vg, nvgRGBA(100, 90, 70, 150)); nvgStrokeWidth(vg, 0.8); nvgStroke(vg)
            -- 输入框文字
            nvgFontSize(vg, 16); nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)
            if worldChatUI.chatInput and #worldChatUI.chatInput > 0 then
                nvgFillColor(vg, nvgRGBA(230, 230, 230, 230))
                nvgText(vg, chatX + 14, inputY + (inputH - 4) / 2, worldChatUI.chatInput, nil)
            else
                nvgFillColor(vg, nvgRGBA(120, 120, 120, 150))
                nvgText(vg, chatX + 14, inputY + (inputH - 4) / 2, "输入消息...", nil)
            end
            menuBtnRects.worldChatInput = { x = chatX + 8, y = inputY, w = inputW, h = inputH - 4 }
            -- 发送按钮
            local sendX = chatX + chatW - sendBtnW - 8
            nvgBeginPath(vg); nvgRoundedRect(vg, sendX, inputY, sendBtnW, inputH - 4, 6)
            nvgFillColor(vg, nvgRGBA(180, 120, 40, 220)); nvgFill(vg)
            nvgFontSize(vg, 17); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
            nvgFillColor(vg, nvgRGBA(255, 255, 255, 240))
            nvgText(vg, sendX + sendBtnW / 2, inputY + (inputH - 4) / 2, "发送", nil)
            menuBtnRects.worldChatSend = { x = sendX, y = inputY, w = sendBtnW, h = inputH - 4 }
        end
    end

    -- ===========================
    -- 7. 左上角玩家面板
    -- ===========================
    local panelW = 220
    local panelH = 90
    local panelX = 6
    local panelY = H * 0.015

    -- 面板背景
    nvgBeginPath(vg); nvgRoundedRect(vg, panelX + 3, panelY + 3, panelW, panelH, 8)
    nvgFillColor(vg, nvgRGBA(0, 0, 0, 70)); nvgFill(vg)
    local panelGrad = nvgLinearGradient(vg, panelX, panelY, panelX, panelY + panelH,
        nvgRGBA(35, 25, 40, 220), nvgRGBA(20, 15, 28, 230))
    nvgBeginPath(vg); nvgRoundedRect(vg, panelX, panelY, panelW, panelH, 8)
    nvgFillPaint(vg, panelGrad); nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(20, 15, 10, 200)); nvgStrokeWidth(vg, 2.5); nvgStroke(vg)

    -- 头像
    local avatarSize = 48
    local avatarX = panelX + 8
    local avatarY = panelY + 8
    nvgBeginPath(vg); nvgRoundedRect(vg, avatarX - 2, avatarY - 2, avatarSize + 4, avatarSize + 4, 4)
    nvgFillColor(vg, nvgRGBA(10, 8, 15, 180)); nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(20, 15, 10, 200)); nvgStrokeWidth(vg, 2.0); nvgStroke(vg)
    if IMG.avatarSheet >= 0 then
        local avData = AVATAR_DATA[playerInfo.avatarIdx] or AVATAR_DATA[1]
        local imgW, imgH = 512, 768
        local cellW = imgW / AVATAR_COLS
        local cellH = imgH / AVATAR_ROWS
        local sx = avData.col * cellW
        local sy = avData.row * cellH
        local pat = nvgImagePattern(vg, avatarX - sx * (avatarSize / cellW),
            avatarY - sy * (avatarSize / cellH),
            imgW * (avatarSize / cellW), imgH * (avatarSize / cellH), 0, IMG.avatarSheet, 1.0)
        nvgBeginPath(vg); nvgRoundedRect(vg, avatarX, avatarY, avatarSize, avatarSize, 3)
        nvgFillPaint(vg, pat); nvgFill(vg)
    end

    -- 文字信息
    local infoX = avatarX + avatarSize + 8
    local infoTopY = avatarY + 2
    nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_TOP)
    local maxTextW = panelX + panelW - infoX - 6
    nvgFontFaceId(vg, GetMainFont()); nvgFontSize(vg, 20)
    local displayName = playerInfo.name
    local nameW = nvgTextBounds(vg, 0, 0, displayName, nil)
    if nameW > maxTextW then
        while #displayName > 2 do
            displayName = string.sub(displayName, 1, #displayName - 3)
            local w = nvgTextBounds(vg, 0, 0, displayName .. "..", nil)
            if w <= maxTextW then displayName = displayName .. ".."; break end
        end
    end
    nvgFillColor(vg, nvgRGBA(10, 5, 15, 200))
    for _, off in ipairs({{-0.5,0},{0.5,0},{0,-0.5},{0,0.5}}) do
        _nvgTextOrig(vg, infoX + off[1], infoTopY + off[2], displayName, nil)
    end
    nvgFillColor(vg, nvgRGBA(220, 210, 230, 240))
    _nvgTextOrig(vg, infoX, infoTopY, displayName, nil)

    local rankName = GetRankDisplayName()
    nvgFontSize(vg, 18)
    nvgFillColor(vg, nvgRGBA(180, 60, 50, 220))
    nvgText(vg, infoX, infoTopY + 22, rankName, nil)

    -- 战力
    local totalPwr = CalcPlayerTotalPower()
    nvgFontSize(vg, 18)
    nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_TOP)
    local statX = panelX + 8
    local statY = avatarY + avatarSize + 4
    nvgFillColor(vg, nvgRGBA(10, 5, 15, 160))
    nvgText(vg, statX + 0.5, statY + 0.5, "战力 " .. FormatPower(totalPwr), nil)
    nvgFillColor(vg, nvgRGBA(200, 190, 210, 230))
    nvgText(vg, statX, statY, "战力 " .. FormatPower(totalPwr), nil)

    -- 战力 "?" 按钮
    local pwrTextW = nvgTextBounds(vg, 0, 0, "战力 " .. FormatPower(totalPwr), nil)
    local qBtnX = statX + pwrTextW + 4
    local qBtnY = statY - 1
    local qBtnS = 18
    nvgBeginPath(vg); nvgCircle(vg, qBtnX + qBtnS/2, qBtnY + qBtnS/2, qBtnS/2)
    nvgFillColor(vg, nvgRGBA(80, 50, 90, 160)); nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(160, 120, 180, 180)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
    nvgFontSize(vg, 13); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    nvgFillColor(vg, nvgRGBA(220, 200, 240, 230))
    nvgText(vg, qBtnX + qBtnS/2, qBtnY + qBtnS/2, "?", nil)
    menuBtnRects.powerHelp = { x = qBtnX, y = qBtnY, w = qBtnS, h = qBtnS }

    playerDetailBtnRect = { x = panelX, y = panelY, w = panelW, h = panelH }

    -- 新手指引按钮 (面板下方)
    local guideBtnX = panelX
    local guideBtnY = panelY + panelH + 6
    local guideBtnW = 88
    local guideBtnH = 32
    nvgBeginPath(vg); nvgRoundedRect(vg, guideBtnX + 2, guideBtnY + 2, guideBtnW, guideBtnH, 5)
    nvgFillColor(vg, nvgRGBA(0, 0, 0, 40)); nvgFill(vg)
    nvgBeginPath(vg); nvgRoundedRect(vg, guideBtnX, guideBtnY, guideBtnW, guideBtnH, 5)
    nvgFillColor(vg, nvgRGBA(35, 25, 50, 180)); nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(20, 15, 10, 180)); nvgStrokeWidth(vg, 1.5); nvgStroke(vg)
    nvgFontFaceId(vg, GetMainFont()); nvgFontSize(vg, 21)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    nvgFillColor(vg, nvgRGBA(200, 180, 220, 210))
    nvgText(vg, guideBtnX + guideBtnW/2, guideBtnY + guideBtnH/2, "新手指引", nil)
    menuBtnRects.newbieGuide = { x = guideBtnX, y = guideBtnY, w = guideBtnW, h = guideBtnH }
    DrawHelpBtn(guideBtnX + guideBtnW + 6, guideBtnY + (guideBtnH - 26) / 2, 26)

    -- ===========================
    -- 8. 右上角虎符显示 + 广告
    -- ===========================
    local jadeBoxW = 190
    local jadeBoxH = 34
    local jadeBoxX = W - jadeBoxW - 10
    local jadeBoxY = H * 0.020

    nvgBeginPath(vg); nvgRoundedRect(vg, jadeBoxX + 2, jadeBoxY + 2, jadeBoxW, jadeBoxH, 6)
    nvgFillColor(vg, nvgRGBA(0, 0, 0, 50)); nvgFill(vg)
    nvgBeginPath(vg); nvgRoundedRect(vg, jadeBoxX, jadeBoxY, jadeBoxW, jadeBoxH, 6)
    nvgFillColor(vg, nvgRGBA(30, 20, 40, 200)); nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(20, 15, 10, 200)); nvgStrokeWidth(vg, 2.0); nvgStroke(vg)

    nvgFontFaceId(vg, GetMainFont()); nvgFontSize(vg, 21)
    nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(jadeBoxX + 6, jadeBoxY + jadeBoxH / 2, "虎符")
    nvgFontSize(vg, 21)
    nvgTextAlign(vg, NVG_ALIGN_RIGHT + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(jadeBoxX + jadeBoxW - 38, jadeBoxY + jadeBoxH / 2, FormatJade(playerInfo.jade))

    -- 广告 (+)
    local adBtnW = 36
    local adBtnH = 28
    local adBtnX = jadeBoxX + jadeBoxW - adBtnW - 3
    local adBtnY = jadeBoxY + (jadeBoxH - adBtnH) / 2
    local adPulse = 0.7 + 0.3 * math.sin(t * 3)
    nvgBeginPath(vg); nvgRoundedRect(vg, adBtnX + 1, adBtnY + 1, adBtnW, adBtnH, 4)
    nvgFillColor(vg, nvgRGBA(0, 0, 0, 40)); nvgFill(vg)
    nvgBeginPath(vg); nvgRoundedRect(vg, adBtnX, adBtnY, adBtnW, adBtnH, 4)
    nvgFillColor(vg, nvgRGBA(200, 60, 40, math.floor(210 * adPulse))); nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(20, 15, 10, 170)); nvgStrokeWidth(vg, 1.5); nvgStroke(vg)
    nvgFontSize(vg, 24); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(adBtnX + adBtnW/2, adBtnY + adBtnH/2, "+")
    local adPad = 8
    adRects.jade = { x = adBtnX - adPad, y = adBtnY - adPad, w = adBtnW + adPad*2, h = adBtnH + adPad*2 }
    -- 广告提示
    nvgFontSize(vg, 22); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_TOP)
    nvgFillColor(vg, nvgRGBA(200, 120, 120, math.floor(140 * adPulse)))
    nvgText(vg, jadeBoxX + jadeBoxW / 2, jadeBoxY + jadeBoxH + 2, "+2000虎符", nil)

    -- ===========================
    -- 9. 下载按钮 + 下载面板
    -- ===========================
    local allModulesReady = moduleState.equipment.ready and moduleState.heroes.ready
        and moduleState.skills.ready and moduleState.battle.ready
    if not allModulesReady then
        local dlBtnW = 78
        local dlBtnH = 28
        local dlBtnX = W - dlBtnW - 12
        local dlBtnY = jadeBoxY + jadeBoxH + 20
        local totalProg = (moduleState.equipment.progress + moduleState.heroes.progress
            + moduleState.skills.progress + moduleState.battle.progress) / 4
        local totalPct = math.floor(totalProg * 100)
        local dlBtnPulse = 0.7 + 0.3 * math.sin(t * 3)
        nvgBeginPath(vg); nvgRoundedRect(vg, dlBtnX, dlBtnY, dlBtnW, dlBtnH, 4)
        nvgFillColor(vg, nvgRGBA(20, 30, 55, 180)); nvgFill(vg)
        nvgStrokeColor(vg, nvgRGBA(100, 160, 220, math.floor(130 * dlBtnPulse))); nvgStrokeWidth(vg, 1); nvgStroke(vg)
        local miniBarH = 2
        local miniBarY2 = dlBtnY + dlBtnH - miniBarH - 2
        local miniBarX = dlBtnX + 4
        local miniBarW = dlBtnW - 8
        nvgBeginPath(vg); nvgRoundedRect(vg, miniBarX, miniBarY2, miniBarW, miniBarH, 1)
        nvgFillColor(vg, nvgRGBA(40, 50, 70, 150)); nvgFill(vg)
        local miniFillW = miniBarW * totalProg
        if miniFillW > 1 then
            nvgBeginPath(vg); nvgRoundedRect(vg, miniBarX, miniBarY2, miniFillW, miniBarH, 1)
            nvgFillColor(vg, nvgRGBA(100, 180, 255, 200)); nvgFill(vg)
        end
        nvgFontFaceId(vg, GetMainFont()); nvgFontSize(vg, 24)
        nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        DrawWhiteInkText(dlBtnX + dlBtnW/2, dlBtnY + (dlBtnH - miniBarH)/2, "下载" .. totalPct .. "%")
        downloadUI.btnRect = { x = dlBtnX, y = dlBtnY, w = dlBtnW, h = dlBtnH }

        if downloadUI.panelOpen then
            local panW = 200
            local panH = 164
            local panX = dlBtnX + dlBtnW - panW
            local panY = dlBtnY + dlBtnH + 4
            nvgBeginPath(vg); nvgRoundedRect(vg, panX, panY, panW, panH, 6)
            nvgFillColor(vg, nvgRGBA(15, 18, 30, 230)); nvgFill(vg)
            nvgStrokeColor(vg, nvgRGBA(100, 160, 220, 100)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
            downloadUI.panelRect = { x = panX, y = panY, w = panW, h = panH }
            nvgFontFaceId(vg, GetMainFont()); nvgFontSize(vg, 28)
            nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_TOP)
            DrawWhiteInkText(panX + panW/2, panY + 6, "资源下载进度")
            local modules = {
                { name = "兵甲", mod = moduleState.equipment },
                { name = "武灵", mod = moduleState.heroes },
                { name = "武技", mod = moduleState.skills },
                { name = "战斗", mod = moduleState.battle },
            }
            local rowH = 24; local rowStartY2 = panY + 26
            local barX2 = panX + 52; local barW2 = panW - 66; local barH2 = 8
            for mi, m in ipairs(modules) do
                local ry = rowStartY2 + (mi - 1) * rowH
                nvgFontSize(vg, 28); nvgTextAlign(vg, NVG_ALIGN_RIGHT + NVG_ALIGN_MIDDLE)
                nvgFillColor(vg, m.mod.ready and nvgRGBA(120,220,150,220) or nvgRGBA(180,180,200,200))
                nvgText(vg, barX2 - 6, ry + barH2/2, m.name, nil)
                nvgBeginPath(vg); nvgRoundedRect(vg, barX2, ry, barW2, barH2, 3)
                nvgFillColor(vg, nvgRGBA(40, 45, 60, 180)); nvgFill(vg)
                local modFillW = barW2 * m.mod.progress
                if modFillW > 1 then
                    nvgBeginPath(vg); nvgRoundedRect(vg, barX2, ry, modFillW, barH2, 3)
                    nvgFillColor(vg, m.mod.ready and nvgRGBA(80,200,130,220) or nvgRGBA(100,160,240,200)); nvgFill(vg)
                end
                nvgFontSize(vg, 28); nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)
                if m.mod.ready then
                    DrawWhiteInkText(barX2 + barW2 + 4, ry + barH2/2, "OK")
                else
                    DrawWhiteInkText(barX2 + barW2 + 4, ry + barH2/2, math.floor(m.mod.progress * 100) .. "%")
                end
            end
        end
    else
        downloadUI.btnRect = nil; downloadUI.panelRect = nil; downloadUI.panelOpen = false
    end

    -- ===========================
    -- 10. 漂浮粒子 (金色闪星)
    -- ===========================
    for i = 1, 6 do
        local px = W * (0.15 + 0.7 * ((i * 137 + math.floor(t * 18)) % 100) / 100)
        local py = H * (0.12 + 0.55 * math.sin(t * 0.4 + i * 1.3))
        local sr = 2.2 + math.sin(t * 2 + i) * 1.0
        local pa = math.floor(45 + 35 * math.sin(t * 1.5 + i * 0.7))
        nvgBeginPath(vg)
        nvgMoveTo(vg, px, py - sr); nvgLineTo(vg, px + sr * 0.3, py - sr * 0.3)
        nvgLineTo(vg, px + sr, py); nvgLineTo(vg, px + sr * 0.3, py + sr * 0.3)
        nvgLineTo(vg, px, py + sr); nvgLineTo(vg, px - sr * 0.3, py + sr * 0.3)
        nvgLineTo(vg, px - sr, py); nvgLineTo(vg, px - sr * 0.3, py - sr * 0.3)
        nvgClosePath(vg)
        nvgFillColor(vg, nvgRGBA(255, 230, 160, pa)); nvgFill(vg)
    end
end

-- ============================================================================
-- 按钮位置调整模式 (战斗场景实时预览, 设计坐标)
-- ============================================================================
function DrawBtnAdjustMode()
    local W = DESIGN_W
    local H = DESIGN_H
    local t = menuAnimTimer

    -- 1. 绘制战斗背景
    if IsImageReady(IMG.bg) then
        local p = nvgImagePattern(vg, 0, 0, W, H, 0, IMG.bg, 1.0)
        nvgBeginPath(vg); nvgRect(vg, 0, 0, W, H)
        nvgFillPaint(vg, p); nvgFill(vg)
    else
        nvgBeginPath(vg); nvgRect(vg, 0, 0, W, H)
        nvgFillColor(vg, nvgRGBA(25, 22, 16, 255)); nvgFill(vg)
        DrawSpinner(W / 2, H / 2, 20)
    end

    -- 半透明遮罩让按钮更清晰
    nvgBeginPath(vg); nvgRect(vg, 0, 0, W, H)
    nvgFillColor(vg, nvgRGBA(0, 0, 0, 50)); nvgFill(vg)

    nvgFontFaceId(vg, GetMainFont())

    -- 2. 绘制战斗区域参考线
    nvgBeginPath(vg)
    nvgRect(vg, BATTLE_ZONE.left, BATTLE_ZONE.top,
        BATTLE_ZONE.right - BATTLE_ZONE.left, BATTLE_ZONE.bottom - BATTLE_ZONE.top)
    nvgStrokeColor(vg, nvgRGBA(100, 90, 60, 60)); nvgStrokeWidth(vg, 1); nvgStroke(vg)

    -- 3. 绘制实际大小的三圈按钮（使用与 DrawBottomActionBar 完全相同的布局逻辑）
    local btnSc = settingsPage.adjScale
    local R = math.floor(26 * btnSc)
    local gap = math.floor(6 * btnSc)
    local marginR = 8 + safeInsets.right
    local marginB = 12 + safeInsets.bottom

    local btnOfsX = settingsPage.adjOffsetX
    local btnOfsY = settingsPage.adjOffsetY
    local bottomCY = BATTLE_ZONE.bottom - marginB - R + R * 2 + btnOfsY
    local rightCX = W - marginR - R + btnOfsX
    local leftCX  = rightCX - R * 2 - gap
    local topCX = (leftCX + rightCX) / 2
    local topCY = bottomCY - R * 2 - gap

    -- 绘制三个操作圈
    local circles = {
        { cx = topCX, cy = topCY, label = "自动", sub = "行军" },
        { cx = leftCX, cy = bottomCY, label = "武技", sub = "1" },
        { cx = rightCX, cy = bottomCY, label = "武技", sub = "2" },
    }
    for _, c in ipairs(circles) do
        -- 外发光
        local glowGrad = nvgRadialGradient(vg, c.cx, c.cy, R * 0.8, R * 1.6,
            nvgRGBA(120, 50, 55, 40), nvgRGBA(120, 50, 55, 0))
        nvgBeginPath(vg); nvgCircle(vg, c.cx, c.cy, R * 1.6)
        nvgFillPaint(vg, glowGrad); nvgFill(vg)
        -- 按钮本体
        nvgBeginPath(vg); nvgCircle(vg, c.cx, c.cy, R)
        nvgFillColor(vg, nvgRGBA(30, 35, 50, 220)); nvgFill(vg)
        nvgStrokeColor(vg, nvgRGBA(120, 50, 55, 200)); nvgStrokeWidth(vg, 2); nvgStroke(vg)
        -- 文字
        nvgFontSize(vg, math.floor(11 * btnSc))
        nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        DrawWhiteInkText(c.cx, c.cy - 5 * btnSc, c.label)
        nvgFontSize(vg, math.floor(9 * btnSc))
        DrawWhiteInkText(c.cx, c.cy + 7 * btnSc, c.sub)
    end

    -- 拖拽中的视觉提示 (仅当前选中组高亮)
    local activeGrp = settingsPage.adjActiveGroup or "skill"
    if settingsPage.adjDragging and activeGrp == "skill" then
        for _, c in ipairs(circles) do
            nvgBeginPath(vg); nvgCircle(vg, c.cx, c.cy, R + 3)
            nvgStrokeColor(vg, nvgRGBA(100, 200, 255, 120)); nvgStrokeWidth(vg, 1.5); nvgStroke(vg)
        end
    end
    -- 选中高亮框 (技能组)
    if activeGrp == "skill" then
        for _, c in ipairs(circles) do
            nvgBeginPath(vg); nvgCircle(vg, c.cx, c.cy, R + 2)
            nvgStrokeColor(vg, nvgRGBA(100, 200, 255, 180)); nvgStrokeWidth(vg, 1.5); nvgStroke(vg)
        end
    end

    -- 3b. 绘制右上角按钮组预览
    local rbOfsX = settingsPage.adjRightBtnOffsetX
    local rbOfsY = settingsPage.adjRightBtnOffsetY
    local rbBtnW = 72
    local rbBtnH = 30
    local rbGap = 6
    local rbRightMargin = 4
    local rbStartY = 28 + rbOfsY
    local rbX = W - rbBtnW - rbRightMargin + rbOfsX
    local rbLabels = { "军资", "刷新", "退出" }
    local rbCurY = rbStartY
    for idx, lbl in ipairs(rbLabels) do
        nvgBeginPath(vg); nvgRoundedRect(vg, rbX, rbCurY, rbBtnW, rbBtnH, 3)
        if idx == #rbLabels then
            nvgFillColor(vg, nvgRGBA(60, 20, 20, 160)); nvgFill(vg)
            nvgStrokeColor(vg, nvgRGBA(180, 100, 80, 120))
        else
            nvgFillColor(vg, nvgRGBA(12, 10, 6, 180)); nvgFill(vg)
            nvgStrokeColor(vg, nvgRGBA(100, 180, 220, 80))
        end
        nvgStrokeWidth(vg, 0.6); nvgStroke(vg)
        nvgFontSize(vg, 13)
        nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        DrawWhiteInkText(rbX + rbBtnW / 2, rbCurY + rbBtnH / 2, lbl)
        rbCurY = rbCurY + rbBtnH + rbGap
    end
    if activeGrp == "rightBtn" then
        nvgBeginPath(vg); nvgRoundedRect(vg, rbX - 3, rbStartY - 3, rbBtnW + 6, rbCurY - rbStartY + 3, 4)
        nvgStrokeColor(vg, nvgRGBA(100, 200, 255, 180)); nvgStrokeWidth(vg, 1.5); nvgStroke(vg)
    end
    if settingsPage.adjDragging and activeGrp == "rightBtn" then
        nvgBeginPath(vg); nvgRoundedRect(vg, rbX - 4, rbStartY - 4, rbBtnW + 8, rbCurY - rbStartY + 4, 5)
        nvgStrokeColor(vg, nvgRGBA(100, 200, 255, 120)); nvgStrokeWidth(vg, 1.5); nvgStroke(vg)
    end

    -- 3c. 绘制顶部HUD预览
    local hudOfsX = settingsPage.adjHudOffsetX
    local hudOfsY = settingsPage.adjHudOffsetY
    local hudH2 = 22
    nvgBeginPath(vg); nvgRoundedRect(vg, 4 + hudOfsX, 2 + hudOfsY, W - 8, hudH2, 4)
    nvgFillColor(vg, nvgRGBA(30, 25, 16, 190)); nvgFill(vg)
    nvgFontSize(vg, 20)
    nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(16 + hudOfsX, 13 + hudOfsY, "军资")
    nvgFontSize(vg, 22)
    DrawWhiteInkText(50 + hudOfsX, 13 + hudOfsY, "99")
    nvgFontSize(vg, 20)
    DrawWhiteInkText(120 + hudOfsX, 13 + hudOfsY, "斩")
    nvgFontSize(vg, 22)
    DrawWhiteInkText(140 + hudOfsX, 13 + hudOfsY, "0")
    -- 倒计时预览
    local tmrW2 = 72
    local tmrH2 = 20
    local tmrX2 = W / 2 - tmrW2 / 2 + hudOfsX
    local tmrY2 = hudH2 + 4 + hudOfsY
    nvgBeginPath(vg); nvgRoundedRect(vg, tmrX2, tmrY2, tmrW2, tmrH2, 10)
    nvgFillColor(vg, nvgRGBA(12, 10, 6, 180)); nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(90, 45, 55, 80)); nvgStrokeWidth(vg, 0.5); nvgStroke(vg)
    nvgFontSize(vg, 16)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(W / 2 + hudOfsX, tmrY2 + tmrH2 / 2, "1:30")
    if activeGrp == "hud" then
        nvgBeginPath(vg); nvgRoundedRect(vg, 1 + hudOfsX, -1 + hudOfsY, W - 2, hudH2 + tmrH2 + 10, 5)
        nvgStrokeColor(vg, nvgRGBA(100, 200, 255, 180)); nvgStrokeWidth(vg, 1.5); nvgStroke(vg)
    end

    -- 3d. 绘制左上角信息面板预览
    local ipOfsX = settingsPage.adjInfoPanelOffsetX
    local ipOfsY = settingsPage.adjInfoPanelOffsetY
    local ipW = 110
    local ipH = 88
    local ipX = 4 + ipOfsX
    local ipY = 28 + ipOfsY
    nvgBeginPath(vg); nvgRoundedRect(vg, ipX, ipY, ipW, ipH, 4)
    nvgFillColor(vg, nvgRGBA(10, 8, 5, 140)); nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(160, 130, 70, 40)); nvgStrokeWidth(vg, 0.5); nvgStroke(vg)
    nvgFontSize(vg, 13.5)
    nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_TOP)
    DrawWhiteInkText(ipX + 6, ipY + 10, "阵容 3/6")
    DrawWhiteInkText(ipX + 6, ipY + 23, "总攻: 100")
    DrawWhiteInkText(ipX + 6, ipY + 35, "总防: 80")
    nvgFontSize(vg, 11.2)
    DrawWhiteInkText(ipX + 6, ipY + 51, "点击查看 - 拖拽换位")
    DrawWhiteInkText(ipX + 6, ipY + 61, "拖拽卡牌至石台放置")
    if activeGrp == "infoPanel" then
        nvgBeginPath(vg); nvgRoundedRect(vg, ipX - 3, ipY - 3, ipW + 6, ipH + 6, 5)
        nvgStrokeColor(vg, nvgRGBA(100, 200, 255, 180)); nvgStrokeWidth(vg, 1.5); nvgStroke(vg)
    end

    -- 4. 顶部提示条
    local tipBarH = 36
    nvgBeginPath(vg); nvgRect(vg, 0, 0, W, tipBarH)
    nvgFillColor(vg, nvgRGBA(10, 15, 30, 200)); nvgFill(vg)
    nvgFontSize(vg, 24)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(W / 2, tipBarH / 2, "拖拽屏幕移动选中组位置")

    -- 5. 底部工具栏 (增高以容纳组切换标签)
    local barH = 90
    local barY = H - barH
    nvgBeginPath(vg); nvgRect(vg, 0, barY, W, barH)
    nvgFillColor(vg, nvgRGBA(10, 15, 30, 220)); nvgFill(vg)
    -- 顶部分隔线
    nvgBeginPath(vg)
    nvgMoveTo(vg, 0, barY); nvgLineTo(vg, W, barY)
    nvgStrokeColor(vg, nvgRGBA(90, 45, 55, 100)); nvgStrokeWidth(vg, 1); nvgStroke(vg)

    -- 5a. 组切换标签栏
    local groups = {
        { key = "skill",     label = "技能按钮" },
        { key = "rightBtn",  label = "右侧按钮" },
        { key = "hud",       label = "顶部信息" },
        { key = "infoPanel", label = "左侧面板" },
    }
    local tabY = barY + 6
    local tabH = 26
    local tabGap = 6
    local totalTabW = 0
    local tabWidths = {}
    for _, g in ipairs(groups) do
        local tw = 70
        tabWidths[#tabWidths + 1] = tw
        totalTabW = totalTabW + tw + tabGap
    end
    totalTabW = totalTabW - tabGap
    local tabStartX = (W - totalTabW) / 2
    local tabCurX = tabStartX
    settingsPage.adjGroupBtnRects = {}
    for gi, g in ipairs(groups) do
        local tw = tabWidths[gi]
        local isActive = (activeGrp == g.key)
        nvgBeginPath(vg); nvgRoundedRect(vg, tabCurX, tabY, tw, tabH, 4)
        if isActive then
            nvgFillColor(vg, nvgRGBA(60, 100, 160, 230)); nvgFill(vg)
            nvgStrokeColor(vg, nvgRGBA(100, 200, 255, 200)); nvgStrokeWidth(vg, 1.5); nvgStroke(vg)
        else
            nvgFillColor(vg, nvgRGBA(40, 40, 55, 200)); nvgFill(vg)
            nvgStrokeColor(vg, nvgRGBA(100, 90, 70, 100)); nvgStrokeWidth(vg, 0.8); nvgStroke(vg)
        end
        nvgFontSize(vg, 20)
        nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        DrawWhiteInkText(tabCurX + tw / 2, tabY + tabH / 2, g.label)
        settingsPage.adjGroupBtnRects[gi] = { x = tabCurX, y = tabY, w = tw, h = tabH, key = g.key }
        tabCurX = tabCurX + tw + tabGap
    end

    -- 5b. 缩放滑条 (仅技能按钮组显示)
    local row2Y = tabY + tabH + 8
    if activeGrp == "skill" then
        local sliderLabel = "大小"
        local sliderX = 60
        local sliderW = W - 260
        local sliderH = 8
        local sliderY = row2Y + 4
        nvgFontSize(vg, 24)
        nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)
        DrawWhiteInkText(14, sliderY, sliderLabel)
        nvgBeginPath(vg); nvgRoundedRect(vg, sliderX, sliderY - sliderH / 2, sliderW, sliderH, 4)
        nvgFillColor(vg, nvgRGBA(40, 45, 60, 200)); nvgFill(vg)
        local scaleRatio = (settingsPage.adjScale - 0.5) / 1.5
        local scaleFill = sliderW * scaleRatio
        nvgBeginPath(vg); nvgRoundedRect(vg, sliderX, sliderY - sliderH / 2, scaleFill, sliderH, 4)
        nvgFillColor(vg, nvgRGBA(100, 180, 220, 200)); nvgFill(vg)
        local scaleKnobX = sliderX + scaleFill
        nvgBeginPath(vg); nvgCircle(vg, scaleKnobX, sliderY, 9)
        nvgFillColor(vg, nvgRGBA(180, 220, 255, 240)); nvgFill(vg)
        nvgStrokeColor(vg, nvgRGBA(80, 140, 200, 200)); nvgStrokeWidth(vg, 1.5); nvgStroke(vg)
        nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)
        nvgFontSize(vg, 24)
        DrawWhiteInkText(sliderX + sliderW + 6, sliderY, math.floor(settingsPage.adjScale * 100) .. "%")
        settingsPage.adjScaleSliderRect = { x = sliderX, y = sliderY - 14, w = sliderW, h = 28 }
    else
        settingsPage.adjScaleSliderRect = nil
    end

    -- 5c. 按钮区域 (底部右侧)
    local btnAreaX = W - 190
    local btnY = row2Y
    local btnW2 = 54
    local btnH2 = 32

    -- 重置按钮
    nvgBeginPath(vg); nvgRoundedRect(vg, btnAreaX, btnY, btnW2, btnH2, 5)
    nvgFillColor(vg, nvgRGBA(60, 55, 70, 220)); nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(90, 45, 55, 120)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
    nvgFontSize(vg, 24)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(btnAreaX + btnW2 / 2, btnY + btnH2 / 2, "重置")
    settingsPage.adjResetBtnRect = { x = btnAreaX, y = btnY, w = btnW2, h = btnH2 }

    -- 保存按钮
    local saveBtnX = btnAreaX + btnW2 + 8
    nvgBeginPath(vg); nvgRoundedRect(vg, saveBtnX, btnY, btnW2, btnH2, 5)
    local saveGrad = nvgLinearGradient(vg, saveBtnX, btnY, saveBtnX, btnY + btnH2,
        nvgRGBA(90, 45, 55, 230), nvgRGBA(60, 25, 35, 230))
    nvgFillPaint(vg, saveGrad); nvgFill(vg)
    nvgFontSize(vg, 24)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(saveBtnX + btnW2 / 2, btnY + btnH2 / 2, "保存")
    settingsPage.adjSaveBtnRect = { x = saveBtnX, y = btnY, w = btnW2, h = btnH2 }

    -- 返回按钮
    local backBtnX = saveBtnX + btnW2 + 8
    nvgBeginPath(vg); nvgRoundedRect(vg, backBtnX, btnY, btnW2, btnH2, 5)
    nvgFillColor(vg, nvgRGBA(50, 35, 35, 220)); nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(180, 100, 80, 120)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
    nvgFontSize(vg, 24)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(backBtnX + btnW2 / 2, btnY + btnH2 / 2, "返回")
    settingsPage.adjBackBtnRect = { x = backBtnX, y = btnY, w = btnW2, h = btnH2 }
end

-- ============================================================================
-- 设置界面 (设计坐标, 覆盖在菜单上方)
-- ============================================================================
function DrawSettingsScreen()
    local W = DESIGN_W
    local H = DESIGN_H
    local cx = W / 2
    local t = gameState.gameTime

    -- 半透明全屏遮罩
    nvgBeginPath(vg); nvgRect(vg, 0, 0, W, H)
    nvgFillColor(vg, nvgRGBA(5, 5, 12, 95)); nvgFill(vg)

    -- 设置面板
    local panW = 380
    local panH = 696
    local panX = cx - panW / 2
    local panY = (H - panH) / 2 - 10

    -- 面板背景
    nvgBeginPath(vg)
    nvgRoundedRect(vg, panX, panY, panW, panH, 8)
    nvgFillColor(vg, nvgRGBA(30, 38, 58, 220)); nvgFill(vg)
    -- 铜色边框
    nvgBeginPath(vg)
    nvgRoundedRect(vg, panX, panY, panW, panH, 8)
    nvgStrokeWidth(vg, 2)
    nvgStrokeColor(vg, nvgRGBA(162, 128, 78, 200)); nvgStroke(vg)

    nvgFontFaceId(vg, GetMainFont())

    -- 标题
    nvgFontSize(vg, 34)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(cx, panY + 36, "设置")

    -- UID 显示 + 一键复制按钮 (分隔线下方独立行)
    local leftM = panX + 24
    local rightM = panX + panW - 24
    local uidRowY = panY + 80
    do
        local uid = rawget(_G, "clientCloud") and clientCloud.userId or 0
        local uidStr = uid ~= 0 and tostring(uid) or "---"
        -- UID 标签 + 数值
        nvgFontSize(vg, 18)
        nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)
        nvgFillColor(vg, nvgRGBA(140, 135, 120, 180))
        nvgText(vg, leftM, uidRowY, "UID:", nil)
        nvgFillColor(vg, nvgRGBA(220, 215, 200, 230))
        nvgText(vg, leftM + 40, uidRowY, uidStr, nil)
        -- 复制按钮
        local cpBtnW, cpBtnH = 52, 22
        local cpBtnX = leftM + 40 + nvgTextBounds(vg, 0, 0, uidStr, nil) + 10
        local cpBtnY = uidRowY - cpBtnH / 2
        nvgBeginPath(vg); nvgRoundedRect(vg, cpBtnX, cpBtnY, cpBtnW, cpBtnH, 4)
        -- 复制成功闪烁效果
        local copyFlash = settingsPage.uidCopyTimer and settingsPage.uidCopyTimer > 0
        if copyFlash then
            nvgFillColor(vg, nvgRGBA(60, 160, 80, 220))
        else
            nvgFillColor(vg, nvgRGBA(60, 80, 120, 200))
        end
        nvgFill(vg)
        nvgStrokeColor(vg, nvgRGBA(100, 140, 200, 150)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
        nvgFontSize(vg, 14)
        nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        nvgFillColor(vg, nvgRGBA(220, 230, 255, 230))
        nvgText(vg, cpBtnX + cpBtnW / 2, cpBtnY + cpBtnH / 2, copyFlash and "已复制" or "复制", nil)
        settingsPage.uidCopyBtnRect = { x = cpBtnX, y = cpBtnY, w = cpBtnW, h = cpBtnH }
        settingsPage.uidValue = uidStr
        -- 复制成功提示计时衰减
        if settingsPage.uidCopyTimer and settingsPage.uidCopyTimer > 0 then
            settingsPage.uidCopyTimer = settingsPage.uidCopyTimer - (1.0 / 60.0)
        end
    end

    -- 分隔线
    nvgBeginPath(vg)
    nvgMoveTo(vg, panX + 20, panY + 56)
    nvgLineTo(vg, panX + panW - 20, panY + 56)
    nvgStrokeColor(vg, nvgRGBA(90, 45, 55, 100)); nvgStrokeWidth(vg, 1); nvgStroke(vg)

    local contentW = rightM - leftM
    local rowY = panY + 108
    local rowGap = 68

    -- ======== 音乐音量 ========
    nvgFontSize(vg, 27)
    nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(leftM, rowY, "音乐")

    local sliderX = leftM + 80
    local sliderW = contentW - 80
    local sliderH = 8
    local sliderY = rowY - sliderH / 2
    -- 滑条背景
    nvgBeginPath(vg); nvgRoundedRect(vg, sliderX, sliderY, sliderW, sliderH, 4)
    nvgFillColor(vg, nvgRGBA(40, 45, 60, 200)); nvgFill(vg)
    -- 滑条填充
    local musicFill = sliderW * gameSettings.musicVolume
    nvgBeginPath(vg); nvgRoundedRect(vg, sliderX, sliderY, musicFill, sliderH, 4)
    nvgFillColor(vg, nvgRGBA(120, 50, 55, 200)); nvgFill(vg)
    -- 滑块
    local knobX = sliderX + musicFill
    nvgBeginPath(vg); nvgCircle(vg, knobX, rowY, 8)
    nvgFillColor(vg, nvgRGBA(200, 180, 190, 240)); nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(90, 45, 55, 200)); nvgStrokeWidth(vg, 1.5); nvgStroke(vg)
    -- 百分比 (显示在滑条右端上方)
    nvgFontSize(vg, 20)
    nvgTextAlign(vg, NVG_ALIGN_RIGHT + NVG_ALIGN_BOTTOM)
    DrawWhiteInkText(rightM, rowY - 10, math.floor(gameSettings.musicVolume * 100) .. "%")
    settingsPage.musicSliderRect = { x = sliderX, y = sliderY - 10, w = sliderW, h = sliderH + 20 }

    -- ======== 音效音量 ========
    rowY = rowY + rowGap
    nvgFontSize(vg, 27)
    nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(leftM, rowY, "音效")

    nvgBeginPath(vg); nvgRoundedRect(vg, sliderX, rowY - sliderH / 2, sliderW, sliderH, 4)
    nvgFillColor(vg, nvgRGBA(40, 45, 60, 200)); nvgFill(vg)
    local sfxFill = sliderW * gameSettings.sfxVolume
    nvgBeginPath(vg); nvgRoundedRect(vg, sliderX, rowY - sliderH / 2, sfxFill, sliderH, 4)
    nvgFillColor(vg, nvgRGBA(120, 50, 55, 200)); nvgFill(vg)
    local sfxKnobX = sliderX + sfxFill
    nvgBeginPath(vg); nvgCircle(vg, sfxKnobX, rowY, 8)
    nvgFillColor(vg, nvgRGBA(200, 180, 190, 240)); nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(90, 45, 55, 200)); nvgStrokeWidth(vg, 1.5); nvgStroke(vg)
    nvgFontSize(vg, 20)
    nvgTextAlign(vg, NVG_ALIGN_RIGHT + NVG_ALIGN_BOTTOM)
    DrawWhiteInkText(rightM, rowY - 10, math.floor(gameSettings.sfxVolume * 100) .. "%")
    settingsPage.sfxSliderRect = { x = sliderX, y = rowY - sliderH / 2 - 10, w = sliderW, h = sliderH + 20 }

    -- ======== 按钮位置与大小 ========
    rowY = rowY + rowGap
    nvgFontSize(vg, 27)
    nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(leftM, rowY, "按钮位置与大小")

    local adjBtnW = 80
    local adjBtnH = 28
    local adjBtnX = rightM - adjBtnW
    local adjBtnY = rowY - adjBtnH / 2
    nvgBeginPath(vg); nvgRoundedRect(vg, adjBtnX, adjBtnY, adjBtnW, adjBtnH, 6)
    nvgFillPaint(vg, nvgLinearGradient(vg, adjBtnX, adjBtnY, adjBtnX, adjBtnY + adjBtnH,
        nvgRGBA(100, 140, 200, 220), nvgRGBA(60, 90, 150, 220)))
    nvgFill(vg)
    nvgFontSize(vg, 27)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(adjBtnX + adjBtnW / 2, adjBtnY + adjBtnH / 2, "调整")
    settingsPage.adjustPosBtnRect = { x = adjBtnX, y = adjBtnY, w = adjBtnW, h = adjBtnH }

    -- ======== 默认自动行军 ========
    rowY = rowY + rowGap
    nvgFontSize(vg, 27)
    nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(leftM, rowY, "默认自动行军")

    -- 开关按钮
    local toggleW = 44
    local toggleH = 22
    local toggleX = rightM - toggleW
    local toggleY = rowY - toggleH / 2
    local isOn = gameSettings.defaultAutoMarch
    -- 底座
    nvgBeginPath(vg); nvgRoundedRect(vg, toggleX, toggleY, toggleW, toggleH, toggleH / 2)
    nvgFillColor(vg, isOn and nvgRGBA(80, 180, 100, 200) or nvgRGBA(60, 55, 70, 200)); nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(90, 45, 55, 120)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
    -- 滑块圆
    local toggleKnobX = isOn and (toggleX + toggleW - toggleH / 2 - 2) or (toggleX + toggleH / 2 + 2)
    nvgBeginPath(vg); nvgCircle(vg, toggleKnobX, rowY, toggleH / 2 - 3)
    nvgFillColor(vg, nvgRGBA(240, 230, 210, 240)); nvgFill(vg)
    settingsPage.autoMarchToggleRect = { x = toggleX, y = toggleY, w = toggleW, h = toggleH }

    -- ======== 字体风格 ========
    rowY = rowY + rowGap
    nvgFontSize(vg, 27)
    nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(leftM, rowY, "字体风格")

    -- 四个字体选项按钮: MiSans / 快乐体 / 文楷 / 行书
    local fontOptW = 42
    local fontOptH = 28
    local fontOptGap = 4
    local curFontStyle = gameSettings.fontStyle or "misans"

    local fontBtns = {
        { key = "misans",  label = "默认" },
        { key = "kuaile",  label = "快乐" },
        { key = "wenkai",  label = "文楷" },
        { key = "xingshu", label = "行书" },
    }
    local totalBtnW = #fontBtns * fontOptW + (#fontBtns - 1) * fontOptGap
    local fontOptStartX = rightM - totalBtnW
    for i, btn in ipairs(fontBtns) do
        local bx = fontOptStartX + (i - 1) * (fontOptW + fontOptGap)
        local by = rowY - fontOptH / 2
        local isActive = (curFontStyle == btn.key)
        nvgBeginPath(vg); nvgRoundedRect(vg, bx, by, fontOptW, fontOptH, 5)
        if isActive then
            nvgFillPaint(vg, nvgLinearGradient(vg, bx, by, bx, by + fontOptH,
                nvgRGBA(90, 45, 55, 220), nvgRGBA(60, 25, 35, 220)))
        else
            nvgFillColor(vg, nvgRGBA(40, 38, 50, 200))
        end
        nvgFill(vg)
        nvgStrokeColor(vg, nvgRGBA(90, 45, 55, 120)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
        nvgFontSize(vg, 22)
        nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        if isActive then
            DrawWhiteInkText(bx + fontOptW / 2, by + fontOptH / 2, btn.label)
        else
            nvgFillColor(vg, nvgRGBA(160, 145, 120, 180))
            nvgText(vg, bx + fontOptW / 2, by + fontOptH / 2, btn.label, nil)
        end
        -- 存储按钮区域用于点击检测
        settingsPage["font_" .. btn.key .. "_rect"] = { x = bx, y = by, w = fontOptW, h = fontOptH }
    end

    -- ======== 默认战场 ========
    rowY = rowY + rowGap
    nvgFontSize(vg, 27)
    nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(leftM, rowY, "默认战场")

    -- 切换按钮 (显示当前战场名, 点击切换)
    local bfBtnW = 120
    local bfBtnH = 28
    local bfBtnX = rightM - bfBtnW
    local bfBtnY = rowY - bfBtnH / 2
    local curBf = gameSettings.defaultBattlefield or 1
    local bfLayout = BATTLE_LAYOUTS[curBf]
    local bfName = bfLayout and bfLayout.name or "默认战场"
    nvgBeginPath(vg); nvgRoundedRect(vg, bfBtnX, bfBtnY, bfBtnW, bfBtnH, 5)
    nvgFillColor(vg, nvgRGBA(25, 35, 55, 200)); nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(100, 180, 255, 140)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
    nvgFontSize(vg, 23)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(bfBtnX + bfBtnW / 2, bfBtnY + bfBtnH / 2, bfName)
    -- 左右小箭头提示
    nvgFontSize(vg, 19)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(bfBtnX - 2, bfBtnY + bfBtnH / 2, "◀")
    DrawWhiteInkText(bfBtnX + bfBtnW + 2, bfBtnY + bfBtnH / 2, "▶")
    settingsPage.battlefieldBtnRect = { x = bfBtnX - 14, y = bfBtnY, w = bfBtnW + 28, h = bfBtnH }

    -- ======== CDK 兑换 ========
    rowY = rowY + rowGap
    nvgFontSize(vg, 27)
    nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(leftM, rowY, "CDK兑换")

    local cdkBtnW = 80
    local cdkBtnH = 28
    local cdkBtnX = rightM - cdkBtnW
    local cdkBtnY = rowY - cdkBtnH / 2
    nvgBeginPath(vg); nvgRoundedRect(vg, cdkBtnX, cdkBtnY, cdkBtnW, cdkBtnH, 6)
    nvgFillPaint(vg, nvgLinearGradient(vg, cdkBtnX, cdkBtnY, cdkBtnX, cdkBtnY + cdkBtnH,
        nvgRGBA(80, 140, 180, 220), nvgRGBA(50, 100, 140, 220)))
    nvgFill(vg)
    nvgFontSize(vg, 25)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(cdkBtnX + cdkBtnW / 2, cdkBtnY + cdkBtnH / 2, "输入兑换码")
    settingsPage.cdkBtnRect = { x = cdkBtnX, y = cdkBtnY, w = cdkBtnW, h = cdkBtnH }

    -- ======== 今日免广告卡 (看3次广告免战斗广告) ========
    rowY = rowY + rowGap
    do
        -- 跨日重置检查
        local today = os.date("%Y-%m-%d")
        if gameSettings.dailyAdDate ~= today then
            gameSettings.dailyAdCount = 0
            gameSettings.dailyAdDate = today
        end
        local adCount = math.min(gameSettings.dailyAdCount, 3)
        local isActive = adCount >= 3
        local isPermanent = playerInfo.ad_free

        nvgFontSize(vg, 27)
        nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)
        DrawWhiteInkText(leftM, rowY, "免广告卡")

        -- 右侧: 进度条 + 看广告按钮
        local adBtnW = 72
        local adBtnGap = 8
        local barW = contentW - 90 - adBtnW - adBtnGap
        local barH = 10
        local barX = leftM + 90
        local barY = rowY - barH / 2

        if isPermanent then
            -- 永久免广告特权
            nvgFontSize(vg, 22)
            nvgTextAlign(vg, NVG_ALIGN_RIGHT + NVG_ALIGN_MIDDLE)
            nvgFillColor(vg, nvgRGBA(100, 255, 150, 220))
            nvgText(vg, rightM, rowY, "永久免广告", nil)
            settingsPage.adCardBtnRect = nil
        else
            -- 进度条背景
            nvgBeginPath(vg); nvgRoundedRect(vg, barX, barY, barW, barH, 5)
            nvgFillColor(vg, nvgRGBA(40, 45, 60, 200)); nvgFill(vg)
            -- 进度条填充
            local fillW = barW * (adCount / 3)
            nvgBeginPath(vg); nvgRoundedRect(vg, barX, barY, fillW, barH, 5)
            if isActive then
                nvgFillColor(vg, nvgRGBA(80, 200, 120, 220))
            else
                nvgFillColor(vg, nvgRGBA(200, 160, 60, 200))
            end
            nvgFill(vg)
            -- 3个刻度点
            for i = 1, 3 do
                local dotX = barX + barW * (i / 3) - barW / 6
                local filled = i <= adCount
                nvgBeginPath(vg); nvgCircle(vg, dotX, rowY, 5)
                if filled then
                    nvgFillColor(vg, nvgRGBA(255, 255, 255, 240))
                else
                    nvgFillColor(vg, nvgRGBA(60, 55, 70, 200))
                end
                nvgFill(vg)
                nvgStrokeColor(vg, nvgRGBA(90, 80, 70, 150)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
            end
            -- 状态文字
            nvgFontSize(vg, 18)
            nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_TOP)
            if isActive then
                nvgFillColor(vg, nvgRGBA(100, 255, 180, 220))
                nvgText(vg, barX + barW / 2, rowY + barH / 2 + 4, "已激活 - 战斗广告已免除", nil)
            else
                nvgFillColor(vg, nvgRGBA(180, 170, 150, 160))
                nvgText(vg, barX + barW / 2, rowY + barH / 2 + 4, adCount .. "/3 看广告激活", nil)
            end
            -- ★ 看广告按钮 (未激活时显示)
            local adBtnX = barX + barW + adBtnGap
            local adBtnH = 28
            local adBtnY = rowY - adBtnH / 2
            if not isActive then
                nvgBeginPath(vg); nvgRoundedRect(vg, adBtnX, adBtnY, adBtnW, adBtnH, 6)
                nvgFillColor(vg, nvgRGBA(200, 160, 50, 220)); nvgFill(vg)
                nvgStrokeColor(vg, nvgRGBA(255, 210, 80, 180)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
                nvgFontSize(vg, 16)
                nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
                nvgFillColor(vg, nvgRGBA(40, 30, 10, 240))
                nvgText(vg, adBtnX + adBtnW / 2, adBtnY + adBtnH / 2, "看广告", nil)
                settingsPage.adCardBtnRect = { x = adBtnX, y = adBtnY, w = adBtnW, h = adBtnH }
            else
                settingsPage.adCardBtnRect = nil
            end
        end
    end

    -- ======== 保存 & 关闭按钮 ========
    local btnRowY = panY + panH - 58
    local saveBtnW = 100
    local saveBtnH = 36
    local closeBtnW = 80
    local closeBtnH = 36

    -- 保存按钮
    local saveBtnX = cx - saveBtnW / 2 - closeBtnW / 2 - 10
    nvgBeginPath(vg); nvgRoundedRect(vg, saveBtnX, btnRowY, saveBtnW, saveBtnH, 6)
    local saveGrad = nvgLinearGradient(vg, saveBtnX, btnRowY, saveBtnX, btnRowY + saveBtnH,
        nvgRGBA(90, 45, 55, 220), nvgRGBA(60, 25, 35, 220))
    nvgFillPaint(vg, saveGrad); nvgFill(vg)
    nvgFontSize(vg, 27)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(saveBtnX + saveBtnW / 2, btnRowY + saveBtnH / 2, "保存")
    settingsPage.saveBtnRect = { x = saveBtnX, y = btnRowY, w = saveBtnW, h = saveBtnH }

    -- 关闭按钮
    local closeBtnX = cx + saveBtnW / 2 - closeBtnW / 2 + 10
    nvgBeginPath(vg); nvgRoundedRect(vg, closeBtnX, btnRowY, closeBtnW, closeBtnH, 6)
    nvgFillColor(vg, nvgRGBA(50, 45, 60, 200)); nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(90, 45, 55, 120)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
    nvgFontSize(vg, 27)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(closeBtnX + closeBtnW / 2, btnRowY + closeBtnH / 2, "关闭")
    settingsPage.closeBtnRect = { x = closeBtnX, y = btnRowY, w = closeBtnW, h = closeBtnH }
end

-- ============================================================================
-- CDK 兑换弹窗 (使用原生键盘输入)
-- ============================================================================
function DrawCDKPopup()
    if not cdkState.inputOpen then return end
    local W = DESIGN_W
    local H = DESIGN_H
    -- 遮罩
    nvgBeginPath(vg); nvgRect(vg, 0, 0, W, H)
    nvgFillColor(vg, nvgRGBA(5, 5, 12, 130)); nvgFill(vg)

    -- 紧凑弹窗面板
    local pw, ph = 420, 200
    local px = (W - pw) / 2
    local py = (H - ph) / 2 - 80  -- 偏上，给原生键盘留空间
    nvgBeginPath(vg); nvgRoundedRect(vg, px, py, pw, ph, 12)
    nvgFillColor(vg, nvgRGBA(30, 28, 40, 240)); nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(90, 45, 55, 180)); nvgStrokeWidth(vg, 2); nvgStroke(vg)

    -- 标题
    nvgFontSize(vg, 26)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(px + pw / 2, py + 24, "输入兑换码")

    -- 输入框
    local inputX = px + 20
    local inputY = py + 50
    local inputW = pw - 40
    local inputH = 46
    nvgBeginPath(vg); nvgRoundedRect(vg, inputX, inputY, inputW, inputH, 6)
    nvgFillColor(vg, nvgRGBA(15, 14, 22, 220)); nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(100, 80, 50, 160)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
    cdkState.inputBoxRect = { x = inputX, y = inputY, w = inputW, h = inputH }
    -- 输入文字 / 占位符
    nvgFontSize(vg, 22)
    nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)
    local textY = inputY + inputH / 2
    if #cdkState.inputText > 0 then
        nvgFillColor(vg, nvgRGBA(255, 255, 255, 230))
        nvgText(vg, inputX + 10, textY, cdkState.inputText, nil)
        -- 光标闪烁
        if math.floor(os.clock() * 2) % 2 == 0 then
            local tw = nvgTextBounds(vg, 0, 0, cdkState.inputText, nil)
            nvgBeginPath(vg); nvgRect(vg, inputX + 10 + tw + 2, inputY + 8, 2, inputH - 16)
            nvgFillColor(vg, nvgRGBA(255, 255, 255, 200)); nvgFill(vg)
        end
    else
        nvgFillColor(vg, nvgRGBA(150, 140, 130, 120))
        nvgText(vg, inputX + 10, textY, "请用键盘输入兑换码", nil)
        -- 光标
        if math.floor(os.clock() * 2) % 2 == 0 then
            nvgBeginPath(vg); nvgRect(vg, inputX + 10, inputY + 8, 2, inputH - 16)
            nvgFillColor(vg, nvgRGBA(255, 255, 255, 200)); nvgFill(vg)
        end
    end

    -- 结果反馈 (在输入框下方)
    local feedbackY = inputY + inputH + 4
    if cdkState.resultTimer > 0 then
        nvgFontSize(vg, 20)
        nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        if cdkState.resultOk then
            nvgFillColor(vg, nvgRGBA(80, 230, 80, 230))
        else
            nvgFillColor(vg, nvgRGBA(255, 80, 80, 230))
        end
        nvgText(vg, W / 2, feedbackY + 8, cdkState.resultText, nil)
    end

    -- ======== 按钮行: 粘贴 | 清空 | 兑换 | 关闭 ========
    local btnY = inputY + inputH + 32
    local btnH = 42
    local btnGap = 8
    local btnTotalW = pw - 40
    local btnStartX = px + 20
    -- 4个按钮均分宽度
    local btnW = math.floor((btnTotalW - btnGap * 3) / 4)

    -- 粘贴
    local pasteX = btnStartX
    nvgBeginPath(vg); nvgRoundedRect(vg, pasteX, btnY, btnW, btnH, 6)
    nvgFillColor(vg, nvgRGBA(50, 80, 120, 220)); nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(100, 150, 200, 140)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
    nvgFontSize(vg, 20)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(pasteX + btnW / 2, btnY + btnH / 2, "粘贴")
    cdkState.pasteBtnRect = { x = pasteX, y = btnY, w = btnW, h = btnH }

    -- 清空
    local clearX = pasteX + btnW + btnGap
    nvgBeginPath(vg); nvgRoundedRect(vg, clearX, btnY, btnW, btnH, 6)
    nvgFillColor(vg, nvgRGBA(60, 55, 70, 220)); nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(90, 45, 55, 100)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
    nvgFontSize(vg, 20)
    DrawWhiteInkText(clearX + btnW / 2, btnY + btnH / 2, "清空")
    cdkState.clearBtnRect = { x = clearX, y = btnY, w = btnW, h = btnH }

    -- 兑换
    local redeemX = clearX + btnW + btnGap
    nvgBeginPath(vg); nvgRoundedRect(vg, redeemX, btnY, btnW, btnH, 6)
    nvgFillPaint(vg, nvgLinearGradient(vg, redeemX, btnY, redeemX, btnY + btnH,
        nvgRGBA(160, 120, 40, 230), nvgRGBA(120, 80, 20, 230)))
    nvgFill(vg)
    nvgFontSize(vg, 20)
    DrawWhiteInkText(redeemX + btnW / 2, btnY + btnH / 2, "兑换")
    cdkState.redeemBtnRect = { x = redeemX, y = btnY, w = btnW, h = btnH }

    -- 关闭
    local closeX = redeemX + btnW + btnGap
    local closeW = btnStartX + btnTotalW - closeX  -- 最后一个按钮吃掉余量
    nvgBeginPath(vg); nvgRoundedRect(vg, closeX, btnY, closeW, btnH, 6)
    nvgFillColor(vg, nvgRGBA(60, 55, 70, 220)); nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(90, 45, 55, 100)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
    nvgFontSize(vg, 20)
    DrawWhiteInkText(closeX + closeW / 2, btnY + btnH / 2, "关闭")
    cdkState.closeBtnRect = { x = closeX, y = btnY, w = closeW, h = btnH }
end

-- ============================================================================
-- 召唤武灵 (抽卡界面) - 设计坐标
-- ============================================================================
function DrawGachaScreen()
    if gameState.phase ~= "GACHA" then return end

    local W = DESIGN_W
    local H = DESIGN_H
    local cx = W / 2
    local t = gachaState.animTimer

    -- 1. 背景 (复用首页背景图 + 深色调)
    DrawBgImage(IMG.menuBg, W, H, 1143, 2048)

    -- 深色遮罩 (比首页更暗, 突出抽卡区域)
    nvgBeginPath(vg); nvgRect(vg, 0, 0, W, H)
    nvgFillColor(vg, nvgRGBA(5, 8, 18, 160)); nvgFill(vg)

    -- 底部渐变
    local botGrad = nvgLinearGradient(vg, 0, H * 0.65, 0, H,
        nvgRGBA(0, 0, 0, 0), nvgRGBA(5, 8, 15, 180))
    nvgBeginPath(vg); nvgRect(vg, 0, H * 0.65, W, H * 0.35)
    nvgFillPaint(vg, botGrad); nvgFill(vg)

    nvgFontFaceId(vg, GetMainFont())

    -- ===========================
    -- 2. 顶部返回按钮 + 标题 + 虎符显示
    -- ===========================
    local topBarY = 10
    local backW, backH = 100, 40
    local backX = 10

    -- 返回按钮
    nvgBeginPath(vg)
    nvgRoundedRect(vg, backX, topBarY, backW, backH, 6)
    nvgFillColor(vg, nvgRGBA(20, 25, 40, 200)); nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(90, 45, 55, 160)); nvgStrokeWidth(vg, 1.5); nvgStroke(vg)
    nvgFontSize(vg, 22)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(backX + backW / 2, topBarY + backH / 2, "< 返回")
    gachaBackBtnRect = { x = backX, y = topBarY, w = backW, h = backH }

    -- Tab 切换按钮 (武灵 / 武技 / 兵符 / 限定) — grid 排列，避免与虎符重叠
    local hasSealUnlock = HasMaxConstellationHero()
    local tabW = 65
    local tabH = 32
    local tabGap = 5
    local tabLabels, tabCount
    if hasSealUnlock then
        tabLabels = { "武灵", "武技", "兵符", "限定" }
        tabCount = 4
    else
        tabLabels = { "武灵", "武技", "限定" }
        tabCount = 3
    end
    local tabTotalW = tabW * tabCount + tabGap * (tabCount - 1)
    local tabStartX = math.floor((W - tabTotalW) / 2)
    local tabY = topBarY + backH + 6
    gachaTabRects = {}
    for ti = 1, tabCount do
        local tx = tabStartX + (ti - 1) * (tabW + tabGap)
        nvgBeginPath(vg); nvgRoundedRect(vg, tx, tabY, tabW, tabH, 5)
        if gachaState.currentTab == ti then
            local tabGrad = nvgLinearGradient(vg, tx, tabY, tx, tabY + tabH,
                nvgRGBA(180, 150, 70, 220), nvgRGBA(140, 100, 40, 220))
            nvgFillPaint(vg, tabGrad); nvgFill(vg)
        else
            nvgFillColor(vg, nvgRGBA(25, 30, 50, 180)); nvgFill(vg)
            nvgStrokeColor(vg, nvgRGBA(120, 100, 60, 120)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
        end
        nvgFontSize(vg, 18)
        nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        if gachaState.currentTab == ti then
            nvgFillColor(vg, nvgRGBA(40, 20, 5, 250))
            nvgText(vg, tx + tabW / 2, tabY + tabH / 2, tabLabels[ti], nil)
        else
            DrawWhiteInkText(tx + tabW / 2, tabY + tabH / 2, tabLabels[ti])
        end
        gachaTabRects[ti] = { x = tx, y = tabY, w = tabW, h = tabH }
    end

    -- 虎符显示 (右上角) + 广告按钮
    local jadeBoxW = 185
    local jadeBoxH = 30
    local jadeBoxX = W - jadeBoxW - 10
    local jadeBoxY = topBarY + (backH - jadeBoxH) / 2

    nvgBeginPath(vg); nvgRoundedRect(vg, jadeBoxX, jadeBoxY, jadeBoxW, jadeBoxH, 4)
    nvgFillColor(vg, nvgRGBA(15, 20, 35, 140)); nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(120, 200, 160, 80)); nvgStrokeWidth(vg, 0.8); nvgStroke(vg)

    nvgFontSize(vg, 19)
    nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(jadeBoxX + 8, jadeBoxY + jadeBoxH / 2, "虎符")
    nvgFontSize(vg, 20)
    nvgTextAlign(vg, NVG_ALIGN_RIGHT + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(jadeBoxX + jadeBoxW - 36, jadeBoxY + jadeBoxH / 2, FormatJade(playerInfo.jade))

    -- 广告 + 按钮
    local gadBtnW = 36
    local gadBtnH = 28
    local gadBtnX = jadeBoxX + jadeBoxW - gadBtnW - 3
    local gadBtnY = jadeBoxY + (jadeBoxH - gadBtnH) / 2
    local gadPulse = 0.7 + 0.3 * math.sin(t * 3)
    nvgBeginPath(vg); nvgRoundedRect(vg, gadBtnX, gadBtnY, gadBtnW, gadBtnH, 4)
    nvgFillColor(vg, nvgRGBA(60, 160, 100, math.floor(170 * gadPulse))); nvgFill(vg)
    nvgFontSize(vg, 22)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(gadBtnX + gadBtnW / 2, gadBtnY + gadBtnH / 2, "+")
    -- 点击区域覆盖整个虎符框+下方提示文字，防止误触Tab切换
    local jadeTouchPad = 4
    adRects.jade = { x = jadeBoxX - jadeTouchPad, y = jadeBoxY - jadeTouchPad, w = jadeBoxW + jadeTouchPad * 2, h = jadeBoxH + 22 + jadeTouchPad }
    -- 广告规则提示
    nvgFontSize(vg, 14)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_TOP)
    nvgFillColor(vg, nvgRGBA(160, 220, 180, math.floor(140 * gadPulse)))
    nvgText(vg, jadeBoxX + jadeBoxW / 2, jadeBoxY + jadeBoxH + 1, "+40虎符", nil)

    -- ===========================
    -- 3. 主内容区域
    -- ===========================

    local curTabType = GetGachaTabType()
    if gachaState.showFragShop then
        -- === 残片仓库 ===
        DrawFragmentShop(t)
    elseif curTabType == "seal" then
        -- === 兵符召唤 Tab ===
        if sealGachaState.pulling then
            DrawSealGachaPullAnimation(t)
        elseif sealGachaState.showResults then
            DrawSealGachaResults()
        else
            DrawSealGachaIdle(t)
        end
    elseif gachaState.pulling then
        -- === 召唤动画 (武灵/武技/限定共用) ===
        DrawGachaPullAnimation(t)
    elseif gachaState.showResults then
        -- === 显示抽卡结果 ===
        if curTabType == "limited" then
            DrawLimitedGachaResults()
        elseif curTabType == "skill" then
            DrawSkillGachaResults()
        else
            DrawGachaResults()
        end
    else
        -- === 待机界面 ===
        if curTabType == "limited" then
            DrawLimitedGachaIdle(t)
        elseif curTabType == "skill" then
            DrawSkillGachaIdle(t)
        else
            DrawGachaIdle(t)
        end
    end

    -- 漂浮粒子 (幽冥气)
    for i = 1, 6 do
        local px = W * (0.1 + 0.8 * ((i * 137 + math.floor(t * 18)) % 100) / 100)
        local py = H * (0.1 + 0.2 * math.sin(t * 0.4 + i * 1.5))
        local pr = 1.2 + math.sin(t * 2 + i) * 0.6
        local pa = math.floor(30 + 20 * math.sin(t * 1.3 + i * 0.8))
        nvgBeginPath(vg); nvgCircle(vg, px, py, pr)
        nvgFillColor(vg, nvgRGBA(180, 200, 255, pa)); nvgFill(vg)
    end

    -- ===========================
    -- 概率规则弹窗 (最顶层)
    -- ===========================
    if gachaState.showRules then
        if curTabType == "seal" then
            DrawSealGachaRulesPopup()
        elseif curTabType == "limited" then
            DrawLimitedGachaRulesPopup()
        elseif curTabType == "skill" then
            DrawSkillGachaRulesPopup()
        else
            DrawGachaRulesPopup()
        end
    end
end

--- 概率规则弹窗
function DrawGachaRulesPopup()
    local W = DESIGN_W
    local H = DESIGN_H
    local cx = W / 2

    -- 半透明遮罩
    nvgBeginPath(vg); nvgRect(vg, 0, 0, W, H)
    nvgFillColor(vg, nvgRGBA(5, 5, 12, 110)); nvgFill(vg)

    -- 弹窗面板
    local panelW = W * 0.82
    local panelH = 750
    local panelX = cx - panelW / 2
    local panelY = H / 2 - panelH / 2 - 20

    -- 面板背景
    local panelGrad = nvgLinearGradient(vg, panelX, panelY, panelX, panelY + panelH,
        nvgRGBA(42, 38, 58, 240), nvgRGBA(30, 26, 44, 245))
    nvgBeginPath(vg); nvgRoundedRect(vg, panelX, panelY, panelW, panelH, 10)
    nvgFillPaint(vg, panelGrad); nvgFill(vg)

    -- 面板边框
    nvgBeginPath(vg); nvgRoundedRect(vg, panelX, panelY, panelW, panelH, 10)
    nvgStrokeColor(vg, nvgRGBA(160, 130, 70, 160)); nvgStrokeWidth(vg, 1.5); nvgStroke(vg)

    nvgFontFaceId(vg, GetMainFont())

    -- 标题
    local titleY = panelY + 28
    nvgFontSize(vg, 35)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(cx, titleY, "召唤规则")

    -- 分隔线
    nvgBeginPath(vg)
    nvgMoveTo(vg, panelX + 20, titleY + 18)
    nvgLineTo(vg, panelX + panelW - 20, titleY + 18)
    nvgStrokeColor(vg, nvgRGBA(140, 120, 70, 80)); nvgStrokeWidth(vg, 1); nvgStroke(vg)

    -- 概率表
    local lineH = 30
    local startY = titleY + 36
    local leftX = panelX + 28
    local rightX = panelX + panelW - 28

    -- 小标题: 出率
    nvgFontSize(vg, 27)
    nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(leftX, startY, "各品质出率")
    startY = startY + lineH * 0.8

    -- 概率行
    local qualities = {
        { tag = "N",   name = "凡品", pct = GameConfig.DRAW_QUALITY_WEIGHTS[1], color = QUALITY_COLORS[1] },
        { tag = "R",   name = "王品", pct = GameConfig.DRAW_QUALITY_WEIGHTS[2], color = QUALITY_COLORS[2] },
        { tag = "SR",  name = "帝品", pct = GameConfig.DRAW_QUALITY_WEIGHTS[3], color = QUALITY_COLORS[3] },
        { tag = "SSR", name = "将品", pct = GameConfig.DRAW_QUALITY_WEIGHTS[4], color = QUALITY_COLORS[4] },
    }

    for _, q in ipairs(qualities) do
        local qc = q.color
        -- 标签色块
        local tagW = #q.tag > 2 and 36 or (#q.tag > 1 and 28 or 20)
        nvgBeginPath(vg); nvgRoundedRect(vg, leftX, startY - 9, tagW, 18, 3)
        nvgFillColor(vg, nvgRGBA(qc[1], qc[2], qc[3], 200)); nvgFill(vg)
        nvgFontSize(vg, 27)
        nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        DrawWhiteInkText(leftX + tagW / 2, startY, q.tag)

        -- 品质名
        nvgFontSize(vg, 27)
        nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)
        nvgFillColor(vg, nvgRGBA(qc[1], qc[2], qc[3], 220))
        nvgText(vg, leftX + tagW + 8, startY, q.name, nil)

        -- 概率百分比
        nvgTextAlign(vg, NVG_ALIGN_RIGHT + NVG_ALIGN_MIDDLE)
        DrawWhiteInkText(rightX, startY, q.pct .. "%")

        startY = startY + lineH * 0.85
    end

    -- 分隔线
    startY = startY + 4
    nvgBeginPath(vg)
    nvgMoveTo(vg, panelX + 20, startY)
    nvgLineTo(vg, panelX + panelW - 20, startY)
    nvgStrokeColor(vg, nvgRGBA(140, 120, 70, 50)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
    startY = startY + 14

    -- 保底规则
    nvgFontSize(vg, 27)
    nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(leftX, startY, "保底机制")
    startY = startY + lineH * 0.8

    nvgFontSize(vg, 24)
    DrawWhiteInkText(leftX, startY, "每" .. GameConfig.PITY_SSR_COUNT .. "抽保底:必出整卡")
    startY = startY + lineH * 0.7

    nvgFontSize(vg, 24)
    DrawWhiteInkText(leftX, startY, "十连大保底:必出SSR整卡")
    startY = startY + lineH * 0.7

    local remaining = GameConfig.PITY_SSR_COUNT - gachaState.pityCounter
    DrawWhiteInkText(leftX, startY, "当前距保底: " .. remaining .. " 抽")
    startY = startY + lineH

    -- 分隔线
    nvgBeginPath(vg)
    nvgMoveTo(vg, panelX + 20, startY)
    nvgLineTo(vg, panelX + panelW - 20, startY)
    nvgStrokeColor(vg, nvgRGBA(140, 120, 70, 50)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
    startY = startY + 14

    -- 残片/整卡出率
    nvgFontSize(vg, 27)
    nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(leftX, startY, "召唤产出形式")
    startY = startY + lineH * 0.8

    nvgFontSize(vg, 14.5)
    nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(leftX, startY, "整卡直出")
    nvgTextAlign(vg, NVG_ALIGN_RIGHT + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(rightX, startY, HERO_FULL_CARD_RATE .. "%")
    startY = startY + lineH * 0.7

    nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(leftX, startY, "武灵残片 (1~5个)")
    nvgTextAlign(vg, NVG_ALIGN_RIGHT + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(rightX, startY, (100 - HERO_FULL_CARD_RATE) .. "%")
    startY = startY + lineH * 0.7

    nvgFontSize(vg, 12)
    nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)
    nvgFillColor(vg, nvgRGBA(180, 170, 150, 180))
    nvgText(vg, leftX, startY, "* 保底SSR必定为整卡", nil)
    startY = startY + lineH * 0.7

    -- 分隔线
    nvgBeginPath(vg)
    nvgMoveTo(vg, panelX + 20, startY)
    nvgLineTo(vg, panelX + panelW - 20, startY)
    nvgStrokeColor(vg, nvgRGBA(140, 120, 70, 50)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
    startY = startY + 14

    -- 残片合成阶梯
    nvgFontSize(vg, 27)
    nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(leftX, startY, "残片合成所需")
    startY = startY + lineH * 0.8

    nvgFontSize(vg, 14.5)
    local fragInfo = {
        { tag = "N",   cnt = HERO_FRAG_EXCHANGE[1], color = QUALITY_COLORS[1] },
        { tag = "R",   cnt = HERO_FRAG_EXCHANGE[2], color = QUALITY_COLORS[2] },
        { tag = "SR",  cnt = HERO_FRAG_EXCHANGE[3], color = QUALITY_COLORS[3] },
        { tag = "SSR", cnt = HERO_FRAG_EXCHANGE[4], color = QUALITY_COLORS[4] },
        { tag = "限定SSR", cnt = HERO_FRAG_EXCHANGE[5], color = QUALITY_COLORS[5] },
    }
    for _, fi in ipairs(fragInfo) do
        local fic = fi.color
        nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)
        nvgFillColor(vg, nvgRGBA(fic[1], fic[2], fic[3], 200))
        nvgText(vg, leftX + 4, startY, fi.tag .. " 品质", nil)
        nvgTextAlign(vg, NVG_ALIGN_RIGHT + NVG_ALIGN_MIDDLE)
        DrawWhiteInkText(rightX, startY, fi.cnt .. " 残片")
        startY = startY + lineH * 0.7
    end

    -- 分隔线
    nvgBeginPath(vg)
    nvgMoveTo(vg, panelX + 20, startY)
    nvgLineTo(vg, panelX + panelW - 20, startY)
    nvgStrokeColor(vg, nvgRGBA(140, 120, 70, 50)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
    startY = startY + 14

    -- 重复角色规则
    nvgFontSize(vg, 27)
    nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(leftX, startY, "满命格重复转化")
    startY = startY + lineH * 0.8

    nvgFontSize(vg, 14.5)
    local refundInfo = {
        { tag = "N",   jade = GameConfig.DUPLICATE_JADE_REWARD[1], color = QUALITY_COLORS[1] },
        { tag = "R",   jade = GameConfig.DUPLICATE_JADE_REWARD[2], color = QUALITY_COLORS[2] },
        { tag = "SR",  jade = GameConfig.DUPLICATE_JADE_REWARD[3], color = QUALITY_COLORS[3] },
        { tag = "SSR", jade = GameConfig.DUPLICATE_JADE_REWARD[4], color = QUALITY_COLORS[4] },
    }

    for _, ri in ipairs(refundInfo) do
        local ric = ri.color
        nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)
        nvgFillColor(vg, nvgRGBA(ric[1], ric[2], ric[3], 200))
        nvgText(vg, leftX + 4, startY, ri.tag .. "  满命格重复", nil)
        nvgTextAlign(vg, NVG_ALIGN_RIGHT + NVG_ALIGN_MIDDLE)
        DrawWhiteInkText(rightX, startY, ">> " .. ri.jade .. " 虎符")
        startY = startY + lineH * 0.7
    end

    -- 关闭按钮
    local closeBtnW = 120
    local closeBtnH = 36
    local closeBtnX = cx - closeBtnW / 2
    local closeBtnY = panelY + panelH - closeBtnH - 14
    nvgBeginPath(vg); nvgRoundedRect(vg, closeBtnX, closeBtnY, closeBtnW, closeBtnH, 6)
    nvgFillColor(vg, nvgRGBA(40, 45, 65, 220)); nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(160, 140, 80, 150)); nvgStrokeWidth(vg, 1.2); nvgStroke(vg)
    nvgFontSize(vg, 29)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(cx, closeBtnY + closeBtnH / 2, "知道了")
    gachaRulesCloseBtnRect = { x = closeBtnX, y = closeBtnY, w = closeBtnW, h = closeBtnH }
end

--- 武技召唤专属规则弹窗（显示阶级概率 + 75抽保底）
-- ============================================================================
-- 兵符召唤 - 待机界面
-- ============================================================================
function DrawSealGachaIdle(t)
    local W = DESIGN_W
    local H = DESIGN_H
    local cx = W / 2
    local circleY = H * 0.42
    local circleR = 90

    nvgFontFaceId(vg, GetMainFont())

    -- 召唤阵: 六芒兵符旋转 (六欲主题)
    for i = 1, 6 do
        local angle = (i / 6) * math.pi * 2 + t * 0.5
        local r = circleR + 6 + 4 * math.sin(t * 1.8 + i)
        -- 六角星点
        local px = cx + math.cos(angle) * r
        local py = circleY + math.sin(angle) * r
        local dotR = 3 + math.sin(t * 2.5 + i * 1.2) * 1.5
        nvgBeginPath(vg); nvgCircle(vg, px, py, dotR)
        local pulse = 0.5 + 0.5 * math.sin(t * 2 + i * 0.9)
        nvgFillColor(vg, nvgRGBA(200, 100, 255, math.floor(160 * pulse))); nvgFill(vg)
        -- 连线到下一点
        local nextAngle = ((i % 6) + 1) / 6 * math.pi * 2 + t * 0.5
        local nr = circleR + 6 + 4 * math.sin(t * 1.8 + (i % 6 + 1))
        local nx = cx + math.cos(nextAngle) * nr
        local ny = circleY + math.sin(nextAngle) * nr
        nvgBeginPath(vg)
        nvgMoveTo(vg, px, py); nvgLineTo(vg, nx, ny)
        nvgStrokeColor(vg, nvgRGBA(160, 80, 220, math.floor(60 * pulse)))
        nvgStrokeWidth(vg, 1); nvgStroke(vg)
    end

    -- 内旋转弧
    for i = 1, 8 do
        local angle = -(i / 8) * math.pi * 2 + t * 0.9
        local arcLen = math.pi / 7
        nvgBeginPath(vg)
        nvgArc(vg, cx, circleY, circleR - 8, angle, angle + arcLen, NVG_CW)
        local pulse = 0.3 + 0.7 * math.sin(t * 2 + i * 0.7)
        nvgStrokeColor(vg, nvgRGBA(180, 130, 255, math.floor(70 * pulse)))
        nvgStrokeWidth(vg, 1.0); nvgStroke(vg)
    end

    -- 中心光晕 (紫色调)
    local glowPulse = 0.5 + 0.5 * math.sin(t * 1.6)
    local glow = nvgRadialGradient(vg, cx, circleY, 5, circleR * 0.7,
        nvgRGBA(160, 80, 220, math.floor(50 * glowPulse)),
        nvgRGBA(100, 50, 180, 0))
    nvgBeginPath(vg); nvgCircle(vg, cx, circleY, circleR * 0.7)
    nvgFillPaint(vg, glow); nvgFill(vg)

    -- 中心文字
    nvgFontSize(vg, 26)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    local textPulse = 0.6 + 0.4 * math.sin(t * 1.5)
    nvgFillColor(vg, nvgRGBA(200, 140, 255, math.floor(200 * textPulse)))
    nvgText(vg, cx, circleY, "咒 印 铭 刻", nil)

    nvgFontSize(vg, 14)
    DrawWhiteInkText(cx, circleY + 32, "满命武灵专属强化")

    -- 满命武灵数量提示
    local maxHeroes = GetMaxConstellationHeroes()
    nvgFontSize(vg, 14)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(cx, circleY + 56, "可铭刻武灵: " .. #maxHeroes .. " 位")

    -- ===========================
    -- 抽卡按钮
    -- ===========================
    local bigPull = playerInfo.jadeUnlockedBigPull
    gachaHundredBtnRect = nil

    if bigPull then
        -- 增强模式: 3个按钮 (10连/50连/100连) 紫色调
        local btnW = 160
        local btnH = 46
        local btnGap = 8
        local btnY1 = H * 0.62
        local btnY2 = btnY1 + btnH + btnGap
        local btnY3 = btnY2 + btnH + btnGap
        local unitCost = SEAL_GACHA_COST

        -- 10连
        local b1x = cx - btnW / 2
        nvgBeginPath(vg); nvgRoundedRect(vg, b1x, btnY1, btnW, btnH, 6)
        nvgFillColor(vg, nvgRGBA(35, 20, 50, 200)); nvgFill(vg)
        local bp1 = 0.7 + 0.3 * math.sin(t * 2)
        nvgStrokeColor(vg, nvgRGBA(180, 100, 220, math.floor(180 * bp1)))
        nvgStrokeWidth(vg, 1.5); nvgStroke(vg)
        nvgFontSize(vg, 20); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        DrawWhiteInkText(cx, btnY1 + btnH / 2 - 7, "十 连 铭 刻")
        nvgFontSize(vg, 14)
        DrawWhiteInkText(cx, btnY1 + btnH / 2 + 12, math.floor(unitCost * 10 * 0.9) .. " 虎符 (9折)")
        gachaSingleBtnRect = { x = b1x, y = btnY1, w = btnW, h = btnH }

        -- 50连
        local b2x = cx - btnW / 2
        nvgBeginPath(vg); nvgRoundedRect(vg, b2x, btnY2, btnW, btnH, 6)
        local g50 = nvgLinearGradient(vg, b2x, btnY2, b2x + btnW, btnY2 + btnH,
            nvgRGBA(45, 20, 65, 220), nvgRGBA(60, 25, 80, 220))
        nvgFillPaint(vg, g50); nvgFill(vg)
        local bp2 = 0.6 + 0.4 * math.sin(t * 2.5)
        nvgBeginPath(vg); nvgRoundedRect(vg, b2x, btnY2, btnW, btnH, 6)
        nvgStrokeColor(vg, nvgRGBA(220, 140, 255, math.floor(200 * bp2)))
        nvgStrokeWidth(vg, 1.8); nvgStroke(vg)
        nvgFontSize(vg, 20); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        DrawWhiteInkText(cx, btnY2 + btnH / 2 - 7, "五十连铭刻")
        nvgFontSize(vg, 14)
        DrawWhiteInkText(cx, btnY2 + btnH / 2 + 12, math.floor(unitCost * 50 * 0.9) .. " 虎符 (9折)")
        gachaTenBtnRect = { x = b2x, y = btnY2, w = btnW, h = btnH }

        -- 100连
        local b3x = cx - btnW / 2
        nvgBeginPath(vg); nvgRoundedRect(vg, b3x, btnY3, btnW, btnH, 6)
        local g100 = nvgLinearGradient(vg, b3x, btnY3, b3x + btnW, btnY3 + btnH,
            nvgRGBA(55, 15, 80, 230), nvgRGBA(70, 10, 90, 230))
        nvgFillPaint(vg, g100); nvgFill(vg)
        local bp3 = 0.5 + 0.5 * math.sin(t * 3)
        nvgBeginPath(vg); nvgRoundedRect(vg, b3x, btnY3, btnW, btnH, 6)
        nvgStrokeColor(vg, nvgRGBA(255, 180, 255, math.floor(220 * bp3)))
        nvgStrokeWidth(vg, 2.0); nvgStroke(vg)
        nvgFontSize(vg, 20); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        DrawWhiteInkText(cx, btnY3 + btnH / 2 - 7, "百 连 铭 刻")
        nvgFontSize(vg, 14)
        DrawWhiteInkText(cx, btnY3 + btnH / 2 + 12, math.floor(unitCost * 100 * 0.9) .. " 虎符 (9折)")
        gachaHundredBtnRect = { x = b3x, y = btnY3, w = btnW, h = btnH }
    else
        -- 原始模式: 2个按钮 (单抽/十连)
        local btnW = 160
        local btnH = 56
        local btnGap = 16
        local btnY1 = H * 0.66
        local btnY2 = btnY1 + btnH + btnGap

        -- 单抽按钮
        local b1x = cx - btnW / 2
        nvgBeginPath(vg); nvgRoundedRect(vg, b1x, btnY1, btnW, btnH, 6)
        nvgFillColor(vg, nvgRGBA(35, 20, 50, 200)); nvgFill(vg)
        local borderPulse1 = 0.7 + 0.3 * math.sin(t * 2)
        nvgStrokeColor(vg, nvgRGBA(180, 100, 220, math.floor(180 * borderPulse1)))
        nvgStrokeWidth(vg, 1.5); nvgStroke(vg)
        nvgFontSize(vg, 22); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        DrawWhiteInkText(cx, btnY1 + btnH / 2 - 10, "单 抽")
        nvgFontSize(vg, 16)
        DrawWhiteInkText(cx, btnY1 + btnH / 2 + 20, SEAL_GACHA_COST .. " 虎符")
        gachaSingleBtnRect = { x = b1x, y = btnY1, w = btnW, h = btnH }

        -- 十连按钮
        local b2x = cx - btnW / 2
        nvgBeginPath(vg); nvgRoundedRect(vg, b2x, btnY2, btnW, btnH, 6)
        local tenGrad = nvgLinearGradient(vg, b2x, btnY2, b2x + btnW, btnY2 + btnH,
            nvgRGBA(45, 20, 65, 220), nvgRGBA(60, 25, 80, 220))
        nvgFillPaint(vg, tenGrad); nvgFill(vg)
        local borderPulse2 = 0.6 + 0.4 * math.sin(t * 2.5)
        nvgBeginPath(vg); nvgRoundedRect(vg, b2x, btnY2, btnW, btnH, 6)
        nvgStrokeColor(vg, nvgRGBA(220, 140, 255, math.floor(200 * borderPulse2)))
        nvgStrokeWidth(vg, 1.8); nvgStroke(vg)
        nvgFontSize(vg, 22); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        DrawWhiteInkText(cx, btnY2 + btnH / 2 - 10, "十 连 铭 刻")
        nvgFontSize(vg, 16)
        DrawWhiteInkText(cx, btnY2 + btnH / 2 + 20, SEAL_GACHA_TEN_COST .. " 虎符 (9折)")
        gachaTenBtnRect = { x = b2x, y = btnY2, w = btnW, h = btnH }
    end

    -- 计算最后一个按钮底部Y (兼容增强模式3按钮)
    local lastBtnBottom = gachaHundredBtnRect and (gachaHundredBtnRect.y + gachaHundredBtnRect.h) or (gachaTenBtnRect.y + gachaTenBtnRect.h)

    -- 兵符持有概览
    local totalSeals = 0
    local totalSlots = 0
    for cardIdx, sd in pairs(sealData) do
        for s = 1, SEAL_MAX_SLOTS do
            if sd.slots[s] then
                totalSeals = totalSeals + 1
                totalSlots = totalSlots + 1
            end
        end
    end
    nvgFontSize(vg, 14)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(cx, lastBtnBottom + 20, "已开启兵符孔: " .. totalSeals)

    -- 经验道具概览
    local expText = ""
    for idx, item in ipairs(SEAL_EXP_ITEMS) do
        local cnt = sealExpItems[idx] or 0
        if cnt > 0 then
            if #expText > 0 then expText = expText .. "  " end
            expText = expText .. item.name .. "×" .. cnt
        end
    end
    if #expText > 0 then
        nvgFontSize(vg, 13)
        DrawWhiteInkText(cx, lastBtnBottom + 42, expText)
    end

    -- "?" 概率规则按钮 (右下角)
    local bottomBtnY = lastBtnBottom + 8
    local qBtnSize = 30
    local qBtnX = W - qBtnSize - 12
    local qBtnY = bottomBtnY
    nvgBeginPath(vg); nvgCircle(vg, qBtnX + qBtnSize / 2, qBtnY + qBtnSize / 2, qBtnSize / 2)
    nvgFillColor(vg, nvgRGBA(50, 30, 65, 200)); nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(180, 120, 220, 160)); nvgStrokeWidth(vg, 1.2); nvgStroke(vg)
    nvgFontSize(vg, 29)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(qBtnX + qBtnSize / 2, qBtnY + qBtnSize / 2, "?")
    gachaRulesBtnRect = { x = qBtnX, y = qBtnY, w = qBtnSize, h = qBtnSize }

    -- 兵符管理入口按钮（左下角）
    local mgrBtnW = 90
    local mgrBtnH = 30
    local mgrBtnX = 12
    local mgrBtnY = bottomBtnY
    nvgBeginPath(vg); nvgRoundedRect(vg, mgrBtnX, mgrBtnY, mgrBtnW, mgrBtnH, 6)
    nvgFillColor(vg, nvgRGBA(35, 30, 50, 210)); nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(180, 100, 220, 160)); nvgStrokeWidth(vg, 1.2); nvgStroke(vg)
    nvgFontSize(vg, 14)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(mgrBtnX + mgrBtnW / 2, mgrBtnY + mgrBtnH / 2, "兵符管理")
    sealMgrBtnRect = { x = mgrBtnX, y = mgrBtnY, w = mgrBtnW, h = mgrBtnH }
end

-- ============================================================================
-- 兵符召唤 - 抽卡动画
-- ============================================================================
function DrawSealGachaPullAnimation(t)
    local W = DESIGN_W
    local H = DESIGN_H
    local cx = W / 2
    local cy = H * 0.40
    local progress = math.min(1, sealGachaState.pullTimer / 1.2)

    -- 紫色扩散光圈
    local maxR = 120
    local r = maxR * progress
    local glow = nvgRadialGradient(vg, cx, cy, r * 0.3, r,
        nvgRGBA(200, 120, 255, math.floor(120 * (1 - progress * 0.5))),
        nvgRGBA(140, 60, 200, 0))
    nvgBeginPath(vg); nvgCircle(vg, cx, cy, r)
    nvgFillPaint(vg, glow); nvgFill(vg)

    -- 旋转咒纹光线
    local lineCount = sealGachaState.pullCount == 10 and 20 or 8
    for i = 1, lineCount do
        local angle = (i / lineCount) * math.pi * 2 + t * 4
        local len = 30 + 80 * progress
        local lsx = cx + math.cos(angle) * 10
        local lsy = cy + math.sin(angle) * 10
        local lex = cx + math.cos(angle) * len
        local ley = cy + math.sin(angle) * len
        nvgBeginPath(vg)
        nvgMoveTo(vg, lsx, lsy); nvgLineTo(vg, lex, ley)
        local la = math.floor(180 * (1 - progress * 0.3))
        nvgStrokeColor(vg, nvgRGBA(200, 140, 255, la))
        nvgStrokeWidth(vg, 1.5); nvgStroke(vg)
    end

    -- 中心紫色闪光
    local flashA = math.floor(255 * math.max(0, progress - 0.6) / 0.4)
    if flashA > 0 then
        nvgBeginPath(vg); nvgRect(vg, 0, 0, W, H)
        nvgFillColor(vg, nvgRGBA(220, 180, 255, flashA)); nvgFill(vg)
    end

    -- 提示文字
    nvgFontFaceId(vg, GetMainFont())
    nvgFontSize(vg, 30)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(cx, H * 0.72, "点击跳过")
end

-- ============================================================================
-- 兵符召唤 - 结果展示
-- ============================================================================
function DrawSealGachaResults()
    local W = DESIGN_W
    local H = DESIGN_H
    local cx = W / 2
    local results = sealGachaState.results
    local count = #results

    -- 半透明全屏遮罩
    nvgBeginPath(vg)
    nvgRect(vg, 0, 0, W, H)
    nvgFillColor(vg, nvgRGBA(0, 0, 0, 160))
    nvgFill(vg)

    nvgFontFaceId(vg, GetMainFont())

    -- 标题
    nvgFontSize(vg, 33)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(cx, 65, "铭刻结果")

    if count == 0 then return end

    if count == 1 then
        -- 单抽: 大卡居中
        local r = results[1]
        local cardY = H * 0.25
        DrawSealResultCard(cx, cardY, r, true)
    else
        -- 按品质降序排序（高品质排前面，兵符优先于经验道具）
        table.sort(results, function(a, b)
            -- 兵符(seal/seal_dupe)排在经验道具(exp_item)前面
            local typeOrder = { seal = 3, seal_dupe = 2, exp_item = 1 }
            local ta = typeOrder[a.type] or 0
            local tb = typeOrder[b.type] or 0
            if ta ~= tb then return ta > tb end
            -- 同类型按品质降序
            local qa = a.sealQ or 0
            local qb = b.sealQ or 0
            return qa > qb
        end)
        -- 十连: 5列×2行 网格
        local cols = 5
        local cardW = 80
        local cardH = 90
        local gap = 8
        local gridW = cols * cardW + (cols - 1) * gap
        local startX = cx - gridW / 2
        local startY = 90

        for i, r in ipairs(results) do
            local col = ((i - 1) % cols)
            local row = math.floor((i - 1) / cols)
            local x = startX + col * (cardW + gap) + cardW / 2
            local y = startY + row * (cardH + 30 + gap)
            DrawSealResultCard(x, y, r, false)
        end
    end

    -- 确认按钮
    local confirmW = 140
    local confirmH = 38
    local confirmX = cx - confirmW / 2
    local confirmY = H * 0.88
    nvgBeginPath(vg)
    nvgRoundedRect(vg, confirmX, confirmY, confirmW, confirmH, 5)
    nvgFillColor(vg, nvgRGBA(35, 20, 50, 200)); nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(180, 120, 220, 180)); nvgStrokeWidth(vg, 1.2); nvgStroke(vg)
    nvgFontSize(vg, 30)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(cx, confirmY + confirmH / 2, "确 认")
    gachaConfirmBtnRect = { x = confirmX, y = confirmY, w = confirmW, h = confirmH }
end

--- 绘制单个兵符结果卡片
--- @param cx number 卡片中心X
--- @param cy number 卡片顶部Y
--- @param r table 结果数据
--- @param isBig boolean 是否大卡
function DrawSealResultCard(cx, cy, r, isBig)
    local fontSize = isBig and 25 or 14
    local nameSize = isBig and 28 or 16
    local tagY = cy

    if r.type == "seal" then
        -- 兵符: 新开孔
        local qc = SEAL_QUALITY_COLORS[r.sealQ] or { 180, 175, 165 }
        local qName = SEAL_QUALITY_NAMES[r.sealQ] or "?"

        -- 兵符图标 (六边形)
        local iconR = isBig and 40 or 22
        DrawSealHexIcon(cx, tagY + iconR + 5, iconR, qc, r.sealQ)

        tagY = tagY + iconR * 2 + 14

        nvgFontSize(vg, nameSize)
        nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        nvgFillColor(vg, nvgRGBA(qc[1], qc[2], qc[3], 240))
        nvgText(vg, cx, tagY, r.slotName .. "兵符", nil)
        tagY = tagY + (isBig and 24 or 16)

        nvgFontSize(vg, fontSize)
        nvgFillColor(vg, nvgRGBA(200, 200, 200, 200))
        nvgText(vg, cx, tagY, r.heroName, nil)
        tagY = tagY + (isBig and 22 or 14)

        nvgFontSize(vg, fontSize - 2)
        nvgFillColor(vg, nvgRGBA(120, 255, 160, 220))
        nvgText(vg, cx, tagY, "新!", nil)

    elseif r.type == "seal_dupe" then
        -- 重复兵符: 返还虎符
        local qc = SEAL_QUALITY_COLORS[r.sealQ] or { 180, 175, 165 }

        local iconR = isBig and 40 or 22
        DrawSealHexIcon(cx, tagY + iconR + 5, iconR, qc, r.sealQ)
        tagY = tagY + iconR * 2 + 14

        nvgFontSize(vg, nameSize)
        nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        nvgFillColor(vg, nvgRGBA(qc[1], qc[2], qc[3], 180))
        nvgText(vg, cx, tagY, r.heroName, nil)
        tagY = tagY + (isBig and 24 or 16)

        nvgFontSize(vg, fontSize)
        nvgFillColor(vg, nvgRGBA(255, 215, 0, 220))
        nvgText(vg, cx, tagY, "重复 +" .. r.refund .. " 虎符", nil)

    elseif r.type == "exp_item" then
        -- 经验道具 (正式图片渲染)
        local itemIdx = r.itemIdx
        local itemColors = {
            [1] = { 180, 200, 220 },  -- 微光: 浅蓝
            [2] = { 140, 160, 200 },  -- 幽暗: 灰蓝
            [3] = { 160, 100, 220 },  -- 讨伐: 紫
            [4] = { 80, 50, 120 },    -- 虚无: 暗紫
        }
        local ic = itemColors[itemIdx] or { 180, 180, 180 }

        -- 经验道具图标 (使用图片)
        local iconSize = isBig and 64 or 36
        local imgHandle = sealExpItemImages[itemIdx]
        if imgHandle and imgHandle > 0 then
            local imgPat = nvgImagePattern(vg, cx - iconSize / 2, tagY + 5, iconSize, iconSize, 0, imgHandle, 1.0)
            nvgBeginPath(vg)
            nvgRoundedRect(vg, cx - iconSize / 2, tagY + 5, iconSize, iconSize, 6)
            nvgFillPaint(vg, imgPat); nvgFill(vg)
            -- 品质边框光晕
            nvgBeginPath(vg)
            nvgRoundedRect(vg, cx - iconSize / 2, tagY + 5, iconSize, iconSize, 6)
            nvgStrokeColor(vg, nvgRGBA(ic[1], ic[2], ic[3], 160))
            nvgStrokeWidth(vg, 1.2); nvgStroke(vg)
        else
            -- 图片未加载时的回退: 圆形
            local iconR = isBig and 32 or 18
            nvgBeginPath(vg); nvgCircle(vg, cx, tagY + iconR + 5, iconR)
            local igr = nvgRadialGradient(vg, cx, tagY + iconR + 5, 3, iconR,
                nvgRGBA(ic[1], ic[2], ic[3], 200), nvgRGBA(ic[1] * 0.5, ic[2] * 0.5, ic[3] * 0.5, 150))
            nvgFillPaint(vg, igr); nvgFill(vg)
            nvgStrokeColor(vg, nvgRGBA(ic[1], ic[2], ic[3], 180)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
            nvgFontSize(vg, isBig and 18 or 10)
            nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
            nvgFillColor(vg, nvgRGBA(255, 255, 255, 200))
            nvgText(vg, cx, tagY + iconR + 5, "墨", nil)
        end

        tagY = tagY + iconSize + 14

        nvgFontSize(vg, nameSize)
        nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        nvgFillColor(vg, nvgRGBA(ic[1], ic[2], ic[3], 240))
        nvgText(vg, cx, tagY, r.itemName, nil)
        tagY = tagY + (isBig and 22 or 14)

        nvgFontSize(vg, fontSize)
        nvgFillColor(vg, nvgRGBA(200, 200, 200, 200))
        nvgText(vg, cx, tagY, "EXP +" .. r.itemExp, nil)
    end
end

--- 绘制六边形兵符图标
function DrawSealHexIcon(cx, cy, r, color, quality)
    nvgBeginPath(vg)
    for i = 0, 5 do
        local angle = (i / 6) * math.pi * 2 - math.pi / 2
        local px = cx + math.cos(angle) * r
        local py = cy + math.sin(angle) * r
        if i == 0 then nvgMoveTo(vg, px, py)
        else nvgLineTo(vg, px, py) end
    end
    nvgClosePath(vg)
    local gr = nvgRadialGradient(vg, cx, cy, 2, r,
        nvgRGBA(color[1], color[2], color[3], 160),
        nvgRGBA(color[1] * 0.4, color[2] * 0.4, color[3] * 0.4, 100))
    nvgFillPaint(vg, gr); nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(color[1], color[2], color[3], 200))
    nvgStrokeWidth(vg, 1.5); nvgStroke(vg)

    -- 品质文字 (上半区, 避免与 Lv 文字重叠)
    local qName = SEAL_QUALITY_NAMES[quality] or "?"
    nvgFontSize(vg, math.max(9, r * 0.38))
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    nvgFillColor(vg, nvgRGBA(255, 255, 255, 200))
    nvgText(vg, cx, cy - r * 0.32, qName, nil)
end

-- ============================================================================
-- 兵符召唤 - 概率规则弹窗
-- ============================================================================
function DrawSealGachaRulesPopup()
    local W = DESIGN_W
    local H = DESIGN_H
    local cx = W / 2

    -- 半透明遮罩
    nvgBeginPath(vg); nvgRect(vg, 0, 0, W, H)
    nvgFillColor(vg, nvgRGBA(5, 5, 12, 110)); nvgFill(vg)

    -- 弹窗面板
    local panelW = W * 0.84
    local panelH = 1380
    local panelX = cx - panelW / 2
    local panelY = H / 2 - panelH / 2 - 10

    -- 面板背景（暗紫色调）
    local panelGrad = nvgLinearGradient(vg, panelX, panelY, panelX, panelY + panelH,
        nvgRGBA(50, 25, 65, 240), nvgRGBA(35, 18, 50, 245))
    nvgBeginPath(vg); nvgRoundedRect(vg, panelX, panelY, panelW, panelH, 10)
    nvgFillPaint(vg, panelGrad); nvgFill(vg)
    nvgBeginPath(vg); nvgRoundedRect(vg, panelX, panelY, panelW, panelH, 10)
    nvgStrokeColor(vg, nvgRGBA(180, 100, 255, 160)); nvgStrokeWidth(vg, 1.5); nvgStroke(vg)

    nvgFontFaceId(vg, GetMainFont())

    -- 标题
    local titleY = panelY + 28
    nvgFontSize(vg, 35)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(cx, titleY, "兵符铭刻规则")

    -- 分隔线
    nvgBeginPath(vg)
    nvgMoveTo(vg, panelX + 20, titleY + 18)
    nvgLineTo(vg, panelX + panelW - 20, titleY + 18)
    nvgStrokeColor(vg, nvgRGBA(160, 100, 220, 80)); nvgStrokeWidth(vg, 1); nvgStroke(vg)

    local lineH = 26
    local startY = titleY + 38
    local leftX = panelX + 24

    -- 解锁条件
    nvgFontSize(vg, 25)
    nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(leftX, startY, "解锁条件")
    startY = startY + lineH
    nvgFontSize(vg, 19)
    DrawWhiteInkText(leftX + 10, startY, "· 拥有至少 1 个满命格(C6)武灵")
    startY = startY + lineH * 0.9

    -- 分隔线
    nvgBeginPath(vg)
    nvgMoveTo(vg, panelX + 20, startY)
    nvgLineTo(vg, panelX + panelW - 20, startY)
    nvgStrokeColor(vg, nvgRGBA(160, 100, 220, 50)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
    startY = startY + 12

    -- 产出概率
    nvgFontSize(vg, 25)
    DrawWhiteInkText(leftX, startY, "产出概率")
    startY = startY + lineH

    nvgFontSize(vg, 19)
    nvgFillColor(vg, nvgRGBA(200, 140, 255, 220))
    nvgText(vg, leftX + 10, startY, "· 兵符(开孔): 60%", nil)
    startY = startY + lineH * 0.8
    nvgFillColor(vg, nvgRGBA(180, 200, 220, 220))
    nvgText(vg, leftX + 10, startY, "· 兵符经验道具: 40%", nil)
    startY = startY + lineH * 0.9

    -- 分隔线
    nvgBeginPath(vg)
    nvgMoveTo(vg, panelX + 20, startY)
    nvgLineTo(vg, panelX + panelW - 20, startY)
    nvgStrokeColor(vg, nvgRGBA(160, 100, 220, 50)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
    startY = startY + 12

    -- 兵符等阶概率 (与装备相同)
    nvgFontSize(vg, 25)
    DrawWhiteInkText(leftX, startY, "兵符等阶 (无保底)")
    startY = startY + lineH

    local tierProbs = {
        { name = "凡品",   prob = "52.5%", color = SEAL_QUALITY_COLORS[1] },
        { name = "良品",   prob = "25%",   color = SEAL_QUALITY_COLORS[2] },
        { name = "优品",   prob = "15%",   color = SEAL_QUALITY_COLORS[3] },
        { name = "将品", prob = "5%",    color = SEAL_QUALITY_COLORS[4] },
        { name = "王品", prob = "2%",    color = SEAL_QUALITY_COLORS[5] },
        { name = "帝品", prob = "0.5%",  color = SEAL_QUALITY_COLORS[6] },
    }
    nvgFontSize(vg, 18)
    for _, tp in ipairs(tierProbs) do
        local c = tp.color
        nvgFillColor(vg, nvgRGBA(c[1], c[2], c[3], 220))
        nvgText(vg, leftX + 10, startY, "· " .. tp.name .. ": " .. tp.prob, nil)
        startY = startY + lineH * 0.7
    end
    startY = startY + 4

    -- 分隔线
    nvgBeginPath(vg)
    nvgMoveTo(vg, panelX + 20, startY)
    nvgLineTo(vg, panelX + panelW - 20, startY)
    nvgStrokeColor(vg, nvgRGBA(160, 100, 220, 50)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
    startY = startY + 12

    -- 兵符说明
    nvgFontSize(vg, 25)
    DrawWhiteInkText(leftX, startY, "兵符系统")
    startY = startY + lineH

    nvgFontSize(vg, 19)
    nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(leftX + 10, startY, "· 兵符独特绑定特定武灵")
    startY = startY + lineH * 0.75
    DrawWhiteInkText(leftX + 10, startY, "· 每位武灵最多开 " .. SEAL_MAX_SLOTS .. " 孔(六欲)")
    startY = startY + lineH * 0.75
    DrawWhiteInkText(leftX + 10, startY, "· 可消耗咒墨强化至 Lv." .. SEAL_MAX_LEVEL)
    startY = startY + lineH * 0.75
    DrawWhiteInkText(leftX + 10, startY, "· 强化难度大, 但提升显著")
    startY = startY + lineH * 0.9

    -- 分隔线
    nvgBeginPath(vg)
    nvgMoveTo(vg, panelX + 20, startY)
    nvgLineTo(vg, panelX + panelW - 20, startY)
    nvgStrokeColor(vg, nvgRGBA(160, 100, 220, 50)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
    startY = startY + 12

    -- 六欲效果详解
    nvgFontSize(vg, 25)
    DrawWhiteInkText(leftX, startY, "六欲孔位详解")
    startY = startY + lineH

    local qualityNames = { "凡", "良", "优", "将", "侯", "王", "帝" }
    nvgFontSize(vg, 17)
    for si = 1, 6 do
        local eff = SEAL_SLOT_EFFECTS[si]
        local stc = SEAL_SLOT_THEME_COLORS[si]
        if eff and stc then
            -- 孔位名称 + 主题
            nvgFillColor(vg, nvgRGBA(stc[1], stc[2], stc[3], 240))
            nvgFontSize(vg, 18)
            nvgText(vg, leftX + 10, startY, "· " .. SEAL_SLOT_NAMES[si] .. " - " .. eff.theme, nil)
            startY = startY + lineH * 0.7
            -- 效果描述
            nvgFontSize(vg, 15)
            nvgFillColor(vg, nvgRGBA(210, 190, 230, 210))
            nvgText(vg, leftX + 18, startY, eff.desc, nil)
            startY = startY + lineH * 0.65
            -- 主属性数值范围
            nvgFillColor(vg, nvgRGBA(200, 200, 180, 200))
            local mainLine
            if eff.mainName then
                local v1 = eff[1] and eff[1].main or 0
                local v7 = eff[7] and eff[7].main or 0
                if si == 1 then
                    mainLine = "主: " .. eff.mainName .. "  " .. qualityNames[1] .. "+" .. string.format("%.1f", v1) .. " → " .. qualityNames[7] .. "+" .. string.format("%.1f", v7) .. " (每级)"
                else
                    mainLine = "主: " .. eff.mainName .. "%  " .. qualityNames[1] .. "+" .. string.format("%.1f", v1) .. "% → " .. qualityNames[7] .. "+" .. string.format("%.1f", v7) .. "%"
                end
                nvgText(vg, leftX + 18, startY, mainLine, nil)
                startY = startY + lineH * 0.6
            end
            -- 副属性数值范围
            if eff.subName then
                local s1 = eff[1] and eff[1].sub or 0
                local s7 = eff[7] and eff[7].sub or 0
                local subLine = "副: " .. eff.subName .. "%  " .. qualityNames[1] .. "+" .. string.format("%.1f", s1) .. "% → " .. qualityNames[7] .. "+" .. string.format("%.1f", s7) .. "%"
                nvgText(vg, leftX + 18, startY, subLine, nil)
                startY = startY + lineH * 0.6
            end
            startY = startY + 4
            nvgFontSize(vg, 17)
        end
    end
    startY = startY + 4

    -- 分隔线
    nvgBeginPath(vg)
    nvgMoveTo(vg, panelX + 20, startY)
    nvgLineTo(vg, panelX + panelW - 20, startY)
    nvgStrokeColor(vg, nvgRGBA(160, 100, 220, 50)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
    startY = startY + 12

    -- 重复兵符 & 费用
    nvgFontSize(vg, 25)
    DrawWhiteInkText(leftX, startY, "重复兵符 & 费用")
    startY = startY + lineH

    nvgFontSize(vg, 19)
    DrawWhiteInkText(leftX + 10, startY, "· 已满 " .. SEAL_MAX_SLOTS .. " 孔再抽到兵符 → 返还 " .. SEAL_DUPE_REFUND .. " 虎符")
    startY = startY + lineH * 0.75
    DrawWhiteInkText(leftX + 10, startY, "· 单抽 " .. SEAL_GACHA_COST .. " 虎符 / 十连 " .. SEAL_GACHA_TEN_COST .. " 虎符(9折)")

    -- 关闭按钮
    local closeBtnW = 120
    local closeBtnH = 36
    local closeBtnX = cx - closeBtnW / 2
    local closeBtnY = panelY + panelH - closeBtnH - 14
    nvgBeginPath(vg); nvgRoundedRect(vg, closeBtnX, closeBtnY, closeBtnW, closeBtnH, 6)
    nvgFillColor(vg, nvgRGBA(50, 30, 65, 220)); nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(200, 140, 255, 150)); nvgStrokeWidth(vg, 1.2); nvgStroke(vg)
    nvgFontSize(vg, 29)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(cx, closeBtnY + closeBtnH / 2, "知道了")
    gachaRulesCloseBtnRect = { x = closeBtnX, y = closeBtnY, w = closeBtnW, h = closeBtnH }
end

-- ============================================================================
-- 兵符管理界面 - 查看/升级兵符 (正式版: 卡牌居中 + 六欲环绕)
-- ============================================================================
function DrawSealMgrScreen()
    local W = DESIGN_W
    local H = DESIGN_H
    local cx = W / 2
    local t = menuAnimTimer

    -- 背景
    DrawMenuBg(W, H)
    nvgBeginPath(vg); nvgRect(vg, 0, 0, W, H)
    nvgFillColor(vg, nvgRGBA(12, 6, 24, 80)); nvgFill(vg)

    nvgFontFaceId(vg, GetMainFont())

    -- 清空点击区域
    sealMgrHeroRects = {}
    sealMgrSlotRects = {}
    sealMgrExpItemRects = {}

    -- ============ 顶部栏 ============
    local topBarY = 14
    local backW, backH = 100, 40
    local backX = 12
    nvgBeginPath(vg); nvgRoundedRect(vg, backX, topBarY, backW, backH, 4)
    nvgFillColor(vg, nvgRGBA(20, 15, 35, 200)); nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(160, 80, 220, 140)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
    nvgFontSize(vg, 24)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(backX + backW / 2, topBarY + backH / 2, "< 返回")
    sealMgrBtnRects.back = { x = backX, y = topBarY, w = backW, h = backH }

    nvgFontSize(vg, 36)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(cx, topBarY + backH / 2, "兵符管理")
    DrawHelpBtn(DESIGN_W - 14 - 30, topBarY + (backH - 30) / 2, 30)

    -- 仓库入口按钮
    local invBtnW, invBtnH = 80, 34
    local invBtnX = DESIGN_W - 14 - 30 - 10 - invBtnW
    local invBtnY = topBarY + (backH - invBtnH) / 2
    nvgBeginPath(vg); nvgRoundedRect(vg, invBtnX, invBtnY, invBtnW, invBtnH, 4)
    nvgFillColor(vg, nvgRGBA(30, 55, 85, 220)); nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(70, 140, 210, 160)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
    nvgFontSize(vg, 18)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(invBtnX + invBtnW / 2, invBtnY + invBtnH / 2, "仓库")
    sealMgrBtnRects.inventoryBtn = { x = invBtnX, y = invBtnY, w = invBtnW, h = invBtnH }
    -- 仓库数量角标
    if #sealInventory > 0 then
        local badgeR = 10
        local badgeX = invBtnX + invBtnW - 4
        local badgeY = invBtnY
        nvgBeginPath(vg); nvgCircle(vg, badgeX, badgeY, badgeR)
        nvgFillColor(vg, nvgRGBA(200, 50, 50, 240)); nvgFill(vg)
        nvgFontSize(vg, 12)
        nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        nvgFillColor(vg, nvgRGBA(255, 255, 255, 255))
        nvgText(vg, badgeX, badgeY, tostring(#sealInventory), nil)
    end

    -- ============ 筛选分解 + 选中分解 按钮 (仓库按钮左侧) ============
    sealInvFilterBtnRects.batchDecompBtn = nil
    sealInvFilterBtnRects.selectDecompBtn = nil
    if #sealInventory > 0 and not sealInvFilterState.selectMode then
        local dbtnW, dbtnH = 88, 30
        local dbtnGap = 6
        local dbtn1X = invBtnX - dbtnGap - dbtnW
        local dbtnY = topBarY + (backH - dbtnH) / 2
        -- 筛选分解
        nvgBeginPath(vg); nvgRoundedRect(vg, dbtn1X, dbtnY, dbtnW, dbtnH, 4)
        nvgFillColor(vg, nvgRGBA(110, 40, 40, 220)); nvgFill(vg)
        nvgStrokeColor(vg, nvgRGBA(200, 80, 80, 160)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
        nvgFontSize(vg, 16)
        nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        DrawWhiteInkText(dbtn1X + dbtnW / 2, dbtnY + dbtnH / 2, "筛选分解")
        sealInvFilterBtnRects.batchDecompBtn = { x = dbtn1X, y = dbtnY, w = dbtnW, h = dbtnH }
        -- 选中分解
        local dbtn2X = dbtn1X - dbtnGap - dbtnW
        nvgBeginPath(vg); nvgRoundedRect(vg, dbtn2X, dbtnY, dbtnW, dbtnH, 4)
        nvgFillColor(vg, nvgRGBA(40, 60, 100, 220)); nvgFill(vg)
        nvgStrokeColor(vg, nvgRGBA(80, 140, 200, 160)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
        nvgFontSize(vg, 16)
        DrawWhiteInkText(dbtn2X + dbtnW / 2, dbtnY + dbtnH / 2, "选中分解")
        sealInvFilterBtnRects.selectDecompBtn = { x = dbtn2X, y = dbtnY, w = dbtnW, h = dbtnH }
    end

    -- ============ 获取满命武灵 ============
    local maxHeroes = GetMaxConstellationHeroes()

    -- 自动选择第一个英雄
    if not sealMgrState.selectedHero and #maxHeroes > 0 then
        sealMgrState.selectedHero = maxHeroes[1].cardIdx
    end

    -- ============ 选中分解模式: 全屏仓库列表 ============
    if sealInvFilterState.selectMode then
        DrawSealSelectModeList()

        -- 选中分解确认弹窗
        if sealInvFilterState.selectConfirmShow then
            DrawSealSelectDecompConfirm()
        end

        -- 筛选分解确认弹窗（理论上不会在选中模式出现，但保险）
        if sealInvFilterState.batchConfirmShow then
            DrawSealBatchDecompConfirm()
        end
        return
    end

    -- ============ 布局参数 ============
    local cardH = 165
    local cardW = math.floor(cardH * CARD_RATIO)
    local cardCX = cx                    -- 卡牌中心X
    local cardCY = topBarY + backH + 220 -- 卡牌中心Y
    local cardX = cardCX - cardW / 2
    local cardY = cardCY - cardH / 2
    local orbitR = 155                   -- 兵符环绕半径

    -- 六条连线的卡牌锚点 (卡牌边缘不同位置)
    -- 顺序: 贪欲(上), 嗔欲(右上), 痴欲(右下), 慢欲(下), 疑欲(左下), 邪欲(左上)
    local cardAnchors = {
        { x = cardCX,              y = cardY - 2 },              -- 1 贪欲: 顶部中央
        { x = cardX + cardW + 2,   y = cardY + cardH * 0.25 },   -- 2 嗔欲: 右侧偏上
        { x = cardX + cardW + 2,   y = cardY + cardH * 0.75 },   -- 3 痴欲: 右侧偏下
        { x = cardCX,              y = cardY + cardH + 2 },       -- 4 慢欲: 底部中央
        { x = cardX - 2,           y = cardY + cardH * 0.75 },    -- 5 疑欲: 左侧偏下
        { x = cardX - 2,           y = cardY + cardH * 0.25 },    -- 6 邪欲: 左侧偏上
    }

    if sealMgrState.selectedHero then
        local cardIdx = sealMgrState.selectedHero
        local card = HERO_CARDS[cardIdx]
        local sd = sealData[cardIdx]
        local heroQ = card and card.quality or 1
        local qc = QUALITY_COLORS[heroQ] or { 200, 200, 200 }
        local hero = playerHeroes[cardIdx]
        local constellation = hero and hero.constellation or 0
        local slotCount = GetSealSlotCount(cardIdx)

        -- ========== 1. 底层装饰: 轨道环 ==========
        -- 外环 (缓慢脉冲)
        local outerPulse = 0.3 + 0.15 * math.sin(t * 0.6)
        nvgBeginPath(vg)
        nvgCircle(vg, cardCX, cardCY, orbitR + 12)
        nvgStrokeColor(vg, nvgRGBA(100, 50, 180, math.floor(50 * outerPulse)))
        nvgStrokeWidth(vg, 1.0)
        nvgStroke(vg)

        -- 主轨道环 (呼吸)
        local mainPulse = 0.5 + 0.3 * math.sin(t * 0.9)
        nvgBeginPath(vg)
        nvgCircle(vg, cardCX, cardCY, orbitR)
        nvgStrokeColor(vg, nvgRGBA(140, 80, 220, math.floor(40 * mainPulse)))
        nvgStrokeWidth(vg, 0.7)
        nvgStroke(vg)

        -- 旋转刻度标记 (12个小点，缓慢旋转)
        local rotAngle = t * 0.15
        for i = 0, 11 do
            local da = (i / 12) * math.pi * 2 + rotAngle
            local dx = cardCX + math.cos(da) * (orbitR + 6)
            local dy = cardCY + math.sin(da) * (orbitR + 6)
            local dotAlpha = 30 + 20 * math.sin(t * 1.2 + i * 0.5)
            nvgBeginPath(vg)
            nvgCircle(vg, dx, dy, 1.5)
            nvgFillColor(vg, nvgRGBA(180, 120, 255, math.floor(dotAlpha)))
            nvgFill(vg)
        end

        -- ========== 2. 连接线 (各指向卡牌不同锚点) ==========
        for slotIdx = 1, SEAL_MAX_SLOTS do
            local angle = ((slotIdx - 1) / SEAL_MAX_SLOTS) * math.pi * 2 - math.pi / 2
            local sx = cardCX + math.cos(angle) * orbitR
            local sy = cardCY + math.sin(angle) * orbitR
            local anchor = cardAnchors[slotIdx]

            local slot = sd and sd.slots and sd.slots[slotIdx] or nil
            local stc = SEAL_SLOT_THEME_COLORS[slotIdx] or { 120, 80, 180 }

            -- 连线 (从兵符孔位→卡牌锚点)
            local lineActive = slot ~= nil
            local linePulse = 0.4 + 0.3 * math.sin(t * 1.8 + slotIdx * 1.05)
            local lineA = lineActive and math.floor(120 * linePulse) or math.floor(30 * linePulse)

            nvgBeginPath(vg)
            nvgMoveTo(vg, sx, sy)
            nvgLineTo(vg, anchor.x, anchor.y)
            nvgStrokeColor(vg, nvgRGBA(stc[1], stc[2], stc[3], lineA))
            nvgStrokeWidth(vg, lineActive and 1.5 or 0.8)
            nvgStroke(vg)

            -- 锚点端发光点
            if lineActive then
                local anchorGlow = 0.5 + 0.5 * math.sin(t * 2.5 + slotIdx * 0.9)
                nvgBeginPath(vg)
                nvgCircle(vg, anchor.x, anchor.y, 3)
                nvgFillColor(vg, nvgRGBA(stc[1], stc[2], stc[3], math.floor(160 * anchorGlow)))
                nvgFill(vg)
            end

            -- 流动能量粒子 (沿连线从孔位流向卡牌)
            if lineActive then
                for pi = 0, 1 do
                    local pTime = (t * 0.5 + slotIdx * 0.4 + pi * 0.5) % 1.0
                    local px = sx + (anchor.x - sx) * pTime
                    local py = sy + (anchor.y - sy) * pTime
                    local pAlpha = math.sin(pTime * math.pi)
                    nvgBeginPath(vg)
                    nvgCircle(vg, px, py, 2.0)
                    nvgFillColor(vg, nvgRGBA(stc[1], stc[2], stc[3], math.floor(140 * pAlpha)))
                    nvgFill(vg)
                end
            end
        end

        -- ========== 3. 中心卡牌 (复用武灵图录渲染) ==========
        if card then
            DrawInventoryCard(cardX, cardY, cardW, cardH, card, constellation, false)
        end

        -- 兵符孔数信息 (卡牌下方)
        nvgFontSize(vg, 16)
        nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        DrawWhiteInkText(cardCX, cardY + cardH + 16, "六欲 " .. slotCount .. "/" .. SEAL_MAX_SLOTS)

        -- 切换提示
        if #maxHeroes > 1 then
            local hintPulse = 150 + 60 * math.sin(t * 2.0)
            nvgFontSize(vg, 13)
            nvgFillColor(vg, nvgRGBA(200, 170, 240, math.floor(hintPulse)))
            nvgText(vg, cardCX, cardY + cardH + 34, "- 点击卡牌切换 -", nil)
        end

        -- 中心卡牌点击区域
        sealMgrBtnRects.centerCard = { x = cardX - 8, y = cardY - 8, w = cardW + 16, h = cardH + 46 }

        -- ========== 4. 六个兵符孔 (环绕布局) ==========
        local slotR = 34
        for slotIdx = 1, SEAL_MAX_SLOTS do
            local angle = ((slotIdx - 1) / SEAL_MAX_SLOTS) * math.pi * 2 - math.pi / 2
            -- 浮动偏移
            local floatAmt = math.sin(t * 1.2 + slotIdx * 1.05) * 3
            local sx = cardCX + math.cos(angle) * (orbitR + floatAmt)
            local sy = cardCY + math.sin(angle) * (orbitR + floatAmt)

            local slot = sd and sd.slots and sd.slots[slotIdx] or nil
            local isSelected = (sealMgrState.selectedSlot == slotIdx)
            local stc = SEAL_SLOT_THEME_COLORS[slotIdx] or { 200, 200, 200 }

            if slot then
                -- ===== 已开孔 =====
                local sc = SEAL_QUALITY_COLORS[slot.sealQ] or { 180, 180, 180 }

                -- 底部光晕 (品质色)
                local glowPulse = 0.4 + 0.3 * math.sin(t * 1.5 + slotIdx * 0.7)
                local slotGlow = nvgRadialGradient(vg, sx, sy, 4, slotR + 16,
                    nvgRGBA(sc[1], sc[2], sc[3], math.floor(60 * glowPulse)),
                    nvgRGBA(sc[1], sc[2], sc[3], 0))
                nvgBeginPath(vg); nvgCircle(vg, sx, sy, slotR + 16)
                nvgFillPaint(vg, slotGlow); nvgFill(vg)

                -- 选中时外层强光脉冲
                if isSelected then
                    local selPulse2 = 0.5 + 0.5 * math.sin(t * 4.0)
                    local selGlow2 = nvgRadialGradient(vg, sx, sy, slotR, slotR + 20,
                        nvgRGBA(255, 255, 255, math.floor(70 * selPulse2)),
                        nvgRGBA(255, 255, 255, 0))
                    nvgBeginPath(vg); nvgCircle(vg, sx, sy, slotR + 20)
                    nvgFillPaint(vg, selGlow2); nvgFill(vg)
                end

                -- 六角形主体
                DrawSealHexIcon(sx, sy, slotR, sc, slot.sealQ)

                -- 选中高亮描边 (六角形脉冲)
                if isSelected then
                    nvgBeginPath(vg)
                    for vi = 0, 5 do
                        local a = (vi / 6) * math.pi * 2 - math.pi / 2
                        local px = sx + math.cos(a) * (slotR + 4)
                        local py = sy + math.sin(a) * (slotR + 4)
                        if vi == 0 then nvgMoveTo(vg, px, py) else nvgLineTo(vg, px, py) end
                    end
                    nvgClosePath(vg)
                    local sPulse = 0.5 + 0.5 * math.sin(t * 3.0)
                    nvgStrokeColor(vg, nvgRGBA(255, 255, 255, math.floor(200 * sPulse)))
                    nvgStrokeWidth(vg, 2.5); nvgStroke(vg)
                end

                -- 等级 (六角形下半区)
                nvgFontSize(vg, 13)
                nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
                DrawWhiteInkText(sx, sy + slotR * 0.25, "Lv." .. (slot.level or 1))

                -- 孔名 (下方白字描边)
                nvgFontSize(vg, 14)
                nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
                DrawWhiteInkText(sx, sy + slotR + 14, SEAL_SLOT_NAMES[slotIdx])

                -- 效果主题 (更下方，带主题色描边)
                local eff = SEAL_SLOT_EFFECTS[slotIdx]
                if eff then
                    nvgFontSize(vg, 11)
                    -- 先画描边
                    nvgFillColor(vg, nvgRGBA(0, 0, 0, 140))
                    nvgText(vg, sx - 1, sy + slotR + 29, eff.theme, nil)
                    nvgText(vg, sx + 1, sy + slotR + 29, eff.theme, nil)
                    nvgText(vg, sx, sy + slotR + 28, eff.theme, nil)
                    nvgText(vg, sx, sy + slotR + 30, eff.theme, nil)
                    -- 主题色主体
                    nvgFillColor(vg, nvgRGBA(stc[1], stc[2], stc[3], 220))
                    nvgText(vg, sx, sy + slotR + 29, eff.theme, nil)
                end
            else
                -- ===== 未开孔 =====
                -- 暗淡光晕
                local dimGlow = nvgRadialGradient(vg, sx, sy, 4, slotR + 10,
                    nvgRGBA(60, 30, 90, 25), nvgRGBA(60, 30, 90, 0))
                nvgBeginPath(vg); nvgCircle(vg, sx, sy, slotR + 10)
                nvgFillPaint(vg, dimGlow); nvgFill(vg)

                -- 暗淡六角形
                nvgBeginPath(vg)
                for vi = 0, 5 do
                    local a = (vi / 6) * math.pi * 2 - math.pi / 2
                    local px = sx + math.cos(a) * slotR
                    local py = sy + math.sin(a) * slotR
                    if vi == 0 then nvgMoveTo(vg, px, py) else nvgLineTo(vg, px, py) end
                end
                nvgClosePath(vg)
                nvgFillColor(vg, nvgRGBA(25, 15, 40, 180)); nvgFill(vg)
                -- 虚线边框效果 (分段描边)
                nvgStrokeColor(vg, nvgRGBA(80, 50, 120, 80))
                nvgStrokeWidth(vg, 1); nvgStroke(vg)

                -- 锁定图标 (呼吸)
                local lockAlpha = 80 + 40 * math.sin(t * 0.8 + slotIdx * 0.6)
                nvgFontSize(vg, 24)
                nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
                nvgFillColor(vg, nvgRGBA(120, 80, 160, math.floor(lockAlpha)))
                nvgText(vg, sx, sy, "锁", nil)

                -- 孔名 (白字描边，暗淡)
                nvgFontSize(vg, 14)
                nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
                nvgFillColor(vg, nvgRGBA(0, 0, 0, 100))
                nvgText(vg, sx - 1, sy + slotR + 14, SEAL_SLOT_NAMES[slotIdx], nil)
                nvgText(vg, sx + 1, sy + slotR + 14, SEAL_SLOT_NAMES[slotIdx], nil)
                nvgFillColor(vg, nvgRGBA(160, 130, 200, 100))
                nvgText(vg, sx, sy + slotR + 14, SEAL_SLOT_NAMES[slotIdx], nil)

                -- 效果主题 (暗淡)
                local eff2 = SEAL_SLOT_EFFECTS[slotIdx]
                if eff2 then
                    nvgFontSize(vg, 11)
                    nvgFillColor(vg, nvgRGBA(100, 70, 150, 60))
                    nvgText(vg, sx, sy + slotR + 29, eff2.theme, nil)
                end
            end

            sealMgrSlotRects[slotIdx] = { x = sx - slotR - 6, y = sy - slotR - 6, w = (slotR + 6) * 2, h = (slotR + 6) * 2 + 36 }
        end

        -- ========== 5. 底部信息面板 ==========
        local bottomY = cardCY + orbitR + 68

        -- 兵符总加成
        local bonus = GetSealTotalBonus(cardIdx)
        local bonusLines = {}
        local bonusFieldDefs = {
            { key = "atkPct",           name = "攻击",     fmt = "+%.1f%%",  slot = 2 },
            { key = "defPct",           name = "防御",     fmt = "+%.1f%%",  slot = 5 },
            { key = "hpPct",            name = "生命",     fmt = "+%.1f%%",  slot = 3 },
            { key = "extraTroops",      name = "额外兵力", fmt = "+%.1f",    slot = 1 },
            { key = "critRate",         name = "暴击率",   fmt = "+%.1f%%",  slot = 2 },
            { key = "dmgReduction",     name = "减伤",     fmt = "+%.1f%%",  slot = 3 },
            { key = "speedPct",         name = "移速",     fmt = "+%.1f%%",  slot = 4 },
            { key = "atkSpeedPct",      name = "攻速",     fmt = "+%.1f%%",  slot = 4 },
            { key = "counterRate",      name = "反击率",   fmt = "+%.1f%%",  slot = 5 },
            { key = "breakDmgPct",      name = "突破伤害", fmt = "+%.1f%%",  slot = 6 },
            { key = "deathExplosionPct",name = "死亡爆炸", fmt = "+%.1f%%",  slot = 6 },
        }
        for _, fd in ipairs(bonusFieldDefs) do
            local v = bonus[fd.key] or 0
            if v > 0 then
                local tc = SEAL_SLOT_THEME_COLORS[fd.slot] or { 200, 160, 255 }
                table.insert(bonusLines, { text = fd.name .. string.format(fd.fmt, v), color = tc })
            end
        end

        if #bonusLines > 0 then
            local lineH2 = 18
            local bPanelW = W - 40
            local bPanelH = 34 + math.ceil(#bonusLines / 2) * lineH2
            local bPanelX = cx - bPanelW / 2

            -- 面板背景
            nvgBeginPath(vg); nvgRoundedRect(vg, bPanelX, bottomY, bPanelW, bPanelH, 8)
            nvgFillColor(vg, nvgRGBA(20, 10, 35, 200)); nvgFill(vg)
            nvgStrokeColor(vg, nvgRGBA(140, 80, 200, 60)); nvgStrokeWidth(vg, 1); nvgStroke(vg)

            -- 标题
            nvgFontSize(vg, 18)
            nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
            DrawWhiteInkText(cx, bottomY + 16, "兵符总加成")

            -- 两列加成
            nvgFontSize(vg, 14)
            local colW = bPanelW / 2
            for li, bl in ipairs(bonusLines) do
                local col = (li - 1) % 2
                local row = math.floor((li - 1) / 2)
                local lx = bPanelX + colW * col + colW / 2
                local ly = bottomY + 32 + row * lineH2
                nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
                -- 描边
                nvgFillColor(vg, nvgRGBA(0, 0, 0, 120))
                nvgText(vg, lx - 1, ly, bl.text, nil)
                nvgText(vg, lx + 1, ly, bl.text, nil)
                -- 主色
                nvgFillColor(vg, nvgRGBA(bl.color[1], bl.color[2], bl.color[3], 230))
                nvgText(vg, lx, ly, bl.text, nil)
            end
            bottomY = bottomY + bPanelH + 8
        end

        -- 咒墨道具概览
        nvgFontSize(vg, 19)
        nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        DrawWhiteInkText(cx, bottomY + 6, "咒墨道具")

        local itemRowY = bottomY + 28
        local itemW = (W - 40) / 4
        local itemCardH = 72
        for idx, item in ipairs(SEAL_EXP_ITEMS) do
            local ix = 20 + (idx - 1) * itemW
            local cnt = sealExpItems[idx] or 0
            local cw = itemW - 6
            local ccx = ix + cw / 2

            -- 道具卡片背景
            nvgBeginPath(vg); nvgRoundedRect(vg, ix, itemRowY, cw, itemCardH, 5)
            nvgFillColor(vg, nvgRGBA(20, 12, 35, 200)); nvgFill(vg)
            nvgStrokeColor(vg, nvgRGBA(110, 70, 170, 80)); nvgStrokeWidth(vg, 0.8); nvgStroke(vg)

            -- 道具图标
            local imgSize = 30
            local imgHandle = sealExpItemImages[idx]
            if imgHandle and imgHandle > 0 then
                local imgPat = nvgImagePattern(vg, ccx - imgSize / 2, itemRowY + 4, imgSize, imgSize, 0, imgHandle, 1.0)
                nvgBeginPath(vg)
                nvgRoundedRect(vg, ccx - imgSize / 2, itemRowY + 4, imgSize, imgSize, 4)
                nvgFillPaint(vg, imgPat); nvgFill(vg)
            end

            -- 道具名 (白字描边)
            nvgFontSize(vg, 12)
            nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
            DrawWhiteInkText(ccx, itemRowY + imgSize + 10, item.name)

            -- 数量
            nvgFontSize(vg, 14)
            nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
            if cnt > 0 then
                DrawWhiteInkText(ccx, itemRowY + imgSize + 26, "x" .. cnt)
            else
                nvgFillColor(vg, nvgRGBA(80, 60, 110, 120))
                nvgText(vg, ccx, itemRowY + imgSize + 26, "x0", nil)
            end
        end
    else
        -- ============ 无满命英雄提示 ============
        -- 装饰环
        local emptyPulse = 0.3 + 0.2 * math.sin(t * 0.6)
        nvgBeginPath(vg)
        nvgCircle(vg, cardCX, cardCY, orbitR)
        nvgStrokeColor(vg, nvgRGBA(80, 40, 140, math.floor(50 * emptyPulse)))
        nvgStrokeWidth(vg, 1)
        nvgStroke(vg)

        -- 占位空卡
        nvgBeginPath(vg); nvgRoundedRect(vg, cardX, cardY, cardW, cardH, 6)
        nvgFillColor(vg, nvgRGBA(30, 20, 45, 180)); nvgFill(vg)
        nvgStrokeColor(vg, nvgRGBA(80, 50, 120, 100)); nvgStrokeWidth(vg, 1); nvgStroke(vg)

        nvgFontSize(vg, 40)
        nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        nvgFillColor(vg, nvgRGBA(80, 50, 120, 80))
        nvgText(vg, cardCX, cardCY - 10, "?", nil)

        nvgFontSize(vg, 18)
        DrawWhiteInkText(cardCX, cardY + cardH + 20, "暂无满命武灵")

        nvgFontSize(vg, 14)
        nvgFillColor(vg, nvgRGBA(140, 110, 180, 120))
        nvgText(vg, cardCX, cardY + cardH + 42, "满命后解锁兵符系统", nil)
    end

    -- ============ 英雄选择弹窗 ============
    if sealMgrState.showHeroPicker and #maxHeroes > 1 then
        -- 半透明遮罩
        nvgBeginPath(vg); nvgRect(vg, 0, 0, W, H)
        nvgFillColor(vg, nvgRGBA(5, 3, 15, 180)); nvgFill(vg)

        -- 布局计算
        local ppW = W * 0.92
        local colCount = 3
        local padX = 18
        local cellGap = 10
        local cellW = (ppW - padX * 2 - (colCount - 1) * cellGap) / colCount
        local cellH = cellW * 1.35
        local rows = math.ceil(#maxHeroes / colCount)
        local headerH = 56
        local gridContentH = rows * (cellH + cellGap) - cellGap
        local maxGridViewH = H * 0.62  -- 弹窗网格区最大可视高度
        local gridViewH = math.min(gridContentH, maxGridViewH)
        local needsScroll = (gridContentH > gridViewH)
        local footerH = needsScroll and 28 or 12
        local ppH = headerH + gridViewH + footerH
        local ppX = cx - ppW / 2
        local ppY = H / 2 - ppH / 2

        -- 记录滚动区域尺寸 (供拖拽逻辑使用)
        heroPickerScroll.contentH = gridContentH
        heroPickerScroll.viewH = gridViewH

        -- ====== 面板背景 (三国古风暗紫渐变) ======
        nvgSave(vg)
        local ppGrad = nvgLinearGradient(vg, ppX, ppY, ppX, ppY + ppH,
            nvgRGBA(42, 20, 65, 250), nvgRGBA(25, 12, 42, 252))
        nvgBeginPath(vg); nvgRoundedRect(vg, ppX, ppY, ppW, ppH, 14)
        nvgFillPaint(vg, ppGrad); nvgFill(vg)
        -- 外边框 (双层: 金色内框 + 暗紫外框)
        nvgBeginPath(vg); nvgRoundedRect(vg, ppX + 1, ppY + 1, ppW - 2, ppH - 2, 13)
        nvgStrokeColor(vg, nvgRGBA(200, 160, 80, 80)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
        nvgBeginPath(vg); nvgRoundedRect(vg, ppX, ppY, ppW, ppH, 14)
        nvgStrokeColor(vg, nvgRGBA(140, 70, 200, 160)); nvgStrokeWidth(vg, 1.5); nvgStroke(vg)

        -- ====== 标题栏 ======
        -- 标题背景装饰条
        local titleBarGrad = nvgLinearGradient(vg, ppX, ppY, ppX + ppW, ppY,
            nvgRGBA(120, 60, 180, 0), nvgRGBA(120, 60, 180, 60))
        nvgBeginPath(vg); nvgRoundedRect(vg, ppX + 4, ppY + 4, ppW - 8, headerH - 8, 10)
        nvgFillPaint(vg, titleBarGrad); nvgFill(vg)
        -- 底部分隔线
        local sepGrad = nvgLinearGradient(vg, ppX + 20, ppY + headerH, ppX + ppW - 20, ppY + headerH,
            nvgRGBA(200, 160, 80, 0), nvgRGBA(200, 160, 80, 120))
        nvgBeginPath(vg)
        nvgMoveTo(vg, ppX + 20, ppY + headerH - 1)
        nvgLineTo(vg, ppX + ppW - 20, ppY + headerH - 1)
        nvgStrokePaint(vg, sepGrad); nvgStrokeWidth(vg, 1); nvgStroke(vg)

        nvgFontFaceId(vg, GetMainFont())
        nvgFontSize(vg, 22)
        nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        DrawWhiteInkText(cx, ppY + headerH / 2, "— 选择武灵 —")

        -- 武灵数量提示
        nvgFontSize(vg, 12)
        nvgFillColor(vg, nvgRGBA(180, 150, 220, 160))
        nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)
        nvgText(vg, ppX + padX, ppY + headerH / 2 + 1, #maxHeroes .. "位满命", nil)

        -- ====== 关闭按钮 (圆形) ======
        local closeBtnR = 16
        local closeCX = ppX + ppW - 24
        local closeCY = ppY + headerH / 2
        nvgBeginPath(vg); nvgCircle(vg, closeCX, closeCY, closeBtnR)
        nvgFillColor(vg, nvgRGBA(60, 30, 85, 220)); nvgFill(vg)
        nvgStrokeColor(vg, nvgRGBA(180, 120, 240, 120)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
        -- X 图标
        local xOff = 7
        nvgBeginPath(vg)
        nvgMoveTo(vg, closeCX - xOff, closeCY - xOff)
        nvgLineTo(vg, closeCX + xOff, closeCY + xOff)
        nvgMoveTo(vg, closeCX + xOff, closeCY - xOff)
        nvgLineTo(vg, closeCX - xOff, closeCY + xOff)
        nvgStrokeColor(vg, nvgRGBA(220, 200, 255, 200)); nvgStrokeWidth(vg, 2); nvgStroke(vg)
        sealMgrBtnRects.closeHeroPicker = { x = closeCX - closeBtnR, y = closeCY - closeBtnR, w = closeBtnR * 2, h = closeBtnR * 2 }

        -- ====== 英雄网格 (带裁剪滚动) ======
        local gridAreaX = ppX + padX
        local gridAreaY = ppY + headerH
        local gridAreaW = ppW - padX * 2
        local scrollY = heroPickerScroll.y or 0

        nvgSave(vg)
        nvgScissor(vg, gridAreaX - 2, gridAreaY, gridAreaW + 4, gridViewH)

        for i, heroInfo in ipairs(maxHeroes) do
            local col = ((i - 1) % colCount)
            local row = math.floor((i - 1) / colCount)
            local hx = gridAreaX + col * (cellW + cellGap)
            local hy = gridAreaY + row * (cellH + cellGap) - scrollY

            -- 跳过不可见的卡牌 (性能优化)
            if hy + cellH >= gridAreaY - 10 and hy <= gridAreaY + gridViewH + 10 then
                local hCard = HERO_CARDS[heroInfo.cardIdx]
                local hHero = playerHeroes[heroInfo.cardIdx]
                local hConst = hHero and hHero.constellation or 0
                local isSelected = (sealMgrState.selectedHero == heroInfo.cardIdx)

                -- 卡牌底色 (选中时金色光晕)
                if isSelected then
                    nvgBeginPath(vg); nvgRoundedRect(vg, hx - 4, hy - 4, cellW + 8, cellH + 8, 8)
                    nvgFillColor(vg, nvgRGBA(200, 160, 60, 40)); nvgFill(vg)
                end

                if hCard then
                    DrawInventoryCard(hx, hy, cellW, cellH, hCard, hConst, false)
                end

                -- 选中高亮边框 (金色双层)
                if isSelected then
                    nvgBeginPath(vg); nvgRoundedRect(vg, hx - 3, hy - 3, cellW + 6, cellH + 6, 7)
                    nvgStrokeColor(vg, nvgRGBA(255, 210, 80, 240))
                    nvgStrokeWidth(vg, 2.5); nvgStroke(vg)
                    nvgBeginPath(vg); nvgRoundedRect(vg, hx - 1, hy - 1, cellW + 2, cellH + 2, 5)
                    nvgStrokeColor(vg, nvgRGBA(255, 240, 160, 100))
                    nvgStrokeWidth(vg, 1); nvgStroke(vg)
                end

                -- 已开孔数标记 (右下角胶囊)
                local sc2 = GetSealSlotCount(heroInfo.cardIdx)
                local badgeW2, badgeH2 = 36, 16
                local badgeX = hx + cellW - badgeW2 - 3
                local badgeY = hy + cellH - badgeH2 - 3
                local badgeBg = nvgLinearGradient(vg, badgeX, badgeY, badgeX, badgeY + badgeH2,
                    nvgRGBA(30, 15, 50, 230), nvgRGBA(20, 8, 35, 240))
                nvgBeginPath(vg); nvgRoundedRect(vg, badgeX, badgeY, badgeW2, badgeH2, badgeH2 / 2)
                nvgFillPaint(vg, badgeBg); nvgFill(vg)
                nvgBeginPath(vg); nvgRoundedRect(vg, badgeX, badgeY, badgeW2, badgeH2, badgeH2 / 2)
                nvgStrokeColor(vg, nvgRGBA(160, 120, 220, 100)); nvgStrokeWidth(vg, 0.5); nvgStroke(vg)
                nvgFontSize(vg, 10)
                nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
                local slotColor = sc2 >= 6 and nvgRGBA(255, 220, 80, 255) or nvgRGBA(200, 180, 240, 220)
                nvgFillColor(vg, slotColor)
                nvgText(vg, badgeX + badgeW2 / 2, badgeY + badgeH2 / 2, sc2 .. "/" .. SEAL_MAX_SLOTS .. "孔", nil)

                -- 记录点击区域 (使用滚动后的实际位置)
                sealMgrHeroRects[heroInfo.cardIdx] = { x = hx, y = hy, w = cellW, h = cellH }
            end
        end

        nvgRestore(vg)  -- 恢复裁剪

        -- ====== 滚动条（粗，高可见度）======
        if needsScroll and gridContentH > 0 then
            local sbBarW = 8
            local scrollBarX = ppX + ppW - sbBarW - 4
            local scrollBarH = math.max(30, gridViewH * (gridViewH / gridContentH))
            local scrollBarMaxY = gridViewH - scrollBarH
            local scrollRatio = scrollY / math.max(1, gridContentH - gridViewH)
            local scrollBarY = gridAreaY + scrollRatio * scrollBarMaxY
            -- 轨道
            nvgBeginPath(vg); nvgRoundedRect(vg, scrollBarX, gridAreaY, sbBarW, gridViewH, sbBarW / 2)
            nvgFillColor(vg, nvgRGBA(40, 20, 60, 100)); nvgFill(vg)
            -- 滑块
            nvgBeginPath(vg); nvgRoundedRect(vg, scrollBarX, scrollBarY, sbBarW, scrollBarH, sbBarW / 2)
            nvgFillColor(vg, nvgRGBA(200, 160, 255, heroPickerScroll.isDragging and 220 or 150)); nvgFill(vg)
        end

        -- ====== 底部提示 (可滚动时显示) ======
        if needsScroll then
            nvgFontSize(vg, 11)
            nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
            nvgFillColor(vg, nvgRGBA(160, 140, 200, 100))
            nvgText(vg, cx, ppY + ppH - footerH / 2, "上下滑动查看更多", nil)
        end

        nvgRestore(vg)
    end

    -- ============ 升级面板 (弹窗) ============
    if sealMgrState.showLevelUp and sealMgrState.selectedHero and sealMgrState.selectedSlot then
        local cardIdx = sealMgrState.selectedHero
        local slotIdx = sealMgrState.selectedSlot
        local sd = sealData[cardIdx]
        local slot = sd and sd.slots and sd.slots[slotIdx]

        if slot then
            -- 遮罩
            nvgBeginPath(vg); nvgRect(vg, 0, 0, W, H)
            nvgFillColor(vg, nvgRGBA(5, 3, 15, 160)); nvgFill(vg)

            -- 弹窗面板
            local pW = W * 0.88
            local pH = 560
            local pX = cx - pW / 2
            local pY = H / 2 - pH / 2

            local pGrad = nvgLinearGradient(vg, pX, pY, pX, pY + pH,
                nvgRGBA(40, 18, 55, 248), nvgRGBA(25, 12, 38, 252))
            nvgBeginPath(vg); nvgRoundedRect(vg, pX, pY, pW, pH, 12)
            nvgFillPaint(vg, pGrad); nvgFill(vg)
            nvgBeginPath(vg); nvgRoundedRect(vg, pX, pY, pW, pH, 12)
            nvgStrokeColor(vg, nvgRGBA(160, 80, 240, 140)); nvgStrokeWidth(vg, 1.5); nvgStroke(vg)

            nvgFontFaceId(vg, GetMainFont())

            -- 标题 (白字描边)
            local sc = SEAL_QUALITY_COLORS[slot.sealQ] or { 180, 180, 180 }
            nvgFontSize(vg, 28)
            nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
            DrawWhiteInkText(cx, pY + 28, SEAL_SLOT_NAMES[slotIdx] .. " · " .. (SEAL_QUALITY_NAMES[slot.sealQ] or "?"))

            -- 关闭按钮
            local closeBtnSize = 36
            local closeX = pX + pW - closeBtnSize - 8
            local closeY = pY + 8
            nvgBeginPath(vg); nvgRoundedRect(vg, closeX, closeY, closeBtnSize, closeBtnSize, 6)
            nvgFillColor(vg, nvgRGBA(50, 25, 70, 220)); nvgFill(vg)
            nvgStrokeColor(vg, nvgRGBA(160, 100, 220, 120)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
            nvgFontSize(vg, 24)
            nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
            DrawWhiteInkText(closeX + closeBtnSize / 2, closeY + closeBtnSize / 2, "X")
            sealMgrBtnRects.closeLevelUp = { x = closeX, y = closeY, w = closeBtnSize, h = closeBtnSize }

            -- 六角形图标 + 等级
            local iconY = pY + 90
            DrawSealHexIcon(cx, iconY, 38, sc, slot.sealQ)
            nvgFontSize(vg, 22)
            nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
            DrawWhiteInkText(cx, iconY + 2, "Lv." .. slot.level)

            -- 属性加成
            local slotBonus = GetSealSlotBonus(slotIdx, slot.sealQ, slot.level)
            local attrY = iconY + 46
            local stc = SEAL_SLOT_THEME_COLORS[slotIdx] or { 200, 160, 255 }
            if slotBonus then
                -- 主题名 (主题色描边)
                nvgFontSize(vg, 15)
                nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
                nvgFillColor(vg, nvgRGBA(0, 0, 0, 120))
                nvgText(vg, cx - 1, attrY, "【" .. slotBonus.theme .. "】", nil)
                nvgText(vg, cx + 1, attrY, "【" .. slotBonus.theme .. "】", nil)
                nvgFillColor(vg, nvgRGBA(stc[1], stc[2], stc[3], 230))
                nvgText(vg, cx, attrY, "【" .. slotBonus.theme .. "】", nil)
                attrY = attrY + 22

                -- 主属性 (白字描边)
                nvgFontSize(vg, 17)
                local mainText = slotBonus.mainName .. string.format("+%.1f%%", slotBonus.mainVal)
                if slotBonus.mainKey == "extraTroops" then
                    mainText = slotBonus.mainName .. string.format("+%.1f", slotBonus.mainVal)
                end
                DrawWhiteInkText(cx, attrY, mainText)

                -- 副属性
                if slotBonus.subKey and slotBonus.subVal > 0 then
                    attrY = attrY + 20
                    nvgFontSize(vg, 15)
                    nvgFillColor(vg, nvgRGBA(0, 0, 0, 120))
                    nvgText(vg, cx - 1, attrY, slotBonus.subName .. string.format("+%.1f%%", slotBonus.subVal), nil)
                    nvgText(vg, cx + 1, attrY, slotBonus.subName .. string.format("+%.1f%%", slotBonus.subVal), nil)
                    nvgFillColor(vg, nvgRGBA(stc[1], stc[2], stc[3], 230))
                    nvgText(vg, cx, attrY, slotBonus.subName .. string.format("+%.1f%%", slotBonus.subVal), nil)
                end
            end

            -- 经验进度条
            local barY = attrY + 28
            local barW2 = pW - 60
            local barH2 = 16
            local barX = cx - barW2 / 2

            if slot.level < SEAL_MAX_LEVEL then
                local expNeeded = SEAL_EXP_TABLE[slot.level] or 999
                local expCur = slot.exp or 0
                local ratio = math.min(1.0, expCur / expNeeded)

                nvgBeginPath(vg); nvgRoundedRect(vg, barX, barY, barW2, barH2, 4)
                nvgFillColor(vg, nvgRGBA(15, 8, 28, 220)); nvgFill(vg)
                if ratio > 0 then
                    local barGrad = nvgLinearGradient(vg, barX, barY, barX + barW2 * ratio, barY,
                        nvgRGBA(sc[1], sc[2], sc[3], 200), nvgRGBA(sc[1], sc[2], sc[3], 140))
                    nvgBeginPath(vg); nvgRoundedRect(vg, barX, barY, barW2 * ratio, barH2, 4)
                    nvgFillPaint(vg, barGrad); nvgFill(vg)
                end
                nvgBeginPath(vg); nvgRoundedRect(vg, barX, barY, barW2, barH2, 4)
                nvgStrokeColor(vg, nvgRGBA(sc[1], sc[2], sc[3], 100))
                nvgStrokeWidth(vg, 0.8); nvgStroke(vg)

                nvgFontSize(vg, 13)
                nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
                DrawWhiteInkText(cx, barY + barH2 / 2, expCur .. " / " .. expNeeded)
            else
                nvgFontSize(vg, 16)
                nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
                nvgFillColor(vg, nvgRGBA(0, 0, 0, 120))
                nvgText(vg, cx - 1, barY + barH2 / 2, "已达最高等级!", nil)
                nvgText(vg, cx + 1, barY + barH2 / 2, "已达最高等级!", nil)
                nvgFillColor(vg, nvgRGBA(255, 220, 80, 240))
                nvgText(vg, cx, barY + barH2 / 2, "已达最高等级!", nil)
            end

            -- 使用咒墨道具
            local useItemY = barY + barH2 + 24
            nvgFontSize(vg, 20)
            nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
            DrawWhiteInkText(cx, useItemY, "使用咒墨提升等级")

            local useBtnY = useItemY + 26
            local useBtnW = (pW - 50) / 4
            local useBtnH = 90
            local imgBtnSize = 28

            for idx, item in ipairs(SEAL_EXP_ITEMS) do
                local bx = pX + 20 + (idx - 1) * (useBtnW + 4)
                local by = useBtnY
                local cnt = sealExpItems[idx] or 0
                local canUse = cnt > 0 and slot.level < SEAL_MAX_LEVEL
                local bcx = bx + useBtnW / 2

                nvgBeginPath(vg); nvgRoundedRect(vg, bx, by, useBtnW, useBtnH, 6)
                if canUse then
                    nvgFillColor(vg, nvgRGBA(35, 18, 55, 230)); nvgFill(vg)
                    nvgBeginPath(vg); nvgRoundedRect(vg, bx, by, useBtnW, useBtnH, 6)
                    nvgStrokeColor(vg, nvgRGBA(sc[1], sc[2], sc[3], 160))
                    nvgStrokeWidth(vg, 1.2); nvgStroke(vg)
                else
                    nvgFillColor(vg, nvgRGBA(20, 12, 30, 180)); nvgFill(vg)
                    nvgBeginPath(vg); nvgRoundedRect(vg, bx, by, useBtnW, useBtnH, 6)
                    nvgStrokeColor(vg, nvgRGBA(50, 35, 70, 80))
                    nvgStrokeWidth(vg, 0.8); nvgStroke(vg)
                end

                -- 道具图标
                local imgHandle = sealExpItemImages[idx]
                if imgHandle and imgHandle > 0 then
                    local alpha = canUse and 1.0 or 0.4
                    local imgPat = nvgImagePattern(vg, bcx - imgBtnSize / 2, by + 6, imgBtnSize, imgBtnSize, 0, imgHandle, alpha)
                    nvgBeginPath(vg)
                    nvgRoundedRect(vg, bcx - imgBtnSize / 2, by + 6, imgBtnSize, imgBtnSize, 4)
                    nvgFillPaint(vg, imgPat); nvgFill(vg)
                end

                -- 道具名 (白字描边)
                nvgFontSize(vg, 12)
                nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
                if canUse then
                    DrawWhiteInkText(bcx, by + imgBtnSize + 14, item.name)
                else
                    nvgFillColor(vg, nvgRGBA(80, 60, 100, 120))
                    nvgText(vg, bcx, by + imgBtnSize + 14, item.name, nil)
                end

                -- 经验值
                nvgFontSize(vg, 11)
                if canUse then
                    DrawWhiteInkText(bcx, by + imgBtnSize + 30, "+" .. item.exp .. "EXP")
                else
                    nvgFillColor(vg, nvgRGBA(80, 60, 100, 80))
                    nvgText(vg, bcx, by + imgBtnSize + 30, "+" .. item.exp .. "EXP", nil)
                end

                -- 数量
                nvgFontSize(vg, 14)
                nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
                if cnt > 0 then
                    DrawWhiteInkText(bcx, by + imgBtnSize + 48, "x" .. cnt)
                else
                    nvgFillColor(vg, nvgRGBA(80, 60, 100, 100))
                    nvgText(vg, bcx, by + imgBtnSize + 48, "x0", nil)
                end

                -- "使用" 按钮文字
                if canUse then
                    nvgFontSize(vg, 14)
                    nvgFillColor(vg, nvgRGBA(0, 0, 0, 120))
                    nvgText(vg, bcx - 1, by + useBtnH - 8, "使用", nil)
                    nvgText(vg, bcx + 1, by + useBtnH - 8, "使用", nil)
                    nvgFillColor(vg, nvgRGBA(sc[1], sc[2], sc[3], 240))
                    nvgText(vg, bcx, by + useBtnH - 8, "使用", nil)
                end

                sealMgrExpItemRects[idx] = { x = bx, y = by, w = useBtnW, h = useBtnH }
            end

            -- ============ 一键升级区域 ============
            local batchY = useBtnY + useBtnH + 12
            if slot.level < SEAL_MAX_LEVEL then
                -- 初始化目标等级
                if not sealBatchTarget or sealBatchTarget <= slot.level then
                    sealBatchTarget = math.min(slot.level + 1, SEAL_MAX_LEVEL)
                end
                if sealBatchTarget > SEAL_MAX_LEVEL then sealBatchTarget = SEAL_MAX_LEVEL end

                local expNeeded = CalcSealExpNeeded(slot.level, slot.exp, sealBatchTarget)
                local plan = CalcSealAutoEnhancePlan(expNeeded)
                local canBatch = plan ~= nil and sealBatchTarget > slot.level

                -- 背景条
                nvgBeginPath(vg); nvgRoundedRect(vg, pX + 16, batchY, pW - 32, 52, 8)
                nvgFillColor(vg, nvgRGBA(20, 12, 35, 200)); nvgFill(vg)
                nvgStrokeColor(vg, nvgRGBA(140, 80, 220, 80)); nvgStrokeWidth(vg, 1); nvgStroke(vg)

                -- "升至" 文字
                nvgFontSize(vg, 16); nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)
                DrawWhiteInkText(pX + 26, batchY + 18, "升至")

                -- - 按钮
                local minusBtnX = pX + 66
                local minusBtnW, minusBtnH = 30, 28
                nvgBeginPath(vg); nvgRoundedRect(vg, minusBtnX, batchY + 4, minusBtnW, minusBtnH, 5)
                nvgFillColor(vg, sealBatchTarget > slot.level + 1 and nvgRGBA(60, 30, 90, 220) or nvgRGBA(30, 18, 45, 150))
                nvgFill(vg)
                nvgStrokeColor(vg, nvgRGBA(140, 80, 220, 120)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
                nvgFontSize(vg, 20); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
                DrawWhiteInkText(minusBtnX + minusBtnW / 2, batchY + 4 + minusBtnH / 2, "-")
                sealMgrBtnRects.batchMinus = { x = minusBtnX, y = batchY + 4, w = minusBtnW, h = minusBtnH }

                -- 目标等级
                nvgFontSize(vg, 22); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
                nvgFillColor(vg, nvgRGBA(255, 220, 80, 255))
                nvgText(vg, minusBtnX + minusBtnW + 30, batchY + 18, "Lv." .. sealBatchTarget, nil)

                -- + 按钮
                local plusBtnX = minusBtnX + minusBtnW + 58
                nvgBeginPath(vg); nvgRoundedRect(vg, plusBtnX, batchY + 4, minusBtnW, minusBtnH, 5)
                nvgFillColor(vg, sealBatchTarget < SEAL_MAX_LEVEL and nvgRGBA(60, 30, 90, 220) or nvgRGBA(30, 18, 45, 150))
                nvgFill(vg)
                nvgStrokeColor(vg, nvgRGBA(140, 80, 220, 120)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
                nvgFontSize(vg, 20); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
                DrawWhiteInkText(plusBtnX + minusBtnW / 2, batchY + 4 + minusBtnH / 2, "+")
                sealMgrBtnRects.batchPlus = { x = plusBtnX, y = batchY + 4, w = minusBtnW, h = minusBtnH }

                -- 所需经验
                nvgFontSize(vg, 12); nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)
                nvgFillColor(vg, nvgRGBA(180, 160, 220, 180))
                nvgText(vg, pX + 26, batchY + 40, "需" .. expNeeded .. "EXP", nil)

                -- 材料消耗预览
                if plan then
                    local previewX = pX + 100
                    nvgFontSize(vg, 11)
                    for idx = 1, #SEAL_EXP_ITEMS do
                        local use = plan[idx] or 0
                        if use > 0 then
                            nvgFillColor(vg, nvgRGBA(200, 180, 255, 200))
                            nvgText(vg, previewX, batchY + 40, SEAL_EXP_ITEMS[idx].name .. "x" .. use, nil)
                            local tw = nvgTextBounds(vg, 0, 0, SEAL_EXP_ITEMS[idx].name .. "x" .. use, nil)
                            previewX = previewX + tw + 8
                        end
                    end
                else
                    nvgFontSize(vg, 12)
                    nvgFillColor(vg, nvgRGBA(255, 100, 100, 200))
                    nvgText(vg, pX + 100, batchY + 40, "材料不足", nil)
                end

                -- 一键升级按钮
                local goBtnW = 80
                local goBtnH = 36
                local goBtnX = pX + pW - goBtnW - 24
                local goBtnY2 = batchY + 8
                nvgBeginPath(vg); nvgRoundedRect(vg, goBtnX, goBtnY2, goBtnW, goBtnH, 6)
                if canBatch then
                    local goGrad = nvgLinearGradient(vg, goBtnX, goBtnY2, goBtnX, goBtnY2 + goBtnH,
                        nvgRGBA(180, 80, 255, 230), nvgRGBA(120, 40, 200, 230))
                    nvgFillPaint(vg, goGrad); nvgFill(vg)
                    nvgStrokeColor(vg, nvgRGBA(220, 160, 255, 180)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
                else
                    nvgFillColor(vg, nvgRGBA(40, 25, 55, 180)); nvgFill(vg)
                    nvgStrokeColor(vg, nvgRGBA(80, 50, 110, 80)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
                end
                nvgFontSize(vg, 16); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
                if canBatch then
                    DrawWhiteInkText(goBtnX + goBtnW / 2, goBtnY2 + goBtnH / 2, "一键升级")
                else
                    nvgFillColor(vg, nvgRGBA(80, 60, 100, 120))
                    nvgText(vg, goBtnX + goBtnW / 2, goBtnY2 + goBtnH / 2, "一键升级", nil)
                end
                sealMgrBtnRects.batchGo = canBatch and { x = goBtnX, y = goBtnY2, w = goBtnW, h = goBtnH } or nil
            end

            local batchAreaH = (slot.level < SEAL_MAX_LEVEL) and 60 or 0

            -- ============ 替换 / 分解 操作按钮 ============
            local actionBtnY = useBtnY + useBtnH + 14 + batchAreaH
            local actionBtnW = (pW - 54) / 2
            local actionBtnH = 38

            -- 替换按钮
            local replaceBtnX = pX + 20
            nvgBeginPath(vg); nvgRoundedRect(vg, replaceBtnX, actionBtnY, actionBtnW, actionBtnH, 6)
            nvgFillColor(vg, nvgRGBA(35, 70, 110, 220)); nvgFill(vg)
            nvgStrokeColor(vg, nvgRGBA(80, 150, 220, 160)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
            nvgFontSize(vg, 18)
            nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
            DrawWhiteInkText(replaceBtnX + actionBtnW / 2, actionBtnY + actionBtnH / 2, "替换兵符")
            sealMgrBtnRects.replaceBtn = { x = replaceBtnX, y = actionBtnY, w = actionBtnW, h = actionBtnH }

            -- 分解按钮
            local decomposeBtnX = pX + 34 + actionBtnW
            nvgBeginPath(vg); nvgRoundedRect(vg, decomposeBtnX, actionBtnY, actionBtnW, actionBtnH, 6)
            nvgFillColor(vg, nvgRGBA(110, 35, 35, 220)); nvgFill(vg)
            nvgStrokeColor(vg, nvgRGBA(200, 80, 80, 160)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
            nvgFontSize(vg, 18)
            nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
            DrawWhiteInkText(decomposeBtnX + actionBtnW / 2, actionBtnY + actionBtnH / 2, "分解兵符")
            sealMgrBtnRects.decomposeBtn = { x = decomposeBtnX, y = actionBtnY, w = actionBtnW, h = actionBtnH }
        end
    end

    -- ============ 替换弹窗 (最高优先级) ============
    if sealReplaceState.show then
        DrawSealReplacePopup()
    end

    -- ============ 分解确认弹窗 (次高优先级) ============
    if sealDecomposeState.show then
        DrawSealDecomposeConfirm()
    end

    -- ============ 筛选分解确认弹窗 ============
    if sealInvFilterState.batchConfirmShow then
        DrawSealBatchDecompConfirm()
    end
end

-- ============================================================================
-- 兵符替换弹窗绘制
-- ============================================================================
function DrawSealReplacePopup()
    local W = DESIGN_W
    local H = DESIGN_H
    local cx = W / 2
    local heroIdx = sealReplaceState.heroIdx
    local slotIdx = sealReplaceState.slotIdx
    if not heroIdx or not slotIdx then return end

    -- 半透明遮罩
    nvgBeginPath(vg); nvgRect(vg, 0, 0, W, H)
    nvgFillColor(vg, nvgRGBA(5, 3, 15, 190)); nvgFill(vg)

    -- 弹窗面板
    local pW = W * 0.92
    local pH = H * 0.72
    local pX = cx - pW / 2
    local pY = H / 2 - pH / 2

    local pGrad = nvgLinearGradient(vg, pX, pY, pX, pY + pH,
        nvgRGBA(38, 18, 58, 250), nvgRGBA(22, 10, 38, 252))
    nvgBeginPath(vg); nvgRoundedRect(vg, pX, pY, pW, pH, 12)
    nvgFillPaint(vg, pGrad); nvgFill(vg)
    nvgBeginPath(vg); nvgRoundedRect(vg, pX, pY, pW, pH, 12)
    nvgStrokeColor(vg, nvgRGBA(160, 80, 240, 140)); nvgStrokeWidth(vg, 1.5); nvgStroke(vg)

    nvgFontFaceId(vg, GetMainFont())

    -- 标题
    local stc = SEAL_SLOT_THEME_COLORS[slotIdx] or { 200, 160, 255 }
    nvgFontSize(vg, 26)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(cx, pY + 28, SEAL_SLOT_NAMES[slotIdx] .. " - 仓库")

    -- 当前装备信息
    local sd = sealData[heroIdx]
    local equipped = sd and sd.slots and sd.slots[slotIdx]
    local infoY = pY + 54
    if equipped then
        local sc = SEAL_QUALITY_COLORS[equipped.sealQ] or { 180, 180, 180 }
        nvgFontSize(vg, 15)
        nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        nvgFillColor(vg, nvgRGBA(sc[1], sc[2], sc[3], 220))
        nvgText(vg, cx, infoY, "当前: " .. (SEAL_QUALITY_NAMES[equipped.sealQ] or "?") .. " Lv." .. (equipped.level or 1), nil)
    else
        nvgFontSize(vg, 15)
        nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        nvgFillColor(vg, nvgRGBA(120, 100, 160, 150))
        nvgText(vg, cx, infoY, "当前: 空", nil)
    end

    -- 关闭按钮
    local closeBtnSize = 36
    local closeX = pX + pW - closeBtnSize - 8
    local closeY = pY + 8
    nvgBeginPath(vg); nvgRoundedRect(vg, closeX, closeY, closeBtnSize, closeBtnSize, 6)
    nvgFillColor(vg, nvgRGBA(50, 25, 70, 220)); nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(160, 100, 220, 120)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
    nvgFontSize(vg, 24)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(closeX + closeBtnSize / 2, closeY + closeBtnSize / 2, "X")
    sealReplaceBtnRects.close = { x = closeX, y = closeY, w = closeBtnSize, h = closeBtnSize }

    -- 仓库列表区域
    local listX = pX + 12
    local listY = infoY + 22
    local listW = pW - 24 - 14  -- 右边留14px给滚动条
    local listH = pH - (listY - pY) - 16
    local itemH = 80
    local itemGap = 6

    -- 获取所有兵符（按品质降序），高亮匹配项，其余半遮罩
    local allSeals = GetAllInventorySeals()
    sealReplaceListRects = {}

    if #allSeals == 0 then
        nvgFontSize(vg, 18)
        nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        nvgFillColor(vg, nvgRGBA(140, 110, 180, 120))
        nvgText(vg, cx, listY + listH / 2, "仓库中没有兵符", nil)
        return
    end

    -- 对列表排序：匹配的排前面，不匹配的排后面，各自内部按品质降序
    table.sort(allSeals, function(a, b)
        local aMatch = (a.seal.slotType == slotIdx and a.seal.fromHero == heroIdx) and 1 or 0
        local bMatch = (b.seal.slotType == slotIdx and b.seal.fromHero == heroIdx) and 1 or 0
        if aMatch ~= bMatch then return aMatch > bMatch end
        if a.seal.sealQ ~= b.seal.sealQ then return a.seal.sealQ > b.seal.sealQ end
        if a.seal.slotType ~= b.seal.slotType then return a.seal.slotType < b.seal.slotType end
        return a.seal.level > b.seal.level
    end)

    -- 统计匹配数量
    local matchCount = 0
    for _, e in ipairs(allSeals) do
        if e.seal.slotType == slotIdx and e.seal.fromHero == heroIdx then matchCount = matchCount + 1 end
    end

    -- 匹配/全部计数
    nvgFontSize(vg, 12)
    nvgTextAlign(vg, NVG_ALIGN_RIGHT + NVG_ALIGN_MIDDLE)
    nvgFillColor(vg, nvgRGBA(180, 140, 240, 160))
    nvgText(vg, pX + pW - 18, listY - 8, "匹配 " .. matchCount .. " / 全部 " .. #allSeals, nil)

    -- 内容总高度
    local contentH = #allSeals * (itemH + itemGap) - itemGap
    local maxScroll = math.max(0, contentH - listH)
    local scrollY = sealReplaceState.scroll.y
    scrollY = math.max(0, math.min(scrollY, maxScroll))
    sealReplaceState.scroll.y = scrollY
    sealReplaceState.scroll.contentH = contentH
    sealReplaceState.scroll.viewH = listH

    -- 裁剪区域
    nvgSave(vg)
    nvgScissor(vg, listX, listY, listW + 14, listH)

    -- 绘制列表项
    for i, entry in ipairs(allSeals) do
        local seal = entry.seal
        local iy = listY + (i - 1) * (itemH + itemGap) - scrollY
        -- 可见性检测
        if iy + itemH >= listY and iy <= listY + listH then
            local isMatch = (seal.slotType == slotIdx and seal.fromHero == heroIdx)
            local dimAlpha = isMatch and 1.0 or 0.35  -- 不匹配的整体降低透明度
            local sc = SEAL_QUALITY_COLORS[seal.sealQ] or { 180, 180, 180 }

            -- 项目背景
            nvgBeginPath(vg); nvgRoundedRect(vg, listX, iy, listW, itemH, 6)
            nvgFillColor(vg, nvgRGBA(28, 14, 45, math.floor(220 * dimAlpha))); nvgFill(vg)
            nvgBeginPath(vg); nvgRoundedRect(vg, listX, iy, listW, itemH, 6)
            nvgStrokeColor(vg, nvgRGBA(sc[1], sc[2], sc[3], math.floor(100 * dimAlpha))); nvgStrokeWidth(vg, 1); nvgStroke(vg)

            -- 左侧: 六角形小图标
            local hexX = listX + 32
            local hexY = iy + itemH / 2
            local hexR = 22
            if isMatch then
                DrawSealHexIcon(hexX, hexY, hexR, sc, seal.sealQ)
            else
                -- 暗淡版六角形
                local dsc = { math.floor(sc[1] * 0.4), math.floor(sc[2] * 0.4), math.floor(sc[3] * 0.4) }
                DrawSealHexIcon(hexX, hexY, hexR, dsc, seal.sealQ)
            end
            nvgFontSize(vg, 13)
            nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
            if isMatch then
                DrawWhiteInkText(hexX, hexY + 2, "Lv." .. (seal.level or 1))
            else
                nvgFillColor(vg, nvgRGBA(180, 180, 180, 80))
                nvgText(vg, hexX, hexY + 2, "Lv." .. (seal.level or 1), nil)
            end

            -- 中间: 信息
            local infoX = listX + 68
            nvgFontSize(vg, 16)
            nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)
            nvgFillColor(vg, nvgRGBA(sc[1], sc[2], sc[3], math.floor(230 * dimAlpha)))
            nvgText(vg, infoX, iy + 18, (SEAL_QUALITY_NAMES[seal.sealQ] or "?") .. " " .. SEAL_SLOT_NAMES[seal.slotType], nil)

            -- 效果描述
            local eff = SEAL_SLOT_EFFECTS[seal.slotType]
            if eff then
                nvgFontSize(vg, 12)
                local effTC = SEAL_SLOT_THEME_COLORS[seal.slotType] or stc
                nvgFillColor(vg, nvgRGBA(effTC[1], effTC[2], effTC[3], math.floor(180 * dimAlpha)))
                local tierData = eff[seal.sealQ] or eff[1]
                local mainVal = (tierData.main or 0) * (seal.level or 1)
                local desc = eff.mainName .. string.format("+%.1f", mainVal)
                if eff.subKey and tierData.sub then
                    local subVal = tierData.sub * (seal.level or 1)
                    desc = desc .. "  " .. eff.subName .. string.format("+%.1f", subVal)
                end
                nvgText(vg, infoX, iy + 38, desc, nil)
            end

            -- 来源英雄
            if seal.fromHero and HERO_CARDS[seal.fromHero] then
                nvgFontSize(vg, 11)
                nvgFillColor(vg, nvgRGBA(140, 120, 180, math.floor((isMatch and 120 or 60) * 1)))
                local heroTag = HERO_CARDS[seal.fromHero].name
                if not isMatch then heroTag = heroTag .. (seal.slotType ~= slotIdx and " [孔位不同]" or " [其他武灵]") end
                nvgText(vg, infoX, iy + 54, "来源: " .. heroTag, nil)
            end

            -- 右侧按钮: 装备 / 分解
            local btnW = 52
            local btnH2 = 28
            local btnGap2 = 6
            local btnX = listX + listW - btnW - 8

            sealReplaceListRects[i] = sealReplaceListRects[i] or {}

            if isMatch then
                -- 装备按钮（仅匹配的兵符可装备）
                local equipBtnY = iy + (itemH / 2 - btnH2 - btnGap2 / 2)
                nvgBeginPath(vg); nvgRoundedRect(vg, btnX, equipBtnY, btnW, btnH2, 4)
                nvgFillColor(vg, nvgRGBA(40, 120, 80, 220)); nvgFill(vg)
                nvgStrokeColor(vg, nvgRGBA(80, 200, 120, 160)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
                nvgFontSize(vg, 15)
                nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
                DrawWhiteInkText(btnX + btnW / 2, equipBtnY + btnH2 / 2, "装备")
                sealReplaceListRects[i].equip = { x = btnX, y = equipBtnY, w = btnW, h = btnH2, invIndex = entry.index }
            else
                -- 不匹配: 显示灰色禁用的装备按钮
                local equipBtnY = iy + (itemH / 2 - btnH2 - btnGap2 / 2)
                nvgBeginPath(vg); nvgRoundedRect(vg, btnX, equipBtnY, btnW, btnH2, 4)
                nvgFillColor(vg, nvgRGBA(30, 30, 30, 120)); nvgFill(vg)
                nvgStrokeColor(vg, nvgRGBA(80, 80, 80, 60)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
                nvgFontSize(vg, 15)
                nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
                nvgFillColor(vg, nvgRGBA(120, 120, 120, 80))
                nvgText(vg, btnX + btnW / 2, equipBtnY + btnH2 / 2, "装备", nil)
                -- 不设置 equip rect，禁止点击
            end

            -- 分解按钮（所有兵符都可分解）
            local decompBtnY = iy + (itemH / 2 + btnGap2 / 2)
            nvgBeginPath(vg); nvgRoundedRect(vg, btnX, decompBtnY, btnW, btnH2, 4)
            nvgFillColor(vg, nvgRGBA(120, 40, 40, math.floor(220 * (isMatch and 1.0 or 0.6)))); nvgFill(vg)
            nvgStrokeColor(vg, nvgRGBA(200, 80, 80, math.floor(160 * (isMatch and 1.0 or 0.6)))); nvgStrokeWidth(vg, 1); nvgStroke(vg)
            nvgFontSize(vg, 15)
            nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
            if isMatch then
                DrawWhiteInkText(btnX + btnW / 2, decompBtnY + btnH2 / 2, "分解")
            else
                nvgFillColor(vg, nvgRGBA(200, 160, 160, 140))
                nvgText(vg, btnX + btnW / 2, decompBtnY + btnH2 / 2, "分解", nil)
            end
            sealReplaceListRects[i].decompose = { x = btnX, y = decompBtnY, w = btnW, h = btnH2, invIndex = entry.index }

            -- 不匹配的兵符加半透明深色遮罩
            if not isMatch then
                nvgBeginPath(vg); nvgRoundedRect(vg, listX, iy, listW, itemH, 6)
                nvgFillColor(vg, nvgRGBA(8, 4, 18, 120)); nvgFill(vg)
            end
        end
    end

    nvgRestore(vg)

    -- 滚动条（粗，高可见度）
    if contentH > listH then
        local sbBarW = 8
        local sbX = pX + pW - sbBarW - 4
        local sbTotalH = listH
        local sbThumbH = math.max(30, sbTotalH * (listH / contentH))
        local sbThumbY = listY + (scrollY / maxScroll) * (sbTotalH - sbThumbH)

        -- 轨道
        nvgBeginPath(vg); nvgRoundedRect(vg, sbX, listY, sbBarW, sbTotalH, sbBarW / 2)
        nvgFillColor(vg, nvgRGBA(40, 20, 60, 100)); nvgFill(vg)

        -- 滑块
        nvgBeginPath(vg); nvgRoundedRect(vg, sbX, sbThumbY, sbBarW, sbThumbH, sbBarW / 2)
        nvgFillColor(vg, nvgRGBA(180, 120, 240, sealReplaceState.scroll.isDragging and 220 or 160)); nvgFill(vg)
    end
end

-- ============================================================================
-- 兵符分解确认弹窗绘制
-- ============================================================================
function DrawSealDecomposeConfirm()
    local W = DESIGN_W
    local H = DESIGN_H
    local cx = W / 2

    -- 半透明遮罩
    nvgBeginPath(vg); nvgRect(vg, 0, 0, W, H)
    nvgFillColor(vg, nvgRGBA(5, 3, 15, 200)); nvgFill(vg)

    -- 获取兵符信息
    local sealQ, slotType, sealLevel
    if sealDecomposeState.source == "inventory" and sealDecomposeState.invIndex then
        local invSeal = sealInventory[sealDecomposeState.invIndex]
        if not invSeal then sealDecomposeState.show = false; return end
        sealQ = invSeal.sealQ
        slotType = invSeal.slotType
        sealLevel = invSeal.level or 1
    elseif sealDecomposeState.source == "equipped" and sealDecomposeState.heroIdx and sealDecomposeState.slotIdx then
        local sd = sealData[sealDecomposeState.heroIdx]
        local slot = sd and sd.slots and sd.slots[sealDecomposeState.slotIdx]
        if not slot then sealDecomposeState.show = false; return end
        sealQ = slot.sealQ
        slotType = sealDecomposeState.slotIdx
        sealLevel = slot.level or 1
    else
        sealDecomposeState.show = false; return
    end

    local sc = SEAL_QUALITY_COLORS[sealQ] or { 180, 180, 180 }
    local qName = SEAL_QUALITY_NAMES[sealQ] or "?"

    -- 弹窗面板
    local pW = W * 0.78
    local pH = 300
    local pX = cx - pW / 2
    local pY = H / 2 - pH / 2

    local pGrad = nvgLinearGradient(vg, pX, pY, pX, pY + pH,
        nvgRGBA(50, 20, 30, 250), nvgRGBA(30, 12, 22, 252))
    nvgBeginPath(vg); nvgRoundedRect(vg, pX, pY, pW, pH, 12)
    nvgFillPaint(vg, pGrad); nvgFill(vg)
    nvgBeginPath(vg); nvgRoundedRect(vg, pX, pY, pW, pH, 12)
    nvgStrokeColor(vg, nvgRGBA(220, 80, 80, 160)); nvgStrokeWidth(vg, 1.5); nvgStroke(vg)

    nvgFontFaceId(vg, GetMainFont())

    -- 标题
    nvgFontSize(vg, 26)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(cx, pY + 30, "确认分解")

    -- 兵符信息
    nvgFontSize(vg, 20)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    nvgFillColor(vg, nvgRGBA(sc[1], sc[2], sc[3], 240))
    nvgText(vg, cx, pY + 70, qName .. " " .. SEAL_SLOT_NAMES[slotType] .. " Lv." .. sealLevel, nil)

    -- 返还道具预览
    local returns = SEAL_DECOMPOSE_RETURNS[sealQ] or SEAL_DECOMPOSE_RETURNS[1]
    local retY = pY + 105
    nvgFontSize(vg, 15)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(cx, retY, "分解将获得:")
    retY = retY + 24
    for _, ret in ipairs(returns) do
        nvgFontSize(vg, 14)
        nvgFillColor(vg, nvgRGBA(200, 180, 255, 220))
        nvgText(vg, cx, retY, SEAL_EXP_ITEMS[ret.idx].name .. " x" .. ret.count, nil)
        retY = retY + 20
    end
    -- 额外经验返还提示
    if sealLevel > 1 then
        local extraExp = 0
        for lv = 1, sealLevel - 1 do extraExp = extraExp + (SEAL_EXP_TABLE[lv] or 0) end
        local extraCount = math.floor(extraExp / SEAL_EXP_ITEMS[1].exp)
        if extraCount > 0 then
            nvgFontSize(vg, 13)
            nvgFillColor(vg, nvgRGBA(255, 220, 100, 180))
            nvgText(vg, cx, retY, "+" .. SEAL_EXP_ITEMS[1].name .. " x" .. extraCount .. " (经验返还)", nil)
            retY = retY + 20
        end
    end

    -- 按钮区域
    local btnW = 110
    local btnH2 = 42
    local btnY = pY + pH - btnH2 - 24
    local btnGap = 30

    -- 确认按钮
    local confirmX = cx - btnW - btnGap / 2
    nvgBeginPath(vg); nvgRoundedRect(vg, confirmX, btnY, btnW, btnH2, 6)
    nvgFillColor(vg, nvgRGBA(160, 40, 40, 230)); nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(220, 80, 80, 180)); nvgStrokeWidth(vg, 1.2); nvgStroke(vg)
    nvgFontSize(vg, 20)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(confirmX + btnW / 2, btnY + btnH2 / 2, "确认分解")
    sealDecomposeBtnRects.confirm = { x = confirmX, y = btnY, w = btnW, h = btnH2 }

    -- 取消按钮
    local cancelX = cx + btnGap / 2
    nvgBeginPath(vg); nvgRoundedRect(vg, cancelX, btnY, btnW, btnH2, 6)
    nvgFillColor(vg, nvgRGBA(50, 35, 70, 230)); nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(120, 90, 170, 150)); nvgStrokeWidth(vg, 1.2); nvgStroke(vg)
    nvgFontSize(vg, 20)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(cancelX + btnW / 2, btnY + btnH2 / 2, "取消")
    sealDecomposeBtnRects.cancel = { x = cancelX, y = btnY, w = btnW, h = btnH2 }
end

-- ============================================================================
-- 兵符筛选分解确认弹窗
-- ============================================================================
function DrawSealBatchDecompConfirm()
    local W = DESIGN_W
    local H = DESIGN_H
    local cx = W / 2

    -- 遮罩
    nvgBeginPath(vg); nvgRect(vg, 0, 0, W, H)
    nvgFillColor(vg, nvgRGBA(5, 3, 15, 200)); nvgFill(vg)

    -- 弹窗面板
    local pW = W * 0.82
    local pH = 340
    local pX = cx - pW / 2
    local pY = H / 2 - pH / 2

    local pGrad = nvgLinearGradient(vg, pX, pY, pX, pY + pH,
        nvgRGBA(50, 20, 30, 250), nvgRGBA(30, 12, 22, 252))
    nvgBeginPath(vg); nvgRoundedRect(vg, pX, pY, pW, pH, 12)
    nvgFillPaint(vg, pGrad); nvgFill(vg)
    nvgBeginPath(vg); nvgRoundedRect(vg, pX, pY, pW, pH, 12)
    nvgStrokeColor(vg, nvgRGBA(220, 80, 80, 160)); nvgStrokeWidth(vg, 1.5); nvgStroke(vg)

    nvgFontFaceId(vg, GetMainFont())
    nvgFontSize(vg, 24)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(cx, pY + 32, "筛选分解兵符")

    -- 品质筛选行
    local filterY = pY + 75
    local arrowW, arrowH = 32, 28
    nvgFontSize(vg, 15)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    nvgFillColor(vg, nvgRGBA(200, 180, 220, 220))
    nvgText(vg, cx - 70, filterY, "品质上限:", nil)

    -- 左箭头
    local arrowLX = cx + 10
    nvgBeginPath(vg); nvgRoundedRect(vg, arrowLX, filterY - arrowH / 2, arrowW, arrowH, 4)
    nvgFillColor(vg, nvgRGBA(60, 40, 80, 220)); nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(140, 100, 200, 150)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
    nvgFillColor(vg, nvgRGBA(255, 255, 255, 220))
    nvgText(vg, arrowLX + arrowW / 2, filterY, "<", nil)
    sealInvFilterBtnRects.tierLeft = { x = arrowLX, y = filterY - arrowH / 2, w = arrowW, h = arrowH }

    -- 当前品质
    local ft = sealInvFilterState.filterMaxTier
    local tierLabel = ft <= 7 and (SEAL_TIER_NAMES[ft] or "全部") or "全部"
    local tc = SEAL_QUALITY_COLORS[ft] or { 200, 200, 200 }
    nvgFillColor(vg, nvgRGBA(tc[1], tc[2], tc[3], 240))
    nvgFontSize(vg, 17)
    nvgText(vg, cx + 70, filterY, tierLabel, nil)

    -- 右箭头
    local arrowRX = cx + 105
    nvgBeginPath(vg); nvgRoundedRect(vg, arrowRX, filterY - arrowH / 2, arrowW, arrowH, 4)
    nvgFillColor(vg, nvgRGBA(60, 40, 80, 220)); nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(140, 100, 200, 150)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
    nvgFillColor(vg, nvgRGBA(255, 255, 255, 220))
    nvgText(vg, arrowRX + arrowW / 2, filterY, ">", nil)
    sealInvFilterBtnRects.tierRight = { x = arrowRX, y = filterY - arrowH / 2, w = arrowW, h = arrowH }

    -- 孔位筛选行
    local slotFilterY = filterY + 40
    nvgFontSize(vg, 15)
    nvgFillColor(vg, nvgRGBA(200, 180, 220, 220))
    nvgText(vg, cx - 70, slotFilterY, "孔位筛选:", nil)

    local slotArrowLX = cx + 10
    nvgBeginPath(vg); nvgRoundedRect(vg, slotArrowLX, slotFilterY - arrowH / 2, arrowW, arrowH, 4)
    nvgFillColor(vg, nvgRGBA(60, 40, 80, 220)); nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(140, 100, 200, 150)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
    nvgFillColor(vg, nvgRGBA(255, 255, 255, 220))
    nvgText(vg, slotArrowLX + arrowW / 2, slotFilterY, "<", nil)
    sealInvFilterBtnRects.slotLeft = { x = slotArrowLX, y = slotFilterY - arrowH / 2, w = arrowW, h = arrowH }

    local sf = sealInvFilterState.filterSlotType
    local slotLabel = sf == 0 and "全部" or SEAL_SLOT_NAMES[sf]
    local slotC = sf > 0 and (SEAL_SLOT_THEME_COLORS[sf] or { 200, 160, 255 }) or { 200, 200, 200 }
    nvgFillColor(vg, nvgRGBA(slotC[1], slotC[2], slotC[3], 240))
    nvgFontSize(vg, 17)
    nvgText(vg, cx + 70, slotFilterY, slotLabel, nil)

    local slotArrowRX = cx + 105
    nvgBeginPath(vg); nvgRoundedRect(vg, slotArrowRX, slotFilterY - arrowH / 2, arrowW, arrowH, 4)
    nvgFillColor(vg, nvgRGBA(60, 40, 80, 220)); nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(140, 100, 200, 150)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
    nvgFillColor(vg, nvgRGBA(255, 255, 255, 220))
    nvgText(vg, slotArrowRX + arrowW / 2, slotFilterY, ">", nil)
    sealInvFilterBtnRects.slotRight = { x = slotArrowRX, y = slotFilterY - arrowH / 2, w = arrowW, h = arrowH }

    -- 分割线
    nvgBeginPath(vg)
    nvgMoveTo(vg, pX + 20, slotFilterY + 22)
    nvgLineTo(vg, pX + pW - 20, slotFilterY + 22)
    nvgStrokeColor(vg, nvgRGBA(100, 60, 140, 80)); nvgStrokeWidth(vg, 1); nvgStroke(vg)

    -- 统计
    local bdc, bdReturns = CalcSealBatchDecomp(ft, sf)
    local statY = slotFilterY + 42
    nvgFontSize(vg, 16)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    nvgFillColor(vg, nvgRGBA(200, 180, 220, 220))
    nvgText(vg, cx, statY, "将分解 " .. bdc .. " 件仓库兵符", nil)
    if bdc > 0 then
        local parts = {}
        for idx = 1, #SEAL_EXP_ITEMS do
            if bdReturns[idx] and bdReturns[idx] > 0 then
                table.insert(parts, SEAL_EXP_ITEMS[idx].name .. "x" .. bdReturns[idx])
            end
        end
        if #parts > 0 then
            nvgFontSize(vg, 14)
            nvgFillColor(vg, nvgRGBA(200, 180, 255, 180))
            nvgText(vg, cx, statY + 22, "返还: " .. table.concat(parts, " "), nil)
        end
        nvgFontSize(vg, 13)
        nvgFillColor(vg, nvgRGBA(255, 130, 80, 200))
        nvgText(vg, cx, statY + 46, "此操作不可撤销!", nil)
    else
        nvgFontSize(vg, 14)
        nvgFillColor(vg, nvgRGBA(140, 120, 180, 140))
        nvgText(vg, cx, statY + 22, "当前筛选无可分解兵符", nil)
    end

    -- 按钮
    local btnW = 110
    local btnH2 = 40
    local btnY = pY + pH - btnH2 - 20
    local btnGap = 30

    -- 确认按钮
    local confirmX = cx - btnW - btnGap / 2
    nvgBeginPath(vg); nvgRoundedRect(vg, confirmX, btnY, btnW, btnH2, 6)
    if bdc > 0 then
        nvgFillColor(vg, nvgRGBA(160, 40, 40, 230)); nvgFill(vg)
        nvgStrokeColor(vg, nvgRGBA(220, 80, 80, 180)); nvgStrokeWidth(vg, 1.2); nvgStroke(vg)
    else
        nvgFillColor(vg, nvgRGBA(60, 40, 50, 180)); nvgFill(vg)
        nvgStrokeColor(vg, nvgRGBA(100, 70, 90, 100)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
    end
    nvgFontSize(vg, 18)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(confirmX + btnW / 2, btnY + btnH2 / 2, "确认分解")
    sealInvFilterBtnRects.batchConfirm = bdc > 0 and { x = confirmX, y = btnY, w = btnW, h = btnH2 } or nil

    -- 取消按钮
    local cancelX = cx + btnGap / 2
    nvgBeginPath(vg); nvgRoundedRect(vg, cancelX, btnY, btnW, btnH2, 6)
    nvgFillColor(vg, nvgRGBA(50, 35, 70, 230)); nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(120, 90, 170, 150)); nvgStrokeWidth(vg, 1.2); nvgStroke(vg)
    nvgFontSize(vg, 18)
    DrawWhiteInkText(cancelX + btnW / 2, btnY + btnH2 / 2, "取消")
    sealInvFilterBtnRects.batchCancel = { x = cancelX, y = btnY, w = btnW, h = btnH2 }
end

-- ============================================================================
-- 兵符选中分解模式 - 全屏仓库列表
-- ============================================================================
function DrawSealSelectModeList()
    local W = DESIGN_W
    local H = DESIGN_H
    local cx = W / 2

    nvgFontFaceId(vg, GetMainFont())

    -- 提示标题
    nvgFontSize(vg, 18)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    nvgFillColor(vg, nvgRGBA(100, 180, 255, 200))
    nvgText(vg, cx, 82, "点击选中要分解的兵符", nil)

    -- 列表区域
    local listX = 14
    local listY = 100
    local listW = W - 28
    local listH = H - listY - 60  -- 底部留操作栏
    local itemH = 62
    local itemGap = 4

    local allSeals = GetAllInventorySeals()
    sealInvFilterBtnRects.selectItems = {}

    if #allSeals == 0 then
        nvgFontSize(vg, 16)
        nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        nvgFillColor(vg, nvgRGBA(140, 120, 180, 120))
        nvgText(vg, cx, listY + listH / 2, "仓库中没有兵符", nil)
    else
        -- 滚动
        local contentH = #allSeals * (itemH + itemGap) - itemGap
        local maxScroll = math.max(0, contentH - listH)
        local scrollY = math.max(0, math.min(sealMgrScroll.y or 0, maxScroll))
        sealMgrScroll.y = scrollY
        sealMgrScroll.contentH = contentH
        sealMgrScroll.viewH = listH

        nvgSave(vg)
        nvgScissor(vg, listX, listY, listW, listH)

        for fi, entry in ipairs(allSeals) do
            local seal = entry.seal
            local invIdx = entry.index
            local iy = listY + (fi - 1) * (itemH + itemGap) - scrollY

            if iy + itemH >= listY and iy <= listY + listH then
                local sc = SEAL_QUALITY_COLORS[seal.sealQ] or { 180, 180, 180 }
                local isSelected = sealInvFilterState.selectedIds[invIdx] == true

                -- 背景
                nvgBeginPath(vg); nvgRoundedRect(vg, listX, iy, listW, itemH, 6)
                if isSelected then
                    nvgFillColor(vg, nvgRGBA(60, 30, 30, 230)); nvgFill(vg)
                    nvgBeginPath(vg); nvgRoundedRect(vg, listX, iy, listW, itemH, 6)
                    nvgStrokeColor(vg, nvgRGBA(220, 100, 80, 200)); nvgStrokeWidth(vg, 1.5); nvgStroke(vg)
                else
                    nvgFillColor(vg, nvgRGBA(28, 14, 45, 220)); nvgFill(vg)
                    nvgBeginPath(vg); nvgRoundedRect(vg, listX, iy, listW, itemH, 6)
                    nvgStrokeColor(vg, nvgRGBA(sc[1], sc[2], sc[3], 80)); nvgStrokeWidth(vg, 0.8); nvgStroke(vg)
                end

                -- 勾选框
                local cbSize = 22
                local cbX = listX + 10
                local cbY = iy + itemH / 2 - cbSize / 2
                nvgBeginPath(vg); nvgRoundedRect(vg, cbX, cbY, cbSize, cbSize, 4)
                if isSelected then
                    nvgFillColor(vg, nvgRGBA(200, 60, 60, 230)); nvgFill(vg)
                    nvgFontSize(vg, 16)
                    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
                    nvgFillColor(vg, nvgRGBA(255, 255, 255, 255))
                    nvgText(vg, cbX + cbSize / 2, cbY + cbSize / 2, "✓", nil)
                else
                    nvgFillColor(vg, nvgRGBA(40, 25, 60, 200)); nvgFill(vg)
                    nvgBeginPath(vg); nvgRoundedRect(vg, cbX, cbY, cbSize, cbSize, 4)
                    nvgStrokeColor(vg, nvgRGBA(120, 90, 170, 120)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
                end

                -- 六角图标
                local hexX = cbX + cbSize + 18
                local hexY = iy + itemH / 2
                DrawSealHexIcon(hexX, hexY, 18, sc, seal.sealQ)
                nvgFontSize(vg, 11)
                nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
                DrawWhiteInkText(hexX, hexY + 2, "Lv." .. (seal.level or 1))

                -- 信息
                local infoX = hexX + 28
                nvgFontSize(vg, 15)
                nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)
                nvgFillColor(vg, nvgRGBA(sc[1], sc[2], sc[3], 230))
                nvgText(vg, infoX, iy + 18, (SEAL_QUALITY_NAMES[seal.sealQ] or "?") .. " " .. SEAL_SLOT_NAMES[seal.slotType], nil)

                -- 属性简述
                local stc = SEAL_SLOT_THEME_COLORS[seal.slotType] or { 200, 160, 255 }
                local eff = SEAL_SLOT_EFFECTS[seal.slotType]
                if eff then
                    nvgFontSize(vg, 11)
                    nvgFillColor(vg, nvgRGBA(stc[1], stc[2], stc[3], 180))
                    local tierData = eff[seal.sealQ] or eff[1]
                    local mainVal = (tierData.main or 0) * (seal.level or 1)
                    nvgText(vg, infoX, iy + 36, eff.mainName .. string.format("+%.1f", mainVal), nil)
                end

                -- 来源
                if seal.fromHero and HERO_CARDS[seal.fromHero] then
                    nvgFontSize(vg, 10)
                    nvgFillColor(vg, nvgRGBA(140, 120, 180, 100))
                    nvgText(vg, infoX, iy + 50, "来源: " .. HERO_CARDS[seal.fromHero].name, nil)
                end

                -- 返还预览 (右侧)
                local returns = SEAL_DECOMPOSE_RETURNS[seal.sealQ] or SEAL_DECOMPOSE_RETURNS[1]
                local retParts = {}
                for _, ret in ipairs(returns) do
                    table.insert(retParts, SEAL_EXP_ITEMS[ret.idx].name:sub(1, 6) .. "x" .. ret.count)
                end
                nvgFontSize(vg, 10)
                nvgTextAlign(vg, NVG_ALIGN_RIGHT + NVG_ALIGN_MIDDLE)
                nvgFillColor(vg, nvgRGBA(180, 160, 220, 140))
                nvgText(vg, listX + listW - 8, iy + itemH / 2, table.concat(retParts, " "), nil)

                -- 点击区域
                sealInvFilterBtnRects.selectItems[fi] = { x = listX, y = iy, w = listW, h = itemH, invIndex = invIdx }
            end
        end

        nvgRestore(vg)

        -- 滚动条（粗，高可见度）
        if contentH > listH then
            local sbBarW = 8
            local sbX = W - sbBarW - 4
            local sbThumbH = math.max(30, listH * (listH / contentH))
            local sbThumbY = listY + (scrollY / maxScroll) * (listH - sbThumbH)
            -- 轨道
            nvgBeginPath(vg); nvgRoundedRect(vg, sbX, listY, sbBarW, listH, sbBarW / 2)
            nvgFillColor(vg, nvgRGBA(40, 20, 60, 100)); nvgFill(vg)
            -- 滑块
            nvgBeginPath(vg); nvgRoundedRect(vg, sbX, sbThumbY, sbBarW, sbThumbH, sbBarW / 2)
            nvgFillColor(vg, nvgRGBA(180, 120, 240, sealMgrScroll.isDragging and 220 or 160)); nvgFill(vg)
        end
    end

    -- ========== 底部操作栏 ==========
    local barH = 50
    local barY = H - barH
    nvgBeginPath(vg); nvgRect(vg, 0, barY, W, barH)
    nvgFillColor(vg, nvgRGBA(20, 10, 35, 240)); nvgFill(vg)
    nvgBeginPath(vg); nvgMoveTo(vg, 0, barY); nvgLineTo(vg, W, barY)
    nvgStrokeColor(vg, nvgRGBA(100, 60, 160, 100)); nvgStrokeWidth(vg, 1); nvgStroke(vg)

    -- 已选数量
    local selCount = 0
    for _ in pairs(sealInvFilterState.selectedIds) do selCount = selCount + 1 end
    nvgFontSize(vg, 14)
    nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)
    nvgFillColor(vg, nvgRGBA(200, 180, 255, 200))
    nvgText(vg, 14, barY + barH / 2, "已选 " .. selCount .. " 件", nil)

    -- 按钮
    local sbW2 = 76
    local sbH = 34
    local sbY = barY + (barH - sbH) / 2
    local sbGap = 8

    -- 全选
    local allX = W - 14 - sbW2 * 3 - sbGap * 2
    nvgBeginPath(vg); nvgRoundedRect(vg, allX, sbY, sbW2, sbH, 5)
    nvgFillColor(vg, nvgRGBA(50, 50, 90, 220)); nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(100, 100, 200, 150)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
    nvgFontSize(vg, 15)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(allX + sbW2 / 2, sbY + sbH / 2, "全选")
    sealInvFilterBtnRects.selectAll = { x = allX, y = sbY, w = sbW2, h = sbH }

    -- 确认分解
    local confirmX = allX + sbW2 + sbGap
    nvgBeginPath(vg); nvgRoundedRect(vg, confirmX, sbY, sbW2, sbH, 5)
    if selCount > 0 then
        nvgFillColor(vg, nvgRGBA(160, 40, 40, 230)); nvgFill(vg)
        nvgStrokeColor(vg, nvgRGBA(220, 80, 80, 180)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
    else
        nvgFillColor(vg, nvgRGBA(60, 30, 40, 180)); nvgFill(vg)
        nvgStrokeColor(vg, nvgRGBA(100, 60, 70, 100)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
    end
    nvgFontSize(vg, 15)
    DrawWhiteInkText(confirmX + sbW2 / 2, sbY + sbH / 2, "分解")
    sealInvFilterBtnRects.selectDoDecomp = { x = confirmX, y = sbY, w = sbW2, h = sbH }

    -- 取消
    local cancelX = confirmX + sbW2 + sbGap
    nvgBeginPath(vg); nvgRoundedRect(vg, cancelX, sbY, sbW2, sbH, 5)
    nvgFillColor(vg, nvgRGBA(50, 35, 70, 220)); nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(120, 90, 170, 150)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
    nvgFontSize(vg, 15)
    DrawWhiteInkText(cancelX + sbW2 / 2, sbY + sbH / 2, "取消")
    sealInvFilterBtnRects.selectCancelMode = { x = cancelX, y = sbY, w = sbW2, h = sbH }
end

-- ============================================================================
-- 兵符选中分解确认弹窗
-- ============================================================================
function DrawSealSelectDecompConfirm()
    local W = DESIGN_W
    local H = DESIGN_H
    local cx = W / 2

    -- 遮罩
    nvgBeginPath(vg); nvgRect(vg, 0, 0, W, H)
    nvgFillColor(vg, nvgRGBA(5, 3, 15, 210)); nvgFill(vg)

    local selCount, selReturns = CalcSealSelectDecomp(sealInvFilterState.selectedIds)

    -- 弹窗面板
    local pW = W * 0.78
    local pH = 240
    local pX = cx - pW / 2
    local pY = H / 2 - pH / 2

    local pGrad = nvgLinearGradient(vg, pX, pY, pX, pY + pH,
        nvgRGBA(50, 20, 30, 250), nvgRGBA(30, 12, 22, 252))
    nvgBeginPath(vg); nvgRoundedRect(vg, pX, pY, pW, pH, 12)
    nvgFillPaint(vg, pGrad); nvgFill(vg)
    nvgBeginPath(vg); nvgRoundedRect(vg, pX, pY, pW, pH, 12)
    nvgStrokeColor(vg, nvgRGBA(220, 80, 80, 160)); nvgStrokeWidth(vg, 1.5); nvgStroke(vg)

    nvgFontFaceId(vg, GetMainFont())
    nvgFontSize(vg, 22)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(cx, pY + 32, "确认分解选中兵符？")

    nvgFontSize(vg, 16)
    nvgFillColor(vg, nvgRGBA(200, 180, 220, 220))
    nvgText(vg, cx, pY + 68, "将分解 " .. selCount .. " 件兵符", nil)

    -- 返还预览
    local parts = {}
    for idx = 1, #SEAL_EXP_ITEMS do
        if selReturns[idx] and selReturns[idx] > 0 then
            table.insert(parts, SEAL_EXP_ITEMS[idx].name .. "x" .. selReturns[idx])
        end
    end
    if #parts > 0 then
        nvgFontSize(vg, 14)
        nvgFillColor(vg, nvgRGBA(200, 180, 255, 180))
        nvgText(vg, cx, pY + 95, "返还: " .. table.concat(parts, " "), nil)
    end
    nvgFontSize(vg, 13)
    nvgFillColor(vg, nvgRGBA(255, 130, 80, 200))
    nvgText(vg, cx, pY + 120, "此操作不可撤销!", nil)

    -- 按钮
    local btnW = 110
    local btnH2 = 40
    local btnY = pY + pH - btnH2 - 20
    local btnGap = 30

    local confirmX = cx - btnW - btnGap / 2
    nvgBeginPath(vg); nvgRoundedRect(vg, confirmX, btnY, btnW, btnH2, 6)
    nvgFillColor(vg, nvgRGBA(160, 40, 40, 230)); nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(220, 80, 80, 180)); nvgStrokeWidth(vg, 1.2); nvgStroke(vg)
    nvgFontSize(vg, 18)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(confirmX + btnW / 2, btnY + btnH2 / 2, "确认分解")
    sealInvFilterBtnRects.selectConfirm = { x = confirmX, y = btnY, w = btnW, h = btnH2 }

    local cancelX = cx + btnGap / 2
    nvgBeginPath(vg); nvgRoundedRect(vg, cancelX, btnY, btnW, btnH2, 6)
    nvgFillColor(vg, nvgRGBA(50, 35, 70, 230)); nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(120, 90, 170, 150)); nvgStrokeWidth(vg, 1.2); nvgStroke(vg)
    nvgFontSize(vg, 18)
    DrawWhiteInkText(cancelX + btnW / 2, btnY + btnH2 / 2, "取消")
    sealInvFilterBtnRects.selectCancel = { x = cancelX, y = btnY, w = btnW, h = btnH2 }
end

function DrawSkillGachaRulesPopup()
    local W = DESIGN_W
    local H = DESIGN_H
    local cx = W / 2

    -- 半透明遮罩
    nvgBeginPath(vg); nvgRect(vg, 0, 0, W, H)
    nvgFillColor(vg, nvgRGBA(5, 5, 12, 110)); nvgFill(vg)

    -- 弹窗面板
    local panelW = W * 0.84
    local panelH = 570
    local panelX = cx - panelW / 2
    local panelY = H / 2 - panelH / 2 - 10

    -- 面板背景（紫色调，与武技主题一致）
    local panelGrad = nvgLinearGradient(vg, panelX, panelY, panelX, panelY + panelH,
        nvgRGBA(45, 35, 60, 240), nvgRGBA(32, 25, 48, 245))
    nvgBeginPath(vg); nvgRoundedRect(vg, panelX, panelY, panelW, panelH, 10)
    nvgFillPaint(vg, panelGrad); nvgFill(vg)

    -- 面板边框
    nvgBeginPath(vg); nvgRoundedRect(vg, panelX, panelY, panelW, panelH, 10)
    nvgStrokeColor(vg, nvgRGBA(160, 100, 200, 160)); nvgStrokeWidth(vg, 1.5); nvgStroke(vg)

    nvgFontFaceId(vg, GetMainFont())

    -- 标题
    local titleY = panelY + 28
    nvgFontSize(vg, 35)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(cx, titleY, "武技感悟规则")

    -- 分隔线
    nvgBeginPath(vg)
    nvgMoveTo(vg, panelX + 20, titleY + 18)
    nvgLineTo(vg, panelX + panelW - 20, titleY + 18)
    nvgStrokeColor(vg, nvgRGBA(140, 100, 180, 80)); nvgStrokeWidth(vg, 1); nvgStroke(vg)

    -- 各阶级出率
    local lineH = 28
    local startY = titleY + 36
    local leftX = panelX + 24
    local rightX = panelX + panelW - 24

    -- 小标题: 残片出率
    nvgFontSize(vg, 25)
    nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(leftX, startY, "各阶级残片出率")
    startY = startY + lineH

    -- 7个等阶概率行 (与 SKILL_TIERS 7阶对齐)
    local totalWeight = 0
    for t = 1, 7 do totalWeight = totalWeight + (SKILL_FRAG_WEIGHTS[t] or 0) end
    local tierData = {}
    for t = 1, 7 do
        local st = SKILL_TIERS[t]
        local pct = (SKILL_FRAG_WEIGHTS[t] or 0) / totalWeight * 100
        table.insert(tierData, { name = st.name, pct = pct, color = st.color })
    end

    for _, td in ipairs(tierData) do
        local tc = td.color

        -- 等阶色块标签
        local tagW = 44
        nvgBeginPath(vg); nvgRoundedRect(vg, leftX, startY - 9, tagW, 18, 3)
        nvgFillColor(vg, nvgRGBA(tc[1], tc[2], tc[3], 180)); nvgFill(vg)
        nvgFontSize(vg, 15)
        nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        DrawWhiteInkText(leftX + tagW / 2, startY, td.name)

        -- 概率百分比
        local pctStr = string.format("%.1f%%", td.pct)
        nvgFontSize(vg, 23)
        nvgTextAlign(vg, NVG_ALIGN_RIGHT + NVG_ALIGN_MIDDLE)
        nvgFillColor(vg, nvgRGBA(tc[1], tc[2], tc[3], 220))
        nvgText(vg, rightX, startY, pctStr, nil)

        -- 概率条形图（直观展示）
        local barMaxW = rightX - leftX - tagW - 60
        local barH = 6
        local barX = leftX + tagW + 10
        local barW = barMaxW * (td.pct / 55)  -- 以最大55%为满
        nvgBeginPath(vg); nvgRoundedRect(vg, barX, startY - barH / 2, barMaxW, barH, 2)
        nvgFillColor(vg, nvgRGBA(40, 30, 60, 150)); nvgFill(vg)
        nvgBeginPath(vg); nvgRoundedRect(vg, barX, startY - barH / 2, barW, barH, 2)
        nvgFillColor(vg, nvgRGBA(tc[1], tc[2], tc[3], 160)); nvgFill(vg)

        startY = startY + lineH * 0.85
    end

    -- 分隔线
    startY = startY + 6
    nvgBeginPath(vg)
    nvgMoveTo(vg, panelX + 20, startY)
    nvgLineTo(vg, panelX + panelW - 20, startY)
    nvgStrokeColor(vg, nvgRGBA(140, 100, 180, 50)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
    startY = startY + 14

    -- 兑换说明
    nvgFontSize(vg, 25)
    nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(leftX, startY, "残片兑换")
    startY = startY + lineH * 0.85

    nvgFontSize(vg, 19)
    DrawWhiteInkText(leftX + 10, startY, "· 集齐 " .. SKILL_FRAG_EXCHANGE .. " 个同武技残片可兑换完整武技")
    startY = startY + lineH * 0.7
    nvgText(vg, leftX + 10, startY, "· 探索/战斗/任务可获得特定武技残片", nil)
    startY = startY + lineH * 0.7
    nvgText(vg, leftX + 10, startY, "· 每次感悟获得 " .. SKILL_FRAG_PER_PULL .. " 个随机残片", nil)

    -- 关闭按钮
    local closeBtnW = 120
    local closeBtnH = 36
    local closeBtnX = cx - closeBtnW / 2
    local closeBtnY = panelY + panelH - closeBtnH - 14
    nvgBeginPath(vg); nvgRoundedRect(vg, closeBtnX, closeBtnY, closeBtnW, closeBtnH, 6)
    nvgFillColor(vg, nvgRGBA(40, 30, 60, 220)); nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(180, 130, 220, 150)); nvgStrokeWidth(vg, 1.2); nvgStroke(vg)
    nvgFontSize(vg, 29)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(cx, closeBtnY + closeBtnH / 2, "知道了")
    gachaRulesCloseBtnRect = { x = closeBtnX, y = closeBtnY, w = closeBtnW, h = closeBtnH }
end

--- 抽卡待机界面: 旋转召唤阵 + 按钮
function DrawGachaIdle(t)
    local W = DESIGN_W
    local H = DESIGN_H
    local cx = W / 2
    local circleY = H * 0.42
    local circleR = 95

    -- 召唤阵外圈: 旋转虚线光弧
    for i = 1, 12 do
        local angle = (i / 12) * math.pi * 2 + t * 0.6
        local arcLen = math.pi / 8
        local r = circleR + 8 + 3 * math.sin(t * 2 + i)
        nvgBeginPath(vg)
        nvgArc(vg, cx, circleY, r, angle, angle + arcLen, NVG_CW)
        local pulse = 0.4 + 0.6 * math.sin(t * 1.5 + i * 0.5)
        nvgStrokeColor(vg, nvgRGBA(160, 130, 80, math.floor(100 * pulse)))
        nvgStrokeWidth(vg, 1.5); nvgStroke(vg)
    end

    -- 内圈
    for i = 1, 8 do
        local angle = -(i / 8) * math.pi * 2 + t * 1.0
        local arcLen = math.pi / 6
        nvgBeginPath(vg)
        nvgArc(vg, cx, circleY, circleR - 5, angle, angle + arcLen, NVG_CW)
        local pulse = 0.3 + 0.7 * math.sin(t * 2.5 + i * 0.8)
        nvgStrokeColor(vg, nvgRGBA(120, 180, 220, math.floor(80 * pulse)))
        nvgStrokeWidth(vg, 1.0); nvgStroke(vg)
    end

    -- 中心光晕
    local glowPulse = 0.6 + 0.4 * math.sin(t * 2)
    local glow = nvgRadialGradient(vg, cx, circleY, 5, circleR * 0.8,
        nvgRGBA(180, 160, 100, math.floor(40 * glowPulse)),
        nvgRGBA(100, 120, 180, 0))
    nvgBeginPath(vg); nvgCircle(vg, cx, circleY, circleR * 0.8)
    nvgFillPaint(vg, glow); nvgFill(vg)

    -- 中心文字
    nvgFontFaceId(vg, GetMainFont())
    nvgFontSize(vg, 26)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    local textPulse = 0.6 + 0.4 * math.sin(t * 1.8)
    nvgFillColor(vg, nvgRGBA(220, 200, 140, math.floor(180 * textPulse)))
    nvgText(vg, cx, circleY, "灵 将 召 唤", nil)

    nvgFontSize(vg, 14)
    nvgFillColor(vg, nvgRGBA(190, 180, 155, 160))
    nvgText(vg, cx, circleY + 26, "消耗虎符, 召唤武灵", nil)

    -- ===========================
    -- 抽卡按钮
    -- ===========================
    local bigPull = playerInfo.jadeUnlockedBigPull
    gachaHundredBtnRect = nil  -- 每帧重置

    if bigPull then
        -- 增强模式: 3个按钮 (10连/50连/100连)
        local btnW = 160
        local btnH = 46
        local btnGap = 8
        local btnY1 = H * 0.62
        local btnY2 = btnY1 + btnH + btnGap
        local btnY3 = btnY2 + btnH + btnGap
        local unitCost = GameConfig.GACHA_COST_SINGLE

        -- 10连按钮
        local b1x = cx - btnW / 2
        nvgBeginPath(vg); nvgRoundedRect(vg, b1x, btnY1, btnW, btnH, 6)
        nvgFillColor(vg, nvgRGBA(25, 32, 50, 200)); nvgFill(vg)
        local bp1 = 0.7 + 0.3 * math.sin(t * 2)
        nvgStrokeColor(vg, nvgRGBA(180, 145, 75, math.floor(180 * bp1)))
        nvgStrokeWidth(vg, 1.5); nvgStroke(vg)
        nvgFontSize(vg, 20); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        DrawWhiteInkText(cx, btnY1 + btnH / 2 - 7, "十 连 召 唤")
        nvgFontSize(vg, 14); nvgFillColor(vg, nvgRGBA(220, 200, 150, 200))
        nvgText(vg, cx, btnY1 + btnH / 2 + 12, math.floor(unitCost * 10 * 0.9) .. " 虎符 (9折)", nil)
        gachaSingleBtnRect = { x = b1x, y = btnY1, w = btnW, h = btnH }

        -- 50连按钮
        local b2x = cx - btnW / 2
        nvgBeginPath(vg); nvgRoundedRect(vg, b2x, btnY2, btnW, btnH, 6)
        local g50 = nvgLinearGradient(vg, b2x, btnY2, b2x + btnW, btnY2 + btnH,
            nvgRGBA(30, 28, 55, 220), nvgRGBA(45, 25, 60, 220))
        nvgFillPaint(vg, g50); nvgFill(vg)
        local bp2 = 0.6 + 0.4 * math.sin(t * 2.5)
        nvgBeginPath(vg); nvgRoundedRect(vg, b2x, btnY2, btnW, btnH, 6)
        nvgStrokeColor(vg, nvgRGBA(220, 180, 80, math.floor(200 * bp2)))
        nvgStrokeWidth(vg, 1.8); nvgStroke(vg)
        nvgFontSize(vg, 20); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        DrawWhiteInkText(cx, btnY2 + btnH / 2 - 7, "五十连召唤")
        nvgFontSize(vg, 14); nvgFillColor(vg, nvgRGBA(255, 220, 130, 210))
        nvgText(vg, cx, btnY2 + btnH / 2 + 12, math.floor(unitCost * 50 * 0.9) .. " 虎符 (9折)", nil)
        gachaTenBtnRect = { x = b2x, y = btnY2, w = btnW, h = btnH }

        -- 100连按钮 (最突出)
        local b3x = cx - btnW / 2
        nvgBeginPath(vg); nvgRoundedRect(vg, b3x, btnY3, btnW, btnH, 6)
        local g100 = nvgLinearGradient(vg, b3x, btnY3, b3x + btnW, btnY3 + btnH,
            nvgRGBA(50, 20, 30, 230), nvgRGBA(60, 15, 45, 230))
        nvgFillPaint(vg, g100); nvgFill(vg)
        local bp3 = 0.5 + 0.5 * math.sin(t * 3)
        nvgBeginPath(vg); nvgRoundedRect(vg, b3x, btnY3, btnW, btnH, 6)
        nvgStrokeColor(vg, nvgRGBA(255, 180, 60, math.floor(220 * bp3)))
        nvgStrokeWidth(vg, 2.0); nvgStroke(vg)
        nvgFontSize(vg, 20); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        DrawWhiteInkText(cx, btnY3 + btnH / 2 - 7, "百 连 召 唤")
        nvgFontSize(vg, 14); nvgFillColor(vg, nvgRGBA(255, 200, 80, 230))
        nvgText(vg, cx, btnY3 + btnH / 2 + 12, math.floor(unitCost * 100 * 0.9) .. " 虎符 (9折)", nil)
        gachaHundredBtnRect = { x = b3x, y = btnY3, w = btnW, h = btnH }
    else
        -- 原始模式: 2个按钮 (单抽/十连)
        local btnW = 160
        local btnH = 56
        local btnGap = 16
        local btnY1 = H * 0.66
        local btnY2 = btnY1 + btnH + btnGap

        -- 单抽按钮
        local b1x = cx - btnW / 2
        nvgBeginPath(vg); nvgRoundedRect(vg, b1x, btnY1, btnW, btnH, 6)
        nvgFillColor(vg, nvgRGBA(25, 32, 50, 200)); nvgFill(vg)
        local borderPulse1 = 0.7 + 0.3 * math.sin(t * 2)
        nvgStrokeColor(vg, nvgRGBA(180, 145, 75, math.floor(180 * borderPulse1)))
        nvgStrokeWidth(vg, 1.5); nvgStroke(vg)
        nvgFontSize(vg, 22); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        DrawWhiteInkText(cx, btnY1 + btnH / 2 - 8, "单 抽")
        nvgFontSize(vg, 16); nvgFillColor(vg, nvgRGBA(220, 200, 150, 200))
        nvgText(vg, cx, btnY1 + btnH / 2 + 14, GameConfig.GACHA_COST_SINGLE .. " 虎符", nil)
        gachaSingleBtnRect = { x = b1x, y = btnY1, w = btnW, h = btnH }

        -- 十连按钮 (更突出)
        local b2x = cx - btnW / 2
        nvgBeginPath(vg); nvgRoundedRect(vg, b2x, btnY2, btnW, btnH, 6)
        local tenGrad = nvgLinearGradient(vg, b2x, btnY2, b2x + btnW, btnY2 + btnH,
            nvgRGBA(30, 28, 55, 220), nvgRGBA(45, 25, 60, 220))
        nvgFillPaint(vg, tenGrad); nvgFill(vg)
        local borderPulse2 = 0.6 + 0.4 * math.sin(t * 2.5)
        nvgBeginPath(vg); nvgRoundedRect(vg, b2x, btnY2, btnW, btnH, 6)
        nvgStrokeColor(vg, nvgRGBA(220, 180, 80, math.floor(200 * borderPulse2)))
        nvgStrokeWidth(vg, 1.8); nvgStroke(vg)
        nvgFontSize(vg, 22); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        DrawWhiteInkText(cx, btnY2 + btnH / 2 - 8, "十 连 召 唤")
        nvgFontSize(vg, 16); nvgFillColor(vg, nvgRGBA(255, 220, 130, 210))
        nvgText(vg, cx, btnY2 + btnH / 2 + 14, GameConfig.GACHA_COST_TEN .. " 虎符 (9折)", nil)
        gachaTenBtnRect = { x = b2x, y = btnY2, w = btnW, h = btnH }
    end

    -- 计算最后一个按钮底部Y (兼容增强模式3按钮)
    local lastBtnBottom = gachaHundredBtnRect and (gachaHundredBtnRect.y + gachaHundredBtnRect.h) or (gachaTenBtnRect.y + gachaTenBtnRect.h)

    -- 拥有武灵提示
    local ownedCount = 0
    for _, h in pairs(playerHeroes) do
        if h.owned then ownedCount = ownedCount + 1 end
    end
    nvgFontSize(vg, 14)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    nvgFillColor(vg, nvgRGBA(200, 195, 180, 180))
    nvgText(vg, cx, lastBtnBottom + 18, "已拥有 " .. ownedCount .. "/" .. #HERO_CARDS .. " 位武灵", nil)

    -- 保底进度
    local pityRemain = GameConfig.PITY_SSR_COUNT - gachaState.pityCounter
    local pityText = "距保底: " .. pityRemain .. " 抽 | 保底必出整卡"
    nvgFontSize(vg, 13)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    nvgFillColor(vg, nvgRGBA(180, 170, 140, 160))
    nvgText(vg, cx, lastBtnBottom + 38, pityText, nil)

    -- 残片仓库按钮（左下角）
    local bottomBtnY = lastBtnBottom + 8
    local shopBtnW = 90
    local shopBtnH = 30
    local shopBtnX = 12
    nvgBeginPath(vg); nvgRoundedRect(vg, shopBtnX, bottomBtnY, shopBtnW, shopBtnH, 6)
    nvgFillColor(vg, nvgRGBA(35, 30, 50, 210)); nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(180, 145, 75, 160)); nvgStrokeWidth(vg, 1.2); nvgStroke(vg)
    nvgFontSize(vg, 14)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(shopBtnX + shopBtnW / 2, bottomBtnY + shopBtnH / 2, "残片仓库")
    -- 可合成红点
    local heroComposeN = 0
    for ci, cnt in pairs(heroFragments) do
        local cd = HERO_CARDS[ci]
        if cd and cnt >= (HERO_FRAG_EXCHANGE[cd.quality] or 20) then heroComposeN = heroComposeN + 1 end
    end
    local skillComposeN = 0
    for _, cnt in pairs(skillFragments) do
        if cnt >= SKILL_FRAG_EXCHANGE then skillComposeN = skillComposeN + 1 end
    end
    local totalCompN = heroComposeN + skillComposeN
    if totalCompN > 0 then
        local dotR = 7
        local dotX = shopBtnX + shopBtnW - 4
        local dotY = bottomBtnY + 4
        nvgBeginPath(vg); nvgCircle(vg, dotX, dotY, dotR)
        nvgFillColor(vg, nvgRGBA(255, 60, 60, 230)); nvgFill(vg)
        nvgFontSize(vg, 10)
        nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        DrawWhiteInkText(dotX, dotY, tostring(totalCompN))
    end
    gachaFragShopBtnRect = { x = shopBtnX, y = bottomBtnY, w = shopBtnW, h = shopBtnH }

    -- "?" 概率规则按钮 (右下角)
    local qBtnSize = 30
    local qBtnX = W - qBtnSize - 12
    local qBtnY = bottomBtnY
    nvgBeginPath(vg); nvgCircle(vg, qBtnX + qBtnSize / 2, qBtnY + qBtnSize / 2, qBtnSize / 2)
    nvgFillColor(vg, nvgRGBA(40, 45, 65, 200)); nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(180, 160, 100, 160)); nvgStrokeWidth(vg, 1.2); nvgStroke(vg)
    nvgFontSize(vg, 29)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(qBtnX + qBtnSize / 2, qBtnY + qBtnSize / 2, "?")
    gachaRulesBtnRect = { x = qBtnX, y = qBtnY, w = qBtnSize, h = qBtnSize }
end

