--- 限定池待机界面
function DrawLimitedGachaIdle(t)
    local W = DESIGN_W
    local H = DESIGN_H
    local cx = W / 2
    local circleY = H * 0.42
    local circleR = 95

    -- 召唤阵外圈: 红色旋转弧线 (区别于普通池的金色)
    for i = 1, 12 do
        local angle = (i / 12) * math.pi * 2 + t * 0.8
        local arcLen = math.pi / 8
        local r = circleR + 8 + 3 * math.sin(t * 2 + i)
        nvgBeginPath(vg)
        nvgArc(vg, cx, circleY, r, angle, angle + arcLen, NVG_CW)
        local pulse = 0.4 + 0.6 * math.sin(t * 1.5 + i * 0.5)
        nvgStrokeColor(vg, nvgRGBA(255, 80, 120, math.floor(100 * pulse)))
        nvgStrokeWidth(vg, 1.5); nvgStroke(vg)
    end

    -- 内圈: 暗红光弧
    for i = 1, 8 do
        local angle = -(i / 8) * math.pi * 2 + t * 1.2
        local arcLen = math.pi / 6
        nvgBeginPath(vg)
        nvgArc(vg, cx, circleY, circleR - 5, angle, angle + arcLen, NVG_CW)
        local pulse = 0.3 + 0.7 * math.sin(t * 2.5 + i * 0.8)
        nvgStrokeColor(vg, nvgRGBA(255, 100, 140, math.floor(80 * pulse)))
        nvgStrokeWidth(vg, 1.0); nvgStroke(vg)
    end

    -- 中心光晕 (红粉色)
    local glowPulse = 0.6 + 0.4 * math.sin(t * 2)
    local glow = nvgRadialGradient(vg, cx, circleY, 5, circleR * 0.8,
        nvgRGBA(255, 80, 120, math.floor(40 * glowPulse)),
        nvgRGBA(180, 60, 100, 0))
    nvgBeginPath(vg); nvgCircle(vg, cx, circleY, circleR * 0.8)
    nvgFillPaint(vg, glow); nvgFill(vg)

    -- 中心文字
    nvgFontFaceId(vg, GetMainFont())
    nvgFontSize(vg, 26)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    local textPulse = 0.6 + 0.4 * math.sin(t * 1.8)
    nvgFillColor(vg, nvgRGBA(255, 120, 150, math.floor(200 * textPulse)))
    nvgText(vg, cx, circleY - 5, "限 定 召 唤", nil)

    nvgFontSize(vg, 14)
    nvgFillColor(vg, nvgRGBA(255, 180, 200, 160))
    nvgText(vg, cx, circleY + 28, "仅出碎片 · 限定SSR唯一来源", nil)

    -- 限定武灵展示 (小图标)
    local limitedPool = {}
    for idx, card in ipairs(HERO_CARDS) do
        if card.quality == QUALITY.LIMITED then
            table.insert(limitedPool, { idx = idx, card = card })
        end
    end
    if #limitedPool > 0 then
        local iconSize = 32
        local iconGap = 8
        local totalIconW = #limitedPool * iconSize + (#limitedPool - 1) * iconGap
        local iconStartX = cx - totalIconW / 2
        local iconY = circleY + 50
        nvgFontSize(vg, 13)
        nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_TOP)
        for li, lh in ipairs(limitedPool) do
            local ix = iconStartX + (li - 1) * (iconSize + iconGap)
            -- 红粉边框小卡
            nvgBeginPath(vg); nvgRoundedRect(vg, ix, iconY, iconSize, iconSize, 4)
            nvgFillColor(vg, nvgRGBA(40, 20, 30, 200)); nvgFill(vg)
            local bPulse = 0.6 + 0.4 * math.sin(t * 2 + li)
            nvgStrokeColor(vg, nvgRGBA(255, 80, 120, math.floor(180 * bPulse)))
            nvgStrokeWidth(vg, 1.5); nvgStroke(vg)
            -- 名字首字
            nvgFillColor(vg, nvgRGBA(255, 200, 210, 220))
            local firstName = string.sub(lh.card.name, 1, 3)  -- UTF-8 首字
            nvgText(vg, ix + iconSize / 2, iconY + iconSize / 2 - 7, firstName, nil)
        end
    end

    -- 抽卡按钮
    local bigPull = playerInfo.jadeUnlockedBigPull
    gachaHundredBtnRect = nil

    if bigPull then
        -- 增强模式: 3个按钮 (10连/50连/100连) 红粉色调
        local btnW = 160
        local btnH = 46
        local btnGap = 8
        local btnY1 = H * 0.62
        local btnY2 = btnY1 + btnH + btnGap
        local btnY3 = btnY2 + btnH + btnGap
        local unitCost = LIMITED_GACHA_COST

        -- 10连
        local b1x = cx - btnW / 2
        nvgBeginPath(vg); nvgRoundedRect(vg, b1x, btnY1, btnW, btnH, 6)
        nvgFillColor(vg, nvgRGBA(35, 18, 28, 200)); nvgFill(vg)
        local bp1 = 0.7 + 0.3 * math.sin(t * 2)
        nvgStrokeColor(vg, nvgRGBA(255, 80, 120, math.floor(180 * bp1)))
        nvgStrokeWidth(vg, 1.5); nvgStroke(vg)
        nvgFontSize(vg, 20); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        DrawWhiteInkText(cx, btnY1 + btnH / 2 - 7, "十 连 召 唤")
        nvgFontSize(vg, 14)
        DrawWhiteInkText(cx, btnY1 + btnH / 2 + 12, math.floor(unitCost * 10 * 0.9) .. " 虎符 (9折)")
        gachaSingleBtnRect = { x = b1x, y = btnY1, w = btnW, h = btnH }

        -- 50连
        local b2x = cx - btnW / 2
        nvgBeginPath(vg); nvgRoundedRect(vg, b2x, btnY2, btnW, btnH, 6)
        local g50 = nvgLinearGradient(vg, b2x, btnY2, b2x + btnW, btnY2 + btnH,
            nvgRGBA(55, 20, 35, 220), nvgRGBA(60, 18, 50, 220))
        nvgFillPaint(vg, g50); nvgFill(vg)
        local bp2 = 0.6 + 0.4 * math.sin(t * 2.5)
        nvgBeginPath(vg); nvgRoundedRect(vg, b2x, btnY2, btnW, btnH, 6)
        nvgStrokeColor(vg, nvgRGBA(255, 100, 140, math.floor(200 * bp2)))
        nvgStrokeWidth(vg, 1.8); nvgStroke(vg)
        nvgFontSize(vg, 20); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        DrawWhiteInkText(cx, btnY2 + btnH / 2 - 7, "五十连召唤")
        nvgFontSize(vg, 14)
        DrawWhiteInkText(cx, btnY2 + btnH / 2 + 12, math.floor(unitCost * 50 * 0.9) .. " 虎符 (9折)")
        gachaTenBtnRect = { x = b2x, y = btnY2, w = btnW, h = btnH }

        -- 100连 (最突出)
        local b3x = cx - btnW / 2
        nvgBeginPath(vg); nvgRoundedRect(vg, b3x, btnY3, btnW, btnH, 6)
        local g100 = nvgLinearGradient(vg, b3x, btnY3, b3x + btnW, btnY3 + btnH,
            nvgRGBA(70, 15, 30, 230), nvgRGBA(80, 10, 50, 230))
        nvgFillPaint(vg, g100); nvgFill(vg)
        local bp3 = 0.5 + 0.5 * math.sin(t * 3)
        nvgBeginPath(vg); nvgRoundedRect(vg, b3x, btnY3, btnW, btnH, 6)
        nvgStrokeColor(vg, nvgRGBA(255, 140, 100, math.floor(220 * bp3)))
        nvgStrokeWidth(vg, 2.0); nvgStroke(vg)
        nvgFontSize(vg, 20); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        DrawWhiteInkText(cx, btnY3 + btnH / 2 - 7, "百 连 召 唤")
        nvgFontSize(vg, 14)
        DrawWhiteInkText(cx, btnY3 + btnH / 2 + 12, math.floor(unitCost * 100 * 0.9) .. " 虎符 (9折)")
        gachaHundredBtnRect = { x = b3x, y = btnY3, w = btnW, h = btnH }
    else
        -- 原始模式: 2个按钮 (单抽/十连)
        local btnW = 160
        local btnH = 56
        local btnGap = 16
        local btnY1 = H * 0.66
        local btnY2 = btnY1 + btnH + btnGap

        -- 单抽按钮 (红粉色调)
        local b1x = cx - btnW / 2
        nvgBeginPath(vg); nvgRoundedRect(vg, b1x, btnY1, btnW, btnH, 6)
        nvgFillColor(vg, nvgRGBA(35, 18, 28, 200)); nvgFill(vg)
        local borderPulse1 = 0.7 + 0.3 * math.sin(t * 2)
        nvgStrokeColor(vg, nvgRGBA(255, 80, 120, math.floor(180 * borderPulse1)))
        nvgStrokeWidth(vg, 1.5); nvgStroke(vg)
        nvgFontSize(vg, 22); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        DrawWhiteInkText(cx, btnY1 + btnH / 2 - 10, "单 抽")
        nvgFontSize(vg, 16)
        DrawWhiteInkText(cx, btnY1 + btnH / 2 + 20, LIMITED_GACHA_COST .. " 虎符")
        gachaSingleBtnRect = { x = b1x, y = btnY1, w = btnW, h = btnH }

        -- 十连按钮 (更突出, 红紫渐变)
        local b2x = cx - btnW / 2
        nvgBeginPath(vg); nvgRoundedRect(vg, b2x, btnY2, btnW, btnH, 6)
        local tenGrad = nvgLinearGradient(vg, b2x, btnY2, b2x + btnW, btnY2 + btnH,
            nvgRGBA(55, 20, 35, 220), nvgRGBA(60, 18, 50, 220))
        nvgFillPaint(vg, tenGrad); nvgFill(vg)
        local borderPulse2 = 0.6 + 0.4 * math.sin(t * 2.5)
        nvgBeginPath(vg); nvgRoundedRect(vg, b2x, btnY2, btnW, btnH, 6)
        nvgStrokeColor(vg, nvgRGBA(255, 100, 140, math.floor(200 * borderPulse2)))
        nvgStrokeWidth(vg, 1.8); nvgStroke(vg)
        nvgFontSize(vg, 22); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        DrawWhiteInkText(cx, btnY2 + btnH / 2 - 10, "十 连 召 唤")
        nvgFontSize(vg, 16)
        DrawWhiteInkText(cx, btnY2 + btnH / 2 + 20, LIMITED_GACHA_TEN_COST .. " 虎符 (9折)")
        gachaTenBtnRect = { x = b2x, y = btnY2, w = btnW, h = btnH }
    end

    -- 计算最后一个按钮底部Y (兼容增强模式3按钮)
    local lastBtnBottom = gachaHundredBtnRect and (gachaHundredBtnRect.y + gachaHundredBtnRect.h) or (gachaTenBtnRect.y + gachaTenBtnRect.h)

    -- 保底进度
    local pityRemain = LIMITED_PITY_FRAG_COUNT - gachaState.limitedPityCounter
    local pityText = "距碎片保底: " .. pityRemain .. " 抽 | " .. LIMITED_FRAG_GUARANTEE_MIN .. "~" .. LIMITED_FRAG_GUARANTEE_MAX .. "碎片"
    nvgFontSize(vg, 14)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(cx, lastBtnBottom + 20, pityText)

    nvgFontSize(vg, 13)
    nvgFillColor(vg, nvgRGBA(255, 150, 170, 120))
    nvgText(vg, cx, lastBtnBottom + 46, "无整卡保底 · 仅产出碎片", nil)

    -- 残片仓库按钮（左下角）
    local bottomBtnY = lastBtnBottom + 8
    local shopBtnW = 90
    local shopBtnH = 30
    local shopBtnX = 12
    nvgBeginPath(vg); nvgRoundedRect(vg, shopBtnX, bottomBtnY, shopBtnW, shopBtnH, 6)
    nvgFillColor(vg, nvgRGBA(35, 30, 50, 210)); nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(255, 80, 120, 160)); nvgStrokeWidth(vg, 1.2); nvgStroke(vg)
    nvgFontSize(vg, 14)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(shopBtnX + shopBtnW / 2, bottomBtnY + shopBtnH / 2, "残片仓库")
    gachaFragShopBtnRect = { x = shopBtnX, y = bottomBtnY, w = shopBtnW, h = shopBtnH }

    -- "?" 概率规则按钮 (右下角)
    local qBtnSize = 30
    local qBtnX = W - qBtnSize - 12
    local qBtnY = bottomBtnY
    nvgBeginPath(vg); nvgCircle(vg, qBtnX + qBtnSize / 2, qBtnY + qBtnSize / 2, qBtnSize / 2)
    nvgFillColor(vg, nvgRGBA(40, 20, 30, 200)); nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(255, 100, 120, 160)); nvgStrokeWidth(vg, 1.2); nvgStroke(vg)
    nvgFontSize(vg, 29)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(qBtnX + qBtnSize / 2, qBtnY + qBtnSize / 2, "?")
    gachaRulesBtnRect = { x = qBtnX, y = qBtnY, w = qBtnSize, h = qBtnSize }
end

--- 限定池抽取结果展示
function DrawLimitedGachaResults()
    local W = DESIGN_W
    local H = DESIGN_H
    local cx = W / 2
    local results = gachaState.limitedResults
    if not results or #results == 0 then return end
    local count = #results
    local t = gachaState.animTimer or 0

    -- 检查是否有限定SSR
    local hasLimitedSSR = false
    for _, r in ipairs(results) do
        local c = HERO_CARDS[r.cardIdx]
        if c and c.quality == QUALITY.LIMITED then hasLimitedSSR = true; break end
    end

    -- === 全屏遮罩 ===
    nvgBeginPath(vg)
    nvgRect(vg, 0, 0, W, H)
    nvgFillColor(vg, nvgRGBA(0, 0, 0, 180))
    nvgFill(vg)

    -- === 限定SSR出货特效: 全屏闪光 + 粒子 ===
    if hasLimitedSSR then
        -- 全屏红金色脉冲光
        local flashA = math.max(0, 80 * math.sin(t * 4))
        nvgBeginPath(vg); nvgRect(vg, 0, 0, W, H)
        local flashGrad = nvgRadialGradient(vg, cx, H * 0.4, 10, W * 0.9,
            nvgRGBA(255, 100, 60, math.floor(flashA)),
            nvgRGBA(255, 40, 80, 0))
        nvgFillPaint(vg, flashGrad); nvgFill(vg)

        -- 旋转光线
        for i = 1, 12 do
            local angle = (i / 12) * math.pi * 2 + t * 0.6
            local len = 260 + 40 * math.sin(t * 3 + i)
            local ex = cx + math.cos(angle) * len
            local ey = H * 0.4 + math.sin(angle) * len
            local rayA = 0.3 + 0.7 * math.sin(t * 2.5 + i * 0.5)
            nvgBeginPath(vg)
            nvgMoveTo(vg, cx, H * 0.4)
            nvgLineTo(vg, ex, ey)
            nvgStrokeColor(vg, nvgRGBA(255, 180, 80, math.floor(40 * rayA)))
            nvgStrokeWidth(vg, 2); nvgStroke(vg)
        end

        -- 上升粒子
        for i = 1, 20 do
            local px = cx + math.sin(t * 1.3 + i * 1.7) * W * 0.4
            local py = H - ((t * 60 + i * 47) % (H + 40))
            local pSize = 2 + math.sin(t * 3 + i) * 1.5
            local pA = 0.4 + 0.6 * math.sin(t * 2 + i * 0.8)
            nvgBeginPath(vg); nvgCircle(vg, px, py, pSize)
            if i % 3 == 0 then
                nvgFillColor(vg, nvgRGBA(255, 80, 120, math.floor(180 * pA)))
            else
                nvgFillColor(vg, nvgRGBA(255, 200, 80, math.floor(160 * pA)))
            end
            nvgFill(vg)
        end
    end

    nvgFontFaceId(vg, GetMainFont())

    -- === 标题 ===
    nvgFontSize(vg, 33)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    if hasLimitedSSR then
        -- 限定SSR: 金色闪烁标题
        local titlePulse = 0.7 + 0.3 * math.sin(t * 3)
        nvgFillColor(vg, nvgRGBA(255, 200, 80, math.floor(255 * titlePulse)))
        nvgText(vg, cx, 65, "限定召唤结果", nil)
        -- 标题光晕
        nvgFillColor(vg, nvgRGBA(255, 120, 60, math.floor(60 * titlePulse)))
        nvgText(vg, cx, 65, "限定召唤结果", nil)
    else
        DrawWhiteInkText(cx, 65, "限定召唤结果")
    end

    -- === 卡牌展示 (与武灵召唤一致) ===
    if count == 1 then
        -- 单抽: 大卡居中
        local cardW = 120
        local cardH = cardW / CARD_RATIO
        local cardX = cx - cardW / 2
        local cardY = H * 0.25
        local r = results[1]
        local card = HERO_CARDS[r.cardIdx]

        -- 限定SSR出货: 额外大光晕
        if card and card.quality == QUALITY.LIMITED then
            local bigGlow = nvgRadialGradient(vg, cx, cardY + cardH / 2, 10, cardW * 1.8,
                nvgRGBA(255, 80, 120, math.floor(100 * (0.5 + 0.5 * math.sin(t * 2.5)))),
                nvgRGBA(255, 40, 80, 0))
            nvgBeginPath(vg); nvgCircle(vg, cx, cardY + cardH / 2, cardW * 1.8)
            nvgFillPaint(vg, bigGlow); nvgFill(vg)
        end

        DrawInventoryCard(cardX, cardY, cardW, cardH, card, 0, false)

        local tagY = cardY + cardH + 12
        nvgFontSize(vg, 30)
        nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)

        -- 碎片信息
        local isLimited = card and card.quality == QUALITY.LIMITED
        local qc = QUALITY_COLORS[card.quality] or { 200, 200, 200 }
        if isLimited then
            nvgFillColor(vg, nvgRGBA(255, 120, 150, 240))
        else
            nvgFillColor(vg, nvgRGBA(qc[1], qc[2], qc[3], 240))
        end
        nvgText(vg, cx, tagY, card.name .. " 碎片 x" .. r.fragCount, nil)

        -- 进度
        local need = HERO_FRAG_EXCHANGE[card.quality] or 20
        local total = r.totalFrags or 0
        nvgFontSize(vg, 24)
        nvgFillColor(vg, nvgRGBA(200, 200, 200, 200))
        nvgText(vg, cx, tagY + 28, "累计 " .. total .. "/" .. need, nil)

        -- 保底标记
        if r.isPity then
            nvgFontSize(vg, 18)
            nvgFillColor(vg, nvgRGBA(255, 80, 120, 220))
            nvgText(vg, cx, tagY + 56, "保底出货!", nil)
        end
    else
        -- 按品质降序排序（高品质排前面，限定SSR最优先）
        table.sort(results, function(a, b)
            local qa = HERO_CARDS[a.cardIdx] and HERO_CARDS[a.cardIdx].quality or 0
            local qb = HERO_CARDS[b.cardIdx] and HERO_CARDS[b.cardIdx].quality or 0
            return qa > qb
        end)
        -- 十连: 5列×2行 卡牌网格
        local cols = 5
        local cardW = 80
        local cardH = cardW / CARD_RATIO
        local gap = 8
        local gridW = cols * cardW + (cols - 1) * gap
        local startX = cx - gridW / 2
        local startY = 85

        for i, r in ipairs(results) do
            local col = ((i - 1) % cols)
            local row = math.floor((i - 1) / cols)
            local x = startX + col * (cardW + gap)
            local y = startY + row * (cardH + 28 + gap)
            local card = HERO_CARDS[r.cardIdx]

            -- 限定SSR: 卡牌额外光晕
            if card and card.quality == QUALITY.LIMITED then
                local gPulse = 0.5 + 0.5 * math.sin(t * 3 + i)
                local glow = nvgRadialGradient(vg, x + cardW / 2, y + cardH / 2, 5, cardW * 0.9,
                    nvgRGBA(255, 80, 120, math.floor(80 * gPulse)),
                    nvgRGBA(255, 40, 80, 0))
                nvgBeginPath(vg); nvgCircle(vg, x + cardW / 2, y + cardH / 2, cardW * 0.9)
                nvgFillPaint(vg, glow); nvgFill(vg)
            end

            DrawInventoryCard(x, y, cardW, cardH, card, 0, false)

            nvgFontSize(vg, 14)
            nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_TOP)

            -- 碎片数量
            local isLimited = card and card.quality == QUALITY.LIMITED
            if isLimited then
                nvgFillColor(vg, nvgRGBA(255, 120, 150, 240))
                nvgText(vg, x + cardW / 2, y + cardH + 2, "碎片x" .. r.fragCount, nil)
            else
                local qc = QUALITY_COLORS[card.quality] or { 200, 200, 200 }
                nvgFillColor(vg, nvgRGBA(qc[1], qc[2], qc[3], 220))
                nvgText(vg, x + cardW / 2, y + cardH + 2, "碎片x" .. r.fragCount, nil)
            end

            -- 累计碎片小字
            local need = HERO_FRAG_EXCHANGE[card.quality] or 20
            local total = r.totalFrags or 0
            nvgFontSize(vg, 11)
            nvgFillColor(vg, nvgRGBA(200, 200, 200, 160))
            nvgText(vg, x + cardW / 2, y + cardH + 16, total .. "/" .. need, nil)

            -- 保底标记
            if r.isPity then
                nvgFontSize(vg, 11)
                nvgFillColor(vg, nvgRGBA(255, 80, 120, 220))
                nvgTextAlign(vg, NVG_ALIGN_RIGHT + NVG_ALIGN_TOP)
                nvgText(vg, x + cardW - 2, y + 2, "保底", nil)
            end
        end
    end

    -- === 确认按钮 ===
    local confirmW = 140
    local confirmH = 44
    local confirmX = cx - confirmW / 2
    local confirmY = H * 0.88
    nvgBeginPath(vg); nvgRoundedRect(vg, confirmX, confirmY, confirmW, confirmH, 6)
    nvgFillColor(vg, nvgRGBA(255, 60, 100, 200)); nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(255, 160, 180, 160)); nvgStrokeWidth(vg, 1.2); nvgStroke(vg)
    nvgFontSize(vg, 26)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(cx, confirmY + confirmH / 2, "确 认")
    gachaConfirmBtnRect = { x = confirmX, y = confirmY, w = confirmW, h = confirmH }
end

--- 限定池规则弹窗
function DrawLimitedGachaRulesPopup()
    local W = DESIGN_W
    local H = DESIGN_H
    local cx = W / 2

    -- 半透明遮罩
    nvgBeginPath(vg); nvgRect(vg, 0, 0, W, H)
    nvgFillColor(vg, nvgRGBA(5, 5, 12, 110)); nvgFill(vg)

    -- 弹窗面板
    local panelW = W * 0.82
    local panelH = 680
    local panelX = cx - panelW / 2
    local panelY = H / 2 - panelH / 2 - 20

    local panelGrad = nvgLinearGradient(vg, panelX, panelY, panelX, panelY + panelH,
        nvgRGBA(50, 28, 38, 240), nvgRGBA(35, 20, 30, 245))
    nvgBeginPath(vg); nvgRoundedRect(vg, panelX, panelY, panelW, panelH, 10)
    nvgFillPaint(vg, panelGrad); nvgFill(vg)

    nvgBeginPath(vg); nvgRoundedRect(vg, panelX, panelY, panelW, panelH, 10)
    nvgStrokeColor(vg, nvgRGBA(255, 80, 120, 160)); nvgStrokeWidth(vg, 1.5); nvgStroke(vg)

    nvgFontFaceId(vg, GetMainFont())

    -- 标题
    local titleY = panelY + 28
    nvgFontSize(vg, 35)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    nvgFillColor(vg, nvgRGBA(255, 120, 150, 240))
    nvgText(vg, cx, titleY, "限定召唤规则", nil)

    -- 分隔线
    nvgBeginPath(vg)
    nvgMoveTo(vg, panelX + 20, titleY + 18)
    nvgLineTo(vg, panelX + panelW - 20, titleY + 18)
    nvgStrokeColor(vg, nvgRGBA(255, 80, 120, 60)); nvgStrokeWidth(vg, 1); nvgStroke(vg)

    local leftX = panelX + 20
    local rightX = panelX + panelW - 20
    local lineH = 30
    local startY = titleY + 36

    -- 核心规则
    nvgFontSize(vg, 27)
    nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(leftX, startY, "核心规则")
    startY = startY + lineH * 0.8

    local function DrawRuleLine(text)
        nvgFontSize(vg, 14.5)
        nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)
        DrawWhiteInkText(leftX + 10, startY, text)
        startY = startY + lineH * 0.7
    end

    DrawRuleLine("· 限定池仅产出碎片, 无整卡产出")
    DrawRuleLine("· 限定SSR武灵碎片唯一来源")
    DrawRuleLine("· 每 " .. LIMITED_PITY_FRAG_COUNT .. " 抽保底: 必出限定SSR碎片x" .. LIMITED_FRAG_GUARANTEE_MIN .. "~" .. LIMITED_FRAG_GUARANTEE_MAX)
    DrawRuleLine("· 单抽 " .. LIMITED_GACHA_COST .. " 虎符 / 十连 " .. LIMITED_GACHA_TEN_COST .. " 虎符(9折)")

    -- 分隔线
    startY = startY + 6
    nvgBeginPath(vg)
    nvgMoveTo(vg, panelX + 20, startY)
    nvgLineTo(vg, panelX + panelW - 20, startY)
    nvgStrokeColor(vg, nvgRGBA(255, 80, 120, 40)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
    startY = startY + 14

    -- 概率表
    nvgFontSize(vg, 27)
    nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(leftX, startY, "碎片品质概率")
    startY = startY + lineH * 0.8

    local probInfo = {
        { tag = "R",   name = "地品碎片", pct = LIMITED_DRAW_WEIGHTS[2], color = QUALITY_COLORS[2] },
        { tag = "SR",  name = "天品碎片", pct = LIMITED_DRAW_WEIGHTS[3], color = QUALITY_COLORS[3] },
        { tag = "SSR", name = "神品碎片", pct = LIMITED_DRAW_WEIGHTS[4], color = QUALITY_COLORS[4] },
        { tag = "限定", name = "限定碎片", pct = LIMITED_DRAW_WEIGHTS[5], color = QUALITY_COLORS[5] },
    }
    local totalProb = 0
    for _, p in ipairs(probInfo) do totalProb = totalProb + p.pct end

    for _, pi in ipairs(probInfo) do
        local pic = pi.color
        nvgFontSize(vg, 14.5)
        nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)
        nvgFillColor(vg, nvgRGBA(pic[1], pic[2], pic[3], 200))
        nvgText(vg, leftX + 4, startY, pi.tag .. " " .. pi.name, nil)
        nvgTextAlign(vg, NVG_ALIGN_RIGHT + NVG_ALIGN_MIDDLE)
        local pctText = string.format("%.0f%%", pi.pct / totalProb * 100)
        DrawWhiteInkText(rightX, startY, pctText)
        startY = startY + lineH * 0.7
    end

    -- 分隔线
    startY = startY + 6
    nvgBeginPath(vg)
    nvgMoveTo(vg, panelX + 20, startY)
    nvgLineTo(vg, panelX + panelW - 20, startY)
    nvgStrokeColor(vg, nvgRGBA(255, 80, 120, 40)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
    startY = startY + 14

    -- 保底进度
    nvgFontSize(vg, 27)
    nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(leftX, startY, "保底进度")
    startY = startY + lineH * 0.8

    local remaining = LIMITED_PITY_FRAG_COUNT - gachaState.limitedPityCounter
    nvgFontSize(vg, 14.5)
    nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(leftX + 4, startY, "距离保底还需")
    nvgTextAlign(vg, NVG_ALIGN_RIGHT + NVG_ALIGN_MIDDLE)
    nvgFillColor(vg, nvgRGBA(255, 120, 150, 240))
    nvgText(vg, rightX, startY, remaining .. " 抽", nil)
    startY = startY + lineH * 0.7

    nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(leftX + 4, startY, "已累计抽取")
    nvgTextAlign(vg, NVG_ALIGN_RIGHT + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(rightX, startY, gachaState.limitedPityCounter .. " 抽")
    startY = startY + lineH * 0.7

    -- 残片合成所需
    startY = startY + 8
    nvgFontSize(vg, 27)
    nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(leftX, startY, "限定武灵合成所需")
    startY = startY + lineH * 0.8

    nvgFontSize(vg, 14.5)
    nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)
    local lc = QUALITY_COLORS[5]
    nvgFillColor(vg, nvgRGBA(lc[1], lc[2], lc[3], 200))
    nvgText(vg, leftX + 4, startY, "限定SSR 品质", nil)
    nvgTextAlign(vg, NVG_ALIGN_RIGHT + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(rightX, startY, HERO_FRAG_EXCHANGE[5] .. " 残片")

    -- 关闭按钮
    local closeBtnW = 100
    local closeBtnH = 36
    local closeBtnX = cx - closeBtnW / 2
    local closeBtnY = panelY + panelH - closeBtnH - 14
    nvgBeginPath(vg); nvgRoundedRect(vg, closeBtnX, closeBtnY, closeBtnW, closeBtnH, 6)
    nvgFillColor(vg, nvgRGBA(255, 60, 100, 180)); nvgFill(vg)
    nvgFontSize(vg, 24)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(cx, closeBtnY + closeBtnH / 2, "关 闭")
    gachaRulesCloseBtnRect = { x = closeBtnX, y = closeBtnY, w = closeBtnW, h = closeBtnH }
end

--- 抽卡召唤动画
function DrawGachaPullAnimation(t)
    local W = DESIGN_W
    local H = DESIGN_H
    local cx = W / 2
    local cy = H * 0.40
    local progress = math.min(1, gachaState.pullTimer / 1.2)

    -- 扩大的光圈
    local maxR = 120
    local r = maxR * progress
    local glow = nvgRadialGradient(vg, cx, cy, r * 0.3, r,
        nvgRGBA(255, 230, 120, math.floor(120 * (1 - progress * 0.5))),
        nvgRGBA(180, 140, 60, 0))
    nvgBeginPath(vg); nvgCircle(vg, cx, cy, r)
    nvgFillPaint(vg, glow); nvgFill(vg)

    -- 旋转光线
    local lineCount = gachaState.pullCount == 10 and 20 or 8
    for i = 1, lineCount do
        local angle = (i / lineCount) * math.pi * 2 + t * 4
        local len = 30 + 80 * progress
        local sx = cx + math.cos(angle) * 10
        local sy = cy + math.sin(angle) * 10
        local ex = cx + math.cos(angle) * len
        local ey = cy + math.sin(angle) * len
        nvgBeginPath(vg)
        nvgMoveTo(vg, sx, sy); nvgLineTo(vg, ex, ey)
        local la = math.floor(180 * (1 - progress * 0.3))
        nvgStrokeColor(vg, nvgRGBA(255, 220, 100, la))
        nvgStrokeWidth(vg, 1.5); nvgStroke(vg)
    end

    -- 中心闪光
    local flashA = math.floor(255 * math.max(0, progress - 0.6) / 0.4)
    if flashA > 0 then
        nvgBeginPath(vg); nvgRect(vg, 0, 0, W, H)
        nvgFillColor(vg, nvgRGBA(255, 245, 220, flashA)); nvgFill(vg)
    end

    -- 提示文字
    nvgFontFaceId(vg, GetMainFont())
    nvgFontSize(vg, 30)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(cx, H * 0.72, "点击跳过")
end

--- 抽卡结果展示
function DrawGachaResults()
    local W = DESIGN_W
    local H = DESIGN_H
    local cx = W / 2
    local results = gachaState.results
    local count = #results

    -- 半透明全屏遮罩
    nvgBeginPath(vg)
    nvgRect(vg, 0, 0, W, H)
    nvgFillColor(vg, nvgRGBA(0, 0, 0, 160))
    nvgFill(vg)

    nvgFontFaceId(vg, GetMainFont())

    -- 标题
    nvgFontSize(vg, 33)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(cx, 65, count > 10 and ("召唤结果 ×" .. count) or "召唤结果")

    if count == 0 then return end

    -- 品质颜色
    local QCOLORS = {
        [1] = { 180, 180, 170 }, -- N
        [2] = { 100, 200, 120 }, -- R
        [3] = { 80, 160, 255 },  -- SR
        [4] = { 255, 200, 60 },  -- SSR
    }

    if count == 1 then
        -- 单抽: 大卡居中显示
        local cardW = 120
        local cardH = cardW / CARD_RATIO
        local cardX = cx - cardW / 2
        local cardY = H * 0.25
        local r = results[1]
        local card = HERO_CARDS[r.cardIdx]
        DrawInventoryCard(cardX, cardY, cardW, cardH, card, r.constellation or 0, false)

        local tagY = cardY + cardH + 12
        nvgFontSize(vg, 30)
        nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)

        if r.isFullCard then
            -- 整卡结果
            if r.isNew then
                nvgFillColor(vg, nvgRGBA(120, 255, 160, 240))
                nvgText(vg, cx, tagY, "新! " .. card.name, nil)
            elseif r.jadeRefund and r.jadeRefund > 0 then
                nvgFillColor(vg, nvgRGBA(255, 215, 0, 240))
                nvgText(vg, cx, tagY, card.name .. " 满命格", nil)
                nvgFontSize(vg, 27)
                nvgText(vg, cx, tagY + 24, "返还 " .. r.jadeRefund .. " 虎符", nil)
            else
                local cc = GameConfig.CONSTELLATION_COLORS[r.constellation] or { 180, 175, 165 }
                nvgFillColor(vg, nvgRGBA(cc[1], cc[2], cc[3], 240))
                nvgText(vg, cx, tagY, card.name .. " C" .. r.oldConst .. " >> C" .. r.constellation, nil)
            end
        else
            -- 残片结果
            local qc = QCOLORS[card.quality] or { 180, 180, 170 }
            nvgFillColor(vg, nvgRGBA(qc[1], qc[2], qc[3], 240))
            nvgText(vg, cx, tagY, card.name .. " 残片 ×" .. r.fragCount, nil)
            -- 进度
            local need = HERO_FRAG_EXCHANGE[card.quality] or 20
            local total = heroFragments[r.cardIdx] or 0
            nvgFontSize(vg, 24)
            nvgFillColor(vg, nvgRGBA(200, 200, 200, 200))
            nvgText(vg, cx, tagY + 28, "累计 " .. total .. "/" .. need, nil)
        end
    elseif count <= 10 then
        -- 按品质降序排序（高品质排前面）
        table.sort(results, function(a, b)
            local qa = HERO_CARDS[a.cardIdx] and HERO_CARDS[a.cardIdx].quality or 0
            local qb = HERO_CARDS[b.cardIdx] and HERO_CARDS[b.cardIdx].quality or 0
            return qa > qb
        end)
        -- 十连: 5列×2行 网格
        local cols = 5
        local cardW = 80
        local cardH = cardW / CARD_RATIO
        local gap = 8
        local gridW = cols * cardW + (cols - 1) * gap
        local startX = cx - gridW / 2
        local startY = 85

        for i, r in ipairs(results) do
            local col = ((i - 1) % cols)
            local row = math.floor((i - 1) / cols)
            local x = startX + col * (cardW + gap)
            local y = startY + row * (cardH + 28 + gap)
            local card = HERO_CARDS[r.cardIdx]

            DrawInventoryCard(x, y, cardW, cardH, card, r.constellation or 0, false)

            nvgFontSize(vg, 14)
            nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_TOP)

            if r.isFullCard then
                -- 整卡标记
                if r.isNew then
                    nvgFillColor(vg, nvgRGBA(120, 255, 160, 220))
                    nvgText(vg, x + cardW / 2, y + cardH + 2, "新!", nil)
                elseif r.jadeRefund and r.jadeRefund > 0 then
                    nvgFillColor(vg, nvgRGBA(255, 215, 0, 220))
                    nvgText(vg, x + cardW / 2, y + cardH + 2, "+" .. r.jadeRefund .. "玉", nil)
                else
                    local cc = GameConfig.CONSTELLATION_COLORS[r.constellation] or { 180, 175, 165 }
                    nvgFillColor(vg, nvgRGBA(cc[1], cc[2], cc[3], 200))
                    nvgText(vg, x + cardW / 2, y + cardH + 2, "C" .. r.oldConst .. ">>" .. r.constellation, nil)
                end
            else
                -- 残片标记
                local qc = QCOLORS[card.quality] or { 180, 180, 170 }
                nvgFillColor(vg, nvgRGBA(qc[1], qc[2], qc[3], 220))
                nvgText(vg, x + cardW / 2, y + cardH + 2, "残片×" .. r.fragCount, nil)
                -- 进度小字
                local need = HERO_FRAG_EXCHANGE[card.quality] or 20
                local total = heroFragments[r.cardIdx] or 0
                nvgFontSize(vg, 11)
                nvgFillColor(vg, nvgRGBA(200, 200, 200, 160))
                nvgText(vg, x + cardW / 2, y + cardH + 16, total .. "/" .. need, nil)
            end
        end
    else
        -- 按品质降序排序（高品质排前面）
        table.sort(results, function(a, b)
            local qa = HERO_CARDS[a.cardIdx] and HERO_CARDS[a.cardIdx].quality or 0
            local qb = HERO_CARDS[b.cardIdx] and HERO_CARDS[b.cardIdx].quality or 0
            return qa > qb
        end)
        -- 大量抽卡汇总展示 (50连/100连)
        -- 统计各品质数量
        local qualityCounts = { [1] = 0, [2] = 0, [3] = 0, [4] = 0 }
        local notableResults = {}  -- SSR + 新获得的SR
        local totalRefund = 0
        local totalFragCount = 0
        for _, r in ipairs(results) do
            local card = HERO_CARDS[r.cardIdx]
            qualityCounts[card.quality] = (qualityCounts[card.quality] or 0) + 1
            if r.jadeRefund then totalRefund = totalRefund + r.jadeRefund end
            if r.fragCount then totalFragCount = totalFragCount + r.fragCount end
            -- 收集SSR和新获得的SR作为亮点
            if card.quality == 4 or (card.quality == 3 and r.isNew) then
                table.insert(notableResults, r)
            end
        end

        -- 品质汇总条
        local sumY = 95
        nvgFontSize(vg, 20)
        nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)

        local qLabels = {}
        if qualityCounts[4] > 0 then
            table.insert(qLabels, { text = "SSR ×" .. qualityCounts[4], color = { 255, 200, 60 } })
        end
        if qualityCounts[3] > 0 then
            table.insert(qLabels, { text = "SR ×" .. qualityCounts[3], color = { 80, 160, 255 } })
        end
        if qualityCounts[2] > 0 then
            table.insert(qLabels, { text = "R ×" .. qualityCounts[2], color = { 100, 200, 120 } })
        end
        if qualityCounts[1] > 0 then
            table.insert(qLabels, { text = "N ×" .. qualityCounts[1], color = { 180, 180, 170 } })
        end

        -- 居中绘制品质标签
        local totalLabelW = 0
        local labelGap = 16
        for _, ql in ipairs(qLabels) do
            totalLabelW = totalLabelW + nvgTextBounds(vg, 0, 0, ql.text, nil)
        end
        totalLabelW = totalLabelW + labelGap * math.max(0, #qLabels - 1)
        local labelX = cx - totalLabelW / 2
        nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)
        for _, ql in ipairs(qLabels) do
            nvgFillColor(vg, nvgRGBA(ql.color[1], ql.color[2], ql.color[3], 240))
            nvgText(vg, labelX, sumY, ql.text, nil)
            labelX = labelX + nvgTextBounds(vg, 0, 0, ql.text, nil) + labelGap
        end

        -- 残片/返还统计
        local statsY = 120
        nvgFontSize(vg, 16)
        nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        local statsText = ""
        if totalFragCount > 0 then
            statsText = "残片 ×" .. totalFragCount
        end
        if totalRefund > 0 then
            if #statsText > 0 then statsText = statsText .. "  |  " end
            statsText = statsText .. "返还 " .. totalRefund .. " 虎符"
        end
        if #statsText > 0 then
            nvgFillColor(vg, nvgRGBA(200, 195, 180, 200))
            nvgText(vg, cx, statsY, statsText, nil)
        end

        -- 亮点武灵展示 (SSR + 新SR, 最多10张)
        local showResults = notableResults
        local showCount = #showResults
        local gridStartY = 145

        if showCount == 0 then
            -- 没有亮点: 显示所有结果的紧凑网格
            showResults = results
            showCount = math.min(#results, 20)  -- 最多显示20张
            nvgFontSize(vg, 15)
            nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
            nvgFillColor(vg, nvgRGBA(200, 195, 180, 160))
            nvgText(vg, cx, gridStartY, "本次未获得SSR/新SR", nil)
            gridStartY = 170
        else
            nvgFontSize(vg, 16)
            nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
            nvgFillColor(vg, nvgRGBA(255, 220, 100, 200))
            nvgText(vg, cx, gridStartY, "亮点武灵", nil)
            gridStartY = 168
            showCount = math.min(showCount, 10)
        end

        -- 绘制亮点卡片网格 (自适应列数)
        if showCount > 0 then
            local cols = math.min(showCount, 5)
            local cardW = showCount <= 5 and 80 or 64
            local cardH = cardW / CARD_RATIO
            local gap = showCount <= 5 and 8 or 6
            local gridW = cols * cardW + (cols - 1) * gap
            local startX = cx - gridW / 2

            for i = 1, showCount do
                local r = showResults[i]
                local col = ((i - 1) % cols)
                local row = math.floor((i - 1) / cols)
                local x = startX + col * (cardW + gap)
                local y = gridStartY + row * (cardH + 28 + gap)
                local card = HERO_CARDS[r.cardIdx]

                DrawInventoryCard(x, y, cardW, cardH, card, r.constellation or 0, false)

                nvgFontSize(vg, 13)
                nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_TOP)

                if r.isFullCard then
                    if r.isNew then
                        nvgFillColor(vg, nvgRGBA(120, 255, 160, 220))
                        nvgText(vg, x + cardW / 2, y + cardH + 2, "新!", nil)
                    elseif r.jadeRefund and r.jadeRefund > 0 then
                        nvgFillColor(vg, nvgRGBA(255, 215, 0, 220))
                        nvgText(vg, x + cardW / 2, y + cardH + 2, "+" .. r.jadeRefund .. "玉", nil)
                    else
                        local cc = GameConfig.CONSTELLATION_COLORS[r.constellation] or { 180, 175, 165 }
                        nvgFillColor(vg, nvgRGBA(cc[1], cc[2], cc[3], 200))
                        nvgText(vg, x + cardW / 2, y + cardH + 2, "C" .. r.oldConst .. ">>" .. r.constellation, nil)
                    end
                else
                    local qc = QCOLORS[card.quality] or { 180, 180, 170 }
                    nvgFillColor(vg, nvgRGBA(qc[1], qc[2], qc[3], 220))
                    nvgText(vg, x + cardW / 2, y + cardH + 2, "残片×" .. r.fragCount, nil)
                end
            end
        end
    end

    -- 确认按钮
    local confirmW = 140
    local confirmH = 38
    local confirmX = cx - confirmW / 2
    local confirmY = H * 0.88
    nvgBeginPath(vg)
    nvgRoundedRect(vg, confirmX, confirmY, confirmW, confirmH, 5)
    nvgFillColor(vg, nvgRGBA(25, 30, 50, 200)); nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(160, 130, 70, 180)); nvgStrokeWidth(vg, 1.2); nvgStroke(vg)
    nvgFontSize(vg, 30)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(cx, confirmY + confirmH / 2, "确 认")
    gachaConfirmBtnRect = { x = confirmX, y = confirmY, w = confirmW, h = confirmH }
end

-- ============================================================================
-- 武技召唤 - 待机界面
-- ============================================================================
function DrawSkillGachaIdle(t)
    local W = DESIGN_W
    local H = DESIGN_H
    local cx = W / 2
    local circleY = H * 0.42
    local circleR = 95

    -- 武技召唤阵 (紫色系, 与武灵金色区分)
    for i = 1, 10 do
        local angle = (i / 10) * math.pi * 2 + t * 0.8
        local arcLen = math.pi / 7
        local r = circleR + 6 + 3 * math.sin(t * 2 + i)
        nvgBeginPath(vg)
        nvgArc(vg, cx, circleY, r, angle, angle + arcLen, NVG_CW)
        local pulse = 0.4 + 0.6 * math.sin(t * 1.5 + i * 0.6)
        nvgStrokeColor(vg, nvgRGBA(160, 100, 220, math.floor(100 * pulse)))
        nvgStrokeWidth(vg, 1.5); nvgStroke(vg)
    end
    for i = 1, 6 do
        local angle = -(i / 6) * math.pi * 2 + t * 1.2
        local arcLen = math.pi / 5
        nvgBeginPath(vg)
        nvgArc(vg, cx, circleY, circleR - 5, angle, angle + arcLen, NVG_CW)
        local pulse = 0.3 + 0.7 * math.sin(t * 2.5 + i * 0.9)
        nvgStrokeColor(vg, nvgRGBA(180, 130, 255, math.floor(80 * pulse)))
        nvgStrokeWidth(vg, 1.0); nvgStroke(vg)
    end

    -- 中心光晕 (紫色)
    local glowPulse = 0.6 + 0.4 * math.sin(t * 2)
    local glow = nvgRadialGradient(vg, cx, circleY, 5, circleR * 0.8,
        nvgRGBA(140, 80, 200, math.floor(40 * glowPulse)),
        nvgRGBA(100, 60, 180, 0))
    nvgBeginPath(vg); nvgCircle(vg, cx, circleY, circleR * 0.8)
    nvgFillPaint(vg, glow); nvgFill(vg)

    -- 中心文字
    nvgFontFaceId(vg, GetMainFont())
    nvgFontSize(vg, 26)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    local textPulse = 0.6 + 0.4 * math.sin(t * 1.8)
    nvgFillColor(vg, nvgRGBA(200, 160, 255, math.floor(180 * textPulse)))
    nvgText(vg, cx, circleY, "功 法 感 悟", nil)

    nvgFontSize(vg, 14)
    DrawWhiteInkText(cx, circleY + 32, "消耗虎符, 感悟武技残片")

    -- 抽卡按钮
    local bigPull = playerInfo.jadeUnlockedBigPull
    gachaHundredBtnRect = nil

    if bigPull then
        -- 增强模式: 3个按钮 (10连/50连/100连) 紫色调
        local btnW = 160
        local btnH = 46
        local btnGap = 8
        local btnY1 = H * 0.62
        local btnY2 = btnY1 + btnH + btnGap
        local btnY3 = btnY2 + btnH + btnGap
        local unitCost = GameConfig.GACHA_COST_SINGLE
        local fragPer = SKILL_FRAG_PER_PULL  -- 单抽5个残片

        -- 10连 (出50残片)
        local b1x = cx - btnW / 2
        nvgBeginPath(vg); nvgRoundedRect(vg, b1x, btnY1, btnW, btnH, 6)
        nvgFillColor(vg, nvgRGBA(30, 20, 50, 200)); nvgFill(vg)
        local bp1 = 0.7 + 0.3 * math.sin(t * 2)
        nvgStrokeColor(vg, nvgRGBA(160, 100, 220, math.floor(180 * bp1)))
        nvgStrokeWidth(vg, 1.5); nvgStroke(vg)
        nvgFontSize(vg, 20); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        DrawWhiteInkText(cx, btnY1 + btnH / 2 - 7, "十连感悟 ×" .. (fragPer * 10))
        nvgFontSize(vg, 14)
        DrawWhiteInkText(cx, btnY1 + btnH / 2 + 12, math.floor(unitCost * 10 * 0.9) .. " 虎符 (9折)")
        gachaSingleBtnRect = { x = b1x, y = btnY1, w = btnW, h = btnH }

        -- 50连 (出250残片)
        local b2x = cx - btnW / 2
        nvgBeginPath(vg); nvgRoundedRect(vg, b2x, btnY2, btnW, btnH, 6)
        local g50 = nvgLinearGradient(vg, b2x, btnY2, b2x + btnW, btnY2 + btnH,
            nvgRGBA(40, 20, 60, 220), nvgRGBA(55, 25, 80, 220))
        nvgFillPaint(vg, g50); nvgFill(vg)
        local bp2 = 0.6 + 0.4 * math.sin(t * 2.5)
        nvgBeginPath(vg); nvgRoundedRect(vg, b2x, btnY2, btnW, btnH, 6)
        nvgStrokeColor(vg, nvgRGBA(200, 140, 255, math.floor(200 * bp2)))
        nvgStrokeWidth(vg, 1.8); nvgStroke(vg)
        nvgFontSize(vg, 20); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        DrawWhiteInkText(cx, btnY2 + btnH / 2 - 7, "五十连 ×" .. (fragPer * 50))
        nvgFontSize(vg, 14)
        DrawWhiteInkText(cx, btnY2 + btnH / 2 + 12, math.floor(unitCost * 50 * 0.9) .. " 虎符 (9折)")
        gachaTenBtnRect = { x = b2x, y = btnY2, w = btnW, h = btnH }

        -- 100连 (出500残片)
        local b3x = cx - btnW / 2
        nvgBeginPath(vg); nvgRoundedRect(vg, b3x, btnY3, btnW, btnH, 6)
        local g100 = nvgLinearGradient(vg, b3x, btnY3, b3x + btnW, btnY3 + btnH,
            nvgRGBA(50, 15, 75, 230), nvgRGBA(65, 10, 90, 230))
        nvgFillPaint(vg, g100); nvgFill(vg)
        local bp3 = 0.5 + 0.5 * math.sin(t * 3)
        nvgBeginPath(vg); nvgRoundedRect(vg, b3x, btnY3, btnW, btnH, 6)
        nvgStrokeColor(vg, nvgRGBA(240, 180, 255, math.floor(220 * bp3)))
        nvgStrokeWidth(vg, 2.0); nvgStroke(vg)
        nvgFontSize(vg, 20); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        DrawWhiteInkText(cx, btnY3 + btnH / 2 - 7, "百连感悟 ×" .. (fragPer * 100))
        nvgFontSize(vg, 14)
        DrawWhiteInkText(cx, btnY3 + btnH / 2 + 12, math.floor(unitCost * 100 * 0.9) .. " 虎符 (9折)")
        gachaHundredBtnRect = { x = b3x, y = btnY3, w = btnW, h = btnH }
    else
        -- 原始模式: 2个按钮 (单抽/十连)
        local btnW = 160
        local btnH = 56
        local btnGap = 16
        local btnY1 = H * 0.66
        local btnY2 = btnY1 + btnH + btnGap

        -- 单抽按钮 (出5残片)
        local b1x = cx - btnW / 2
        nvgBeginPath(vg); nvgRoundedRect(vg, b1x, btnY1, btnW, btnH, 6)
        nvgFillColor(vg, nvgRGBA(30, 20, 50, 200)); nvgFill(vg)
        local bp1 = 0.7 + 0.3 * math.sin(t * 2)
        nvgStrokeColor(vg, nvgRGBA(160, 100, 220, math.floor(180 * bp1)))
        nvgStrokeWidth(vg, 1.5); nvgStroke(vg)
        nvgFontSize(vg, 22); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        DrawWhiteInkText(cx, btnY1 + btnH / 2 - 10, "感悟 ×5")
        nvgFontSize(vg, 16)
        DrawWhiteInkText(cx, btnY1 + btnH / 2 + 20, GameConfig.GACHA_COST_SINGLE .. " 虎符")
        gachaSingleBtnRect = { x = b1x, y = btnY1, w = btnW, h = btnH }

        -- 十连按钮 (出50残片)
        local b2x = cx - btnW / 2
        nvgBeginPath(vg); nvgRoundedRect(vg, b2x, btnY2, btnW, btnH, 6)
        local tenGrad = nvgLinearGradient(vg, b2x, btnY2, b2x + btnW, btnY2 + btnH,
            nvgRGBA(40, 20, 60, 220), nvgRGBA(55, 25, 80, 220))
        nvgFillPaint(vg, tenGrad); nvgFill(vg)
        local bp2 = 0.6 + 0.4 * math.sin(t * 2.5)
        nvgBeginPath(vg); nvgRoundedRect(vg, b2x, btnY2, btnW, btnH, 6)
        nvgStrokeColor(vg, nvgRGBA(200, 140, 255, math.floor(200 * bp2)))
        nvgStrokeWidth(vg, 1.8); nvgStroke(vg)
        nvgFontSize(vg, 22); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        DrawWhiteInkText(cx, btnY2 + btnH / 2 - 10, "十连感悟 ×50")
        nvgFontSize(vg, 16)
        DrawWhiteInkText(cx, btnY2 + btnH / 2 + 20, GameConfig.GACHA_COST_TEN .. " 虎符 (9折)")
        gachaTenBtnRect = { x = b2x, y = btnY2, w = btnW, h = btnH }
    end

    -- 计算最后一个按钮底部Y (兼容增强模式3按钮)
    local lastBtnBottom = gachaHundredBtnRect and (gachaHundredBtnRect.y + gachaHundredBtnRect.h) or (gachaTenBtnRect.y + gachaTenBtnRect.h)

    -- 残片兑换提示
    nvgFontSize(vg, 14)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(cx, lastBtnBottom + 20, "集齐49个同名残片可兑换完整武技")

    -- 已收集残片统计
    local fragTotal = 0
    local fragTypes = 0
    for _, cnt in pairs(skillFragments) do
        fragTotal = fragTotal + cnt
        fragTypes = fragTypes + 1
    end
    nvgFontSize(vg, 14)
    DrawWhiteInkText(cx, lastBtnBottom + 52, "已收集 " .. fragTotal .. " 残片 (" .. fragTypes .. " 种)")

    -- (万能残片已移除，不再显示)

    -- 可兑换列表预览（最多显示3个最接近兑换的）
    local exchangeable = {}
    for skillIdx, cnt in pairs(skillFragments) do
        if cnt >= SKILL_FRAG_EXCHANGE then
            table.insert(exchangeable, { idx = skillIdx, cnt = cnt })
        end
    end
    if #exchangeable > 0 then
        nvgFontSize(vg, 14)
        DrawWhiteInkText(cx, lastBtnBottom + 84, "有 " .. #exchangeable .. " 个武技可兑换! 前往武技")
    end

    -- 底部按钮行：概率规则(?) + 残片仓库
    local bottomBtnY = lastBtnBottom + 8

    -- 残片仓库按钮（左侧）
    local shopBtnW = 90
    local shopBtnH = 30
    local shopBtnX = 12
    nvgBeginPath(vg); nvgRoundedRect(vg, shopBtnX, bottomBtnY, shopBtnW, shopBtnH, 6)
    nvgFillColor(vg, nvgRGBA(35, 25, 55, 210)); nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(180, 130, 220, 160)); nvgStrokeWidth(vg, 1.2); nvgStroke(vg)
    nvgFontSize(vg, 14)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(shopBtnX + shopBtnW / 2, bottomBtnY + shopBtnH / 2, "残片仓库")
    -- 可合成红点提示（含武灵+武技）
    local canComposeCount = 0
    for cardIdx, cnt in pairs(heroFragments) do
        local card = HERO_CARDS[cardIdx]
        if card and cnt >= (HERO_FRAG_EXCHANGE[card.quality] or 20) then canComposeCount = canComposeCount + 1 end
    end
    for _, cnt in pairs(skillFragments) do
        if cnt >= SKILL_FRAG_EXCHANGE then canComposeCount = canComposeCount + 1 end
    end
    if canComposeCount > 0 then
        local dotR = 7
        local dotX = shopBtnX + shopBtnW - 4
        local dotY = bottomBtnY + 4
        nvgBeginPath(vg); nvgCircle(vg, dotX, dotY, dotR)
        nvgFillColor(vg, nvgRGBA(255, 60, 60, 230)); nvgFill(vg)
        nvgFontSize(vg, 10)
        nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        DrawWhiteInkText(dotX, dotY, tostring(canComposeCount))
    end
    gachaFragShopBtnRect = { x = shopBtnX, y = bottomBtnY, w = shopBtnW, h = shopBtnH }

    -- 概率规则按钮（右侧）
    local qBtnSize = 30
    local qBtnX = W - qBtnSize - 12
    local qBtnY = bottomBtnY
    nvgBeginPath(vg); nvgCircle(vg, qBtnX + qBtnSize / 2, qBtnY + qBtnSize / 2, qBtnSize / 2)
    nvgFillColor(vg, nvgRGBA(40, 30, 65, 200)); nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(160, 100, 200, 160)); nvgStrokeWidth(vg, 1.2); nvgStroke(vg)
    nvgFontSize(vg, 29)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(qBtnX + qBtnSize / 2, qBtnY + qBtnSize / 2, "?")
    gachaRulesBtnRect = { x = qBtnX, y = qBtnY, w = qBtnSize, h = qBtnSize }
end

-- ============================================================================
-- 武技召唤 - 结果展示
-- ============================================================================
function DrawSkillGachaResults()
    local W = DESIGN_W
    local H = DESIGN_H
    local cx = W / 2
    local results = gachaState.skillResults
    local count = #results

    -- 半透明全屏遮罩
    nvgBeginPath(vg)
    nvgRect(vg, 0, 0, W, H)
    nvgFillColor(vg, nvgRGBA(0, 0, 0, 160))
    nvgFill(vg)

    nvgFontFaceId(vg, GetMainFont())

    -- 标题
    nvgFontSize(vg, 33)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(cx, 65, "感悟结果")

    if count == 0 then return end

    -- 武技残片tier对应颜色 (7阶, 与 SKILL_TIERS 对齐)
    local TIER_COLORS = {
        { 180, 175, 165 },  -- 凡品 灰
        { 100, 210, 120 },  -- 良品 绿
        { 80, 160, 255 },   -- 优品 蓝
        { 180, 100, 255 },  -- 将品 紫
        { 255, 140, 0 },    -- 侯品 橙
        { 255, 180, 50 },   -- 王品 金
        { 255, 80, 80 },    -- 帝品 红
    }

    -- 按等阶降序排序（高品质排前面）
    if count > 1 then
        table.sort(results, function(a, b)
            local ta = SKILL_TECHNIQUES[a.skillIdx] and SKILL_TECHNIQUES[a.skillIdx].tier or 0
            local tb = SKILL_TECHNIQUES[b.skillIdx] and SKILL_TECHNIQUES[b.skillIdx].tier or 0
            return ta > tb
        end)
    end

    -- 网格展示残片（带武技图标）
    local cols = math.min(count, 4)
    local cardW = 90
    local cardH = 130
    local gap = 8
    local gridW = cols * cardW + (cols - 1) * gap
    local startX = cx - gridW / 2
    local startY = 85

    for i, r in ipairs(results) do
        local col = ((i - 1) % cols)
        local row = math.floor((i - 1) / cols)
        local x = startX + col * (cardW + gap)
        local y = startY + row * (cardH + gap)
        local tech = SKILL_TECHNIQUES[r.skillIdx]
        local tier = tech.tier
        local tc = TIER_COLORS[tier] or { 180, 180, 170 }

        -- 残片卡片背景
        nvgBeginPath(vg); nvgRoundedRect(vg, x, y, cardW, cardH, 8)
        nvgFillColor(vg, nvgRGBA(20, 15, 35, 220)); nvgFill(vg)
        nvgStrokeColor(vg, nvgRGBA(tc[1], tc[2], tc[3], 180)); nvgStrokeWidth(vg, 1.5); nvgStroke(vg)

        -- 武技图标（居中显示）
        local iconSize = 52
        local iconX = x + (cardW - iconSize) / 2
        local iconY = y + 6
        drawSkillIcon(tech.iconIdx, iconX, iconY, iconSize, 6)

        -- 残片数量标签（图标右下角叠加）
        local badgeX = iconX + iconSize - 8
        local badgeY = iconY + iconSize - 10
        nvgBeginPath(vg); nvgRoundedRect(vg, badgeX - 10, badgeY - 6, 26, 16, 4)
        nvgFillColor(vg, nvgRGBA(30, 20, 50, 220)); nvgFill(vg)
        nvgStrokeColor(vg, nvgRGBA(255, 220, 100, 180)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
        nvgFontSize(vg, 17)
        nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        DrawWhiteInkText(badgeX + 3, badgeY + 2, "×" .. r.fragCount)

        -- 武技名（图标下方）
        nvgFontSize(vg, 16)
        nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        nvgFillColor(vg, nvgRGBA(tc[1], tc[2], tc[3], 240))
        nvgText(vg, x + cardW / 2, y + 68, tech.name, nil)

        -- 等阶标签
        local tierInfo = SKILL_TIERS[tier]
        local tierLabel = tierInfo and tierInfo.name or ("T" .. tier)
        nvgFontSize(vg, 14)
        nvgFillColor(vg, nvgRGBA(tc[1], tc[2], tc[3], 160))
        nvgText(vg, x + cardW / 2, y + 82, tierLabel, nil)

        -- 累计进度条
        local barW = cardW - 16
        local barH = 8
        local barX = x + 8
        local barY = y + 92
        local total = r.totalFrags
        local progress = math.min(total / SKILL_FRAG_EXCHANGE, 1.0)

        nvgBeginPath(vg); nvgRoundedRect(vg, barX, barY, barW, barH, 3)
        nvgFillColor(vg, nvgRGBA(40, 30, 60, 200)); nvgFill(vg)

        if progress > 0 then
            local fillColor = total >= SKILL_FRAG_EXCHANGE
                and nvgRGBA(255, 200, 60, 240)
                or nvgRGBA(tc[1], tc[2], tc[3], 200)
            nvgBeginPath(vg); nvgRoundedRect(vg, barX, barY, barW * progress, barH, 3)
            nvgFillColor(vg, fillColor); nvgFill(vg)
        end

        -- 进度文字 x/49
        nvgFontSize(vg, 15)
        nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        if total >= SKILL_FRAG_EXCHANGE then
            DrawWhiteInkText(x + cardW / 2, y + 112, "可合成!")
        else
            DrawWhiteInkText(x + cardW / 2, y + 112, total .. "/" .. SKILL_FRAG_EXCHANGE)
        end
    end

    -- 确认按钮
    local confirmW = 140
    local confirmH = 38
    local confirmX = cx - confirmW / 2
    local confirmY = H * 0.88
    nvgBeginPath(vg); nvgRoundedRect(vg, confirmX, confirmY, confirmW, confirmH, 5)
    nvgFillColor(vg, nvgRGBA(25, 20, 50, 200)); nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(160, 100, 200, 180)); nvgStrokeWidth(vg, 1.2); nvgStroke(vg)
    nvgFontSize(vg, 30)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(cx, confirmY + confirmH / 2, "确 认")
    gachaConfirmBtnRect = { x = confirmX, y = confirmY, w = confirmW, h = confirmH }
end

-- ============================================================================
-- 残片商店 (召唤Tab 3) — 重做版
-- ============================================================================
function DrawFragmentShop(t)
    local W = DESIGN_W
    local H = DESIGN_H
    local cx = W / 2

    -- 半透明黑色遮罩 (0.6 不透明度)
    nvgBeginPath(vg); nvgRect(vg, 0, 0, W, H)
    nvgFillColor(vg, nvgRGBA(0, 0, 0, 153))  -- 255 * 0.6 = 153
    nvgFill(vg)

    nvgFontFaceId(vg, GetMainFont())
    fragShopComposeBtnRects = {}
    heroFragShopComposeBtnRects = {}

    -- 收集武灵残片
    local heroFragList = {}
    for cardIdx, cnt in pairs(heroFragments) do
        if cnt > 0 and HERO_CARDS[cardIdx] then
            table.insert(heroFragList, { cardIdx = cardIdx, count = cnt, quality = HERO_CARDS[cardIdx].quality })
        end
    end
    table.sort(heroFragList, function(a, b)
        if a.quality ~= b.quality then return a.quality > b.quality end
        return a.count > b.count
    end)

    -- 收集武技残片
    local fragList = {}
    for skillIdx, cnt in pairs(skillFragments) do
        if cnt > 0 then
            local tech = SKILL_TECHNIQUES[skillIdx]
            if tech then
                table.insert(fragList, { skillIdx = skillIdx, count = cnt, tier = tech.tier })
            end
        end
    end
    table.sort(fragList, function(a, b)
        if a.tier ~= b.tier then return a.tier > b.tier end
        if a.count ~= b.count then return a.count > b.count end
        return a.skillIdx < b.skillIdx
    end)

    -- 统计可合成数量
    local heroCanCompose = 0
    for _, f in ipairs(heroFragList) do
        local need = HERO_FRAG_EXCHANGE[f.quality] or 20
        if f.count >= need then heroCanCompose = heroCanCompose + 1 end
    end
    local skillCanCompose = 0
    for _, f in ipairs(fragList) do
        if f.count >= SKILL_FRAG_EXCHANGE then skillCanCompose = skillCanCompose + 1 end
    end
    local totalCanCompose = heroCanCompose + skillCanCompose

    -- ======== 标题区域 ========
    local titleY = 55
    nvgFontSize(vg, 28)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(cx, titleY, "残片仓库")

    -- 副标题统计
    nvgFontSize(vg, 14)
    nvgFillColor(vg, nvgRGBA(200, 190, 180, 160))
    nvgText(vg, cx, titleY + 20, "武灵 " .. #heroFragList .. " 种  ·  武技 " .. #fragList .. " 种", nil)
    if totalCanCompose > 0 then
        -- "✦ N 个可合成" 左侧 + "一键合成"按钮右侧，同一行
        local rowY = titleY + 38
        local composeLabel = "✦ " .. totalCanCompose .. " 个可合成"
        nvgFontSize(vg, 14)
        nvgTextAlign(vg, NVG_ALIGN_RIGHT + NVG_ALIGN_MIDDLE)
        nvgFillColor(vg, nvgRGBA(255, 220, 80, 220))
        nvgText(vg, cx - 4, rowY, composeLabel, nil)

        -- 一键合成按钮
        local okBtnW, okBtnH = 72, 22
        local okBtnX = cx + 4
        local okBtnY = rowY - okBtnH / 2
        local pulse = 0.75 + 0.25 * math.sin(t * 3.5)
        local bgP = nvgLinearGradient(vg, okBtnX, okBtnY, okBtnX, okBtnY + okBtnH,
            nvgRGBA(220, 170, 40, math.floor(240 * pulse)),
            nvgRGBA(180, 120, 20, math.floor(210 * pulse)))
        nvgBeginPath(vg); nvgRoundedRect(vg, okBtnX, okBtnY, okBtnW, okBtnH, 5)
        nvgFillPaint(vg, bgP); nvgFill(vg)
        nvgStrokeColor(vg, nvgRGBA(255, 240, 140, math.floor(200 * pulse)))
        nvgStrokeWidth(vg, 1.2); nvgStroke(vg)
        nvgFontSize(vg, 13)
        nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        DrawWhiteInkText(okBtnX + okBtnW / 2, okBtnY + okBtnH / 2, "一键合成")
        fragShopOneKeyBtnRect = { x = okBtnX, y = okBtnY, w = okBtnW, h = okBtnH }
    else
        fragShopOneKeyBtnRect = nil
    end

    -- ======== 空状态 ========
    if #heroFragList == 0 and #fragList == 0 then
        nvgFontSize(vg, 22)
        DrawWhiteInkText(cx, H * 0.44, "暂无残片")
        nvgFontSize(vg, 15)
        nvgFillColor(vg, nvgRGBA(180, 170, 160, 140))
        nvgText(vg, cx, H * 0.44 + 30, "召唤武灵或感悟武技获取残片", nil)
        return
    end

    -- ======== 滚动区域 ========
    local clipTop = titleY + 50
    local clipBottom = H - 10
    local clipH = clipBottom - clipTop

    -- 网格布局 — 3列更宽敞
    local cols = 3
    local cellW = 110
    local cellH = 140
    local gapX = 10
    local gapY = 10

    -- 武技残片 tier 颜色 (7阶, 与 SKILL_TIERS 对齐)
    local TIER_COLORS = {
        { 180, 175, 165 },  -- 凡品 灰
        { 100, 210, 120 },  -- 良品 绿
        { 80, 160, 255 },   -- 优品 蓝
        { 180, 100, 255 },  -- 将品 紫
        { 255, 140, 0 },    -- 侯品 橙
        { 255, 180, 50 },   -- 王品 金
        { 255, 80, 80 },    -- 帝品 红
    }
    local tierNames = { "凡", "良", "优", "将", "侯", "王", "帝" }

    -- 计算各区域高度
    local sectionTitleH = 32
    local heroSectionH = 0
    local heroRows = math.ceil(#heroFragList / cols)
    if #heroFragList > 0 then
        heroSectionH = sectionTitleH + heroRows * (cellH + gapY)
    end
    local skillSectionH = 0
    local skillRows = math.ceil(#fragList / cols)
    if #fragList > 0 then
        skillSectionH = sectionTitleH + skillRows * (cellH + gapY)
    end
    local sectionGap = (#heroFragList > 0 and #fragList > 0) and 12 or 0
    local contentH = heroSectionH + sectionGap + skillSectionH
    local gridW = cols * cellW + (cols - 1) * gapX
    local gridStartX = cx - gridW / 2

    -- 限制滚动范围
    local maxScroll = 0
    local minScroll = math.min(0, clipH - contentH - 10)
    fragShopScroll.offset = math.max(minScroll, math.min(maxScroll, fragShopScroll.offset))

    nvgSave(vg)
    nvgScissor(vg, 0, clipTop, W, clipH)

    local cursorY = clipTop + fragShopScroll.offset

    -- ======== 区域分隔标题绘制辅助 ========
    local function drawSectionHeader(label, labelColor, count, yPos)
        local lineY = yPos + sectionTitleH / 2
        -- 左侧装饰线
        local labelW = 80
        local lineLeft = gridStartX
        local lineRight = gridStartX + gridW
        nvgBeginPath(vg)
        nvgMoveTo(vg, lineLeft, lineY)
        nvgLineTo(vg, cx - labelW / 2 - 8, lineY)
        nvgStrokeColor(vg, nvgRGBA(labelColor[1], labelColor[2], labelColor[3], 60))
        nvgStrokeWidth(vg, 1); nvgStroke(vg)
        -- 右侧装饰线
        nvgBeginPath(vg)
        nvgMoveTo(vg, cx + labelW / 2 + 8, lineY)
        nvgLineTo(vg, lineRight, lineY)
        nvgStrokeColor(vg, nvgRGBA(labelColor[1], labelColor[2], labelColor[3], 60))
        nvgStrokeWidth(vg, 1); nvgStroke(vg)
        -- 标签
        nvgFontSize(vg, 16)
        nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        nvgFillColor(vg, nvgRGBA(labelColor[1], labelColor[2], labelColor[3], 200))
        nvgText(vg, cx, lineY, label .. " (" .. count .. ")", nil)
    end

    -- ======== 通用合成按钮绘制 ========
    local function drawComposeBtn(bx, by, bw, bh, pulse)
        -- 按钮底色渐变
        local bgPaint = nvgLinearGradient(vg, bx, by, bx, by + bh,
            nvgRGBA(200, 150, 40, math.floor(230 * pulse)),
            nvgRGBA(160, 100, 20, math.floor(200 * pulse)))
        nvgBeginPath(vg); nvgRoundedRect(vg, bx, by, bw, bh, 5)
        nvgFillPaint(vg, bgPaint); nvgFill(vg)
        nvgStrokeColor(vg, nvgRGBA(255, 230, 120, math.floor(180 * pulse)))
        nvgStrokeWidth(vg, 1.2); nvgStroke(vg)
        nvgFontSize(vg, 14)
        nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        DrawWhiteInkText(bx + bw / 2, by + bh / 2, "合 成")
    end

    -- ========== 武灵残片区域 ==========
    if #heroFragList > 0 then
        drawSectionHeader("武灵残片", { 255, 200, 80 }, #heroFragList, cursorY)
        cursorY = cursorY + sectionTitleH

        for i, f in ipairs(heroFragList) do
            local col = ((i - 1) % cols)
            local row = math.floor((i - 1) / cols)
            local x = gridStartX + col * (cellW + gapX)
            local y = cursorY + row * (cellH + gapY)

            if y + cellH >= clipTop and y <= clipBottom then
                local card = HERO_CARDS[f.cardIdx]
                local qc = QUALITY_COLORS[f.quality] or { 180, 180, 170 }
                local need = HERO_FRAG_EXCHANGE[f.quality] or 20
                local canExchange = f.count >= need

                -- 卡片背景 — 渐变底色
                nvgBeginPath(vg); nvgRoundedRect(vg, x, y, cellW, cellH, 10)
                if canExchange then
                    local glowPulse = 0.6 + 0.4 * math.sin(t * 3 + f.cardIdx)
                    local bgP = nvgLinearGradient(vg, x, y, x, y + cellH,
                        nvgRGBA(50, 45, 15, math.floor(230 * glowPulse)),
                        nvgRGBA(30, 25, 10, math.floor(210 * glowPulse)))
                    nvgFillPaint(vg, bgP); nvgFill(vg)
                    -- 金色发光边框
                    nvgStrokeColor(vg, nvgRGBA(255, 220, 80, math.floor(200 * glowPulse)))
                    nvgStrokeWidth(vg, 2); nvgStroke(vg)
                else
                    local bgP = nvgLinearGradient(vg, x, y, x, y + cellH,
                        nvgRGBA(30, 28, 45, 230), nvgRGBA(18, 16, 30, 240))
                    nvgFillPaint(vg, bgP); nvgFill(vg)
                    nvgStrokeColor(vg, nvgRGBA(qc[1], qc[2], qc[3], 100))
                    nvgStrokeWidth(vg, 1); nvgStroke(vg)
                end

                -- 品质色顶部装饰条
                nvgBeginPath(vg); nvgRoundedRect(vg, x + 2, y + 2, cellW - 4, 3, 1.5)
                nvgFillColor(vg, nvgRGBA(qc[1], qc[2], qc[3], 160)); nvgFill(vg)

                -- 武灵头像（卡牌缩略图）
                local thumbW = 60
                local thumbH = thumbW / CARD_RATIO
                local thumbX = x + (cellW - thumbW) / 2
                local thumbY = y + 8
                DrawInventoryCard(thumbX, thumbY, thumbW, thumbH, card, 0, false)

                -- 进度条
                local barW = cellW - 16
                local barH = 6
                local barX = x + 8
                local barY = y + 95
                local progress = math.min(f.count / need, 1.0)

                nvgBeginPath(vg); nvgRoundedRect(vg, barX, barY, barW, barH, 3)
                nvgFillColor(vg, nvgRGBA(40, 30, 50, 200)); nvgFill(vg)
                if progress > 0 then
                    local fillCol = canExchange
                        and nvgRGBA(255, 210, 60, 240)
                        or nvgRGBA(qc[1], qc[2], qc[3], 180)
                    nvgBeginPath(vg); nvgRoundedRect(vg, barX, barY, barW * progress, barH, 3)
                    nvgFillColor(vg, fillCol); nvgFill(vg)
                end

                -- 残片数文字
                nvgFontSize(vg, 13)
                nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
                if canExchange then
                    nvgFillColor(vg, nvgRGBA(255, 220, 80, 240))
                else
                    nvgFillColor(vg, nvgRGBA(200, 195, 185, 200))
                end
                nvgText(vg, x + cellW / 2, barY + barH + 10, f.count .. " / " .. need, nil)

                -- 合成按钮
                if canExchange then
                    local btnW = 64
                    local btnH = 22
                    local btnX = x + (cellW - btnW) / 2
                    local btnY = y + cellH - btnH - 4
                    local pulse = 0.7 + 0.3 * math.sin(t * 4 + f.cardIdx * 0.7)
                    drawComposeBtn(btnX, btnY, btnW, btnH, pulse)
                    heroFragShopComposeBtnRects[f.cardIdx] = { x = btnX, y = btnY, w = btnW, h = btnH }
                end
            end
        end
        cursorY = cursorY + heroRows * (cellH + gapY)
    end

    -- 区域间距
    if #heroFragList > 0 and #fragList > 0 then
        cursorY = cursorY + sectionGap
    end

    -- ========== 武技残片区域 ==========
    if #fragList > 0 then
        drawSectionHeader("武技残片", { 180, 140, 255 }, #fragList, cursorY)
        cursorY = cursorY + sectionTitleH
    end

    for i, f in ipairs(fragList) do
        local col = ((i - 1) % cols)
        local row = math.floor((i - 1) / cols)
        local x = gridStartX + col * (cellW + gapX)
        local y = cursorY + row * (cellH + gapY)

        if y + cellH >= clipTop and y <= clipBottom then
            local tech = SKILL_TECHNIQUES[f.skillIdx]
            local tc = TIER_COLORS[tech.tier] or { 180, 180, 170 }
            local canExchange = f.count >= SKILL_FRAG_EXCHANGE

            -- 卡片背景 — 渐变
            nvgBeginPath(vg); nvgRoundedRect(vg, x, y, cellW, cellH, 10)
            if canExchange then
                local glowPulse = 0.6 + 0.4 * math.sin(t * 3 + f.skillIdx)
                local bgP = nvgLinearGradient(vg, x, y, x, y + cellH,
                    nvgRGBA(50, 45, 15, math.floor(230 * glowPulse)),
                    nvgRGBA(30, 25, 10, math.floor(210 * glowPulse)))
                nvgFillPaint(vg, bgP); nvgFill(vg)
                nvgStrokeColor(vg, nvgRGBA(255, 220, 80, math.floor(200 * glowPulse)))
                nvgStrokeWidth(vg, 2); nvgStroke(vg)
            else
                local bgP = nvgLinearGradient(vg, x, y, x, y + cellH,
                    nvgRGBA(25, 20, 40, 230), nvgRGBA(15, 12, 28, 240))
                nvgFillPaint(vg, bgP); nvgFill(vg)
                nvgStrokeColor(vg, nvgRGBA(tc[1], tc[2], tc[3], 100))
                nvgStrokeWidth(vg, 1); nvgStroke(vg)
            end

            -- 品质色顶部装饰条
            nvgBeginPath(vg); nvgRoundedRect(vg, x + 2, y + 2, cellW - 4, 3, 1.5)
            nvgFillColor(vg, nvgRGBA(tc[1], tc[2], tc[3], 160)); nvgFill(vg)

            -- 武技图标 — 更大
            local iconSize = 54
            local iconX = x + (cellW - iconSize) / 2
            local iconY = y + 8
            drawSkillIcon(tech.iconIdx, iconX, iconY, iconSize, 6)

            -- 阶级标签（右上角小徽章）
            local badgeX = x + cellW - 24
            local badgeY = y + 6
            nvgBeginPath(vg); nvgRoundedRect(vg, badgeX, badgeY, 20, 16, 4)
            nvgFillColor(vg, nvgRGBA(tc[1], tc[2], tc[3], 140)); nvgFill(vg)
            nvgFontSize(vg, 11)
            nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
            nvgFillColor(vg, nvgRGBA(255, 255, 255, 230))
            nvgText(vg, badgeX + 10, badgeY + 8, tierNames[tech.tier] or "?", nil)

            -- 武技名
            nvgFontSize(vg, 14)
            nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
            nvgFillColor(vg, nvgRGBA(tc[1], tc[2], tc[3], 240))
            nvgText(vg, x + cellW / 2, y + 70, tech.name, nil)

            -- 进度条
            local barW = cellW - 16
            local barH = 6
            local barX = x + 8
            local barY = y + 82
            local progress = math.min(f.count / SKILL_FRAG_EXCHANGE, 1.0)

            nvgBeginPath(vg); nvgRoundedRect(vg, barX, barY, barW, barH, 3)
            nvgFillColor(vg, nvgRGBA(40, 30, 60, 200)); nvgFill(vg)

            if progress > 0 then
                local fillColor = canExchange
                    and nvgRGBA(255, 210, 60, 240)
                    or nvgRGBA(tc[1], tc[2], tc[3], 180)
                nvgBeginPath(vg); nvgRoundedRect(vg, barX, barY, barW * progress, barH, 3)
                nvgFillColor(vg, fillColor); nvgFill(vg)
            end

            -- 残片数 x/49
            nvgFontSize(vg, 13)
            nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
            if canExchange then
                nvgFillColor(vg, nvgRGBA(255, 220, 80, 240))
            else
                nvgFillColor(vg, nvgRGBA(200, 195, 185, 200))
            end
            nvgText(vg, x + cellW / 2, barY + barH + 10, f.count .. " / " .. SKILL_FRAG_EXCHANGE, nil)

            -- 合成按钮
            if canExchange then
                local btnW = 64
                local btnH = 22
                local btnX = x + (cellW - btnW) / 2
                local btnY = y + cellH - btnH - 4
                local pulse = 0.7 + 0.3 * math.sin(t * 4 + f.skillIdx * 0.7)
                drawComposeBtn(btnX, btnY, btnW, btnH, pulse)
                fragShopComposeBtnRects[f.skillIdx] = { x = btnX, y = btnY, w = btnW, h = btnH }
            end
        end
    end

    nvgRestore(vg)

    -- 滚动条指示器
    if contentH > clipH then
        local scrollRange = contentH - clipH
        local scrollRatio = (scrollRange > 0) and (-fragShopScroll.offset / scrollRange) or 0
        local barVisH = math.max(24, clipH * clipH / contentH)
        local barPosY = clipTop + scrollRatio * (clipH - barVisH)
        nvgBeginPath(vg); nvgRoundedRect(vg, W - 5, barPosY, 3, barVisH, 1.5)
        nvgFillColor(vg, nvgRGBA(180, 160, 220, 70)); nvgFill(vg)
    end
end

-- ============================================================================
-- 武灵录 (图鉴界面) - 设计坐标
-- ============================================================================
function DrawCodexScreen()
    if gameState.phase ~= "CODEX" then return end

    local W = DESIGN_W
    local H = DESIGN_H
    local cx = W / 2
    local t = menuAnimTimer

    -- 1. 统一菜单背景
    DrawMenuBg(W, H)

    nvgFontFaceId(vg, GetMainFont())

    -- 顶部栏参数 (按钮绘制移到卡牌之后, 确保在卡牌上层)
    local topBarY = 12
    local backW, backH = 110, 48
    local backX = 10

    -- ===========================
    -- 2. 品质标签页过滤
    -- ===========================
    local TAB_DEFS = {
        { label = "全部", quality = nil },
        { label = "N",    quality = QUALITY.COMMON },
        { label = "R",    quality = QUALITY.RARE },
        { label = "SR",   quality = QUALITY.EPIC },
        { label = "SSR",  quality = QUALITY.LEGENDARY },
        { label = "限定",  quality = QUALITY.LIMITED },
    }
    -- 构建过滤后的卡牌列表 { origIdx, card }
    local filteredCards = {}
    for i = 1, #HERO_CARDS do
        local card = HERO_CARDS[i]
        local match = false
        if codexTab == 0 then
            match = true
        elseif TAB_DEFS[codexTab + 1].quality == QUALITY.LEGENDARY then
            -- SSR标签页同时显示SSR和限定SSR
            match = (card.quality == QUALITY.LEGENDARY or card.quality == QUALITY.LIMITED)
        else
            match = (card.quality == TAB_DEFS[codexTab + 1].quality)
        end
        if match then
            filteredCards[#filteredCards + 1] = { origIdx = i, card = card }
        end
    end

    -- ===========================
    -- 3. 英雄网格 (3列大卡牌, 可滚动) — 先绘制，在底层
    -- ===========================
    local cols = 3
    local gap = 12
    local cardW = math.floor((W - 28 - (cols - 1) * gap) / cols)
    local cardH = cardW / CARD_RATIO
    local gridW = cols * cardW + (cols - 1) * gap
    local startX = cx - gridW / 2
    local startY = 110  -- 为标签页留空间
    local bottomPad = 40  -- 底部留白

    -- 计算内容总高度和滚动边界
    local totalRows = math.ceil(#filteredCards / cols)
    local contentH = totalRows * (cardH + gap + 4) - (gap + 4)
    local visibleH = H - startY - bottomPad
    local maxScrollY = 0
    local minScrollY = math.min(0, -(contentH - visibleH))

    -- 钳制滚动范围
    codexScroll.y = math.max(minScrollY, math.min(maxScrollY, codexScroll.y))

    -- 滚动区域裁剪 (严格限制在 startY 以下, 防止卡片遮挡顶部按钮)
    nvgSave(vg)
    nvgScissor(vg, 0, startY, W, visibleH)

    codexCardRects = {}
    for fi = 1, #filteredCards do
        local entry = filteredCards[fi]
        local idx = entry.origIdx
        local card = entry.card
        local col = ((fi - 1) % cols)
        local row = math.floor((fi - 1) / cols)
        local x = startX + col * (cardW + gap)
        local y = startY + row * (cardH + gap + 4) + codexScroll.y
        local hero = playerHeroes[idx]

        -- 存储点击区域 (用原始索引作为key, 兼容EndPress点击检测)
        codexCardRects[idx] = { x = x, y = y, w = cardW, h = cardH }

        -- 跳过完全不可见的卡牌
        if y + cardH >= startY and y <= startY + visibleH then
            if hero and hero.owned then
                -- 已拥有: 正常绘制
                DrawInventoryCard(x, y, cardW, cardH, card, hero.constellation, false)
            else
                -- 未拥有: 灰暗效果
                -- 暗底板
                nvgBeginPath(vg); nvgRoundedRect(vg, x, y, cardW, cardH, 4)
                nvgFillColor(vg, nvgRGBA(28, 25, 20, 240)); nvgFill(vg)

                -- 角色图 (暗淡)
                local _shC, _scC, _srC = GetHeroSheetInfo(card)
                if _shC > 0 then
                    nvgGlobalAlpha(vg, 0.2)
                    DrawCardImage(x + 3, y + 3, cardW - 6, cardH - 20, _shC, card.row, card.col, _scC, _srC)
                    nvgGlobalAlpha(vg, 1.0)
                end

                -- 暗色遮罩
                nvgBeginPath(vg); nvgRoundedRect(vg, x, y, cardW, cardH, 4)
                nvgFillColor(vg, nvgRGBA(10, 10, 15, 140)); nvgFill(vg)

                -- 边框
                nvgBeginPath(vg); nvgRoundedRect(vg, x, y, cardW, cardH, 4)
                nvgStrokeColor(vg, nvgRGBA(60, 55, 45, 120))
                nvgStrokeWidth(vg, 1); nvgStroke(vg)

                -- "?" 标记
                nvgFontSize(vg, 57)
                nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
                DrawWhiteInkText(x + cardW / 2, y + (cardH - 24) / 2, "?")

                -- 品质边框色 (未解锁也显示品质色)
                local uqc = QUALITY_COLORS[card.quality]
                nvgBeginPath(vg); nvgRoundedRect(vg, x, y, cardW, cardH, 4)
                nvgStrokeColor(vg, nvgRGBA(uqc[1], uqc[2], uqc[3], 80))
                nvgStrokeWidth(vg, 1); nvgStroke(vg)

                -- 左上角品质标签 (未解锁也显示 N/R/SR/SSR)
                local uqTag = QUALITY_TAGS[card.quality] or "N"
                local uTagW = #uqTag > 2 and 26 or (#uqTag > 1 and 20 or 14)
                local uTagH = 13
                nvgBeginPath(vg); nvgRoundedRect(vg, x + 2, y + 2, uTagW, uTagH, 2)
                nvgFillColor(vg, nvgRGBA(uqc[1], uqc[2], uqc[3], 140)); nvgFill(vg)
                nvgFontSize(vg, 16)
                nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
                DrawWhiteInkText(x + 2 + uTagW / 2, y + 2 + uTagH / 2, uqTag)

                -- 底部名条 (暗色)
                local nameBarH = 24
                local nameBarY = y + cardH - nameBarH
                nvgBeginPath(vg)
                nvgRoundedRect(vg, x + 1, nameBarY, cardW - 2, nameBarH, 0)
                nvgFillColor(vg, nvgRGBA(28, 24, 16, 210)); nvgFill(vg)
                nvgFontSize(vg, 25)
                nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
                DrawWhiteInkText(x + cardW / 2, nameBarY + nameBarH / 2, "???")
            end
        end
    end

    nvgRestore(vg)

    -- ===========================
    -- 3. 顶部栏: 返回 + 标题 + 统计 (在卡牌之后绘制，确保在最上层)
    -- ===========================
    -- 先绘制不透明背景条遮住卡牌
    nvgBeginPath(vg); nvgRect(vg, 0, 0, W, startY)
    nvgFillColor(vg, nvgRGBA(15, 20, 38, 230)); nvgFill(vg)

    -- 返回按钮
    nvgBeginPath(vg)
    nvgRoundedRect(vg, backX, topBarY, backW, backH, 8)
    nvgFillColor(vg, nvgRGBA(32, 38, 58, 200)); nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(162, 128, 78, 170)); nvgStrokeWidth(vg, 1.5); nvgStroke(vg)
    nvgFontSize(vg, 28)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(backX + backW / 2, topBarY + backH / 2, "< 返回")
    codexBackBtnRect = { x = backX, y = topBarY, w = backW, h = backH }

    -- 标题
    nvgFontSize(vg, 45)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(cx, topBarY + backH / 2, "武灵录")

    -- 收集统计
    local ownedCount = 0
    for _, h in pairs(playerHeroes) do
        if h.owned then ownedCount = ownedCount + 1 end
    end
    nvgFontSize(vg, 27)
    nvgTextAlign(vg, NVG_ALIGN_RIGHT + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(W - 14, topBarY + backH / 2, ownedCount .. "/" .. #HERO_CARDS)

    -- ===========================
    -- 4. 品质标签页按钮
    -- ===========================
    local tabY = topBarY + backH + 8
    local tabH = 30
    local tabTotalW = W - 20
    local tabCount = #TAB_DEFS
    local tabGap = 6
    local tabW = math.floor((tabTotalW - (tabCount - 1) * tabGap) / tabCount)
    local tabStartX = 10
    codexTabRects = {}
    local TAB_QUALITY_COLORS = {
        [0] = {160, 160, 160},                     -- 全部: 灰白
        [1] = {160, 180, 160},                     -- N: 灰绿
        [2] = {80, 180, 255},                      -- R: 蓝
        [3] = {200, 130, 255},                     -- SR: 紫
        [4] = {255, 200, 60},                      -- SSR: 金
        [5] = {255, 80, 120},                      -- 限定: 红粉
    }
    for ti = 1, tabCount do
        local tabIdx = ti - 1
        local tx = tabStartX + (ti - 1) * (tabW + tabGap)
        local isActive = (codexTab == tabIdx)
        local tc = TAB_QUALITY_COLORS[tabIdx]
        -- 按钮背景
        nvgBeginPath(vg); nvgRoundedRect(vg, tx, tabY, tabW, tabH, 6)
        if isActive then
            nvgFillColor(vg, nvgRGBA(tc[1], tc[2], tc[3], 50)); nvgFill(vg)
            nvgStrokeColor(vg, nvgRGBA(tc[1], tc[2], tc[3], 220)); nvgStrokeWidth(vg, 2); nvgStroke(vg)
        else
            nvgFillColor(vg, nvgRGBA(30, 35, 50, 180)); nvgFill(vg)
            nvgStrokeColor(vg, nvgRGBA(80, 75, 65, 100)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
        end
        -- 标签文字
        nvgFontSize(vg, 22)
        nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        if isActive then
            nvgFillColor(vg, nvgRGBA(tc[1], tc[2], tc[3], 255))
        else
            nvgFillColor(vg, nvgRGBA(180, 175, 165, 160))
        end
        nvgText(vg, tx + tabW / 2, tabY + tabH / 2, TAB_DEFS[ti].label, nil)
        -- 数量角标
        local tabQCount = 0
        for hIdx, h in pairs(playerHeroes) do
            if h.owned then
                local c = HERO_CARDS[hIdx]
                if c then
                    local tabMatch = false
                    if tabIdx == 0 then
                        tabMatch = true
                    elseif TAB_DEFS[ti].quality == QUALITY.LEGENDARY then
                        tabMatch = (c.quality == QUALITY.LEGENDARY or c.quality == QUALITY.LIMITED)
                    else
                        tabMatch = (c.quality == TAB_DEFS[ti].quality)
                    end
                    if tabMatch then tabQCount = tabQCount + 1 end
                end
            end
        end
        if tabQCount > 0 and not isActive then
            nvgFontSize(vg, 16)
            nvgTextAlign(vg, NVG_ALIGN_RIGHT + NVG_ALIGN_TOP)
            nvgFillColor(vg, nvgRGBA(tc[1], tc[2], tc[3], 140))
            nvgText(vg, tx + tabW - 2, tabY + 1, tostring(tabQCount), nil)
        end
        -- 存储点击区域
        codexTabRects[ti] = { x = tx, y = tabY, w = tabW, h = tabH, tabIdx = tabIdx }
    end

    -- 滚动条指示器 (内容超出可见区域时显示)
    if contentH > visibleH then
        local scrollBarH = math.max(30, visibleH * (visibleH / contentH))
        local scrollRange = visibleH - scrollBarH
        local scrollRatio = codexScroll.y / minScrollY  -- 0~1
        local scrollBarY = startY + scrollRange * scrollRatio
        nvgBeginPath(vg)
        nvgRoundedRect(vg, W - 6, scrollBarY, 3, scrollBarH, 1.5)
        nvgFillColor(vg, nvgRGBA(180, 160, 120, math.floor(60 + 40 * scrollRatio)))
        nvgFill(vg)
    end

    -- 底部装饰文字
    nvgFontSize(vg, 19)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    local tipPulse = 0.4 + 0.6 * math.abs(math.sin(t * 1.2))
    local tipInkAlpha = math.floor(100 * tipPulse)
    nvgFillColor(vg, nvgRGBA(255, 255, 255, math.floor(tipInkAlpha * 0.54)))
    nvgText(vg, cx - 1, H - 20, "集齐武灵, 天道可期", nil)
    nvgText(vg, cx + 1, H - 20, "集齐武灵, 天道可期", nil)
    nvgText(vg, cx, H - 21, "集齐武灵, 天道可期", nil)
    nvgText(vg, cx, H - 19, "集齐武灵, 天道可期", nil)
    nvgFillColor(vg, nvgRGBA(30, 25, 20, tipInkAlpha))
    nvgText(vg, cx, H - 20, "集齐武灵, 天道可期", nil)

    -- 漂浮粒子
    for i = 1, 5 do
        local px = W * (0.1 + 0.8 * ((i * 97 + math.floor(t * 15)) % 100) / 100)
        local py = H * (0.05 + 0.12 * math.sin(t * 0.5 + i * 1.8))
        local pr = 1 + math.sin(t * 1.8 + i) * 0.5
        local pa = math.floor(25 + 18 * math.sin(t * 1.3 + i * 0.9))
        nvgBeginPath(vg); nvgCircle(vg, px, py, pr)
        nvgFillColor(vg, nvgRGBA(200, 210, 240, pa)); nvgFill(vg)
    end
end

-- ============================================================================
-- 武灵详情养成页 - 设计坐标
-- ============================================================================
function DrawHeroDetailScreen()
    if gameState.phase ~= "HERO_DETAIL" then return end

    local idx = heroDetailState.cardIdx
    if idx < 1 or idx > #HERO_CARDS then return end

    local card = HERO_CARDS[idx]
    local hero = playerHeroes[idx]
    if not hero or not hero.owned then return end

    local W = DESIGN_W
    local H = DESIGN_H
    local cx = W / 2
    local t = menuAnimTimer
    local cons = hero.constellation

    -- 1. 统一菜单背景
    DrawMenuBg(W, H)

    nvgFontFaceId(vg, GetMainFont())

    -- 2. 顶部栏: 返回 + 标题
    local topBarY = 14
    local backW, backH = 100, 40
    local backX = 12
    nvgBeginPath(vg); nvgRoundedRect(vg, backX, topBarY, backW, backH, 4)
    nvgFillColor(vg, nvgRGBA(20, 25, 40, 180)); nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(90, 45, 55, 140)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
    nvgFontSize(vg, 24)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(backX + backW / 2, topBarY + backH / 2, "< 返回")
    heroDetailBackBtnRect = { x = backX, y = topBarY, w = backW, h = backH }

    nvgFontSize(vg, 39)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(cx, topBarY + backH / 2, "武灵详情")

    -- 3. 大卡牌 (居中上部)
    local bigCardW = 160
    local bigCardH = bigCardW / CARD_RATIO
    local bigCardX = cx - bigCardW / 2
    local bigCardY = 60
    DrawInventoryCard(bigCardX, bigCardY, bigCardW, bigCardH, card, cons, false)

    -- 4. 名称 + 基本信息（紧凑两行）
    local qName = QUALITY_NAMES[card.quality]
    local uc = UNIT_CLASS[card.unitClass]
    local infoY = bigCardY + bigCardH + 16

    -- 名称（大号白字）
    nvgFontSize(vg, 36)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(cx, infoY, card.name)

    -- 品质 | 兵种 | 站位（合并为一行）
    local posTag = ""
    if card.unitClass == "SHIELD" or card.unitClass == "CAVALRY" or card.unitClass == "LANCER" then
        posTag = "前排+50%"
    elseif card.unitClass == "ARCHER" or card.unitClass == "MAGE" then
        posTag = "后排+50%"
    elseif card.unitClass == "HEALER" then
        posTag = "后排+60%"
    elseif card.unitClass == "ASSASSIN" then
        posTag = "任意+20%"
    elseif card.unitClass == "BEAST" then
        posTag = "前排+50%"
    else
        posTag = "前排+50%"
    end
    nvgFontSize(vg, 22)
    DrawWhiteInkText(cx, infoY + 26, qName .. "  |  " .. (uc and uc.name or "未知") .. "  |  " .. posTag)

    -- 兵种描述
    if uc then
        nvgFontSize(vg, 20)
        DrawWhiteInkText(cx, infoY + 50, uc.desc)
    end

    -- 4.5 兵种战斗特性面板
    local traitY = infoY + 68
    if uc then
        local traitPanelW = W - 40
        local traitPanelX = 20

        -- 预计算特性数据
        local traits = {}
        local ucKey = card.unitClass
        if ucKey == "CAVALRY" then
            traits[#traits + 1] = { icon = "速", color = {255,200,80}, text = "冲锋突进: 不停留，沿途撞击伤害(120%ATK)" }
        elseif ucKey == "ASSASSIN" then
            traits[#traits + 1] = { icon = "隐", color = {180,100,255}, text = "绕后暗杀: 跨越路线包抄后排，背刺伤害x1.5" }
        elseif ucKey == "HEALER" then
            traits[#traits + 1] = { icon = "疗", color = {80,255,120}, text = "随军治疗: 跟随友军推进，沿途治疗最低血量友军" }
        elseif ucKey == "BEAST" then
            traits[#traits + 1] = { icon = "震", color = {255,160,50}, text = "范围震击: 边推进边打击前方所有挡路敌人(80%ATK)" }
        elseif ucKey == "LANCER" then
            traits[#traits + 1] = { icon = "贯", color = {200,220,255}, text = "贯穿攻击: 边推进边攻击，同时穿刺2个敌人" }
        elseif ucKey == "SHIELD" then
            traits[#traits + 1] = { icon = "盾", color = {100,200,255}, text = "铁壁防御: 不进攻，在己方半场站岗拦截过路敌人" }
        elseif ucKey == "ARCHER" then
            traits[#traits + 1] = { icon = "箭", color = {200,255,150}, text = "远程射击: 远距离锁定目标(120)，驻足瞄准射击" }
        elseif ucKey == "MAGE" then
            traits[#traits + 1] = { icon = "法", color = {200,150,255}, text = "法术轰击: 远距离锁定目标(110)，驻足施法轰击" }
        elseif ucKey == "TALISMAN" then
            traits[#traits + 1] = { icon = "符", color = {255,200,50}, text = "火牛冲阵: 全速冲锋，接触敌人后引爆造成250%范围伤害" }
        elseif ucKey == "PUPPETEER" then
            traits[#traits + 1] = { icon = "兽", color = {160,80,200}, text = "驱兽助战: 缓步推进，每4秒召唤1只走兽(上限4只)" }
        elseif ucKey == "ICE_MAGE" then
            traits[#traits + 1] = { icon = "冰", color = {80,200,255}, text = "霜冻减速: 远程攻击附带40%减速效果，持续2秒" }
        elseif ucKey == "SWARM" then
            traits[#traits + 1] = { icon = "蜂", color = {240,180,40}, text = "灵蜂涌袭: 一次派出6只，血薄但攻速极快(0.3s)" }
        else
            traits[#traits + 1] = { icon = "剑", color = {255,220,180}, text = "近战输出: 攻速快伤害均衡，边推进边斩杀挡路敌人" }
        end

        local statsLine = string.format("范围:%d  速度:%d  攻速:%.1fs  突破:%d",
            uc.atkRange, uc.speed, uc.atkCd, uc.breakDmg)
        if uc.spawnMax then
            statsLine = statsLine .. "  上限:" .. uc.spawnMax .. "只"
        end

        -- 先计算面板总高度: 标题(14) + 特性行(28+20*n) + 数值行(+20) + 规则行(+18) + 底边距(12)
        local contentBottom = 28 + #traits * 20 + 20 + 18
        local traitPanelH = contentBottom + 12

        -- 绘制背景
        nvgBeginPath(vg); nvgRoundedRect(vg, traitPanelX, traitY, traitPanelW, traitPanelH, 6)
        nvgFillColor(vg, nvgRGBA(20, 30, 45, 180)); nvgFill(vg)
        nvgStrokeColor(vg, nvgRGBA(80, 120, 180, 80)); nvgStrokeWidth(vg, 1); nvgStroke(vg)

        -- 标题
        nvgFontSize(vg, 18)
        nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)
        nvgFillColor(vg, nvgRGBA(120, 180, 255, 220))
        nvgText(vg, traitPanelX + 10, traitY + 14, "战斗特性", nil)

        -- 绘制特性
        nvgFontSize(vg, 17)
        for i, tr in ipairs(traits) do
            local ty = traitY + 28 + (i - 1) * 20
            nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
            nvgFillColor(vg, nvgRGBA(tr.color[1], tr.color[2], tr.color[3], 240))
            nvgText(vg, traitPanelX + 22, ty, "[" .. tr.icon .. "]", nil)
            nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)
            nvgFillColor(vg, nvgRGBA(220, 220, 230, 200))
            nvgText(vg, traitPanelX + 42, ty, tr.text, nil)
        end
        -- 数值行
        local numY = traitY + 28 + #traits * 20
        nvgFontSize(vg, 15)
        nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        nvgFillColor(vg, nvgRGBA(160, 170, 190, 160))
        nvgText(vg, cx, numY, statsLine, nil)

        -- 通用规则
        local ruleY = numY + 18
        nvgFontSize(vg, 14)
        nvgFillColor(vg, nvgRGBA(180, 160, 120, 140))
        local ruleText = "武灵首要目标: 进攻敌方基地"
        if ucKey == "SHIELD" then ruleText = "铁盾重卫驻守己方半场，不主动进攻"
        elseif ucKey == "TALISMAN" then ruleText = "火牛突袭全速冲锋，引爆后消亡"
        elseif ucKey == "PUPPETEER" then ruleText = "驯兽使缓步推进，召唤走兽代为作战"
        end
        nvgText(vg, cx, ruleY, ruleText, nil)

        traitY = traitY + traitPanelH + 4
    end

    -- 5. 属性面板 (含命格加成)
    local bonus = GetConstellationBonus(cons)
    local statsY = traitY + 6
    local panelW = W - 40
    local panelX = 20
    local panelH = 70

    nvgBeginPath(vg); nvgRoundedRect(vg, panelX, statsY, panelW, panelH, 6)
    nvgFillColor(vg, nvgRGBA(15, 18, 30, 180)); nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(90, 45, 55, 100)); nvgStrokeWidth(vg, 1); nvgStroke(vg)

    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    local statItems = {
        { label = "攻击", base = card.atk, mult = bonus.atkMult },
        { label = "防御", base = card.def, mult = bonus.defMult },
        { label = "生命", base = card.hp,  mult = bonus.hpMult },
    }
    local sCol = panelW / 3
    for si, st in ipairs(statItems) do
        local sx = panelX + (si - 0.5) * sCol
        local sy = statsY + 22
        -- 标签
        nvgFontSize(vg, 20)
        DrawWhiteInkText(sx, sy, st.label)
        -- 数值
        local finalVal = math.floor(st.base * st.mult)
        local valStr = tostring(finalVal)
        if st.mult > 1.0 then
            valStr = valStr .. string.format(" (+%d%%)", math.floor((st.mult - 1) * 100))
        end
        nvgFontSize(vg, 28)
        DrawWhiteInkText(sx, sy + 26, valStr)
    end

    -- 额外加成（突破伤害/出兵速率）
    local extraParts = {}
    if bonus.breakDmgAdd > 0 then
        extraParts[#extraParts + 1] = "突破伤害+" .. bonus.breakDmgAdd
    end
    if bonus.spawnRateMult > 1.0 then
        extraParts[#extraParts + 1] = string.format("出兵速率+%d%%", math.floor((bonus.spawnRateMult - 1) * 100))
    end
    local extraY = statsY + panelH + 6
    if #extraParts > 0 then
        nvgFontSize(vg, 20)
        nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        DrawWhiteInkText(cx, extraY, table.concat(extraParts, "  |  "))
        extraY = extraY + 20
    end

    -- 5.5 兵符总加成面板
    local sealBonus = GetSealTotalBonus(idx)
    local hasSealAny = sealBonus and (
        sealBonus.atkPct > 0 or sealBonus.defPct > 0 or sealBonus.hpPct > 0 or
        sealBonus.extraTroops > 0 or sealBonus.critRate > 0 or sealBonus.dmgReduction > 0 or
        sealBonus.speedPct > 0 or sealBonus.atkSpeedPct > 0 or sealBonus.counterRate > 0 or
        sealBonus.breakDmgPct > 0 or sealBonus.deathExplosionPct > 0)
    if hasSealAny then
        local sealPanelX = panelX
        local sealPanelW = panelW

        -- 收集非零加成行
        local sealEntries = {}
        local sealSlotData = sealData[idx]
        if sealSlotData and sealSlotData.slots then
            for i = 1, SEAL_MAX_SLOTS do
                local sealSlot = sealSlotData.slots[i]
                if sealSlot then
                    local effect = SEAL_SLOT_EFFECTS[i]
                    if effect then
                        local tierData = effect[sealSlot.sealQ] or effect[1]
                        local lv = sealSlot.level or 1
                        local mainVal = (tierData.main or 0) * lv
                        local subVal = (tierData.sub or 0) * lv
                        sealEntries[#sealEntries + 1] = {
                            slotIdx = i, theme = effect.theme, level = lv,
                            mainName = effect.mainName, mainVal = mainVal,
                            mainUnit = (effect.mainKey == "extraTroops") and "" or "%",
                            subName = effect.subName, subVal = subVal,
                        }
                    end
                end
            end
        end

        -- 汇总行：攻+X% 防+X% 血+X%
        local summaryParts = {}
        if sealBonus.atkPct > 0 then summaryParts[#summaryParts + 1] = "攻+" .. string.format("%.0f", sealBonus.atkPct) .. "%" end
        if sealBonus.defPct > 0 then summaryParts[#summaryParts + 1] = "防+" .. string.format("%.0f", sealBonus.defPct) .. "%" end
        if sealBonus.hpPct > 0 then summaryParts[#summaryParts + 1] = "血+" .. string.format("%.0f", sealBonus.hpPct) .. "%" end
        -- 特殊效果汇总
        if sealBonus.extraTroops > 0 then summaryParts[#summaryParts + 1] = "兵力+" .. string.format("%.1f", sealBonus.extraTroops) end
        if sealBonus.critRate > 0 then summaryParts[#summaryParts + 1] = "暴击+" .. string.format("%.0f", sealBonus.critRate) .. "%" end
        if sealBonus.dmgReduction > 0 then summaryParts[#summaryParts + 1] = "减伤+" .. string.format("%.0f", sealBonus.dmgReduction) .. "%" end
        if sealBonus.speedPct > 0 then summaryParts[#summaryParts + 1] = "移速+" .. string.format("%.0f", sealBonus.speedPct) .. "%" end
        if sealBonus.atkSpeedPct > 0 then summaryParts[#summaryParts + 1] = "攻速+" .. string.format("%.0f", sealBonus.atkSpeedPct) .. "%" end
        if sealBonus.counterRate > 0 then summaryParts[#summaryParts + 1] = "反击+" .. string.format("%.0f", sealBonus.counterRate) .. "%" end
        if sealBonus.breakDmgPct > 0 then summaryParts[#summaryParts + 1] = "突破+" .. string.format("%.0f", sealBonus.breakDmgPct) .. "%" end
        if sealBonus.deathExplosionPct > 0 then summaryParts[#summaryParts + 1] = "爆炸+" .. string.format("%.0f", sealBonus.deathExplosionPct) .. "%" end

        -- 面板高度: 标题(28) + 汇总行(20) + 详情行(每行18) + 底边距(8)
        local sealPanelH = 28 + 22 + #sealEntries * 18 + 8

        nvgBeginPath(vg); nvgRoundedRect(vg, sealPanelX, extraY, sealPanelW, sealPanelH, 6)
        nvgFillColor(vg, nvgRGBA(25, 20, 15, 190)); nvgFill(vg)
        nvgStrokeColor(vg, nvgRGBA(200, 170, 80, 80)); nvgStrokeWidth(vg, 1); nvgStroke(vg)

        -- 标题
        nvgFontSize(vg, 18)
        nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)
        nvgFillColor(vg, nvgRGBA(255, 215, 80, 230))
        nvgText(vg, sealPanelX + 10, extraY + 14, "兵符总加成", nil)

        -- 汇总行
        nvgFontSize(vg, 17)
        nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        nvgFillColor(vg, nvgRGBA(100, 255, 130, 220))
        nvgText(vg, cx, extraY + 38, table.concat(summaryParts, "  "), nil)

        -- 详情行
        nvgFontSize(vg, 15)
        nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)
        for ei, se in ipairs(sealEntries) do
            local ey = extraY + 50 + (ei - 1) * 18
            local tc2 = SEAL_SLOT_THEME_COLORS[se.slotIdx] or { 200, 200, 200 }
            nvgFillColor(vg, nvgRGBA(tc2[1], tc2[2], tc2[3], 210))
            local txt = SEAL_SLOT_NAMES[se.slotIdx] .. " " .. se.theme
            if se.mainName then
                txt = txt .. "  " .. se.mainName .. "+" .. string.format("%.1f", se.mainVal) .. se.mainUnit
            end
            if se.subName and se.subVal > 0 then
                txt = txt .. "  " .. se.subName .. "+" .. string.format("%.1f", se.subVal) .. "%"
            end
            txt = txt .. "  Lv" .. se.level
            nvgText(vg, sealPanelX + 10, ey, txt, nil)
        end

        extraY = extraY + sealPanelH + 6
    end

    -- 6. 命格进度 (C0~C6 横排)
    local constY = extraY + 10
    nvgFontSize(vg, 26)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(cx, constY, "命格进度")

    local constStartY = constY + 22
    local nodeR = 16
    local nodeGap = (W - 60) / 7
    local nodeStartX = 30 + nodeGap / 2

    for c = 0, GameConfig.MAX_CONSTELLATION do
        local nx = nodeStartX + c * nodeGap
        local ny = constStartY + nodeR
        local isActive = c <= cons
        local isCurrent = c == cons

        -- 连接线
        if c < GameConfig.MAX_CONSTELLATION then
            local nextActive = (c + 1) <= cons
            nvgBeginPath(vg)
            nvgMoveTo(vg, nx + nodeR, ny)
            nvgLineTo(vg, nx + nodeGap - nodeR, ny)
            nvgStrokeWidth(vg, 2)
            nvgStrokeColor(vg, nvgRGBA(180, 155, 100, nextActive and 180 or 40))
            nvgStroke(vg)
        end

        -- 节点圆
        if isCurrent then
            local pulse = 0.6 + 0.4 * math.sin(t * 3)
            local glowR = nodeR + 6 * pulse
            local glow = nvgRadialGradient(vg, nx, ny, nodeR - 2, glowR,
                nvgRGBA(220, 190, 120, math.floor(60 * pulse)),
                nvgRGBA(220, 190, 120, 0))
            nvgBeginPath(vg); nvgCircle(vg, nx, ny, glowR)
            nvgFillPaint(vg, glow); nvgFill(vg)
        end

        nvgBeginPath(vg); nvgCircle(vg, nx, ny, nodeR)
        if isActive then
            nvgFillColor(vg, nvgRGBA(200, 170, 100, 220))
        else
            nvgFillColor(vg, nvgRGBA(40, 38, 35, 200))
        end
        nvgFill(vg)
        nvgStrokeWidth(vg, isCurrent and 2 or 1)
        nvgStrokeColor(vg, nvgRGBA(200, 170, 100, isActive and 220 or 50))
        nvgStroke(vg)

        -- 节点文字
        nvgFontSize(vg, 20)
        nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        if isActive then
            DrawWhiteInkText(nx, ny, "C" .. c)
        else
            nvgFillColor(vg, nvgRGBA(255, 255, 255, 60))
            nvgText(vg, nx, ny, "C" .. c, nil)
        end

        -- 下方加成标注
        local bonusC = GameConfig.CONSTELLATION_BONUS[c]
        if bonusC then
            nvgFontSize(vg, 10)
            nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_TOP)
            local atkPct = math.floor((bonusC.atkMult - 1) * 100)
            local label = atkPct > 0 and ("+" .. atkPct .. "%") or "基础"
            if isActive then
                DrawWhiteInkText(nx, ny + nodeR + 3, label)
            else
                nvgFillColor(vg, nvgRGBA(200, 190, 160, 50))
                nvgText(vg, nx, ny + nodeR + 3, label, nil)
            end
        end
    end

    -- 7. 人物生平面板
    if card.bio then
        local bioY = constStartY + nodeR * 2 + 30
        local bioPanelW = W - 40
        local bioPanelX = 20
        local bioText = card.bio
        -- 预计算文本高度
        nvgFontFaceId(vg, GetMainFont())
        nvgFontSize(vg, 18)
        local textW = bioPanelW - 24
        local bounds = {}
        nvgTextBoxBounds(vg, bioPanelX + 12, 0, textW, bioText, bounds)
        local textH = bounds[4] - bounds[2]
        local bioPanelH = 14 + 20 + 8 + textH + 12  -- 顶边距+标题行+间距+文本+底边距

        -- 面板背景
        nvgBeginPath(vg); nvgRoundedRect(vg, bioPanelX, bioY, bioPanelW, bioPanelH, 6)
        nvgFillColor(vg, nvgRGBA(20, 30, 45, 180)); nvgFill(vg)
        nvgStrokeColor(vg, nvgRGBA(180, 155, 100, 80)); nvgStrokeWidth(vg, 1); nvgStroke(vg)

        -- 标题
        nvgFontSize(vg, 18)
        nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)
        nvgFillColor(vg, nvgRGBA(200, 175, 120, 220))
        nvgText(vg, bioPanelX + 10, bioY + 14, "人物生平", nil)

        -- 装饰短线
        nvgBeginPath(vg)
        nvgMoveTo(vg, bioPanelX + 10, bioY + 26)
        nvgLineTo(vg, bioPanelX + bioPanelW - 10, bioY + 26)
        nvgStrokeColor(vg, nvgRGBA(180, 155, 100, 40)); nvgStrokeWidth(vg, 0.5); nvgStroke(vg)

        -- 生平文本（自动换行）
        nvgFontSize(vg, 18)
        nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_TOP)
        nvgFillColor(vg, nvgRGBA(210, 210, 220, 200))
        nvgTextBox(vg, bioPanelX + 12, bioY + 34, textW, bioText)
    end

    -- 漂浮粒子
    for i = 1, 4 do
        local px = W * (0.1 + 0.8 * ((i * 113 + math.floor(t * 16)) % 100) / 100)
        local py = H * (0.05 + 0.12 * math.sin(t * 0.5 + i * 1.6))
        local pr = 1 + math.sin(t * 1.8 + i) * 0.5
        local pa = math.floor(20 + 16 * math.sin(t * 1.3 + i * 0.9))
        nvgBeginPath(vg); nvgCircle(vg, px, py, pr)
        nvgFillColor(vg, nvgRGBA(200, 210, 240, pa)); nvgFill(vg)
    end
end

-- ============================================================================
-- 玩家详情页 - 设计坐标
-- ============================================================================
function DrawPlayerDetailScreen()
    if gameState.phase ~= "PLAYER_DETAIL" then return end

    local W = DESIGN_W
    local H = DESIGN_H
    local cx = W / 2
    local t = menuAnimTimer

    -- 1. 统一菜单背景
    DrawMenuBg(W, H)

    nvgFontFaceId(vg, GetMainFont())

    -- 2. 顶部栏
    local topBarY = 14
    local backW, backH = 120, 50
    local backX = 10
    local backY = 8
    nvgBeginPath(vg); nvgRoundedRect(vg, backX, backY, backW, backH, 6)
    nvgFillColor(vg, nvgRGBA(40, 20, 15, 220)); nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(180, 140, 70, 200)); nvgStrokeWidth(vg, 1.5); nvgStroke(vg)
    nvgFontSize(vg, 28)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(backX + backW / 2, backY + backH / 2, "< 返回")
    playerDetailBackBtnRect = { x = backX, y = backY, w = backW, h = backH }

    nvgFontSize(vg, 39)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(cx, 33, "冒险者详情")

    -- 3. 头像区 (大头像 + 名字 + 职务)
    local avatarSize = 88
    local avatarX = cx - avatarSize / 2
    local avatarY = 68
    -- 头像边框
    nvgBeginPath(vg); nvgRoundedRect(vg, avatarX - 3, avatarY - 3, avatarSize + 6, avatarSize + 6, 8)
    nvgFillColor(vg, nvgRGBA(90, 45, 55, 200)); nvgFill(vg)
    -- 头像图 (用IMG.avatarSheet)
    if IMG.avatarSheet >= 0 then
        local avData = AVATAR_DATA[playerInfo.avatarIdx] or AVATAR_DATA[1]
        local imgW, imgH = 512, 768
        local cellW = imgW / AVATAR_COLS
        local cellH = imgH / AVATAR_ROWS
        local sx = avData.col * cellW
        local sy = avData.row * cellH
        local pat = nvgImagePattern(vg, avatarX - sx * (avatarSize / cellW),
            avatarY - sy * (avatarSize / cellH),
            imgW * (avatarSize / cellW), imgH * (avatarSize / cellH),
            0, IMG.avatarSheet, 1.0)
        nvgBeginPath(vg); nvgRoundedRect(vg, avatarX, avatarY, avatarSize, avatarSize, 5)
        nvgFillPaint(vg, pat); nvgFill(vg)
    end

    local nameY = avatarY + avatarSize + 24
    nvgFontSize(vg, 39)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(cx, nameY, playerInfo.name)

    local factionInfoProfile = CloudManager.GetFactionInfo()
    local profileRoleText = ""
    if factionInfoProfile and factionInfoProfile.name and #factionInfoProfile.name > 0 then
        profileRoleText = factionInfoProfile.name .. " · " .. (CloudManager.GetRoleName(factionInfoProfile.role) or "成员")
    else
        profileRoleText = "无阵营"
    end
    nvgFontSize(vg, 27)
    DrawWhiteInkText(cx, nameY + 36, profileRoleText)

    -- 经验条
    local expBarW = 240
    local expBarH = 12
    local expBarX = cx - expBarW / 2
    local expBarY = nameY + 68
    nvgBeginPath(vg); nvgRoundedRect(vg, expBarX, expBarY, expBarW, expBarH, 4)
    nvgFillColor(vg, nvgRGBA(30, 30, 40, 200)); nvgFill(vg)
    local maxRank = #GameConfig.RANK_EXP_TABLE
    local isMaxLevel = playerInfo.rankIdx >= maxRank
    local curRankExp = GameConfig.RANK_EXP_TABLE[playerInfo.rankIdx] or 0
    local nextRankExp = GameConfig.RANK_EXP_TABLE[playerInfo.rankIdx + 1]
    local expRatio = 1.0
    if not isMaxLevel and nextRankExp then
        expRatio = math.min(1, (playerInfo.exp - curRankExp) / math.max(1, nextRankExp - curRankExp))
    end
    local fillW = expBarW * expRatio
    if fillW > 1 then
        local expGrad = nvgLinearGradient(vg, expBarX, expBarY, expBarX + fillW, expBarY,
            nvgRGBA(100, 200, 255, 220), nvgRGBA(80, 160, 220, 220))
        nvgBeginPath(vg); nvgRoundedRect(vg, expBarX, expBarY, fillW, expBarH, 4)
        nvgFillPaint(vg, expGrad); nvgFill(vg)
    end
    nvgFontSize(vg, 29)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    if isMaxLevel then
        DrawWhiteInkText(cx, expBarY + expBarH + 20, "已满级")
    else
        DrawWhiteInkText(cx, expBarY + expBarH + 20,
            string.format("经验: %d / %d", playerInfo.exp - curRankExp, nextRankExp - curRankExp))
    end

    -- 3.4 编辑资料按钮 (头像右侧)
    local editBtnW, editBtnH = 80, 30
    local editBtnX = cx + avatarSize / 2 + 12
    local editBtnY = avatarY + avatarSize / 2 - editBtnH / 2
    nvgBeginPath(vg); nvgRoundedRect(vg, editBtnX, editBtnY, editBtnW, editBtnH, 5)
    nvgFillColor(vg, nvgRGBA(50, 40, 60, 200)); nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(180, 160, 120, 150)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
    nvgFontSize(vg, 22)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    nvgFillColor(vg, nvgRGBA(220, 210, 180, 220))
    nvgText(vg, editBtnX + editBtnW / 2, editBtnY + editBtnH / 2, "编辑资料", nil)
    playerDetailEditBtnRect = { x = editBtnX, y = editBtnY, w = editBtnW, h = editBtnH }

    -- 3.5 战力评分 (居中金色大字)
    local powerY = expBarY + expBarH + 52
    local myTotalPower = CalcPlayerTotalPower()
    nvgFontSize(vg, 33)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    local powerText = "总战力 " .. FormatPower(myTotalPower)
    DrawWhiteInkText(cx, powerY, powerText)

    -- "?" 按钮 (战力说明)
    local powerTextW = nvgTextBounds(vg, 0, 0, powerText, nil)
    local qBtnX = cx + powerTextW / 2 + 8
    local qBtnR = 12
    nvgBeginPath(vg); nvgCircle(vg, qBtnX, powerY, qBtnR)
    nvgFillColor(vg, nvgRGBA(80, 70, 55, 200)); nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(200, 180, 120, 180)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
    nvgFontSize(vg, 18)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    nvgFillColor(vg, nvgRGBA(255, 220, 120, 230))
    nvgText(vg, qBtnX, powerY, "?", nil)
    playerDetailPowerHelpRect = { cx = qBtnX, cy = powerY, r = qBtnR + 4, isCircle = true }

    -- 战力说明弹窗（已移至 DrawPowerExplainPopup，在 DrawPlayerDetailScreen 之后渲染，避免层级问题）

    -- 4. 统计面板
    local statsY = powerY + 34
    local panelW = W - 40
    local panelX = 20

    nvgBeginPath(vg); nvgRoundedRect(vg, panelX, statsY, panelW, 110, 6)
    nvgFillColor(vg, nvgRGBA(15, 18, 30, 180)); nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(90, 45, 55, 100)); nvgStrokeWidth(vg, 1); nvgStroke(vg)

    -- 统计数据
    local ownedCount = 0
    local totalConst = 0
    for _, h in pairs(playerHeroes) do
        if h.owned then
            ownedCount = ownedCount + 1
            totalConst = totalConst + h.constellation
        end
    end

    local stats = {
        { label = "虎符", value = FormatJade(playerInfo.jade) },
        { label = "武灵收集", value = ownedCount .. "/" .. #HERO_CARDS },
        { label = "总命格", value = tostring(totalConst) },
    }
    local sColW = panelW / #stats
    for si, st in ipairs(stats) do
        local sx = panelX + (si - 1) * sColW + sColW / 2
        local sy = statsY + 26
        nvgFontSize(vg, 29)
        nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        DrawWhiteInkText(sx, sy, st.label)
        nvgFontSize(vg, 37)
        DrawWhiteInkText(sx, sy + 34, st.value)
    end

    -- 4.5 已装备武技栏
    local skillSectionY = statsY + 96
    nvgFontSize(vg, 31)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(cx, skillSectionY, "已装备武技")

    local skIconSize = 54
    local skSlotW = 80  -- 每个武技槽位总宽度 (图标+文字区域)
    local skCount = #playerEquippedSkills
    local skRowW = skCount * skSlotW
    local skStartX = cx - skRowW / 2
    local skStartY = skillSectionY + 24
    playerDetailSkillRects = playerDetailSkillRects or {}
    for k in pairs(playerDetailSkillRects) do playerDetailSkillRects[k] = nil end

    if skCount == 0 then
        nvgFontSize(vg, 29)
        DrawWhiteInkText(cx, skStartY + skIconSize / 2, "暂无装备武技")
    else
        for si, skIdx in ipairs(playerEquippedSkills) do
            local sk = SKILL_TECHNIQUES[skIdx]
            if sk then
                local skTier = SKILL_TIERS[sk.tier]
                local stc = skTier.color
                local slotCX = skStartX + (si - 1) * skSlotW + skSlotW / 2
                local mx = slotCX - skIconSize / 2
                local my = skStartY

                -- 底板
                nvgBeginPath(vg); nvgRoundedRect(vg, mx - 2, my - 2, skIconSize + 4, skIconSize + 4, 6)
                nvgFillColor(vg, nvgRGBA(stc[1], stc[2], stc[3], 60)); nvgFill(vg)
                nvgBeginPath(vg); nvgRoundedRect(vg, mx, my, skIconSize, skIconSize, 5)
                nvgFillColor(vg, nvgRGBA(15, 18, 30, 220)); nvgFill(vg)

                -- 图标
                drawSkillIcon(sk.iconIdx, mx + 3, my + 3, skIconSize - 6, 3)

                -- 边框
                nvgBeginPath(vg); nvgRoundedRect(vg, mx, my, skIconSize, skIconSize, 5)
                nvgStrokeColor(vg, nvgRGBA(stc[1], stc[2], stc[3], 150)); nvgStrokeWidth(vg, 1.2); nvgStroke(vg)

                -- 武技名 (限制宽度, 截断显示)
                nvgFontSize(vg, 21)
                nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_TOP)
                local maxTextW = skSlotW - 4
                local displayName = sk.name
                if nvgTextBounds(vg, 0, 0, displayName, nil) > maxTextW then
                    -- 截断到合适长度
                    for ci = #displayName - 1, 2, -1 do
                        local sub = string.sub(displayName, 1, ci) .. ".."
                        if nvgTextBounds(vg, 0, 0, sub, nil) <= maxTextW then
                            displayName = sub; break
                        end
                    end
                end
                DrawWhiteInkText(slotCX, my + skIconSize + 6, displayName)

                -- 存储点击区域
                playerDetailSkillRects[si] = { x = mx - 4, y = my - 4, w = skIconSize + 8, h = skIconSize + 28, skIdx = skIdx }
            end
        end
    end

    local skillSectionH = skIconSize + 36

    -- 5. 拥有武灵预览 (小卡牌横排, 带裁剪防超框)
    local previewY = skillSectionY + skillSectionH + 54
    nvgFontSize(vg, 31)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(cx, previewY, "我的武灵")

    local miniCardW = 64
    local miniCardH = miniCardW / CARD_RATIO
    local miniGap = 20
    local ownedList = {}
    for i = 1, #HERO_CARDS do
        if playerHeroes[i] and playerHeroes[i].owned then
            table.insert(ownedList, i)
        end
    end
    local rowCols = 5
    local miniStartY = previewY + 20
    -- 裁剪区域: 从 miniStartY 到 DESIGN_H 底部留少量间距
    local miniClipH = H - miniStartY - 8
    playerDetailHeroRects = playerDetailHeroRects or {}
    for k in pairs(playerDetailHeroRects) do playerDetailHeroRects[k] = nil end
    nvgSave(vg)
    nvgScissor(vg, 0, miniStartY, W, miniClipH)
    for oi, heroIdx in ipairs(ownedList) do
        local c = ((oi - 1) % rowCols)
        local r = math.floor((oi - 1) / rowCols)
        local gridW = rowCols * miniCardW + (rowCols - 1) * miniGap
        local mx = cx - gridW / 2 + c * (miniCardW + miniGap)
        local my = miniStartY + r * (miniCardH + miniGap + 4)
        -- 跳过完全在裁剪区域外的行
        if my + miniCardH < miniStartY or my > miniStartY + miniClipH then
            -- skip
        else
            local hCard = HERO_CARDS[heroIdx]
            local hCons = playerHeroes[heroIdx].constellation
            DrawInventoryCard(mx, my, miniCardW, miniCardH, hCard, hCons, false)
            playerDetailHeroRects[oi] = { x = mx, y = my, w = miniCardW, h = miniCardH, heroIdx = heroIdx }
        end
    end
    nvgRestore(vg)

    -- 漂浮粒子
    for i = 1, 5 do
        local px = W * (0.1 + 0.8 * ((i * 127 + math.floor(t * 14)) % 100) / 100)
        local py = H * (0.05 + 0.1 * math.sin(t * 0.45 + i * 1.7))
        local pr = 1 + math.sin(t * 1.6 + i) * 0.5
        local pa = math.floor(22 + 16 * math.sin(t * 1.2 + i * 1.0))
        nvgBeginPath(vg); nvgCircle(vg, px, py, pr)
        nvgFillColor(vg, nvgRGBA(200, 210, 240, pa)); nvgFill(vg)
    end
end

-- ============================================================================
-- 贡献榜详情独立界面（与战力排行榜同款样式，显示次数）
-- ============================================================================

function DrawContribRankScreen()
    local W = DESIGN_W
    local H = DESIGN_H
    local cx = W / 2
    local t = menuAnimTimer or 0

    -- 1. 统一菜单背景
    DrawMenuBg(W, H)
    nvgFontFaceId(vg, GetMainFont())

    -- 2. 返回按钮
    local backW, backH = 100, 44
    local backX, backY = 10, 10
    nvgBeginPath(vg); nvgRoundedRect(vg, backX, backY, backW, backH, 6)
    nvgFillColor(vg, nvgRGBA(30, 35, 50, 220)); nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(90, 45, 55, 160)); nvgStrokeWidth(vg, 1.5); nvgStroke(vg)
    nvgFontSize(vg, 29)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(backX + backW / 2, backY + backH / 2, "< 返回")
    menuBtnRects.contribRankBack = { x = backX, y = backY, w = backW, h = backH }

    -- 3. 标题
    nvgFontSize(vg, 39)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(cx, 32, "贡献排行榜")

    nvgFontSize(vg, 25)
    DrawWhiteInkText(cx, 56, "感谢每一次支持")

    -- 4. 排行列表区域
    local listTop = 76
    local listBottom = H - 12
    local listH = listBottom - listTop
    local secPad = 16
    local secW = W - secPad * 2

    local contribData = welfareState.contribRank
    local contribCount = contribData and #contribData or 0
    local rowH = 56
    local headerH = 44
    local contentH = math.max(listH, headerH + contribCount * rowH + 20)

    -- 滚动偏移
    local scrollOff = welfareState.contribDetailScroll.offset
    local minScroll = math.min(0, listH - contentH)
    scrollOff = math.max(minScroll, math.min(0, scrollOff))
    welfareState.contribDetailScroll.offset = scrollOff

    nvgSave(vg)
    nvgScissor(vg, 0, listTop, W, listH)

    local baseY = listTop + scrollOff

    -- 底板（暖色半透明，暗黑地牢风格）
    nvgBeginPath(vg); nvgRoundedRect(vg, secPad, baseY, secW, contentH, 10)
    nvgFillColor(vg, nvgRGBA(15, 12, 8, 190)); nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(90, 45, 55, 80)); nvgStrokeWidth(vg, 1.5); nvgStroke(vg)

    -- 表头
    local hy = baseY + 8
    nvgBeginPath(vg); nvgRoundedRect(vg, secPad + 6, hy, secW - 12, headerH - 4, 6)
    local headerGrad = nvgLinearGradient(vg, secPad, hy, secPad + secW, hy,
        nvgRGBA(80, 60, 30, 100), nvgRGBA(60, 45, 20, 60))
    nvgFillPaint(vg, headerGrad); nvgFill(vg)
    nvgFontSize(vg, 20)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    nvgFillColor(vg, nvgRGBA(200, 180, 140, 200))
    nvgText(vg, secPad + 30, hy + headerH / 2 - 2, "排名", nil)
    nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)
    nvgText(vg, secPad + 60, hy + headerH / 2 - 2, "道号", nil)
    nvgTextAlign(vg, NVG_ALIGN_RIGHT + NVG_ALIGN_MIDDLE)
    nvgText(vg, secPad + secW - 16, hy + headerH / 2 - 2, "次数", nil)

    -- 表头分隔线
    nvgBeginPath(vg); nvgMoveTo(vg, secPad + 10, hy + headerH - 2); nvgLineTo(vg, secPad + secW - 10, hy + headerH - 2)
    nvgStrokeColor(vg, nvgRGBA(90, 45, 55, 60)); nvgStrokeWidth(vg, 1); nvgStroke(vg)

    if welfareState.contribLoading and not welfareState.contribLoaded then
        nvgFontSize(vg, 26)
        nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        DrawWhiteInkText(cx, baseY + listH / 2, "加载中...")
    elseif contribCount == 0 then
        nvgFontSize(vg, 26)
        nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        DrawWhiteInkText(cx, baseY + listH / 2, "暂无数据，快去看广告上榜吧！")
    else
        local medals = {"[1]", "[2]", "[3]"}
        local rankColors = {
            nvgRGBA(255, 215, 80, 35),   -- 第1名 金
            nvgRGBA(210, 210, 220, 25),  -- 第2名 银
            nvgRGBA(200, 160, 90, 20),   -- 第3名 铜
        }
        for i, entry in ipairs(contribData) do
            local ry = baseY + headerH + 8 + (i - 1) * rowH
            -- 前3名暖金高亮底色
            if i <= 3 then
                nvgBeginPath(vg); nvgRoundedRect(vg, secPad + 6, ry + 2, secW - 12, rowH - 4, 6)
                nvgFillColor(vg, rankColors[i]); nvgFill(vg)
                nvgStrokeColor(vg, nvgRGBA(180, 145, 60, 40)); nvgStrokeWidth(vg, 0.5); nvgStroke(vg)
            elseif i % 2 == 0 then
                nvgBeginPath(vg); nvgRoundedRect(vg, secPad + 6, ry + 2, secW - 12, rowH - 4, 4)
                nvgFillColor(vg, nvgRGBA(255, 240, 200, 6)); nvgFill(vg)
            end

            -- 排名
            nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
            if i <= 3 then
                nvgFontSize(vg, 28)
                nvgText(vg, secPad + 30, ry + rowH / 2, medals[i], nil)
            else
                nvgFontSize(vg, 22)
                nvgFillColor(vg, nvgRGBA(180, 165, 130, 200))
                nvgText(vg, secPad + 30, ry + rowH / 2, "#" .. i, nil)
            end

            -- 道号
            nvgFontSize(vg, 24)
            nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)
            if i <= 3 then
                nvgFillColor(vg, nvgRGBA(255, 235, 175, 240))
            else
                nvgFillColor(vg, nvgRGBA(220, 210, 190, 220))
            end
            nvgText(vg, secPad + 60, ry + rowH / 2, entry.name, nil)

            -- 次数（暖金色）
            nvgFontSize(vg, 24)
            nvgTextAlign(vg, NVG_ALIGN_RIGHT + NVG_ALIGN_MIDDLE)
            if i <= 3 then
                nvgFillColor(vg, nvgRGBA(255, 200, 80, 240))
            else
                nvgFillColor(vg, nvgRGBA(220, 180, 100, 210))
            end
            nvgText(vg, secPad + secW - 16, ry + rowH / 2, tostring(entry.count) .. " 次", nil)

            -- 行间分隔线
            if i < contribCount then
                nvgBeginPath(vg)
                nvgMoveTo(vg, secPad + 20, ry + rowH)
                nvgLineTo(vg, secPad + secW - 20, ry + rowH)
                nvgStrokeColor(vg, nvgRGBA(90, 45, 55, 25))
                nvgStrokeWidth(vg, 0.5); nvgStroke(vg)
            end
        end
    end

    nvgRestore(vg)

    -- 幽冥粒子
    for i = 1, 6 do
        local px = W * (0.1 + 0.8 * ((i * 131 + math.floor(t * 16)) % 100) / 100)
        local py = H * (0.04 + 0.12 * math.sin(t * 0.5 + i * 1.5))
        local pr = 1 + math.sin(t * 1.8 + i) * 0.5
        local pa = math.floor(22 + 16 * math.sin(t * 1.3 + i * 0.9))
        nvgBeginPath(vg); nvgCircle(vg, px, py, pr)
        nvgFillColor(vg, nvgRGBA(220, 195, 140, pa)); nvgFill(vg)
    end
end

-- ============================================================================
-- 战力排行榜独立界面
-- ============================================================================

function DrawMailBoxScreen()
    local W, H = DESIGN_W, DESIGN_H
    local cx = W / 2
    local t = menuAnimTimer or 0
    local ms = welfareState.mail

    -- 1. 背景
    DrawMenuBg(W, H)
    nvgFontFaceId(vg, GetMainFont())

    -- 2. 返回按钮
    local backW, backH = 100, 44
    local backX, backY = 10, 10
    nvgBeginPath(vg); nvgRoundedRect(vg, backX, backY, backW, backH, 6)
    nvgFillColor(vg, nvgRGBA(30, 35, 50, 220)); nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(90, 45, 55, 160)); nvgStrokeWidth(vg, 1.5); nvgStroke(vg)
    nvgFontSize(vg, 29)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(backX + backW / 2, backY + backH / 2, "< 返回")
    menuBtnRects.mailBack = { x = backX, y = backY, w = backW, h = backH }

    -- 3. 标题 + UID显示
    nvgFontSize(vg, 30)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(cx, 32, "邮件")

    -- 右上角显示玩家UID (方便管理员确认身份)
    local myUid = rawget(_G, "clientCloud") and clientCloud.userId or 0
    nvgFontSize(vg, 11)
    nvgTextAlign(vg, NVG_ALIGN_RIGHT + NVG_ALIGN_TOP)
    nvgFillColor(vg, nvgRGBA(100, 100, 110, 140))
    nvgText(vg, W - 10, 6, "UID:" .. tostring(myUid), nil)
    -- 管理员标识
    if CloudManager.IsAdmin() then
        nvgFillColor(vg, nvgRGBA(255, 200, 60, 200))
        nvgText(vg, W - 10, 20, "[管理员]", nil)
    end
    -- 免广告状态
    if playerInfo.ad_free then
        nvgFillColor(vg, nvgRGBA(100, 255, 150, 180))
        nvgText(vg, W - 10, CloudManager.IsAdmin() and 34 or 20, "[免广告]", nil)
    end

    -- 4. Tab 栏: 系统邮件 / 玩家邮件 (非管理员只显示系统邮件)
    local pad = 14
    local tabY = 56
    local tabH = 36
    local isMailAdmin = CloudManager.IsAdmin()
    local tabs
    if isMailAdmin then
        tabs = { { id = "system", label = "系统邮件" }, { id = "cloud", label = "玩家邮件" } }
    else
        tabs = { { id = "system", label = "邮件" } }
        -- 非管理员强制切到 system tab
        if ms.tab == "cloud" then ms.tab = "system" end
    end
    -- 云邮件未读数
    local cloudUnread = 0
    for _, cm in ipairs(CloudManager._mailInbox or {}) do
        if not CloudManager.IsMailClaimed(cm.id) and #(cm.rewards or {}) > 0 then
            cloudUnread = cloudUnread + 1
        end
    end
    local tabW = (W - pad * 2) / #tabs
    for i, tb in ipairs(tabs) do
        local tx = pad + (i - 1) * tabW
        local sel = (ms.tab == tb.id)
        nvgBeginPath(vg); nvgRoundedRect(vg, tx + 2, tabY, tabW - 4, tabH, 6)
        nvgFillColor(vg, sel and nvgRGBA(90, 60, 30, 220) or nvgRGBA(30, 30, 40, 180)); nvgFill(vg)
        if sel then nvgStrokeColor(vg, nvgRGBA(255, 180, 60, 180)); nvgStrokeWidth(vg, 1.5); nvgStroke(vg) end
        nvgFontSize(vg, 18); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        nvgFillColor(vg, sel and nvgRGBA(255, 220, 100, 255) or nvgRGBA(180, 180, 180, 200))
        local lbl = tb.label
        if tb.id == "cloud" and cloudUnread > 0 then lbl = lbl .. "(" .. cloudUnread .. ")" end
        -- 非管理员在邮件Tab上显示未读云邮件数
        if not isMailAdmin and tb.id == "system" and cloudUnread > 0 then lbl = lbl .. "(" .. cloudUnread .. ")" end
        nvgText(vg, tx + tabW / 2, tabY + tabH / 2, lbl, nil)
        menuBtnRects["mailTab_" .. tb.id] = { x = tx + 2, y = tabY, w = tabW - 4, h = tabH }
    end

    local listTop = tabY + tabH + 8
    local listBottom = H - 12
    local listH = listBottom - listTop
    local cardGap = 10

    -- =============== 系统邮件 Tab ===============
    if ms.tab == "system" then
        local mailCardH = 220
        local cloudCardH = 130  -- 云邮件卡片高度
        ms.btnRects = {}
        if not isMailAdmin then ms.cloudBtnRects = {} end  -- 非管理员也需要云邮件领取按钮

        nvgSave(vg)
        nvgScissor(vg, 0, listTop, W, listH)

        local scrollOff = ms.scroll and ms.scroll.offset or 0
        local mailCount = #welfareState.mailDefs
        local inbox = not isMailAdmin and (CloudManager._mailInbox or {}) or {}
        local contentH = mailCount * (mailCardH + cardGap) - cardGap
        -- 非管理员: 系统邮件底部追加云邮件
        if #inbox > 0 then
            contentH = contentH + (mailCount > 0 and cardGap or 0) + #inbox * (cloudCardH + cardGap) - cardGap
        end
        local maxScroll = math.max(0, contentH - listH)
        if ms.scroll then
            if ms.scroll.offset > maxScroll then ms.scroll.offset = maxScroll; ms.scroll.vel = 0 end
            if ms.scroll.offset < 0 then ms.scroll.offset = 0; ms.scroll.vel = 0 end
            scrollOff = ms.scroll.offset
        end

        for i, mail in ipairs(welfareState.mailDefs) do
            local isClaimed = ms.claimed[mail.id] == true
            local cardY = listTop + (i - 1) * (mailCardH + cardGap) - scrollOff
            local cardX = pad
            local cardW = W - pad * 2

            nvgBeginPath(vg); nvgRoundedRect(vg, cardX, cardY, cardW, mailCardH, 10)
            if isClaimed then
                nvgFillColor(vg, nvgRGBA(20, 20, 25, 180)); nvgFill(vg)
                nvgStrokeColor(vg, nvgRGBA(60, 60, 70, 100)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
            else
                local glow = 0.8 + 0.2 * math.sin(t * 2.5)
                nvgFillColor(vg, nvgRGBA(30, 18, 10, math.floor(210 * glow))); nvgFill(vg)
                nvgStrokeColor(vg, nvgRGBA(255, 180, 80, math.floor(140 * glow))); nvgStrokeWidth(vg, 1.5); nvgStroke(vg)
            end

            nvgFontSize(vg, 14); nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_TOP)
            nvgFillColor(vg, nvgRGBA(140, 130, 110, isClaimed and 120 or 200))
            nvgText(vg, cardX + 12, cardY + 8, "来自: " .. mail.sender, nil)

            nvgFontSize(vg, 24); nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_TOP)
            if isClaimed then
                nvgFillColor(vg, nvgRGBA(120, 120, 120, 160))
                nvgText(vg, cardX + 12, cardY + 26, mail.title, nil)
            else
                DrawWhiteInkText(cardX + 12, cardY + 26, mail.title)
            end

            nvgFontSize(vg, 15); nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_TOP)
            nvgFillColor(vg, nvgRGBA(190, 180, 170, isClaimed and 100 or 210))
            local contentLines = {}
            local lineLen = 22
            local txt = mail.content
            while #txt > 0 do
                local seg, count, pos = "", 0, 1
                while pos <= #txt and count < lineLen do
                    local b = string.byte(txt, pos)
                    if b >= 0xE0 then seg = seg .. txt:sub(pos, pos + 2); pos = pos + 3
                    elseif b >= 0xC0 then seg = seg .. txt:sub(pos, pos + 1); pos = pos + 2
                    else seg = seg .. txt:sub(pos, pos); pos = pos + 1 end
                    count = count + 1
                end
                contentLines[#contentLines + 1] = seg
                txt = txt:sub(pos)
                if #contentLines >= 5 then break end
            end
            for li, line in ipairs(contentLines) do
                nvgText(vg, cardX + 12, cardY + 54 + (li - 1) * 22, line, nil)
            end

            local rwY = cardY + 54 + #contentLines * 22 + 8
            for ri, rw in ipairs(mail.rewards) do
                local rwX = cardX + 12 + (ri - 1) * 160
                nvgFontSize(vg, 16); nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_TOP)
                nvgFillColor(vg, nvgRGBA(rw.type == "jade" and 255 or 200, rw.type == "jade" and 220 or 160, rw.type == "jade" and 100 or 255, isClaimed and 100 or 230))
                nvgText(vg, rwX, rwY, rw.label, nil)
            end

            local btnW2, btnH2 = 100, 36
            local btnX2 = cardX + cardW - btnW2 - 12
            local btnY2 = cardY + mailCardH - btnH2 - 10
            if isClaimed then
                nvgFontSize(vg, 18); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
                nvgFillColor(vg, nvgRGBA(100, 100, 100, 140))
                nvgText(vg, btnX2 + btnW2 / 2, btnY2 + btnH2 / 2, "已领取", nil)
            else
                local bp = 0.85 + 0.15 * math.sin(t * 3.5 + i)
                nvgBeginPath(vg); nvgRoundedRect(vg, btnX2, btnY2, btnW2, btnH2, 8)
                nvgFillColor(vg, nvgRGBA(180, 80, 30, math.floor(220 * bp))); nvgFill(vg)
                nvgStrokeColor(vg, nvgRGBA(255, 200, 100, math.floor(180 * bp))); nvgStrokeWidth(vg, 1.5); nvgStroke(vg)
                nvgFontSize(vg, 20); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
                DrawWhiteInkText(btnX2 + btnW2 / 2, btnY2 + btnH2 / 2, "领取")
                ms.btnRects[i] = { x = btnX2, y = btnY2, w = btnW2, h = btnH2 }
            end

            if not isClaimed then
                local sparkle = math.sin(t * 4.0 + i * 2.0)
                if sparkle > 0.7 then
                    local sa = math.floor((sparkle - 0.7) / 0.3 * 80)
                    nvgBeginPath(vg); nvgRoundedRect(vg, cardX - 1, cardY - 1, cardW + 2, mailCardH + 2, 11)
                    nvgStrokeColor(vg, nvgRGBA(255, 220, 120, sa)); nvgStrokeWidth(vg, 2); nvgStroke(vg)
                end
            end
        end

        -- 非管理员: 系统邮件底部追加云邮件
        if not isMailAdmin and #inbox > 0 then
            local cloudStartY = listTop + mailCount * (mailCardH + cardGap)
            for i, cm in ipairs(inbox) do
                local isClaimed = CloudManager.IsMailClaimed(cm.id)
                local hasRewards = #(cm.rewards or {}) > 0
                local cardY = cloudStartY + (i - 1) * (cloudCardH + cardGap) - scrollOff
                local cardX = pad
                local cardW = W - pad * 2

                nvgBeginPath(vg); nvgRoundedRect(vg, cardX, cardY, cardW, cloudCardH, 10)
                if isClaimed or not hasRewards then
                    nvgFillColor(vg, nvgRGBA(20, 20, 25, 180)); nvgFill(vg)
                    nvgStrokeColor(vg, nvgRGBA(60, 60, 70, 100)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
                else
                    local glow = 0.8 + 0.2 * math.sin(t * 2.5)
                    nvgFillColor(vg, nvgRGBA(20, 25, 40, math.floor(210 * glow))); nvgFill(vg)
                    nvgStrokeColor(vg, nvgRGBA(100, 160, 255, math.floor(140 * glow))); nvgStrokeWidth(vg, 1.5); nvgStroke(vg)
                end

                -- 广播标识
                if cm.isBroadcast then
                    nvgFontSize(vg, 11); nvgTextAlign(vg, NVG_ALIGN_RIGHT + NVG_ALIGN_TOP)
                    nvgFillColor(vg, nvgRGBA(255, 180, 60, 180))
                    nvgText(vg, cardX + cardW - 8, cardY + 4, "[全服]", nil)
                end

                -- 发件人 + 时间
                nvgFontSize(vg, 13); nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_TOP)
                nvgFillColor(vg, nvgRGBA(140, 140, 160, 180))
                nvgText(vg, cardX + 10, cardY + 6, "来自: " .. (cm.fromName or "系统"), nil)
                local timeStr = ""
                if cm.time and cm.time > 0 then
                    local dt2 = os.time() - cm.time
                    if dt2 < 60 then timeStr = "刚刚"
                    elseif dt2 < 3600 then timeStr = math.floor(dt2 / 60) .. "分钟前"
                    elseif dt2 < 86400 then timeStr = math.floor(dt2 / 3600) .. "小时前"
                    else timeStr = math.floor(dt2 / 86400) .. "天前" end
                end
                nvgTextAlign(vg, NVG_ALIGN_RIGHT + NVG_ALIGN_TOP)
                nvgText(vg, cardX + cardW - 10, cardY + 6 + (cm.isBroadcast and 14 or 0), timeStr, nil)

                -- 标题
                nvgFontSize(vg, 20); nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_TOP)
                if isClaimed or not hasRewards then
                    nvgFillColor(vg, nvgRGBA(160, 160, 170, 180))
                else
                    nvgFillColor(vg, nvgRGBA(220, 230, 255, 240))
                end
                nvgText(vg, cardX + 10, cardY + 24, cm.subject or "(无主题)", nil)

                -- 正文预览
                nvgFontSize(vg, 14); nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_TOP)
                nvgFillColor(vg, nvgRGBA(160, 160, 170, isClaimed and 100 or 180))
                local bodyPreview = (cm.body or "")
                if #bodyPreview > 60 then bodyPreview = bodyPreview:sub(1, 60) .. "..." end
                nvgText(vg, cardX + 10, cardY + 48, bodyPreview, nil)

                -- 奖励预览
                if hasRewards then
                    local rwY2 = cardY + 70
                    for ri, rw in ipairs(cm.rewards) do
                        local rwX = cardX + 10 + (ri - 1) * 140
                        nvgFontSize(vg, 14); nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_TOP)
                        if rw.type == "jade" then
                            nvgFillColor(vg, nvgRGBA(255, 220, 100, isClaimed and 80 or 220))
                        elseif rw.type == "ad_free" then
                            nvgFillColor(vg, nvgRGBA(100, 255, 150, isClaimed and 80 or 220))
                        else
                            nvgFillColor(vg, nvgRGBA(200, 160, 255, isClaimed and 80 or 220))
                        end
                        nvgText(vg, rwX, rwY2, rw.label or "", nil)
                    end
                end

                -- 领取按钮 / 已读标签
                local btnW2, btnH2 = 80, 30
                local btnX2 = cardX + cardW - btnW2 - 10
                local btnY2 = cardY + cloudCardH - btnH2 - 8
                if hasRewards then
                    if isClaimed then
                        nvgFontSize(vg, 15); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
                        nvgFillColor(vg, nvgRGBA(100, 100, 100, 140))
                        nvgText(vg, btnX2 + btnW2 / 2, btnY2 + btnH2 / 2, "已领取", nil)
                    else
                        local bp = 0.85 + 0.15 * math.sin(t * 3.5 + i)
                        nvgBeginPath(vg); nvgRoundedRect(vg, btnX2, btnY2, btnW2, btnH2, 8)
                        nvgFillColor(vg, nvgRGBA(50, 90, 160, math.floor(220 * bp))); nvgFill(vg)
                        nvgStrokeColor(vg, nvgRGBA(100, 180, 255, math.floor(180 * bp))); nvgStrokeWidth(vg, 1.5); nvgStroke(vg)
                        nvgFontSize(vg, 17); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
                        nvgFillColor(vg, nvgRGBA(220, 240, 255, 240))
                        nvgText(vg, btnX2 + btnW2 / 2, btnY2 + btnH2 / 2, "领取", nil)
                        ms.cloudBtnRects[i] = { x = btnX2, y = btnY2, w = btnW2, h = btnH2 }
                    end
                end
            end
        end

        if #welfareState.mailDefs == 0 and #inbox == 0 then
            nvgFontSize(vg, 20); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
            nvgFillColor(vg, nvgRGBA(120, 110, 100, 160))
            nvgText(vg, cx, listTop + listH / 2, "暂无邮件", nil)
        end

        nvgRestore(vg)

    -- =============== 玩家邮件 Tab ===============
    elseif ms.tab == "cloud" then
        local mailCardH = 130
        ms.cloudBtnRects = {}
        local inbox = CloudManager._mailInbox or {}

        -- 写信按钮位置 (其他按钮也依赖这些坐标)
        local compBtnW, compBtnH = 90, 32
        local compBtnX = W - pad - compBtnW
        local compBtnY = listTop

        -- 写信按钮 (暂时隐藏, 仅管理员可见)
        menuBtnRects.mailCompose = nil
        if CloudManager.IsAdmin() then
            nvgBeginPath(vg); nvgRoundedRect(vg, compBtnX, compBtnY, compBtnW, compBtnH, 6)
            nvgFillColor(vg, nvgRGBA(50, 90, 140, 220)); nvgFill(vg)
            nvgStrokeColor(vg, nvgRGBA(100, 160, 220, 180)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
            nvgFontSize(vg, 16); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
            nvgFillColor(vg, nvgRGBA(200, 230, 255, 240))
            nvgText(vg, compBtnX + compBtnW / 2, compBtnY + compBtnH / 2, "写信", nil)
            menuBtnRects.mailCompose = { x = compBtnX, y = compBtnY, w = compBtnW, h = compBtnH }
        end

        -- 管理员专属: 发奖励邮件按钮 + 玩家管理按钮
        if CloudManager.IsAdmin() then
            local admBtnW, admBtnH = 110, 32
            local admBtnX = compBtnX - admBtnW - 8
            nvgBeginPath(vg); nvgRoundedRect(vg, admBtnX, compBtnY, admBtnW, admBtnH, 6)
            nvgFillColor(vg, nvgRGBA(140, 70, 20, 220)); nvgFill(vg)
            nvgStrokeColor(vg, nvgRGBA(255, 180, 60, 180)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
            nvgFontSize(vg, 15); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
            nvgFillColor(vg, nvgRGBA(255, 220, 100, 240))
            nvgText(vg, admBtnX + admBtnW / 2, compBtnY + admBtnH / 2, "发奖励邮件", nil)
            menuBtnRects.mailAdminReward = { x = admBtnX, y = compBtnY, w = admBtnW, h = admBtnH }
            -- 玩家管理按钮
            local mgBtnW, mgBtnH = 90, 32
            local mgBtnX = admBtnX - mgBtnW - 8
            nvgBeginPath(vg); nvgRoundedRect(vg, mgBtnX, compBtnY, mgBtnW, mgBtnH, 6)
            nvgFillColor(vg, nvgRGBA(100, 30, 30, 220)); nvgFill(vg)
            nvgStrokeColor(vg, nvgRGBA(220, 80, 80, 180)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
            nvgFontSize(vg, 15); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
            nvgFillColor(vg, nvgRGBA(255, 180, 180, 240))
            nvgText(vg, mgBtnX + mgBtnW / 2, compBtnY + mgBtnH / 2, "玩家管理", nil)
            menuBtnRects.mailAdminManage = { x = mgBtnX, y = compBtnY, w = mgBtnW, h = mgBtnH }
        end

        -- 刷新按钮
        local refBtnW, refBtnH = 60, 32
        local refBtnX = pad
        nvgBeginPath(vg); nvgRoundedRect(vg, refBtnX, compBtnY, refBtnW, refBtnH, 6)
        nvgFillColor(vg, nvgRGBA(40, 60, 50, 220)); nvgFill(vg)
        nvgStrokeColor(vg, nvgRGBA(80, 160, 120, 160)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
        nvgFontSize(vg, 15); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        nvgFillColor(vg, nvgRGBA(140, 220, 180, 220))
        nvgText(vg, refBtnX + refBtnW / 2, compBtnY + refBtnH / 2, "刷新", nil)
        menuBtnRects.mailRefresh = { x = refBtnX, y = compBtnY, w = refBtnW, h = refBtnH }

        local cloudListTop = compBtnY + compBtnH + 8
        local cloudListH = listBottom - cloudListTop

        nvgSave(vg)
        nvgScissor(vg, 0, cloudListTop, W, cloudListH)

        local scrollOff = ms.scroll and ms.scroll.offset or 0
        local contentH = #inbox * (mailCardH + cardGap) - cardGap
        local maxScroll = math.max(0, contentH - cloudListH)
        if ms.scroll then
            if ms.scroll.offset > maxScroll then ms.scroll.offset = maxScroll; ms.scroll.vel = 0 end
            if ms.scroll.offset < 0 then ms.scroll.offset = 0; ms.scroll.vel = 0 end
            scrollOff = ms.scroll.offset
        end

        for i, cm in ipairs(inbox) do
            local isClaimed = CloudManager.IsMailClaimed(cm.id)
            local hasRewards = #(cm.rewards or {}) > 0
            local cardY = cloudListTop + (i - 1) * (mailCardH + cardGap) - scrollOff
            local cardX = pad
            local cardW = W - pad * 2

            nvgBeginPath(vg); nvgRoundedRect(vg, cardX, cardY, cardW, mailCardH, 10)
            if isClaimed or not hasRewards then
                nvgFillColor(vg, nvgRGBA(20, 20, 25, 180)); nvgFill(vg)
                nvgStrokeColor(vg, nvgRGBA(60, 60, 70, 100)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
            else
                local glow = 0.8 + 0.2 * math.sin(t * 2.5)
                nvgFillColor(vg, nvgRGBA(20, 25, 40, math.floor(210 * glow))); nvgFill(vg)
                nvgStrokeColor(vg, nvgRGBA(100, 160, 255, math.floor(140 * glow))); nvgStrokeWidth(vg, 1.5); nvgStroke(vg)
            end

            -- 广播标识
            if cm.isBroadcast then
                nvgFontSize(vg, 11); nvgTextAlign(vg, NVG_ALIGN_RIGHT + NVG_ALIGN_TOP)
                nvgFillColor(vg, nvgRGBA(255, 180, 60, 180))
                nvgText(vg, cardX + cardW - 8, cardY + 4, "[全服]", nil)
            end

            -- 发件人 + 时间
            nvgFontSize(vg, 13); nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_TOP)
            nvgFillColor(vg, nvgRGBA(140, 140, 160, 180))
            nvgText(vg, cardX + 10, cardY + 6, "来自: " .. (cm.fromName or "未知"), nil)
            -- 时间
            local timeStr = ""
            if cm.time and cm.time > 0 then
                local dt2 = os.time() - cm.time
                if dt2 < 60 then timeStr = "刚刚"
                elseif dt2 < 3600 then timeStr = math.floor(dt2 / 60) .. "分钟前"
                elseif dt2 < 86400 then timeStr = math.floor(dt2 / 3600) .. "小时前"
                else timeStr = math.floor(dt2 / 86400) .. "天前"
                end
            end
            nvgTextAlign(vg, NVG_ALIGN_RIGHT + NVG_ALIGN_TOP)
            nvgText(vg, cardX + cardW - 10, cardY + 6 + (cm.isBroadcast and 14 or 0), timeStr, nil)

            -- 标题
            nvgFontSize(vg, 20); nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_TOP)
            if isClaimed or not hasRewards then
                nvgFillColor(vg, nvgRGBA(160, 160, 170, 180))
            else
                nvgFillColor(vg, nvgRGBA(220, 230, 255, 240))
            end
            nvgText(vg, cardX + 10, cardY + 24, cm.subject or "(无主题)", nil)

            -- 正文预览 (最多2行)
            nvgFontSize(vg, 14); nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_TOP)
            nvgFillColor(vg, nvgRGBA(160, 160, 170, isClaimed and 100 or 180))
            local bodyPreview = (cm.body or "")
            if #bodyPreview > 60 then bodyPreview = bodyPreview:sub(1, 60) .. "..." end
            nvgText(vg, cardX + 10, cardY + 48, bodyPreview, nil)

            -- 奖励预览
            if hasRewards then
                local rwY2 = cardY + 70
                for ri, rw in ipairs(cm.rewards) do
                    local rwX = cardX + 10 + (ri - 1) * 140
                    nvgFontSize(vg, 14); nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_TOP)
                    if rw.type == "jade" then
                        nvgFillColor(vg, nvgRGBA(255, 220, 100, isClaimed and 80 or 220))
                    elseif rw.type == "ad_free" then
                        nvgFillColor(vg, nvgRGBA(100, 255, 150, isClaimed and 80 or 220))
                    else
                        nvgFillColor(vg, nvgRGBA(200, 160, 255, isClaimed and 80 or 220))
                    end
                    nvgText(vg, rwX, rwY2, rw.label or "", nil)
                end
            end

            -- 领取按钮 / 已读标签
            local btnW2, btnH2 = 80, 30
            local btnX2 = cardX + cardW - btnW2 - 10
            local btnY2 = cardY + mailCardH - btnH2 - 8
            if hasRewards then
                if isClaimed then
                    nvgFontSize(vg, 15); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
                    nvgFillColor(vg, nvgRGBA(100, 100, 100, 140))
                    nvgText(vg, btnX2 + btnW2 / 2, btnY2 + btnH2 / 2, "已领取", nil)
                else
                    local bp = 0.85 + 0.15 * math.sin(t * 3.5 + i)
                    nvgBeginPath(vg); nvgRoundedRect(vg, btnX2, btnY2, btnW2, btnH2, 8)
                    nvgFillColor(vg, nvgRGBA(50, 90, 160, math.floor(220 * bp))); nvgFill(vg)
                    nvgStrokeColor(vg, nvgRGBA(100, 180, 255, math.floor(180 * bp))); nvgStrokeWidth(vg, 1.5); nvgStroke(vg)
                    nvgFontSize(vg, 17); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
                    nvgFillColor(vg, nvgRGBA(220, 240, 255, 240))
                    nvgText(vg, btnX2 + btnW2 / 2, btnY2 + btnH2 / 2, "领取", nil)
                    ms.cloudBtnRects[i] = { x = btnX2, y = btnY2, w = btnW2, h = btnH2 }
                end
            end
        end

        if #inbox == 0 then
            nvgFontSize(vg, 20); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
            nvgFillColor(vg, nvgRGBA(120, 120, 140, 160))
            nvgText(vg, cx, cloudListTop + cloudListH / 2, CloudManager._mailLoading and "加载中..." or "暂无玩家邮件", nil)
        end

        nvgRestore(vg)
    end

    -- =============== 写信弹窗 / 管理面板弹窗 ===============
    if ms.composing and ms.composeData then
        local cd = ms.composeData
        nvgBeginPath(vg); nvgRect(vg, 0, 0, W, H)
        nvgFillColor(vg, nvgRGBA(0, 0, 0, 180)); nvgFill(vg)

      if cd.isManage then
        -- =============== 玩家管理面板（支持标签切换） ===============
        if not cd.banTab then cd.banTab = "operate" end
        local pw, ph = 420, 440
        local px, py = cx - pw / 2, H / 2 - ph / 2
        nvgBeginPath(vg); nvgRoundedRect(vg, px, py, pw, ph, 14)
        nvgFillColor(vg, nvgRGBA(30, 18, 18, 245)); nvgFill(vg)
        nvgStrokeColor(vg, nvgRGBA(200, 80, 80, 160)); nvgStrokeWidth(vg, 2); nvgStroke(vg)
        cd.bgRect = { x = px, y = py, w = pw, h = ph }

        nvgFontSize(vg, 20); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        nvgFillColor(vg, nvgRGBA(255, 180, 180, 240))
        nvgText(vg, cx, py + 24, "玩家管理(管理员)", nil)

        -- 标签按钮
        local fieldX, fieldW = px + 16, pw - 32
        local mTabY = py + 44
        local mTabNames = { { id = "operate", name = "操作" }, { id = "tempList", name = "暂时封禁" }, { id = "permList", name = "永久封禁" } }
        local mTabW = math.floor((fieldW - 8) / 3)
        local mTabH = 28
        cd.tabBtnRects = {}
        for ti, tab in ipairs(mTabNames) do
            local tx = fieldX + (ti - 1) * (mTabW + 4)
            local isSel = (cd.banTab == tab.id)
            nvgBeginPath(vg); nvgRoundedRect(vg, tx, mTabY, mTabW, mTabH, 5)
            if isSel then
                nvgFillColor(vg, nvgRGBA(160, 60, 60, 240)); nvgFill(vg)
            else
                nvgFillColor(vg, nvgRGBA(60, 30, 30, 200)); nvgFill(vg)
            end
            nvgStrokeColor(vg, nvgRGBA(180, 80, 80, 150)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
            nvgFontSize(vg, 14); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
            nvgFillColor(vg, isSel and nvgRGBA(255, 240, 240, 255) or nvgRGBA(180, 140, 140, 200))
            nvgText(vg, tx + mTabW / 2, mTabY + mTabH / 2, tab.name, nil)
            cd.tabBtnRects[tab.id] = { x = tx, y = mTabY, w = mTabW, h = mTabH }
        end

        local contentY = mTabY + mTabH + 10
        local contentH = py + ph - contentY - 50  -- 底部留空给结果提示

      if cd.banTab == "operate" then
        -- =============== 操作标签（原有功能） ===============
        local fy = contentY
        -- UID输入
        nvgFontSize(vg, 14); nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_TOP)
        nvgFillColor(vg, nvgRGBA(200, 180, 180, 200))
        nvgText(vg, fieldX, fy, "目标玩家UID:", nil)
        fy = fy + 18
        nvgBeginPath(vg); nvgRoundedRect(vg, fieldX, fy, fieldW, 28, 4)
        nvgFillColor(vg, nvgRGBA(15, 15, 20, 200)); nvgFill(vg)
        nvgStrokeColor(vg, cd.inputFocus == "uid" and nvgRGBA(255, 120, 120, 200) or nvgRGBA(80, 50, 50, 150))
        nvgStrokeWidth(vg, 1); nvgStroke(vg)
        local uidPasteW = 50
        nvgFillColor(vg, nvgRGBA(240, 220, 220, 230)); nvgFontSize(vg, 15)
        nvgText(vg, fieldX + 8, fy + 5, cd.targetUid .. (cd.inputFocus == "uid" and "|" or ""), nil)
        cd.uidRect = { x = fieldX, y = fy, w = fieldW - uidPasteW - 6, h = 28 }
        local upX = fieldX + fieldW - uidPasteW
        nvgBeginPath(vg); nvgRoundedRect(vg, upX, fy, uidPasteW, 28, 4)
        nvgFillColor(vg, nvgRGBA(100, 60, 60, 200)); nvgFill(vg)
        nvgStrokeColor(vg, nvgRGBA(200, 120, 120, 150)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
        nvgFontSize(vg, 13); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        nvgFillColor(vg, nvgRGBA(255, 200, 200, 230))
        nvgText(vg, upX + uidPasteW / 2, fy + 14, "粘贴", nil)
        cd.uidPasteRect = { x = upX, y = fy, w = uidPasteW, h = 28 }

        -- 登录管理
        fy = fy + 42
        nvgFontSize(vg, 13); nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_TOP)
        nvgFillColor(vg, nvgRGBA(200, 180, 180, 180))
        nvgText(vg, fieldX, fy, "登录管理:", nil)
        fy = fy + 18
        local btnW, btnH = (fieldW - 12) / 2, 32
        -- 暂时封禁
        nvgBeginPath(vg); nvgRoundedRect(vg, fieldX, fy, btnW, btnH, 6)
        nvgFillColor(vg, nvgRGBA(140, 90, 20, 220)); nvgFill(vg)
        nvgStrokeColor(vg, nvgRGBA(220, 160, 60, 180)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
        nvgFontSize(vg, 14); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        nvgFillColor(vg, nvgRGBA(255, 220, 140, 240))
        nvgText(vg, fieldX + btnW / 2, fy + btnH / 2, "暂时封禁", nil)
        cd.banBtnRect = { x = fieldX, y = fy, w = btnW, h = btnH }
        -- 解禁
        local ubX = fieldX + btnW + 12
        nvgBeginPath(vg); nvgRoundedRect(vg, ubX, fy, btnW, btnH, 6)
        nvgFillColor(vg, nvgRGBA(30, 100, 50, 220)); nvgFill(vg)
        nvgStrokeColor(vg, nvgRGBA(80, 200, 120, 180)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
        nvgFillColor(vg, nvgRGBA(200, 255, 200, 240))
        nvgText(vg, ubX + btnW / 2, fy + btnH / 2, "解禁", nil)
        cd.unbanBtnRect = { x = ubX, y = fy, w = btnW, h = btnH }

        -- 排行榜管理
        fy = fy + btnH + 14
        nvgFontSize(vg, 13); nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_TOP)
        nvgFillColor(vg, nvgRGBA(200, 180, 180, 180))
        nvgText(vg, fieldX, fy, "排行榜管理:", nil)
        fy = fy + 18
        -- 隐藏排行榜
        nvgBeginPath(vg); nvgRoundedRect(vg, fieldX, fy, btnW, btnH, 6)
        nvgFillColor(vg, nvgRGBA(120, 80, 20, 220)); nvgFill(vg)
        nvgStrokeColor(vg, nvgRGBA(220, 160, 60, 180)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
        nvgFontSize(vg, 14); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        nvgFillColor(vg, nvgRGBA(255, 220, 140, 240))
        nvgText(vg, fieldX + btnW / 2, fy + btnH / 2, "隐藏排行榜", nil)
        cd.hideRankBtnRect = { x = fieldX, y = fy, w = btnW, h = btnH }
        -- 恢复排行榜
        nvgBeginPath(vg); nvgRoundedRect(vg, ubX, fy, btnW, btnH, 6)
        nvgFillColor(vg, nvgRGBA(30, 80, 120, 220)); nvgFill(vg)
        nvgStrokeColor(vg, nvgRGBA(80, 160, 220, 180)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
        nvgFillColor(vg, nvgRGBA(180, 220, 255, 240))
        nvgText(vg, ubX + btnW / 2, fy + btnH / 2, "恢复排行榜", nil)
        cd.unhideRankBtnRect = { x = ubX, y = fy, w = btnW, h = btnH }

        -- 永久封禁按钮
        fy = fy + btnH + 14
        nvgFontSize(vg, 13); nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_TOP)
        nvgFillColor(vg, nvgRGBA(200, 180, 180, 180))
        nvgText(vg, fieldX, fy, "永久封禁(不可恢复):", nil)
        fy = fy + 18
        nvgBeginPath(vg); nvgRoundedRect(vg, fieldX, fy, fieldW, btnH, 6)
        nvgFillColor(vg, nvgRGBA(120, 10, 10, 220)); nvgFill(vg)
        nvgStrokeColor(vg, nvgRGBA(255, 40, 40, 200)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
        nvgFontSize(vg, 14); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        nvgFillColor(vg, nvgRGBA(255, 160, 160, 255))
        nvgText(vg, fieldX + fieldW / 2, fy + btnH / 2, "永久封禁(删除数据)", nil)
        cd.permBanBtnRect = { x = fieldX, y = fy, w = fieldW, h = btnH }

      elseif cd.banTab == "tempList" or cd.banTab == "permList" then
        -- =============== 封禁名单标签 ===============
        local isTemp = (cd.banTab == "tempList")
        -- 自动加载
        if not cd.banListLoaded and not cd.banListLoading then
            cd.banListLoading = true
            CloudManager.AdminGetBanListSummary(function(tempList, permList, err)
                cd.banTempList = tempList or {}
                cd.banPermList = permList or {}
                cd.banListLoaded = true
                cd.banListLoading = false
            end)
        end

        local listData = isTemp and cd.banTempList or cd.banPermList
        local fy = contentY

        if cd.banListLoading then
            nvgFontSize(vg, 16); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
            nvgFillColor(vg, nvgRGBA(200, 180, 180, 200))
            nvgText(vg, cx, fy + contentH / 2, "加载中...", nil)
        elseif #listData == 0 then
            nvgFontSize(vg, 16); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
            nvgFillColor(vg, nvgRGBA(160, 140, 140, 180))
            nvgText(vg, cx, fy + contentH / 2, isTemp and "暂无暂时封禁玩家" or "暂无永久封禁玩家", nil)
        else
            -- 刷新按钮
            local refBtnW, refBtnH = 60, 24
            local refBtnX = fieldX + fieldW - refBtnW
            nvgBeginPath(vg); nvgRoundedRect(vg, refBtnX, fy, refBtnW, refBtnH, 4)
            nvgFillColor(vg, nvgRGBA(60, 80, 100, 200)); nvgFill(vg)
            nvgStrokeColor(vg, nvgRGBA(100, 150, 200, 150)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
            nvgFontSize(vg, 12); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
            nvgFillColor(vg, nvgRGBA(180, 220, 255, 230))
            nvgText(vg, refBtnX + refBtnW / 2, fy + refBtnH / 2, "刷新", nil)
            cd.banRefreshBtnRect = { x = refBtnX, y = fy, w = refBtnW, h = refBtnH }

            nvgFontSize(vg, 13); nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)
            nvgFillColor(vg, nvgRGBA(180, 160, 160, 180))
            nvgText(vg, fieldX, fy + refBtnH / 2, "共 " .. #listData .. " 人", nil)
            fy = fy + refBtnH + 6

            -- 列表区域（带滚动）
            local banListH = contentH - (refBtnH + 6)
            local itemH = 44
            local totalH = #listData * itemH
            local scroll = cd.banListScroll
            if not scroll then scroll = { offset = 0, vel = 0 }; cd.banListScroll = scroll end
            local maxScroll = math.max(0, totalH - banListH)
            if scroll.offset < 0 then scroll.offset = 0 end
            if scroll.offset > maxScroll then scroll.offset = maxScroll end

            nvgSave(vg)
            nvgScissor(vg, fieldX, fy, fieldW, banListH)
            cd.banListItemRects = {}

            for i, item in ipairs(listData) do
                local iy = fy + (i - 1) * itemH - scroll.offset
                if iy + itemH > fy and iy < fy + banListH then
                    -- 行背景
                    local bgAlpha = (i % 2 == 0) and 40 or 25
                    nvgBeginPath(vg); nvgRoundedRect(vg, fieldX, iy, fieldW, itemH - 2, 4)
                    nvgFillColor(vg, nvgRGBA(80, 40, 40, bgAlpha)); nvgFill(vg)

                    -- UID 和状态
                    nvgFontSize(vg, 14); nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)
                    nvgFillColor(vg, nvgRGBA(240, 210, 210, 230))
                    nvgText(vg, fieldX + 8, iy + itemH / 2 - 8, "UID: " .. item.uid, nil)
                    nvgFontSize(vg, 11); nvgFillColor(vg, nvgRGBA(180, 150, 150, 180))
                    local statusTxt = ""
                    if item.permanent then
                        statusTxt = "永久封禁"
                    else
                        if item.level >= 3 then statusTxt = "全面封禁"
                        elseif item.level >= 2 then statusTxt = "核心封禁"
                        elseif item.level >= 1 then statusTxt = "社交封禁"
                        end
                        if item.rankHidden then statusTxt = statusTxt .. "+排行隐藏" end
                    end
                    nvgText(vg, fieldX + 8, iy + itemH / 2 + 8, statusTxt, nil)

                    -- 操作按钮
                    local actBtnW, actBtnH = 72, 26
                    local actBtnX = fieldX + fieldW - actBtnW - 8
                    local actBtnY = iy + (itemH - actBtnH) / 2

                    if isTemp then
                        -- 暂时封禁名单 → 显示"永久封禁"按钮
                        nvgBeginPath(vg); nvgRoundedRect(vg, actBtnX, actBtnY, actBtnW, actBtnH, 4)
                        nvgFillColor(vg, nvgRGBA(140, 20, 20, 220)); nvgFill(vg)
                        nvgStrokeColor(vg, nvgRGBA(255, 60, 60, 180)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
                        nvgFontSize(vg, 12); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
                        nvgFillColor(vg, nvgRGBA(255, 180, 180, 240))
                        nvgText(vg, actBtnX + actBtnW / 2, actBtnY + actBtnH / 2, "永久删除", nil)

                        -- 解禁按钮
                        local unBtnX = actBtnX - actBtnW - 6
                        nvgBeginPath(vg); nvgRoundedRect(vg, unBtnX, actBtnY, actBtnW, actBtnH, 4)
                        nvgFillColor(vg, nvgRGBA(30, 90, 50, 220)); nvgFill(vg)
                        nvgStrokeColor(vg, nvgRGBA(80, 200, 120, 160)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
                        nvgFillColor(vg, nvgRGBA(180, 255, 200, 240))
                        nvgText(vg, unBtnX + actBtnW / 2, actBtnY + actBtnH / 2, "解禁", nil)
                        cd.banListItemRects[i] = {
                            permBtn = { x = actBtnX, y = actBtnY, w = actBtnW, h = actBtnH },
                            unbanBtn = { x = unBtnX, y = actBtnY, w = actBtnW, h = actBtnH },
                            uid = item.uid,
                        }
                    else
                        -- 永久封禁名单 → 仅显示"已删除"标记
                        nvgFontSize(vg, 12); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
                        nvgFillColor(vg, nvgRGBA(255, 80, 80, 160))
                        nvgText(vg, actBtnX + actBtnW / 2, actBtnY + actBtnH / 2, "已删除", nil)
                    end
                end
            end
            nvgRestore(vg)
        end
      end -- banTab

        -- 操作结果提示（所有标签共享）
        if cd.resultMsg and cd.resultTimer and cd.resultTimer > 0 then
            local msgY = py + ph - 36
            local alpha = math.min(255, math.floor(cd.resultTimer / 3.0 * 255))
            local rc = cd.resultOk and nvgRGBA(100, 255, 150, alpha) or nvgRGBA(255, 120, 120, alpha)
            nvgFontSize(vg, 14); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
            nvgFillColor(vg, rc)
            nvgText(vg, cx, msgY, cd.resultMsg, nil)
            cd.resultTimer = cd.resultTimer - 0.016
        end

        -- 确认删除弹窗
        if cd.confirmDeleteUid then
            nvgBeginPath(vg); nvgRect(vg, 0, 0, W, H)
            nvgFillColor(vg, nvgRGBA(0, 0, 0, 150)); nvgFill(vg)
            local dw, dh = 300, 140
            local dx, dy = cx - dw / 2, H / 2 - dh / 2
            nvgBeginPath(vg); nvgRoundedRect(vg, dx, dy, dw, dh, 10)
            nvgFillColor(vg, nvgRGBA(40, 20, 20, 250)); nvgFill(vg)
            nvgStrokeColor(vg, nvgRGBA(255, 60, 60, 200)); nvgStrokeWidth(vg, 2); nvgStroke(vg)

            nvgFontSize(vg, 16); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
            nvgFillColor(vg, nvgRGBA(255, 200, 200, 240))
            nvgText(vg, cx, dy + 30, "确认永久封禁(删除)?", nil)
            nvgFontSize(vg, 14); nvgFillColor(vg, nvgRGBA(200, 160, 160, 200))
            nvgText(vg, cx, dy + 54, "UID: " .. tostring(cd.confirmDeleteUid), nil)
            nvgFontSize(vg, 12); nvgFillColor(vg, nvgRGBA(255, 120, 120, 180))
            nvgText(vg, cx, dy + 72, "此操作不可恢复!", nil)

            local cbW, cbH = 100, 32
            local cfmX = cx - cbW - 8
            local cfmY = dy + dh - cbH - 16
            -- 确认按钮
            nvgBeginPath(vg); nvgRoundedRect(vg, cfmX, cfmY, cbW, cbH, 6)
            nvgFillColor(vg, nvgRGBA(160, 20, 20, 230)); nvgFill(vg)
            nvgStrokeColor(vg, nvgRGBA(255, 60, 60, 200)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
            nvgFontSize(vg, 15); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
            nvgFillColor(vg, nvgRGBA(255, 200, 200, 250))
            nvgText(vg, cfmX + cbW / 2, cfmY + cbH / 2, "确认删除", nil)
            cd.confirmYesRect = { x = cfmX, y = cfmY, w = cbW, h = cbH }
            -- 取消按钮
            local cnlX = cx + 8
            nvgBeginPath(vg); nvgRoundedRect(vg, cnlX, cfmY, cbW, cbH, 6)
            nvgFillColor(vg, nvgRGBA(60, 60, 70, 230)); nvgFill(vg)
            nvgStrokeColor(vg, nvgRGBA(140, 140, 160, 180)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
            nvgFillColor(vg, nvgRGBA(200, 200, 210, 240))
            nvgText(vg, cnlX + cbW / 2, cfmY + cbH / 2, "取消", nil)
            cd.confirmNoRect = { x = cnlX, y = cfmY, w = cbW, h = cbH }
        end

        -- 关闭按钮
        local clR = 16
        local clX = px + pw - 25
        local clY = py + 20
        nvgBeginPath(vg); nvgCircle(vg, clX, clY, clR)
        nvgFillColor(vg, nvgRGBA(60, 40, 40, 200)); nvgFill(vg)
        nvgStrokeColor(vg, nvgRGBA(180, 100, 100, 150)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
        nvgFontSize(vg, 20); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        nvgFillColor(vg, nvgRGBA(220, 180, 180, 220))
        nvgText(vg, clX, clY, "X", nil)
        cd.closeBtnRect = { x = clX - clR, y = clY - clR, w = clR * 2, h = clR * 2 }

      else
        -- =============== 写信 / 发奖励邮件面板 ===============
        local sealSectionH = (cd.isAdmin and cd.sealHeroIdx) and 180 or (cd.isAdmin and 30 or 0)
        local pw, ph = 420, 340 + sealSectionH
        local px, py = cx - pw / 2, H / 2 - ph / 2
        nvgBeginPath(vg); nvgRoundedRect(vg, px, py, pw, ph, 14)
        nvgFillColor(vg, nvgRGBA(25, 28, 40, 245)); nvgFill(vg)
        nvgStrokeColor(vg, nvgRGBA(100, 160, 220, 160)); nvgStrokeWidth(vg, 2); nvgStroke(vg)
        cd.bgRect = { x = px, y = py, w = pw, h = ph }

        nvgFontSize(vg, 24); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        DrawWhiteInkText(cx, py + 28, cd.isAdmin and "发奖励邮件(管理员)" or "写信")

        -- 收件人UID (0=全服广播)
        local fieldX, fieldW = px + 20, pw - 40
        local fy = py + 56
        nvgFontSize(vg, 14); nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_TOP)
        nvgFillColor(vg, nvgRGBA(180, 180, 200, 200))
        nvgText(vg, fieldX, fy, cd.isAdmin and "收件人UID (0=全服广播):" or "收件人UID:", nil)
        fy = fy + 20
        nvgBeginPath(vg); nvgRoundedRect(vg, fieldX, fy, fieldW, 30, 4)
        nvgFillColor(vg, nvgRGBA(15, 15, 25, 200)); nvgFill(vg)
        nvgStrokeColor(vg, cd.inputFocus == "uid" and nvgRGBA(100, 180, 255, 200) or nvgRGBA(60, 60, 80, 150))
        nvgStrokeWidth(vg, 1); nvgStroke(vg)
        local uidPasteW = 50
        nvgFillColor(vg, nvgRGBA(220, 220, 240, 230)); nvgFontSize(vg, 16)
        nvgText(vg, fieldX + 8, fy + 6, cd.targetUid .. (cd.inputFocus == "uid" and "|" or ""), nil)
        cd.uidRect = { x = fieldX, y = fy, w = fieldW - uidPasteW - 6, h = 30 }
        -- UID粘贴按钮
        local upX = fieldX + fieldW - uidPasteW
        nvgBeginPath(vg); nvgRoundedRect(vg, upX, fy, uidPasteW, 30, 4)
        nvgFillColor(vg, nvgRGBA(60, 100, 160, 200)); nvgFill(vg)
        nvgStrokeColor(vg, nvgRGBA(100, 160, 255, 150)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
        nvgFontSize(vg, 14); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        DrawWhiteInkText(upX + uidPasteW / 2, fy + 15, "粘贴")
        cd.uidPasteRect = { x = upX, y = fy, w = uidPasteW, h = 30 }
        nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_TOP)

        -- 主题
        fy = fy + 38
        nvgFontSize(vg, 14); nvgFillColor(vg, nvgRGBA(180, 180, 200, 200))
        nvgText(vg, fieldX, fy, "主题:", nil)
        fy = fy + 20
        nvgBeginPath(vg); nvgRoundedRect(vg, fieldX, fy, fieldW, 30, 4)
        nvgFillColor(vg, nvgRGBA(15, 15, 25, 200)); nvgFill(vg)
        nvgStrokeColor(vg, cd.inputFocus == "subject" and nvgRGBA(100, 180, 255, 200) or nvgRGBA(60, 60, 80, 150))
        nvgStrokeWidth(vg, 1); nvgStroke(vg)
        nvgFillColor(vg, nvgRGBA(220, 220, 240, 230)); nvgFontSize(vg, 16)
        nvgText(vg, fieldX + 8, fy + 6, cd.subject .. (cd.inputFocus == "subject" and "|" or ""), nil)
        cd.subjectRect = { x = fieldX, y = fy, w = fieldW, h = 30 }

        -- 正文
        fy = fy + 38
        nvgFontSize(vg, 14); nvgFillColor(vg, nvgRGBA(180, 180, 200, 200))
        nvgText(vg, fieldX, fy, "正文:", nil)
        fy = fy + 20
        nvgBeginPath(vg); nvgRoundedRect(vg, fieldX, fy, fieldW, 50, 4)
        nvgFillColor(vg, nvgRGBA(15, 15, 25, 200)); nvgFill(vg)
        nvgStrokeColor(vg, cd.inputFocus == "body" and nvgRGBA(100, 180, 255, 200) or nvgRGBA(60, 60, 80, 150))
        nvgStrokeWidth(vg, 1); nvgStroke(vg)
        nvgFillColor(vg, nvgRGBA(220, 220, 240, 230)); nvgFontSize(vg, 14)
        nvgText(vg, fieldX + 8, fy + 6, cd.body .. (cd.inputFocus == "body" and "|" or ""), nil)
        cd.bodyRect = { x = fieldX, y = fy, w = fieldW, h = 50 }

        -- 管理员: 奖励选项
        if cd.isAdmin then
            fy = fy + 58
            nvgFontSize(vg, 14); nvgFillColor(vg, nvgRGBA(255, 200, 80, 200))
            nvgText(vg, fieldX, fy, "附件奖励:", nil)
            fy = fy + 18
            -- 虎符: 标签
            nvgFontSize(vg, 14); nvgFillColor(vg, nvgRGBA(255, 220, 100, 220))
            nvgText(vg, fieldX, fy, "虎符:", nil)
            -- 虎符: 输入框 (可直接输入数字)
            local jInputX, jInputW, jbH = fieldX + 42, 80, 22
            nvgBeginPath(vg); nvgRoundedRect(vg, jInputX, fy - 2, jInputW, jbH, 4)
            nvgFillColor(vg, nvgRGBA(15, 15, 25, 200)); nvgFill(vg)
            nvgStrokeColor(vg, cd.inputFocus == "jade" and nvgRGBA(255, 200, 80, 200) or nvgRGBA(80, 70, 40, 150))
            nvgStrokeWidth(vg, 1); nvgStroke(vg)
            nvgFillColor(vg, nvgRGBA(255, 230, 130, 240)); nvgFontSize(vg, 15)
            nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
            local jadeDisplayStr = cd.inputFocus == "jade" and ((cd.jadeInputText or "0") .. "|") or tostring(cd.rewardJade or 0)
            nvgText(vg, jInputX + jInputW / 2, fy + jbH / 2 - 2, jadeDisplayStr, nil)
            cd.jadeInputRect = { x = jInputX, y = fy - 2, w = jInputW, h = jbH }
            -- -500 按钮
            local jbW = 36
            local jMinusX = jInputX + jInputW + 6
            nvgBeginPath(vg); nvgRoundedRect(vg, jMinusX, fy - 2, jbW, jbH, 4)
            nvgFillColor(vg, nvgRGBA(80, 40, 40, 200)); nvgFill(vg)
            nvgFontSize(vg, 13); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
            nvgFillColor(vg, nvgRGBA(255, 200, 200, 220))
            nvgText(vg, jMinusX + jbW / 2, fy + jbH / 2 - 2, "-500", nil)
            cd.jadeMinus = { x = jMinusX, y = fy - 2, w = jbW, h = jbH }
            -- +500 按钮
            local jPlusX = jMinusX + jbW + 6
            nvgBeginPath(vg); nvgRoundedRect(vg, jPlusX, fy - 2, jbW, jbH, 4)
            nvgFillColor(vg, nvgRGBA(40, 80, 40, 200)); nvgFill(vg)
            nvgFillColor(vg, nvgRGBA(200, 255, 200, 220))
            nvgText(vg, jPlusX + jbW / 2, fy + jbH / 2 - 2, "+500", nil)
            cd.jadePlus = { x = jPlusX, y = fy - 2, w = jbW, h = jbH }

            -- 免广告特权开关
            nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_TOP)
            local adFreeX = jPlusX + jbW + 14
            nvgFontSize(vg, 14)
            nvgFillColor(vg, cd.adFree and nvgRGBA(100, 255, 150, 230) or nvgRGBA(160, 160, 170, 180))
            nvgText(vg, adFreeX, fy, cd.adFree and "[v] 免广告" or "[ ] 免广告", nil)
            cd.adFreeRect = { x = adFreeX, y = fy - 2, w = 90, h = jbH }

            -- ========== 兵符派发 ==========
            fy = fy + 28
            nvgFontSize(vg, 14); nvgFillColor(vg, nvgRGBA(180, 140, 255, 220))
            nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_TOP)
            nvgText(vg, fieldX, fy, "兵符派发:", nil)

            -- 武灵选择按钮
            local heroSelX = fieldX + 68
            local heroSelW, heroSelH = 140, 22
            local heroName = "未选择"
            if cd.sealHeroIdx and HERO_CARDS[cd.sealHeroIdx] then
                heroName = cd.sealHeroIdx .. "." .. HERO_CARDS[cd.sealHeroIdx].name
            end
            nvgBeginPath(vg); nvgRoundedRect(vg, heroSelX, fy - 2, heroSelW, heroSelH, 4)
            nvgFillColor(vg, nvgRGBA(30, 20, 50, 200)); nvgFill(vg)
            nvgStrokeColor(vg, nvgRGBA(140, 100, 200, 150)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
            nvgFontSize(vg, 13); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
            nvgFillColor(vg, nvgRGBA(220, 200, 255, 230))
            nvgText(vg, heroSelX + heroSelW / 2, fy + heroSelH / 2 - 2, heroName, nil)
            cd.sealHeroSelRect = { x = heroSelX, y = fy - 2, w = heroSelW, h = heroSelH }

            -- 左右翻页按钮
            local arrW = 22
            local arrLX = heroSelX - arrW - 4
            nvgBeginPath(vg); nvgRoundedRect(vg, arrLX, fy - 2, arrW, heroSelH, 4)
            nvgFillColor(vg, nvgRGBA(60, 40, 80, 200)); nvgFill(vg)
            nvgFontSize(vg, 14); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
            nvgFillColor(vg, nvgRGBA(200, 180, 255, 220))
            nvgText(vg, arrLX + arrW / 2, fy + heroSelH / 2 - 2, "<", nil)
            cd.sealHeroPrev = { x = arrLX, y = fy - 2, w = arrW, h = heroSelH }

            local arrRX = heroSelX + heroSelW + 4
            nvgBeginPath(vg); nvgRoundedRect(vg, arrRX, fy - 2, arrW, heroSelH, 4)
            nvgFillColor(vg, nvgRGBA(60, 40, 80, 200)); nvgFill(vg)
            nvgFillColor(vg, nvgRGBA(200, 180, 255, 220))
            nvgText(vg, arrRX + arrW / 2, fy + heroSelH / 2 - 2, ">", nil)
            cd.sealHeroNext = { x = arrRX, y = fy - 2, w = arrW, h = heroSelH }

            -- 清除武灵选择
            local clrX = arrRX + arrW + 6
            local clrW = 36
            nvgBeginPath(vg); nvgRoundedRect(vg, clrX, fy - 2, clrW, heroSelH, 4)
            nvgFillColor(vg, nvgRGBA(80, 40, 40, 200)); nvgFill(vg)
            nvgFontSize(vg, 12); nvgFillColor(vg, nvgRGBA(255, 180, 180, 220))
            nvgText(vg, clrX + clrW / 2, fy + heroSelH / 2 - 2, "清除", nil)
            cd.sealHeroClear = { x = clrX, y = fy - 2, w = clrW, h = heroSelH }

            -- 如果已选武灵，显示6个孔位选择
            if cd.sealHeroIdx then
                if not cd.sealSlots then cd.sealSlots = {} end
                cd.sealSlotRects = {}
                fy = fy + 26

                -- 快捷操作行: 全随机 / 全不选
                local qkBtnW, qkBtnH = 64, 20
                local qkX1 = fieldX
                nvgBeginPath(vg); nvgRoundedRect(vg, qkX1, fy - 1, qkBtnW, qkBtnH, 4)
                nvgFillColor(vg, nvgRGBA(50, 50, 20, 200)); nvgFill(vg)
                nvgStrokeColor(vg, nvgRGBA(200, 200, 100, 120)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
                nvgFontSize(vg, 12); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
                nvgFillColor(vg, nvgRGBA(220, 220, 120, 230))
                nvgText(vg, qkX1 + qkBtnW / 2, fy + qkBtnH / 2 - 1, "全随机", nil)
                cd.sealAllRandom = { x = qkX1, y = fy - 1, w = qkBtnW, h = qkBtnH }

                local qkX2 = qkX1 + qkBtnW + 8
                nvgBeginPath(vg); nvgRoundedRect(vg, qkX2, fy - 1, qkBtnW, qkBtnH, 4)
                nvgFillColor(vg, nvgRGBA(50, 20, 20, 200)); nvgFill(vg)
                nvgStrokeColor(vg, nvgRGBA(200, 100, 100, 120)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
                nvgFillColor(vg, nvgRGBA(220, 150, 150, 230))
                nvgText(vg, qkX2 + qkBtnW / 2, fy + qkBtnH / 2 - 1, "全不选", nil)
                cd.sealAllClear = { x = qkX2, y = fy - 1, w = qkBtnW, h = qkBtnH }

                -- 已选计数提示
                local selCount = 0
                for s = 1, SEAL_MAX_SLOTS do if cd.sealSlots[s] ~= nil then selCount = selCount + 1 end end
                nvgFontSize(vg, 11); nvgTextAlign(vg, NVG_ALIGN_RIGHT + NVG_ALIGN_MIDDLE)
                nvgFillColor(vg, nvgRGBA(160, 140, 200, 160))
                nvgText(vg, fieldX + fieldW, fy + qkBtnH / 2 - 1, selCount .. "/6 已选", nil)

                fy = fy + qkBtnH + 6
                local colW = (fieldW) / 3
                for s = 1, SEAL_MAX_SLOTS do
                    local col = (s - 1) % 3
                    local row = (s - 1) < 3 and 0 or 1
                    local sx = fieldX + col * colW
                    local sy = fy + row * 50
                    local slotVal = cd.sealSlots[s] -- nil=不选, 0=随机, 1~7=指定品阶

                    -- 孔位名称
                    local tc = SEAL_SLOT_THEME_COLORS[s] or {180,180,180}
                    nvgFontSize(vg, 12); nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_TOP)
                    nvgFillColor(vg, nvgRGBA(tc[1], tc[2], tc[3], 220))
                    nvgText(vg, sx, sy, SEAL_SLOT_NAMES[s], nil)

                    -- 品阶选择按钮
                    local btnX = sx + 36
                    local btnW, btnH = 80, 20
                    local label = "跳过"
                    local lblClr = nvgRGBA(100, 100, 110, 150)
                    local bgAlpha = 180
                    if slotVal == 0 then
                        label = "随机"
                        lblClr = nvgRGBA(220, 220, 100, 240)
                        bgAlpha = 220
                    elseif slotVal and slotVal >= 1 then
                        label = SEAL_TIER_NAMES[slotVal] or ("Lv" .. slotVal)
                        local qc = SEAL_QUALITY_COLORS[slotVal] or {200,200,200}
                        lblClr = nvgRGBA(qc[1], qc[2], qc[3], 250)
                        bgAlpha = 230
                    end
                    nvgBeginPath(vg); nvgRoundedRect(vg, btnX, sy - 1, btnW, btnH, 4)
                    nvgFillColor(vg, nvgRGBA(20, 15, 30, bgAlpha)); nvgFill(vg)
                    nvgStrokeColor(vg, slotVal ~= nil and nvgRGBA(tc[1], tc[2], tc[3], 140) or nvgRGBA(tc[1], tc[2], tc[3], 50))
                    nvgStrokeWidth(vg, slotVal ~= nil and 1.5 or 0.8); nvgStroke(vg)
                    nvgFontSize(vg, 13); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
                    nvgFillColor(vg, lblClr)
                    nvgText(vg, btnX + btnW / 2, sy + btnH / 2 - 1, label, nil)
                    cd.sealSlotRects[s] = { x = btnX, y = sy - 1, w = btnW, h = btnH }
                end
                fy = fy + 100
            end
        end

        -- 发送按钮
        local sendBtnW, sendBtnH = 120, 40
        local sendBtnX = cx - sendBtnW / 2
        local sendBtnY = py + ph - sendBtnH - 16
        local sp = 0.85 + 0.15 * math.sin(t * 3.0)
        nvgBeginPath(vg); nvgRoundedRect(vg, sendBtnX, sendBtnY, sendBtnW, sendBtnH, 8)
        nvgFillColor(vg, nvgRGBA(50, 100, 170, math.floor(230 * sp))); nvgFill(vg)
        nvgStrokeColor(vg, nvgRGBA(100, 180, 255, math.floor(180 * sp))); nvgStrokeWidth(vg, 1.5); nvgStroke(vg)
        nvgFontSize(vg, 20); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        nvgFillColor(vg, nvgRGBA(220, 240, 255, 240))
        nvgText(vg, sendBtnX + sendBtnW / 2, sendBtnY + sendBtnH / 2, "发送", nil)
        cd.sendBtnRect = { x = sendBtnX, y = sendBtnY, w = sendBtnW, h = sendBtnH }

        -- 关闭按钮
        local clR = 16
        local clX = px + pw - 25
        local clY = py + 20
        nvgBeginPath(vg); nvgCircle(vg, clX, clY, clR)
        nvgFillColor(vg, nvgRGBA(60, 50, 40, 200)); nvgFill(vg)
        nvgStrokeColor(vg, nvgRGBA(160, 140, 110, 150)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
        nvgFontSize(vg, 20); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        nvgFillColor(vg, nvgRGBA(200, 190, 170, 220))
        nvgText(vg, clX, clY, "X", nil)
        cd.closeBtnRect = { x = clX - clR, y = clY - clR, w = clR * 2, h = clR * 2 }
      end -- isManage branch
    end

    -- =============== 系统邮件确认弹窗 ===============
    if ms.confirmPopup and not ms.composing then
        local popup = ms.confirmPopup
        local mail = popup.cloudMail or welfareState.mailDefs[popup.mailIdx]
        if mail then
            nvgBeginPath(vg); nvgRect(vg, 0, 0, W, H)
            nvgFillColor(vg, nvgRGBA(0, 0, 0, 160)); nvgFill(vg)

            local pw, ph = 380, 280
            local px, py = cx - pw / 2, H / 2 - ph / 2
            nvgBeginPath(vg); nvgRoundedRect(vg, px, py, pw, ph, 14)
            nvgFillColor(vg, nvgRGBA(25, 20, 15, 240)); nvgFill(vg)
            nvgStrokeColor(vg, nvgRGBA(200, 160, 80, 160)); nvgStrokeWidth(vg, 2); nvgStroke(vg)
            popup.bgRect = { x = px, y = py, w = pw, h = ph }

            local popTitle = popup.cloudMail and (mail.subject or "领取") or mail.title
            nvgFontSize(vg, 26); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
            DrawWhiteInkText(cx, py + 30, "领取: " .. popTitle)

            local rewards = popup.cloudMail and (mail.rewards or {}) or (mail.rewards or {})
            nvgFontSize(vg, 20); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_TOP)
            local ry0 = py + 60
            for ri, rw in ipairs(rewards) do
                if rw.type == "jade" then
                    nvgFillColor(vg, nvgRGBA(255, 220, 100, 240))
                elseif rw.type == "ad_free" then
                    nvgFillColor(vg, nvgRGBA(100, 255, 150, 240))
                else
                    nvgFillColor(vg, nvgRGBA(200, 160, 255, 240))
                end
                nvgText(vg, cx, ry0 + (ri - 1) * 30, rw.label or "", nil)
            end

            if not popup.cloudMail then
                nvgFontSize(vg, 14); nvgFillColor(vg, nvgRGBA(160, 150, 130, 180))
                nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
                nvgText(vg, cx, ry0 + #rewards * 30 + 16, "武技残片将分配给每个已开放的武技", nil)
            end

            local cbW, cbH = 140, 42
            local cbX = cx - cbW / 2
            local cbY = py + ph - cbH - 20
            local cbP = 0.85 + 0.15 * math.sin(t * 3.0)
            nvgBeginPath(vg); nvgRoundedRect(vg, cbX, cbY, cbW, cbH, 8)
            nvgFillColor(vg, nvgRGBA(180, 80, 30, math.floor(230 * cbP))); nvgFill(vg)
            nvgStrokeColor(vg, nvgRGBA(255, 200, 100, math.floor(180 * cbP))); nvgStrokeWidth(vg, 1.5); nvgStroke(vg)
            nvgFontSize(vg, 22); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
            DrawWhiteInkText(cbX + cbW / 2, cbY + cbH / 2, "确认领取")
            popup.confirmBtnRect = { x = cbX, y = cbY, w = cbW, h = cbH }

            local clR = 16
            local clX = px + pw - 25
            local clY = py + 20
            nvgBeginPath(vg); nvgCircle(vg, clX, clY, clR)
            nvgFillColor(vg, nvgRGBA(60, 50, 40, 200)); nvgFill(vg)
            nvgStrokeColor(vg, nvgRGBA(160, 140, 110, 150)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
            nvgFontSize(vg, 20); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
            nvgFillColor(vg, nvgRGBA(200, 190, 170, 220))
            nvgText(vg, clX, clY, "X", nil)
            popup.closeBtnRect = { x = clX - clR, y = clY - clR, w = clR * 2, h = clR * 2 }
        end
    end
end

