-- ============================================================================
-- 排位赛 - 选择界面
-- ============================================================================
function DrawRankedSelectScreen()
    if gameState.phase ~= "RANKED_SELECT" then return end
    local W = DESIGN_W
    local H = DESIGN_H
    local cx = W / 2
    local t = gameState.gameTime
    local tier = GetRankedTier(rankedState.score)
    local tc = tier.color

    -- 排位专属背景
    DrawBgImage(IMG.rankedSelectBg, W, H, 1143, 2048)
    nvgBeginPath(vg); nvgRect(vg, 0, 0, W, H)
    nvgFillColor(vg, nvgRGBA(15, 10, 5, 60)); nvgFill(vg)
    local botGrad = nvgLinearGradient(vg, 0, H * 0.7, 0, H,
        nvgRGBA(0, 0, 0, 0), nvgRGBA(20, 10, 0, 140))
    nvgBeginPath(vg); nvgRect(vg, 0, H * 0.7, W, H * 0.3)
    nvgFillPaint(vg, botGrad); nvgFill(vg)

    nvgFontFaceId(vg, GetMainFont())

    -- 匹配中覆盖层
    if rankedState.isMatching then
        nvgBeginPath(vg); nvgRect(vg, 0, 0, W, H)
        nvgFillColor(vg, nvgRGBA(5, 5, 12, 130)); nvgFill(vg)
        -- 匹配动画
        local dots = string.rep(".", math.floor(rankedState.matchAnim * 4) % 4)
        nvgFontSize(vg, 36)
        nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        DrawWhiteInkText(cx, H * 0.35, "正在匹配对手" .. dots)
        -- 旋转圈
        local angle = rankedState.matchAnim * 6
        local ringR = 30
        local ringCY = H * 0.5
        for i = 0, 7 do
            local a = angle + i * math.pi / 4
            local px = cx + math.cos(a) * ringR
            local py = ringCY + math.sin(a) * ringR
            local alpha = math.floor(255 * (1 - i / 8))
            nvgBeginPath(vg); nvgCircle(vg, px, py, 4)
            nvgFillColor(vg, nvgRGBA(255, 200, 80, alpha)); nvgFill(vg)
        end
        -- 对手信息预览
        nvgFontSize(vg, 28)
        DrawWhiteInkText(cx, H * 0.65, "对手: " .. rankedState.opponentName)
        nvgFontSize(vg, 24)
        nvgFillColor(vg, nvgRGBA(255, 200, 100, 200))
        nvgText(vg, cx, H * 0.7, "战力: " .. FormatPower(rankedState.opponentPower), nil)
        return
    end

    -- 排行榜弹窗
    if rankedState.showLeaderboard then
        nvgBeginPath(vg); nvgRect(vg, 0, 0, W, H)
        nvgFillColor(vg, nvgRGBA(0, 0, 0, 180)); nvgFill(vg)
        local popW = W - 40
        local popH = H - 60
        local popX = 20
        local popY = 30
        nvgBeginPath(vg); nvgRoundedRect(vg, popX, popY, popW, popH, 10)
        nvgFillColor(vg, nvgRGBA(20, 18, 35, 240)); nvgFill(vg)
        nvgBeginPath(vg); nvgRoundedRect(vg, popX, popY, popW, popH, 10)
        nvgStrokeColor(vg, nvgRGBA(255, 200, 80, 160)); nvgStrokeWidth(vg, 1.5); nvgStroke(vg)
        -- 标题
        nvgFontSize(vg, 34); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        DrawWhiteInkText(cx, popY + 28, "排位排行榜")
        -- 关闭按钮
        local closeBtnW, closeBtnH = 80, 34
        nvgBeginPath(vg); nvgRoundedRect(vg, cx - closeBtnW/2, popY + popH - 46, closeBtnW, closeBtnH, 6)
        nvgFillColor(vg, nvgRGBA(60, 40, 30, 200)); nvgFill(vg)
        nvgStrokeColor(vg, nvgRGBA(200, 160, 80, 140)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
        nvgFontSize(vg, 26)
        DrawWhiteInkText(cx, popY + popH - 29, "关闭")
        rankedState.backBtnRect = { x = cx - closeBtnW/2, y = popY + popH - 46, w = closeBtnW, h = closeBtnH }
        -- 列表
        if rankedState.rankLoading and not rankedState.rankLoaded then
            nvgFontSize(vg, 26)
            DrawWhiteInkText(cx, popY + popH/2, "加载中...")
        elseif #rankedState.rankList == 0 then
            nvgFontSize(vg, 26)
            DrawWhiteInkText(cx, popY + popH/2, "暂无排行数据")
        else
            nvgSave(vg)
            nvgScissor(vg, popX + 8, popY + 54, popW - 16, popH - 110)
            local listY = popY + 72 - rankedState.rankScroll.offset
            for i, entry in ipairs(rankedState.rankList) do
                local ey = listY + (i - 1) * 36
                if ey > popY + 54 and ey < popY + popH - 55 then
                    local eTier = GetRankedTier(entry.score)
                    nvgFontSize(vg, 24); nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)
                    -- 排名
                    local rankStr = "#" .. i
                    local rankColor = (i <= 3) and nvgRGBA(255, 200, 60, 240) or nvgRGBA(200, 200, 200, 200)
                    nvgFillColor(vg, rankColor)
                    nvgText(vg, popX + 16, ey, rankStr, nil)
                    -- 名字（根据排名宽度动态偏移）
                    local nameX = popX + 70
                    nvgFillColor(vg, nvgRGBA(220, 220, 220, 230))
                    nvgText(vg, nameX, ey, entry.name, nil)
                    -- 段位名称
                    nvgTextAlign(vg, NVG_ALIGN_RIGHT + NVG_ALIGN_MIDDLE)
                    nvgFillColor(vg, nvgRGBA(eTier.color[1], eTier.color[2], eTier.color[3], 230))
                    nvgFontSize(vg, 20)
                    nvgText(vg, popX + popW - 20, ey, eTier.name .. " " .. tostring(entry.score) .. "分", nil)
                end
            end
            nvgRestore(vg)
        end
        return
    end

    -- 顶部返回按钮
    local topY = 14
    local backW, backH = 100, 38
    nvgBeginPath(vg); nvgRoundedRect(vg, 14, topY, backW, backH, 6)
    nvgFillColor(vg, nvgRGBA(15, 12, 30, 200)); nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(200, 160, 60, 140)); nvgStrokeWidth(vg, 1.2); nvgStroke(vg)
    nvgFontSize(vg, 26); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    nvgFillColor(vg, nvgRGBA(5, 5, 12, 95))
    nvgText(vg, 14 + backW/2 + 1, topY + backH/2 + 1, "< 返回", nil)
    DrawWhiteInkText(14 + backW/2, topY + backH/2, "< 返回")
    rankedState.backBtnRect = { x = 14, y = topY, w = backW, h = backH }

    -- 标题
    local titleCY = topY + backH/2
    nvgFontSize(vg, 38); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    nvgFillColor(vg, nvgRGBA(5, 5, 12, 130))
    nvgText(vg, cx + 2, titleCY + 2, "排位赛", nil)
    nvgFillColor(vg, nvgRGBA(tc[1], tc[2], tc[3], 200))
    nvgText(vg, cx + 1, titleCY + 1, "排位赛", nil)
    DrawWhiteInkText(cx, titleCY, "排位赛")
    DrawHelpBtn(DESIGN_W - 14 - 30, topY + (backH - 30) / 2, 30)

    -- 副标题
    nvgFontSize(vg, 27)
    DrawWhiteInkText(cx, titleCY + 22, "- 武灵对决 - 段位攀升 -")

    -- 装饰分隔线
    local sepY2 = titleCY + 36
    local sepHalfW2 = 130
    local lineGradL2 = nvgLinearGradient(vg, cx - sepHalfW2, sepY2, cx - 8, sepY2,
        nvgRGBA(tc[1], tc[2], tc[3], 0), nvgRGBA(tc[1], tc[2], tc[3], 160))
    nvgBeginPath(vg)
    nvgMoveTo(vg, cx - sepHalfW2, sepY2); nvgLineTo(vg, cx - 8, sepY2)
    nvgStrokeWidth(vg, 1.2); nvgStrokePaint(vg, lineGradL2); nvgStroke(vg)
    local lineGradR2 = nvgLinearGradient(vg, cx + 8, sepY2, cx + sepHalfW2, sepY2,
        nvgRGBA(tc[1], tc[2], tc[3], 160), nvgRGBA(tc[1], tc[2], tc[3], 0))
    nvgBeginPath(vg)
    nvgMoveTo(vg, cx + 8, sepY2); nvgLineTo(vg, cx + sepHalfW2, sepY2)
    nvgStrokeWidth(vg, 1.2); nvgStrokePaint(vg, lineGradR2); nvgStroke(vg)
    nvgBeginPath(vg)
    nvgMoveTo(vg, cx, sepY2 - 4); nvgLineTo(vg, cx + 4, sepY2)
    nvgLineTo(vg, cx, sepY2 + 4); nvgLineTo(vg, cx - 4, sepY2)
    nvgClosePath(vg)
    nvgFillColor(vg, nvgRGBA(tc[1], tc[2], tc[3], 200)); nvgFill(vg)

    -- 段位卡片
    local contentY = sepY2 + 25
    local cardW = W - 60
    local cardH = 150
    local cardX = 30
    nvgBeginPath(vg); nvgRoundedRect(vg, cardX, contentY, cardW, cardH, 8)
    nvgFillColor(vg, nvgRGBA(22, 20, 40, 200)); nvgFill(vg)
    local cardPulse = 0.7 + 0.3 * math.sin(t * 2)
    nvgBeginPath(vg); nvgRoundedRect(vg, cardX, contentY, cardW, cardH, 8)
    nvgStrokeColor(vg, nvgRGBA(tc[1], tc[2], tc[3], math.floor(150 * cardPulse)))
    nvgStrokeWidth(vg, 1.2); nvgStroke(vg)

    -- 段位大图标
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    nvgFontSize(vg, 56)
    nvgFillColor(vg, nvgRGBA(tc[1], tc[2], tc[3], 240))
    nvgText(vg, cardX + 50, contentY + 55, tier.icon, nil)

    -- 段位名称
    nvgFontSize(vg, 38)
    nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)
    nvgFillColor(vg, nvgRGBA(tc[1], tc[2], tc[3], 240))
    nvgText(vg, cardX + 85, contentY + 40, tier.name, nil)

    -- 积分
    nvgFontSize(vg, 28)
    nvgFillColor(vg, nvgRGBA(220, 220, 220, 220))
    nvgText(vg, cardX + 85, contentY + 68, "积分: " .. rankedState.score, nil)

    -- 下一段位进度
    local nextTierIdx = math.min(#RANKED_TIERS, tier.index + 1)
    local nextTier = RANKED_TIERS[nextTierIdx]
    if tier.index < #RANKED_TIERS then
        local progress = (rankedState.score - tier.minScore) / (nextTier.minScore - tier.minScore)
        progress = math.max(0, math.min(1, progress))
        nvgFontSize(vg, 22)
        nvgFillColor(vg, nvgRGBA(180, 180, 180, 180))
        nvgText(vg, cardX + 85, contentY + 92, "距" .. nextTier.name .. ": " .. (nextTier.minScore - rankedState.score) .. "分", nil)
        -- 进度条
        local barX = cardX + 85
        local barY = contentY + 106
        local barW = cardW - 120
        local barH = 8
        nvgBeginPath(vg); nvgRoundedRect(vg, barX, barY, barW, barH, 4)
        nvgFillColor(vg, nvgRGBA(40, 40, 50, 200)); nvgFill(vg)
        if progress > 0 then
            nvgBeginPath(vg); nvgRoundedRect(vg, barX, barY, barW * progress, barH, 4)
            nvgFillColor(vg, nvgRGBA(tc[1], tc[2], tc[3], 220)); nvgFill(vg)
        end
    else
        nvgFontSize(vg, 22)
        nvgFillColor(vg, nvgRGBA(255, 200, 80, 200))
        nvgText(vg, cardX + 85, contentY + 92, "已达最高段位!", nil)
    end

    -- 战绩统计
    nvgTextAlign(vg, NVG_ALIGN_RIGHT + NVG_ALIGN_MIDDLE)
    nvgFontSize(vg, 24)
    nvgFillColor(vg, nvgRGBA(100, 220, 130, 220))
    nvgText(vg, cardX + cardW - 15, contentY + 40, rankedState.wins .. "胜", nil)
    nvgFillColor(vg, nvgRGBA(255, 100, 100, 220))
    nvgText(vg, cardX + cardW - 15, contentY + 65, rankedState.losses .. "负", nil)
    local winRate = (rankedState.wins + rankedState.losses > 0)
        and math.floor(rankedState.wins / (rankedState.wins + rankedState.losses) * 100) or 0
    nvgFillColor(vg, nvgRGBA(200, 200, 200, 200))
    nvgText(vg, cardX + cardW - 15, contentY + 90, "胜率" .. winRate .. "%", nil)
    nvgFillColor(vg, nvgRGBA(255, 220, 100, 200))
    nvgFontSize(vg, 22)
    nvgText(vg, cardX + cardW - 15, contentY + 115, "最高" .. rankedState.highestScore .. "分", nil)

    -- 我的战力
    local myPower = CalcPlayerTotalPower()
    local powerY = contentY + cardH + 14
    nvgFontSize(vg, 26); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(cx, powerY, "当前战力: " .. FormatPower(myPower))

    -- 按钮区域
    local btnY = powerY + 30
    -- 开始匹配按钮
    local startBtnW = 160
    local startBtnH = 44
    local startBtnX = cx - startBtnW / 2
    local btnPulse = 0.7 + 0.3 * math.sin(t * 2.5)
    nvgBeginPath(vg); nvgRoundedRect(vg, startBtnX, btnY, startBtnW, startBtnH, 6)
    local startGrad = nvgLinearGradient(vg, startBtnX, btnY, startBtnX, btnY + startBtnH,
        nvgRGBA(200, 150, 30, math.floor(220 * btnPulse)),
        nvgRGBA(160, 100, 10, math.floor(240 * btnPulse)))
    nvgFillPaint(vg, startGrad); nvgFill(vg)
    nvgBeginPath(vg); nvgRoundedRect(vg, startBtnX, btnY, startBtnW, startBtnH, 6)
    nvgStrokeColor(vg, nvgRGBA(255, 230, 120, math.floor(180 * btnPulse)))
    nvgStrokeWidth(vg, 1.2); nvgStroke(vg)
    nvgFontSize(vg, 33); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    nvgFillColor(vg, nvgRGBA(5, 5, 12, 120))
    nvgText(vg, cx + 1, btnY + startBtnH / 2 + 1, "开始匹配", nil)
    DrawWhiteInkText(cx, btnY + startBtnH / 2, "开始匹配")
    rankedState.startBtnRect = { x = startBtnX, y = btnY, w = startBtnW, h = startBtnH }

    -- 排行榜按钮
    local rankBtnW = 100
    local rankBtnH = 36
    local rankBtnX = cx - rankBtnW / 2
    local rankBtnY = btnY + startBtnH + 12
    nvgBeginPath(vg); nvgRoundedRect(vg, rankBtnX, rankBtnY, rankBtnW, rankBtnH, 6)
    nvgFillColor(vg, nvgRGBA(30, 28, 50, 200)); nvgFill(vg)
    nvgBeginPath(vg); nvgRoundedRect(vg, rankBtnX, rankBtnY, rankBtnW, rankBtnH, 6)
    nvgStrokeColor(vg, nvgRGBA(180, 150, 80, 140)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
    nvgFontSize(vg, 26); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(cx, rankBtnY + rankBtnH / 2, "排行榜")
    rankedState.rankBtnRect = { x = rankBtnX, y = rankBtnY, w = rankBtnW, h = rankBtnH }
end

-- ============================================================================
-- 30s打桩 - 选将界面
-- ============================================================================
function DrawDummySelectScreen()
    if gameState.phase ~= "DUMMY_SELECT" then return end
    local W = DESIGN_W
    local H = DESIGN_H
    local cx = W / 2
    local t = menuAnimTimer or 0

    DrawMenuBg(W, H)
    nvgFontFaceId(vg, GetMainFont())

    -- 返回按钮
    local backW, backH = 100, 44
    local backX, backY = 10, 10
    nvgBeginPath(vg); nvgRoundedRect(vg, backX, backY, backW, backH, 6)
    nvgFillColor(vg, nvgRGBA(30, 35, 50, 220)); nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(90, 45, 55, 160)); nvgStrokeWidth(vg, 1.5); nvgStroke(vg)
    nvgFontSize(vg, 28)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(backX + backW / 2, backY + backH / 2, "< 返回")
    dummyState.backBtnRect = { x = backX, y = backY, w = backW, h = backH }

    -- 标题
    nvgFontSize(vg, 39)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    nvgFillColor(vg, nvgRGBA(255, 100, 80, 240))
    nvgText(vg, cx, 32, "30s 打桩挑战", nil)

    nvgFontSize(vg, 25)
    DrawWhiteInkText(cx, 56, "选择最多4名武灵出战")

    -- 已选武灵预览区 (顶部)
    local selY = 74
    local selSlotW = 80
    local selSlotH = 110
    local selGap = 12
    local selCardW = selSlotW - 8
    local selCardH = selCardW / CARD_RATIO  -- 保持正确比例
    local selStartX = cx - (4 * selSlotW + 3 * selGap) / 2
    for i = 1, 4 do
        local sx2 = selStartX + (i - 1) * (selSlotW + selGap)
        nvgBeginPath(vg); nvgRoundedRect(vg, sx2, selY, selSlotW, selSlotH, 6)
        if dummyState.selected[i] then
            local card = HERO_CARDS[dummyState.selected[i]]
            local qc = QUALITY_COLORS[card.quality]
            nvgFillColor(vg, nvgRGBA(qc[1], qc[2], qc[3], 40)); nvgFill(vg)
            -- 武灵卡片 (保持比例, 隐藏名字; 卡片内部已有品质边框, 不再画外框)
            DrawInventoryCard(sx2 + 4, selY + 4, selCardW, selCardH, card,
                playerHeroes[dummyState.selected[i]] and playerHeroes[dummyState.selected[i]].constellation or 0, false, true)
        else
            nvgFillColor(vg, nvgRGBA(20, 22, 35, 180)); nvgFill(vg)
            nvgBeginPath(vg); nvgRoundedRect(vg, sx2, selY, selSlotW, selSlotH, 6)
            nvgStrokeColor(vg, nvgRGBA(80, 75, 60, 80)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
            nvgFontSize(vg, 33)
            nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
            DrawWhiteInkText(sx2 + selSlotW / 2, selY + selSlotH / 2, "+")
        end
    end

    -- 开始按钮
    local startW = 200
    local startH = 44
    local startX = cx - startW / 2
    local startY = selY + selSlotH + 12
    local canStart = #dummyState.selected >= 1
    nvgBeginPath(vg); nvgRoundedRect(vg, startX, startY, startW, startH, 8)
    if canStart then
        local sp = 0.85 + 0.15 * math.sin(t * 4)
        local startGrad = nvgLinearGradient(vg, startX, startY, startX, startY + startH,
            nvgRGBA(220, 60, 40, math.floor(230 * sp)),
            nvgRGBA(160, 30, 20, math.floor(230 * sp)))
        nvgFillPaint(vg, startGrad); nvgFill(vg)
    else
        nvgFillColor(vg, nvgRGBA(40, 38, 35, 200)); nvgFill(vg)
    end
    nvgFontSize(vg, 31)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    nvgFillColor(vg, nvgRGBA(255, 240, 210, canStart and 240 or 100))
    nvgText(vg, cx, startY + startH / 2, "开始挑战 (" .. #dummyState.selected .. "/4)", nil)
    dummyState.startBtnRect = canStart and { x = startX, y = startY, w = startW, h = startH } or nil

    -- 武灵选择网格（已拥有的武灵，支持拖拽滚动）
    local gridY = startY + startH + 16
    local gridH = H - gridY - 10
    dummyState.gridH = gridH
    nvgSave(vg)
    nvgScissor(vg, 0, gridY, W, gridH)

    dummyState.cardRects = {}
    local cols = 4
    local cardW2 = math.floor((W - 32 - (cols - 1) * 8) / cols)
    local cardImgW = cardW2 - 6
    local cardImgH = cardImgW / CARD_RATIO  -- 保持正确比例
    local cardH2 = math.floor(cardImgH + 28)
    local scrollY = dummyState.scrollY
    local cardIdx = 0
    for ci = 1, #HERO_CARDS do
        if playerHeroes[ci] and playerHeroes[ci].owned then
            local col = cardIdx % cols
            local row = math.floor(cardIdx / cols)
            local cxp = 16 + col * (cardW2 + 8)
            local cyp = gridY + row * (cardH2 + 8) - scrollY
            cardIdx = cardIdx + 1

            -- 检查是否已被选中
            local isSelected = false
            for _, si in ipairs(dummyState.selected) do
                if si == ci then isSelected = true; break end
            end

            if cyp + cardH2 >= gridY and cyp <= gridY + gridH then
                local card = HERO_CARDS[ci]
                local qc = QUALITY_COLORS[card.quality]

                -- 直接使用 DrawInventoryCard 绘制完整卡片（与武灵图录一致）
                DrawInventoryCard(cxp, cyp, cardW2, cardH2, card,
                    playerHeroes[ci].constellation, false)

                -- 选中高亮边框
                if isSelected then
                    nvgBeginPath(vg); nvgRoundedRect(vg, cxp, cyp, cardW2, cardH2, 4)
                    nvgStrokeColor(vg, nvgRGBA(80, 220, 100, 200))
                    nvgStrokeWidth(vg, 2); nvgStroke(vg)

                    nvgFontFaceId(vg, GetMainFont())
                    nvgFontSize(vg, 23)
                    nvgFillColor(vg, nvgRGBA(80, 255, 120, 240))
                    nvgTextAlign(vg, NVG_ALIGN_RIGHT + NVG_ALIGN_TOP)
                    nvgText(vg, cxp + cardW2 - 4, cyp + 2, "✓", nil)
                end

                dummyState.cardRects[ci] = { x = cxp, y = cyp, w = cardW2, h = cardH2 }
            end
        end
    end
    -- 记录内容总高度
    local totalRows = math.ceil(cardIdx / cols)
    dummyState.contentH = totalRows * (cardH2 + 8) - 8
    nvgRestore(vg)
end

-- ============================================================================
-- 30s打桩 - 结果界面
-- ============================================================================
function DrawDummyResultScreen()
    if gameState.phase ~= "DUMMY_RESULT" then return end
    local W = DESIGN_W
    local H = DESIGN_H
    local cx = W / 2
    local t = menuAnimTimer or 0

    DrawMenuBg(W, H)
    nvgFontFaceId(vg, GetMainFont())

    -- 标题
    nvgFontSize(vg, 43)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    nvgFillColor(vg, nvgRGBA(255, 100, 80, 240))
    nvgText(vg, cx, H * 0.15, "挑战结束!", nil)

    -- 总伤害
    nvgFontSize(vg, 31)
    DrawWhiteInkText(cx, H * 0.25, "30秒内累计伤害")

    -- 伤害数字（大字）
    nvgFontSize(vg, 63)
    local dmgPulse = 0.9 + 0.1 * math.sin(t * 3)
    nvgFillColor(vg, nvgRGBA(255, 200, 60, math.floor(240 * dmgPulse)))
    nvgText(vg, cx, H * 0.36, tostring(math.floor(dummyState.totalDamage)), nil)

    -- DPS
    local dps = dummyState.totalDamage / 30
    nvgFontSize(vg, 31)
    nvgFillColor(vg, nvgRGBA(130, 200, 255, 220))
    nvgText(vg, cx, H * 0.45, string.format("DPS: %.0f", dps), nil)

    -- 参战武灵
    nvgFontSize(vg, 27)
    DrawWhiteInkText(cx, H * 0.54, "参战武灵")

    local cardW3 = 80
    local resCardImgW = cardW3 - 8
    local resCardImgH = resCardImgW / CARD_RATIO  -- 保持正确比例
    local cardH3 = math.floor(resCardImgH + 28)
    local gap3 = 12
    local selCount = #dummyState.selected
    local totalW = selCount * cardW3 + (selCount - 1) * gap3
    local sx3 = cx - totalW / 2
    for i, ci in ipairs(dummyState.selected) do
        local card = HERO_CARDS[ci]
        local px = sx3 + (i - 1) * (cardW3 + gap3)
        local py = H * 0.58
        DrawInventoryCard(px, py, cardW3, cardH3, card,
            playerHeroes[ci] and playerHeroes[ci].constellation or 0, false)
    end

    -- 返回按钮
    local btnW = 200
    local btnH = 50
    local btnX = cx - btnW / 2
    local btnY = H * 0.82
    nvgBeginPath(vg); nvgRoundedRect(vg, btnX, btnY, btnW, btnH, 8)
    local btnGrad = nvgLinearGradient(vg, btnX, btnY, btnX, btnY + btnH,
        nvgRGBA(200, 160, 60, 220), nvgRGBA(160, 110, 30, 220))
    nvgFillPaint(vg, btnGrad); nvgFill(vg)
    nvgFontSize(vg, 31)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    nvgFillColor(vg, nvgRGBA(40, 20, 0, 240))
    nvgText(vg, cx, btnY + btnH / 2, "返回主菜单", nil)
    dummyState.resultBackRect = { x = btnX, y = btnY, w = btnW, h = btnH }
end

-- ============================================================================
-- 开发者战场编辑器
-- ============================================================================
function DrawDevEditorScreen()
    if gameState.phase ~= "DEV_EDITOR" then return end
    local W = DESIGN_W
    local H = DESIGN_H
    local cx = W / 2
    local t = menuAnimTimer or 0

    DrawMenuBg(W, H)
    nvgFontFaceId(vg, GetMainFont())

    -- 返回按钮
    local backW, backH = 100, 44
    local backX, backY = 10, 10
    nvgBeginPath(vg); nvgRoundedRect(vg, backX, backY, backW, backH, 6)
    nvgFillColor(vg, nvgRGBA(30, 35, 50, 220)); nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(100, 180, 255, 160)); nvgStrokeWidth(vg, 1.5); nvgStroke(vg)
    nvgFontSize(vg, 28)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    nvgFillColor(vg, nvgRGBA(140, 200, 255, 240))
    nvgText(vg, backX + backW / 2, backY + backH / 2, "< 返回", nil)
    editorState.backBtnRect = { x = backX, y = backY, w = backW, h = backH }

    -- 标题
    nvgFontSize(vg, 37)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    nvgFillColor(vg, nvgRGBA(140, 200, 255, 240))
    nvgText(vg, cx, 32, "开发者·战场编辑器", nil)

    -- Tab 切换
    local tabNames = { "关卡编辑", "战斗参数", "快速测试", "石台编辑" }
    local tabW = 90
    local tabH = 36
    local tabGap = 6
    local tabStartX = cx - (#tabNames * tabW + (#tabNames - 1) * tabGap) / 2
    local tabY = 56
    editorState.tabRects = {}
    for i, name in ipairs(tabNames) do
        local tx = tabStartX + (i - 1) * (tabW + tabGap)
        local isActive = (editorState.tab == i)
        nvgBeginPath(vg); nvgRoundedRect(vg, tx, tabY, tabW, tabH, 6)
        if isActive then
            nvgFillColor(vg, nvgRGBA(50, 100, 180, 240)); nvgFill(vg)
        else
            nvgFillColor(vg, nvgRGBA(25, 30, 45, 200)); nvgFill(vg)
            nvgStrokeColor(vg, nvgRGBA(80, 130, 200, 100)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
        end
        nvgFontSize(vg, 23)
        nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        nvgFillColor(vg, isActive and nvgRGBA(240, 248, 255, 255) or nvgRGBA(140, 160, 190, 200))
        nvgText(vg, tx + tabW / 2, tabY + tabH / 2, name, nil)
        editorState.tabRects[i] = { x = tx, y = tabY, w = tabW, h = tabH }
    end

    local clipTop = tabY + tabH + 8
    local clipH = H - clipTop - 4
    local sOff = editorState.scrollY

    nvgSave(vg)
    nvgScissor(vg, 0, clipTop, W, clipH)

    local pad = 14
    local secW = W - pad * 2

    if editorState.tab == 1 then
        -- =====================
        -- Tab 1: 关卡编辑
        -- =====================
        local startY = clipTop + 10 + sOff
        editorState.btnRects = {}

        -- 关卡列表
        local cardH = 90
        local cardGap = 8
        for si, stage in ipairs(STAGES) do
            local cy = startY + (si - 1) * (cardH + cardGap)
            local isSelected = (editorState.selectedStage == si)
            local sc = stage.color or {180, 180, 180}

            nvgBeginPath(vg); nvgRoundedRect(vg, pad, cy, secW, cardH, 8)
            if isSelected then
                nvgFillColor(vg, nvgRGBA(30, 50, 80, 230))
            else
                nvgFillColor(vg, nvgRGBA(18, 22, 38, 220))
            end
            nvgFill(vg)
            nvgBeginPath(vg); nvgRoundedRect(vg, pad, cy, secW, cardH, 8)
            nvgStrokeColor(vg, isSelected and nvgRGBA(sc[1], sc[2], sc[3], 200) or nvgRGBA(60, 70, 90, 100))
            nvgStrokeWidth(vg, isSelected and 2 or 1); nvgStroke(vg)

            -- 左侧颜色标记
            nvgBeginPath(vg); nvgRoundedRect(vg, pad, cy + 6, 4, cardH - 12, 2)
            nvgFillColor(vg, nvgRGBA(sc[1], sc[2], sc[3], 220)); nvgFill(vg)

            -- 关卡名
            nvgFontSize(vg, 27)
            nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)
            nvgFillColor(vg, nvgRGBA(sc[1], sc[2], sc[3], 240))
            nvgText(vg, pad + 16, cy + 22, si .. ". " .. stage.name, nil)

            -- 描述
            nvgFontSize(vg, 19)
            DrawWhiteInkText(pad + 16, cy + 46, stage.desc)

            -- 参数
            local sOver = editorState.stageOverrides[si]
            local eScale = sOver and sOver.enemyScale or stage.enemyScale
            nvgFontSize(vg, 18)
            DrawWhiteInkText(pad + 16, cy + 68, string.format("难度x%.1f  掉落阶%d", eScale, stage.maxTier))

            -- 难度调整按钮 (- / +)
            local adjBtnW = 34
            local adjBtnH = 28
            local adjY = cy + cardH / 2 - adjBtnH / 2

            -- 减
            local minusBtnX = secW - 10 - adjBtnW * 2 - 8
            nvgBeginPath(vg); nvgRoundedRect(vg, minusBtnX, adjY, adjBtnW, adjBtnH, 5)
            nvgFillColor(vg, nvgRGBA(180, 60, 50, 200)); nvgFill(vg)
            nvgFontSize(vg, 25); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
            DrawWhiteInkText(minusBtnX + adjBtnW / 2, adjY + adjBtnH / 2, "-")

            -- 加
            local plusBtnX = secW - 10 - adjBtnW
            nvgBeginPath(vg); nvgRoundedRect(vg, plusBtnX, adjY, adjBtnW, adjBtnH, 5)
            nvgFillColor(vg, nvgRGBA(50, 140, 80, 200)); nvgFill(vg)
            nvgFontSize(vg, 25); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
            DrawWhiteInkText(plusBtnX + adjBtnW / 2, adjY + adjBtnH / 2, "+")

            editorState.btnRects["stage_" .. si] = { x = pad, y = cy, w = secW, h = cardH }
            editorState.btnRects["stage_minus_" .. si] = { x = minusBtnX, y = adjY, w = adjBtnW, h = adjBtnH }
            editorState.btnRects["stage_plus_" .. si] = { x = plusBtnX, y = adjY, w = adjBtnW, h = adjBtnH }
        end

        -- 重置按钮
        local resetY = startY + #STAGES * (cardH + cardGap) + 12
        local resetW = 160
        local resetH = 40
        local resetX = cx - resetW / 2
        nvgBeginPath(vg); nvgRoundedRect(vg, resetX, resetY, resetW, resetH, 8)
        nvgFillColor(vg, nvgRGBA(120, 50, 40, 200)); nvgFill(vg)
        nvgFontSize(vg, 23); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        DrawWhiteInkText(cx, resetY + resetH / 2, "重置全部难度")
        editorState.btnRects["reset_stages"] = { x = resetX, y = resetY, w = resetW, h = resetH }

        local totalH = #STAGES * (cardH + cardGap) + 12 + resetH + 30
        editorState.contentHeight = math.max(0, totalH - clipH)

    elseif editorState.tab == 2 then
        -- =====================
        -- Tab 2: 战斗参数
        -- =====================
        local startY = clipTop + 10 + sOff
        editorState.btnRects = {}

        local params = {
            { key = "baseHpMax",        label = "基地血量",     default = GameConfig.BASE_HP_MAX,       step = 50, min = 100, max = 5000 },
            { key = "initialGold",      label = "初始军资",     default = GameConfig.INITIAL_GOLD,      step = 5,  min = 0,   max = 200 },
            { key = "enemySpawnCd",     label = "敌方出兵CD",   default = GameConfig.ENEMY_SPAWN_CD,    step = 0.1, min = 0.3, max = 10, fmt = "%.1f秒" },
            { key = "playerSpawnCd",    label = "我方出兵CD",   default = GameConfig.PLAYER_SPAWN_CD,   step = 0.1, min = 0.3, max = 10, fmt = "%.1f秒" },
            { key = "battleTimeLimit",  label = "战斗时限",     default = GameConfig.BATTLE_TIME_LIMIT or 180, step = 15, min = 30, max = 600, fmt = "%d秒" },
            { key = "soldierStatScale", label = "兵属性倍率",   default = GameConfig.SOLDIER_STAT_SCALE, step = 0.05, min = 0.05, max = 2.0, fmt = "%.2f" },
            { key = "deployCd",         label = "部署冷却",     default = GameConfig.DEPLOY_CD or 3.5,  step = 0.5, min = 1, max = 20, fmt = "%.1f秒" },
        }

        local cardH = 60
        local cardGap = 6
        for pi, p in ipairs(params) do
            local cy = startY + (pi - 1) * (cardH + cardGap)
            local curVal = editorState.overrides[p.key] or p.default

            nvgBeginPath(vg); nvgRoundedRect(vg, pad, cy, secW, cardH, 8)
            nvgFillColor(vg, nvgRGBA(18, 24, 40, 220)); nvgFill(vg)
            nvgBeginPath(vg); nvgRoundedRect(vg, pad, cy, secW, cardH, 8)
            nvgStrokeColor(vg, nvgRGBA(60, 90, 140, 80)); nvgStrokeWidth(vg, 1); nvgStroke(vg)

            -- 参数名
            nvgFontSize(vg, 23)
            nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)
            nvgFillColor(vg, nvgRGBA(160, 200, 255, 230))
            nvgText(vg, pad + 14, cy + cardH / 2, p.label, nil)

            -- 当前值
            local valStr = p.fmt and string.format(p.fmt, curVal) or tostring(math.floor(curVal))
            local isModified = editorState.overrides[p.key] ~= nil
            nvgFontSize(vg, 23)
            nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
            nvgFillColor(vg, isModified and nvgRGBA(255, 200, 80, 255) or nvgRGBA(220, 220, 220, 220))
            nvgText(vg, cx + 20, cy + cardH / 2, valStr, nil)

            -- 减/加按钮
            local adjBtnW = 36
            local adjBtnH = 30
            local adjY = cy + cardH / 2 - adjBtnH / 2

            local minusBtnX = secW - 10 - adjBtnW * 2 - 10
            nvgBeginPath(vg); nvgRoundedRect(vg, minusBtnX, adjY, adjBtnW, adjBtnH, 5)
            nvgFillColor(vg, nvgRGBA(160, 50, 40, 200)); nvgFill(vg)
            nvgFontSize(vg, 25); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
            DrawWhiteInkText(minusBtnX + adjBtnW / 2, adjY + adjBtnH / 2, "-")

            local plusBtnX = secW - 10 - adjBtnW
            nvgBeginPath(vg); nvgRoundedRect(vg, plusBtnX, adjY, adjBtnW, adjBtnH, 5)
            nvgFillColor(vg, nvgRGBA(40, 130, 70, 200)); nvgFill(vg)
            nvgFontSize(vg, 25); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
            DrawWhiteInkText(plusBtnX + adjBtnW / 2, adjY + adjBtnH / 2, "+")

            editorState.btnRects["param_minus_" .. pi] = { x = minusBtnX, y = adjY, w = adjBtnW, h = adjBtnH }
            editorState.btnRects["param_plus_" .. pi] = { x = plusBtnX, y = adjY, w = adjBtnW, h = adjBtnH }
        end

        -- 重置按钮
        local resetY = startY + #params * (cardH + cardGap) + 12
        local resetW = 160
        local resetH = 40
        local resetX = cx - resetW / 2
        nvgBeginPath(vg); nvgRoundedRect(vg, resetX, resetY, resetW, resetH, 8)
        nvgFillColor(vg, nvgRGBA(120, 50, 40, 200)); nvgFill(vg)
        nvgFontSize(vg, 23); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        DrawWhiteInkText(cx, resetY + resetH / 2, "重置全部参数")
        editorState.btnRects["reset_params"] = { x = resetX, y = resetY, w = resetW, h = resetH }

        -- 应用提示
        local tipY = resetY + resetH + 16
        nvgFontSize(vg, 18)
        nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        DrawWhiteInkText(cx, tipY, "修改后的参数将在下次战斗生效")

        local totalH = #params * (cardH + cardGap) + 12 + resetH + 40
        editorState.contentHeight = math.max(0, totalH - clipH)

    elseif editorState.tab == 3 then
        -- =====================
        -- Tab 3: 快速测试
        -- =====================
        local startY = clipTop + 30 + sOff
        editorState.btnRects = {}

        -- 关卡选择
        nvgFontSize(vg, 25)
        nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        nvgFillColor(vg, nvgRGBA(160, 200, 255, 230))
        nvgText(vg, cx, startY, "选择测试关卡", nil)
        startY = startY + 36

        local cols = 3
        local btnW2 = math.floor((secW - (cols - 1) * 8) / cols)
        local btnH2 = 50
        for si, stage in ipairs(STAGES) do
            local col = (si - 1) % cols
            local row = math.floor((si - 1) / cols)
            local bx = pad + col * (btnW2 + 8)
            local by = startY + row * (btnH2 + 8)
            local isSelected = (editorState.testStage == si)
            local sc = stage.color or {180, 180, 180}

            nvgBeginPath(vg); nvgRoundedRect(vg, bx, by, btnW2, btnH2, 6)
            if isSelected then
                nvgFillColor(vg, nvgRGBA(sc[1], sc[2], sc[3], 60)); nvgFill(vg)
                nvgBeginPath(vg); nvgRoundedRect(vg, bx, by, btnW2, btnH2, 6)
                nvgStrokeColor(vg, nvgRGBA(sc[1], sc[2], sc[3], 220)); nvgStrokeWidth(vg, 2); nvgStroke(vg)
            else
                nvgFillColor(vg, nvgRGBA(25, 30, 45, 200)); nvgFill(vg)
                nvgBeginPath(vg); nvgRoundedRect(vg, bx, by, btnW2, btnH2, 6)
                nvgStrokeColor(vg, nvgRGBA(60, 70, 90, 100)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
            end
            nvgFontSize(vg, 21)
            nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
            nvgFillColor(vg, isSelected and nvgRGBA(255, 255, 255, 240) or nvgRGBA(sc[1], sc[2], sc[3], 200))
            nvgText(vg, bx + btnW2 / 2, by + btnH2 / 2, stage.name, nil)

            editorState.btnRects["test_stage_" .. si] = { x = bx, y = by, w = btnW2, h = btnH2 }
        end

        local rows = math.ceil(#STAGES / cols)
        local gridBottom = startY + rows * (btnH2 + 8)

        -- 配置摘要
        local sumY = gridBottom + 20
        nvgFontSize(vg, 21)
        nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        nvgFillColor(vg, nvgRGBA(200, 190, 140, 200))
        local selectedStage = STAGES[editorState.testStage]
        local sOver = editorState.stageOverrides[editorState.testStage]
        local eScale = sOver and sOver.enemyScale or selectedStage.enemyScale
        nvgText(vg, cx, sumY, string.format("当前: %s (难度x%.1f)", selectedStage.name, eScale), nil)

        -- 显示修改过的参数
        sumY = sumY + 28
        local hasOverrides = false
        for k, v in pairs(editorState.overrides) do
            if v ~= nil then hasOverrides = true; break end
        end
        if hasOverrides then
            nvgFontSize(vg, 18)
            DrawWhiteInkText(cx, sumY, "⚠ 存在参数覆盖（黄色标记）")
            sumY = sumY + 24
        end

        -- 开始测试按钮
        local testBtnW = 240
        local testBtnH = 52
        local testBtnX = cx - testBtnW / 2
        local testBtnY = sumY + 10
        local pulse = 0.8 + 0.2 * math.sin(t * 3)
        nvgBeginPath(vg); nvgRoundedRect(vg, testBtnX, testBtnY, testBtnW, testBtnH, 10)
        local testGrad = nvgLinearGradient(vg, testBtnX, testBtnY, testBtnX, testBtnY + testBtnH,
            nvgRGBA(50, math.floor(140 * pulse), math.floor(220 * pulse), 230),
            nvgRGBA(30, math.floor(90 * pulse), math.floor(160 * pulse), 230))
        nvgFillPaint(vg, testGrad); nvgFill(vg)
        nvgFontSize(vg, 29)
        nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        DrawWhiteInkText(cx, testBtnY + testBtnH / 2, "开始测试战斗")
        editorState.btnRects["start_test"] = { x = testBtnX, y = testBtnY, w = testBtnW, h = testBtnH }

        editorState.contentHeight = 0  -- 单屏即可

    elseif editorState.tab == 4 then
        -- =====================
        -- Tab 4: 石台编辑
        -- =====================
        editorState.btnRects = {}
        local layoutIdx = editorState.editLayoutIdx or 1
        local layout = BATTLE_LAYOUTS[layoutIdx]
        if not layout then layout = BATTLE_LAYOUTS[1]; layoutIdx = 1 end

        -- 布局选择器 (顶部两行按钮: 第1行=默认+讨伐1~4, 第2行=讨伐5~7)
        local selY = clipTop + 4
        local selBtnH = 24
        local selGap = 3
        local availW = W - pad * 2
        -- 简短标签
        local shortNames = { "默认", "讨伐1", "讨伐2", "讨伐3", "讨伐4", "讨伐5", "讨伐6", "讨伐7" }
        -- 第1行: 布局 1~4
        local row1Count = 4
        local selBtnW1 = math.floor((availW - selGap * (row1Count - 1)) / row1Count)
        for li = 1, row1Count do
            local bx = pad + (li - 1) * (selBtnW1 + selGap)
            local isActive = (li == layoutIdx)
            nvgBeginPath(vg); nvgRoundedRect(vg, bx, selY, selBtnW1, selBtnH, 4)
            nvgFillColor(vg, isActive and nvgRGBA(50, 100, 180, 230) or nvgRGBA(25, 30, 45, 200)); nvgFill(vg)
            nvgFontSize(vg, 16); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
            nvgFillColor(vg, isActive and nvgRGBA(240, 248, 255, 255) or nvgRGBA(140, 160, 190, 200))
            nvgText(vg, bx + selBtnW1 / 2, selY + selBtnH / 2, shortNames[li] or ("L" .. li), nil)
            editorState.btnRects["layout_" .. li] = { x = bx, y = selY, w = selBtnW1, h = selBtnH }
        end
        -- 第2行: 布局 5~8
        local selY2 = selY + selBtnH + selGap
        local row2Count = #BATTLE_LAYOUTS - row1Count
        local selBtnW2 = math.floor((availW - selGap * (row2Count - 1)) / row2Count)
        for li = row1Count + 1, #BATTLE_LAYOUTS do
            local ri = li - row1Count
            local bx = pad + (ri - 1) * (selBtnW2 + selGap)
            local isActive = (li == layoutIdx)
            nvgBeginPath(vg); nvgRoundedRect(vg, bx, selY2, selBtnW2, selBtnH, 4)
            nvgFillColor(vg, isActive and nvgRGBA(50, 100, 180, 230) or nvgRGBA(25, 30, 45, 200)); nvgFill(vg)
            nvgFontSize(vg, 16); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
            nvgFillColor(vg, isActive and nvgRGBA(240, 248, 255, 255) or nvgRGBA(140, 160, 190, 200))
            nvgText(vg, bx + selBtnW2 / 2, selY2 + selBtnH / 2, shortNames[li] or ("L" .. li), nil)
            editorState.btnRects["layout_" .. li] = { x = bx, y = selY2, w = selBtnW2, h = selBtnH }
        end

        -- 背景预览区域 (尽可能大, 等比缩放)
        local prevTop = selY2 + selBtnH + 8
        local prevAvailH = H - prevTop - 88  -- 底部留按钮栏+图例
        local prevAvailW = W - pad * 2
        -- 背景原始比例 BG_W:BG_H = 1142:2048
        local bgAspect = BG_W / BG_H
        local prevH = prevAvailH
        local prevW = prevH * bgAspect
        if prevW > prevAvailW then
            prevW = prevAvailW
            prevH = prevW / bgAspect
        end
        local prevX = cx - prevW / 2
        local prevY = prevTop

        editorState.previewRect = { x = prevX, y = prevY, w = prevW, h = prevH }

        -- 绘制背景图
        local bgH = layout.bgHandle or IMG.bg
        if bgH and IsImageReady(bgH) then
            local pat = nvgImagePattern(vg, prevX, prevY, prevW, prevH, 0, bgH, 0.85)
            nvgBeginPath(vg); nvgRoundedRect(vg, prevX, prevY, prevW, prevH, 4)
            nvgFillPaint(vg, pat); nvgFill(vg)
        else
            nvgBeginPath(vg); nvgRoundedRect(vg, prevX, prevY, prevW, prevH, 4)
            nvgFillColor(vg, nvgRGBA(30, 35, 50, 200)); nvgFill(vg)
        end
        -- 坐标转换: 背景像素 → 预览坐标
        local function BgToPreview(bgPx, bgPy)
            return prevX + bgPx * (prevW / BG_W), prevY + bgPy * (prevH / BG_H)
        end

        -- 卡牌缩略图尺寸 (按背景像素空间中的卡牌占位计算)
        local cardBgW = SLOT_CARD_W / BG2D_X  -- 设计尺寸→背景像素
        local cardBgH = SLOT_CARD_H / BG2D_Y
        local cardPrevW = cardBgW * (prevW / BG_W)  -- 背景像素→预览像素
        local cardPrevH = cardBgH * (prevH / BG_H)
        local slotR = math.max(8, prevW * 0.025)
        local hitR = math.max(slotR, cardPrevW * 0.6)  -- 点击区域

        -- 绘制敌方石台 (红色)
        for ei, pos in ipairs(layout.enemySlots) do
            local sx, sy = BgToPreview(pos[1], pos[2])
            local key = "enemy_" .. ei
            local isSel = editorState.selectedSlots[key]
            local isDragging = editorState.slotDragging and isSel
            -- 卡牌缩略图 (使用武灵独立图)
            local previewCard = ENEMY_CARDS[((ei - 1) % #ENEMY_CARDS) + 1]
            local prevImg = previewCard and GetHeroSheet(previewCard) or -1
            if prevImg and prevImg > 0 then
                local imgW, imgH = nvgImageSize(vg, prevImg)
                if imgW > 4 and imgH > 4 then
                    local p = nvgImagePattern(vg, sx - cardPrevW / 2, sy - cardPrevH / 2, cardPrevW, cardPrevH, 0, prevImg, 0.7)
                    nvgBeginPath(vg); nvgRoundedRect(vg, sx - cardPrevW / 2, sy - cardPrevH / 2, cardPrevW, cardPrevH, 2)
                    nvgFillPaint(vg, p); nvgFill(vg)
                end
            end
            -- 选中高亮圈
            if isSel then
                nvgBeginPath(vg); nvgCircle(vg, sx, sy, slotR + 4)
                nvgStrokeColor(vg, nvgRGBA(255, 230, 60, 220))
                nvgStrokeWidth(vg, 2.5); nvgStroke(vg)
            end
            -- 外圈
            nvgBeginPath(vg); nvgCircle(vg, sx, sy, slotR + 1)
            nvgStrokeColor(vg, isDragging and nvgRGBA(255, 255, 100, 240) or nvgRGBA(255, 80, 60, 200))
            nvgStrokeWidth(vg, isDragging and 3 or 1.5); nvgStroke(vg)
            -- 标号
            nvgFontSize(vg, math.max(10, slotR * 1.0))
            nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
            DrawWhiteInkText(sx, sy, "E" .. ei)
            editorState.btnRects["eslot_" .. ei] = { x = sx - hitR, y = sy - hitR, w = hitR * 2, h = hitR * 2 }
        end

        -- 绘制玩家石台 (蓝色)
        for pi, pos in ipairs(layout.playerSlots) do
            local sx, sy = BgToPreview(pos[1], pos[2])
            local key = "player_" .. pi
            local isSel = editorState.selectedSlots[key]
            local isDragging = editorState.slotDragging and isSel
            -- 卡牌缩略图 (玩家第一张卡: row=0, col=0)
            if IMG.heroSheet and IMG.heroSheet > 0 then
                nvgSave(vg)
                nvgScissor(vg, sx - cardPrevW / 2, sy - cardPrevH / 2, cardPrevW, cardPrevH)
                local totalImgW = cardPrevW * SHEET_COLS
                local totalImgH = cardPrevH * SHEET_ROWS
                local ox = sx - cardPrevW / 2
                local oy = sy - cardPrevH / 2
                local p = nvgImagePattern(vg, ox, oy, totalImgW, totalImgH, 0, IMG.heroSheet, 0.7)
                nvgBeginPath(vg); nvgRoundedRect(vg, ox, oy, cardPrevW, cardPrevH, 2)
                nvgFillPaint(vg, p); nvgFill(vg)
                nvgRestore(vg)
            end
            -- 选中高亮圈
            if isSel then
                nvgBeginPath(vg); nvgCircle(vg, sx, sy, slotR + 4)
                nvgStrokeColor(vg, nvgRGBA(255, 230, 60, 220))
                nvgStrokeWidth(vg, 2.5); nvgStroke(vg)
            end
            -- 外圈
            nvgBeginPath(vg); nvgCircle(vg, sx, sy, slotR + 1)
            nvgStrokeColor(vg, isDragging and nvgRGBA(255, 255, 100, 240) or nvgRGBA(60, 140, 255, 200))
            nvgStrokeWidth(vg, isDragging and 3 or 1.5); nvgStroke(vg)
            -- 标号
            nvgFontSize(vg, math.max(10, slotR * 1.0))
            nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
            DrawWhiteInkText(sx, sy, "P" .. pi)
            editorState.btnRects["pslot_" .. pi] = { x = sx - hitR, y = sy - hitR, w = hitR * 2, h = hitR * 2 }
        end

        -- === 底部: 选中数量 + 坐标信息 ===
        local infoY = prevY + prevH + 4
        local selCount = 0
        for _ in pairs(editorState.selectedSlots) do selCount = selCount + 1 end
        nvgFontSize(vg, 15)
        nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)
        DrawWhiteInkText(pad, infoY + 7,
            string.format("敌%d 我%d | 选中%d", #layout.enemySlots, #layout.playerSlots, selCount))
        -- 拖拽坐标实时显示
        if editorState.slotDragging and editorState.slotPressKey then
            nvgTextAlign(vg, NVG_ALIGN_RIGHT + NVG_ALIGN_MIDDLE)
            DrawWhiteInkText(W - pad, infoY + 7, "拖拽中...")
        else
            nvgTextAlign(vg, NVG_ALIGN_RIGHT + NVG_ALIGN_MIDDLE)
            DrawWhiteInkText(W - pad, infoY + 7, "点选+拖拽移动")
        end

        -- === 底部: 操作按钮行 (2行: 选择按钮 + 撤销/保存) ===
        local btnY1 = infoY + 18
        local btnH = 26
        local btnGap = 4
        -- 第1行: 选我方 | 选敌方 | 清除选择
        local row1Btns = {
            { "sel_player", "选我方",  {50, 80, 160},  {180, 210, 255} },
            { "sel_enemy",  "选敌方",  {160, 60, 50},  {255, 200, 180} },
            { "sel_clear",  "清除",    {60, 60, 70},   {160, 160, 170} },
        }
        local r1BtnW = math.floor((availW - btnGap * (#row1Btns - 1)) / #row1Btns)
        for bi, btn in ipairs(row1Btns) do
            local bx = pad + (bi - 1) * (r1BtnW + btnGap)
            nvgBeginPath(vg); nvgRoundedRect(vg, bx, btnY1, r1BtnW, btnH, 4)
            nvgFillColor(vg, nvgRGBA(btn[3][1], btn[3][2], btn[3][3], 200)); nvgFill(vg)
            nvgFontSize(vg, 16); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
            nvgFillColor(vg, nvgRGBA(btn[4][1], btn[4][2], btn[4][3], 240))
            nvgText(vg, bx + r1BtnW / 2, btnY1 + btnH / 2, btn[2], nil)
            editorState.btnRects[btn[1]] = { x = bx, y = btnY1, w = r1BtnW, h = btnH }
        end
        -- 第2行: 撤销 | 保存配置
        local btnY2 = btnY1 + btnH + btnGap
        local undoCount = #slotUndoStack
        local saveFlash = editorState.saveFlashT and (os.clock() - editorState.saveFlashT) < 1.5
        local row2Btns = {
            { "slot_undo", "撤销(" .. undoCount .. ")",
              undoCount > 0 and {180, 140, 50} or {60, 60, 70},
              undoCount > 0 and {255, 240, 180} or {100, 100, 110} },
            { "slot_save", saveFlash and "已导出!" or "导出配置",
              saveFlash and {60, 200, 100} or {40, 140, 80},
              saveFlash and {255, 255, 255} or {220, 255, 230} },
        }
        local r2BtnW = math.floor((availW - btnGap * (#row2Btns - 1)) / #row2Btns)
        for bi, btn in ipairs(row2Btns) do
            local bx = pad + (bi - 1) * (r2BtnW + btnGap)
            nvgBeginPath(vg); nvgRoundedRect(vg, bx, btnY2, r2BtnW, btnH, 4)
            nvgFillColor(vg, nvgRGBA(btn[3][1], btn[3][2], btn[3][3], 200)); nvgFill(vg)
            nvgFontSize(vg, 16); nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
            nvgFillColor(vg, nvgRGBA(btn[4][1], btn[4][2], btn[4][3], 240))
            nvgText(vg, bx + r2BtnW / 2, btnY2 + btnH / 2, btn[2], nil)
            editorState.btnRects[btn[1]] = { x = bx, y = btnY2, w = r2BtnW, h = btnH }
        end

        editorState.contentHeight = 0
    end

    nvgRestore(vg)
end

--- 应用编辑器参数覆盖到战斗系统
function ApplyEditorOverrides()
    local o = editorState.overrides
    if o.baseHpMax then
        BASE_HP_MAX = o.baseHpMax
    end
    if o.initialGold then
        GameConfig.INITIAL_GOLD = o.initialGold
    end
    if o.enemySpawnCd then
        ENEMY_SPAWN_CD = o.enemySpawnCd
        GameConfig.ENEMY_SPAWN_CD = o.enemySpawnCd
    end
    if o.playerSpawnCd then
        PLAYER_SPAWN_CD = o.playerSpawnCd
        GameConfig.PLAYER_SPAWN_CD = o.playerSpawnCd
    end
    if o.battleTimeLimit then
        BATTLE_TIME_LIMIT = o.battleTimeLimit
        GameConfig.BATTLE_TIME_LIMIT = o.battleTimeLimit
    end
    if o.soldierStatScale then
        SOLDIER_STAT_SCALE = o.soldierStatScale
        GameConfig.SOLDIER_STAT_SCALE = o.soldierStatScale
    end
    if o.deployCd then
        DEPLOY_CD = o.deployCd
        GameConfig.DEPLOY_CD = o.deployCd
    end
    -- 应用关卡难度覆盖
    for si, sOver in pairs(editorState.stageOverrides) do
        if STAGES[si] and sOver.enemyScale then
            STAGES[si].enemyScale = sOver.enemyScale
        end
    end
end

-- ============================================================================
-- 新手引导系统
-- ============================================================================

--- 教程 Update 逻辑 (step 1 = 漫画, step 11 = 胜利过渡)
function UpdateTutorial(dt)
    local ts = tutorialState
    ts.hintTimer = ts.hintTimer + dt
    ts.fingerY = math.sin(ts.hintTimer * 3) * 6  -- 手指浮动动画

    -- (step 1 视频/漫画已移除，教程从 step 2 开始)
    if ts.step == 2 then
        -- 等待玩家点击设置按钮 (拦截在点击处理中)
        -- menuAnimTimer 已由 MENU 分支更新, 此处不重复
        ts.stepTimer = ts.stepTimer + dt
    elseif ts.step == 3 then
        -- 等待玩家点击"自动行军"开关
        ts.stepTimer = ts.stepTimer + dt
    elseif ts.step == 4 then
        -- 等待玩家点击"调整位置"
        ts.stepTimer = ts.stepTimer + dt
    elseif ts.step == 5 then
        -- 等待 btnAdjustMode 关闭
        ts.stepTimer = ts.stepTimer + dt
        if not settingsPage.btnAdjustMode then
            -- UI调整完成, 关闭设置
            settingsPage.isOpen = false
            ts.step = 6
            ts.stepTimer = 0
            phaseChangeCooldown = 0.3
            print("=== 教程: UI调整完成, 进入抽卡引导 ===")
        end
    elseif ts.step == 6 then
        -- 等待玩家点击"召唤武灵"
        -- menuAnimTimer 已由 MENU 分支更新, 此处不重复
        ts.stepTimer = ts.stepTimer + dt
    elseif ts.step == 7 then
        -- 抽卡界面中, 等待抽卡完成
        gachaState.animTimer = gachaState.animTimer + dt
        if gachaState.pulling then
            gachaState.pullTimer = gachaState.pullTimer + dt
            if gachaState.pullTimer >= 1.2 then
                gachaState.pulling = false
                gachaState.showResults = true
            end
        end
        -- 检测抽卡结果确认后进入教程战斗
        if ts.waitingGachaConfirm and not gachaState.showResults then
            ts.waitingGachaConfirm = false
            -- 进入教程战斗
            StartTutorialBattle()
        end
    elseif ts.step >= 8 and ts.step <= 13 then
        -- 教程战斗中, 使用正常战斗 update
        UpdateBattle(dt)
        ts.stepTimer = ts.stepTimer + dt
        -- step 8: 等待玩家放置武灵到石台 (自由操作, 无遮罩)
        -- 必须全部拖到石台上才进入下一步
        if ts.step == 8 then
            if GetUnsoldShopCardCount() == 0 and not IsDraggingCard() then
                ts.heroPlaced = true
                ts.step = 9
                ts.stepTimer = 0
                AddFloatText(DESIGN_W / 2, DESIGN_H * 0.35, "点击「换战场」切换战斗风格!", 2.5, {255, 220, 80}, 14)
                print("=== 教程: 武灵已全部放置, 引导换战场 ===")
            end
        end
        -- step 9: 等待玩家点击"换战场"按钮 (遮罩高亮)
        -- (推进逻辑在 HandleTutorialClick 中处理)
        -- step 10: 等待玩家点击"开战"按钮 (遮罩高亮)
        if ts.step == 10 then
            if gameState.battlePhase == "FIGHT" then
                ts.fightStarted = true
                ts.step = 11
                ts.stepTimer = 0
                gameState.gold = math.max(gameState.gold, 10)
                AddFloatText(DESIGN_W / 2, DESIGN_H * 0.35, "点击「刷新」获取新武灵!", 2.0, {255, 220, 80}, 14)
                print("=== 教程: 已开战, 引导刷新 ===")
            end
        end
        -- step 11: 等待玩家点击"刷新"按钮 (遮罩高亮)
        -- (推进逻辑在 HandleTutorialClick 中处理)
        -- step 12: 提示拖拽派放小兵, 几秒后自动进入自由战斗
        if ts.step == 12 then
            if ts.stepTimer >= 4.0 then
                ts.step = 13
                ts.stepTimer = 0
                AddFloatText(DESIGN_W / 2, DESIGN_H * 0.35, "消灭所有敌人!", 2.0, {255, 220, 80}, 14)
                print("=== 教程: 自由战斗 ===")
            end
        end
    elseif ts.step == 14 then
        -- 胜利过渡: 淡出效果
        ts.fadeTimer = ts.fadeTimer + dt
        if ts.fadeTimer >= 3.0 then
            -- 进入奖励弹窗
            ts.step = 15
            ts.stepTimer = 0
            ts.fadeTimer = 0
            -- 发放凡品兵甲奖励
            ts.tutorialReward = GrantRandomEquipment(1)  -- maxTier=1, 凡品
            print("=== 教程: 进入初始奖励弹窗 ===")
        end
    elseif ts.step == 15 then
        -- 等待玩家点击领取 (在 HandleTutorialClick 中处理)
        ts.stepTimer = ts.stepTimer + dt
    end
end

--- 启动教程战斗
function StartTutorialBattle()
    local ts = tutorialState
    -- 教程战斗: 临时解锁武技7和19供体验
    playerEquippedSkills = { 7, 19 }
    if SKILL_DEFS[7] then SKILL_DEFS[7].unlocked = true end
    if SKILL_DEFS[19] then SKILL_DEFS[19].unlocked = true end
    -- 初始化战斗
    InitBattle()
    gameState.phase = "BATTLE"
    gameState.battlePhase = "SHOP"
    -- 敌人较弱但不会秒杀 (给玩家时间学习操作)
    gameState.enemyBaseHP = 50
    gameState.enemyBaseMax = 50
    -- 教程战敌方大幅削弱，确保新手顺利破局
    local tutorialWeaken = 0.4
    for _, slot in ipairs(ENEMY_SLOTS) do
        if slot.filled and slot.card then
            slot.card.atk = math.floor(slot.card.atk * tutorialWeaken)
            slot.card.def = math.floor(slot.card.def * tutorialWeaken)
            slot.card.hp  = math.floor(slot.card.hp  * tutorialWeaken)
        end
    end
    -- 教程: 给足金币让玩家能买完所有商店卡牌
    local totalCost = 0
    for _, card in ipairs(shopCards) do
        totalCost = totalCost + card.cost
    end
    gameState.gold = totalCost
    -- 标记为教程战斗
    ts.step = 8
    ts.stepTimer = 0
    ts.heroPlaced = false
    ts.unitSpawned = false
    ts.skillUsed = false
    ts.shopRefreshed = false
    ts.fightStarted = false
    AddFloatText(DESIGN_W / 2, DESIGN_H * 0.35, "将武灵拖到石台上部署", 3.0, {255, 220, 80}, 14)
    print("=== 教程: 进入教程战斗 (先放置武灵) ===")
end

