--- 绘制教程引导遮罩 + 高亮 + 提示文字 (step 2-13)
function DrawTutorialGuideOverlay()
    local ts = tutorialState
    if not ts.active then return end
    local W, H = DESIGN_W, DESIGN_H
    local step = ts.step

    -- 确定当前步骤的目标按钮和提示文字
    local targetRect = nil
    local hintText = nil

    if step == 2 then
        targetRect = settingsPage.btnRect
        hintText = "点击「设置」按钮"
    elseif step == 3 then
        targetRect = settingsPage.autoMarchToggleRect
        hintText = "开启「自动行军」"
    elseif step == 4 then
        targetRect = settingsPage.adjustPosBtnRect
        hintText = "点击「调整位置」适配UI"
    elseif step == 5 then
        hintText = "拖动调整UI位置，完成后点击确认"
    elseif step == 6 then
        targetRect = menuBtnRects and menuBtnRects.gacha
        hintText = "点击「召唤武灵」抽取角色"
    elseif step == 7 then
        if gachaState.showResults and gachaConfirmBtnRect then
            targetRect = gachaConfirmBtnRect
            hintText = "点击确认召唤结果"
        elseif gachaState.pulling then
            hintText = "召唤中..."
        else
            targetRect = gachaSingleBtnRect
            hintText = "点击「单抽」召唤武灵"
        end
    elseif step == 8 then
        hintText = "将武灵拖放到石台上"
    elseif step == 9 then
        targetRect = battleChangeBgBtnRect
        hintText = "点击「换战场」切换战斗风格"
    elseif step == 10 then
        targetRect = shopFightBtnRect
        hintText = "点击「开战」开始战斗!"
    elseif step == 11 then
        targetRect = shopRefreshBtnRect
        hintText = "点击「刷新」获取新武灵"
    elseif step == 12 then
        hintText = "拖拽武灵部署到石台上"
    elseif step == 13 then
        hintText = "消灭所有敌人!"
    else
        return
    end

    -- 半透明遮罩 (有目标按钮时镂空高亮)
    if targetRect then
        local r = targetRect
        local pad = 8
        local hx, hy = r.x - pad, r.y - pad
        local hw, hh = r.w + pad * 2, r.h + pad * 2

        -- 四周遮罩 (上/下/左/右)
        nvgBeginPath(vg); nvgRect(vg, 0, 0, W, hy)
        nvgFillColor(vg, nvgRGBA(5, 5, 12, 160)); nvgFill(vg)
        nvgBeginPath(vg); nvgRect(vg, 0, hy + hh, W, H - hy - hh)
        nvgFillColor(vg, nvgRGBA(5, 5, 12, 160)); nvgFill(vg)
        nvgBeginPath(vg); nvgRect(vg, 0, hy, hx, hh)
        nvgFillColor(vg, nvgRGBA(5, 5, 12, 160)); nvgFill(vg)
        nvgBeginPath(vg); nvgRect(vg, hx + hw, hy, W - hx - hw, hh)
        nvgFillColor(vg, nvgRGBA(5, 5, 12, 160)); nvgFill(vg)

        -- 高亮边框 (金色脉动)
        local pulse = 0.7 + 0.3 * math.sin(ts.hintTimer * 4)
        local ga = math.floor(200 * pulse)
        nvgBeginPath(vg); nvgRoundedRect(vg, hx, hy, hw, hh, 6)
        nvgStrokeColor(vg, nvgRGBA(255, 200, 80, ga))
        nvgStrokeWidth(vg, 2.5); nvgStroke(vg)

        -- 手指动画 (在目标下方)
        local fingerX = r.x + r.w / 2
        local fingerY = r.y + r.h + 18 + ts.fingerY
        nvgFontFaceId(vg, GetMainFont())
        nvgFontSize(vg, 28)
        nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_TOP)
        nvgFillColor(vg, nvgRGBA(255, 220, 100, 230))
        nvgText(vg, fingerX, fingerY, "^", nil)
    else
        -- 无目标按钮: 淡遮罩 + 居中提示
        nvgBeginPath(vg); nvgRect(vg, 0, 0, W, H)
        nvgFillColor(vg, nvgRGBA(5, 5, 12, 80)); nvgFill(vg)
    end

    -- 提示文字 (显示在屏幕上方)
    if hintText then
        local textY = 80
        if targetRect and targetRect.y < H * 0.3 then
            textY = targetRect.y + targetRect.h + 60
        end
        nvgFontFaceId(vg, GetMainFont())
        nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)

        -- 文字背景条
        nvgFontSize(vg, 24)
        local tw = nvgTextBounds(vg, 0, 0, hintText, nil)
        local bgW = tw + 40
        local bgH = 44
        local bgX = (W - bgW) / 2
        nvgBeginPath(vg); nvgRoundedRect(vg, bgX, textY - bgH / 2, bgW, bgH, 10)
        nvgFillColor(vg, nvgRGBA(20, 15, 35, 200)); nvgFill(vg)
        nvgStrokeColor(vg, nvgRGBA(180, 140, 255, 120)); nvgStrokeWidth(vg, 1); nvgStroke(vg)

        -- 文字
        DrawWhiteInkText(W / 2, textY, hintText)
    end

    -- 退出按钮 (步骤 8-13 战斗中可退出)
    if step >= 8 and step <= 13 then
        local exitW, exitH = 80, 32
        local exitX, exitY = W - exitW - 12, 10
        nvgBeginPath(vg); nvgRoundedRect(vg, exitX, exitY, exitW, exitH, 6)
        nvgFillColor(vg, nvgRGBA(60, 40, 80, 180)); nvgFill(vg)
        nvgFontFaceId(vg, GetMainFont())
        nvgFontSize(vg, 18)
        nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        DrawWhiteInkText(exitX + exitW / 2, exitY + exitH / 2, "跳过")
        ts.tutorialSkipBtnRect = { x = exitX, y = exitY, w = exitW, h = exitH }
    end
end

function DrawTutorialExitConfirmPopup()
    local ts = tutorialState
    if not ts.exitConfirm then return end
    local W, H = DESIGN_W, DESIGN_H

    -- 半透明遮罩
    nvgBeginPath(vg); nvgRect(vg, 0, 0, W, H)
    nvgFillColor(vg, nvgRGBA(5, 5, 12, 120)); nvgFill(vg)

    -- 弹窗面板 (放大)
    local pw, ph = 380, 220
    local px, py = (W - pw) / 2, (H - ph) / 2 - 20
    -- 底板
    nvgBeginPath(vg); nvgRoundedRect(vg, px, py, pw, ph, 12)
    local bg = nvgLinearGradient(vg, px, py, px, py + ph,
        nvgRGBA(40, 30, 60, 245), nvgRGBA(25, 18, 40, 245))
    nvgFillPaint(vg, bg); nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(180, 140, 255, 120)); nvgStrokeWidth(vg, 1.5); nvgStroke(vg)

    -- 标题
    nvgFontFaceId(vg, GetMainFont())
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    nvgFontSize(vg, 32)
    DrawWhiteInkText(W / 2, py + 48, "退出战斗引导")

    -- 说明文字
    nvgFontSize(vg, 24)
    DrawWhiteInkText(W / 2, py + 95, "确认退出并直接领取奖励？")

    -- 按钮
    local btnW2, btnH2 = 130, 44
    local gap = 28
    local btnY = py + ph - 64
    local confirmX = W / 2 - btnW2 - gap / 2
    local cancelX = W / 2 + gap / 2

    -- 确认按钮
    nvgBeginPath(vg); nvgRoundedRect(vg, confirmX, btnY, btnW2, btnH2, 8)
    local cbg = nvgLinearGradient(vg, confirmX, btnY, confirmX, btnY + btnH2,
        nvgRGBA(255, 200, 80, 220), nvgRGBA(220, 160, 40, 220))
    nvgFillPaint(vg, cbg); nvgFill(vg)
    nvgFontSize(vg, 26)
    nvgFillColor(vg, nvgRGBA(50, 30, 10, 255))
    nvgText(vg, confirmX + btnW2 / 2, btnY + btnH2 / 2, "确认退出", nil)
    ts.exitConfirmBtnRect = { x = confirmX, y = btnY, w = btnW2, h = btnH2 }

    -- 取消按钮
    nvgBeginPath(vg); nvgRoundedRect(vg, cancelX, btnY, btnW2, btnH2, 8)
    nvgFillColor(vg, nvgRGBA(60, 50, 80, 200)); nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(140, 120, 180, 140)); nvgStrokeWidth(vg, 1.0); nvgStroke(vg)
    nvgFontSize(vg, 26)
    DrawWhiteInkText(cancelX + btnW2 / 2, btnY + btnH2 / 2, "继续战斗")
    ts.exitCancelBtnRect = { x = cancelX, y = btnY, w = btnW2, h = btnH2 }
end

--- 绘制胜利过渡 (step 14)
function DrawTutorialVictoryTransition()
    local ts = tutorialState
    local W, H = DESIGN_W, DESIGN_H
    local t = ts.fadeTimer

    -- 渐黑遮罩
    local alpha = math.min(1, t / 2.0)
    nvgBeginPath(vg); nvgRect(vg, 0, 0, W, H)
    nvgFillColor(vg, nvgRGBA(5, 5, 10, math.floor(255 * alpha))); nvgFill(vg)

    -- 文字 "试炼完成!"
    if t > 0.5 then
        local textAlpha = math.min(1, (t - 0.5) / 1.0)
        nvgFontFaceId(vg, GetMainFont())
        nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)

        -- 光晕
        local glowR = 60 * textAlpha
        local glow = nvgRadialGradient(vg, W / 2, H / 2 - 20, 5, glowR,
            nvgRGBA(255, 220, 80, math.floor(60 * textAlpha)),
            nvgRGBA(255, 200, 50, 0))
        nvgBeginPath(vg); nvgCircle(vg, W / 2, H / 2 - 20, glowR)
        nvgFillPaint(vg, glow); nvgFill(vg)

        nvgFontSize(vg, 43)
        nvgFillColor(vg, nvgRGBA(255, 230, 100, math.floor(255 * textAlpha)))
        nvgText(vg, W / 2, H / 2 - 20, "试炼完成!", nil)

        nvgFontSize(vg, 23)
        nvgFillColor(vg, nvgRGBA(220, 200, 150, math.floor(200 * textAlpha)))
        nvgText(vg, W / 2, H / 2 + 20, "欢迎来到讨伐...", nil)
    end
end

--- 教程初始奖励弹窗 (step 15)
function DrawTutorialRewardPopup()
    local ts = tutorialState
    local W, H = DESIGN_W, DESIGN_H
    local reward = ts.tutorialReward
    if not reward then return end

    -- 全屏黑底
    nvgBeginPath(vg); nvgRect(vg, 0, 0, W, H)
    nvgFillColor(vg, nvgRGBA(12, 12, 22, 230)); nvgFill(vg)

    local popAlpha = math.min(1, ts.stepTimer / 0.5)
    nvgSave(vg)
    nvgGlobalAlpha(vg, popAlpha)

    -- 标题
    nvgFontFaceId(vg, GetMainFont())
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    nvgFontSize(vg, 39)
    DrawWhiteInkText(W / 2, H * 0.22, "初始奖励")

    nvgFontSize(vg, 19)
    DrawWhiteInkText(W / 2, H * 0.28, "恭喜完成试炼，获得初始奖励！")

    -- 兵甲展示卡片
    local cardW, cardH = 140, 180
    local cx = W / 2 - cardW / 2
    local cy = H * 0.34
    local tierInfo = EQUIP_TIERS[reward.tier]
    local setInfo = EQUIPMENT_SETS[reward.setIdx]
    local piece = setInfo.pieces[reward.slotIdx]
    local tc = tierInfo.color

    -- 卡片背景
    nvgBeginPath(vg); nvgRoundedRect(vg, cx, cy, cardW, cardH, 8)
    nvgFillColor(vg, nvgRGBA(25, 20, 35, 220)); nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(tc[1], tc[2], tc[3], 200))
    nvgStrokeWidth(vg, 2); nvgStroke(vg)

    -- 光晕
    local glowPulse = 0.7 + 0.3 * math.sin(ts.stepTimer * 2)
    local glowR = 50 * glowPulse
    local glow = nvgRadialGradient(vg, W / 2, cy + cardH / 2 - 20, 5, glowR,
        nvgRGBA(tc[1], tc[2], tc[3], math.floor(60 * glowPulse)),
        nvgRGBA(tc[1], tc[2], tc[3], 0))
    nvgBeginPath(vg); nvgCircle(vg, W / 2, cy + cardH / 2 - 20, glowR)
    nvgFillPaint(vg, glow); nvgFill(vg)

    -- 兵甲图标
    local iconSize = 80
    local iconX = W / 2 - iconSize / 2
    local iconY = cy + 15
    if IMG.equipmentSheet and IMG.equipmentSheet > 0 then
        DrawEquipTierBg(iconX, iconY, iconSize, iconSize, reward.tier, 5)
        DrawCardImage(iconX, iconY, iconSize, iconSize,
            IMG.equipmentSheet, reward.slotIdx - 1, reward.setIdx - 1,
            EQUIP_SHEET_COLS, EQUIP_SHEET_ROWS)
    end

    -- 兵甲名称
    nvgFontSize(vg, 21)
    nvgFillColor(vg, nvgRGBA(tc[1], tc[2], tc[3], 255))
    nvgText(vg, W / 2, iconY + iconSize + 18, piece.name, nil)

    -- 品阶
    nvgFontSize(vg, 17)
    nvgFillColor(vg, nvgRGBA(tc[1], tc[2], tc[3], 180))
    nvgText(vg, W / 2, iconY + iconSize + 40, tierInfo.name, nil)

    -- 套装名
    nvgFontSize(vg, 15)
    DrawWhiteInkText(W / 2, iconY + iconSize + 58, setInfo.name)

    -- 武技奖励展示 (武技7)
    local skillRewardIdx = 7
    local skillRewardTech = SKILL_TECHNIQUES[skillRewardIdx]
    if skillRewardTech then
        local skTier = SKILL_TIERS[skillRewardTech.tier]
        local stc = skTier.color
        local skCardW, skCardH = 80, 90
        local skCx = W / 2 - skCardW / 2
        local skCy = cy + cardH + 12
        -- 小标题
        nvgFontSize(vg, 17)
        nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        DrawWhiteInkText(W / 2, skCy - 6, "额外赠送武技")
        -- 武技小卡片
        nvgBeginPath(vg); nvgRoundedRect(vg, skCx, skCy + 6, skCardW, skCardH, 6)
        nvgFillColor(vg, nvgRGBA(25, 20, 35, 220)); nvgFill(vg)
        nvgStrokeColor(vg, nvgRGBA(stc[1], stc[2], stc[3], 180))
        nvgStrokeWidth(vg, 1.5); nvgStroke(vg)
        -- 武技图标
        local skIconSz = 48
        drawSkillIcon(skillRewardTech.iconIdx, W / 2 - skIconSz / 2, skCy + 12, skIconSz, 4)
        -- 武技名
        nvgFontSize(vg, 17)
        nvgFillColor(vg, nvgRGBA(stc[1], stc[2], stc[3], 240))
        nvgText(vg, W / 2, skCy + 12 + skIconSz + 16, skillRewardTech.name, nil)
        -- 调整领取按钮Y位置
        cy = skCy + skCardH -- 更新基准
    end

    -- 领取按钮
    local btnW, btnH = 160, 44
    local btnX = W / 2 - btnW / 2
    local btnY = cy + 30
    local btnPulse = 0.85 + 0.15 * math.sin(ts.stepTimer * 3)

    nvgBeginPath(vg); nvgRoundedRect(vg, btnX, btnY, btnW, btnH, 8)
    local btnGrad = nvgLinearGradient(vg, btnX, btnY, btnX, btnY + btnH,
        nvgRGBA(255, 200, 60, math.floor(255 * btnPulse)),
        nvgRGBA(220, 160, 30, math.floor(255 * btnPulse)))
    nvgFillPaint(vg, btnGrad); nvgFill(vg)

    nvgFontSize(vg, 23)
    nvgFillColor(vg, nvgRGBA(40, 20, 0, 255))
    nvgText(vg, W / 2, btnY + btnH / 2, "领取", nil)

    -- 保存按钮区域供点击检测
    ts.rewardBtnRect = { x = btnX, y = btnY, w = btnW, h = btnH }

    nvgRestore(vg)
end

-- DrawTutorialFinger 已移除

--- 教程点击处理 (拦截非目标区域)
--- 返回 true 表示教程已处理此点击, 外部不应继续处理
function HandleTutorialClick(sx, sy)
    local ts = tutorialState
    if not ts.active then return false end

    local dx, dy = ScreenToDesign(sx, sy)

    -- 退出确认弹窗点击处理
    if ts.exitConfirm then
        if ts.exitConfirmBtnRect then
            local r = ts.exitConfirmBtnRect
            if dx >= r.x and dx <= r.x + r.w and dy >= r.y and dy <= r.y + r.h then
                -- 确认退出: 直接跳到奖励领取页
                ts.exitConfirm = false
                ts.step = 15
                ts.stepTimer = 0
                ts.fadeTimer = 0
                ts.tutorialReward = GrantRandomEquipment(1)
                print("=== 教程: 玩家确认退出引导, 直接领取奖励 ===")
                return true
            end
        end
        if ts.exitCancelBtnRect then
            local r = ts.exitCancelBtnRect
            if dx >= r.x and dx <= r.x + r.w and dy >= r.y and dy <= r.y + r.h then
                ts.exitConfirm = false
                print("=== 教程: 取消退出 ===")
                return true
            end
        end
        return true  -- 弹窗期间拦截所有点击
    end

    -- 教程战斗阶段(step 8-13): "跳过"按钮 → 弹出退出确认框
    if ts.step >= 8 and ts.step <= 13 then
        if ts.tutorialSkipBtnRect then
            local r = ts.tutorialSkipBtnRect
            if dx >= r.x and dx <= r.x + r.w and dy >= r.y and dy <= r.y + r.h then
                ts.exitConfirm = true
                print("=== 教程: 点击跳过, 弹出确认框 ===")
                return true
            end
        end
        if battleBackBtnRect then
            local r = battleBackBtnRect
            if dx >= r.x and dx <= r.x + r.w and dy >= r.y and dy <= r.y + r.h then
                ts.exitConfirm = true
                print("=== 教程: 点击退出, 弹出确认框 ===")
                return true
            end
        end
    end

    -- (step 1 视频/漫画已移除，教程从 step 2 开始)

    if ts.step == 2 then
        -- 只允许点击设置按钮
        if settingsPage.btnRect then
            local r = settingsPage.btnRect
            if dx >= r.x and dx <= r.x + r.w and dy >= r.y and dy <= r.y + r.h then
                settingsPage.isOpen = true
                ts.step = 3
                ts.stepTimer = 0
                print("=== 教程: 打开设置 ===")
                return false  -- 让正常逻辑也处理
            end
        end
        return true  -- 拦截其他点击
    end

    if ts.step == 3 then
        -- 只允许点击"自动行军"开关
        if settingsPage.autoMarchToggleRect then
            local r = settingsPage.autoMarchToggleRect
            if dx >= r.x and dx <= r.x + r.w and dy >= r.y and dy <= r.y + r.h then
                -- 强制开启自动行军
                gameSettings.defaultAutoMarch = true
                ts.step = 4
                ts.stepTimer = 0
                ShowToast("提示：可在设置中随时切换字体风格~", 3.0)
                print("=== 教程: 已开启自动行军 ===")
                return true  -- 拦截, 由教程控制状态
            end
        end
        return true  -- 拦截其他点击
    end

    if ts.step == 4 then
        -- 只允许点击"调整位置"
        if settingsPage.adjustPosBtnRect then
            local r = settingsPage.adjustPosBtnRect
            if dx >= r.x and dx <= r.x + r.w and dy >= r.y and dy <= r.y + r.h then
                settingsPage.btnAdjustMode = true
                ts.step = 5
                ts.stepTimer = 0
                print("=== 教程: 进入UI调整 ===")
                return false  -- 让正常逻辑处理
            end
        end
        return true  -- 拦截其他点击
    end

    if ts.step == 6 then
        -- 只允许点击召唤武灵按钮
        if menuBtnRects.gacha then
            local r = menuBtnRects.gacha
            if dx >= r.x and dx <= r.x + r.w and dy >= r.y and dy <= r.y + r.h then
                -- 确保有足够虎符
                if playerInfo.jade < GameConfig.GACHA_COST_SINGLE then
                    playerInfo.jade = playerInfo.jade + GameConfig.GACHA_COST_SINGLE
                end
                PushPhase("GACHA")
                ts.step = 7
                ts.stepTimer = 0
                phaseChangeCooldown = 0.3
                print("=== 教程: 进入抽卡 ===")
                return true
            end
        end
        return true  -- 拦截其他点击
    end

    if ts.step == 7 then
        -- 抽卡界面: 拦截部分按钮
        -- 允许: 单抽, 确认结果
        -- 不允许: 十连, 返回, tab切换, 规则

        if gachaState.showResults then
            -- 允许确认结果
            if gachaConfirmBtnRect then
                local r = gachaConfirmBtnRect
                if dx >= r.x and dx <= r.x + r.w and dy >= r.y and dy <= r.y + r.h then
                    gachaState.showResults = false
                    gachaState.results = {}
                    gachaState.skillResults = {}
                    ts.waitingGachaConfirm = true
                    return true
                end
            end
            return true
        end

        if gachaState.pulling then
            -- 允许跳过动画
            gachaState.pulling = false
            gachaState.showResults = true
            return true
        end

        -- 单抽按钮
        if gachaSingleBtnRect then
            local r = gachaSingleBtnRect
            if dx >= r.x and dx <= r.x + r.w and dy >= r.y and dy <= r.y + r.h then
                -- 确保有足够虎符
                if playerInfo.jade < GameConfig.GACHA_COST_SINGLE then
                    playerInfo.jade = playerInfo.jade + GameConfig.GACHA_COST_SINGLE
                end
                ExecuteGachaPull(1, 6)  -- 新手引导必中SR玄机子(cardIdx=6)
                return true
            end
        end
        return true  -- 拦截其他点击
    end

    if ts.step == 8 then
        -- 放置武灵阶段: 允许拖拽操作, 但阻止点击开战按钮(必须先放完所有武灵)
        if shopFightBtnRect then
            local r = shopFightBtnRect
            if dx >= r.x and dx <= r.x + r.w and dy >= r.y and dy <= r.y + r.h then
                AddFloatText(DESIGN_W / 2, DESIGN_H * 0.35, "请先将武灵全部拖到石台上!", 1.5, {255, 100, 100}, 14)
                return true  -- 阻止开战
            end
        end
        -- 同时阻止换战场按钮(step 9 才允许)
        if battleChangeBgBtnRect then
            local r = battleChangeBgBtnRect
            if dx >= r.x and dx <= r.x + r.w and dy >= r.y and dy <= r.y + r.h then
                return true  -- 阻止换战场
            end
        end
        return false  -- 其他操作(拖拽等)放行
    end

    if ts.step == 9 then
        -- 只允许点击"换战场"按钮
        if battleChangeBgBtnRect then
            local r = battleChangeBgBtnRect
            if dx >= r.x and dx <= r.x + r.w and dy >= r.y and dy <= r.y + r.h then
                -- 执行换战场逻辑
                local newIdx = (currentLayoutIdx % 8) + 1
                ApplyBattleLayout(newIdx)
                local layoutName = BATTLE_LAYOUTS[newIdx] and BATTLE_LAYOUTS[newIdx].name or "默认"
                AddFloatText(DESIGN_W / 2, DESIGN_H * 0.4, layoutName, 1.0, { 180, 220, 255 }, 14)
                PlaySFX(AUDIO.sfx_click)
                -- 进入下一步: 引导开战
                ts.step = 10
                ts.stepTimer = 0
                AddFloatText(DESIGN_W / 2, DESIGN_H * 0.35, "点击「开战」开始战斗!", 2.5, {255, 220, 80}, 14)
                print("=== 教程: 已换战场, 引导开战 ===")
                return true
            end
        end
        return true  -- 拦截其他点击
    end

    if ts.step == 10 then
        -- 只允许点击"开战"按钮
        if shopFightBtnRect then
            local r = shopFightBtnRect
            if dx >= r.x and dx <= r.x + r.w and dy >= r.y and dy <= r.y + r.h then
                return false  -- 让正常逻辑处理开战
            end
        end
        return true  -- 拦截其他点击
    end

    if ts.step == 11 then
        -- 只允许点击"刷新"按钮
        if shopRefreshBtnRect then
            local r = shopRefreshBtnRect
            if dx >= r.x and dx <= r.x + r.w and dy >= r.y and dy <= r.y + r.h then
                -- 确保有足够金币
                if gameState.gold < GameConfig.REFRESH_COST then
                    gameState.gold = gameState.gold + GameConfig.REFRESH_COST
                end
                ts.shopRefreshed = true
                ts.step = 12
                ts.stepTimer = 0
                AddFloatText(DESIGN_W / 2, DESIGN_H * 0.35, "拖拽武灵到底座部署小兵!", 2.5, {255, 220, 80}, 14)
                print("=== 教程: 已刷新, 引导拖拽部署 ===")
                return false  -- 让正常逻辑也执行刷新
            end
        end
        return true  -- 拦截其他点击
    end

    if ts.step == 14 then
        return true  -- 过渡中拦截所有点击
    end

    if ts.step == 15 then
        -- 奖励弹窗: 只允许点击"领取"按钮
        if ts.rewardBtnRect then
            local r = ts.rewardBtnRect
            if dx >= r.x and dx <= r.x + r.w and dy >= r.y and dy <= r.y + r.h then
                -- 领取奖励, 完成教程
                gameSettings.tutorialCompleted = true
                -- 奖励终身只领一次：检查是否已领取过
                if not gameSettings.tutorialRewardClaimed then
                    gameSettings.tutorialRewardClaimed = true
                    -- 教程完成奖励: 永久解锁武技7, 回收临时体验的武技19
                    if SKILL_DEFS[19] then SKILL_DEFS[19].unlocked = false end
                    -- 武技7作为教程奖励永久解锁(已在StartTutorialBattle中解锁, 保持)
                    playerEquippedSkills = { 7 }  -- 只保留武技7
                    AddFloatText(DESIGN_W / 2, DESIGN_H * 0.3,
                        "习得武技: " .. (SKILL_DEFS[7] and SKILL_DEFS[7].name or "武技"), 2.0, { 255, 180, 60 }, 20)
                    print("=== 教程完成! 已领取初始兵甲奖励, 赠送武技7 ===")
                else
                    print("=== 教程完成! 奖励已领取过，不再重复发放 ===")
                end
                SaveSettings()
                SaveGameProgress()
                tutorialState.active = false
                tutorialState.step = 0
                gameState.phase = "MENU"
                phaseChangeCooldown = 0.3
                AddFloatText(DESIGN_W / 2, DESIGN_H * 0.4, "欢迎来到讨伐!", 2.5, {255, 230, 100}, 20)
            end
        end
        return true  -- 拦截所有点击
    end

    -- step 5, 12-13: 不拦截, 让正常逻辑处理
    return false
end

-- ============================================================================
-- 编队界面 (预编队 10 人)
-- ============================================================================
formationUI = formationUI or {}
formationBackBtnRect = nil

function DrawFormationScreen()
    if gameState.phase ~= "FORMATION" then return end

    local W = DESIGN_W
    local H = DESIGN_H
    local t = menuAnimTimer or 0

    DrawMenuBg(W, H)
    nvgFontFaceId(vg, GetMainFont())

    -- ===========================
    -- 1. 顶部栏: 返回 + 标题
    -- ===========================
    local topBarY = 12
    local backW, backH = 110, 48
    local backX = 10

    -- ===========================
    -- 2. 编队槽区域 (上半部分, 最多10个槽)
    -- ===========================
    local FORMATION_MAX = 10
    local slotCols = 5
    local slotRows = 2
    local slotW = 62
    local slotH = 80
    local slotGap = 8
    local slotAreaW = slotCols * slotW + (slotCols - 1) * slotGap
    local slotStartX = (W - slotAreaW) / 2
    local slotStartY = topBarY + backH + 16

    -- 统计信息
    local formation = gameSettings.formation or {}
    local formCount = #formation
    local ownedCount = formationUI.ownedCount or GetOwnedHeroCount()
    local targetCount = math.min(FORMATION_MAX, ownedCount)
    local canManualEdit = ownedCount >= 10

    -- 标题栏
    nvgFontSize(vg, 15)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    local titleStr = "编队 (" .. formCount .. "/" .. targetCount .. ")"
    DrawWhiteInkText(W / 2, slotStartY - 8, titleStr)

    -- 编队说明 (根据状态不同显示)
    nvgFontSize(vg, 11)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    if canManualEdit then
        nvgFillColor(vg, nvgRGBA(180, 170, 140, 180))
        nvgText(vg, W / 2, slotStartY + 4, "点击卡牌可调整编队阵容")
    else
        nvgFillColor(vg, nvgRGBA(255, 200, 100, math.floor(150 + 60 * math.sin(t * 2.5))))
        nvgText(vg, W / 2, slotStartY + 4, "武灵不足10人, 已全部自动上阵")
    end

    slotStartY = slotStartY + 14

    formationUI.slotRects = {}
    for i = 1, FORMATION_MAX do
        local col = ((i - 1) % slotCols)
        local row = math.floor((i - 1) / slotCols)
        local sx = slotStartX + col * (slotW + slotGap)
        local sy = slotStartY + row * (slotH + slotGap + 4)

        formationUI.slotRects[i] = { x = sx, y = sy, w = slotW, h = slotH }

        local cardIdx = formation[i]
        if cardIdx and HERO_CARDS[cardIdx] and playerHeroes[cardIdx] and playerHeroes[cardIdx].owned then
            -- 已放置武灵
            local card = HERO_CARDS[cardIdx]
            local hero = playerHeroes[cardIdx]
            DrawInventoryCard(sx, sy, slotW, slotH, card, hero.constellation or 0, false, false)
            -- 移除标记 (右上角x) — 仅满10人可手动编辑时显示
            if canManualEdit then
                nvgBeginPath(vg)
                nvgCircle(vg, sx + slotW - 6, sy + 6, 8)
                nvgFillColor(vg, nvgRGBA(180, 50, 50, 200)); nvgFill(vg)
                nvgFontSize(vg, 14)
                nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
                nvgFillColor(vg, nvgRGBA(255, 255, 255, 240))
                nvgText(vg, sx + slotW - 6, sy + 6, "×")
            end
        else
            -- 空槽位
            local isEmpty = i > targetCount
            nvgBeginPath(vg); nvgRoundedRect(vg, sx, sy, slotW, slotH, 4)
            if isEmpty then
                nvgFillColor(vg, nvgRGBA(20, 18, 15, 150))
            else
                nvgFillColor(vg, nvgRGBA(35, 32, 25, 200))
            end
            nvgFill(vg)
            nvgBeginPath(vg); nvgRoundedRect(vg, sx, sy, slotW, slotH, 4)
            if isEmpty then
                nvgStrokeColor(vg, nvgRGBA(60, 55, 40, 60))
            else
                local pulse = 0.5 + 0.5 * math.sin(t * 2.5 + i)
                nvgStrokeColor(vg, nvgRGBA(180, 150, 80, math.floor(80 + 60 * pulse)))
            end
            nvgStrokeWidth(vg, 1); nvgStroke(vg)
            if not isEmpty then
                nvgFontSize(vg, 28)
                nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
                nvgFillColor(vg, nvgRGBA(120, 110, 80, 100))
                nvgText(vg, sx + slotW / 2, sy + slotH / 2, "+")
            end
        end
    end

    -- ===========================
    -- 3. 功能按钮区 (一键编队 / 清空)
    -- ===========================
    local btnAreaY = slotStartY + slotRows * (slotH + slotGap + 4) + 8
    local btnW = 90
    local btnH = 32
    local btnGap = 16
    local totalBtnW = btnW * 2 + btnGap
    local btnStartX = (W - totalBtnW) / 2

    -- 一键编队按钮
    local autoBtnX = btnStartX
    nvgBeginPath(vg); nvgRoundedRect(vg, autoBtnX, btnAreaY, btnW, btnH, 6)
    local autoGrad = nvgLinearGradient(vg, autoBtnX, btnAreaY, autoBtnX, btnAreaY + btnH,
        nvgRGBA(80, 140, 60, 220), nvgRGBA(50, 100, 40, 240))
    nvgFillPaint(vg, autoGrad); nvgFill(vg)
    nvgBeginPath(vg); nvgRoundedRect(vg, autoBtnX, btnAreaY, btnW, btnH, 6)
    nvgStrokeColor(vg, nvgRGBA(120, 200, 80, 120)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
    nvgFontSize(vg, 16)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(autoBtnX + btnW / 2, btnAreaY + btnH / 2, "一键编队")
    formationUI.autoBtnRect = { x = autoBtnX, y = btnAreaY, w = btnW, h = btnH }

    -- 清空按钮 (不满10人时显示灰色锁定)
    local clearBtnX = btnStartX + btnW + btnGap
    nvgBeginPath(vg); nvgRoundedRect(vg, clearBtnX, btnAreaY, btnW, btnH, 6)
    if canManualEdit then
        local clearGrad = nvgLinearGradient(vg, clearBtnX, btnAreaY, clearBtnX, btnAreaY + btnH,
            nvgRGBA(140, 60, 50, 220), nvgRGBA(100, 40, 35, 240))
        nvgFillPaint(vg, clearGrad); nvgFill(vg)
        nvgBeginPath(vg); nvgRoundedRect(vg, clearBtnX, btnAreaY, btnW, btnH, 6)
        nvgStrokeColor(vg, nvgRGBA(200, 80, 60, 120)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
    else
        nvgFillColor(vg, nvgRGBA(60, 55, 50, 180)); nvgFill(vg)
        nvgBeginPath(vg); nvgRoundedRect(vg, clearBtnX, btnAreaY, btnW, btnH, 6)
        nvgStrokeColor(vg, nvgRGBA(80, 70, 60, 80)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
    end
    nvgFontSize(vg, 16)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    if canManualEdit then
        DrawWhiteInkText(clearBtnX + btnW / 2, btnAreaY + btnH / 2, "清空")
    else
        nvgFillColor(vg, nvgRGBA(120, 110, 100, 120))
        nvgText(vg, clearBtnX + btnW / 2, btnAreaY + btnH / 2, "清空")
    end
    formationUI.clearBtnRect = { x = clearBtnX, y = btnAreaY, w = btnW, h = btnH }

    -- ===========================
    -- 4. 品质筛选标签页
    -- ===========================
    local tabY = btnAreaY + btnH + 12
    local tabH = 26
    local TAB_DEFS = {
        { label = "全部", quality = 0 },
        { label = "N",    quality = 1 },
        { label = "R",    quality = 2 },
        { label = "SR",   quality = 3 },
        { label = "SSR",  quality = 4 },
        { label = "限定", quality = 5 },
    }
    local tabW = math.floor((W - 20) / #TAB_DEFS) - 4
    local tabStartX = 12
    formationUI.tabRects = {}
    for ti, td in ipairs(TAB_DEFS) do
        local tx = tabStartX + (ti - 1) * (tabW + 4)
        local isActive = (formationUI.tab or 0) == td.quality
        nvgBeginPath(vg); nvgRoundedRect(vg, tx, tabY, tabW, tabH, 4)
        if isActive then
            local qc = td.quality > 0 and QUALITY_COLORS[td.quality] or { 200, 180, 140 }
            nvgFillColor(vg, nvgRGBA(qc[1], qc[2], qc[3], 180)); nvgFill(vg)
        else
            nvgFillColor(vg, nvgRGBA(40, 36, 28, 200)); nvgFill(vg)
            nvgBeginPath(vg); nvgRoundedRect(vg, tx, tabY, tabW, tabH, 4)
            nvgStrokeColor(vg, nvgRGBA(80, 70, 50, 100)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
        end
        nvgFontSize(vg, 14)
        nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        if isActive then
            nvgFillColor(vg, nvgRGBA(30, 25, 15, 255))
        else
            nvgFillColor(vg, nvgRGBA(180, 170, 140, 200))
        end
        nvgText(vg, tx + tabW / 2, tabY + tabH / 2, td.label)
        formationUI.tabRects[ti] = { x = tx, y = tabY, w = tabW, h = tabH, quality = td.quality }
    end

    -- ===========================
    -- 5. 已拥有武灵列表 (可滚动)
    -- ===========================
    local listStartY = tabY + tabH + 8
    local listEndY = H - 10
    local listViewH = listEndY - listStartY

    -- 筛选已拥有 + 品质过滤
    local filteredOwned = {}
    local inFormationSet = {}
    for _, idx in ipairs(formation) do inFormationSet[idx] = true end

    for idx = 1, #HERO_CARDS do
        local hero = playerHeroes[idx]
        if hero and hero.owned then
            local card = HERO_CARDS[idx]
            local matchQuality = (formationUI.tab or 0) == 0 or card.quality == formationUI.tab
            if matchQuality then
                table.insert(filteredOwned, { cardIdx = idx, card = card, hero = hero, inFormation = inFormationSet[idx] or false })
            end
        end
    end

    -- 排序: 已编队的排后面, 同组按品质降序
    table.sort(filteredOwned, function(a, b)
        if a.inFormation ~= b.inFormation then return not a.inFormation end
        if a.card.quality ~= b.card.quality then return a.card.quality > b.card.quality end
        return a.cardIdx < b.cardIdx
    end)

    local cardW = 62
    local cardH = 80
    local cardGap = 8
    local cols = math.floor((W - 20) / (cardW + cardGap))
    local cardStartX = math.floor((W - (cols * (cardW + cardGap) - cardGap)) / 2)
    local rows = math.ceil(#filteredOwned / cols)
    local contentH = rows * (cardH + cardGap + 4)

    -- 滚动范围限制
    local maxScroll = math.max(0, contentH - listViewH)
    formationUI.scrollY = math.max(0, math.min(formationUI.scrollY or 0, maxScroll))
    local scrollY = formationUI.scrollY

    -- 滚动裁剪
    nvgSave(vg)
    nvgScissor(vg, 0, listStartY, W, listViewH)

    formationUI.cardRects = {}
    for fi = 1, #filteredOwned do
        local entry = filteredOwned[fi]
        local col = ((fi - 1) % cols)
        local row = math.floor((fi - 1) / cols)
        local cx = cardStartX + col * (cardW + cardGap)
        local cy = listStartY + row * (cardH + cardGap + 4) - scrollY

        formationUI.cardRects[fi] = { x = cx, y = cy, w = cardW, h = cardH, cardIdx = entry.cardIdx }

        -- 跳过不可见
        if cy + cardH >= listStartY - 10 and cy <= listEndY + 10 then
            if entry.inFormation then
                -- 已编队: 暗化显示
                DrawInventoryCard(cx, cy, cardW, cardH, entry.card, entry.hero.constellation or 0, false, false)
                nvgBeginPath(vg); nvgRoundedRect(vg, cx, cy, cardW, cardH, 4)
                nvgFillColor(vg, nvgRGBA(10, 10, 15, 150)); nvgFill(vg)
                -- "已编入" 标记
                nvgFontSize(vg, 13)
                nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
                nvgFillColor(vg, nvgRGBA(120, 200, 100, 220))
                nvgText(vg, cx + cardW / 2, cy + cardH / 2, "已编入")
            else
                -- 未编队
                DrawInventoryCard(cx, cy, cardW, cardH, entry.card, entry.hero.constellation or 0, false, false)
                -- 不满10人锁定时，未编队卡牌也显示暗化锁定
                if not canManualEdit then
                    nvgBeginPath(vg); nvgRoundedRect(vg, cx, cy, cardW, cardH, 4)
                    nvgFillColor(vg, nvgRGBA(10, 10, 15, 100)); nvgFill(vg)
                    nvgFontSize(vg, 20)
                    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
                    nvgFillColor(vg, nvgRGBA(160, 140, 100, 120))
                    nvgText(vg, cx + cardW / 2, cy + cardH / 2, "🔒")
                end
            end
        end
    end

    nvgRestore(vg)

    -- 滚动条
    if contentH > listViewH then
        local barH = math.max(20, listViewH * listViewH / contentH)
        local barY = listStartY + (scrollY / maxScroll) * (listViewH - barH)
        nvgBeginPath(vg); nvgRoundedRect(vg, W - 5, barY, 3, barH, 1.5)
        nvgFillColor(vg, nvgRGBA(180, 160, 120, 70)); nvgFill(vg)
    end

    -- ===========================
    -- 6. 顶部栏 (覆盖在上层)
    -- ===========================
    nvgBeginPath(vg); nvgRect(vg, 0, 0, W, topBarY + backH + 4)
    nvgFillColor(vg, nvgRGBA(15, 20, 38, 230)); nvgFill(vg)

    -- 返回按钮
    nvgBeginPath(vg); nvgRoundedRect(vg, backX, topBarY, backW, backH, 8)
    nvgFillColor(vg, nvgRGBA(32, 38, 58, 200)); nvgFill(vg)
    nvgBeginPath(vg); nvgRoundedRect(vg, backX, topBarY, backW, backH, 8)
    nvgStrokeColor(vg, nvgRGBA(100, 85, 55, 100)); nvgStrokeWidth(vg, 1); nvgStroke(vg)
    nvgFontSize(vg, 20)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(backX + backW / 2, topBarY + backH / 2, "◁ 返回")
    formationBackBtnRect = { x = backX, y = topBarY, w = backW, h = backH }

    -- 标题
    nvgFontSize(vg, 22)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    DrawWhiteInkText(W / 2, topBarY + backH / 2, "出征编队")

    -- 右上角状态提示
    nvgFontSize(vg, 12)
    nvgTextAlign(vg, NVG_ALIGN_RIGHT + NVG_ALIGN_MIDDLE)
    if not canManualEdit then
        -- 不满10人: 锁定提示
        nvgFillColor(vg, nvgRGBA(255, 200, 100, math.floor(150 + 80 * math.sin(t * 3))))
        nvgText(vg, W - 14, topBarY + backH / 2, "自动编队中")
    elseif formCount < targetCount then
        -- 满10人但编队未满
        nvgFillColor(vg, nvgRGBA(255, 180, 80, math.floor(150 + 80 * math.sin(t * 3))))
        nvgText(vg, W - 14, topBarY + backH / 2, "需补齐" .. targetCount .. "人")
    else
        -- 编队已满
        nvgFillColor(vg, nvgRGBA(120, 220, 100, 180))
        nvgText(vg, W - 14, topBarY + backH / 2, "编队完成")
    end
end

--- 编队一键自动填充: 按品质优先选前 targetCount 个武灵
--- 获取已拥有武灵总数
--- @return number
function GetOwnedHeroCount()
    local count = 0
    for _, info in pairs(playerHeroes) do
        if info.owned then count = count + 1 end
    end
    return count
end

--- 一键编队: 按品质优先选前 FORMATION_MAX 个武灵
--- @return number ownedCount 已拥有总数
function AutoFillFormation()
    local FORMATION_MAX = 10
    local ownedCount = 0
    local owned = {}
    for idx = 1, #HERO_CARDS do
        local hero = playerHeroes[idx]
        if hero and hero.owned then
            ownedCount = ownedCount + 1
            table.insert(owned, { cardIdx = idx, quality = HERO_CARDS[idx].quality })
        end
    end
    local targetCount = math.min(FORMATION_MAX, ownedCount)
    -- 按品质降序排列
    table.sort(owned, function(a, b)
        if a.quality ~= b.quality then return a.quality > b.quality end
        return a.cardIdx < b.cardIdx
    end)
    gameSettings.formation = {}
    for i = 1, targetCount do
        table.insert(gameSettings.formation, owned[i].cardIdx)
    end
    SaveSettings()
    return ownedCount
end

-- ============================================================================
function GetScreenJoystickPatchString()
    return "<patch><add sel=\"/element/element[./attribute[@name='Name' and @value='Hat0']]\">" ..
        "<attribute name=\"Is Visible\" value=\"false\" /></add></patch>"
end
